const MEDIA_ASSET_HASH_CHUNK_BYTES: usize = 1024 * 1024;
/// Disabled-by-default native QA seam. An explicit duration pauses each source
/// after its first hash chunk while continuing to poll that operation's exact
/// cancellation flag. Native acceptance uses a one-file operation and can
/// therefore exercise Cancel or project replacement during a real hash without
/// filesystem markers or timing luck. Multiple/batch operations all pause
/// independently; the seam never injects a synthetic per-entry failure.
const MEDIA_ASSET_QA_HASH_PAUSE_MS_ENV: &str = "SYNDOCAL_QA_MEDIA_HASH_PAUSE_MS";
const MEDIA_ASSET_QA_HASH_PAUSE_MAX_MS: u64 = 30_000;
const MAX_LOCAL_MEDIA_ASSET_IMPORT_FILES: usize = 64;
const MEDIA_ASSET_PREPARED_IMPORT_TTL: Duration = Duration::from_secs(10 * 60);
/// A reserved-but-not-yet-prepared operation only holds a registry slot (no
/// file handle). It is reaped if the staged prepare never arrives so a client
/// that starts an operation and then dies cannot leak the request slot.
const MEDIA_ASSET_RESERVED_OPERATION_TTL: Duration = Duration::from_secs(2 * 60);
/// A terminal commit receipt is retained past the engine ACK so an exact retry
/// after a lost reply returns the same definitive result without republishing.
const MEDIA_ASSET_COMMIT_RECEIPT_TTL: Duration = Duration::from_secs(10 * 60);
/// The single background reaper wakes on this cadence to release expired
/// prepared handles and finished receipts at TTL without waiting for the next
/// registry call. One task total, owned by `AppState`; never one per item.
const MEDIA_ASSET_OPERATION_REAP_INTERVAL: Duration = Duration::from_millis(500);
/// Hover previews keep one verified private copy briefly, so a 4fps UI does
/// not rehash and recopy the original media on every pointer update.
const MEDIA_ASSET_PREVIEW_SESSION_TTL: Duration = Duration::from_secs(30);
/// Bounded number of collision-avoidance attempts when minting a private media
/// snapshot filename. `create_new` guarantees we never clobber an existing file;
/// this only bounds the retry loop if the OS temp dir already holds a name.
const MEDIA_ASSET_SNAPSHOT_NAME_ATTEMPTS: usize = 16;
static MEDIA_ASSET_SNAPSHOT_COUNTER: AtomicU64 = AtomicU64::new(0);
static RDM_TRANSACTION_NUMBER: AtomicU8 = AtomicU8::new(1);
static LIVE_VIDEO_MONITOR_SEQUENCE: AtomicU64 = AtomicU64::new(1);
static PROJECT_SAVE_TEMP_SEQUENCE: AtomicU64 = AtomicU64::new(1);
static PROJECT_BACKUP_ID_SEQUENCE: AtomicU64 = AtomicU64::new(0);
static NATIVE_VIDEO_OUTPUT_QUARANTINE_SEQUENCE: AtomicU64 = AtomicU64::new(1);
static LIVE_VIDEO_OUTPUT_WINDOW_INCARNATION: AtomicU64 = AtomicU64::new(0);
static LIVE_VIDEO_OUTPUT_WINDOW_TRUTH: LazyLock<
    Mutex<HashMap<VideoOutputId, LiveVideoWindowTruth>>,
> = LazyLock::new(|| Mutex::new(HashMap::new()));
/// `mediaAssetAuthority.ts` creates request IDs in the exact JavaScript-safe
/// range `1..=2^53-1` (`21-bit prefix * 2^32 + 32-bit sequence`). Compatibility
/// IPC has no request field at all, so it owns this disjoint server-only
/// namespace instead of guessing whether two equal `{ label, path }` calls are
/// a reply retry or two intended adds.
const LEGACY_MEDIA_ASSET_COMPATIBILITY_REQUEST_ID_MIN: u64 = 1_u64 << 63;
const RENDERER_MEDIA_ASSET_REQUEST_ID_MAX: u64 = (1_u64 << 53) - 1;
/// Legacy IPC predates renderer-owned media operation identities. Keep its
/// server-generated requests outside the renderer's exact-JavaScript range so
/// an old `{ label, path }` retry can never accidentally adopt a staged UI
/// request. This is deliberately *not* a semantic-fingerprint dedupe: the old
/// wire contract cannot distinguish a lost reply from a second intentional
/// add, so it remains one backend operation per invocation.
static LEGACY_MEDIA_ASSET_COMPATIBILITY_REQUEST_ID: AtomicU64 =
    AtomicU64::new(LEGACY_MEDIA_ASSET_COMPATIBILITY_REQUEST_ID_MIN);

fn allocate_legacy_media_asset_compatibility_request_id_from(
    sequence: &AtomicU64,
) -> Result<u64, String> {
    if RENDERER_MEDIA_ASSET_REQUEST_ID_MAX >= LEGACY_MEDIA_ASSET_COMPATIBILITY_REQUEST_ID_MIN {
        return Err(
            "Legacy media compatibility request namespace overlaps renderer request IDs"
                .to_string(),
        );
    }
    let mut current = sequence.load(Ordering::Acquire);
    loop {
        if current < LEGACY_MEDIA_ASSET_COMPATIBILITY_REQUEST_ID_MIN {
            return Err("Legacy media compatibility request namespace is invalid".to_string());
        }
        // Never hand out `u64::MAX`: reserving a next value first makes the
        // exhaustion boundary fail closed rather than wrapping into any other
        // registry namespace.
        let next = current.checked_add(1).ok_or_else(|| {
            "Legacy media compatibility request ID space is exhausted; restart Syndocal".to_string()
        })?;
        match sequence.compare_exchange_weak(current, next, Ordering::AcqRel, Ordering::Acquire) {
            Ok(_) => return Ok(current),
            Err(actual) => current = actual,
        }
    }
}

fn validate_app_name(file_label: &str, app: &str) -> Result<(), String> {
    if app.trim() == APP_NAME {
        Ok(())
    } else {
        Err(format!("Unsupported {file_label} app '{app}'"))
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ProjectOperatorSession {
    project_epoch: u64,
    policy: OperatorPolicy,
    unlocked: bool,
}

const MAX_DURABLE_OUTPUT_LEASE_RECEIPTS: usize = output_lease::MAX_OUTPUT_LEASE_REQUESTS;
// Keep one extra durable-origin slot for the request currently in Pending.
// Once its terminal receipt is recorded, receipt eviction and origin GC bring
// the retained set back under the 128-record bound.  Without this slot, a
// fresh principal arriving after exactly 128 retained receipts is rejected
// before the oldest receipt can be evicted.
const MAX_DURABLE_OUTPUT_LEASE_ORIGINS: usize = output_lease::MAX_OUTPUT_LEASE_REQUEST_ORIGINS + 1;
/// The DSF2026 probe has one successful send and, at most, one successful
/// explicit reconciliation. Keep both public terminal receipts forever so a
/// reply-loss retry remains a no-confirmation/no-transport replay after a
/// process restart.
const MAX_DURABLE_DSF2026_OUTPUT_CONTROL_TERMINALS: usize = 2;
/// Only the two short post-confirmation managed-exact-Both routes retain an
/// outer public terminal.  This bound is intentionally independent from the
/// generic process-local output-control cache: it is a restart-safe reply
/// record, not a new durable control-plane mechanism.
const MAX_DURABLE_MANAGED_EXACT_BOTH_OUTPUT_CONTROL_TERMINALS: usize =
    MAX_DURABLE_OUTPUT_LEASE_RECEIPTS;

fn default_output_lease_replay_guard() -> bool {
    // Older journals did not distinguish a receiptless SafeAbort from an
    // evicted terminal receipt.  Preserve the replay barrier conservatively
    // when migrating such an origin.
    true
}

/// The output-lease registry intentionally starts empty after every backend
/// restart.  This journal retains only bounded terminal evidence so an exact
/// reply-loss retry can be answered without reconstructing authority or
/// replaying a physical operation.  The durable record is evidence of the
/// previous process, not a lease grant in the new process.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct PersistedOutputLeaseReceiptOrigin {
    principal: String,
    domain: String,
    high_water_request_id: u64,
    /// A SafeAbort has no retained receipt, but its high-water request ID is
    /// still the replay guard for that exact physical attempt.  It becomes
    /// pruneable once the operation reaches a terminal receipt and that
    /// receipt is later evicted.
    #[serde(default = "default_output_lease_replay_guard")]
    replay_guard: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct PersistedOutputLeasePendingReceipt {
    key: output_lease::OutputLeaseRequestKey,
    shape_hash: output_lease::OutputLeaseShapeHash,
    /// Present only for the fixed DSF2026 physical-send domain.  Generic
    /// output-control Pending records deliberately remain principal-scoped.
    #[serde(default)]
    window_label: Option<String>,
}

/// Public R4 terminal response retained alongside the private lease receipt.
/// The public response contains the exact fence, shape, argument fingerprint,
/// and audit identity the renderer must receive on an idempotent retry.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct PersistedDsf2026OutputControlTerminal {
    principal: String,
    window_label: String,
    response: OutputControlResponseV2,
}

/// Public terminal retained for the two route-specific managed-exact-Both
/// operations.  The private manager authorization never appears here: the
/// response remains keyed by the canonical renderer request and caller
/// binding, so a lost reply can be replayed before a now-stale fence is
/// checked after restart.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct PersistedManagedExactBothOutputControlTerminal {
    principal: String,
    window_label: String,
    response: OutputControlResponseV2,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct PersistedOutputLeaseReceiptState {
    version: u32,
    receipts: Vec<output_lease::OutputLeaseRequestReceipt>,
    origins: Vec<PersistedOutputLeaseReceiptOrigin>,
    #[serde(default)]
    pending: Vec<PersistedOutputLeasePendingReceipt>,
    /// This fixed machine-local Art-Net proof has one physical budget for the
    /// lifetime of the durable journal.  It is intentionally global rather
    /// than principal-scoped: another renderer, request ID, restart, or
    /// reconciliation acknowledgement must never make a second datagram
    /// eligible.
    #[serde(default)]
    dsf2026_artnet_acceptance_probe_consumed: bool,
    /// Unlike the general in-memory response cache, these two fixed action
    /// receipts survive restart. They are intentionally not used by generic
    /// output-control operations.
    #[serde(default)]
    dsf2026_artnet_acceptance_probe_terminals: Vec<PersistedDsf2026OutputControlTerminal>,
    /// Restart-safe public responses are deliberately retained only for
    /// ReleaseBlackout, EnableShowSpoutOutputs, and SetDisplayWindowOpen.
    /// AddDisplay remains outside this bridge because its native work is a
    /// long two-phase transaction.
    #[serde(default)]
    managed_exact_both_output_control_terminals:
        Vec<PersistedManagedExactBothOutputControlTerminal>,
}

impl Default for PersistedOutputLeaseReceiptState {
    fn default() -> Self {
        Self {
            version: OUTPUT_LEASE_DURABLE_RECEIPT_STATE_VERSION,
            receipts: Vec::new(),
            origins: Vec::new(),
            pending: Vec::new(),
            dsf2026_artnet_acceptance_probe_consumed: false,
            dsf2026_artnet_acceptance_probe_terminals: Vec::new(),
            managed_exact_both_output_control_terminals: Vec::new(),
        }
    }
}

#[derive(Debug)]
struct OutputLeaseDurableReceiptJournal {
    path: Option<PathBuf>,
    state: PersistedOutputLeaseReceiptState,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OutputLeaseDurablePrepareResult {
    Fresh,
    Terminal,
}

/// Durable visibility for the fixed DSF2026 machine-local probe.  This is
/// intentionally separate from output-route state: no normal Art-Net or
/// Spout command reads or writes the one-shot physical budget.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
enum Dsf2026ArtNetAcceptanceProbeStatus {
    Available,
    InDoubt,
    Consumed,
}

/// Classifies a physical/project callback failure at the durable output
/// boundary.  A SafeAbort proves that no external resource remains and that
/// the engine/project candidate was rolled back, so its Pending marker may be
/// removed.  InDoubt means that any cleanup acknowledgement was lost or
/// failed; the Pending marker must remain and the exact operation must be
/// refused on retry rather than risk a second physical output.
#[derive(Debug, Clone, PartialEq, Eq)]
enum OutputLeaseCandidateCommitFailure {
    SafeAbort(String),
    InDoubt(String),
}

impl OutputLeaseCandidateCommitFailure {
    fn safe(message: impl Into<String>) -> Self {
        Self::SafeAbort(message.into())
    }

    fn in_doubt(message: impl Into<String>) -> Self {
        Self::InDoubt(message.into())
    }

    fn with_cleanup(self, context: &str, cleanup: Result<(), String>) -> Self {
        match cleanup {
            Ok(()) => self,
            Err(cleanup_error) => Self::InDoubt(format!("{self:?}; {context}: {cleanup_error}")),
        }
    }

    fn into_message(self) -> String {
        match self {
            Self::SafeAbort(message) => message,
            Self::InDoubt(message) => format!("{message}; durable output commit is in doubt"),
        }
    }
}

impl From<String> for OutputLeaseCandidateCommitFailure {
    fn from(message: String) -> Self {
        Self::safe(message)
    }
}

impl From<&str> for OutputLeaseCandidateCommitFailure {
    fn from(message: &str) -> Self {
        Self::safe(message)
    }
}

impl OutputLeaseDurableReceiptJournal {
    fn in_memory() -> Self {
        Self {
            path: None,
            state: PersistedOutputLeaseReceiptState::default(),
        }
    }

    fn install_path(&mut self, path: PathBuf) -> Result<(), String> {
        let mut state = load_output_lease_receipt_state_from_path(&path)?;
        // The consumed marker is additive.  If a journal created by the
        // immediately preceding implementation contains a retained terminal
        // probe receipt, fail closed on upgrade as well instead of permitting
        // a new fixed packet merely because the marker had not existed yet.
        state.dsf2026_artnet_acceptance_probe_consumed |= state
            .receipts
            .iter()
            .any(|receipt| receipt.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN);
        self.path = Some(path);
        self.state = state;
        Ok(())
    }

    fn next_request_id(&self) -> Result<u64, String> {
        self.state
            .origins
            .iter()
            .filter(|origin| self.origin_is_retained(origin))
            .map(|origin| origin.high_water_request_id)
            .max()
            .unwrap_or(0)
            .checked_add(1)
            .filter(|value| *value != 0)
            .ok_or_else(|| {
                "Output-lease durable request identity space is exhausted; restart Syndocal"
                    .to_string()
            })
    }

    fn lookup(
        &self,
        request: &OutputLeaseRequest,
    ) -> Result<Option<output_lease::OutputLeaseRequestReceipt>, output_lease::OutputLeaseError>
    {
        if request.shape.canonical_hash()? != request.shape_hash {
            return Err(output_lease::OutputLeaseError::InvalidRequest);
        }
        if let Some(receipt) = self
            .state
            .receipts
            .iter()
            .find(|receipt| receipt.key == request.key)
        {
            if receipt.shape_hash == request.shape_hash {
                return Ok(Some(receipt.clone()));
            }
            return Err(output_lease::OutputLeaseError::Conflict);
        }
        if request.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN
            && (self.state.dsf2026_artnet_acceptance_probe_consumed
                || self
                    .state
                    .pending
                    .iter()
                    .any(|pending| pending.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN))
        {
            // An exact terminal replay was returned above. Every other
            // request is a second physical attempt and must fail before the
            // candidate registry or transport callback is reached.
            return Err(output_lease::OutputLeaseError::RequestCapacity);
        }
        if let Some(pending) = self.state.pending.iter().find(|pending| {
            pending.key.principal == request.key.principal
                && pending.key.domain == request.key.domain
        }) {
            if pending.key == request.key && pending.shape_hash == request.shape_hash {
                return Err(output_lease::OutputLeaseError::RequestCapacity);
            }
            return Err(output_lease::OutputLeaseError::RequestCapacity);
        }
        let high_water = self
            .state
            .origins
            .iter()
            .filter(|origin| self.origin_is_retained(origin))
            .find(|origin| {
                origin.principal == request.key.principal && origin.domain == request.key.domain
            })
            .map(|origin| origin.high_water_request_id);
        if high_water.is_some_and(|value| request.key.request_id <= value) {
            return Err(output_lease::OutputLeaseError::ReceiptNotRetained);
        }
        Ok(None)
    }

    /// Persist an in-doubt physical commit before entering its irreversible
    /// callback.  Startup must refuse every request in this origin until the
    /// operator can reconcile the physical target; replaying it would violate
    /// exactly-once output semantics.
    /// Prepare an ordinary output transition.  The fixed DSF2026 send must
    /// use `prepare_dsf2026_artnet_acceptance_probe`: accepting it here would
    /// lose the concrete local-window identity needed for a no-send recovery.
    fn prepare(
        &mut self,
        request: &OutputLeaseRequest,
    ) -> Result<OutputLeaseDurablePrepareResult, output_lease::OutputLeaseError> {
        if request.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN {
            return Err(output_lease::OutputLeaseError::InvalidRequest);
        }
        self.prepare_with_pending_window_label(request, None)
    }

    /// Persist the fixed local window binding before the one irreversible
    /// DSF2026 send.  This is not caller metadata: it is captured from the
    /// registered R4 WebView binding and later matched again at reconciliation.
    fn prepare_dsf2026_artnet_acceptance_probe(
        &mut self,
        request: &OutputLeaseRequest,
        window_label: &str,
    ) -> Result<OutputLeaseDurablePrepareResult, output_lease::OutputLeaseError> {
        if request.key.domain != OUTPUT_LEASE_DSF2026_PROBE_DOMAIN
            || OutputLeaseOwner::new(&request.key.principal, window_label, 1, 1).is_err()
        {
            return Err(output_lease::OutputLeaseError::InvalidRequest);
        }
        self.prepare_with_pending_window_label(request, Some(window_label))
    }

    fn prepare_with_pending_window_label(
        &mut self,
        request: &OutputLeaseRequest,
        pending_window_label: Option<&str>,
    ) -> Result<OutputLeaseDurablePrepareResult, output_lease::OutputLeaseError> {
        if request.shape.canonical_hash()? != request.shape_hash {
            return Err(output_lease::OutputLeaseError::InvalidRequest);
        }
        let mut candidate = self.state.clone();
        Self::prune_empty_origins(&mut candidate);
        if let Some(receipt) = candidate
            .receipts
            .iter()
            .find(|receipt| receipt.key == request.key)
        {
            if receipt.shape_hash != request.shape_hash {
                return Err(output_lease::OutputLeaseError::Conflict);
            }
            return Ok(OutputLeaseDurablePrepareResult::Terminal);
        }
        if request.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN
            && (candidate.dsf2026_artnet_acceptance_probe_consumed
                || candidate
                    .pending
                    .iter()
                    .any(|pending| pending.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN))
        {
            return Err(output_lease::OutputLeaseError::RequestCapacity);
        }
        if candidate.pending.iter().any(|pending| {
            pending.key.principal == request.key.principal
                && pending.key.domain == request.key.domain
        }) {
            return Err(output_lease::OutputLeaseError::RequestCapacity);
        }
        let origin_index = candidate.origins.iter().position(|origin| {
            origin.principal == request.key.principal && origin.domain == request.key.domain
        });
        match origin_index {
            Some(index) => {
                let origin = &mut candidate.origins[index];
                origin.replay_guard = true;
                if request.key.request_id <= origin.high_water_request_id {
                    return Err(output_lease::OutputLeaseError::ReceiptNotRetained);
                }
                origin.high_water_request_id = request.key.request_id;
            }
            None => {
                if candidate.origins.len() >= MAX_DURABLE_OUTPUT_LEASE_ORIGINS {
                    return Err(output_lease::OutputLeaseError::RequestCapacity);
                }
                candidate.origins.push(PersistedOutputLeaseReceiptOrigin {
                    principal: request.key.principal.clone(),
                    domain: request.key.domain.clone(),
                    high_water_request_id: request.key.request_id,
                    replay_guard: true,
                });
            }
        }
        candidate.pending.push(PersistedOutputLeasePendingReceipt {
            key: request.key.clone(),
            shape_hash: request.shape_hash.clone(),
            window_label: pending_window_label.map(str::to_string),
        });
        if let Some(path) = self.path.as_deref() {
            persist_output_lease_receipt_state_to_path(path, &candidate)
                .map_err(|_| output_lease::OutputLeaseError::RequestCapacity)?;
        }
        self.state = candidate;
        Ok(OutputLeaseDurablePrepareResult::Fresh)
    }

    fn abort(
        &mut self,
        request: &OutputLeaseRequest,
    ) -> Result<(), output_lease::OutputLeaseError> {
        let mut candidate = self.state.clone();
        candidate
            .pending
            .retain(|pending| pending.key != request.key);
        Self::prune_empty_origins(&mut candidate);
        if let Some(path) = self.path.as_deref() {
            persist_output_lease_receipt_state_to_path(path, &candidate)
                .map_err(|_| output_lease::OutputLeaseError::RequestCapacity)?;
        }
        self.state = candidate;
        Ok(())
    }

    fn record(
        &mut self,
        receipt: &output_lease::OutputLeaseRequestReceipt,
    ) -> Result<(), output_lease::OutputLeaseError> {
        let mut candidate = self.state.clone();
        Self::record_receipt_in_candidate(&mut candidate, receipt)?;
        if let Some(path) = self.path.as_deref() {
            persist_output_lease_receipt_state_to_path(path, &candidate)
                .map_err(|_| output_lease::OutputLeaseError::RequestCapacity)?;
        }
        self.state = candidate;
        Ok(())
    }

    /// Apply one private lease receipt to an unpublished journal candidate.
    /// DSF2026 uses this exact mutation as part of its larger atomic terminal
    /// record; ordinary output control persists the candidate immediately.
    fn record_receipt_in_candidate(
        candidate: &mut PersistedOutputLeaseReceiptState,
        receipt: &output_lease::OutputLeaseRequestReceipt,
    ) -> Result<(), output_lease::OutputLeaseError> {
        Self::prune_empty_origins(candidate);
        if let Some(existing) = candidate
            .receipts
            .iter()
            .find(|existing| existing.key == receipt.key)
        {
            if existing.shape_hash == receipt.shape_hash {
                return Ok(());
            }
            return Err(output_lease::OutputLeaseError::Conflict);
        }
        let had_pending = candidate
            .pending
            .iter()
            .any(|pending| pending.key == receipt.key && pending.shape_hash == receipt.shape_hash);
        candidate
            .pending
            .retain(|pending| pending.key != receipt.key);
        let origin_index = candidate.origins.iter().position(|origin| {
            origin.principal == receipt.key.principal && origin.domain == receipt.key.domain
        });
        match origin_index {
            Some(index) => {
                let origin = &mut candidate.origins[index];
                origin.replay_guard = false;
                if !had_pending && receipt.key.request_id <= origin.high_water_request_id {
                    return Err(output_lease::OutputLeaseError::ReceiptNotRetained);
                }
                origin.high_water_request_id = receipt.key.request_id;
            }
            None => {
                if candidate.origins.len() >= MAX_DURABLE_OUTPUT_LEASE_ORIGINS {
                    return Err(output_lease::OutputLeaseError::RequestCapacity);
                }
                candidate.origins.push(PersistedOutputLeaseReceiptOrigin {
                    principal: receipt.key.principal.clone(),
                    domain: receipt.key.domain.clone(),
                    high_water_request_id: receipt.key.request_id,
                    replay_guard: false,
                });
            }
        }
        candidate.receipts.push(receipt.clone());
        if receipt.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN {
            // This write is persisted atomically with the terminal receipt.
            // A crash before it leaves Pending; a crash after it forbids every
            // fresh probe request after restart.
            candidate.dsf2026_artnet_acceptance_probe_consumed = true;
        }
        if candidate.receipts.len() > MAX_DURABLE_OUTPUT_LEASE_RECEIPTS {
            let remove_count = candidate.receipts.len() - MAX_DURABLE_OUTPUT_LEASE_RECEIPTS;
            candidate.receipts.drain(..remove_count);
        }
        Self::prune_empty_origins(candidate);
        Ok(())
    }

    /// Non-mutating pre-send/no-send reconciliation fence. The terminal
    /// mutation itself happens only in `record_dsf2026_output_control_terminal`
    /// together with its lease receipt and public response.
    fn validate_dsf2026_probe_pending(
        &self,
        window_label: &str,
    ) -> Result<(), output_lease::OutputLeaseError> {
        let probe_pending = self
            .state
            .pending
            .iter()
            .filter(|pending| pending.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN)
            .collect::<Vec<_>>();
        (probe_pending.len() == 1 && probe_pending[0].window_label.as_deref() == Some(window_label))
            .then_some(())
            .ok_or(output_lease::OutputLeaseError::InvalidRequest)
    }

    fn lookup_dsf2026_output_control_terminal(
        &self,
        principal: &str,
        window_label: &str,
        request: &OutputControlCommandRequestV2,
        shape_sha256: &str,
        argument_fingerprint: &str,
    ) -> Result<Option<OutputControlResponseV2>, String> {
        if !is_dsf2026_artnet_acceptance_probe_operation(&request.operation_id) {
            return Ok(None);
        }
        for terminal in &self.state.dsf2026_artnet_acceptance_probe_terminals {
            if terminal.principal != principal
                || terminal.window_label != window_label
                || terminal.response.validate().is_err()
            {
                continue;
            }
            let OutputControlResponseV2::Receipt(receipt) = &terminal.response else {
                return Err("DSF2026 durable terminal is not a receipt".to_string());
            };
            if receipt.operation_id != request.operation_id
                || receipt.request_id != request.request_id
            {
                continue;
            }
            if receipt.shape_sha256 == shape_sha256
                && receipt.argument_fingerprint == argument_fingerprint
            {
                return Ok(Some(terminal.response.clone()));
            }
            return Err(
                "DSF2026 durable terminal request identity conflicts with its replay shape"
                    .to_string(),
            );
        }
        if request.operation_id == OUTPUT_DSF2026_ARTNET_ACCEPTANCE_PROBE_OPERATION_ID
            && (self.state.dsf2026_artnet_acceptance_probe_consumed
                || self
                    .state
                    .pending
                    .iter()
                    .any(|pending| pending.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN))
        {
            // An old journal cannot reconstruct the full public receipt. It
            // must therefore fail closed before confirmation rather than
            // allowing a legacy same-ID retry to reach native code.
            return Err("DSF2026 Art-Net probe is globally consumed or in doubt".to_string());
        }
        if request.operation_id == OUTPUT_DSF2026_ARTNET_ACCEPTANCE_PROBE_RECONCILE_OPERATION_ID {
            let probe_pending = self
                .state
                .pending
                .iter()
                .filter(|pending| pending.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN)
                .collect::<Vec<_>>();
            if probe_pending.len() != 1
                || probe_pending[0].window_label.as_deref() != Some(window_label)
            {
                return Err(
                    "DSF2026 reconciliation has no pending physical outcome for this local window"
                        .to_string(),
                );
            }
        }
        Ok(None)
    }

    /// Atomically persist the DSF2026 private lease receipt, global consumed
    /// latch, and exact public R4 response. A crash can therefore observe
    /// either the prior Pending state or the complete terminal state, never a
    /// consumed/private-success state without the replayable public receipt.
    fn record_dsf2026_output_control_terminal(
        &mut self,
        private_receipt: &output_lease::OutputLeaseRequestReceipt,
        principal: &str,
        window_label: &str,
        request: &OutputControlCommandRequestV2,
        shape_sha256: &str,
        argument_fingerprint: &str,
        response: &OutputControlResponseV2,
    ) -> Result<(), String> {
        if !is_dsf2026_artnet_acceptance_probe_operation(&request.operation_id) {
            return Ok(());
        }
        OutputLeaseOwner::new(principal, window_label, 1, 1)
            .map_err(|_| "DSF2026 durable terminal caller identity is invalid".to_string())?;
        response
            .validate()
            .map_err(|_| "DSF2026 durable terminal response is invalid".to_string())?;
        let OutputControlResponseV2::Receipt(receipt) = response else {
            return Err("DSF2026 durable terminal is not a receipt".to_string());
        };
        if receipt.operation_id != request.operation_id
            || receipt.request_id != request.request_id
            || receipt.shape_sha256 != shape_sha256
            || receipt.argument_fingerprint != argument_fingerprint
        {
            return Err("DSF2026 durable terminal does not exactly match its request".to_string());
        }
        let expected_domain = match request.operation_id.as_str() {
            OUTPUT_DSF2026_ARTNET_ACCEPTANCE_PROBE_OPERATION_ID => {
                OUTPUT_LEASE_DSF2026_PROBE_DOMAIN
            }
            OUTPUT_DSF2026_ARTNET_ACCEPTANCE_PROBE_RECONCILE_OPERATION_ID => {
                OUTPUT_LEASE_DSF2026_PROBE_RECONCILE_DOMAIN
            }
            _ => return Err("DSF2026 durable terminal operation is invalid".to_string()),
        };
        if private_receipt.key.principal != principal
            || private_receipt.key.domain != expected_domain
            || private_receipt.key.request_id != request.request_id
        {
            return Err(
                "DSF2026 private lease receipt does not exactly match its public terminal"
                    .to_string(),
            );
        }
        let mut candidate = self.state.clone();
        if request.operation_id == OUTPUT_DSF2026_ARTNET_ACCEPTANCE_PROBE_RECONCILE_OPERATION_ID {
            let probe_pending = candidate
                .pending
                .iter()
                .filter(|pending| pending.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN)
                .collect::<Vec<_>>();
            if probe_pending.len() != 1
                || probe_pending[0].window_label.as_deref() != Some(window_label)
            {
                return Err(
                    "DSF2026 reconciliation requires exactly one probe Pending record for this local window"
                        .to_string(),
                );
            }
            candidate
                .pending
                .retain(|pending| pending.key.domain != OUTPUT_LEASE_DSF2026_PROBE_DOMAIN);
            candidate.dsf2026_artnet_acceptance_probe_consumed = true;
        }
        Self::record_receipt_in_candidate(&mut candidate, private_receipt).map_err(|error| {
            format!("DSF2026 private lease terminal receipt is invalid: {error:?}")
        })?;
        if let Some(existing) = candidate
            .dsf2026_artnet_acceptance_probe_terminals
            .iter()
            .find(|existing| {
                existing.principal == principal
                    && existing.window_label == window_label
                    && matches!(
                        &existing.response,
                        OutputControlResponseV2::Receipt(existing_receipt)
                            if existing_receipt.operation_id == request.operation_id
                                && existing_receipt.request_id == request.request_id
                    )
            })
        {
            if existing.response == *response {
                return Ok(());
            }
            return Err(
                "DSF2026 durable terminal request identity conflicts with an existing receipt"
                    .to_string(),
            );
        }
        if candidate.dsf2026_artnet_acceptance_probe_terminals.len()
            >= MAX_DURABLE_DSF2026_OUTPUT_CONTROL_TERMINALS
        {
            return Err("DSF2026 durable terminal receipt capacity is exhausted".to_string());
        }
        candidate.dsf2026_artnet_acceptance_probe_terminals.push(
            PersistedDsf2026OutputControlTerminal {
                principal: principal.to_string(),
                window_label: window_label.to_string(),
                response: response.clone(),
            },
        );
        if let Some(path) = self.path.as_deref() {
            persist_output_lease_receipt_state_to_path(path, &candidate)?;
        }
        self.state = candidate;
        Ok(())
    }

    fn lookup_managed_exact_both_output_control_terminal(
        &self,
        principal: &str,
        window_label: &str,
        request: &OutputControlCommandRequestV2,
        shape_sha256: &str,
        argument_fingerprint: &str,
    ) -> Result<Option<OutputControlResponseV2>, String> {
        if !is_managed_exact_both_output_control_replay_action(&request.action) {
            return Ok(None);
        }
        for terminal in &self.state.managed_exact_both_output_control_terminals {
            if terminal.principal != principal
                || terminal.window_label != window_label
                || terminal.response.validate().is_err()
            {
                continue;
            }
            let OutputControlResponseV2::Receipt(receipt) = &terminal.response else {
                return Err("Managed exact-Both durable terminal is not a receipt".to_string());
            };
            if receipt.operation_id != request.operation_id
                || receipt.request_id != request.request_id
            {
                continue;
            }
            if receipt.shape_sha256 == shape_sha256
                && receipt.argument_fingerprint == argument_fingerprint
            {
                return Ok(Some(terminal.response.clone()));
            }
            return Err(
                "Managed exact-Both durable terminal request identity conflicts with its replay shape"
                    .to_string(),
            );
        }
        Ok(None)
    }

    fn record_managed_exact_both_output_control_terminal(
        &mut self,
        principal: &str,
        window_label: &str,
        request: &OutputControlCommandRequestV2,
        shape_sha256: &str,
        argument_fingerprint: &str,
        response: &OutputControlResponseV2,
    ) -> Result<(), String> {
        if !is_managed_exact_both_output_control_replay_action(&request.action) {
            return Ok(());
        }
        OutputLeaseOwner::new(principal, window_label, 1, 1).map_err(|_| {
            "Managed exact-Both durable terminal caller identity is invalid".to_string()
        })?;
        response
            .validate()
            .map_err(|_| "Managed exact-Both durable terminal response is invalid".to_string())?;
        let OutputControlResponseV2::Receipt(receipt) = response else {
            return Err("Managed exact-Both durable terminal is not a receipt".to_string());
        };
        if receipt.operation_id != request.operation_id
            || receipt.request_id != request.request_id
            || receipt.shape_sha256 != shape_sha256
            || receipt.argument_fingerprint != argument_fingerprint
        {
            return Err(
                "Managed exact-Both durable terminal does not exactly match its request"
                    .to_string(),
            );
        }
        let mut candidate = self.state.clone();
        if !candidate.receipts.iter().any(|lease_receipt| {
            lease_receipt.key.principal == principal
                && lease_receipt.key.domain == OUTPUT_LEASE_OUTPUT_CONTROL_DOMAIN
                && lease_receipt.key.request_id == request.request_id
        }) {
            return Err(
                "Managed exact-Both durable terminal has no canonical public lease receipt"
                    .to_string(),
            );
        }
        if let Some(existing) = candidate
            .managed_exact_both_output_control_terminals
            .iter()
            .find(|existing| {
                existing.principal == principal
                    && existing.window_label == window_label
                    && matches!(
                        &existing.response,
                        OutputControlResponseV2::Receipt(existing_receipt)
                            if existing_receipt.operation_id == request.operation_id
                                && existing_receipt.request_id == request.request_id
                    )
            })
        {
            if existing.response == *response {
                return Ok(());
            }
            return Err(
                "Managed exact-Both durable terminal request identity conflicts with an existing receipt"
                    .to_string(),
            );
        }
        if candidate.managed_exact_both_output_control_terminals.len()
            >= MAX_DURABLE_MANAGED_EXACT_BOTH_OUTPUT_CONTROL_TERMINALS
        {
            return Err(
                "Managed exact-Both durable terminal receipt capacity is exhausted".to_string(),
            );
        }
        candidate.managed_exact_both_output_control_terminals.push(
            PersistedManagedExactBothOutputControlTerminal {
                principal: principal.to_string(),
                window_label: window_label.to_string(),
                response: response.clone(),
            },
        );
        if let Some(path) = self.path.as_deref() {
            persist_output_lease_receipt_state_to_path(path, &candidate)?;
        }
        self.state = candidate;
        Ok(())
    }

    #[cfg(test)]
    fn receipt_count(&self) -> usize {
        self.state.receipts.len()
    }

    fn dsf2026_artnet_acceptance_probe_status(&self) -> Dsf2026ArtNetAcceptanceProbeStatus {
        if self.state.dsf2026_artnet_acceptance_probe_consumed {
            Dsf2026ArtNetAcceptanceProbeStatus::Consumed
        } else if self
            .state
            .pending
            .iter()
            .any(|pending| pending.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN)
        {
            Dsf2026ArtNetAcceptanceProbeStatus::InDoubt
        } else {
            Dsf2026ArtNetAcceptanceProbeStatus::Available
        }
    }

    fn origin_is_retained(&self, origin: &PersistedOutputLeaseReceiptOrigin) -> bool {
        self.state.receipts.iter().any(|receipt| {
            receipt.key.principal == origin.principal && receipt.key.domain == origin.domain
        }) || self.state.pending.iter().any(|pending| {
            pending.key.principal == origin.principal && pending.key.domain == origin.domain
        }) || origin.replay_guard
    }

    fn prune_empty_origins(state: &mut PersistedOutputLeaseReceiptState) {
        state.origins.retain(|origin| {
            state.receipts.iter().any(|receipt| {
                receipt.key.principal == origin.principal && receipt.key.domain == origin.domain
            }) || state.pending.iter().any(|pending| {
                pending.key.principal == origin.principal && pending.key.domain == origin.domain
            }) || origin.replay_guard
        });
    }
}

/// Resolve a retained DSF2026 public response before the control-plane lane
/// can reserve work, validate a fence, or open the native confirmation. This
/// is deliberately limited to the two fixed DSF2026 operations; the ordinary
/// output-control response cache remains process-local.
pub(crate) fn replay_durable_dsf2026_output_control_terminal(
    state: &AppState,
    principal: &str,
    window_label: &str,
    request: &OutputControlCommandRequestV2,
    shape_sha256: &str,
    argument_fingerprint: &str,
) -> Result<Option<OutputControlResponseV2>, String> {
    state
        .output_lease_durable_receipts
        .lock()
        .map_err(|_| "Output lease durable receipt journal lock was poisoned".to_string())?
        .lookup_dsf2026_output_control_terminal(
            principal,
            window_label,
            request,
            shape_sha256,
            argument_fingerprint,
        )
}

/// Resolve the narrowly retained public terminal before mutable output state,
/// lease generation, or native confirmation is inspected.  A record is bound
/// to the exact renderer principal and WebView label, so it cannot transfer a
/// reply to a foreign/reloaded binding.
pub(crate) fn replay_durable_managed_exact_both_output_control_terminal(
    state: &AppState,
    principal: &str,
    window_label: &str,
    request: &OutputControlCommandRequestV2,
    shape_sha256: &str,
    argument_fingerprint: &str,
) -> Result<Option<OutputControlResponseV2>, String> {
    state
        .output_lease_durable_receipts
        .lock()
        .map_err(|_| "Output lease durable receipt journal lock was poisoned".to_string())?
        .lookup_managed_exact_both_output_control_terminal(
            principal,
            window_label,
            request,
            shape_sha256,
            argument_fingerprint,
        )
}

pub(crate) fn record_durable_managed_exact_both_output_control_terminal(
    state: &AppState,
    principal: &str,
    window_label: &str,
    request: &OutputControlCommandRequestV2,
    shape_sha256: &str,
    argument_fingerprint: &str,
    response: &OutputControlResponseV2,
) -> Result<(), String> {
    state
        .output_lease_durable_receipts
        .lock()
        .map_err(|_| "Output lease durable receipt journal lock was poisoned".to_string())?
        .record_managed_exact_both_output_control_terminal(
            principal,
            window_label,
            request,
            shape_sha256,
            argument_fingerprint,
            response,
        )
}

const DJ_LINK_DEDUPE_LIMIT: usize = 4_096;
const DJ_LINK_DEDUPE_TTL: Duration = Duration::from_secs(15 * 60);

/// Process-local DJ Link diagnostics and track-trigger dedupe. This state is
/// deliberately not part of ProjectFile, templates, backups, or standby
/// checkpoints. A project identity or mapping replacement clears the play
/// session ledger before the next peer event is admitted.
#[derive(Debug, Clone, PartialEq)]
struct DjLinkRuntime {
    project_epoch: u64,
    mappings: Vec<protocol::DjTrackTriggerMapping>,
    seen_play_sessions: BTreeMap<String, Instant>,
    /// The canonical ACTIVE that currently owns the runtime. Its dedupe
    /// receipt remains live even if no packet refreshes it for the general
    /// TTL: expiry must never turn a still-current/released session's replay
    /// into a second START or clear its release ownership.
    active_dedupe_key: Option<String>,
    state_generation: u64,
    track_active: bool,
    playing: bool,
    released: bool,
    /// A valid ACTIVE with no authored mapping retires all DJ mutation
    /// controls until a mapped ACTIVE has been started and acknowledged.  It
    /// is deliberately separate from `released`: only a canonical RELEASE
    /// ACK may set the release latch.
    unmapped_active_blocked: bool,
    loop_division: Option<u8>,
    /// Last accepted measured Rekordbox loop revision. Predicted fallback
    /// targets never advance this fence, so a later fresh measurement can
    /// always rebase the Timeline while stale/conflicting reports fail closed.
    loop_revision: Option<u64>,
    /// Last consumed physical F14 identity for this session. Fallback intent
    /// IDs are strictly monotonic, so this rejects both replays and delayed
    /// unique older intents without retaining an unbounded history.
    last_loop_fallback_intent_id: Option<u64>,
    last_event_id: Option<String>,
    track_content_id: Option<String>,
    track_title: Option<String>,
    track_artist: Option<String>,
    track_deck_id: Option<String>,
    track_deck_number: Option<u8>,
    track_started_at: Option<String>,
    track_playing: bool,
    track_bpm: Option<f64>,
    position_sec: Option<f64>,
    /// Canonical wire position (`positionAtSendSec` plus the bounded sample
    /// age) paired with `position_revision`.  Raw seconds alone are not a
    /// sufficient equality proof because two packets can carry different
    /// sample ages for the same reported playhead.
    source_position_ms: Option<u64>,
    position_revision: Option<u64>,
    play_session_id: Option<String>,
    pedal_owner: Option<String>,
    release_event_id: Option<String>,
    /// Persists the explicit Syndocal-side return intent across DJ socket
    /// replacement until one exact current candidate is admitted.
    pending_operator_return_request_id: Option<String>,
    authoritative_state: protocol::DjLinkTimelineStateValue,
    timeline_id: Option<String>,
    position_bars: u64,
    loop_active: bool,
    /// One immutable rebase receipt per completed Follow generation.  This
    /// remains process-local alongside the DJ Link session ledger.
    last_follow_rebase: Option<(u64, String, String)>,
}

impl DjLinkRuntime {
    fn from_coordinator(coordinator: &ProjectCoordinator) -> Self {
        Self {
            project_epoch: coordinator.epoch,
            mappings: coordinator.mappings.dj_track_triggers.clone(),
            seen_play_sessions: BTreeMap::new(),
            active_dedupe_key: None,
            state_generation: 0,
            track_active: false,
            playing: false,
            released: false,
            unmapped_active_blocked: false,
            loop_division: None,
            loop_revision: None,
            last_loop_fallback_intent_id: None,
            last_event_id: None,
            track_content_id: None,
            track_title: None,
            track_artist: None,
            track_deck_id: None,
            track_deck_number: None,
            track_started_at: None,
            track_playing: false,
            track_bpm: None,
            position_sec: None,
            source_position_ms: None,
            position_revision: None,
            play_session_id: None,
            pedal_owner: None,
            release_event_id: None,
            pending_operator_return_request_id: None,
            authoritative_state: protocol::DjLinkTimelineStateValue::Idle,
            timeline_id: None,
            position_bars: 0,
            loop_active: false,
            last_follow_rebase: None,
        }
    }

    fn sync_project(&mut self, coordinator: &ProjectCoordinator) {
        let mappings = &coordinator.mappings.dj_track_triggers;
        if self.project_epoch != coordinator.epoch || self.mappings != *mappings {
            // An explicit operator-return request is a process-local intent,
            // not project-owned DJ state.  A project/mapping publication may
            // retire every prior deck/session receipt, but it must not erase
            // that intent before a current candidate is admitted.  Preserve
            // only the already-validated Timeline correlation; admission
            // still resolves the new mapping and rechecks the live engine
            // Timeline before restoring DJ ownership.
            let pending_operator_return_request_id =
                self.pending_operator_return_request_id.clone();
            let pending_timeline_truth = pending_operator_return_request_id.as_ref().map(|_| {
                (
                    self.authoritative_state,
                    self.timeline_id.clone(),
                    self.position_bars,
                    self.loop_active,
                )
            });
            self.project_epoch = coordinator.epoch;
            self.mappings = mappings.clone();
            self.seen_play_sessions.clear();
            self.active_dedupe_key = None;
            self.track_active = false;
            self.playing = false;
            self.released = false;
            self.unmapped_active_blocked = false;
            self.loop_division = None;
            self.loop_revision = None;
            self.last_loop_fallback_intent_id = None;
            self.last_event_id = None;
            self.track_content_id = None;
            self.track_title = None;
            self.track_artist = None;
            self.track_deck_id = None;
            self.track_deck_number = None;
            self.track_started_at = None;
            self.track_playing = false;
            self.track_bpm = None;
            self.position_sec = None;
            self.source_position_ms = None;
            self.position_revision = None;
            self.play_session_id = None;
            self.pedal_owner = None;
            self.release_event_id = None;
            self.pending_operator_return_request_id = pending_operator_return_request_id;
            if let Some((authoritative_state, timeline_id, position_bars, loop_active)) =
                pending_timeline_truth
            {
                self.authoritative_state = authoritative_state;
                self.timeline_id = timeline_id;
                self.position_bars = position_bars;
                self.loop_active = loop_active;
            } else {
                self.authoritative_state = protocol::DjLinkTimelineStateValue::Idle;
                self.timeline_id = None;
                self.position_bars = 0;
                self.loop_active = false;
            }
            self.last_follow_rebase = None;
        }
    }

    fn purge_dedupe(&mut self, now: Instant) {
        let active_dedupe_key = self.active_dedupe_key.as_deref();
        self.seen_play_sessions.retain(|key, observed| {
            Some(key.as_str()) == active_dedupe_key
                || now.duration_since(*observed) <= DJ_LINK_DEDUPE_TTL
        });
        // Live entries are never evicted to make room for a new event.  A
        // full ledger fails closed in the dispatcher; only the explicit TTL
        // purge can release a once-per-session slot.
    }

    fn operator_return_candidate(&self, snapshot: &EngineSnapshot) -> Result<Self, &'static str> {
        let has_owned_session = self.track_active
            || self.play_session_id.is_some()
            || self.pedal_owner.is_some()
            || self.release_event_id.is_some();
        let retrying_unowned_timeline = !self.track_active
            && self.play_session_id.is_none()
            && self.pedal_owner.is_none()
            && self.timeline_id.is_some();
        if !has_owned_session && !retrying_unowned_timeline {
            return Err("dj_control_return_owner_unavailable");
        }
        if self.authoritative_state != protocol::DjLinkTimelineStateValue::Running
            || !snapshot.timeline.playing
        {
            return Err("dj_control_return_requires_running_timeline");
        }
        let next_generation =
            dj_link_next_generation(self).map_err(|_| "dj_control_return_generation_exhausted")?;
        let mut next = self.clone();
        next.active_dedupe_key = None;
        next.track_active = false;
        next.playing = snapshot.timeline.playing;
        next.released = false;
        next.unmapped_active_blocked = false;
        next.loop_division = None;
        next.loop_revision = None;
        next.last_loop_fallback_intent_id = None;
        next.last_event_id = None;
        next.track_content_id = None;
        next.track_title = None;
        next.track_artist = None;
        next.track_deck_id = None;
        next.track_deck_number = None;
        next.track_started_at = None;
        next.track_playing = false;
        next.track_bpm = None;
        next.position_sec = None;
        next.source_position_ms = None;
        next.position_revision = None;
        next.play_session_id = None;
        next.pedal_owner = None;
        next.release_event_id = None;
        next.pending_operator_return_request_id = None;
        next.authoritative_state = if snapshot.timeline.playing {
            protocol::DjLinkTimelineStateValue::Running
        } else if snapshot.timeline.position_ms == 0 {
            protocol::DjLinkTimelineStateValue::Idle
        } else {
            protocol::DjLinkTimelineStateValue::Stopped
        };
        next.timeline_id = Some(snapshot.timeline.id.0.to_string());
        next.position_bars = dj_link_engine_position_bars(snapshot);
        next.loop_active = !matches!(
            snapshot.timeline.loop_runtime.status,
            protocol::TimelineLoopRuntimeStatus::Disabled
        );
        next.last_follow_rebase = None;
        next.state_generation = next_generation;
        Ok(next)
    }
}

fn dj_link_engine_position_bars(snapshot: &EngineSnapshot) -> u64 {
    let bpm = snapshot.clock.bpm;
    if !bpm.is_finite() || bpm <= 0.0 {
        return 0;
    }
    let bar_ms =
        (60_000.0_f64 / f64::from(bpm) * f64::from(protocol::DJ_LINK_BEATS_PER_BAR)).round();
    if !bar_ms.is_finite() || bar_ms < 1.0 || bar_ms > u64::MAX as f64 {
        return 0;
    }
    snapshot.timeline.position_ms / (bar_ms as u64)
}

/// A bare runtime boolean is never enough to keep DJ Link in Timeline
/// control. Only the engine's exact terminal Follow receipt may describe the
/// paused target as `Running` to the v3 peer while it waits for Pedal 1.
fn dj_link_completed_wait_for_pedal(snapshot: &EngineSnapshot) -> bool {
    let follow = &snapshot.timeline.follow_runtime;
    follow.waiting_for_pedal_start
        && !snapshot.timeline.playing
        && snapshot.timeline.position_ms == 0
        && matches!(
            snapshot.timeline.loop_runtime.status,
            protocol::TimelineLoopRuntimeStatus::Disabled
        )
        && !follow.transition_hold_active
        && follow.generation > 0
        && follow.status == protocol::TimelineFollowRuntimeStatus::Idle
        && matches!(
            follow.outcome,
            Some(protocol::TimelineFollowOutcome::Completed)
        )
        && follow.source_timeline_id.is_some()
        && follow.target_timeline_id == Some(snapshot.timeline.id)
        && follow.source_timeline_id != follow.target_timeline_id
}

fn dj_link_timeline_state_from_snapshot(
    runtime: &DjLinkRuntime,
    snapshot: &EngineSnapshot,
    event_id: &str,
    sequence: u64,
) -> protocol::DjLinkTimelineState {
    let timeline_id = runtime
        .timeline_id
        .clone()
        .unwrap_or_else(|| "none".to_string());
    let loop_active = runtime.loop_active
        || !matches!(
            snapshot.timeline.loop_runtime.status,
            protocol::TimelineLoopRuntimeStatus::Disabled
        );
    let transition_hold_active = snapshot.timeline.follow_runtime.transition_hold_active;
    let waiting_for_pedal_start = dj_link_completed_wait_for_pedal(snapshot);
    // The engine's acknowledged clock is the only grid authority. The
    // Rekordbox track BPM is diagnostic metadata and may be stale or absent.
    let position_bars = dj_link_engine_position_bars(snapshot);
    let state = if runtime.timeline_id.is_none() {
        protocol::DjLinkTimelineStateValue::Idle
    } else if snapshot.timeline.playing || waiting_for_pedal_start {
        // A completed WaitForPedal Follow deliberately pauses the target at
        // zero. Keep the existing v3 Timeline-control state Running so the
        // peer retains its already-correlated session/owner/release context
        // for the next Pedal 1 loop-on edge.
        protocol::DjLinkTimelineStateValue::Running
    } else if runtime.authoritative_state == protocol::DjLinkTimelineStateValue::Running {
        // A stale runtime latch must never make a stopped Timeline look
        // running to the peer. `Stopped` is terminal for this snapshot and
        // causes the peer to leave timeline-control.
        protocol::DjLinkTimelineStateValue::Stopped
    } else {
        runtime.authoritative_state
    };
    protocol::DjLinkTimelineState {
        message_type: "DJ_TIMELINE_STATE".to_string(),
        event_id: event_id.to_string(),
        sequence,
        state,
        loop_active,
        transition_hold_active,
        timeline_id,
        position_bars,
        play_session_id: runtime.play_session_id.clone(),
        // DJ Link v3 currently carries no independently verifiable pedal
        // identity.  Never invent one from a loop report.
        pedal_owner: runtime.pedal_owner.clone(),
        release_event_id: runtime.release_event_id.clone(),
        operator_return_request_id: runtime.pending_operator_return_request_id.clone(),
    }
}

fn dj_link_accepted(state_generation: u64) -> DjLinkDispatchOutcome {
    DjLinkDispatchOutcome::Accepted { state_generation }
}

fn dj_link_rejected(code: &str, state_generation: u64) -> DjLinkDispatchOutcome {
    DjLinkDispatchOutcome::Rejected {
        code: code.to_string(),
        state_generation,
    }
}

/// A machine-level DJ listener may exist before any project is loaded, but it
/// never receives an authored mapping authority until a project path is
/// present. Authentication happens in the socket layer; this is the final
/// cold-project injection gate shared by production and listener tests.
fn dj_link_cold_project_rejection(
    project_loaded: bool,
    runtime: &Mutex<DjLinkRuntime>,
) -> Option<DjLinkDispatchOutcome> {
    (!project_loaded).then(|| {
        dj_link_rejected(
            "project_mapping_not_loaded",
            dj_link_runtime_generation_if_available(runtime),
        )
    })
}

/// Dispatches an event that the socket transport has already authenticated.
/// Keeping the cold-project check beside the canonical dispatcher makes it
/// impossible for test listeners to bypass the production injection policy.
fn dispatch_authenticated_dj_link_event_for_project(
    project_loaded: bool,
    envelope: protocol::DjLinkEnvelope,
    engine: &EngineHandle,
    project_coordinator: &Mutex<ProjectCoordinator>,
    runtime: &Mutex<DjLinkRuntime>,
    external_admission: &ProjectExternalCommandAdmission,
    project_transaction_active: &AtomicBool,
) -> DjLinkDispatchOutcome {
    if let Some(rejection) = dj_link_cold_project_rejection(project_loaded, runtime) {
        return rejection;
    }
    dispatch_dj_link_event(
        envelope,
        engine,
        project_coordinator,
        runtime,
        external_admission,
        project_transaction_active,
    )
}

/// Best-effort diagnostic generation for a fail-fast Busy reply. A DJ socket
/// worker must never wait on the runtime mutex merely to explain that another
/// project/runtime authority already owns the lane.
fn dj_link_runtime_generation_if_available(runtime: &Mutex<DjLinkRuntime>) -> u64 {
    match runtime.try_lock() {
        Ok(runtime) => runtime.state_generation,
        Err(TryLockError::Poisoned(poisoned)) => poisoned.into_inner().state_generation,
        Err(TryLockError::WouldBlock) => 0,
    }
}

fn dj_link_next_generation(runtime: &DjLinkRuntime) -> Result<u64, String> {
    runtime
        .state_generation
        .checked_add(1)
        .ok_or_else(|| "DJ Link state generation exhausted; restart Syndocal".to_string())
}

fn dj_link_measured_loop_division(
    loop_state: &protocol::DjLinkMeasuredLoop,
) -> Result<Option<u8>, &'static str> {
    if !loop_state.active {
        if loop_state.start_beat.is_some()
            || loop_state.end_beat.is_some()
            || loop_state.length_beats.is_some()
        {
            return Err("inactive_loop_shape_invalid");
        }
        return Ok(None);
    }
    let Some(length_beats) = loop_state.length_beats else {
        return Err("active_loop_length_missing");
    };
    dj_loop_range::division_for_profile_length(length_beats).map(Some)
}

fn dj_link_track_payload_is_current(payload: &protocol::DjLinkTrackPayload) -> bool {
    payload.is_playing
        && !payload.play_session_id.trim().is_empty()
        && !payload.deck_id.trim().is_empty()
        && payload.position_revision > 0
}

fn dj_link_track_identity_matches_runtime(
    runtime: &DjLinkRuntime,
    payload: &protocol::DjLinkTrackPayload,
) -> bool {
    let incoming = protocol::DjTrackSelector {
        content_id: payload.content_id.clone(),
        title: payload.title.clone(),
        artist: payload.artist.clone(),
        title_contains: None,
        fallback_deck: None,
    };
    let admitted = protocol::DjTrackSelector {
        content_id: runtime.track_content_id.clone(),
        title: runtime.track_title.clone(),
        artist: runtime.track_artist.clone(),
        title_contains: None,
        fallback_deck: None,
    };
    incoming.canonical_key().ok() == admitted.canonical_key().ok()
}

fn dj_link_estimated_position_ms(
    payload: &protocol::DjLinkTrackPayload,
) -> Result<u64, &'static str> {
    if !payload.position_at_send_sec.is_finite()
        || !(0.0..=protocol::DJ_LINK_MAX_POSITION_AT_SEND_SEC)
            .contains(&payload.position_at_send_sec)
        || payload.sample_age_ms > protocol::DJ_LINK_MAX_SAMPLE_AGE_MS
    {
        return Err("invalid_track_position");
    }
    let base_ms = (payload.position_at_send_sec * 1_000.0).round();
    if !base_ms.is_finite() || base_ms < 0.0 || base_ms > u64::MAX as f64 {
        return Err("invalid_track_position");
    }
    (base_ms as u64)
        .checked_add(payload.sample_age_ms)
        .ok_or("invalid_track_position")
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DjLinkPositionRevisionDisposition {
    NewerOrNewSession,
    ExactDuplicate,
}

/// A position revision is a single canonical wire position, not a last-write
/// wins label.  Keep this check independent of engine state: engine-side
/// clipping to a Timeline duration is not a proof that two wire samples were
/// equal.
fn dj_link_position_revision_disposition(
    runtime: &DjLinkRuntime,
    play_session_id: &str,
    position_revision: u64,
    source_position_ms: u64,
) -> Result<DjLinkPositionRevisionDisposition, &'static str> {
    if runtime.play_session_id.as_deref() != Some(play_session_id) {
        return Ok(DjLinkPositionRevisionDisposition::NewerOrNewSession);
    }
    let Some(current_revision) = runtime.position_revision else {
        return Ok(DjLinkPositionRevisionDisposition::NewerOrNewSession);
    };
    if position_revision < current_revision {
        return Err("stale_position_revision");
    }
    if position_revision > current_revision {
        return Ok(DjLinkPositionRevisionDisposition::NewerOrNewSession);
    }
    if runtime.source_position_ms == Some(source_position_ms) {
        Ok(DjLinkPositionRevisionDisposition::ExactDuplicate)
    } else {
        Err("position_revision_conflict")
    }
}

/// Canonical DJ Link authority callback used by the single Web Remote
/// listener. The transport has already authenticated and reserved the event
/// identity; this lane supplies project admission, bounded play-session
/// dedupe, and runtime-only EngineCommand dispatch. No project history or
/// physical output API is reachable from this callback.
fn dispatch_dj_link_event(
    envelope: protocol::DjLinkEnvelope,
    engine: &EngineHandle,
    project_coordinator: &Mutex<ProjectCoordinator>,
    runtime: &Mutex<DjLinkRuntime>,
    external_admission: &ProjectExternalCommandAdmission,
    project_transaction_active: &AtomicBool,
) -> DjLinkDispatchOutcome {
    let Some(_admission) = try_lock_project_external_command_admission(external_admission) else {
        return DjLinkDispatchOutcome::Busy {
            code: "project_admission_busy".to_string(),
            state_generation: dj_link_runtime_generation_if_available(runtime),
        };
    };
    if project_transaction_active.load(Ordering::Acquire) {
        return DjLinkDispatchOutcome::Busy {
            code: "project_transaction_busy".to_string(),
            state_generation: dj_link_runtime_generation_if_available(runtime),
        };
    }
    let coordinator = match project_coordinator.try_lock() {
        Ok(coordinator) => coordinator,
        Err(TryLockError::WouldBlock) => {
            return DjLinkDispatchOutcome::Busy {
                code: "project_coordinator_busy".to_string(),
                state_generation: dj_link_runtime_generation_if_available(runtime),
            }
        }
        Err(TryLockError::Poisoned(_)) => {
            return dj_link_rejected("project_coordinator_poisoned", 0)
        }
    };
    let mut runtime = match runtime.try_lock() {
        Ok(runtime) => runtime,
        Err(TryLockError::WouldBlock) => {
            return DjLinkDispatchOutcome::Busy {
                code: "dj_link_runtime_busy".to_string(),
                state_generation: 0,
            }
        }
        Err(TryLockError::Poisoned(_)) => return dj_link_rejected("dj_link_runtime_poisoned", 0),
    };
    runtime.sync_project(&coordinator);
    let current_generation = runtime.state_generation;
    let event_id = envelope.event_id.clone();
    let sequence = envelope.sequence;
    match envelope.message_type {
        protocol::DjLinkMessageType::TrackActive => {
            let payload =
                match serde_json::from_value::<protocol::DjLinkTrackPayload>(envelope.payload) {
                    Ok(payload) => payload,
                    Err(_) => return dj_link_rejected("invalid_track_payload", current_generation),
                };
            dj_track_runtime::dispatch_active(
                payload,
                engine,
                &mut runtime,
                current_generation,
                &event_id,
                sequence,
            )
        }
        protocol::DjLinkMessageType::TrackSync => {
            let payload =
                match serde_json::from_value::<protocol::DjLinkTrackPayload>(envelope.payload) {
                    Ok(payload) => payload,
                    Err(_) => {
                        return dj_link_rejected("invalid_track_sync_payload", current_generation)
                    }
                };
            dj_track_runtime::dispatch_sync(
                payload,
                engine,
                &mut runtime,
                current_generation,
                &event_id,
                sequence,
            )
        }
        protocol::DjLinkMessageType::LoopState => {
            let payload = match serde_json::from_value::<protocol::DjLinkTrackLoopStatePayload>(
                envelope.payload,
            ) {
                Ok(payload) => payload,
                Err(_) => {
                    return dj_link_rejected("invalid_track_loop_state_payload", current_generation)
                }
            };
            dj_track_runtime::dispatch_loop_state(
                payload,
                engine,
                &mut runtime,
                current_generation,
                &event_id,
            )
        }
        protocol::DjLinkMessageType::LoopFallback => {
            let payload = match serde_json::from_value::<protocol::DjLinkTrackLoopFallbackPayload>(
                envelope.payload,
            ) {
                Ok(payload) => payload,
                Err(_) => {
                    return dj_link_rejected(
                        "invalid_track_loop_fallback_payload",
                        current_generation,
                    )
                }
            };
            dj_track_runtime::dispatch_loop_fallback(
                payload,
                engine,
                &mut runtime,
                current_generation,
                &event_id,
            )
        }
        protocol::DjLinkMessageType::Release => {
            let payload =
                match serde_json::from_value::<protocol::DjLinkReleasePayload>(envelope.payload) {
                    Ok(payload) => payload,
                    Err(_) => {
                        return dj_link_rejected("invalid_release_payload", current_generation)
                    }
                };
            if runtime.unmapped_active_blocked {
                return dj_link_rejected("dj_link_unmapped_active", current_generation);
            }
            if payload.state != "released" {
                return dj_link_rejected("release_context_mismatch", current_generation);
            }
            if let Some(code) = dj_track_runtime::release_authority_rejection(
                &runtime,
                &payload.timeline_id,
                &payload.play_session_id,
            ) {
                return dj_link_rejected(code, current_generation);
            }
            if runtime.released {
                // Release fencing: the first canonical correlated RELEASE owns
                // the immutable receipt identity.  An exact replay and a
                // distinct later RELEASE both observe truthful
                // already-released ownership without rerunning the engine
                // release side effect or replacing `release_event_id`.
                let Some(snapshot) = engine.try_snapshot() else {
                    return DjLinkDispatchOutcome::Busy {
                        code: "engine_snapshot_busy".to_string(),
                        state_generation: current_generation,
                    };
                };
                return DjLinkDispatchOutcome::TimelineState {
                    state_generation: current_generation,
                    state: dj_link_timeline_state_from_snapshot(
                        &runtime, &snapshot, &event_id, sequence,
                    ),
                };
            }
            let Ok(expected_timeline_id) = payload.timeline_id.parse::<u64>() else {
                return dj_link_rejected("timeline_identity_mismatch", current_generation);
            };
            let next = match dj_link_next_generation(&runtime) {
                Ok(next) => next,
                Err(_) => {
                    return dj_link_rejected("state_generation_exhausted", current_generation)
                }
            };
            let snapshot = match engine
                .dj_link_release_with_canonical_snapshot(TimelineId(expected_timeline_id))
            {
                Ok(snapshot) => snapshot,
                Err(_) => {
                    return dj_link_rejected("engine_publication_rejected", current_generation)
                }
            };
            runtime.released = true;
            runtime.authoritative_state = protocol::DjLinkTimelineStateValue::Running;
            runtime.loop_active = false;
            runtime.pedal_owner = Some("timeline".to_string());
            runtime.release_event_id = Some(event_id.clone());
            runtime.last_event_id = Some(envelope.event_id);
            runtime.state_generation = next;
            DjLinkDispatchOutcome::TimelineState {
                state_generation: next,
                state: dj_link_timeline_state_from_snapshot(
                    &runtime, &snapshot, &event_id, sequence,
                ),
            }
        }
        protocol::DjLinkMessageType::StateSync => {
            let payload = match serde_json::from_value::<protocol::DjLinkTrackStateSyncPayload>(
                envelope.payload,
            ) {
                Ok(payload) => payload,
                Err(_) => {
                    return dj_link_rejected("invalid_track_state_sync_payload", current_generation)
                }
            };
            if payload.validate().is_err() {
                return dj_link_rejected("invalid_track_state_sync_payload", current_generation);
            }
            if runtime.unmapped_active_blocked {
                return dj_link_rejected("dj_link_unmapped_active", current_generation);
            }
            if let Some(code) =
                dj_track_runtime::state_sync_owner_context_rejection(&runtime, &payload)
            {
                return dj_link_rejected(code, current_generation);
            }
            runtime.last_event_id = Some(envelope.event_id);
            dj_link_accepted(current_generation)
        }
        protocol::DjLinkMessageType::TimelineStateRequest => {
            let Some(snapshot) = engine.try_snapshot() else {
                return DjLinkDispatchOutcome::Busy {
                    code: "engine_snapshot_busy".to_string(),
                    state_generation: current_generation,
                };
            };
            let _ = dj_track_runtime::rebase_released_follow_completion(
                &mut runtime,
                &snapshot,
                None,
                None,
            );
            DjLinkDispatchOutcome::TimelineState {
                state_generation: runtime.state_generation,
                state: dj_link_timeline_state_from_snapshot(
                    &runtime, &snapshot, &event_id, sequence,
                ),
            }
        }
        protocol::DjLinkMessageType::TimelineBeatJump => {
            let payload = match serde_json::from_value::<protocol::DjLinkTimelineBeatJumpPayload>(
                envelope.payload,
            ) {
                Ok(payload) => payload,
                Err(_) => {
                    return dj_link_rejected(
                        "invalid_timeline_beat_jump_payload",
                        current_generation,
                    )
                }
            };
            if payload.bars != 4 {
                return dj_link_rejected("invalid_timeline_beat_jump_payload", current_generation);
            }
            // The dispatcher keeps the runtime mutex through the synchronous
            // canonical ACK, so no concurrent app projection can advance its
            // generation while the worker repeats the authority check.
            let Some(snapshot) = engine.try_snapshot() else {
                return DjLinkDispatchOutcome::Busy {
                    code: "engine_snapshot_busy".to_string(),
                    state_generation: current_generation,
                };
            };
            let _ = dj_track_runtime::rebase_released_follow_completion(
                &mut runtime,
                &snapshot,
                Some(&payload.timeline_id),
                Some(&payload.play_session_id),
            );
            let current_generation = runtime.state_generation;
            if let Some(code) = dj_track_runtime::stage2_authority_rejection(
                &runtime,
                &payload.timeline_id,
                &payload.play_session_id,
                &snapshot,
            ) {
                return dj_link_rejected(code, current_generation);
            }
            let Ok(timeline_id) = payload.timeline_id.parse::<u64>() else {
                return dj_link_rejected("invalid_timeline_id", current_generation);
            };
            if timeline_id == 0 {
                return dj_link_rejected("invalid_timeline_id", current_generation);
            }
            let next_generation = match dj_link_next_generation(&runtime) {
                Ok(next) => next,
                Err(_) => {
                    return dj_link_rejected("state_generation_exhausted", current_generation)
                }
            };
            let snapshot = match engine.dj_link_timeline_beat_jump_with_canonical_snapshot(
                TimelineId(timeline_id),
                payload.bars,
            ) {
                Ok(snapshot) => snapshot,
                Err(_) => {
                    return dj_link_rejected("engine_publication_rejected", current_generation)
                }
            };
            // The ACK is the mutation boundary. Read the exact post-ACK
            // engine image and derive bars from its authoritative clock; do
            // not perform fallible arithmetic against stale runtime or track
            // metadata after a successful mutation.
            runtime.position_bars = dj_link_engine_position_bars(&snapshot);
            runtime.last_event_id = Some(event_id.clone());
            runtime.state_generation = next_generation;
            DjLinkDispatchOutcome::TimelineState {
                state_generation: next_generation,
                state: dj_link_timeline_state_from_snapshot(
                    &runtime, &snapshot, &event_id, sequence,
                ),
            }
        }
        protocol::DjLinkMessageType::TimelineLoopSet => {
            let payload = match serde_json::from_value::<protocol::DjLinkTimelineLoopSetPayload>(
                envelope.payload,
            ) {
                Ok(payload) => payload,
                Err(_) => {
                    return dj_link_rejected(
                        "invalid_timeline_loop_set_payload",
                        current_generation,
                    )
                }
            };
            // The dispatcher keeps the runtime mutex through the synchronous
            // canonical ACK, so no concurrent app projection can advance its
            // generation while the worker repeats the authority check.
            let Some(snapshot) = engine.try_snapshot() else {
                return DjLinkDispatchOutcome::Busy {
                    code: "engine_snapshot_busy".to_string(),
                    state_generation: current_generation,
                };
            };
            let _ = dj_track_runtime::rebase_released_follow_completion(
                &mut runtime,
                &snapshot,
                Some(&payload.timeline_id),
                Some(&payload.play_session_id),
            );
            let current_generation = runtime.state_generation;
            // A completed WaitForPedal Follow is neither normal Stage 2
            // playback nor an authored loop. Its only admitted Pedal 1 edge
            // is loop-on: consume that exact correlation to start the
            // already-installed target at zero. A retransmitted envelope is
            // an ACK no-op, never a later loop toggle.
            if runtime.last_event_id.as_deref() == Some(event_id.as_str()) {
                return DjLinkDispatchOutcome::TimelineState {
                    state_generation: current_generation,
                    state: dj_link_timeline_state_from_snapshot(
                        &runtime, &snapshot, &event_id, sequence,
                    ),
                };
            }
            if snapshot.timeline.follow_runtime.waiting_for_pedal_start {
                if !payload.active {
                    return dj_link_rejected(
                        "timeline_waiting_pedal_start_requires_active",
                        current_generation,
                    );
                }
                if let Some(code) = dj_track_runtime::waiting_follow_pedal_start_authority_rejection(
                    &runtime,
                    &snapshot,
                    &payload.timeline_id,
                    &payload.play_session_id,
                ) {
                    return dj_link_rejected(code, current_generation);
                }
                let Ok(target_timeline_id) = payload.timeline_id.parse::<u64>() else {
                    return dj_link_rejected("invalid_timeline_id", current_generation);
                };
                if target_timeline_id == 0 {
                    return dj_link_rejected("invalid_timeline_id", current_generation);
                }
                let Some(source_timeline_id) = snapshot.timeline.follow_runtime.source_timeline_id
                else {
                    return dj_link_rejected("timeline_waiting_pedal_stale", current_generation);
                };
                let next_generation = match dj_link_next_generation(&runtime) {
                    Ok(next) => next,
                    Err(_) => {
                        return dj_link_rejected("state_generation_exhausted", current_generation)
                    }
                };
                let snapshot = match engine
                    .dj_link_start_waiting_follow_target_with_canonical_snapshot(
                        source_timeline_id,
                        TimelineId(target_timeline_id),
                        snapshot.timeline.follow_runtime.generation,
                    ) {
                    Ok(snapshot) => snapshot,
                    Err(_) => {
                        return dj_link_rejected("engine_publication_rejected", current_generation)
                    }
                };
                // The canonical engine ACK is the one-shot mutation boundary.
                // Do not advance app state or receipt before it.
                runtime.loop_active = false;
                runtime.position_bars = dj_link_engine_position_bars(&snapshot);
                runtime.last_event_id = Some(event_id.clone());
                runtime.state_generation = next_generation;
                return DjLinkDispatchOutcome::TimelineState {
                    state_generation: next_generation,
                    state: dj_link_timeline_state_from_snapshot(
                        &runtime, &snapshot, &event_id, sequence,
                    ),
                };
            }
            if let Some(code) = dj_track_runtime::stage2_authority_rejection(
                &runtime,
                &payload.timeline_id,
                &payload.play_session_id,
                &snapshot,
            ) {
                return dj_link_rejected(code, current_generation);
            }
            if let Some(code) = dj_track_runtime::timeline_loop_set_authority_rejection(
                &runtime,
                &snapshot,
                payload.active,
            ) {
                return dj_link_rejected(code, current_generation);
            }
            let Ok(timeline_id) = payload.timeline_id.parse::<u64>() else {
                return dj_link_rejected("invalid_timeline_id", current_generation);
            };
            if timeline_id == 0 {
                return dj_link_rejected("invalid_timeline_id", current_generation);
            }
            let next_generation = match dj_link_next_generation(&runtime) {
                Ok(next) => next,
                Err(_) => {
                    return dj_link_rejected("state_generation_exhausted", current_generation)
                }
            };
            let snapshot = match engine
                .dj_link_set_current_timeline_loop_enabled_with_canonical_snapshot(
                    TimelineId(timeline_id),
                    payload.active,
                ) {
                Ok(snapshot) => snapshot,
                Err(_) => {
                    return dj_link_rejected("engine_publication_rejected", current_generation)
                }
            };
            // The ACK is based on the engine publication.  The returned state
            // is built from the post-ACK snapshot, never from the request.
            runtime.loop_active = !matches!(
                snapshot.timeline.loop_runtime.status,
                protocol::TimelineLoopRuntimeStatus::Disabled
            );
            runtime.last_event_id = Some(event_id.clone());
            runtime.state_generation = next_generation;
            DjLinkDispatchOutcome::TimelineState {
                state_generation: next_generation,
                state: dj_link_timeline_state_from_snapshot(
                    &runtime, &snapshot, &event_id, sequence,
                ),
            }
        }
        protocol::DjLinkMessageType::TimelineLoopHalf => {
            let payload = match serde_json::from_value::<protocol::DjLinkTimelineLoopHalfPayload>(
                envelope.payload,
            ) {
                Ok(payload) => payload,
                Err(_) => {
                    return dj_link_rejected(
                        "invalid_timeline_loop_half_payload",
                        current_generation,
                    )
                }
            };
            let Some(snapshot) = engine.try_snapshot() else {
                return DjLinkDispatchOutcome::Busy {
                    code: "engine_snapshot_busy".to_string(),
                    state_generation: current_generation,
                };
            };
            let _ = dj_track_runtime::rebase_released_follow_completion(
                &mut runtime,
                &snapshot,
                Some(&payload.timeline_id),
                Some(&payload.play_session_id),
            );
            let current_generation = runtime.state_generation;
            if let Some(code) = dj_track_runtime::stage2_authority_rejection(
                &runtime,
                &payload.timeline_id,
                &payload.play_session_id,
                &snapshot,
            ) {
                return dj_link_rejected(code, current_generation);
            }
            if let Some(code) =
                dj_track_runtime::timeline_loop_half_authority_rejection(&runtime, &snapshot)
            {
                return dj_link_rejected(code, current_generation);
            }
            let Ok(timeline_id) = payload.timeline_id.parse::<u64>() else {
                return dj_link_rejected("invalid_timeline_id", current_generation);
            };
            if timeline_id == 0 {
                return dj_link_rejected("invalid_timeline_id", current_generation);
            }
            let next_generation = match dj_link_next_generation(&runtime) {
                Ok(next) => next,
                Err(_) => {
                    return dj_link_rejected("state_generation_exhausted", current_generation)
                }
            };
            let snapshot = match engine
                .dj_link_half_current_timeline_loop_with_canonical_snapshot(TimelineId(timeline_id))
            {
                Ok(snapshot) => snapshot,
                Err(_) => {
                    return dj_link_rejected("engine_publication_rejected", current_generation)
                }
            };
            runtime.loop_active = !matches!(
                snapshot.timeline.loop_runtime.status,
                protocol::TimelineLoopRuntimeStatus::Disabled
            );
            runtime.last_event_id = Some(event_id.clone());
            runtime.state_generation = next_generation;
            DjLinkDispatchOutcome::TimelineState {
                state_generation: next_generation,
                state: dj_link_timeline_state_from_snapshot(
                    &runtime, &snapshot, &event_id, sequence,
                ),
            }
        }
        protocol::DjLinkMessageType::Heartbeat | protocol::DjLinkMessageType::Hello => {
            dj_link_accepted(current_generation)
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ApplicationUpdatePublicationClaim {
    origin_id: String,
    request_id: u64,
    shape_hash: String,
    backup_id: u64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ProjectPublicationReconcileClaimV1 {
    origin_id: String,
    request_id: u64,
    shape_hash: String,
    recovery_authority_serial: u64,
    reservation_generation: u64,
}

struct ProjectPublicationReconcileClaimGuardV1<'a> {
    slot: &'a Mutex<Option<ProjectPublicationReconcileClaimV1>>,
    claim: ProjectPublicationReconcileClaimV1,
}

impl Drop for ProjectPublicationReconcileClaimGuardV1<'_> {
    fn drop(&mut self) {
        let mut slot = match self.slot.lock() {
            Ok(slot) => slot,
            Err(poisoned) => poisoned.into_inner(),
        };
        if slot.as_ref() == Some(&self.claim) {
            *slot = None;
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct ProjectPublicationMutationBinding<'a> {
    window_label: &'a str,
    owner_id: &'a str,
}

struct AppState {
    engine: EngineHandle,
    /// The application handle is retained for fenced project replacement so
    /// every project entry point can retire native Display windows before the
    /// engine accepts a new snapshot. Commands do not run until setup has
    /// installed this value.
    app_handle: Mutex<Option<tauri::AppHandle>>,
    vj_first_run: Arc<Mutex<()>>,
    vj_preview_transport: Mutex<VjPreviewTransportRuntime>,
    vj_preview_renderer: Mutex<AppVideoPreviewRenderer>,
    vj_preview_renderer_reset_pending: AtomicBool,
    /// Long-running local media preparation is explicitly separate from the
    /// project mutation ticket. Each operation is owned by an opaque server
    /// generation so a delayed cancel for an old request cannot stop a newer
    /// request that reused the same client request ID.
    media_asset_operations: Arc<MediaAssetOperationRegistry>,
    /// Bounded, typed receipt state for server-authoritative authored
    /// mutations which retain the legacy local Tauri source name.
    authored_control_plane: authored_control_plane::AuthoredControlPlaneState,
    runtime_control_plane: control_plane_runtime::RuntimeControlPlaneState,
    /// Process-local AI3 authority. It is deliberately not persisted or
    /// reconstructed from project/query state; every production mutation
    /// enters through `submit_request`.
    output_lease_registry: Mutex<OutputLeaseRegistry>,
    /// Process-local exact-`Both` lease renewal and fail-stop authority. It is
    /// deliberately independent from the persisted registry and starts Idle
    /// on every process launch; only a newly verified durable Enable receipt
    /// can arm it.
    output_lease_keepalive: Arc<output_lease_keepalive_runtime::OutputLeaseKeepaliveRuntime>,
    /// Durable terminal evidence for output-lease requests.  This is not
    /// authority and is never used to reconstruct a lease after restart.
    output_lease_durable_receipts: Mutex<OutputLeaseDurableReceiptJournal>,
    /// Exact unacknowledged backup receipt pinned from the final local
    /// verification fence until the updater returns. ACK and deletion must not
    /// retire its evidence while the asynchronous install is in flight.
    application_update_publication_claim: Mutex<Option<ApplicationUpdatePublicationClaim>>,
    /// Exact process-local ownership of a Prepared receipt reconciliation.
    /// It is acquired under `project_save_publication` before query cleanup
    /// releases the mutation locks, so an original command cannot publish the
    /// same staging file while the query decides its durable terminal truth.
    project_publication_reconcile_claim: Mutex<Option<ProjectPublicationReconcileClaimV1>>,
    output_lease_clock_origin: Instant,
    next_output_lease_request_id: AtomicU64,
    /// The app-local DJ Link authority owns settings, Credential Manager
    /// restoration and the process-only listener token injection value.
    dj_link_machine: Mutex<DjLinkMachineAuthority>,
    /// The single background reaper for `media_asset_operations`, installed once
    /// during setup. Holding it here keeps the thread owned by `AppState` and
    /// joined on teardown instead of leaked.
    media_asset_reaper: Mutex<Option<MediaAssetOperationReaper>>,
    /// Counts the exact backend-owned Media Asset engine publication boundary
    /// in command-level tests. It is compiled out of production builds.
    #[cfg(test)]
    media_asset_authoritative_publish_attempts: AtomicU64,
    /// Command-level B3 proof counts only authored/direct engine publication
    /// boundaries; runtime slot transport intentionally stays history-free.
    #[cfg(test)]
    video_clip_slot_authoritative_publish_attempts: AtomicU64,
    /// C1 catalog tests count the sole Published catalog boundary. Exact
    /// receipt retries must never increment this counter.
    #[cfg(test)]
    video_effect_catalog_authoritative_publish_attempts: AtomicU64,
    /// Test-only proof that an authored effect toggle reaches the sole
    /// published engine primitive once, never on an exact receipt retry.
    #[cfg(test)]
    authored_effect_enabled_publish_attempts: AtomicU64,
    media_audio: Arc<Mutex<MediaAudioPlayback>>,
    timeline_cue_audio: Arc<TimelineCueAudioRuntime>,
    program_audio_handoff: Arc<ProgramAudioHandoffCoordinator>,
    _media_audio_sync: MediaAudioSyncRuntime,
    live_audio_input_lifecycle: Mutex<()>,
    live_audio_input_devices: Mutex<LiveAudioInputDeviceCatalog>,
    live_audio_input: Mutex<Option<LiveAudioInput>>,
    /// Durable machine storage for the explicit ABI v2 ASIO selection. The
    /// path is installed once during setup; the selection and its stale-lock
    /// status are restored at startup and rewritten after every successful
    /// native ASIO open.
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    asio_input_selection: Mutex<AsioInputSelectionState>,
    /// Process-local exclusive admission owner for normal and show-ASIO
    /// output routes. It is intentionally not reconstructed from project or
    /// machine settings; a missing owner fails show-ASIO closed.
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    audio_output_router: Option<Arc<audio_output_router::RouterSlot>>,
    /// Serializes operator-visible ASIO lifecycle mutations. RouterSlot still
    /// owns the authoritative route state; this lock prevents profile
    /// reselection from racing Start/Revalidate between validation and
    /// persistence.
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    asio_output_lifecycle: Mutex<()>,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    asio_output_runtime: Arc<Mutex<asio_output_runtime::AsioOutputRuntime>>,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    asio_output_session_generation: AtomicU64,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    asio_output_machine: Mutex<AsioOutputMachineState>,
    video_preview: Arc<Mutex<AppVideoPreviewRenderer>>,
    native_thumbnail_work: native_thumbnail_work::NativeThumbnailWork,
    video_recording: Mutex<VideoRecordingRuntime>,
    external_video_transport: Arc<Mutex<video::ExternalVideoTransportRuntime>>,
    external_video_transport_events: Arc<Mutex<Vec<ExternalVideoTransportDriverEvent>>>,
    capture_transport: Arc<Mutex<capture_transport::CaptureTransportState>>,
    capture_inputs: capture_transport::CaptureInputRegistry,
    #[cfg(feature = "ndi")]
    ndi_transport: Arc<Mutex<ndi_transport::NdiTransportState>>,
    #[cfg(feature = "ndi")]
    ndi_inputs: ndi_transport::NdiInputRegistry,
    #[cfg(all(feature = "spout", target_os = "windows", target_arch = "x86_64"))]
    spout_transport: Arc<Mutex<spout_transport::SpoutTransportState>>,
    /// Strict show-owned fixed sender pair. Generic Spout routes remain in
    /// `spout_transport`; this state is deliberately separate so the show
    /// pair cannot be restarted through generic route synchronization.
    #[cfg(all(feature = "spout", target_os = "windows", target_arch = "x86_64"))]
    show_spout_transport: Arc<Mutex<show_spout_transport::ShowSpoutTransportState>>,
    #[cfg(all(feature = "spout", target_os = "windows", target_arch = "x86_64"))]
    spout_inputs: spout_transport::SpoutInputRegistry,
    custom_profiles: Mutex<HashMap<String, FixtureProfileSummary>>,
    fixture_groups: Mutex<Vec<FixtureGroupSummary>>,
    fixture_group_delete_undo: Mutex<Option<DeletedFixtureGroup>>,
    visualizer_model_assets: Mutex<HashMap<String, VisualizerModelAssetCacheEntry>>,
    midi_clock: Mutex<Option<MidiClockInput>>,
    midi_control: Mutex<Option<MidiControlInput>>,
    midi_feedback: Arc<Mutex<Option<MidiFeedbackOutput>>>,
    midi_feedback_runtime: Mutex<Option<MidiFeedbackRuntime>>,
    midi_feedback_last_error: Arc<Mutex<Option<String>>>,
    osc_input: Mutex<Option<OscInput>>,
    /// Serializes listener stop/join and replacement without holding the
    /// general remote-control state mutex across worker joins or socket bind.
    remote_control_lifecycle: Mutex<()>,
    remote_control: Mutex<Option<RemoteWsServer>>,
    /// Process-lifetime DJ physical-event fence. Listener/session state is
    /// instance-local; this handle is deliberately retained across
    /// stop/start and recreated only with a fresh AppState/process.
    dj_link_process_fence: DjLinkProcessFenceHandle,
    dj_link_runtime: Arc<Mutex<DjLinkRuntime>>,
    dmx_input: Mutex<Option<io::dmx_input::DmxInput>>,
    pending_project_open_paths: Mutex<Vec<String>>,
    current_project_path: Arc<Mutex<Option<PathBuf>>>,
    operator_policy: Mutex<Option<OperatorPolicy>>,
    operator_selection: Arc<Mutex<OperatorSelectionContext>>,
    /// Serializes every project-identity operation with its authoritative
    /// ancillary state.  The legacy per-feature mutexes below remain UI
    /// compatibility mirrors while the coordinator is migrated through the
    /// command surface; they must only be changed by coordinator-owned
    /// helpers.
    project_coordinator: Arc<Mutex<ProjectCoordinator>>,
    /// Input callbacks deliberately do not take the coordinator mutex.  They
    /// compare this atomic generation immediately before an engine send so a
    /// callback captured by a retired project can never affect its successor.
    project_callback_epoch: Arc<AtomicU64>,
    /// Separate callback generation for mappings. Updating MIDI/OSC/DMX
    /// mappings retires only mapping-driven runtimes and must not silence the
    /// independent MIDI Clock transport input.
    project_mapping_callback_epoch: Arc<AtomicU64>,
    /// Begin→Commit reserves a coherent persistence capture. Callback inputs
    /// never take the coordinator mutex, so this atomic blocks MIDI/OSC/DMX
    /// and remote sends during that interval without creating a lock cycle.
    project_transaction_active: Arc<AtomicBool>,
    /// Begin receipts are retained by client operation identity rather than a
    /// frontend transaction number.  Pending receipts are never expired;
    /// terminal receipts are bounded by count and the lane refuses a new
    /// operation when the bound is full, so a valid reply-loss recovery can
    /// never race time-based eviction.
    project_transaction_receipts: Mutex<HashMap<String, ProjectTransactionReceipt>>,
    /// Compact per-owner-incarnation high-water marks let ACKed operation
    /// payloads be removed without allowing an old client sequence to replay.
    project_transaction_operation_highwaters: Mutex<HashMap<String, u64>>,
    /// Explicit admission/closing fences for the generic transaction lane.
    /// The external-admission mutex still serializes the production callers,
    /// while this per-operation cell makes callback retirement and in-flight
    /// accounting auditable and testable without holding a coordinator lock
    /// over an engine callback.
    project_transaction_lanes: Mutex<HashMap<String, Arc<ProjectTransactionLane>>>,
    /// Webview label -> current renderer generation. This makes transaction
    /// recovery a liveness decision instead of treating every different
    /// renderer as orphaned (which could steal a live pane's edit).
    project_transaction_owners: Mutex<HashMap<String, String>>,
    /// Backend-issued, never-reused renderer incarnation for each window
    /// label. Kept parallel to the wire-compatible owner string registry so
    /// stale same-string IPC cannot cross a retire/re-register ABA boundary.
    project_transaction_owner_incarnations: Mutex<HashMap<String, u64>>,
    next_project_transaction_owner_incarnation: AtomicU64,
    /// A renderer owner string is single-use for one concrete window label.
    /// Keeping the retired binding prevents a raw caller from re-registering
    /// an observed owner string and replaying an operation after the receipt,
    /// lane, and old incarnation have been compacted. The bounded registry
    /// fails closed at capacity; a process restart issues fresh frontend
    /// owner identities and is the recovery boundary.
    project_transaction_retired_owner_bindings: Mutex<HashSet<String>>,
    /// A Destroyed callback that cannot complete both owner/lease and query
    /// retirement permanently fences this concrete window label.  Entries are
    /// process-local and intentionally have no clear path: restart is the
    /// only recovery for a dead authority boundary.
    project_transaction_owner_retirement_failures: Mutex<HashSet<String>>,
    project_transaction_owner_retirement_failure_overflow: AtomicBool,
    /// Linearizes installation/removal of the temporary Destroyed-retirement
    /// fence with every caller that checks window authority. The existing
    /// owner-rotation mutex protects owner-map mutation; this separate guard
    /// is intentionally safe to acquire from paths that already hold it.
    project_transaction_owner_authority_barrier: Mutex<()>,
    /// Window labels whose Destroyed retirement has started but has not yet
    /// either completed or promoted to the permanent fail-closed registry.
    project_transaction_owner_retiring: Mutex<HashSet<String>>,
    /// Serializes capture/revalidation of a B3 caller incarnation with owner
    /// rotation. This is intentionally distinct from external command
    /// admission because authored/runtime commit helpers acquire that gate.
    project_transaction_owner_rotation: Mutex<()>,
    /// Backend-enforced Operator Lock state for each registered renderer owner.
    /// The project policy remains authoritative in the coordinator; this cache
    /// records only whether that exact owner has successfully unlocked the
    /// current epoch/policy image. A policy or identity change resets to the
    /// policy's `lock_on_load` default before any authoritative mutation.
    project_operator_sessions: Mutex<HashMap<String, ProjectOperatorSession>>,
    /// Monotonic order of successful backend clip-runtime publications and
    /// subsequently observed engine-clock transition images.
    video_clip_slot_runtime_generation: AtomicU64,
    /// Last runtime image paired with the generation above. Engine clock
    /// advancement can change Clip Take progress without an IPC command, so a
    /// read must advance the same monotonic fence whenever that image changes.
    video_clip_slot_runtime_observed: Mutex<VideoClipRuntimeSnapshot>,
    /// Monotonic fence for C3 Layer Transition Bus truth. Like Clip runtime,
    /// engine-clock advancement is observed lazily and receives a new safe
    /// JavaScript integer generation before publication to a renderer.
    video_transition_runtime_generation: AtomicU64,
    video_transition_runtime_observed: Mutex<VideoLayerTransitionRuntimeSnapshot>,
    /// Linearizes every external callback/remote engine send with project
    /// transaction baselines and identity publication.  Any path that also
    /// needs coordinator state must acquire this mutex first.
    project_external_command_admission: Arc<ProjectExternalCommandAdmission>,
    /// Serializes only the final atomic replacement/adoption phase of project
    /// saves. JSON/temp-file preparation happens outside this gate, while a
    /// delayed older writer is rejected under this gate before it can replace
    /// a newer file.
    project_save_publication: Mutex<()>,
    snapshot_sync: Mutex<SnapshotSyncState>,
    standby_sync: Mutex<StandbySyncRuntime>,
    standby_sync_lifecycle: Arc<Mutex<()>>,
    output_ownership_transition: Arc<Mutex<()>>,
    native_video_output_metrics:
        Mutex<HashMap<VideoOutputId, Arc<Mutex<NativeVideoOutputMetrics>>>>,
    native_video_output_workers: Mutex<HashMap<String, NativeVideoOutputWorker>>,
}

#[cfg(test)]
#[derive(Debug, Clone, PartialEq, Eq)]
struct OutputLeaseRegistrySnapshot {
    process_incarnation: u64,
    active_count: usize,
    orphan_count: usize,
    unclaimed_count: usize,
    max_generation: u64,
    audit_sequence: u64,
    generation_stamp: u64,
}

impl AppState {
    pub(crate) fn ensure_window_authority_not_blocked(
        &self,
        window_label: &str,
    ) -> Result<(), String> {
        validate_project_transaction_window_label(window_label)?;
        let _authority_barrier = self
            .project_transaction_owner_authority_barrier
            .lock()
            .map_err(|_| {
                "Project window authority barrier was poisoned; restart Syndocal".to_string()
            })?;
        if self
            .project_transaction_owner_retirement_failure_overflow
            .load(Ordering::Acquire)
        {
            return Err(
                "Project window authority failure registry is full; restart Syndocal".to_string(),
            );
        }
        let failures = self
            .project_transaction_owner_retirement_failures
            .lock()
            .map_err(|_| {
                "Project window authority failure registry lock was poisoned; restart Syndocal"
                    .to_string()
            })?;
        if failures.contains(window_label) {
            return Err(format!(
                "Project window '{window_label}' is permanently blocked after failed authority retirement; restart Syndocal"
            ));
        }
        let retiring = self
            .project_transaction_owner_retiring
            .lock()
            .map_err(|_| {
                "Project window authority retirement registry was poisoned; restart Syndocal"
                    .to_string()
            })?;
        if retiring.contains(window_label) {
            return Err(format!(
                "Project window '{window_label}' authority retirement is in progress; retry from the current window"
            ));
        }
        Ok(())
    }

    fn begin_window_authority_retirement(&self, window_label: &str) -> Result<(), String> {
        validate_project_transaction_window_label(window_label)?;
        let _authority_barrier = self
            .project_transaction_owner_authority_barrier
            .lock()
            .map_err(|_| {
                "Project window authority barrier was poisoned; restart Syndocal".to_string()
            })?;
        if self
            .project_transaction_owner_retirement_failure_overflow
            .load(Ordering::Acquire)
        {
            return Err(
                "Project window authority failure registry is full; restart Syndocal".to_string(),
            );
        }
        let failures = self
            .project_transaction_owner_retirement_failures
            .lock()
            .map_err(|_| {
                "Project window authority failure registry lock was poisoned; restart Syndocal"
                    .to_string()
            })?;
        if failures.contains(window_label) {
            return Err(format!(
                "Project window '{window_label}' is permanently blocked after failed authority retirement; restart Syndocal"
            ));
        }
        let mut retiring = self
            .project_transaction_owner_retiring
            .lock()
            .map_err(|_| {
                "Project window authority retirement registry was poisoned; restart Syndocal"
                    .to_string()
            })?;
        if retiring.contains(window_label) {
            return Err(format!(
                "Project window '{window_label}' authority retirement is already in progress"
            ));
        }
        if failures.len().saturating_add(retiring.len())
            >= MAX_PROJECT_TRANSACTION_OWNER_RETIREMENT_FAILURES
        {
            self.project_transaction_owner_retirement_failure_overflow
                .store(true, Ordering::Release);
            return Err(
                "Project window authority failure registry is full; restart Syndocal".to_string(),
            );
        }
        retiring.insert(window_label.to_string());
        Ok(())
    }

    fn complete_window_authority_retirement(&self, window_label: &str) -> Result<(), String> {
        validate_project_transaction_window_label(window_label)?;
        let _authority_barrier = self
            .project_transaction_owner_authority_barrier
            .lock()
            .map_err(|_| {
                "Project window authority barrier was poisoned; restart Syndocal".to_string()
            })?;
        self.project_transaction_owner_retiring
            .lock()
            .map_err(|_| {
                "Project window authority retirement registry was poisoned; restart Syndocal"
                    .to_string()
            })?
            .remove(window_label);
        Ok(())
    }

    fn record_window_authority_retirement_failure(&self, window_label: &str) -> Result<(), String> {
        validate_project_transaction_window_label(window_label)?;
        let _authority_barrier = self
            .project_transaction_owner_authority_barrier
            .lock()
            .map_err(|_| {
                "Project window authority barrier was poisoned; restart Syndocal".to_string()
            })?;
        if self
            .project_transaction_owner_retirement_failure_overflow
            .load(Ordering::Acquire)
        {
            return Err(
                "Project window authority failure registry is full; restart Syndocal".to_string(),
            );
        }
        let mut failures = self
            .project_transaction_owner_retirement_failures
            .lock()
            .map_err(|_| {
                "Project window authority failure registry lock was poisoned; restart Syndocal"
                    .to_string()
            })?;
        if !failures.contains(window_label)
            && failures.len() >= MAX_PROJECT_TRANSACTION_OWNER_RETIREMENT_FAILURES
        {
            self.project_transaction_owner_retirement_failure_overflow
                .store(true, Ordering::Release);
            return Err(
                "Project window authority failure registry is full; restart Syndocal".to_string(),
            );
        }
        failures.insert(window_label.to_string());
        drop(failures);
        // Promotion is one critical section with installation: callers can
        // observe either the temporary retirement fence or its permanent
        // successor, never an unguarded interval between them.
        self.project_transaction_owner_retiring
            .lock()
            .map_err(|_| {
                "Project window authority retirement registry was poisoned; restart Syndocal"
                    .to_string()
            })?
            .remove(window_label);
        Ok(())
    }

    #[cfg(test)]
    fn blocked_window_authority_count(&self) -> Result<usize, String> {
        self.project_transaction_owner_retirement_failures
            .lock()
            .map(|failures| failures.len())
            .map_err(|_| {
                "Project window authority failure registry lock was poisoned; restart Syndocal"
                    .to_string()
            })
    }

    fn output_lease_now_ms(&self) -> Result<u64, String> {
        let elapsed = Instant::now()
            .checked_duration_since(self.output_lease_clock_origin)
            .ok_or_else(|| "Output lease monotonic clock moved backwards".to_string())?;
        u64::try_from(elapsed.as_millis())
            .map_err(|_| "Output lease monotonic clock exceeded u64 milliseconds".to_string())
    }

    #[cfg(test)]
    fn output_lease_registry_snapshot(&self) -> Result<OutputLeaseRegistrySnapshot, String> {
        let registry = self
            .output_lease_registry
            .lock()
            .map_err(|_| "Output lease registry lock was poisoned".to_string())?;
        let views = registry.lease_views();
        let mut snapshot = OutputLeaseRegistrySnapshot {
            process_incarnation: registry.process_session_incarnation(),
            active_count: 0,
            orphan_count: 0,
            unclaimed_count: 0,
            max_generation: 0,
            audit_sequence: registry.audit().back().map_or(0, |record| record.sequence),
            generation_stamp: 0,
        };
        for view in views {
            snapshot.max_generation = snapshot.max_generation.max(view.snapshot.generation);
            match view.snapshot.phase {
                OutputLeasePhase::HeldActive => snapshot.active_count += 1,
                OutputLeasePhase::HeldOrphaned => snapshot.orphan_count += 1,
                OutputLeasePhase::Unclaimed => snapshot.unclaimed_count += 1,
            }
        }
        snapshot.generation_stamp = snapshot.max_generation.max(snapshot.audit_sequence);
        Ok(snapshot)
    }
}

/// Cancelable -> Admitted | Cancelled linearization for one media operation.
///
/// A media commit and a cancel can arrive concurrently. This single atomic is
/// the only agreement point between them: `try_admit` (taken immediately before
/// the engine publish) and `try_cancel` (taken by the cancel IPC) both CAS the
/// same word, so at most one wins. Once admitted, cancel can never win, so a
/// `cancel == true` result and an engine-publish-success can never coexist. The
/// separate `cancel` `AtomicBool` remains the cooperative stop flag read by the
/// hashing loop; it is set only *after* a winning `try_cancel`.
const MEDIA_ASSET_OP_CANCELABLE: u8 = 0;
const MEDIA_ASSET_OP_ADMITTED: u8 = 1;
const MEDIA_ASSET_OP_CANCELLED: u8 = 2;

/// The outcome of a commit's admission attempt. `Admitted` is returned to the
/// single caller that won the Cancelable -> Admitted transition; every later
/// caller that observes an already-admitted operation gets `AlreadyAdmitted`.
/// Terminal commits publish only on `Admitted`, so a concurrent duplicate that
/// slips past the receipt check can never publish twice or overwrite a receipt.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MediaAssetCommitAdmission {
    Admitted,
    AlreadyAdmitted,
}

#[derive(Debug)]
struct MediaAssetOperationAdmission {
    state: AtomicU8,
}

impl MediaAssetOperationAdmission {
    fn new() -> Self {
        Self {
            state: AtomicU8::new(MEDIA_ASSET_OP_CANCELABLE),
        }
    }

    fn is_cancelled(&self) -> bool {
        self.state.load(Ordering::Acquire) == MEDIA_ASSET_OP_CANCELLED
    }

    fn is_admitted(&self) -> bool {
        self.state.load(Ordering::Acquire) == MEDIA_ASSET_OP_ADMITTED
    }

    /// Win cancellation iff the operation has not been admitted. Idempotent: a
    /// second cancel of an already-cancelled operation still reports `true`.
    fn try_cancel(&self) -> bool {
        loop {
            match self.state.compare_exchange_weak(
                MEDIA_ASSET_OP_CANCELABLE,
                MEDIA_ASSET_OP_CANCELLED,
                Ordering::AcqRel,
                Ordering::Acquire,
            ) {
                Ok(_) => return true,
                Err(MEDIA_ASSET_OP_CANCELLED) => return true,
                Err(MEDIA_ASSET_OP_ADMITTED) => return false,
                // Spurious weak failure while still Cancelable; retry.
                Err(_) => continue,
            }
        }
    }

    /// Admit iff the operation has not been cancelled, distinguishing the single
    /// caller that won the Cancelable -> Admitted CAS (`Admitted`, the one and
    /// only publisher) from any later caller that finds the operation already
    /// admitted (`AlreadyAdmitted`, an exact retry or a concurrent duplicate).
    /// A commit publishes only on `Admitted`; `AlreadyAdmitted` never re-enters
    /// the engine, so a lost ACK retry or a duplicate that slipped past the
    /// receipt check cannot publish a second layer/import.
    fn try_admit(&self) -> Result<MediaAssetCommitAdmission, ()> {
        loop {
            match self.state.compare_exchange_weak(
                MEDIA_ASSET_OP_CANCELABLE,
                MEDIA_ASSET_OP_ADMITTED,
                Ordering::AcqRel,
                Ordering::Acquire,
            ) {
                Ok(_) => return Ok(MediaAssetCommitAdmission::Admitted),
                Err(MEDIA_ASSET_OP_ADMITTED) => {
                    return Ok(MediaAssetCommitAdmission::AlreadyAdmitted)
                }
                Err(MEDIA_ASSET_OP_CANCELLED) => return Err(()),
                Err(_) => continue,
            }
        }
    }
}

/// Which terminal commit a receipt belongs to. Included in the receipt key so a
/// retry that reuses an exact identity for a different command shape can never
/// receive a mismatched payload type.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum MediaAssetCommitReceiptKind {
    Import,
    Relink,
    Layers,
    Bootstrap,
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct MediaAssetCommitReceiptKey {
    kind: MediaAssetCommitReceiptKind,
    prepared_token: u64,
    request_id: u64,
    operation_generation: u64,
    project_transaction_id: u64,
    owner_id: String,
}

/// The definitive result of a terminal commit, retained so a lost engine ACK
/// reply plus an exact retry returns the same value without republishing.
#[derive(Debug, Clone)]
enum MediaAssetCommitReceipt {
    Import(MediaAssetImportReport),
    Relink(MediaAssetRelinkReport),
    Layers(Vec<VideoLayerId>),
    Bootstrap(VjFirstRunSetupResult),
}

/// Backend-owned media commits use an operation-stable identity which never
/// contains a renderer project-transaction ticket. The exact Start authority
/// is part of the key, so a reply retry cannot accidentally bind the prepared
/// bytes to a later same-owner project image.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
struct MediaAssetAuthoritativeOperationKey {
    prepared_token: u64,
    request_id: u64,
    operation_generation: u64,
    owner_id: String,
    start_epoch: u64,
    start_revision: u64,
    start_checkpoint_hash: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize)]
#[serde(rename_all = "snake_case")]
enum MediaAssetAuthoritativeCommitKind {
    Import,
    Relink,
    VideoFileLayer,
    StillImageLayer,
    LocalMediaLayers,
    BootstrapVjShow,
}

/// The operation identity answers "which prepared bytes?" while this shape
/// answers "what should those bytes do?". Keeping both prevents a retry which
/// changes a label/kind/policy from receiving a typed result for a different
/// semantic request. A shape conflict never publishes and the canonical
/// terminal result remains available through the query command.
#[derive(Debug, Clone, PartialEq, Eq)]
struct MediaAssetAuthoritativeRequestShape {
    kind: MediaAssetAuthoritativeCommitKind,
    fingerprint: String,
}

#[derive(Debug, Clone, Serialize)]
struct MediaAssetAuthoritativeLayerResult {
    layer_ids: Vec<VideoLayerId>,
    mutation: ProjectHistoryMutationResult,
}

#[derive(Debug, Clone, Serialize)]
struct MediaAssetAuthoritativeBootstrapResult {
    setup: VjFirstRunSetupResult,
    mutation: ProjectHistoryMutationResult,
}

#[derive(Debug, Clone, Serialize)]
struct MediaAssetAuthoritativeRelinkResult {
    report: MediaAssetRelinkReport,
    mutation: ProjectHistoryMutationResult,
}

#[derive(Debug, Clone, Serialize)]
struct MediaAssetAuthoritativeFailureResult {
    message: String,
}

/// One generic terminal payload is retained for exact retry/query. Command
/// wrappers down-cast only after the operation lane has returned the canonical
/// result, so a receipt can never be mistaken for another command family.
#[derive(Debug, Clone, Serialize)]
#[serde(tag = "kind", content = "result", rename_all = "snake_case")]
enum MediaAssetAuthoritativeTerminalResult {
    Import(MediaAssetAuthoritativeImportResult),
    Relink(MediaAssetAuthoritativeRelinkResult),
    Layers(MediaAssetAuthoritativeLayerResult),
    Bootstrap(MediaAssetAuthoritativeBootstrapResult),
    Failure(MediaAssetAuthoritativeFailureResult),
}

/// Clip-slot operations do not have an expensive Prepare phase, but they still
/// need the same exact reply-recovery identity as Media T1.  The optional
/// prepared token is zero for ordinary slot authoring/runtime commands and is
/// the finalized Media T1 generation only for direct import-and-assign.
