fn clear_transient_video_effect_catalog_kind(kind: &mut VideoEffectKind) {
    let VideoEffectKind::Isf { effect } = kind;
    for control in &mut effect.controls {
        if control.kind == VideoIsfControlKind::Event {
            control.value = [0.0; 4];
        }
    }
    for stage in &mut effect.stack {
        for control in &mut stage.controls {
            if control.kind == VideoIsfControlKind::Event {
                control.value = [0.0; 4];
            }
        }
    }
}

fn project_legacy_video_isf_from_catalog_chain(
    chain: &VideoEffectChainSummary,
) -> Result<Option<VideoIsfEffectSummary>, String> {
    if chain.stages.is_empty() {
        return Ok(None);
    }
    let mut projected = Vec::with_capacity(chain.stages.len());
    for stage in &chain.stages {
        let VideoEffectKind::Isf { effect } = &stage.effect.kind;
        let mut effect = effect.clone();
        effect.enabled = !chain.bypassed && stage.enabled;
        effect.stack.clear();
        projected.push(effect);
    }
    let mut root = projected.remove(0);
    root.stack = projected
        .into_iter()
        .map(|effect| VideoIsfEffectStageSummary {
            enabled: effect.enabled,
            label: effect.label,
            source: effect.source,
            source_path: effect.source_path,
            description: effect.description,
            categories: effect.categories,
            controls: effect.controls,
        })
        .collect();
    Ok(Some(root))
}

fn reconcile_catalog_clip_overrides(
    layer: &mut protocol::VideoLayerSummary,
    layer_chain: Option<&VideoEffectChainSummary>,
) {
    let Some(layer_chain) = layer_chain else {
        for slot in &mut layer.clip_slots {
            slot.effect_overrides.clear();
        }
        return;
    };
    for slot in &mut layer.clip_slots {
        slot.effect_overrides.retain_mut(|effect_override| {
            if let Some(effect_id) = effect_override.effect_id {
                let Some(stage_index) = layer_chain
                    .stages
                    .iter()
                    .position(|stage| stage.effect.id == effect_id)
                else {
                    return false;
                };
                effect_override.stage_index = stage_index;
                true
            } else if let Some(stage) = layer_chain.stages.get(effect_override.stage_index) {
                effect_override.effect_id = Some(stage.effect.id);
                true
            } else {
                // Preserve an invalid legacy positional reference so the
                // engine-ready validator rejects it rather than silently
                // retargeting an authored override.
                true
            }
        });
    }
}

/// `0` is a transport-only "allocate for me" sentinel for C1 catalog
/// creation.  All issued identities remain engine-owned: the caller can only
/// retain an ID that was already present in the exact authored A snapshot it
/// fenced with E/R/H.  This keeps a stale/new caller from minting an arbitrary
/// stable identity while still making retry receipts return the one allocation
/// performed inside their terminal lane.
fn normalize_video_effect_catalog_ids_with_allocator<FC, FS, FE, FP, FG, FB>(
    authored_video: &protocol::VideoSnapshot,
    request: &VideoEffectCatalogApplyRequest,
    allocators: (FC, FS, FE, FP, FG, FB),
) -> Result<VideoEffectCatalogApplyRequest, String>
where
    FC: FnMut() -> Result<protocol::VideoEffectChainId, String>,
    FS: FnMut() -> Result<protocol::VideoEffectStageId, String>,
    FE: FnMut() -> Result<protocol::VideoEffectId, String>,
    FP: FnMut() -> Result<protocol::VideoEffectPresetId, String>,
    FG: FnMut() -> Result<protocol::VideoLayerGroupId, String>,
    FB: FnMut() -> Result<protocol::VideoTransitionBusId, String>,
{
    let (
        mut allocate_chain,
        mut allocate_stage,
        mut allocate_effect,
        mut allocate_preset,
        mut allocate_group,
        mut allocate_bus,
    ) = allocators;
    let known_chains = authored_video
        .effect_chains
        .iter()
        .map(|chain| chain.id.0)
        .collect::<HashSet<_>>();
    let known_stages = authored_video
        .effect_chains
        .iter()
        .flat_map(|chain| chain.stages.iter().map(|stage| stage.id.0))
        .collect::<HashSet<_>>();
    let known_effects = authored_video
        .effect_chains
        .iter()
        .flat_map(|chain| chain.stages.iter().map(|stage| stage.effect.id.0))
        .collect::<HashSet<_>>();
    let known_presets = authored_video
        .effect_presets
        .iter()
        .map(|preset| preset.id.0)
        .collect::<HashSet<_>>();
    let known_groups = authored_video
        .layer_groups
        .iter()
        .map(|group| group.id.0)
        .collect::<HashSet<_>>();
    let known_buses = authored_video
        .transition_buses
        .iter()
        .map(|bus| bus.id.0)
        .collect::<HashSet<_>>();
    let mut normalized = request.clone();

    macro_rules! retain_or_allocate {
        ($id:expr, $known:expr, $allocate:expr, $domain:literal) => {
            if $id.0 == 0 {
                $id = $allocate()?;
            } else if !$known.contains(&$id.0) {
                return Err(format!(
                    "Video effect catalog may only update an existing {} ID {}; use ID 0 for a new entity",
                    $domain, $id.0
                ));
            }
        };
    }

    // Resolve groups first because Group-scoped chains may use the same zero
    // sentinel to refer to their single newly-created group. Multiple zero
    // groups are legal (each gets a distinct monotonic ID), but a zero scope
    // reference would then be ambiguous and is rejected rather than guessed.
    let zero_group_count = normalized
        .layer_groups
        .iter()
        .filter(|group| group.id.0 == 0)
        .count();
    let mut single_zero_group_id = None;
    for group in &mut normalized.layer_groups {
        let was_zero = group.id.0 == 0;
        retain_or_allocate!(group.id, known_groups, allocate_group, "layer group");
        if was_zero {
            single_zero_group_id = Some(group.id);
        }
    }

    let zero_bus_count = normalized
        .transition_buses
        .iter()
        .filter(|bus| bus.id.0 == 0)
        .count();
    let mut single_zero_bus_id = None;
    for bus in &mut normalized.transition_buses {
        let was_zero = bus.id.0 == 0;
        retain_or_allocate!(bus.id, known_buses, allocate_bus, "transition bus");
        if was_zero {
            single_zero_bus_id = Some(bus.id);
        }
    }

    for chain in &mut normalized.effect_chains {
        retain_or_allocate!(chain.id, known_chains, allocate_chain, "chain");
        if let VideoEffectScope::Group { group_id } = &mut chain.scope {
            if group_id.0 == 0 {
                *group_id = match (zero_group_count, single_zero_group_id) {
                    (1, Some(group_id)) => group_id,
                    _ => {
                        return Err(
                            "A Group-scoped effect chain needs exactly one zero-ID layer group in the same catalog"
                                .to_string(),
                        )
                    }
                };
            } else if !known_groups.contains(&group_id.0) {
                return Err(format!(
                    "Video effect catalog may only target an existing layer group ID {}; use one zero-ID group in this catalog for a new target",
                    group_id.0
                ));
            }
        }
        if let VideoEffectScope::Transition {
            owner: protocol::VideoTransitionEffectOwner::LayerBus { bus_id },
        } = &mut chain.scope
        {
            if bus_id.0 == 0 {
                *bus_id = match (zero_bus_count, single_zero_bus_id) {
                    (1, Some(bus_id)) => bus_id,
                    _ => return Err(
                        "A LayerBus-scoped effect chain needs exactly one zero-ID transition bus in the same catalog"
                            .to_string(),
                    ),
                };
            } else if !known_buses.contains(&bus_id.0) {
                return Err(format!(
                    "Video effect catalog may only target an existing transition bus ID {}; use one zero-ID bus in this catalog for a new target",
                    bus_id.0
                ));
            }
        }
        for stage in &mut chain.stages {
            retain_or_allocate!(stage.id, known_stages, allocate_stage, "stage");
            retain_or_allocate!(stage.effect.id, known_effects, allocate_effect, "effect");
        }
    }
    for preset in &mut normalized.effect_presets {
        retain_or_allocate!(preset.id, known_presets, allocate_preset, "preset");
    }
    Ok(normalized)
}

/// The only production allocator source for catalog IDs. It runs after the
/// C1 E/R/H check and inside the operation's terminal single-flight closure,
/// so lost-reply recovery cannot allocate a second set and legacy adapters use
/// exactly the same monotonic domains as the public catalog IPC.
fn normalize_video_effect_catalog_ids(
    state: &AppState,
    before_snapshot: &EngineSnapshot,
    request: &VideoEffectCatalogApplyRequest,
) -> Result<VideoEffectCatalogApplyRequest, String> {
    let authored_video = before_snapshot
        .authored_video
        .as_ref()
        .unwrap_or(&before_snapshot.video);
    normalize_video_effect_catalog_ids_with_allocator(
        authored_video,
        request,
        (
            || Ok(state.engine.allocate_video_effect_chain_id()),
            || Ok(state.engine.allocate_video_effect_stage_id()),
            || Ok(state.engine.allocate_video_effect_id()),
            || Ok(state.engine.allocate_video_effect_preset_id()),
            || Ok(state.engine.allocate_video_layer_group_id()),
            || Ok(state.engine.allocate_video_transition_bus_id()),
        ),
    )
}

/// Reconstruct the persistence candidate from central C1 tables only. This is
/// intentionally the same projection/override seam as the engine: the
/// renderer's active video snapshot must never become the basis for history B.
fn video_effect_catalog_candidate_snapshot(
    mut snapshot: EngineSnapshot,
    request: &VideoEffectCatalogApplyRequest,
) -> Result<EngineSnapshot, String> {
    // Begin strictly from canonical authored persistence, never renderer
    // state. The EngineHandle Published command atomically mirrors that
    // canonical C1 projection into its active `video` image, so B must carry
    // the same completed projection in both fields.
    let mut authored_video = snapshot
        .authored_video
        .clone()
        .unwrap_or_else(|| snapshot.video.clone());
    authored_video.effect_chains = request.effect_chains.clone();
    authored_video.effect_presets = request.effect_presets.clone();
    authored_video.layer_groups = request.layer_groups.clone();
    authored_video.transition_buses = request.transition_buses.clone();

    // Event is pulse-only runtime state. Strip it before both the candidate
    // hash/history image and the one EngineHandle Published request so no
    // Event=1 survives a save/retry boundary.
    for chain in &mut authored_video.effect_chains {
        for stage in &mut chain.stages {
            clear_transient_video_effect_catalog_kind(&mut stage.effect.kind);
        }
    }
    for preset in &mut authored_video.effect_presets {
        for stage in &mut preset.payload.stages {
            clear_transient_video_effect_catalog_kind(&mut stage.effect);
        }
    }
    let layer_chains = authored_video.effect_chains.clone();
    for layer in &mut authored_video.layers {
        let layer_chain = layer_chains
            .iter()
            .find(|chain| chain.scope == VideoEffectScope::Layer { layer_id: layer.id })
            .cloned();
        layer.isf_effect = match layer_chain.as_ref() {
            Some(chain) => project_legacy_video_isf_from_catalog_chain(chain)?,
            None => None,
        };
        reconcile_catalog_clip_overrides(layer, layer_chain.as_ref());
    }
    validate_engine_ready_video_effect_chains(&authored_video)?;
    snapshot.video = authored_video.clone();
    snapshot.authored_video = Some(authored_video);
    Ok(snapshot)
}

fn timeline_advanced_authoring_from_snapshot(
    timeline: &protocol::TimelineSnapshot,
) -> TimelineAdvancedAuthoringSummary {
    TimelineAdvancedAuthoringSummary {
        layers: Some(timeline.layers.clone()),
        snap_request: None,
        video_clips: timeline.video_clips.clone(),
        audio_clips: timeline.audio_clips.clone(),
        phases: timeline.phases.clone(),
        item_groups: timeline.item_groups.clone(),
        loop_region: timeline.loop_region.clone(),
        follow: timeline.follow.clone(),
        guide_enabled: timeline.guide_enabled,
    }
}

fn timeline_shift_ms(value: u64, delta_ms: i64) -> Result<u64, String> {
    if delta_ms >= 0 {
        value
            .checked_add(delta_ms as u64)
            .ok_or_else(|| "Timeline group move exceeds the supported time range".to_string())
    } else {
        value
            .checked_sub(delta_ms.unsigned_abs())
            .ok_or_else(|| "Timeline group move would place an item before time zero".to_string())
    }
}

fn timeline_shift_beats(
    value: Option<f64>,
    delta_ms: i64,
    bpm: f32,
) -> Result<Option<f64>, String> {
    let Some(value) = value else {
        return Ok(None);
    };
    if !bpm.is_finite() || bpm <= 0.0 {
        return Err("Timeline BPM must be finite and positive".to_string());
    }
    let shifted = value + delta_ms as f64 * f64::from(bpm) / 60_000.0;
    if !shifted.is_finite() || shifted < 0.0 {
        return Err("Timeline beat position would fall outside the supported range".to_string());
    }
    Ok(Some(shifted))
}

fn expanded_timeline_items(
    timeline: &TimelineSnapshot,
    requested_items: &[TimelineItemRef],
) -> Result<BTreeSet<TimelineItemRef>, String> {
    if requested_items.is_empty() {
        return Err("Select at least one Timeline item".to_string());
    }
    let mut expanded = requested_items.iter().copied().collect::<BTreeSet<_>>();
    loop {
        let before = expanded.len();
        for group in &timeline.item_groups {
            if group.members.iter().any(|member| expanded.contains(member)) {
                expanded.extend(group.members.iter().copied());
            }
        }
        if expanded.len() == before {
            break;
        }
    }
    for item in &expanded {
        let exists = match item {
            TimelineItemRef::LightingEvent { event_id } => {
                timeline.events.iter().any(|event| event.id == *event_id)
            }
            TimelineItemRef::VideoClip { clip_id } => {
                timeline.video_clips.iter().any(|clip| clip.id == *clip_id)
            }
            TimelineItemRef::AudioClip { clip_id } => {
                timeline.audio_clips.iter().any(|clip| clip.id == *clip_id)
            }
            TimelineItemRef::LightingAutomation { automation_id } => timeline
                .automations
                .iter()
                .any(|automation| automation.id == *automation_id),
            TimelineItemRef::VideoAutomation { automation_id } => timeline
                .video_automations
                .iter()
                .any(|automation| automation.id == *automation_id),
        };
        if !exists {
            return Err("A selected Timeline item no longer exists; refresh and retry".to_string());
        }
    }
    Ok(expanded)
}

fn clone_timeline_items_with_delta(
    state: &AppState,
    timeline: &mut TimelineSnapshot,
    requested_items: &[TimelineItemRef],
    delta_ms: i64,
    bpm: f32,
) -> Result<Vec<TimelineItemRef>, String> {
    let expanded = expanded_timeline_items(timeline, requested_items)?;
    for item in &expanded {
        match item {
            TimelineItemRef::LightingEvent { event_id } => {
                let event = timeline
                    .events
                    .iter()
                    .find(|event| event.id == *event_id)
                    .unwrap();
                timeline_shift_ms(event.time_ms, delta_ms)?;
                timeline_shift_beats(event.time_beats, delta_ms, bpm)?;
            }
            TimelineItemRef::VideoClip { clip_id } => {
                let clip = timeline
                    .video_clips
                    .iter()
                    .find(|clip| clip.id == *clip_id)
                    .unwrap();
                timeline_shift_ms(clip.start_ms, delta_ms)?;
            }
            TimelineItemRef::AudioClip { clip_id } => {
                let clip = timeline
                    .audio_clips
                    .iter()
                    .find(|clip| clip.id == *clip_id)
                    .unwrap();
                timeline_shift_ms(clip.start_ms, delta_ms)?;
            }
            TimelineItemRef::LightingAutomation { automation_id } => {
                let automation = timeline
                    .automations
                    .iter()
                    .find(|automation| automation.id == *automation_id)
                    .unwrap();
                for keyframe in &automation.keyframes {
                    timeline_shift_ms(keyframe.time_ms, delta_ms)?;
                }
            }
            TimelineItemRef::VideoAutomation { automation_id } => {
                let automation = timeline
                    .video_automations
                    .iter()
                    .find(|automation| automation.id == *automation_id)
                    .unwrap();
                for keyframe in &automation.keyframes {
                    timeline_shift_ms(keyframe.time_ms, delta_ms)?;
                }
            }
        }
    }

    let duplicate_refs = expanded
        .iter()
        .map(|item| {
            let duplicate = match item {
                TimelineItemRef::LightingEvent { .. } => TimelineItemRef::LightingEvent {
                    event_id: state.engine.allocate_timeline_event_id(),
                },
                TimelineItemRef::VideoClip { .. } => TimelineItemRef::VideoClip {
                    clip_id: state.engine.allocate_timeline_video_clip_id(),
                },
                TimelineItemRef::AudioClip { .. } => TimelineItemRef::AudioClip {
                    clip_id: state.engine.allocate_timeline_audio_clip_id(),
                },
                TimelineItemRef::LightingAutomation { .. } => TimelineItemRef::LightingAutomation {
                    automation_id: state.engine.allocate_automation_id(),
                },
                TimelineItemRef::VideoAutomation { .. } => TimelineItemRef::VideoAutomation {
                    automation_id: state.engine.allocate_automation_id(),
                },
            };
            (*item, duplicate)
        })
        .collect::<BTreeMap<_, _>>();

    for item in &expanded {
        let duplicate = duplicate_refs[item];
        match (*item, duplicate) {
            (
                TimelineItemRef::LightingEvent { event_id },
                TimelineItemRef::LightingEvent {
                    event_id: duplicate_id,
                },
            ) => {
                let mut event = timeline
                    .events
                    .iter()
                    .find(|event| event.id == event_id)
                    .cloned()
                    .unwrap();
                event.id = duplicate_id;
                event.time_ms = timeline_shift_ms(event.time_ms, delta_ms).unwrap();
                event.time_beats = timeline_shift_beats(event.time_beats, delta_ms, bpm)?;
                if let Some(target_id) = event.jump_to_event_id {
                    if let Some(TimelineItemRef::LightingEvent {
                        event_id: duplicate_target_id,
                    }) = duplicate_refs.get(&TimelineItemRef::LightingEvent {
                        event_id: target_id,
                    }) {
                        event.jump_to_event_id = Some(*duplicate_target_id);
                    }
                }
                timeline.events.push(event);
            }
            (
                TimelineItemRef::VideoClip { clip_id },
                TimelineItemRef::VideoClip {
                    clip_id: duplicate_id,
                },
            ) => {
                let mut clip = timeline
                    .video_clips
                    .iter()
                    .find(|clip| clip.id == clip_id)
                    .cloned()
                    .unwrap();
                clip.id = duplicate_id;
                clip.start_ms = timeline_shift_ms(clip.start_ms, delta_ms).unwrap();
                timeline.video_clips.push(clip);
            }
            (
                TimelineItemRef::AudioClip { clip_id },
                TimelineItemRef::AudioClip {
                    clip_id: duplicate_id,
                },
            ) => {
                let mut clip = timeline
                    .audio_clips
                    .iter()
                    .find(|clip| clip.id == clip_id)
                    .cloned()
                    .unwrap();
                clip.id = duplicate_id;
                clip.start_ms = timeline_shift_ms(clip.start_ms, delta_ms).unwrap();
                timeline.audio_clips.push(clip);
            }
            (
                TimelineItemRef::LightingAutomation { automation_id },
                TimelineItemRef::LightingAutomation {
                    automation_id: duplicate_id,
                },
            ) => {
                let mut automation = timeline
                    .automations
                    .iter()
                    .find(|automation| automation.id == automation_id)
                    .cloned()
                    .unwrap();
                automation.id = duplicate_id;
                for keyframe in &mut automation.keyframes {
                    keyframe.time_ms = timeline_shift_ms(keyframe.time_ms, delta_ms).unwrap();
                }
                timeline.automations.push(automation);
            }
            (
                TimelineItemRef::VideoAutomation { automation_id },
                TimelineItemRef::VideoAutomation {
                    automation_id: duplicate_id,
                },
            ) => {
                let mut automation = timeline
                    .video_automations
                    .iter()
                    .find(|automation| automation.id == automation_id)
                    .cloned()
                    .unwrap();
                automation.id = duplicate_id;
                for keyframe in &mut automation.keyframes {
                    keyframe.time_ms = timeline_shift_ms(keyframe.time_ms, delta_ms).unwrap();
                }
                timeline.video_automations.push(automation);
            }
            _ => return Err("Timeline duplicate identity domains diverged".to_string()),
        }
    }
    let source_groups = timeline
        .item_groups
        .iter()
        .filter(|group| group.members.iter().any(|member| expanded.contains(member)))
        .cloned()
        .collect::<Vec<_>>();
    for group in source_groups {
        timeline.item_groups.push(TimelineItemGroupSummary {
            id: state.engine.allocate_timeline_item_group_id(),
            members: group
                .members
                .iter()
                .map(|member| duplicate_refs[member])
                .collect(),
        });
    }
    Ok(expanded.iter().map(|item| duplicate_refs[item]).collect())
}

fn duplicate_timeline_items(
    state: &AppState,
    timeline: &mut TimelineSnapshot,
    requested_items: &[TimelineItemRef],
    offset_ms: u64,
    bpm: f32,
) -> Result<Vec<TimelineItemRef>, String> {
    if offset_ms == 0 {
        return Err("Timeline duplicate offset must be greater than zero".to_string());
    }
    let delta_ms = i64::try_from(offset_ms)
        .map_err(|_| "Timeline duplicate offset exceeds the supported time range".to_string())?;
    clone_timeline_items_with_delta(state, timeline, requested_items, delta_ms, bpm)
}

fn nudge_timeline_items(
    timeline: &mut TimelineSnapshot,
    requested_items: &[TimelineItemRef],
    delta_ms: i64,
    bpm: f32,
) -> Result<Vec<TimelineItemRef>, String> {
    if delta_ms == 0 {
        return Err("Timeline nudge amount must not be zero".to_string());
    }
    let expanded = expanded_timeline_items(timeline, requested_items)?;
    nudge_timeline_item_set(timeline, &expanded, delta_ms, bpm)?;
    Ok(expanded.into_iter().collect())
}

fn nudge_timeline_item_set(
    timeline: &mut TimelineSnapshot,
    items: &BTreeSet<TimelineItemRef>,
    delta_ms: i64,
    bpm: f32,
) -> Result<(), String> {
    for item in items {
        match item {
            TimelineItemRef::LightingEvent { event_id } => {
                let event = timeline
                    .events
                    .iter()
                    .find(|event| event.id == *event_id)
                    .unwrap();
                timeline_shift_ms(event.time_ms, delta_ms)?;
                timeline_shift_beats(event.time_beats, delta_ms, bpm)?;
            }
            TimelineItemRef::VideoClip { clip_id } => {
                let clip = timeline
                    .video_clips
                    .iter()
                    .find(|clip| clip.id == *clip_id)
                    .unwrap();
                timeline_shift_ms(clip.start_ms, delta_ms)?;
            }
            TimelineItemRef::AudioClip { clip_id } => {
                let clip = timeline
                    .audio_clips
                    .iter()
                    .find(|clip| clip.id == *clip_id)
                    .unwrap();
                timeline_shift_ms(clip.start_ms, delta_ms)?;
            }
            TimelineItemRef::LightingAutomation { automation_id } => {
                let automation = timeline
                    .automations
                    .iter()
                    .find(|automation| automation.id == *automation_id)
                    .unwrap();
                for keyframe in &automation.keyframes {
                    timeline_shift_ms(keyframe.time_ms, delta_ms)?;
                }
            }
            TimelineItemRef::VideoAutomation { automation_id } => {
                let automation = timeline
                    .video_automations
                    .iter()
                    .find(|automation| automation.id == *automation_id)
                    .unwrap();
                for keyframe in &automation.keyframes {
                    timeline_shift_ms(keyframe.time_ms, delta_ms)?;
                }
            }
        }
    }
    for item in items {
        match item {
            TimelineItemRef::LightingEvent { event_id } => {
                let event = timeline
                    .events
                    .iter_mut()
                    .find(|event| event.id == *event_id)
                    .unwrap();
                event.time_ms = timeline_shift_ms(event.time_ms, delta_ms)?;
                event.time_beats = timeline_shift_beats(event.time_beats, delta_ms, bpm)?;
            }
            TimelineItemRef::VideoClip { clip_id } => {
                let clip = timeline
                    .video_clips
                    .iter_mut()
                    .find(|clip| clip.id == *clip_id)
                    .unwrap();
                clip.start_ms = timeline_shift_ms(clip.start_ms, delta_ms)?;
            }
            TimelineItemRef::AudioClip { clip_id } => {
                let clip = timeline
                    .audio_clips
                    .iter_mut()
                    .find(|clip| clip.id == *clip_id)
                    .unwrap();
                clip.start_ms = timeline_shift_ms(clip.start_ms, delta_ms)?;
            }
            TimelineItemRef::LightingAutomation { automation_id } => {
                let automation = timeline
                    .automations
                    .iter_mut()
                    .find(|automation| automation.id == *automation_id)
                    .unwrap();
                for keyframe in &mut automation.keyframes {
                    keyframe.time_ms = timeline_shift_ms(keyframe.time_ms, delta_ms)?;
                }
            }
            TimelineItemRef::VideoAutomation { automation_id } => {
                let automation = timeline
                    .video_automations
                    .iter_mut()
                    .find(|automation| automation.id == *automation_id)
                    .unwrap();
                for keyframe in &mut automation.keyframes {
                    keyframe.time_ms = timeline_shift_ms(keyframe.time_ms, delta_ms)?;
                }
            }
        }
    }
    Ok(())
}

fn timeline_items_temporal_anchor_ms(
    timeline: &TimelineSnapshot,
    items: &BTreeSet<TimelineItemRef>,
) -> Result<u64, String> {
    items
        .iter()
        .filter_map(|item| match item {
            TimelineItemRef::LightingEvent { event_id } => timeline
                .events
                .iter()
                .find(|event| event.id == *event_id)
                .map(|event| event.time_ms),
            TimelineItemRef::VideoClip { clip_id } => timeline
                .video_clips
                .iter()
                .find(|clip| clip.id == *clip_id)
                .map(|clip| clip.start_ms),
            TimelineItemRef::AudioClip { clip_id } => timeline
                .audio_clips
                .iter()
                .find(|clip| clip.id == *clip_id)
                .map(|clip| clip.start_ms),
            TimelineItemRef::LightingAutomation { automation_id } => timeline
                .automations
                .iter()
                .find(|automation| automation.id == *automation_id)
                .and_then(|automation| {
                    automation
                        .keyframes
                        .iter()
                        .map(|keyframe| keyframe.time_ms)
                        .min()
                }),
            TimelineItemRef::VideoAutomation { automation_id } => timeline
                .video_automations
                .iter()
                .find(|automation| automation.id == *automation_id)
                .and_then(|automation| {
                    automation
                        .keyframes
                        .iter()
                        .map(|keyframe| keyframe.time_ms)
                        .min()
                }),
        })
        .min()
        .ok_or_else(|| "Selected Timeline items have no temporal anchor".to_string())
}

fn ripple_timeline_items(
    timeline: &mut TimelineSnapshot,
    requested_items: &[TimelineItemRef],
    delta_ms: i64,
    bpm: f32,
) -> Result<Vec<TimelineItemRef>, String> {
    if delta_ms == 0 {
        return Err("Timeline ripple amount must not be zero".to_string());
    }
    let selected = expanded_timeline_items(timeline, requested_items)?;
    let boundary_ms = timeline_items_temporal_anchor_ms(timeline, &selected)?;
    let mut ripple_items = selected.clone();
    ripple_items.extend(timeline.events.iter().filter_map(|event| {
        (event.time_ms >= boundary_ms)
            .then_some(TimelineItemRef::LightingEvent { event_id: event.id })
    }));
    ripple_items.extend(timeline.video_clips.iter().filter_map(|clip| {
        (clip.start_ms >= boundary_ms).then_some(TimelineItemRef::VideoClip { clip_id: clip.id })
    }));
    ripple_items.extend(timeline.audio_clips.iter().filter_map(|clip| {
        (clip.start_ms >= boundary_ms).then_some(TimelineItemRef::AudioClip { clip_id: clip.id })
    }));
    ripple_items.extend(timeline.automations.iter().filter_map(|automation| {
        automation
            .keyframes
            .iter()
            .map(|keyframe| keyframe.time_ms)
            .min()
            .filter(|anchor_ms| *anchor_ms >= boundary_ms)
            .map(|_| TimelineItemRef::LightingAutomation {
                automation_id: automation.id,
            })
    }));
    ripple_items.extend(timeline.video_automations.iter().filter_map(|automation| {
        automation
            .keyframes
            .iter()
            .map(|keyframe| keyframe.time_ms)
            .min()
            .filter(|anchor_ms| *anchor_ms >= boundary_ms)
            .map(|_| TimelineItemRef::VideoAutomation {
                automation_id: automation.id,
            })
    }));
    let ripple_items = ripple_items.into_iter().collect::<Vec<_>>();
    nudge_timeline_items(timeline, &ripple_items, delta_ms, bpm)?;
    Ok(selected.into_iter().collect())
}

fn quantize_timeline_items(
    timeline: &mut TimelineSnapshot,
    requested_items: &[TimelineItemRef],
    grid_ms: u64,
    bpm: f32,
) -> Result<Vec<TimelineItemRef>, String> {
    if grid_ms == 0 {
        return Err("Timeline quantize grid must be greater than zero".to_string());
    }
    let expanded = expanded_timeline_items(timeline, requested_items)?;
    let anchor_ms = timeline_items_temporal_anchor_ms(timeline, &expanded)?;
    let lower_ms = (anchor_ms / grid_ms) * grid_ms;
    let remainder_ms = anchor_ms % grid_ms;
    let target_ms = if remainder_ms >= grid_ms - remainder_ms {
        lower_ms.checked_add(grid_ms).ok_or_else(|| {
            "Timeline quantize target exceeds the supported time range".to_string()
        })?
    } else {
        lower_ms
    };
    if target_ms == anchor_ms {
        return Ok(expanded.into_iter().collect());
    }
    let delta_ms = i128::from(target_ms) - i128::from(anchor_ms);
    let delta_ms = i64::try_from(delta_ms)
        .map_err(|_| "Timeline quantize shift exceeds the supported time range".to_string())?;
    nudge_timeline_items(timeline, requested_items, delta_ms, bpm)
}

fn paste_timeline_items(
    state: &AppState,
    timeline: &mut TimelineSnapshot,
    requested_items: &[TimelineItemRef],
    target_ms: u64,
    bpm: f32,
) -> Result<Vec<TimelineItemRef>, String> {
    let expanded = expanded_timeline_items(timeline, requested_items)?;
    let anchor_ms = timeline_items_temporal_anchor_ms(timeline, &expanded)?;
    let delta_ms = i128::from(target_ms) - i128::from(anchor_ms);
    let delta_ms = i64::try_from(delta_ms)
        .map_err(|_| "Timeline paste shift exceeds the supported time range".to_string())?;
    clone_timeline_items_with_delta(state, timeline, requested_items, delta_ms, bpm)
}

fn timeline_trimmed_fades(
    duration_ms: u64,
    fade_in_ms: u64,
    fade_out_ms: u64,
    edge: TimelineTrimEdge,
) -> (u64, u64) {
    if fade_in_ms.saturating_add(fade_out_ms) <= duration_ms {
        return (fade_in_ms, fade_out_ms);
    }
    match edge {
        TimelineTrimEdge::Start => {
            let fade_out_ms = fade_out_ms.min(duration_ms);
            (fade_in_ms.min(duration_ms - fade_out_ms), fade_out_ms)
        }
        TimelineTrimEdge::End => {
            let fade_in_ms = fade_in_ms.min(duration_ms);
            (fade_in_ms, fade_out_ms.min(duration_ms - fade_in_ms))
        }
    }
}

fn timeline_item_is_on_locked_layer(
    timeline: &TimelineSnapshot,
    item: TimelineItemRef,
) -> Result<bool, String> {
    let layer_id = match item {
        TimelineItemRef::LightingEvent { event_id } => timeline
            .events
            .iter()
            .find(|event| event.id == event_id)
            .and_then(|event| {
                event.layer_id.or_else(|| {
                    let kind = TimelineLayerKind::from(&event.track);
                    timeline
                        .layers
                        .iter()
                        .find(|layer| layer.kind == kind)
                        .map(|layer| layer.id)
                })
            }),
        TimelineItemRef::VideoClip { clip_id } => timeline
            .video_clips
            .iter()
            .find(|clip| clip.id == clip_id)
            .map(|clip| clip.layer_id),
        TimelineItemRef::AudioClip { clip_id } => timeline
            .audio_clips
            .iter()
            .find(|clip| clip.id == clip_id)
            .map(|clip| clip.layer_id),
        TimelineItemRef::LightingAutomation { automation_id } => {
            let automation = timeline
                .automations
                .iter()
                .find(|automation| automation.id == automation_id)
                .ok_or_else(|| format!("Timeline automation {automation_id} was not found"))?;
            let expected_kind = TimelineLayerKind::Lighting;
            let layer_id =
                match automation.timeline_layer_id {
                    Some(layer_id) => layer_id,
                    // Legacy persistence intentionally stores no authored lanes.
                    // Its `None` automation lane resolves to implicit Lighting=0,
                    // which is necessarily unlocked and must not materialize A.
                    None if timeline.layers.is_empty() => return Ok(false),
                    None => timeline_first_lane_id_of_kind(timeline, expected_kind).ok_or_else(
                        || format!("Timeline automation {automation_id} requires a Lighting lane"),
                    )?,
                };
            let layer = timeline.layers.iter().find(|layer| layer.id == layer_id).ok_or_else(|| {
                format!(
                    "Timeline automation {automation_id} references missing Timeline lane {layer_id}"
                )
            })?;
            if layer.kind != expected_kind {
                return Err(format!(
                    "Timeline automation {automation_id} references incompatible Timeline lane {layer_id}"
                ));
            }
            return Ok(layer.locked);
        }
        TimelineItemRef::VideoAutomation { automation_id } => {
            let automation = timeline
                .video_automations
                .iter()
                .find(|automation| automation.id == automation_id)
                .ok_or_else(|| {
                    format!("Timeline Video automation {automation_id} was not found")
                })?;
            let expected_kind = TimelineLayerKind::Video;
            let layer_id = match automation.timeline_layer_id {
                Some(layer_id) => layer_id,
                // As above, the historical `None` value is implicit Video=1,
                // unlocked, and remains absent from persisted A/B.
                None if timeline.layers.is_empty() => return Ok(false),
                None => {
                    timeline_first_lane_id_of_kind(timeline, expected_kind).ok_or_else(|| {
                        format!("Timeline Video automation {automation_id} requires a Video lane")
                    })?
                }
            };
            let layer = timeline.layers.iter().find(|layer| layer.id == layer_id).ok_or_else(|| {
                format!(
                    "Timeline Video automation {automation_id} references missing Timeline lane {layer_id}"
                )
            })?;
            if layer.kind != expected_kind {
                return Err(format!(
                    "Timeline Video automation {automation_id} references incompatible Timeline lane {layer_id}"
                ));
            }
            return Ok(layer.locked);
        }
    };
    Ok(layer_id.is_some_and(|layer_id| {
        timeline
            .layers
            .iter()
            .find(|layer| layer.id == layer_id)
            .is_some_and(|layer| layer.locked)
    }))
}

fn timeline_first_lane_id_of_kind(
    timeline: &TimelineSnapshot,
    kind: TimelineLayerKind,
) -> Option<u32> {
    timeline
        .layers
        .iter()
        .filter(|layer| layer.kind == kind)
        .min_by_key(|layer| (layer.order, layer.id))
        .map(|layer| layer.id)
}

/// Materialize only the active candidate's historical implicit lanes before a
/// lane-addressed move.  Legacy persistence deliberately keeps `layers`
/// empty, while the UI and engine expose Lighting=0 and Video=1.  An authored
/// audio clip supplies its own derived Audio lane as the engine does.  The
/// caller works on a clone, so a failed preflight leaves the legacy A image
/// byte-for-byte untouched.
fn materialize_legacy_timeline_layers_for_lane_move(
    timeline: &mut TimelineSnapshot,
) -> Result<(), String> {
    if !timeline.layers.is_empty() {
        return Ok(());
    }

    let mut layers = vec![
        protocol::TimelineLayerSummary {
            id: 0,
            label: "Lighting".to_string(),
            order: 0,
            muted: false,
            locked: false,
            solo: false,
            expanded: false,
            kind: TimelineLayerKind::Lighting,
        },
        protocol::TimelineLayerSummary {
            id: 1,
            label: "Video".to_string(),
            order: 1,
            muted: false,
            locked: false,
            solo: false,
            expanded: false,
            kind: TimelineLayerKind::Video,
        },
    ];
    let audio_lane_ids = timeline
        .audio_clips
        .iter()
        .map(|clip| clip.layer_id)
        .collect::<BTreeSet<_>>();
    for layer_id in audio_lane_ids {
        if matches!(layer_id, 0 | 1) {
            return Err(format!(
                "Legacy Timeline Audio clip lane {layer_id} collides with implicit Lighting or Video"
            ));
        }
        layers.push(protocol::TimelineLayerSummary {
            id: layer_id,
            label: "Audio".to_string(),
            order: 0,
            muted: false,
            locked: false,
            solo: false,
            expanded: false,
            kind: TimelineLayerKind::Audio,
        });
    }
    layers.sort_by_key(|layer| (layer.kind.display_section_rank(), layer.order, layer.id));
    for (index, layer) in layers.iter_mut().enumerate() {
        layer.order = u32::try_from(index)
            .map_err(|_| "Timeline has too many lanes to materialize".to_string())?;
    }
    for event in &mut timeline.events {
        if event.layer_id.is_none() {
            event.layer_id = Some(match event.track {
                TimelineTrackKind::Lighting => 0,
                TimelineTrackKind::Video => 1,
            });
        }
    }
    timeline.layers = layers;
    Ok(())
}

fn timeline_reorder_item_source_lane(
    timeline: &TimelineSnapshot,
    item: TimelineItemRef,
) -> Result<(u32, TimelineLayerKind), String> {
    let (source_layer_id, required_kind) = match item {
        TimelineItemRef::LightingEvent { event_id } => {
            let event = timeline
                .events
                .iter()
                .find(|event| event.id == event_id)
                .ok_or_else(|| format!("Timeline event {event_id} was not found"))?;
            (
                event.layer_id.or_else(|| {
                    timeline_first_lane_id_of_kind(timeline, TimelineLayerKind::from(&event.track))
                }),
                None,
            )
        }
        TimelineItemRef::VideoClip { clip_id } => {
            let clip = timeline
                .video_clips
                .iter()
                .find(|clip| clip.id == clip_id)
                .ok_or_else(|| format!("Timeline Video clip {} was not found", clip_id.0))?;
            (Some(clip.layer_id), Some(TimelineLayerKind::Video))
        }
        TimelineItemRef::AudioClip { clip_id } => {
            let clip = timeline
                .audio_clips
                .iter()
                .find(|clip| clip.id == clip_id)
                .ok_or_else(|| format!("Timeline Audio clip {clip_id} was not found"))?;
            (Some(clip.layer_id), Some(TimelineLayerKind::Audio))
        }
        TimelineItemRef::LightingAutomation { automation_id } => {
            let automation = timeline
                .automations
                .iter()
                .find(|automation| automation.id == automation_id)
                .ok_or_else(|| format!("Timeline automation {automation_id} was not found"))?;
            (
                automation.timeline_layer_id.or_else(|| {
                    timeline_first_lane_id_of_kind(timeline, TimelineLayerKind::Lighting)
                }),
                Some(TimelineLayerKind::Lighting),
            )
        }
        TimelineItemRef::VideoAutomation { automation_id } => {
            let automation = timeline
                .video_automations
                .iter()
                .find(|automation| automation.id == automation_id)
                .ok_or_else(|| {
                    format!("Timeline Video automation {automation_id} was not found")
                })?;
            (
                automation
                    .timeline_layer_id
                    .or_else(|| timeline_first_lane_id_of_kind(timeline, TimelineLayerKind::Video)),
                Some(TimelineLayerKind::Video),
            )
        }
    };
    let source_layer_id = source_layer_id.ok_or_else(|| {
        "Timeline item has no compatible source lane; refresh and retry".to_string()
    })?;
    let source = timeline
        .layers
        .iter()
        .find(|layer| layer.id == source_layer_id)
        .ok_or_else(|| format!("Timeline source lane {source_layer_id} was not found"))?;
    if required_kind.is_some_and(|required_kind| source.kind != required_kind) {
        return Err(format!(
            "Timeline source lane {source_layer_id} is incompatible with the selected item"
        ));
    }
    if matches!(item, TimelineItemRef::LightingEvent { .. })
        && source.kind == TimelineLayerKind::Audio
    {
        return Err("Timeline Scene events cannot be moved from an Audio lane".to_string());
    }
    Ok((source_layer_id, source.kind))
}

fn move_timeline_items_to_lanes(
    timeline: &mut TimelineSnapshot,
    requested_items: &[TimelineItemRef],
    primary: TimelineItemRef,
    lane_targets: &[TimelineItemLaneTarget],
    delta_ms: i64,
    isolate: bool,
    bpm: f32,
) -> Result<Vec<TimelineItemRef>, String> {
    let mut candidate = timeline.clone();
    materialize_legacy_timeline_layers_for_lane_move(&mut candidate)?;
    let expanded = expanded_timeline_items(&candidate, requested_items)?;
    if !expanded.contains(&primary) {
        return Err("Timeline lane reorder primary item is outside the selected group".to_string());
    }
    let edited = if isolate {
        BTreeSet::from([primary])
    } else {
        expanded
    };
    let mut target_by_item = BTreeMap::new();
    for target in lane_targets {
        if !edited.contains(&target.item) {
            return Err("Timeline lane targets contain an unselected item".to_string());
        }
        if target_by_item
            .insert(target.item, target.target_layer_id)
            .is_some()
        {
            return Err("Timeline lane targets contain a duplicate item".to_string());
        }
    }
    if target_by_item.len() != edited.len() {
        return Err(
            "Timeline lane targets must contain every edited item exactly once".to_string(),
        );
    }
    let mut sources = BTreeMap::new();
    for item in &edited {
        let (source_layer_id, expected_kind) =
            timeline_reorder_item_source_lane(&candidate, *item)?;
        let target_layer_id = target_by_item[item];
        let target = candidate
            .layers
            .iter()
            .find(|layer| layer.id == target_layer_id)
            .ok_or_else(|| format!("Timeline target lane {target_layer_id} was not found"))?;
        let target_is_compatible = match item {
            TimelineItemRef::LightingEvent { .. } => {
                matches!(
                    target.kind,
                    TimelineLayerKind::Lighting | TimelineLayerKind::Video
                )
            }
            _ => target.kind == expected_kind,
        };
        if !target_is_compatible {
            return Err("Timeline target lane is incompatible with the selected item".to_string());
        }
        if target.locked {
            return Err("Timeline lane move cannot target a locked lane".to_string());
        }
        let source = candidate
            .layers
            .iter()
            .find(|layer| layer.id == source_layer_id)
            .expect("validated Timeline source lane exists");
        if source.locked {
            return Err("Timeline lane move cannot move an item from a locked lane".to_string());
        }
        sources.insert(*item, source_layer_id);
    }
    if delta_ms == 0
        && sources
            .iter()
            .all(|(item, source_layer_id)| *source_layer_id == target_by_item[item])
    {
        return Err("Timeline lane move target is already selected".to_string());
    }

    if delta_ms != 0 {
        nudge_timeline_item_set(&mut candidate, &edited, delta_ms, bpm)?;
    }
    for item in &edited {
        let target_layer_id = target_by_item[item];
        match *item {
            TimelineItemRef::LightingEvent { event_id } => {
                let target_kind = candidate
                    .layers
                    .iter()
                    .find(|layer| layer.id == target_layer_id)
                    .expect("validated Scene target lane exists")
                    .kind;
                let event = candidate
                    .events
                    .iter_mut()
                    .find(|event| event.id == event_id)
                    .expect("validated Timeline event exists");
                event.layer_id = Some(target_layer_id);
                event.track = match target_kind {
                    TimelineLayerKind::Lighting => TimelineTrackKind::Lighting,
                    TimelineLayerKind::Video => TimelineTrackKind::Video,
                    TimelineLayerKind::Audio => {
                        unreachable!("preflight rejects Audio Scene lane targets")
                    }
                };
            }
            TimelineItemRef::VideoClip { clip_id } => {
                candidate
                    .video_clips
                    .iter_mut()
                    .find(|clip| clip.id == clip_id)
                    .expect("validated Timeline Video clip exists")
                    .layer_id = target_layer_id;
            }
            TimelineItemRef::AudioClip { clip_id } => {
                candidate
                    .audio_clips
                    .iter_mut()
                    .find(|clip| clip.id == clip_id)
                    .expect("validated Timeline Audio clip exists")
                    .layer_id = target_layer_id;
            }
            TimelineItemRef::LightingAutomation { automation_id } => {
                candidate
                    .automations
                    .iter_mut()
                    .find(|automation| automation.id == automation_id)
                    .expect("validated Timeline automation exists")
                    .timeline_layer_id = Some(target_layer_id);
            }
            TimelineItemRef::VideoAutomation { automation_id } => {
                candidate
                    .video_automations
                    .iter_mut()
                    .find(|automation| automation.id == automation_id)
                    .expect("validated Timeline Video automation exists")
                    .timeline_layer_id = Some(target_layer_id);
            }
        }
    }
    *timeline = candidate;
    Ok(edited.into_iter().collect())
}

fn timeline_event_presented_end_ms(
    event: &protocol::TimelineCueEventSummary,
) -> Result<u64, String> {
    let span_ms = if event.conform_to_tempo {
        event.duration_ms
    } else {
        event
            .duration_ms
            .checked_mul(u64::from(event.loop_count))
            .ok_or_else(|| "Scene Block span exceeds the supported time range".to_string())?
    };
    event
        .time_ms
        .checked_add(span_ms)
        .ok_or_else(|| "Scene Block end exceeds the supported time range".to_string())
}

fn timeline_item_edge_ms(
    timeline: &TimelineSnapshot,
    item: TimelineItemRef,
    edge: TimelineTrimEdge,
) -> Result<u64, String> {
    let bounds = match item {
        TimelineItemRef::LightingEvent { event_id } => {
            let event = timeline
                .events
                .iter()
                .find(|event| event.id == event_id)
                .ok_or_else(|| format!("Timeline event {event_id} was not found"))?;
            if event.duration_ms == 0 {
                return Err("Timeline points cannot be trimmed".to_string());
            }
            (event.time_ms, timeline_event_presented_end_ms(event)?)
        }
        TimelineItemRef::VideoClip { clip_id } => {
            let clip = timeline
                .video_clips
                .iter()
                .find(|clip| clip.id == clip_id)
                .ok_or_else(|| format!("Timeline Video clip {} was not found", clip_id.0))?;
            (
                clip.start_ms,
                clip.start_ms.checked_add(clip.duration_ms).ok_or_else(|| {
                    "Timeline Video clip end exceeds the supported time range".to_string()
                })?,
            )
        }
        TimelineItemRef::AudioClip { clip_id } => {
            let clip = timeline
                .audio_clips
                .iter()
                .find(|clip| clip.id == clip_id)
                .ok_or_else(|| format!("Timeline Audio clip {clip_id} was not found"))?;
            (
                clip.start_ms,
                clip.start_ms.checked_add(clip.duration_ms).ok_or_else(|| {
                    "Timeline Audio clip end exceeds the supported time range".to_string()
                })?,
            )
        }
        TimelineItemRef::LightingAutomation { automation_id } => {
            let automation = timeline
                .automations
                .iter()
                .find(|automation| automation.id == automation_id)
                .ok_or_else(|| format!("Timeline automation {automation_id} was not found"))?;
            let start = automation
                .keyframes
                .first()
                .ok_or_else(|| "Timeline automation has no keyframes".to_string())?
                .time_ms;
            let end = automation.keyframes.last().unwrap().time_ms;
            (start, end)
        }
        TimelineItemRef::VideoAutomation { automation_id } => {
            let automation = timeline
                .video_automations
                .iter()
                .find(|automation| automation.id == automation_id)
                .ok_or_else(|| {
                    format!("Timeline Video automation {automation_id} was not found")
                })?;
            let start = automation
                .keyframes
                .first()
                .ok_or_else(|| "Timeline Video automation has no keyframes".to_string())?
                .time_ms;
            let end = automation.keyframes.last().unwrap().time_ms;
            (start, end)
        }
    };
    if bounds.0 >= bounds.1 {
        return Err("Timeline trim requires a non-empty item span".to_string());
    }
    Ok(match edge {
        TimelineTrimEdge::Start => bounds.0,
        TimelineTrimEdge::End => bounds.1,
    })
}

fn timeline_media_duration_ms(
    timeline: &TimelineSnapshot,
    media_assets: &[protocol::MediaAssetSummary],
    media_asset_id: Option<MediaAssetId>,
    legacy_path: Option<&str>,
) -> Option<u64> {
    media_asset_id
        .and_then(|asset_id| media_assets.iter().find(|asset| asset.id == asset_id))
        .and_then(|asset| asset.source.metadata.as_ref())
        .and_then(|metadata| metadata.duration_ms)
        .or_else(|| {
            let path = legacy_path?;
            timeline
                .audio
                .as_ref()
                .filter(|audio| audio.path == path)
                .map(|audio| audio.duration_ms)
        })
}

fn trim_lighting_automation_keyframes(
    keyframes: &[protocol::AutomationKeyframeSummary],
    edge: TimelineTrimEdge,
    boundary_ms: u64,
) -> Result<Vec<protocol::AutomationKeyframeSummary>, String> {
    if keyframes.len() < 2 {
        return Err("Timeline automation trim requires at least two keyframes".to_string());
    }
    if keyframes
        .windows(2)
        .any(|pair| pair[0].time_ms >= pair[1].time_ms)
    {
        return Err("Timeline automation keyframes must be strictly ordered".to_string());
    }
    let first = keyframes.first().unwrap();
    let last = keyframes.last().unwrap();
    if boundary_ms >= last.time_ms && matches!(edge, TimelineTrimEdge::Start)
        || boundary_ms <= first.time_ms && matches!(edge, TimelineTrimEdge::End)
    {
        return Err("Timeline automation trim would remove its complete span".to_string());
    }
    let boundary = if let Some(exact) = keyframes
        .iter()
        .find(|keyframe| keyframe.time_ms == boundary_ms)
    {
        exact.clone()
    } else if boundary_ms < first.time_ms {
        protocol::AutomationKeyframeSummary {
            time_ms: boundary_ms,
            value: first.value,
            interpolation: first.interpolation.clone(),
        }
    } else if boundary_ms > last.time_ms {
        protocol::AutomationKeyframeSummary {
            time_ms: boundary_ms,
            value: last.value,
            interpolation: last.interpolation.clone(),
        }
    } else {
        let pair = keyframes
            .windows(2)
            .find(|pair| pair[0].time_ms < boundary_ms && boundary_ms < pair[1].time_ms)
            .unwrap();
        let value = match pair[0].interpolation {
            protocol::AutomationInterpolation::Step => pair[0].value,
            protocol::AutomationInterpolation::Linear => {
                let numerator = boundary_ms - pair[0].time_ms;
                let denominator = pair[1].time_ms - pair[0].time_ms;
                let ratio = numerator as f64 / denominator as f64;
                (f64::from(pair[0].value)
                    + (f64::from(pair[1].value) - f64::from(pair[0].value)) * ratio)
                    .round()
                    .clamp(0.0, f64::from(u16::MAX)) as u16
            }
            protocol::AutomationInterpolation::Bezier => {
                return Err("Bezier automation must be trimmed on an existing keyframe".to_string())
            }
        };
        protocol::AutomationKeyframeSummary {
            time_ms: boundary_ms,
            value,
            interpolation: pair[0].interpolation.clone(),
        }
    };
    let mut trimmed = match edge {
        TimelineTrimEdge::Start => keyframes
            .iter()
            .filter(|keyframe| keyframe.time_ms >= boundary_ms)
            .cloned()
            .collect::<Vec<_>>(),
        TimelineTrimEdge::End => keyframes
            .iter()
            .filter(|keyframe| keyframe.time_ms <= boundary_ms)
            .cloned()
            .collect::<Vec<_>>(),
    };
    if !trimmed
        .iter()
        .any(|keyframe| keyframe.time_ms == boundary_ms)
    {
        trimmed.push(boundary);
        trimmed.sort_by_key(|keyframe| keyframe.time_ms);
    }
    if trimmed.len() < 2 || trimmed.first().unwrap().time_ms >= trimmed.last().unwrap().time_ms {
        return Err("Timeline automation trim must leave two distinct keyframes".to_string());
    }
    Ok(trimmed)
}

fn trim_video_automation_keyframes(
    keyframes: &[protocol::VideoAutomationKeyframeSummary],
    edge: TimelineTrimEdge,
    boundary_ms: u64,
) -> Result<Vec<protocol::VideoAutomationKeyframeSummary>, String> {
    if keyframes.len() < 2 {
        return Err("Timeline Video automation trim requires at least two keyframes".to_string());
    }
    if keyframes
        .windows(2)
        .any(|pair| pair[0].time_ms >= pair[1].time_ms)
    {
        return Err("Timeline Video automation keyframes must be strictly ordered".to_string());
    }
    let first = keyframes.first().unwrap();
    let last = keyframes.last().unwrap();
    if boundary_ms >= last.time_ms && matches!(edge, TimelineTrimEdge::Start)
        || boundary_ms <= first.time_ms && matches!(edge, TimelineTrimEdge::End)
    {
        return Err("Timeline Video automation trim would remove its complete span".to_string());
    }
    let boundary = if let Some(exact) = keyframes
        .iter()
        .find(|keyframe| keyframe.time_ms == boundary_ms)
    {
        exact.clone()
    } else if boundary_ms < first.time_ms {
        protocol::VideoAutomationKeyframeSummary {
            time_ms: boundary_ms,
            value: first.value,
            interpolation: first.interpolation.clone(),
        }
    } else if boundary_ms > last.time_ms {
        protocol::VideoAutomationKeyframeSummary {
            time_ms: boundary_ms,
            value: last.value,
            interpolation: last.interpolation.clone(),
        }
    } else {
        let pair = keyframes
            .windows(2)
            .find(|pair| pair[0].time_ms < boundary_ms && boundary_ms < pair[1].time_ms)
            .unwrap();
        let value = match pair[0].interpolation {
            protocol::AutomationInterpolation::Step => pair[0].value,
            protocol::AutomationInterpolation::Linear => {
                let numerator = boundary_ms - pair[0].time_ms;
                let denominator = pair[1].time_ms - pair[0].time_ms;
                let ratio = numerator as f64 / denominator as f64;
                pair[0].value + (pair[1].value - pair[0].value) * ratio as f32
            }
            protocol::AutomationInterpolation::Bezier => {
                return Err(
                    "Bezier Video automation must be trimmed on an existing keyframe".to_string(),
                )
            }
        };
        if !value.is_finite() {
            return Err("Timeline Video automation trim produced a non-finite value".to_string());
        }
        protocol::VideoAutomationKeyframeSummary {
            time_ms: boundary_ms,
            value,
            interpolation: pair[0].interpolation.clone(),
        }
    };
    let mut trimmed = match edge {
        TimelineTrimEdge::Start => keyframes
            .iter()
            .filter(|keyframe| keyframe.time_ms >= boundary_ms)
            .cloned()
            .collect::<Vec<_>>(),
        TimelineTrimEdge::End => keyframes
            .iter()
            .filter(|keyframe| keyframe.time_ms <= boundary_ms)
            .cloned()
            .collect::<Vec<_>>(),
    };
    if !trimmed
        .iter()
        .any(|keyframe| keyframe.time_ms == boundary_ms)
    {
        trimmed.push(boundary);
        trimmed.sort_by_key(|keyframe| keyframe.time_ms);
    }
    if trimmed.len() < 2 || trimmed.first().unwrap().time_ms >= trimmed.last().unwrap().time_ms {
        return Err("Timeline Video automation trim must leave two distinct keyframes".to_string());
    }
    Ok(trimmed)
}

fn trim_timeline_items(
    timeline: &mut TimelineSnapshot,
    media_assets: &[protocol::MediaAssetSummary],
    requested_items: &[TimelineItemRef],
    primary: TimelineItemRef,
    edge: TimelineTrimEdge,
    boundary_ms: u64,
    parameters: TimelineItemEditParameters,
) -> Result<Vec<TimelineItemRef>, String> {
    let (isolate, bpm) = parameters;
    if !bpm.is_finite() || bpm <= 0.0 {
        return Err("Timeline BPM must be finite and positive".to_string());
    }
    let expanded = expanded_timeline_items(timeline, requested_items)?;
    if !expanded.contains(&primary) {
        return Err("Timeline trim primary item is outside the selected group".to_string());
    }
    let primary_edge_ms = timeline_item_edge_ms(timeline, primary, edge)?;
    let delta_ms = i128::from(boundary_ms) - i128::from(primary_edge_ms);
    let delta_ms = i64::try_from(delta_ms)
        .map_err(|_| "Timeline trim exceeds the supported time range".to_string())?;
    if delta_ms == 0 {
        return Err("Timeline trim boundary must move".to_string());
    }
    let edited = if isolate {
        BTreeSet::from([primary])
    } else {
        expanded.clone()
    };
    for item in &edited {
        if timeline_item_is_on_locked_layer(timeline, *item)? {
            return Err("Timeline trim cannot edit an item on a locked lane".to_string());
        }
    }

    let mut candidate = timeline.clone();
    for item in &edited {
        let current_edge_ms = timeline_item_edge_ms(&candidate, *item, edge)?;
        let item_boundary_ms = timeline_shift_ms(current_edge_ms, delta_ms)?;
        match *item {
            TimelineItemRef::LightingEvent { event_id } => {
                let event = candidate
                    .events
                    .iter_mut()
                    .find(|event| event.id == event_id)
                    .unwrap();
                let old_end_ms = timeline_event_presented_end_ms(event)?;
                let (new_start_ms, new_end_ms) = match edge {
                    TimelineTrimEdge::Start => (item_boundary_ms, old_end_ms),
                    TimelineTrimEdge::End => (event.time_ms, item_boundary_ms),
                };
                let new_span_ms = new_end_ms
                    .checked_sub(new_start_ms)
                    .filter(|span| *span > 0)
                    .ok_or_else(|| "Scene Block trim would remove its complete span".to_string())?;
                let new_duration_ms = if event.conform_to_tempo {
                    new_span_ms
                } else {
                    let loop_count = u64::from(event.loop_count);
                    if loop_count == 0 || new_span_ms % loop_count != 0 {
                        return Err(
                            "Scene Block trim must preserve an exact whole-loop duration"
                                .to_string(),
                        );
                    }
                    new_span_ms / loop_count
                };
                if matches!(edge, TimelineTrimEdge::Start) {
                    let rate = f64::from(event.rate.unwrap_or(1.0));
                    if !rate.is_finite() || rate <= 0.0 {
                        return Err("Scene Block trim requires a finite positive rate".to_string());
                    }
                    let source_delta = delta_ms as f64 * rate;
                    if !source_delta.is_finite()
                        || source_delta < i64::MIN as f64
                        || source_delta > i64::MAX as f64
                    {
                        return Err(
                            "Scene Block source trim exceeds the supported range".to_string()
                        );
                    }
                    event.source_offset_ms = event
                        .source_offset_ms
                        .checked_add(source_delta.round() as i64)
                        .ok_or_else(|| {
                            "Scene Block source offset exceeds the supported range".to_string()
                        })?;
                    event.time_ms = new_start_ms;
                    event.time_beats = timeline_shift_beats(event.time_beats, delta_ms, bpm)?;
                }
                event.duration_ms = new_duration_ms;
                if event.conform_to_tempo {
                    event.duration_beats = Some(new_duration_ms as f64 * f64::from(bpm) / 60_000.0);
                }
                let fades = timeline_trimmed_fades(
                    new_duration_ms,
                    event.fade_in_ms,
                    event.fade_out_ms,
                    edge,
                );
                event.fade_in_ms = fades.0;
                event.fade_out_ms = fades.1;
            }
            TimelineItemRef::VideoClip { clip_id } => {
                let media_asset_id = candidate
                    .video_clips
                    .iter()
                    .find(|clip| clip.id == clip_id)
                    .unwrap()
                    .media_asset_id;
                let source_duration_ms = timeline_media_duration_ms(
                    &candidate,
                    media_assets,
                    Some(media_asset_id),
                    None,
                );
                let clip = candidate
                    .video_clips
                    .iter_mut()
                    .find(|clip| clip.id == clip_id)
                    .unwrap();
                let old_end_ms = clip.start_ms.checked_add(clip.duration_ms).ok_or_else(|| {
                    "Timeline Video clip end exceeds the supported range".to_string()
                })?;
                match edge {
                    TimelineTrimEdge::Start => {
                        let new_duration_ms = old_end_ms
                            .checked_sub(item_boundary_ms)
                            .filter(|value| *value > 0)
                            .ok_or_else(|| {
                                "Timeline Video trim would remove its complete span".to_string()
                            })?;
                        clip.offset_ms = timeline_shift_ms(clip.offset_ms, delta_ms)?;
                        clip.start_ms = item_boundary_ms;
                        clip.duration_ms = new_duration_ms;
                    }
                    TimelineTrimEdge::End => {
                        clip.duration_ms = item_boundary_ms
                            .checked_sub(clip.start_ms)
                            .filter(|value| *value > 0)
                            .ok_or_else(|| {
                                "Timeline Video trim would remove its complete span".to_string()
                            })?;
                    }
                }
                if let Some(source_duration_ms) = source_duration_ms {
                    if clip
                        .offset_ms
                        .checked_add(clip.duration_ms)
                        .is_none_or(|end| end > source_duration_ms)
                    {
                        return Err("Timeline Video trim exceeds the source duration".to_string());
                    }
                }
                let fades = timeline_trimmed_fades(
                    clip.duration_ms,
                    clip.fade_in_ms,
                    clip.fade_out_ms,
                    edge,
                );
                clip.fade_in_ms = fades.0;
                clip.fade_out_ms = fades.1;
            }
            TimelineItemRef::AudioClip { clip_id } => {
                let (media_asset_id, path) = candidate
                    .audio_clips
                    .iter()
                    .find(|clip| clip.id == clip_id)
                    .map(|clip| (clip.media_asset_id, clip.path.clone()))
                    .unwrap();
                let source_duration_ms = timeline_media_duration_ms(
                    &candidate,
                    media_assets,
                    media_asset_id,
                    Some(&path),
                );
                let clip = candidate
                    .audio_clips
                    .iter_mut()
                    .find(|clip| clip.id == clip_id)
                    .unwrap();
                let old_end_ms = clip.start_ms.checked_add(clip.duration_ms).ok_or_else(|| {
                    "Timeline Audio clip end exceeds the supported range".to_string()
                })?;
                match edge {
                    TimelineTrimEdge::Start => {
                        let new_duration_ms = old_end_ms
                            .checked_sub(item_boundary_ms)
                            .filter(|value| *value > 0)
                            .ok_or_else(|| {
                                "Timeline Audio trim would remove its complete span".to_string()
                            })?;
                        clip.offset_ms = timeline_shift_ms(clip.offset_ms, delta_ms)?;
                        clip.start_ms = item_boundary_ms;
                        clip.duration_ms = new_duration_ms;
                    }
                    TimelineTrimEdge::End => {
                        clip.duration_ms = item_boundary_ms
                            .checked_sub(clip.start_ms)
                            .filter(|value| *value > 0)
                            .ok_or_else(|| {
                                "Timeline Audio trim would remove its complete span".to_string()
                            })?;
                    }
                }
                if let Some(source_duration_ms) = source_duration_ms {
                    if clip
                        .offset_ms
                        .checked_add(clip.duration_ms)
                        .is_none_or(|end| end > source_duration_ms)
                    {
                        return Err("Timeline Audio trim exceeds the source duration".to_string());
                    }
                }
                let fades = timeline_trimmed_fades(
                    clip.duration_ms,
                    clip.fade_in_ms,
                    clip.fade_out_ms,
                    edge,
                );
                clip.fade_in_ms = fades.0;
                clip.fade_out_ms = fades.1;
            }
            TimelineItemRef::LightingAutomation { automation_id } => {
                let automation = candidate
                    .automations
                    .iter_mut()
                    .find(|automation| automation.id == automation_id)
                    .unwrap();
                automation.keyframes = trim_lighting_automation_keyframes(
                    &automation.keyframes,
                    edge,
                    item_boundary_ms,
                )?;
            }
            TimelineItemRef::VideoAutomation { automation_id } => {
                let automation = candidate
                    .video_automations
                    .iter_mut()
                    .find(|automation| automation.id == automation_id)
                    .unwrap();
                automation.keyframes =
                    trim_video_automation_keyframes(&automation.keyframes, edge, item_boundary_ms)?;
            }
        }
    }
    *timeline = candidate;
    Ok(expanded.into_iter().collect())
}

fn split_timeline_scene_event(
    event: &protocol::TimelineCueEventSummary,
    right_event_id: TimelineEventId,
    boundary_ms: u64,
    split_offset_ms: u64,
    bpm: f32,
) -> Result<
    (
        protocol::TimelineCueEventSummary,
        protocol::TimelineCueEventSummary,
    ),
    String,
> {
    // Multi-loop and loop-fill Scene Blocks do not have a source-continuation
    // contract at an arbitrary split boundary. Keep this operation fail-closed
    // instead of guessing which loop/seek state the right half should inherit.
    if event.loop_count != 1 || event.loop_fill {
        return Err(
            "Timeline Split supports only single-span Scene Blocks; loop playback is ambiguous"
                .to_string(),
        );
    }
    let event_end_ms = timeline_event_presented_end_ms(event)?;
    if boundary_ms <= event.time_ms || boundary_ms >= event_end_ms {
        return Err(
            "Timeline Split boundary must be strictly inside every edited item".to_string(),
        );
    }
    let rate = f64::from(event.rate.unwrap_or(1.0));
    if !rate.is_finite() || rate <= 0.0 {
        return Err("Timeline Split requires a finite positive Scene Block rate".to_string());
    }
    let source_delta = split_offset_ms as f64 * rate;
    if !source_delta.is_finite() || source_delta < i64::MIN as f64 || source_delta > i64::MAX as f64
    {
        return Err(
            "Timeline Split Scene Block source offset exceeds the supported range".to_string(),
        );
    }
    let source_delta = source_delta.round() as i64;
    let right_source_offset_ms = event
        .source_offset_ms
        .checked_add(source_delta)
        .ok_or_else(|| {
            "Timeline Split Scene Block source offset exceeds the supported range".to_string()
        })?;
    let right_time_beats = timeline_shift_beats(
        event.time_beats,
        i64::try_from(split_offset_ms)
            .map_err(|_| "Timeline Split exceeds the supported time range".to_string())?,
        bpm,
    )?;
    let right_duration_ms = event_end_ms
        .checked_sub(boundary_ms)
        .filter(|duration_ms| *duration_ms > 0)
        .ok_or_else(|| "Timeline Split would remove the Scene Block right span".to_string())?;
    let ((left_fade_in_ms, left_fade_out_ms), (right_fade_in_ms, right_fade_out_ms)) =
        split_timeline_fade_envelope(
            event.duration_ms,
            event.fade_in_ms,
            event.fade_out_ms,
            split_offset_ms,
        )?;

    let mut left = event.clone();
    left.duration_ms = split_offset_ms;
    if left.conform_to_tempo {
        left.duration_beats = Some(split_offset_ms as f64 * f64::from(bpm) / 60_000.0);
    }
    (left.fade_in_ms, left.fade_out_ms) = (left_fade_in_ms, left_fade_out_ms);

    let mut right = event.clone();
    right.id = right_event_id;
    right.time_ms = boundary_ms;
    right.time_beats = right_time_beats;
    right.source_offset_ms = right_source_offset_ms;
    right.duration_ms = right_duration_ms;
    if right.conform_to_tempo {
        right.duration_beats = Some(right_duration_ms as f64 * f64::from(bpm) / 60_000.0);
    }
    (right.fade_in_ms, right.fade_out_ms) = (right_fade_in_ms, right_fade_out_ms);
    Ok((left, right))
}

fn split_timeline_fade_envelope(
    duration_ms: u64,
    fade_in_ms: u64,
    fade_out_ms: u64,
    split_offset_ms: u64,
) -> Result<TimelineFadeEnvelopeSplit, String> {
    let right_duration_ms = duration_ms
        .checked_sub(split_offset_ms)
        .filter(|duration_ms| *duration_ms > 0)
        .ok_or_else(|| "Timeline Split would remove the item right span".to_string())?;
    if fade_in_ms.saturating_add(fade_out_ms) > duration_ms {
        return Err("Timeline Split item fades exceed its duration".to_string());
    }
    let fade_out_start_ms = duration_ms - fade_out_ms;
    if split_offset_ms < fade_in_ms || split_offset_ms > fade_out_start_ms {
        return Err("Timeline Split cannot cut through an existing fade envelope".to_string());
    }
    Ok((
        (fade_in_ms.min(split_offset_ms), 0),
        (0, fade_out_ms.min(right_duration_ms)),
    ))
}

fn split_timeline_video_clip(
    clip: &TimelineVideoClipSummary,
    right_clip_id: protocol::TimelineVideoClipId,
    boundary_ms: u64,
    split_offset_ms: u64,
) -> Result<(TimelineVideoClipSummary, TimelineVideoClipSummary), String> {
    let end_ms = clip
        .start_ms
        .checked_add(clip.duration_ms)
        .ok_or_else(|| "Timeline Video clip end exceeds the supported time range".to_string())?;
    if boundary_ms <= clip.start_ms || boundary_ms >= end_ms {
        return Err(
            "Timeline Split boundary must be strictly inside every edited item".to_string(),
        );
    }
    let right_duration_ms = end_ms
        .checked_sub(boundary_ms)
        .filter(|duration_ms| *duration_ms > 0)
        .ok_or_else(|| "Timeline Split would remove the Video clip right span".to_string())?;
    let right_offset_ms = clip.offset_ms.checked_add(split_offset_ms).ok_or_else(|| {
        "Timeline Split Video source offset exceeds the supported range".to_string()
    })?;
    let ((left_fade_in_ms, left_fade_out_ms), (right_fade_in_ms, right_fade_out_ms)) =
        split_timeline_fade_envelope(
            clip.duration_ms,
            clip.fade_in_ms,
            clip.fade_out_ms,
            split_offset_ms,
        )?;
    let mut left = clip.clone();
    left.duration_ms = split_offset_ms;
    (left.fade_in_ms, left.fade_out_ms) = (left_fade_in_ms, left_fade_out_ms);
    let mut right = clip.clone();
    right.id = right_clip_id;
    right.start_ms = boundary_ms;
    right.offset_ms = right_offset_ms;
    right.duration_ms = right_duration_ms;
    (right.fade_in_ms, right.fade_out_ms) = (right_fade_in_ms, right_fade_out_ms);
    Ok((left, right))
}

fn split_timeline_audio_clip(
    clip: &TimelineAudioClipSummary,
    right_clip_id: TimelineAudioClipId,
    boundary_ms: u64,
    split_offset_ms: u64,
) -> Result<(TimelineAudioClipSummary, TimelineAudioClipSummary), String> {
    let end_ms = clip
        .start_ms
        .checked_add(clip.duration_ms)
        .ok_or_else(|| "Timeline Audio clip end exceeds the supported time range".to_string())?;
    if boundary_ms <= clip.start_ms || boundary_ms >= end_ms {
        return Err(
            "Timeline Split boundary must be strictly inside every edited item".to_string(),
        );
    }
    let right_duration_ms = end_ms
        .checked_sub(boundary_ms)
        .filter(|duration_ms| *duration_ms > 0)
        .ok_or_else(|| "Timeline Split would remove the Audio clip right span".to_string())?;
    let right_offset_ms = clip.offset_ms.checked_add(split_offset_ms).ok_or_else(|| {
        "Timeline Split Audio source offset exceeds the supported range".to_string()
    })?;
    let ((left_fade_in_ms, left_fade_out_ms), (right_fade_in_ms, right_fade_out_ms)) =
        split_timeline_fade_envelope(
            clip.duration_ms,
            clip.fade_in_ms,
            clip.fade_out_ms,
            split_offset_ms,
        )?;
    let mut left = clip.clone();
    left.duration_ms = split_offset_ms;
    (left.fade_in_ms, left.fade_out_ms) = (left_fade_in_ms, left_fade_out_ms);
    let mut right = clip.clone();
    right.id = right_clip_id;
    right.start_ms = boundary_ms;
    right.offset_ms = right_offset_ms;
    right.duration_ms = right_duration_ms;
    (right.fade_in_ms, right.fade_out_ms) = (right_fade_in_ms, right_fade_out_ms);
    Ok((left, right))
}

fn split_timeline_items(
    state: &AppState,
    timeline: &mut TimelineSnapshot,
    media_assets: &[protocol::MediaAssetSummary],
    requested_items: &[TimelineItemRef],
    primary: TimelineItemRef,
    boundary_ms: u64,
    parameters: TimelineItemEditParameters,
) -> Result<Vec<TimelineItemRef>, String> {
    let (isolate, bpm) = parameters;
    if !bpm.is_finite() || bpm <= 0.0 {
        return Err("Timeline Split requires a finite positive BPM".to_string());
    }
    let expanded = expanded_timeline_items(timeline, requested_items)?;
    if !expanded.contains(&primary) {
        return Err("Timeline Split primary item is outside the selected group".to_string());
    }
    let primary_start_ms = timeline_item_edge_ms(timeline, primary, TimelineTrimEdge::Start)?;
    let primary_end_ms = timeline_item_edge_ms(timeline, primary, TimelineTrimEdge::End)?;
    let split_offset_ms = boundary_ms
        .checked_sub(primary_start_ms)
        .filter(|offset_ms| *offset_ms > 0 && boundary_ms < primary_end_ms)
        .ok_or_else(|| {
            "Timeline Split boundary must be strictly inside the primary item".to_string()
        })?;
    let edited = if isolate {
        BTreeSet::from([primary])
    } else {
        expanded
    };
    let mut item_boundaries = BTreeMap::new();
    for item in &edited {
        if timeline_item_is_on_locked_layer(timeline, *item)? {
            return Err("Timeline Split cannot edit an item on a locked lane".to_string());
        }
        let start_ms = timeline_item_edge_ms(timeline, *item, TimelineTrimEdge::Start)?;
        let end_ms = timeline_item_edge_ms(timeline, *item, TimelineTrimEdge::End)?;
        let item_boundary_ms = start_ms
            .checked_add(split_offset_ms)
            .filter(|boundary_ms| *boundary_ms > start_ms && *boundary_ms < end_ms)
            .ok_or_else(|| {
                "Timeline Split boundary must be strictly inside every edited item".to_string()
            })?;
        item_boundaries.insert(*item, item_boundary_ms);
        match *item {
            TimelineItemRef::LightingEvent { event_id } => {
                let event = timeline
                    .events
                    .iter()
                    .find(|event| event.id == event_id)
                    .expect("expanded Timeline event exists");
                split_timeline_scene_event(
                    event,
                    event_id,
                    item_boundary_ms,
                    split_offset_ms,
                    bpm,
                )?;
            }
            TimelineItemRef::VideoClip { clip_id } => {
                let clip = timeline
                    .video_clips
                    .iter()
                    .find(|clip| clip.id == clip_id)
                    .expect("expanded Timeline Video clip exists");
                split_timeline_video_clip(clip, clip_id, item_boundary_ms, split_offset_ms)?;
                if let Some(source_duration_ms) = timeline_media_duration_ms(
                    timeline,
                    media_assets,
                    Some(clip.media_asset_id),
                    None,
                ) {
                    if clip
                        .offset_ms
                        .checked_add(clip.duration_ms)
                        .is_none_or(|end_ms| end_ms > source_duration_ms)
                    {
                        return Err(
                            "Timeline Split Video clip exceeds the source duration".to_string()
                        );
                    }
                }
            }
            TimelineItemRef::AudioClip { clip_id } => {
                let clip = timeline
                    .audio_clips
                    .iter()
                    .find(|clip| clip.id == clip_id)
                    .expect("expanded Timeline Audio clip exists");
                split_timeline_audio_clip(clip, clip_id, item_boundary_ms, split_offset_ms)?;
                if let Some(source_duration_ms) = timeline_media_duration_ms(
                    timeline,
                    media_assets,
                    clip.media_asset_id,
                    Some(&clip.path),
                ) {
                    if clip
                        .offset_ms
                        .checked_add(clip.duration_ms)
                        .is_none_or(|end_ms| end_ms > source_duration_ms)
                    {
                        return Err(
                            "Timeline Split Audio clip exceeds the source duration".to_string()
                        );
                    }
                }
            }
            TimelineItemRef::LightingAutomation { automation_id } => {
                let automation = timeline
                    .automations
                    .iter()
                    .find(|automation| automation.id == automation_id)
                    .expect("expanded Timeline automation exists");
                trim_lighting_automation_keyframes(
                    &automation.keyframes,
                    TimelineTrimEdge::End,
                    item_boundary_ms,
                )?;
                trim_lighting_automation_keyframes(
                    &automation.keyframes,
                    TimelineTrimEdge::Start,
                    item_boundary_ms,
                )?;
            }
            TimelineItemRef::VideoAutomation { automation_id } => {
                let automation = timeline
                    .video_automations
                    .iter()
                    .find(|automation| automation.id == automation_id)
                    .expect("expanded Timeline Video automation exists");
                trim_video_automation_keyframes(
                    &automation.keyframes,
                    TimelineTrimEdge::End,
                    item_boundary_ms,
                )?;
                trim_video_automation_keyframes(
                    &automation.keyframes,
                    TimelineTrimEdge::Start,
                    item_boundary_ms,
                )?;
            }
        }
    }

    let source_groups = if isolate {
        Vec::new()
    } else {
        timeline
            .item_groups
            .iter()
            .filter(|group| group.members.iter().any(|member| edited.contains(member)))
            .cloned()
            .collect::<Vec<_>>()
    };
    if timeline
        .item_groups
        .len()
        .checked_add(source_groups.len())
        .is_none_or(|count| count > protocol::TIMELINE_MAX_ITEM_GROUPS)
    {
        return Err("Timeline Split would exceed the Timeline item-group limit".to_string());
    }
    if source_groups.iter().any(|group| group.members.len() < 2) {
        return Err("Timeline Split cannot duplicate an invalid Timeline item group".to_string());
    }

    let right_refs = edited
        .iter()
        .map(|item| {
            let right = match item {
                TimelineItemRef::LightingEvent { .. } => TimelineItemRef::LightingEvent {
                    event_id: state.engine.allocate_timeline_event_id(),
                },
                TimelineItemRef::VideoClip { .. } => TimelineItemRef::VideoClip {
                    clip_id: state.engine.allocate_timeline_video_clip_id(),
                },
                TimelineItemRef::AudioClip { .. } => TimelineItemRef::AudioClip {
                    clip_id: state.engine.allocate_timeline_audio_clip_id(),
                },
                TimelineItemRef::LightingAutomation { .. } => TimelineItemRef::LightingAutomation {
                    automation_id: state.engine.allocate_automation_id(),
                },
                TimelineItemRef::VideoAutomation { .. } => TimelineItemRef::VideoAutomation {
                    automation_id: state.engine.allocate_automation_id(),
                },
            };
            (*item, right)
        })
        .collect::<BTreeMap<_, _>>();
    let mut candidate = timeline.clone();
    for item in &edited {
        let item_boundary_ms = item_boundaries[item];
        let right = right_refs[item];
        match (*item, right) {
            (
                TimelineItemRef::LightingEvent { event_id },
                TimelineItemRef::LightingEvent {
                    event_id: right_event_id,
                },
            ) => {
                let event = candidate
                    .events
                    .iter()
                    .find(|event| event.id == event_id)
                    .cloned()
                    .expect("preflighted Timeline event exists");
                let (left, right) = split_timeline_scene_event(
                    &event,
                    right_event_id,
                    item_boundary_ms,
                    split_offset_ms,
                    bpm,
                )?;
                *candidate
                    .events
                    .iter_mut()
                    .find(|event| event.id == event_id)
                    .expect("preflighted Timeline event exists") = left;
                candidate.events.push(right);
            }
            (
                TimelineItemRef::VideoClip { clip_id },
                TimelineItemRef::VideoClip {
                    clip_id: right_clip_id,
                },
            ) => {
                let clip = candidate
                    .video_clips
                    .iter()
                    .find(|clip| clip.id == clip_id)
                    .cloned()
                    .expect("preflighted Timeline Video clip exists");
                let (left, right) = split_timeline_video_clip(
                    &clip,
                    right_clip_id,
                    item_boundary_ms,
                    split_offset_ms,
                )?;
                *candidate
                    .video_clips
                    .iter_mut()
                    .find(|clip| clip.id == clip_id)
                    .expect("preflighted Timeline Video clip exists") = left;
                candidate.video_clips.push(right);
            }
            (
                TimelineItemRef::AudioClip { clip_id },
                TimelineItemRef::AudioClip {
                    clip_id: right_clip_id,
                },
            ) => {
                let clip = candidate
                    .audio_clips
                    .iter()
                    .find(|clip| clip.id == clip_id)
                    .cloned()
                    .expect("preflighted Timeline Audio clip exists");
                let (left, right) = split_timeline_audio_clip(
                    &clip,
                    right_clip_id,
                    item_boundary_ms,
                    split_offset_ms,
                )?;
                *candidate
                    .audio_clips
                    .iter_mut()
                    .find(|clip| clip.id == clip_id)
                    .expect("preflighted Timeline Audio clip exists") = left;
                candidate.audio_clips.push(right);
            }
            (
                TimelineItemRef::LightingAutomation { automation_id },
                TimelineItemRef::LightingAutomation {
                    automation_id: right_automation_id,
                },
            ) => {
                let automation = candidate
                    .automations
                    .iter()
                    .find(|automation| automation.id == automation_id)
                    .cloned()
                    .expect("preflighted Timeline automation exists");
                let left_keyframes = trim_lighting_automation_keyframes(
                    &automation.keyframes,
                    TimelineTrimEdge::End,
                    item_boundary_ms,
                )?;
                let right_keyframes = trim_lighting_automation_keyframes(
                    &automation.keyframes,
                    TimelineTrimEdge::Start,
                    item_boundary_ms,
                )?;
                candidate
                    .automations
                    .iter_mut()
                    .find(|automation| automation.id == automation_id)
                    .expect("preflighted Timeline automation exists")
                    .keyframes = left_keyframes;
                let mut right = automation;
                right.id = right_automation_id;
                right.keyframes = right_keyframes;
                candidate.automations.push(right);
            }
            (
                TimelineItemRef::VideoAutomation { automation_id },
                TimelineItemRef::VideoAutomation {
                    automation_id: right_automation_id,
                },
            ) => {
                let automation = candidate
                    .video_automations
                    .iter()
                    .find(|automation| automation.id == automation_id)
                    .cloned()
                    .expect("preflighted Timeline Video automation exists");
                let left_keyframes = trim_video_automation_keyframes(
                    &automation.keyframes,
                    TimelineTrimEdge::End,
                    item_boundary_ms,
                )?;
                let right_keyframes = trim_video_automation_keyframes(
                    &automation.keyframes,
                    TimelineTrimEdge::Start,
                    item_boundary_ms,
                )?;
                candidate
                    .video_automations
                    .iter_mut()
                    .find(|automation| automation.id == automation_id)
                    .expect("preflighted Timeline Video automation exists")
                    .keyframes = left_keyframes;
                let mut right = automation;
                right.id = right_automation_id;
                right.keyframes = right_keyframes;
                candidate.video_automations.push(right);
            }
            _ => return Err("Timeline Split identity domains diverged".to_string()),
        }
    }
    let jump_rewires = candidate
        .events
        .iter()
        .filter_map(|event| {
            let TimelineItemRef::LightingEvent {
                event_id: right_event_id,
            } = right_refs.get(&TimelineItemRef::LightingEvent { event_id: event.id })?
            else {
                return None;
            };
            let target_id = event.jump_to_event_id?;
            let TimelineItemRef::LightingEvent {
                event_id: right_target_id,
            } = right_refs.get(&TimelineItemRef::LightingEvent {
                event_id: target_id,
            })?
            else {
                return None;
            };
            Some((*right_event_id, *right_target_id))
        })
        .collect::<Vec<_>>();
    for (right_event_id, right_target_id) in jump_rewires {
        candidate
            .events
            .iter_mut()
            .find(|event| event.id == right_event_id)
            .expect("preflighted Timeline Split right event exists")
            .jump_to_event_id = Some(right_target_id);
    }
    for source_group in source_groups {
        let right_members = source_group
            .members
            .iter()
            .map(|member| {
                right_refs
                    .get(member)
                    .copied()
                    .expect("expanded Timeline item group member must be split")
            })
            .collect::<Vec<_>>();
        if right_members.len() >= 2 {
            candidate.item_groups.push(TimelineItemGroupSummary {
                id: state.engine.allocate_timeline_item_group_id(),
                members: right_members,
            });
        }
    }
    *timeline = candidate;
    Ok(edited.into_iter().map(|item| right_refs[&item]).collect())
}

fn delete_timeline_items(
    timeline: &mut TimelineSnapshot,
    requested_items: &[TimelineItemRef],
) -> Result<(), String> {
    let removed = expanded_timeline_items(timeline, requested_items)?;
    let removed_events = removed
        .iter()
        .filter_map(|item| match item {
            TimelineItemRef::LightingEvent { event_id } => Some(*event_id),
            _ => None,
        })
        .collect::<BTreeSet<_>>();
    timeline
        .events
        .retain(|event| !removed.contains(&TimelineItemRef::LightingEvent { event_id: event.id }));
    for event in &mut timeline.events {
        if event
            .jump_to_event_id
            .is_some_and(|event_id| removed_events.contains(&event_id))
        {
            event.jump_to_event_id = None;
        }
    }
    timeline
        .video_clips
        .retain(|clip| !removed.contains(&TimelineItemRef::VideoClip { clip_id: clip.id }));
    timeline
        .audio_clips
        .retain(|clip| !removed.contains(&TimelineItemRef::AudioClip { clip_id: clip.id }));
    timeline.automations.retain(|automation| {
        !removed.contains(&TimelineItemRef::LightingAutomation {
            automation_id: automation.id,
        })
    });
    timeline.video_automations.retain(|automation| {
        !removed.contains(&TimelineItemRef::VideoAutomation {
            automation_id: automation.id,
        })
    });
    timeline
        .item_groups
        .retain(|group| !group.members.iter().any(|member| removed.contains(member)));
    Ok(())
}

fn timeline_advanced_candidate_for_request(
    state: &AppState,
    before: &EngineSnapshot,
    request: &TimelineAdvancedMutationRequest,
) -> Result<TimelineAdvancedAuthoringSummary, String> {
    let mut authoring = timeline_advanced_authoring_from_snapshot(&before.timeline);
    match request {
        TimelineAdvancedMutationRequest::Apply {
            authoring: requested,
        } => {
            authoring = requested.as_ref().clone();
            for phase in &mut authoring.phases {
                if phase.id.0 == 0 {
                    phase.id = state.engine.allocate_timeline_phase_id();
                }
            }
        }
        TimelineAdvancedMutationRequest::InsertMedia {
            media_asset_id,
            start_ms,
            video_layer_id,
            audio_layer_id,
        } => {
            let asset = before
                .video
                .media_assets
                .iter()
                .find(|asset| asset.id == *media_asset_id)
                .ok_or_else(|| format!("MediaAsset {media_asset_id} was not found"))?;
            if !matches!(
                asset.source.kind,
                VideoSourceKind::File | VideoSourceKind::StillImage
            ) {
                return Err(
                    "Only file or still MediaAssets can be placed on a Timeline".to_string()
                );
            }
            let duration_ms = asset
                .source
                .metadata
                .and_then(|metadata| metadata.duration_ms)
                .filter(|duration| *duration > 0)
                .ok_or_else(|| {
                    format!(
                        "MediaAsset {media_asset_id} needs a known non-zero duration before Timeline placement"
                    )
                })?;
            // An explicit lane comes from a drag/drop target and is therefore
            // part of the command's meaning.  Silently substituting another
            // lane when that target is missing, cross-kind, or locked makes a
            // successful receipt disagree with the UI's intended placement.
            // Keep the first-unlocked fallback only for the legacy/accessibility
            // path, where the caller deliberately supplied no lane at all.
            let resolve_layer = |requested: Option<u32>, kind: TimelineLayerKind| match requested {
                Some(id) => {
                    let layer = before
                        .timeline
                        .layers
                        .iter()
                        .find(|layer| layer.id == id)
                        .ok_or_else(|| {
                            format!("Requested {kind:?} Timeline lane {id} was not found")
                        })?;
                    if layer.kind != kind {
                        return Err(format!(
                            "Requested Timeline lane {id} has kind {:?}, expected {kind:?}",
                            layer.kind
                        ));
                    }
                    if layer.locked {
                        return Err(format!("Requested {kind:?} Timeline lane {id} is locked"));
                    }
                    Ok(Some(layer.id))
                }
                None => Ok(before
                    .timeline
                    .layers
                    .iter()
                    .find(|layer| layer.kind == kind && !layer.locked)
                    .map(|layer| layer.id)),
            };
            let has_video = matches!(asset.source.kind, VideoSourceKind::StillImage)
                || asset
                    .source
                    .metadata
                    .is_some_and(|metadata| metadata.width.is_some() && metadata.height.is_some());
            let has_audio = asset
                .source
                .metadata
                .is_some_and(|metadata| metadata.has_audio);
            if !has_video && !has_audio {
                return Err(format!(
                    "MediaAsset {media_asset_id} has neither a video stream nor an audio stream"
                ));
            }
            // An explicit target for a stream that this asset does not carry is
            // still malformed input.  Do not silently discard the target: a
            // caller that named a Video lane for an audio-only asset (or an
            // Audio lane for a video-only asset) must receive a failed receipt
            // with no candidate allocations or publication.
            if !has_video && video_layer_id.is_some() {
                return Err(format!(
                    "MediaAsset {media_asset_id} has no video stream but a Video Timeline lane was requested"
                ));
            }
            if !has_audio && audio_layer_id.is_some() {
                return Err(format!(
                    "MediaAsset {media_asset_id} has no audio stream but an Audio Timeline lane was requested"
                ));
            }
            // Resolve every requested target before allocating any item ID.  A
            // linked AV placement is one authoritative mutation: if either
            // side is invalid, the candidate must fail before allocation or
            // publication can begin.
            let resolved_video_layer_id = if has_video {
                Some(
                    resolve_layer(*video_layer_id, TimelineLayerKind::Video)?
                        .ok_or_else(|| "An unlocked Video Timeline lane is required".to_string())?,
                )
            } else {
                None
            };
            let resolved_audio_layer_id = if has_audio {
                Some(
                    resolve_layer(*audio_layer_id, TimelineLayerKind::Audio)?.ok_or_else(|| {
                        "An unlocked Audio Timeline lane is required for this video's audio"
                            .to_string()
                    })?,
                )
            } else {
                None
            };
            let video_clip_id = if let Some(video_layer_id) = resolved_video_layer_id {
                let video_clip_id = state.engine.allocate_timeline_video_clip_id();
                authoring.video_clips.push(TimelineVideoClipSummary {
                    id: video_clip_id,
                    layer_id: video_layer_id,
                    media_asset_id: *media_asset_id,
                    start_ms: *start_ms,
                    offset_ms: 0,
                    duration_ms,
                    fade_in_ms: 0,
                    fade_out_ms: 0,
                });
                Some(video_clip_id)
            } else {
                None
            };
            if let Some(audio_layer_id) = resolved_audio_layer_id {
                let audio_clip_id = state.engine.allocate_timeline_audio_clip_id();
                authoring.audio_clips.push(TimelineAudioClipSummary {
                    id: audio_clip_id,
                    layer_id: audio_layer_id,
                    media_asset_id: Some(*media_asset_id),
                    path: String::new(),
                    start_ms: *start_ms,
                    offset_ms: 0,
                    duration_ms,
                    gain: 1.0,
                    fade_in_ms: 0,
                    fade_out_ms: 0,
                    output_bus: protocol::TimelineAudioOutputBus::Program,
                });
                if let Some(video_clip_id) = video_clip_id {
                    authoring.item_groups.push(TimelineItemGroupSummary {
                        id: state.engine.allocate_timeline_item_group_id(),
                        members: vec![
                            TimelineItemRef::VideoClip {
                                clip_id: video_clip_id,
                            },
                            TimelineItemRef::AudioClip {
                                clip_id: audio_clip_id,
                            },
                        ],
                    });
                }
            }
        }
        TimelineAdvancedMutationRequest::Group { members } => {
            authoring.item_groups.push(TimelineItemGroupSummary {
                id: state.engine.allocate_timeline_item_group_id(),
                members: members.clone(),
            });
        }
        TimelineAdvancedMutationRequest::Ungroup { group_id } => {
            let previous_len = authoring.item_groups.len();
            authoring.item_groups.retain(|group| group.id != *group_id);
            if authoring.item_groups.len() == previous_len {
                return Err(format!("Timeline item group {} was not found", group_id.0));
            }
        }
        TimelineAdvancedMutationRequest::MoveGroup { group_id, delta_ms } => {
            let group = authoring
                .item_groups
                .iter()
                .find(|group| group.id == *group_id)
                .cloned()
                .ok_or_else(|| format!("Timeline item group {} was not found", group_id.0))?;
            let mut snap = TimelineSnapRequest::default();
            for member in group.members {
                match member {
                    TimelineItemRef::VideoClip { clip_id } => {
                        let clip = authoring
                            .video_clips
                            .iter_mut()
                            .find(|clip| clip.id == clip_id)
                            .ok_or_else(|| "Grouped Video clip was not found".to_string())?;
                        clip.start_ms = timeline_shift_ms(clip.start_ms, *delta_ms)?;
                    }
                    TimelineItemRef::AudioClip { clip_id } => {
                        let clip = authoring
                            .audio_clips
                            .iter_mut()
                            .find(|clip| clip.id == clip_id)
                            .ok_or_else(|| "Grouped Audio clip was not found".to_string())?;
                        clip.start_ms = timeline_shift_ms(clip.start_ms, *delta_ms)?;
                    }
                    TimelineItemRef::LightingEvent { event_id } => {
                        let event = before
                            .timeline
                            .events
                            .iter()
                            .find(|event| event.id == event_id)
                            .ok_or_else(|| "Grouped Scene Block was not found".to_string())?;
                        snap.event_placements
                            .push(protocol::TimelineEventPlacementUpdate {
                                event_id,
                                cue_id: event.cue_id,
                                time_ms: timeline_shift_ms(event.time_ms, *delta_ms)?,
                                time_beats: timeline_shift_beats(
                                    event.time_beats,
                                    *delta_ms,
                                    before.clock.bpm,
                                )?,
                                track: event.track.clone(),
                                layer_id: event.layer_id,
                                duration_ms: event.duration_ms,
                                duration_beats: event.duration_beats,
                                conform_to_tempo: event.conform_to_tempo,
                                loop_fill: event.loop_fill,
                                fade_in_ms: event.fade_in_ms,
                                fade_out_ms: event.fade_out_ms,
                                loop_count: event.loop_count,
                                jump_to_event_id: event.jump_to_event_id,
                            });
                    }
                    TimelineItemRef::LightingAutomation { automation_id } => {
                        let automation = before
                            .timeline
                            .automations
                            .iter()
                            .find(|automation| automation.id == automation_id)
                            .ok_or_else(|| {
                                "Grouped Lighting automation was not found".to_string()
                            })?;
                        let mut keyframes = automation.keyframes.clone();
                        for keyframe in &mut keyframes {
                            keyframe.time_ms = timeline_shift_ms(keyframe.time_ms, *delta_ms)?;
                        }
                        snap.lighting_automations.push(
                            protocol::TimelineAutomationKeyframesUpdate {
                                automation_id,
                                keyframes,
                            },
                        );
                    }
                    TimelineItemRef::VideoAutomation { automation_id } => {
                        let automation = before
                            .timeline
                            .video_automations
                            .iter()
                            .find(|automation| automation.id == automation_id)
                            .ok_or_else(|| "Grouped Video automation was not found".to_string())?;
                        let mut keyframes = automation.keyframes.clone();
                        for keyframe in &mut keyframes {
                            keyframe.time_ms = timeline_shift_ms(keyframe.time_ms, *delta_ms)?;
                        }
                        snap.video_automations.push(
                            protocol::TimelineVideoAutomationKeyframesUpdate {
                                automation_id,
                                keyframes,
                            },
                        );
                    }
                }
            }
            authoring.snap_request = Some(snap);
        }
        TimelineAdvancedMutationRequest::SetPhases { phases } => {
            authoring.phases = phases.clone();
            for phase in &mut authoring.phases {
                if phase.id.0 == 0 {
                    phase.id = state.engine.allocate_timeline_phase_id();
                }
            }
        }
        TimelineAdvancedMutationRequest::SetLoop { loop_region } => {
            authoring.loop_region = loop_region.clone();
        }
        TimelineAdvancedMutationRequest::SetFollow { follow } => {
            authoring.follow = follow.clone();
        }
        TimelineAdvancedMutationRequest::SetGuide { enabled } => {
            authoring.guide_enabled = *enabled;
        }
        TimelineAdvancedMutationRequest::CreateTimeline { .. }
        | TimelineAdvancedMutationRequest::DuplicateTimeline { .. }
        | TimelineAdvancedMutationRequest::RemoveTimeline { .. }
        | TimelineAdvancedMutationRequest::ReorderTimelines { .. }
        | TimelineAdvancedMutationRequest::SelectTimeline { .. }
        | TimelineAdvancedMutationRequest::DuplicateItems { .. }
        | TimelineAdvancedMutationRequest::NudgeItems { .. }
        | TimelineAdvancedMutationRequest::MoveItemsToLanes { .. }
        | TimelineAdvancedMutationRequest::RippleItems { .. }
        | TimelineAdvancedMutationRequest::QuantizeItems { .. }
        | TimelineAdvancedMutationRequest::PasteItems { .. }
        | TimelineAdvancedMutationRequest::TrimItems { .. }
        | TimelineAdvancedMutationRequest::SplitItems { .. }
        | TimelineAdvancedMutationRequest::DeleteItems { .. } => {
            return Err("Timeline bank commands require the bank mutation path".to_string());
        }
    }
    Ok(authoring)
}

fn clear_timeline_bank_runtime(timeline: &mut TimelineSnapshot) {
    timeline.playing = false;
    timeline.position_ms = 0;
    timeline.count_in_remaining_ms = 0;
    timeline.audio_transport_revision = 0;
    timeline.active_child_transports.clear();
    timeline.loop_runtime = Default::default();
    timeline.follow_runtime = Default::default();
    timeline.guide_cues.clear();
}

fn normalize_timeline_duration_for_engine(
    timeline: &mut TimelineSnapshot,
    video: &protocol::VideoSnapshot,
) {
    // Mirror the engine's authored audio projection before authority hashing.
    // Signed copy/paste and nudge operations can move a clip ahead of an
    // earlier entry even though the cloned entry is appended to the vector.
    timeline
        .audio_clips
        .sort_by_key(|clip| (clip.start_ms, clip.layer_id, clip.id));
    let event_duration = timeline
        .events
        .iter()
        .map(|event| {
            let span_ms = if event.conform_to_tempo {
                event.duration_ms
            } else {
                event
                    .duration_ms
                    .saturating_mul(u64::from(event.loop_count))
            };
            event.time_ms.saturating_add(span_ms)
        })
        .max()
        .unwrap_or(0);
    let automation_duration = timeline
        .automations
        .iter()
        .flat_map(|automation| automation.keyframes.iter().map(|keyframe| keyframe.time_ms))
        .max()
        .unwrap_or(0);
    let video_automation_duration = timeline
        .video_automations
        .iter()
        .flat_map(|automation| automation.keyframes.iter().map(|keyframe| keyframe.time_ms))
        .max()
        .unwrap_or(0);
    let audio_duration = timeline
        .audio_clips
        .iter()
        .map(|clip| clip.start_ms.saturating_add(clip.duration_ms))
        .max()
        .unwrap_or_else(|| {
            timeline
                .audio
                .as_ref()
                .map(|audio| audio.duration_ms)
                .unwrap_or(0)
        });
    let video_source_duration = video
        .layers
        .iter()
        .filter_map(|layer| layer.source.metadata.as_ref())
        .filter_map(|metadata| metadata.duration_ms)
        .max()
        .unwrap_or(0);
    let video_clip_duration = timeline
        .video_clips
        .iter()
        .map(|clip| clip.start_ms.saturating_add(clip.duration_ms))
        .max()
        .unwrap_or(0);
    let phase_duration = timeline
        .phases
        .iter()
        .map(|phase| phase.end_ms)
        .max()
        .unwrap_or(0);
    timeline.duration_ms = event_duration
        .max(automation_duration)
        .max(video_automation_duration)
        .max(audio_duration)
        .max(video_source_duration)
        .max(video_clip_duration)
        .max(phase_duration);
}

fn timeline_bank_from_snapshot(before: &EngineSnapshot) -> Vec<TimelineSnapshot> {
    let mut bank = before.timeline_bank.clone();
    if let Some(active) = bank
        .iter_mut()
        .find(|timeline| timeline.id == before.timeline.id)
    {
        *active = before.timeline.clone();
    } else {
        bank.push(before.timeline.clone());
    }
    for timeline in &mut bank {
        clear_timeline_bank_runtime(timeline);
    }
    bank
}

fn restitch_timeline_bank_follow_targets(bank: &mut [TimelineSnapshot]) {
    for index in 0..bank.len() {
        let next_id = bank.get(index + 1).map(|timeline| timeline.id);
        if bank[index]
            .follow
            .as_ref()
            .is_some_and(|follow| follow.enabled)
        {
            if let Some(next_id) = next_id {
                if let Some(follow) = bank[index].follow.as_mut() {
                    follow.next_timeline_id = next_id;
                }
            } else {
                bank[index].follow = None;
            }
        }
    }
}

fn timeline_bank_candidate_for_request(
    state: &AppState,
    before: &EngineSnapshot,
    request: &TimelineAdvancedMutationRequest,
) -> Result<
    (
        Vec<TimelineSnapshot>,
        TimelineId,
        bool,
        Vec<TimelineItemRef>,
    ),
    String,
> {
    let mut bank = timeline_bank_from_snapshot(before);
    let mut active_timeline_id = before.timeline.id;
    let mut play = before.timeline.playing;
    let mut selected_items = Vec::new();
    match request {
        TimelineAdvancedMutationRequest::CreateTimeline { label } => {
            let label = label.trim();
            if label.is_empty() {
                return Err("Timeline label cannot be empty".to_string());
            }
            let mut timeline = before.timeline.clone();
            timeline.id = state.engine.allocate_timeline_id();
            timeline.label = label.to_string();
            timeline.events.clear();
            timeline.automations.clear();
            timeline.video_automations.clear();
            timeline.audio = None;
            timeline.audio_clips.clear();
            timeline.video_clips.clear();
            timeline.phases.clear();
            timeline.item_groups.clear();
            timeline.loop_region = None;
            timeline.follow = None;
            timeline.guide_enabled = false;
            timeline.duration_ms = 0;
            clear_timeline_bank_runtime(&mut timeline);
            active_timeline_id = timeline.id;
            play = false;
            bank.push(timeline);
        }
        TimelineAdvancedMutationRequest::DuplicateTimeline { timeline_id } => {
            let source_index = bank
                .iter()
                .position(|timeline| timeline.id == *timeline_id)
                .ok_or_else(|| format!("Timeline {} was not found", timeline_id.0))?;
            let mut duplicate = bank[source_index].clone();
            duplicate.id = state.engine.allocate_timeline_id();
            duplicate.label = format!("{} Copy", duplicate.label);
            clear_timeline_bank_runtime(&mut duplicate);
            let duplicate_id = duplicate.id;
            if let Some(follow) = bank[source_index]
                .follow
                .as_mut()
                .filter(|follow| follow.enabled)
            {
                follow.next_timeline_id = duplicate_id;
            }
            bank.insert(source_index + 1, duplicate);
            active_timeline_id = duplicate_id;
            play = false;
        }
        TimelineAdvancedMutationRequest::RemoveTimeline { timeline_id } => {
            if bank.len() <= 1 {
                return Err("The final Timeline cannot be removed".to_string());
            }
            let removed_index = bank
                .iter()
                .position(|timeline| timeline.id == *timeline_id)
                .ok_or_else(|| format!("Timeline {} was not found", timeline_id.0))?;
            bank.remove(removed_index);
            if active_timeline_id == *timeline_id {
                active_timeline_id = bank[removed_index.min(bank.len() - 1)].id;
                play = false;
            }
            restitch_timeline_bank_follow_targets(&mut bank);
        }
        TimelineAdvancedMutationRequest::ReorderTimelines { timeline_ids } => {
            if timeline_ids.len() != bank.len() {
                return Err("Timeline reorder must contain every Timeline exactly once".to_string());
            }
            let mut by_id = bank
                .into_iter()
                .map(|timeline| (timeline.id, timeline))
                .collect::<BTreeMap<_, _>>();
            let mut reordered = Vec::with_capacity(timeline_ids.len());
            for timeline_id in timeline_ids {
                let timeline = by_id.remove(timeline_id).ok_or_else(|| {
                    "Timeline reorder contains a missing or duplicate ID".to_string()
                })?;
                reordered.push(timeline);
            }
            if !by_id.is_empty() {
                return Err("Timeline reorder omitted a Timeline".to_string());
            }
            bank = reordered;
            restitch_timeline_bank_follow_targets(&mut bank);
        }
        TimelineAdvancedMutationRequest::SelectTimeline {
            timeline_id,
            play: next_play,
        } => {
            if !bank.iter().any(|timeline| timeline.id == *timeline_id) {
                return Err(format!("Timeline {} was not found", timeline_id.0));
            }
            active_timeline_id = *timeline_id;
            play = *next_play;
        }
        TimelineAdvancedMutationRequest::DuplicateItems { items, offset_ms } => {
            let active = bank
                .iter_mut()
                .find(|timeline| timeline.id == active_timeline_id)
                .ok_or_else(|| "Active Timeline is missing from the Timeline bank".to_string())?;
            selected_items =
                duplicate_timeline_items(state, active, items, *offset_ms, before.clock.bpm)?;
        }
        TimelineAdvancedMutationRequest::NudgeItems { items, delta_ms } => {
            let active = bank
                .iter_mut()
                .find(|timeline| timeline.id == active_timeline_id)
                .ok_or_else(|| "Active Timeline is missing from the Timeline bank".to_string())?;
            selected_items = nudge_timeline_items(active, items, *delta_ms, before.clock.bpm)?;
        }
        TimelineAdvancedMutationRequest::MoveItemsToLanes {
            items,
            primary,
            lane_targets,
            delta_ms,
            isolate,
        } => {
            let active = bank
                .iter_mut()
                .find(|timeline| timeline.id == active_timeline_id)
                .ok_or_else(|| "Active Timeline is missing from the Timeline bank".to_string())?;
            selected_items = move_timeline_items_to_lanes(
                active,
                items,
                *primary,
                lane_targets,
                *delta_ms,
                *isolate,
                before.clock.bpm,
            )?;
        }
        TimelineAdvancedMutationRequest::RippleItems { items, delta_ms } => {
            let active = bank
                .iter_mut()
                .find(|timeline| timeline.id == active_timeline_id)
                .ok_or_else(|| "Active Timeline is missing from the Timeline bank".to_string())?;
            selected_items = ripple_timeline_items(active, items, *delta_ms, before.clock.bpm)?;
        }
        TimelineAdvancedMutationRequest::QuantizeItems { items, grid_ms } => {
            let active = bank
                .iter_mut()
                .find(|timeline| timeline.id == active_timeline_id)
                .ok_or_else(|| "Active Timeline is missing from the Timeline bank".to_string())?;
            selected_items = quantize_timeline_items(active, items, *grid_ms, before.clock.bpm)?;
        }
        TimelineAdvancedMutationRequest::PasteItems { items, target_ms } => {
            let active = bank
                .iter_mut()
                .find(|timeline| timeline.id == active_timeline_id)
                .ok_or_else(|| "Active Timeline is missing from the Timeline bank".to_string())?;
            selected_items =
                paste_timeline_items(state, active, items, *target_ms, before.clock.bpm)?;
        }
        TimelineAdvancedMutationRequest::TrimItems {
            items,
            primary,
            edge,
            boundary_ms,
            isolate,
        } => {
            let active = bank
                .iter_mut()
                .find(|timeline| timeline.id == active_timeline_id)
                .ok_or_else(|| "Active Timeline is missing from the Timeline bank".to_string())?;
            selected_items = trim_timeline_items(
                active,
                &before.video.media_assets,
                items,
                *primary,
                *edge,
                *boundary_ms,
                (*isolate, before.clock.bpm),
            )?;
        }
        TimelineAdvancedMutationRequest::SplitItems {
            items,
            primary,
            boundary_ms,
            isolate,
        } => {
            let active = bank
                .iter_mut()
                .find(|timeline| timeline.id == active_timeline_id)
                .ok_or_else(|| "Active Timeline is missing from the Timeline bank".to_string())?;
            selected_items = split_timeline_items(
                state,
                active,
                &before.video.media_assets,
                items,
                *primary,
                *boundary_ms,
                (*isolate, before.clock.bpm),
            )?;
        }
        TimelineAdvancedMutationRequest::DeleteItems { items } => {
            let active = bank
                .iter_mut()
                .find(|timeline| timeline.id == active_timeline_id)
                .ok_or_else(|| "Active Timeline is missing from the Timeline bank".to_string())?;
            delete_timeline_items(active, items)?;
        }
        _ => return Err("Timeline authoring command is not a bank mutation".to_string()),
    }
    let active = bank
        .iter_mut()
        .find(|timeline| timeline.id == active_timeline_id)
        .ok_or_else(|| "Active Timeline is missing from the Timeline bank".to_string())?;
    normalize_timeline_duration_for_engine(active, &before.video);
    let mut validation = before.clone();
    validation.timeline_bank = bank.clone();
    validation.timeline = bank
        .iter()
        .find(|timeline| timeline.id == active_timeline_id)
        .cloned()
        .ok_or_else(|| "Active Timeline is missing from the bank candidate".to_string())?;
    protocol::validate_timeline_bank(&validation, &validation.video.media_assets)?;
    Ok((bank, active_timeline_id, play, selected_items))
}

fn apply_timeline_advanced_candidate_to_snapshot(
    mut snapshot: EngineSnapshot,
    authoring: &TimelineAdvancedAuthoringSummary,
) -> Result<EngineSnapshot, String> {
    if let Some(layers) = &authoring.layers {
        snapshot.timeline.layers = layers.clone();
    }
    snapshot.timeline.video_clips = authoring.video_clips.clone();
    snapshot.timeline.audio_clips = authoring.audio_clips.clone();
    snapshot.timeline.phases = authoring.phases.clone();
    snapshot.timeline.item_groups = authoring.item_groups.clone();
    snapshot.timeline.loop_region = authoring.loop_region.clone();
    snapshot.timeline.follow = authoring.follow.clone();
    snapshot.timeline.guide_enabled = authoring.guide_enabled;
    if let Some(request) = &authoring.snap_request {
        for update in &request.event_placements {
            let current = snapshot
                .timeline
                .events
                .iter()
                .find(|event| event.id == update.event_id)
                .cloned()
                .ok_or_else(|| format!("Timeline event {} was not found", update.event_id))?;
            let canonical = engine::canonical_timeline_event_after_placement_update(
                &snapshot, &current, update,
            )?;
            let event = snapshot
                .timeline
                .events
                .iter_mut()
                .find(|event| event.id == update.event_id)
                .expect("Timeline event was found before canonical placement update");
            *event = canonical;
        }
        for update in &request.lighting_automations {
            let automation = snapshot
                .timeline
                .automations
                .iter_mut()
                .find(|automation| automation.id == update.automation_id)
                .ok_or_else(|| {
                    format!("Timeline automation {} was not found", update.automation_id)
                })?;
            automation.keyframes = update.keyframes.clone();
        }
        for update in &request.video_automations {
            let automation = snapshot
                .timeline
                .video_automations
                .iter_mut()
                .find(|automation| automation.id == update.automation_id)
                .ok_or_else(|| {
                    format!(
                        "Timeline video automation {} was not found",
                        update.automation_id
                    )
                })?;
            automation.keyframes = update.keyframes.clone();
        }
    }
    normalize_timeline_duration_for_engine(&mut snapshot.timeline, &snapshot.video);
    protocol::validate_timeline_authoring(&snapshot.timeline, &snapshot.video.media_assets)?;
    if let Some(active) = snapshot
        .timeline_bank
        .iter_mut()
        .find(|timeline| timeline.id == snapshot.timeline.id)
    {
        *active = snapshot.timeline.clone();
        clear_timeline_bank_runtime(active);
    } else {
        let mut active = snapshot.timeline.clone();
        clear_timeline_bank_runtime(&mut active);
        snapshot.timeline_bank.push(active);
    }
    protocol::validate_timeline_bank(&snapshot, &snapshot.video.media_assets)?;
    Ok(snapshot)
}

fn timeline_advanced_history_label(request: &TimelineAdvancedMutationRequest) -> &'static str {
    match request {
        TimelineAdvancedMutationRequest::Apply { .. } => "Apply Timeline authoring",
        TimelineAdvancedMutationRequest::InsertMedia { .. } => "Insert Timeline media",
        TimelineAdvancedMutationRequest::Group { .. } => "Group Timeline items",
        TimelineAdvancedMutationRequest::Ungroup { .. } => "Ungroup Timeline items",
        TimelineAdvancedMutationRequest::MoveGroup { .. } => "Move Timeline group",
        TimelineAdvancedMutationRequest::DuplicateItems { .. } => "Duplicate Timeline items",
        TimelineAdvancedMutationRequest::NudgeItems { .. } => "Nudge Timeline items",
        TimelineAdvancedMutationRequest::MoveItemsToLanes { .. } => "Move Timeline items to lanes",
        TimelineAdvancedMutationRequest::RippleItems { .. } => "Ripple Timeline items",
        TimelineAdvancedMutationRequest::QuantizeItems { .. } => "Quantize Timeline items",
        TimelineAdvancedMutationRequest::PasteItems { .. } => "Paste Timeline items",
        TimelineAdvancedMutationRequest::TrimItems { .. } => "Trim Timeline items",
        TimelineAdvancedMutationRequest::SplitItems { .. } => "Split Timeline items",
        TimelineAdvancedMutationRequest::DeleteItems { .. } => "Delete Timeline items",
        TimelineAdvancedMutationRequest::SetPhases { .. } => "Set Timeline Phases",
        TimelineAdvancedMutationRequest::SetLoop { .. } => "Set Timeline loop",
        TimelineAdvancedMutationRequest::SetFollow { .. } => "Set Timeline Follow",
        TimelineAdvancedMutationRequest::SetGuide { .. } => "Set Timeline Guide",
        TimelineAdvancedMutationRequest::CreateTimeline { .. } => "Create Timeline",
        TimelineAdvancedMutationRequest::DuplicateTimeline { .. } => "Duplicate Timeline",
        TimelineAdvancedMutationRequest::RemoveTimeline { .. } => "Remove Timeline",
        TimelineAdvancedMutationRequest::ReorderTimelines { .. } => "Reorder Timelines",
        TimelineAdvancedMutationRequest::SelectTimeline { .. } => "Select Timeline",
    }
}

fn commit_authoritative_timeline_advanced(
    state: &AppState,
    expected_epoch: u64,
    owner_id: &str,
    expected_authority: &MediaAssetPrepareAuthority,
    request: &TimelineAdvancedMutationRequest,
) -> Result<TimelineAdvancedAuthoritativeResult, String> {
    let (_external_admission, mut coordinator) = (
        lock_project_external_command_admission(state)?,
        lock_project_coordinator(state)?,
    );
    validate_authoritative_media_asset_commit(
        state,
        &mut coordinator,
        expected_epoch,
        owner_id,
        expected_authority,
    )?;
    if state.project_transaction_active.load(Ordering::Acquire) {
        return Err("Project transaction is active; retry the Timeline command".to_string());
    }
    let before_snapshot = state.engine.persistence_snapshot()?;
    let bank_request = matches!(
        request,
        TimelineAdvancedMutationRequest::CreateTimeline { .. }
            | TimelineAdvancedMutationRequest::DuplicateTimeline { .. }
            | TimelineAdvancedMutationRequest::RemoveTimeline { .. }
            | TimelineAdvancedMutationRequest::ReorderTimelines { .. }
            | TimelineAdvancedMutationRequest::SelectTimeline { .. }
            | TimelineAdvancedMutationRequest::DuplicateItems { .. }
            | TimelineAdvancedMutationRequest::NudgeItems { .. }
            | TimelineAdvancedMutationRequest::MoveItemsToLanes { .. }
            | TimelineAdvancedMutationRequest::RippleItems { .. }
            | TimelineAdvancedMutationRequest::QuantizeItems { .. }
            | TimelineAdvancedMutationRequest::PasteItems { .. }
            | TimelineAdvancedMutationRequest::TrimItems { .. }
            | TimelineAdvancedMutationRequest::SplitItems { .. }
            | TimelineAdvancedMutationRequest::DeleteItems { .. }
    );
    let (candidate_snapshot, bank_publication, selected_items, publication_snap_request) =
        if bank_request {
            let (timeline_bank, active_timeline_id, play, selected_items) =
                timeline_bank_candidate_for_request(state, &before_snapshot, request)?;
            let mut candidate = before_snapshot.clone();
            candidate.timeline_bank = timeline_bank.clone();
            candidate.timeline = timeline_bank
                .iter()
                .find(|timeline| timeline.id == active_timeline_id)
                .cloned()
                .ok_or_else(|| "Active Timeline is missing from the bank candidate".to_string())?;
            clear_timeline_bank_runtime(&mut candidate.timeline);
            if let Some(active) = candidate
                .timeline_bank
                .iter_mut()
                .find(|timeline| timeline.id == active_timeline_id)
            {
                *active = candidate.timeline.clone();
            }
            protocol::validate_timeline_bank(&candidate, &candidate.video.media_assets)?;
            let timeline_bank = candidate.timeline_bank.clone();
            (
                candidate,
                Some((timeline_bank, active_timeline_id, play)),
                selected_items,
                None,
            )
        } else {
            let authoring =
                timeline_advanced_candidate_for_request(state, &before_snapshot, request)?;
            // Applying a candidate consumes its timing/keyframe delta into the
            // persisted Timeline image. The engine, however, resolves that delta
            // from its current live image at publication time, so retain the
            // exact candidate-produced request for every non-bank mutation. This
            // covers both direct Apply and MoveGroup; reconstructing only Apply
            // would leave MoveGroup history B while the live engine stayed at A.
            let publication_snap_request = authoring.snap_request.clone();
            (
                apply_timeline_advanced_candidate_to_snapshot(before_snapshot.clone(), &authoring)?,
                None,
                Vec::new(),
                publication_snap_request,
            )
        };
    let authoring = timeline_advanced_authoring_from_snapshot(&candidate_snapshot.timeline);
    // The candidate snapshot has already consumed `snap_request` so the
    // returned authoring image deliberately contains none.  EngineHandle,
    // however, applies Timeline authoring from the current live snapshot and
    // therefore still needs that exact timing/keyframe delta at publication.
    // Keep it only on the engine payload; the durable result remains the
    // canonical post-Apply image.  Dropping it here would record history B
    // while leaving the live Scene Block/event timing at A.
    let mut publication_authoring = authoring.clone();
    if bank_publication.is_none() {
        publication_authoring.snap_request = publication_snap_request;
    }
    let result_timeline_bank = candidate_snapshot.timeline_bank.clone();
    let result_active_timeline_id = candidate_snapshot.timeline.id;
    let before_project =
        project_file_for_save_from_parts(before_snapshot.clone(), &coordinator.ancillary);
    let before = ProjectCheckpoint {
        hash: project_checkpoint_hash(&before_project, &coordinator.mappings)?,
        project: before_project,
        mappings: coordinator.mappings.clone(),
        epoch: coordinator.epoch,
        revision: coordinator.revision,
    };
    let after_project =
        project_file_for_save_from_parts(candidate_snapshot, &coordinator.ancillary);
    let after = ProjectCheckpoint {
        project: after_project,
        mappings: coordinator.mappings.clone(),
        epoch: coordinator.epoch,
        revision: coordinator.revision,
        hash: String::new(),
    };
    let plan = prepare_internal_media_asset_commit(
        &coordinator,
        timeline_advanced_history_label(request),
        "",
        before,
        after,
        current_unix_ms().min(u64::MAX as u128) as u64,
    )?;
    run_admitted_internal_media_asset_transaction(
        &state.project_transaction_active,
        &mut coordinator,
        plan,
        || match &bank_publication {
            Some((timeline_bank, active_timeline_id, play)) => state
                .engine
                .apply_timeline_bank_published(timeline_bank.clone(), *active_timeline_id, *play),
            None => state
                .engine
                .apply_timeline_advanced_authoring_published(publication_authoring),
        },
    )?;
    Ok(TimelineAdvancedAuthoritativeResult {
        authoring,
        timeline_bank: result_timeline_bank,
        active_timeline_id: result_active_timeline_id,
        selected_items,
        mutation: ProjectHistoryMutationResult {
            history_status: project_history_status_for_coordinator(&coordinator),
            authority: project_authority_bundle_from_coordinator(state, &coordinator),
        },
    })
}

/// C1's B3-style terminal body: revalidate authority under the external
/// admission, build history B from persistence/authored state, send exactly
/// one catalog Published command, then apply the preflighted history plan.
/// Nothing after the engine ACK is fallible.
fn commit_authoritative_video_effect_catalog(
    state: &AppState,
    expected_epoch: u64,
    owner_id: &str,
    expected_authority: &MediaAssetPrepareAuthority,
    request: &VideoEffectCatalogApplyRequest,
) -> Result<VideoEffectCatalogAuthoritativeResult, String> {
    let (_external_admission, mut coordinator) = (
        lock_project_external_command_admission(state)?,
        lock_project_coordinator(state)?,
    );
    validate_authoritative_media_asset_commit(
        state,
        &mut coordinator,
        expected_epoch,
        owner_id,
        expected_authority,
    )?;
    if state.project_transaction_active.load(Ordering::Acquire) {
        return Err(
            "Project transaction is active; retry the video effect catalog command".to_string(),
        );
    }
    let before_snapshot = state.engine.persistence_snapshot()?;
    let normalized_request = normalize_video_effect_catalog_ids(state, &before_snapshot, request)?;
    let before_project =
        project_file_for_save_from_parts(before_snapshot.clone(), &coordinator.ancillary);
    let before = ProjectCheckpoint {
        hash: project_checkpoint_hash(&before_project, &coordinator.mappings)?,
        project: before_project,
        mappings: coordinator.mappings.clone(),
        epoch: coordinator.epoch,
        revision: coordinator.revision,
    };
    let candidate_snapshot =
        video_effect_catalog_candidate_snapshot(before_snapshot, &normalized_request)?;
    let after_project =
        project_file_for_save_from_parts(candidate_snapshot.clone(), &coordinator.ancillary);
    let after = ProjectCheckpoint {
        project: after_project,
        mappings: coordinator.mappings.clone(),
        epoch: coordinator.epoch,
        revision: coordinator.revision,
        hash: String::new(),
    };
    let plan = prepare_internal_media_asset_commit(
        &coordinator,
        "Apply video effect catalog",
        "",
        before,
        after,
        current_unix_ms().min(u64::MAX as u128) as u64,
    )?;
    let catalog = VideoEffectCatalogAuthoritativeCatalog {
        effect_chains: candidate_snapshot
            .authored_video
            .as_ref()
            .expect("C1 candidate always has canonical authored video")
            .effect_chains
            .clone(),
        effect_presets: candidate_snapshot
            .authored_video
            .as_ref()
            .expect("C1 candidate always has canonical authored video")
            .effect_presets
            .clone(),
        layer_groups: candidate_snapshot
            .authored_video
            .as_ref()
            .expect("C1 candidate always has canonical authored video")
            .layer_groups
            .clone(),
        transition_buses: candidate_snapshot
            .authored_video
            .as_ref()
            .expect("C1/C3 candidate always has canonical authored video")
            .transition_buses
            .clone(),
    };
    run_admitted_internal_media_asset_transaction(
        &state.project_transaction_active,
        &mut coordinator,
        plan,
        || {
            #[cfg(test)]
            state
                .video_effect_catalog_authoritative_publish_attempts
                .fetch_add(1, Ordering::AcqRel);
            state
                .engine
                .apply_video_effect_catalog_with_transition_buses(
                    catalog.effect_chains.clone(),
                    catalog.effect_presets.clone(),
                    catalog.layer_groups.clone(),
                    catalog.transition_buses.clone(),
                )
        },
    )?;
    Ok(VideoEffectCatalogAuthoritativeResult {
        catalog,
        mutation: ProjectHistoryMutationResult {
            history_status: project_history_status_for_coordinator(&coordinator),
            authority: project_authority_bundle_from_coordinator(state, &coordinator),
        },
    })
}

#[allow(clippy::too_many_arguments)]
fn apply_video_effect_catalog_authoritative_command_impl(
    state: &AppState,
    request: VideoEffectCatalogApplyRequest,
    request_id: u64,
    expected_epoch: u64,
    expected_revision: u64,
    expected_checkpoint_hash: String,
    owner_id: String,
    caller_binding: Option<VideoClipSlotCallerBinding>,
) -> Result<VideoEffectCatalogAuthoritativeResult, String> {
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    ensure_project_transaction_owner_registered(state, &owner_id)?;
    let _rotation = state
        .project_transaction_owner_rotation
        .lock()
        .map_err(|_| "Project transaction owner rotation lock was poisoned".to_string())?;
    let binding = resolve_video_clip_slot_caller_binding(state, &owner_id, caller_binding)?;
    let key = video_effect_catalog_authoritative_operation_key(
        request_id,
        &binding,
        expected_epoch,
        expected_revision,
        expected_checkpoint_hash,
    )?;
    let expected_authority = video_effect_catalog_authoritative_expected_authority(&key);
    let shape = video_effect_catalog_authoritative_shape(&request)?;
    let terminal = state
        .media_asset_operations
        .video_effect_catalog_authoritative_terminal_single_flight(&key, &shape, || {
            commit_authoritative_video_effect_catalog(
                state,
                expected_authority.epoch,
                &owner_id,
                &expected_authority,
                &request,
            )
            .map(|result| VideoEffectCatalogAuthoritativeTerminalResult::Applied(Box::new(result)))
        })?;
    match terminal {
        VideoEffectCatalogAuthoritativeTerminalResult::Applied(result) => Ok(*result),
        VideoEffectCatalogAuthoritativeTerminalResult::Timeline(_) => {
            Err("Video effect catalog command received a Timeline terminal result".to_string())
        }
        VideoEffectCatalogAuthoritativeTerminalResult::Runtime(_) => Err(
            "Video effect catalog command received a runtime transition terminal result"
                .to_string(),
        ),
        VideoEffectCatalogAuthoritativeTerminalResult::TimelineFollowAbort(_) => Err(
            "Video effect catalog command received a Timeline Follow abort terminal result"
                .to_string(),
        ),
    }
}

#[allow(clippy::too_many_arguments)]
fn apply_timeline_advanced_authoritative_command_impl(
    state: &AppState,
    request: TimelineAdvancedMutationRequest,
    request_id: u64,
    expected_epoch: u64,
    expected_revision: u64,
    expected_checkpoint_hash: String,
    owner_id: String,
    caller_binding: Option<VideoClipSlotCallerBinding>,
) -> Result<TimelineAdvancedAuthoritativeResult, String> {
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    ensure_project_transaction_owner_registered(state, &owner_id)?;
    let _rotation = state
        .project_transaction_owner_rotation
        .lock()
        .map_err(|_| "Project transaction owner rotation lock was poisoned".to_string())?;
    let binding = resolve_video_clip_slot_caller_binding(state, &owner_id, caller_binding)?;
    let key = video_effect_catalog_authoritative_operation_key(
        request_id,
        &binding,
        expected_epoch,
        expected_revision,
        expected_checkpoint_hash,
    )?;
    let expected_authority = video_effect_catalog_authoritative_expected_authority(&key);
    let shape = timeline_advanced_authoritative_shape(&request)?;
    let terminal = state
        .media_asset_operations
        .video_effect_catalog_authoritative_terminal_single_flight(&key, &shape, || {
            commit_authoritative_timeline_advanced(
                state,
                expected_authority.epoch,
                &owner_id,
                &expected_authority,
                &request,
            )
            .map(|result| VideoEffectCatalogAuthoritativeTerminalResult::Timeline(Box::new(result)))
        })?;
    match terminal {
        VideoEffectCatalogAuthoritativeTerminalResult::Timeline(result) => Ok(*result),
        VideoEffectCatalogAuthoritativeTerminalResult::Applied(_) => {
            Err("Timeline command received a video effect terminal result".to_string())
        }
        VideoEffectCatalogAuthoritativeTerminalResult::Runtime(_) => {
            Err("Timeline command received a runtime transition terminal result".to_string())
        }
        VideoEffectCatalogAuthoritativeTerminalResult::TimelineFollowAbort(_) => {
            Err("Timeline command received a Timeline Follow abort terminal result".to_string())
        }
    }
}

