fn timeline_cue_audio_topology_fingerprint(names: &[String]) -> String {
    let mut names = names.to_vec();
    names.sort();
    let mut hasher = Sha256::new();
    hasher.update(b"syndocal.timeline-cue-audio.topology.v1\0");
    for name in names {
        hasher.update((name.len() as u64).to_le_bytes());
        hasher.update(name.as_bytes());
    }
    hasher
        .finalize()
        .iter()
        .map(|byte| format!("{byte:02X}"))
        .collect()
}

fn timeline_cue_audio_endpoint_summaries(names: &[String]) -> Vec<TimelineCueAudioEndpointSummary> {
    let mut counts = BTreeMap::<String, u32>::new();
    for name in names {
        let count = counts.entry(name.clone()).or_default();
        *count = count.saturating_add(1);
    }
    counts
        .into_iter()
        .map(|(name, occurrences)| TimelineCueAudioEndpointSummary {
            name,
            occurrences,
            selectable: occurrences == 1,
        })
        .collect()
}

fn exact_timeline_cue_audio_device_index(
    names: &[String],
    requested_name: &str,
) -> Result<usize, String> {
    let matching = names
        .iter()
        .enumerate()
        .filter_map(|(index, name)| (name == requested_name).then_some(index))
        .collect::<Vec<_>>();
    match matching.as_slice() {
        [] => Err(format!(
            "Timeline cue audio device '{requested_name}' is missing"
        )),
        [index] => Ok(*index),
        _ => Err(format!(
            "Timeline cue audio device '{requested_name}' is ambiguous ({} exact-name matches)",
            matching.len()
        )),
    }
}

fn validate_explicit_wdm_cue_inventory(
    names: &[String],
    requested_name: &str,
    expected_topology: &str,
    observed_topology: &str,
) -> Result<usize, String> {
    if observed_topology != expected_topology {
        return Err(format!(
            "Timeline cue audio topology changed (expected {expected_topology}, observed {observed_topology}); reselect the device"
        ));
    }
    exact_timeline_cue_audio_device_index(names, requested_name)
}

fn timeline_cue_program_destination(
    playback: &MediaAudioPlayback,
) -> Option<TimelineCueProgramDestination> {
    #[cfg(test)]
    if playback.active_program_mixer().is_none() {
        if let Some(mixer) = playback.timeline_test_mixer.as_ref() {
            return Some(TimelineCueProgramDestination {
                mixer: mixer.clone(),
                output_sample_rate: 48_000,
                channels: 2,
                device_generation: playback.audio_device_generation,
                resolved_device_name: Some("Test Program Mixer".to_string()),
            });
        }
    }
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    let (mixer, output_sample_rate, channels) = {
        let output = playback.normal_output.as_ref()?;
        (output.mixer(), output.sample_rate(), output.channels())
    };
    #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
    let (mixer, output_sample_rate, channels) = {
        let stream = playback.stream.as_ref()?;
        let (output_sample_rate, channels) = direct_media_audio_output_format(stream);
        (
            stream.mixer().clone(),
            output_sample_rate,
            channels,
        )
    };
    Some(TimelineCueProgramDestination {
        mixer,
        output_sample_rate,
        channels,
        device_generation: playback.audio_device_generation,
        resolved_device_name: playback.device_name.clone(),
    })
}

fn timeline_cue_engine_identity(
    timeline: &engine::TimelineAudioRuntimeSnapshot,
) -> Result<TimelineCueEngineIdentity, String> {
    let expected_source = match timeline.metronome_transport {
        Some(engine::TimelineMetronomeTransport::DirectChild { cue_id, generation }) => {
            TimelineScheduleSource::DirectChild { cue_id, generation }
        }
        Some(engine::TimelineMetronomeTransport::Root)
        | Some(engine::TimelineMetronomeTransport::Follow { .. })
        | None => TimelineScheduleSource::Root,
    };
    let mut published_identity = None::<(u64, u64, u64, TimelineScheduleSource)>;
    for identity in timeline
        .click_events
        .iter()
        .map(|event| {
            (
                event.epoch,
                event.transport_generation,
                event.schedule_generation,
                event.source,
            )
        })
        .chain(timeline.guide_cues.iter().map(|cue| {
            (
                cue.epoch,
                cue.transport_generation,
                cue.schedule_generation,
                cue.source,
            )
        }))
    {
        if identity.3 != expected_source {
            return Err(
                "Timeline cue event source does not match the active transport".to_string(),
            );
        }
        if published_identity.is_some_and(|expected| expected != identity) {
            return Err("Timeline cue event batch mixes transport authorities".to_string());
        }
        published_identity = Some(identity);
    }
    let (epoch, transport_generation, schedule_generation, source) =
        published_identity.unwrap_or((
            timeline.transport_epoch,
            timeline.transport_generation,
            timeline.click_schedule_generation.max(1),
            expected_source,
        ));
    if published_identity.is_some()
        && (epoch != timeline.transport_epoch
            || transport_generation != timeline.transport_generation)
    {
        return Err(
            "Timeline cue event transport authority is stale against the published Timeline transport"
                .to_string(),
        );
    }
    if schedule_generation != timeline.click_schedule_generation.max(1) {
        return Err("Timeline cue event schedule generation is stale".to_string());
    }
    Ok(TimelineCueEngineIdentity {
        epoch,
        transport_generation,
        schedule_generation,
        source,
        audio_transport_revision: timeline.transport_revision,
        metronome_enabled: timeline.metronome_enabled,
        guide_enabled: timeline.guide_enabled,
        playing: timeline.playing,
    })
}

fn timeline_cue_canonical_frame(position_ms: u64) -> Result<u64, String> {
    position_ms
        .checked_mul(u64::from(
            timeline_cue_audio::TIMELINE_CUE_CANONICAL_SAMPLE_RATE,
        ))
        .map(|frames| frames / 1_000)
        .ok_or_else(|| "Timeline cue audio canonical frame is exhausted".to_string())
}

fn native_timeline_guide_asset_key(
    asset: TimelineGuideAssetKey,
) -> timeline_cue_audio::TimelineGuideAssetKey {
    match asset {
        TimelineGuideAssetKey::Intro => timeline_cue_audio::TimelineGuideAssetKey::Intro,
        TimelineGuideAssetKey::Verse => timeline_cue_audio::TimelineGuideAssetKey::Verse,
        TimelineGuideAssetKey::PreChorus => timeline_cue_audio::TimelineGuideAssetKey::PreChorus,
        TimelineGuideAssetKey::Chorus => timeline_cue_audio::TimelineGuideAssetKey::Chorus,
        TimelineGuideAssetKey::Interlude => timeline_cue_audio::TimelineGuideAssetKey::Interlude,
        TimelineGuideAssetKey::Bridge => timeline_cue_audio::TimelineGuideAssetKey::Bridge,
        TimelineGuideAssetKey::Breakdown => timeline_cue_audio::TimelineGuideAssetKey::Breakdown,
        TimelineGuideAssetKey::Outro => timeline_cue_audio::TimelineGuideAssetKey::Outro,
        TimelineGuideAssetKey::Looping => timeline_cue_audio::TimelineGuideAssetKey::Looping,
        TimelineGuideAssetKey::Break => timeline_cue_audio::TimelineGuideAssetKey::Break,
        TimelineGuideAssetKey::Trans => timeline_cue_audio::TimelineGuideAssetKey::Trans,
        TimelineGuideAssetKey::Complete => timeline_cue_audio::TimelineGuideAssetKey::Complete,
    }
}

type TimelineCueAudioOutputs = (
    Vec<(String, rodio::cpal::Device)>,
    String,
    Vec<TimelineCueAudioEndpointSummary>,
);

fn enumerate_timeline_cue_audio_outputs() -> Result<TimelineCueAudioOutputs, String> {
    use rodio::cpal::traits::{DeviceTrait, HostTrait};

    let mut devices = Vec::new();
    for device in rodio::cpal::default_host()
        .output_devices()
        .map_err(|error| format!("Failed to list Timeline cue audio devices: {error}"))?
    {
        let name = device
            .name()
            .map_err(|error| format!("Timeline cue audio device name is unavailable: {error}"))?;
        devices.push((name, device));
    }
    let names = devices
        .iter()
        .map(|(name, _)| name.clone())
        .collect::<Vec<_>>();
    Ok((
        devices,
        timeline_cue_audio_topology_fingerprint(&names),
        timeline_cue_audio_endpoint_summaries(&names),
    ))
}

fn prepare_explicit_timeline_cue_destination(
    settings: &timeline_cue_audio::MachineTimelineCueAudioSettingsV1,
) -> Result<
    (
        PreparedTimelineCueDestination,
        Vec<TimelineCueAudioEndpointSummary>,
    ),
    String,
> {
    use rodio::cpal::traits::DeviceTrait;

    let requested_name = settings
        .device_name
        .as_deref()
        .ok_or_else(|| "Explicit Timeline cue audio route requires a device name".to_string())?;
    let expected_topology = settings.topology_fingerprint.as_deref().ok_or_else(|| {
        "Explicit Timeline cue audio selection predates topology fencing; reselect the device"
            .to_string()
    })?;
    let (devices, topology_fingerprint, endpoints) = enumerate_timeline_cue_audio_outputs()?;
    #[cfg(not(target_os = "macos"))]
    let mut devices = devices;
    let names = devices
        .iter()
        .map(|(name, _)| name.clone())
        .collect::<Vec<_>>();
    let index = validate_explicit_wdm_cue_inventory(
        &names,
        requested_name,
        expected_topology,
        &topology_fingerprint,
    )?;
    #[cfg(target_os = "macos")]
    let _ = index;
    #[cfg(target_os = "macos")]
    let (resolved_device_name, output_sample_rate, channels, mixer, explicit_stream) = {
        // CoreAudio's stream is owned by a dedicated resource thread. Only
        // its thread-safe Mixer and immutable format metadata cross into the
        // shared Tauri state.
        let output = mac_audio_resources::MacAudioOutput::open(Some(requested_name), false)?;
        let resolved_device_name = output.device_name().map(str::to_owned);
        let output_sample_rate = output.sample_rate();
        let channels = output.channels();
        let mixer = output.mixer().clone();
        (
            resolved_device_name,
            output_sample_rate,
            channels,
            mixer,
            Some(output),
        )
    };
    #[cfg(not(target_os = "macos"))]
    let (resolved_device_name, output_sample_rate, channels, mixer, explicit_stream) = {
        let (_, device) = devices.swap_remove(index);
        let resolved_device_name = device.name().ok();
        let stream = rodio::OutputStreamBuilder::from_device(device)
            .and_then(|builder| builder.open_stream())
            .map_err(|error| format!("Failed to open Timeline cue audio output: {error}"))?;
        let output_sample_rate = stream.config().sample_rate();
        let channels = stream.config().channel_count();
        let mixer = stream.mixer().clone();
        (
            resolved_device_name,
            output_sample_rate,
            channels,
            mixer,
            Some(stream),
        )
    };
    let assets = timeline_cue_audio::GuideAssetBank::prepare_embedded(output_sample_rate)?;
    Ok((
        PreparedTimelineCueDestination {
            mixer,
            output_sample_rate,
            channels,
            program_device_generation: None,
            resolved_device_name,
            topology_fingerprint: Some(topology_fingerprint),
            explicit_stream,
            assets,
        },
        endpoints,
    ))
}

fn prepare_follow_program_timeline_cue_destination(
    program: TimelineCueProgramDestination,
) -> Result<PreparedTimelineCueDestination, String> {
    let assets = timeline_cue_audio::GuideAssetBank::prepare_embedded(program.output_sample_rate)?;
    Ok(PreparedTimelineCueDestination {
        mixer: program.mixer,
        output_sample_rate: program.output_sample_rate,
        channels: program.channels,
        program_device_generation: Some(program.device_generation),
        resolved_device_name: program.resolved_device_name,
        topology_fingerprint: None,
        explicit_stream: None,
        assets,
    })
}

const TIMELINE_CUE_AUDIO_PREPARE_TIMEOUT: Duration = Duration::from_millis(750);

#[cfg(any(
    test,
    all(target_os = "windows", target_arch = "x86_64", feature = "asio")
))]
fn join_completed_timeline_cue_worker(
    worker: &mut Option<std::thread::JoinHandle<()>>,
) -> Result<(), String> {
    let Some(worker) = worker.take() else {
        return Err("Timeline cue audio worker handle was already consumed".to_string());
    };
    worker
        .join()
        .map_err(|_| "Timeline cue audio worker panicked".to_string())
}

fn take_finished_timeline_cue_workers(
    state: &mut TimelineCueAudioRuntimeState,
) -> Vec<std::thread::JoinHandle<()>> {
    let mut retained = Vec::with_capacity(state.retired_workers.len());
    let mut finished = Vec::new();
    for worker in state.retired_workers.drain(..) {
        if worker.is_finished() {
            finished.push(worker);
        } else {
            retained.push(worker);
        }
    }
    state.retired_workers = retained;
    finished
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn clear_asio_retry_barrier(state: &mut TimelineCueAudioRuntimeState) {
    state.asio_retry_barrier = None;
}

#[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
fn clear_asio_retry_barrier(_state: &mut TimelineCueAudioRuntimeState) {}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn set_asio_retry_barrier(
    state: &mut TimelineCueAudioRuntimeState,
    identity: TimelineCueEngineIdentity,
) {
    state.asio_retry_barrier = Some(identity);
}

#[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
fn set_asio_retry_barrier(
    _state: &mut TimelineCueAudioRuntimeState,
    _identity: TimelineCueEngineIdentity,
) {
}

fn transition_timeline_cue_audio_to_terminal_state(
    state: &mut TimelineCueAudioRuntimeState,
    operation: &str,
    error: String,
    lifecycle: TimelineCueAudioLifecycle,
    state_poisoned: bool,
) -> (
    Option<TimelineCueAudioAttachment>,
    Vec<std::thread::JoinHandle<()>>,
) {
    if let Some(mut job) = state.prepare_job.take() {
        if let Some(worker) = job.worker.take() {
            state.retired_workers.push(worker);
        }
    }
    if let Some(mut probe) = state.topology_probe.take() {
        if let Some(worker) = probe.worker.take() {
            state.retired_workers.push(worker);
        }
    }
    let finished_workers = take_finished_timeline_cue_workers(state);
    let attachment = state.attachment.take();
    state.applied = None;
    state.normal_admission_open = false;
    state.blocked_settings_revision = Some(state.settings_revision);
    state.lifecycle = if state_poisoned {
        TimelineCueAudioLifecycle::Fault
    } else {
        lifecycle
    };
    clear_asio_retry_barrier(state);
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    {
        state.active_asio_cue_delivery = None;
    }
    state.last_error = Some(if state_poisoned {
        format!(
            "Timeline cue audio state lock was poisoned during {operation}; attachment retired and restart is required"
        )
    } else {
        error
    });
    (attachment, finished_workers)
}

impl TimelineCueAudioRuntime {
    fn activate_pending_source(
        attachment: &mut TimelineCueAudioAttachment,
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        asio_runtime: Option<&mut asio_output_runtime::AsioOutputRuntime>,
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        expected_output_identity: Option<asio_timeline_output::TimelineOutputIdentity>,
    ) -> Result<(), String> {
        let Some(source) = attachment.pending_source.take() else {
            return Ok(());
        };
        #[cfg(test)]
        let activation_token = attachment.source_instance_token;
        match &mut attachment.output {
            TimelineCueAudioAttachmentOutput::Legacy { mixer, .. } => {
                mixer.add(source);
                #[cfg(test)]
                {
                    attachment
                        .source_test_counters
                        .activations
                        .fetch_add(1, Ordering::Relaxed);
                    timeline_cue_audio_test_after_source_activation(activation_token);
                }
                Ok(())
            }
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            TimelineCueAudioAttachmentOutput::AsioCue { identity, sink } => {
                let runtime = asio_runtime.ok_or_else(|| {
                    "ASIO output runtime owner is unavailable while activating Timeline cue source"
                        .to_string()
                })?;
                let expected = expected_output_identity.ok_or_else(|| {
                    "ASIO output identity is unavailable while activating Timeline cue source"
                        .to_string()
                })?;
                if *identity != expected {
                    return Err(format!(
                        "ASIO CUE attachment identity changed before source activation: expected {expected:?}, got {identity:?}"
                    ));
                }
                let next_sink = runtime.attach_source(*identity, source, false)?;
                if let Some(previous_sink) = sink.replace(next_sink) {
                    #[cfg(test)]
                    attachment
                        .source_test_counters
                        .retirements
                        .fetch_add(1, Ordering::Relaxed);
                    previous_sink.stop();
                }
                #[cfg(test)]
                attachment
                    .source_test_counters
                    .activations
                    .fetch_add(1, Ordering::Relaxed);
                Ok(())
            }
        }
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn lock_external_wdm_route_state(
        &self,
    ) -> Result<
        (
            std::sync::MutexGuard<'_, ()>,
            std::sync::MutexGuard<'_, TimelineCueAudioRuntimeState>,
        ),
        String,
    > {
        // Acquire the route gate before the lifecycle state and return both
        // guards. Writers keep the gate through the short state mutation, then
        // explicitly drop it before any sink retirement, device I/O, or worker
        // join. The final media commit uses its own guard through publication.
        let route_gate = self
            .external_wdm_timeline_route_gate
            .lock()
            .map_err(|_| "External WDM Timeline route gate was poisoned".to_owned())?;
        let state = self
            .state
            .lock()
            .map_err(|_| "Timeline cue audio lifecycle lock was poisoned".to_owned())?;
        Ok((route_gate, state))
    }

    fn terminal_fault_and_retire_normal_runtime(&self, operation: &str, error: String) {
        let (attachment, finished_workers) = {
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            let route_gate = self
                .external_wdm_timeline_route_gate
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            let state_result = self.state.lock();
            let (mut state, state_poisoned) = match state_result {
                Ok(state) => (state, false),
                Err(poisoned) => (poisoned.into_inner(), true),
            };
            let transition = transition_timeline_cue_audio_to_terminal_state(
                &mut state,
                operation,
                error,
                TimelineCueAudioLifecycle::Fault,
                state_poisoned,
            );
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            drop(route_gate);
            transition
        };
        if let Some(attachment) = attachment {
            attachment.retire();
        }
        for worker in finished_workers {
            let _ = worker.join();
        }
    }

    fn reap_finished_timeline_cue_workers(&self) -> bool {
        let state_result = {
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            let route_gate = self
                .external_wdm_timeline_route_gate
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            let state = self.state.lock();
            let result = state.map(|mut state| take_finished_timeline_cue_workers(&mut state));
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            drop(route_gate);
            result
        };
        let finished = match state_result {
            Ok(finished) => finished,
            Err(poisoned) => {
                drop(poisoned.into_inner());
                self.terminal_fault_and_retire_normal_runtime(
                    "retired worker reap",
                    "Timeline cue audio state lock was poisoned during retired worker reap"
                        .to_owned(),
                );
                return true;
            }
        };
        let panicked = finished.into_iter().any(|worker| worker.join().is_err());
        if panicked {
            self.terminal_fault_and_retire_normal_runtime(
                "retired worker join",
                "Retired Timeline cue audio worker panicked".to_owned(),
            );
        }
        panicked
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn activate_asio_cue_delivery(
        &self,
        delivery: &asio_program_cue::CueDelivery,
    ) -> Result<(), String> {
        let _route_gate = self
            .external_wdm_timeline_route_gate
            .lock()
            .map_err(|_| "External WDM Timeline route gate was poisoned".to_string())?;
        let _admission = self
            .settings_update
            .lock()
            .map_err(|_| "Timeline cue audio admission lock was poisoned".to_string())?;
        let mut state = self
            .state
            .lock()
            .map_err(|_| "Timeline cue audio lifecycle lock was poisoned".to_string())?;
        if state.attachment.is_some()
            || state.prepare_job.is_some()
            || state.topology_probe.is_some()
            || !state.retired_workers.is_empty()
        {
            return Err(
                "ASIO CUE delivery cannot activate before every retired CUE route is drained"
                    .to_string(),
            );
        }
        let active = match delivery {
            asio_program_cue::CueDelivery::SameAsio { .. } => ActiveAsioCueDelivery::SameAsio,
            asio_program_cue::CueDelivery::ExplicitWdm {
                device_name,
                topology_fingerprint,
            } => ActiveAsioCueDelivery::ExplicitWdm {
                device_name: device_name.clone(),
                topology_fingerprint: topology_fingerprint.clone(),
            },
        };
        state.settings_revision = state
            .settings_revision
            .checked_add(1)
            .ok_or_else(|| "Timeline cue audio settings revision is exhausted".to_string())?;
        state.normal_admission_open = matches!(active, ActiveAsioCueDelivery::ExplicitWdm { .. });
        state.active_asio_cue_delivery = Some(active);
        state.blocked_settings_revision = None;
        clear_asio_retry_barrier(&mut state);
        state.lifecycle = TimelineCueAudioLifecycle::Applying;
        state.last_error = None;
        Ok(())
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn explicit_wdm_output_snapshot(&self) -> Option<ExplicitWdmTimelineOutputSnapshot> {
        let _route_gate = self.external_wdm_timeline_route_gate.try_lock().ok()?;
        let state = self.state.try_lock().ok()?;
        if !matches!(
            state.active_asio_cue_delivery,
            Some(ActiveAsioCueDelivery::ExplicitWdm { .. })
        ) {
            return None;
        }
        let attachment = state.attachment.as_ref()?;
        let TimelineCueAudioAttachmentOutput::Legacy { mixer, .. } = &attachment.output else {
            return None;
        };
        (attachment.route == timeline_cue_audio::TimelineCueAudioRoute::ExplicitDevice).then(|| {
            ExplicitWdmTimelineOutputSnapshot {
                mixer: mixer.clone(),
                output_clock_epoch: attachment.output_clock_epoch,
                owner: ExplicitWdmTimelineOwner::AsioCue,
            }
        })
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn normal_authoring_route_snapshot_blocking(
        &self,
    ) -> Result<NormalAuthoringRouteSnapshot, String> {
        let _route_gate = self
            .external_wdm_timeline_route_gate
            .lock()
            .map_err(|_| "External WDM Timeline route gate was poisoned".to_owned())?;
        let state = self.state.lock().map_err(|_| {
            "Timeline cue audio lifecycle lock was poisoned during authoring monitor observation"
                .to_owned()
        })?;
        if !state.normal_admission_open || state.active_asio_cue_delivery.is_some() {
            return Err(
                "Timeline authoring monitor is unavailable outside the Normal output route"
                    .to_owned(),
            );
        }
        if state.desired.route == timeline_cue_audio::TimelineCueAudioRoute::FollowProgram {
            return Ok(NormalAuthoringRouteSnapshot::FollowProgram);
        }
        let output = state.attachment.as_ref().and_then(|attachment| {
            let TimelineCueAudioAttachmentOutput::Legacy { mixer, .. } = &attachment.output else {
                return None;
            };
            let exact_settings = state.lifecycle == TimelineCueAudioLifecycle::Running
                && state.blocked_settings_revision != Some(state.settings_revision)
                && state.applied.as_ref() == Some(&state.desired)
                && attachment.settings_revision == state.settings_revision
                && attachment.route == timeline_cue_audio::TimelineCueAudioRoute::ExplicitDevice
                && state.desired.device_name.as_deref() == state.resolved_device_name.as_deref()
                && state.desired.topology_fingerprint.as_deref()
                    == state.observed_topology_fingerprint.as_deref();
            exact_settings.then(|| ExplicitWdmTimelineOutputSnapshot {
                mixer: mixer.clone(),
                output_clock_epoch: attachment.output_clock_epoch,
                owner: ExplicitWdmTimelineOwner::NormalAuthoring,
            })
        });
        Ok(NormalAuthoringRouteSnapshot::ExplicitWdm(output))
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn append_explicit_wdm_cue_test_tone(&self) -> Result<(), String> {
        // Admission serializes replace/append with Stop/Close and with the
        // Timeline Play linearization fence.  Without this process-local
        // lock, two simultaneous operator presses could both stop the old
        // sink and then publish two new tones on the same WDM attachment.
        let _admission = self.settings_update.lock().map_err(|_| {
            "Timeline cue audio admission lock was poisoned during CUE test".to_owned()
        })?;
        self.stop_explicit_wdm_cue_test_tones_unlocked()?;
        // A second operator press replaces the previous bounded tone instead
        // of accumulating unbounded sources on the independent WDM clock.
        // Capture only the currently published mixer/epoch.  The Sink is
        // created outside the lifecycle mutex, then published back only if
        // the same explicit WDM attachment is still current.  This keeps an
        // output replacement or Stop/Close from leaving a test source on an
        // unowned mixer.
        let (mixer, output_clock_epoch, expected_device_name, expected_topology_fingerprint) = {
            let state = self.state.lock().map_err(|_| {
                "Timeline cue audio lifecycle lock was poisoned during CUE test".to_owned()
            })?;
            let Some(ActiveAsioCueDelivery::ExplicitWdm {
                device_name,
                topology_fingerprint,
            }) = state.active_asio_cue_delivery.as_ref()
            else {
                return Err(
                    "Explicit WDM CUE test requires an active ExplicitWdm delivery".to_owned(),
                );
            };
            let attachment = state.attachment.as_ref().ok_or_else(|| {
                "Explicit WDM CUE test requires a published CUE attachment".to_owned()
            })?;
            let TimelineCueAudioAttachmentOutput::Legacy { mixer, .. } = &attachment.output else {
                return Err(
                    "Explicit WDM CUE test requires the published Legacy WDM CUE attachment"
                        .to_owned(),
                );
            };
            if attachment.route != timeline_cue_audio::TimelineCueAudioRoute::ExplicitDevice {
                return Err(
                    "Explicit WDM CUE test requires the attachment's ExplicitDevice route"
                        .to_owned(),
                );
            }
            if state.resolved_device_name.as_deref() != Some(device_name.as_str())
                || state.observed_topology_fingerprint.as_deref()
                    != Some(topology_fingerprint.as_str())
            {
                return Err(
                    "Explicit WDM CUE test requires the exact published device and topology"
                        .to_owned(),
                );
            }
            (
                mixer.clone(),
                attachment.output_clock_epoch,
                device_name.clone(),
                topology_fingerprint.clone(),
            )
        };

        let frame_count = usize::try_from(
            u64::from(EXPLICIT_WDM_CUE_TEST_TONE_SAMPLE_RATE)
                .saturating_mul(EXPLICIT_WDM_CUE_TEST_TONE_DURATION_MS)
                / 1_000,
        )
        .map_err(|_| "Explicit WDM CUE test tone length is unavailable".to_owned())?;
        let angular_step = std::f32::consts::TAU * EXPLICIT_WDM_CUE_TEST_TONE_FREQUENCY_HZ
            / EXPLICIT_WDM_CUE_TEST_TONE_SAMPLE_RATE as f32;
        let mut samples = Vec::with_capacity(frame_count.saturating_mul(2));
        for frame in 0..frame_count {
            let sample = (angular_step * frame as f32).sin() * EXPLICIT_WDM_CUE_TEST_TONE_PEAK;
            samples.extend([sample, sample]);
        }
        // Keep the source silent until the exact attachment publication has
        // succeeded.  A sink created on the WDM mixer is not owned by the
        // lifecycle until the second state lock below; pause it before any
        // samples are queued so a stale/poisoned publication cannot leak an
        // audible unowned tone.
        let sink = rodio::Sink::connect_new(&mixer);
        sink.pause();
        sink.append(rodio::buffer::SamplesBuffer::new(
            2,
            EXPLICIT_WDM_CUE_TEST_TONE_SAMPLE_RATE,
            samples,
        ));

        let mut state = self.state.lock().map_err(|_| {
            "Timeline cue audio lifecycle lock was poisoned during CUE test publication".to_owned()
        })?;
        let current = state.attachment.as_ref().is_some_and(|attachment| {
            matches!(
                &state.active_asio_cue_delivery,
                Some(ActiveAsioCueDelivery::ExplicitWdm {
                    device_name,
                    topology_fingerprint,
                }) if device_name == &expected_device_name
                    && topology_fingerprint == &expected_topology_fingerprint
            ) && attachment.output_clock_epoch == output_clock_epoch
                && attachment.route == timeline_cue_audio::TimelineCueAudioRoute::ExplicitDevice
                && matches!(
                    &attachment.output,
                    TimelineCueAudioAttachmentOutput::Legacy { .. }
                )
        });
        if !current {
            sink.stop();
            return Err(
                "Explicit WDM CUE output changed before the test tone was published".to_owned(),
            );
        }
        state
            .attachment
            .as_mut()
            .expect("current Explicit WDM attachment")
            .cue_test_sinks
            .push(sink);
        state
            .attachment
            .as_ref()
            .expect("current Explicit WDM attachment")
            .cue_test_sinks
            .last()
            .expect("published Explicit WDM CUE test sink")
            .play();
        Ok(())
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn stop_explicit_wdm_cue_test_tones(&self) -> Result<(), String> {
        let _admission = self.settings_update.lock().map_err(|_| {
            "Timeline cue audio admission lock was poisoned during CUE test stop".to_owned()
        })?;
        self.stop_explicit_wdm_cue_test_tones_unlocked()
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn stop_explicit_wdm_cue_test_tones_unlocked(&self) -> Result<(), String> {
        let sinks = self
            .state
            .lock()
            .map_err(|_| {
                "Timeline cue audio lifecycle lock was poisoned during CUE test stop".to_owned()
            })
            .map(|mut state| {
                state
                    .attachment
                    .as_mut()
                    .map(|attachment| std::mem::take(&mut attachment.cue_test_sinks))
            })?;
        if let Some(sinks) = sinks {
            for sink in sinks {
                sink.stop();
            }
        }
        Ok(())
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn ensure_explicit_wdm_cue_test_output(
        &self,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
        audio: &Arc<Mutex<MediaAudioPlayback>>,
    ) -> Result<(), String> {
        let deadline = Instant::now() + TIMELINE_CUE_AUDIO_PREPARE_TIMEOUT;
        loop {
            if self.explicit_wdm_output_snapshot().is_some() {
                return Ok(());
            }
            // ExplicitWdm is kept ready even for a project with no click,
            // guide, or CUE clip.  Drive the same exact-name/topology worker
            // used by live Timeline CUE instead of opening a test-only or
            // default-device path.
            self.sync_normal(timeline, audio);
            if self.explicit_wdm_output_snapshot().is_some() {
                return Ok(());
            }
            let pending = {
                let state = self.state.lock().map_err(|_| {
                    "Timeline cue audio lifecycle lock was poisoned during CUE test preparation"
                        .to_owned()
                })?;
                if !matches!(
                    state.active_asio_cue_delivery,
                    Some(ActiveAsioCueDelivery::ExplicitWdm { .. })
                ) {
                    return Err(
                        "Explicit WDM CUE test requires an active ExplicitWdm delivery".to_owned(),
                    );
                }
                if state.lifecycle == TimelineCueAudioLifecycle::Fault
                    || state.blocked_settings_revision == Some(state.settings_revision)
                {
                    return Err(state.last_error.clone().unwrap_or_else(|| {
                        "Explicit WDM CUE output preparation failed closed".to_owned()
                    }));
                }
                state.prepare_job.is_some() || state.topology_probe.is_some()
            };
            if Instant::now() >= deadline {
                return Err(if pending {
                    "Explicit WDM CUE test output preparation exceeded 750 ms".to_owned()
                } else {
                    "Explicit WDM CUE test output was not published".to_owned()
                });
            }
            std::thread::sleep(Duration::from_millis(5));
        }
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn asio_cue_route_snapshot(&self) -> AsioCueRouteSnapshot {
        let _route_gate = match self.external_wdm_timeline_route_gate.try_lock() {
            Ok(route_gate) => route_gate,
            Err(TryLockError::WouldBlock | TryLockError::Poisoned(_)) => {
                return AsioCueRouteSnapshot::Busy
            }
        };
        let state = match self.state.try_lock() {
            Ok(state) => state,
            Err(TryLockError::WouldBlock) => return AsioCueRouteSnapshot::Busy,
            Err(TryLockError::Poisoned(_)) => return AsioCueRouteSnapshot::Unavailable,
        };
        Self::asio_cue_route_from_state(&state)
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn asio_cue_route_snapshot_blocking(&self) -> Result<AsioCueRouteSnapshot, String> {
        let _route_gate = self.external_wdm_timeline_route_gate.lock().map_err(|_| {
            "External WDM Timeline route gate was poisoned during ASIO CUE route observation"
                .to_owned()
        })?;
        let state = self.state.lock().map_err(|_| {
            "Timeline cue audio lifecycle lock was poisoned during ASIO CUE route observation"
                .to_owned()
        })?;
        Ok(Self::asio_cue_route_from_state(&state))
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn asio_cue_route_from_state(state: &TimelineCueAudioRuntimeState) -> AsioCueRouteSnapshot {
        match state.active_asio_cue_delivery.as_ref() {
            Some(ActiveAsioCueDelivery::SameAsio) => AsioCueRouteSnapshot::SameAsio,
            Some(ActiveAsioCueDelivery::ExplicitWdm { .. }) => {
                let output = state.attachment.as_ref().and_then(|attachment| {
                    let TimelineCueAudioAttachmentOutput::Legacy { mixer, .. } = &attachment.output
                    else {
                        return None;
                    };
                    (attachment.route == timeline_cue_audio::TimelineCueAudioRoute::ExplicitDevice)
                        .then(|| ExplicitWdmTimelineOutputSnapshot {
                            mixer: mixer.clone(),
                            output_clock_epoch: attachment.output_clock_epoch,
                            owner: ExplicitWdmTimelineOwner::AsioCue,
                        })
                });
                AsioCueRouteSnapshot::ExplicitWdm(output)
            }
            None => AsioCueRouteSnapshot::Unavailable,
        }
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn external_wdm_timeline_route_fence(&self) -> Option<ExternalWdmTimelineRouteFence> {
        let _route_gate = match self.external_wdm_timeline_route_gate.try_lock() {
            Ok(route_gate) => route_gate,
            Err(TryLockError::WouldBlock | TryLockError::Poisoned(_)) => return None,
        };
        let state = match self.state.try_lock() {
            Ok(state) => state,
            Err(TryLockError::WouldBlock | TryLockError::Poisoned(_)) => return None,
        };
        Self::external_wdm_timeline_route_fence_in_state(&state)
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn observe_external_wdm_timeline_route_on_worker_tick(
        &self,
        audio: &Arc<Mutex<MediaAudioPlayback>>,
    ) {
        let fence = self.external_wdm_timeline_route_fence();
        if let Ok(mut playback) = audio.try_lock() {
            // `None` means the lifecycle state could not be observed
            // (busy/poisoned) or is terminal. Retire existing external
            // Timeline sinks immediately; keeping an old sink alive is never
            // a safe fallback. A later tick may publish a fresh exact fence.
            playback.observe_external_wdm_timeline_route(fence);
        }
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn external_wdm_timeline_route_fence_in_state(
        state: &TimelineCueAudioRuntimeState,
    ) -> Option<ExternalWdmTimelineRouteFence> {
        // Terminal lifecycle states are an explicit fail-closed boundary. A
        // stale selected-device description must not look like a live owner
        // after a poison, fault, timeout, or topology failure.
        if matches!(
            state.lifecycle,
            TimelineCueAudioLifecycle::Fault
                | TimelineCueAudioLifecycle::MissingDevice
                | TimelineCueAudioLifecycle::AmbiguousDevice
                | TimelineCueAudioLifecycle::TopologyChanged
                | TimelineCueAudioLifecycle::Stalled
        ) {
            return None;
        }
        let owner = if matches!(
            state.active_asio_cue_delivery,
            Some(ActiveAsioCueDelivery::ExplicitWdm { .. })
        ) {
            Some(ExplicitWdmTimelineOwner::AsioCue)
        } else if state.active_asio_cue_delivery.is_none()
            && state.normal_admission_open
            && state.desired.route == timeline_cue_audio::TimelineCueAudioRoute::ExplicitDevice
        {
            Some(ExplicitWdmTimelineOwner::NormalAuthoring)
        } else {
            None
        };
        Some(ExternalWdmTimelineRouteFence {
            owner,
            generation: owner
                .and_then(|owner| {
                    state.attachment.as_ref().filter(|attachment| {
                        attachment.route
                            == timeline_cue_audio::TimelineCueAudioRoute::ExplicitDevice
                            && matches!(
                                &attachment.output,
                                TimelineCueAudioAttachmentOutput::Legacy { .. }
                            )
                            && match owner {
                                ExplicitWdmTimelineOwner::NormalAuthoring => {
                                    state.active_asio_cue_delivery.is_none()
                                }
                                ExplicitWdmTimelineOwner::AsioCue => matches!(
                                    state.active_asio_cue_delivery,
                                    Some(ActiveAsioCueDelivery::ExplicitWdm { .. })
                                ),
                            }
                    })
                })
                .map(|attachment| attachment.output_clock_epoch)
                // One is a reserved "selected but not publishable" fence. Real
                // attachment epochs start above the state's initialized value.
                .unwrap_or(u64::from(owner.is_some())),
        })
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn lock_external_wdm_timeline_commit(
        &self,
        token: ExternalWdmTimelineRouteFence,
    ) -> Result<ExternalWdmTimelineCommitGuard<'_>, String> {
        // Route writers and this final commit all use gate -> settings ->
        // state. The route gate remains held through the returned guard so a
        // writer cannot invalidate the checked fence before sink install.
        let route_gate = self
            .external_wdm_timeline_route_gate
            .lock()
            .map_err(|_| "External WDM Timeline route gate was poisoned".to_owned())?;
        let admission = self.settings_update.lock().map_err(|_| {
            "Timeline cue audio admission lock was poisoned before Timeline sink commit".to_owned()
        })?;
        let state = self.state.lock().map_err(|_| {
            "Timeline cue audio lifecycle lock was poisoned before Timeline sink commit".to_owned()
        })?;
        if Self::external_wdm_timeline_route_fence_in_state(&state) != Some(token) {
            return Err("External WDM Timeline route changed before sink commit".to_owned());
        }
        drop(state);
        Ok(ExternalWdmTimelineCommitGuard {
            _route_gate: route_gate,
            _settings_update: admission,
        })
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn explicit_wdm_output_is_current_blocking(
        &self,
        token: ExternalWdmTimelineRouteFence,
    ) -> Result<bool, String> {
        let _route_gate = self.external_wdm_timeline_route_gate.lock().map_err(|_| {
            "External WDM Timeline route gate was poisoned during Explicit WDM output observation"
                .to_owned()
        })?;
        let state = self.state.lock().map_err(|_| {
            "Timeline cue audio lifecycle lock was poisoned during Explicit WDM output observation"
                .to_owned()
        })?;
        Ok(Self::explicit_wdm_output_is_current_in_state(&state, token))
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn explicit_wdm_output_is_current_in_state(
        state: &TimelineCueAudioRuntimeState,
        token: ExternalWdmTimelineRouteFence,
    ) -> bool {
        let owner_is_current = match token.owner {
            Some(ExplicitWdmTimelineOwner::NormalAuthoring) => {
                state.active_asio_cue_delivery.is_none()
                    && state.normal_admission_open
                    && state.desired.route
                        == timeline_cue_audio::TimelineCueAudioRoute::ExplicitDevice
                    && state.lifecycle == TimelineCueAudioLifecycle::Running
                    && state.blocked_settings_revision != Some(state.settings_revision)
                    && state.applied.as_ref() == Some(&state.desired)
                    && state.desired.device_name.as_deref() == state.resolved_device_name.as_deref()
                    && state.desired.topology_fingerprint.as_deref()
                        == state.observed_topology_fingerprint.as_deref()
            }
            Some(ExplicitWdmTimelineOwner::AsioCue) => {
                state.lifecycle == TimelineCueAudioLifecycle::Running
                    && state.blocked_settings_revision != Some(state.settings_revision)
                    && matches!(
                        state.active_asio_cue_delivery.as_ref(),
                        Some(ActiveAsioCueDelivery::ExplicitWdm {
                            device_name,
                            topology_fingerprint,
                        }) if Some(device_name.as_str()) == state.resolved_device_name.as_deref()
                            && Some(topology_fingerprint.as_str())
                                == state.observed_topology_fingerprint.as_deref()
                    )
            }
            None => false,
        };
        owner_is_current
            && state.attachment.as_ref().is_some_and(|attachment| {
                attachment.output_clock_epoch == token.generation
                    && attachment.settings_revision == state.settings_revision
                    && attachment.route == timeline_cue_audio::TimelineCueAudioRoute::ExplicitDevice
                    && matches!(
                        &attachment.output,
                        TimelineCueAudioAttachmentOutput::Legacy { .. }
                    )
            })
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn lock_explicit_wdm_timeline_commit(
        &self,
        token: ExternalWdmTimelineRouteFence,
    ) -> Result<ExternalWdmTimelineCommitGuard<'_>, String> {
        // This is the final post-append -> MediaAudioPlayback commit fence.
        // Stop/Close takes the same admission lock before invalidating and
        // retiring the WDM attachment, then drains Timeline sinks after it is
        // released.  Therefore a commit either publishes first and is drained
        // by Stop, or observes the retired epoch and rejects its paused sink.
        let route_gate = self
            .external_wdm_timeline_route_gate
            .lock()
            .map_err(|_| "External WDM Timeline route gate was poisoned".to_owned())?;
        let admission = self.settings_update.lock().map_err(|_| {
            "Timeline cue audio admission lock was poisoned before WDM CUE sink commit".to_owned()
        })?;
        let state = self.state.lock().map_err(|_| {
            "Timeline cue audio lifecycle lock was poisoned before WDM CUE sink commit".to_owned()
        })?;
        if !Self::explicit_wdm_output_is_current_in_state(&state, token) {
            return Err("Explicit WDM Timeline output changed before sink commit".to_owned());
        }
        drop(state);
        Ok(ExternalWdmTimelineCommitGuard {
            _route_gate: route_gate,
            _settings_update: admission,
        })
    }

    fn effective_settings(
        state: &TimelineCueAudioRuntimeState,
    ) -> timeline_cue_audio::MachineTimelineCueAudioSettingsV1 {
        let settings = state.desired.clone();
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let mut settings = settings;
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        if let Some(ActiveAsioCueDelivery::ExplicitWdm {
            device_name,
            topology_fingerprint,
        }) = state.active_asio_cue_delivery.as_ref()
        {
            settings.route = timeline_cue_audio::TimelineCueAudioRoute::ExplicitDevice;
            settings.device_name = Some(device_name.clone());
            settings.topology_fingerprint = Some(topology_fingerprint.clone());
        }
        settings
    }

    /// Close every legacy normal CUE publication before the Router may leave
    /// Normal. A still-running prepare/probe is a pre-admission Busy result:
    /// ASIO Start must not enter Quiescing until the worker has completed and
    /// its JoinHandle plus late result can be reaped here.
    #[cfg(any(
        test,
        all(target_os = "windows", target_arch = "x86_64", feature = "asio")
    ))]
    fn close_normal_routes_for_asio_start(&self) -> Result<(), String> {
        if self.reap_finished_timeline_cue_workers() {
            return Err("Retired Timeline cue audio worker panicked".to_string());
        }
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let route_gate = self
            .external_wdm_timeline_route_gate
            .lock()
            .map_err(|_| "External WDM Timeline route gate was poisoned".to_owned())?;
        let _admission = self
            .settings_update
            .lock()
            .map_err(|_| "Timeline cue audio admission lock was poisoned".to_string())?;
        let (attachment, mut prepare_job, mut topology_probe, retired_workers, busy) = {
            let mut state = self
                .state
                .lock()
                .map_err(|_| "Timeline cue audio lifecycle lock was poisoned".to_string())?;
            state.normal_admission_open = false;
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            {
                state.active_asio_cue_delivery = None;
            }
            let attachment = state.attachment.take();
            clear_asio_retry_barrier(&mut state);
            state.applied = None;
            let busy = state
                .prepare_job
                .as_ref()
                .and_then(|job| job.worker.as_ref())
                .is_some_and(|worker| !worker.is_finished())
                || state
                    .topology_probe
                    .as_ref()
                    .and_then(|probe| probe.worker.as_ref())
                    .is_some_and(|worker| !worker.is_finished())
                || state
                    .retired_workers
                    .iter()
                    .any(|worker| !worker.is_finished());
            if busy {
                // No Router transition has happened yet. Reopen the normal
                // admission so the quarantined worker can finish and be
                // reaped; the operator can retry Start afterward.
                state.normal_admission_open = true;
                state.lifecycle = TimelineCueAudioLifecycle::Stalled;
                state.last_error = Some(
                    "ASIO Start is waiting for a Timeline cue audio worker to finish".to_string(),
                );
                (attachment, None, None, Vec::new(), true)
            } else {
                state.lifecycle = TimelineCueAudioLifecycle::WaitingForProgramOutput;
                state.last_error = None;
                (
                    attachment,
                    state.prepare_job.take(),
                    state.topology_probe.take(),
                    std::mem::take(&mut state.retired_workers),
                    false,
                )
            }
        };
        // The route gate only protects the state transition. Sink retirement
        // and worker joins below are external operations and must not hold it.
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        drop(route_gate);
        if let Some(attachment) = attachment {
            attachment.retire();
        }
        if busy {
            return Err(
                "ASIO Start was not admitted because a Timeline cue audio worker is still running"
                    .to_string(),
            );
        }
        if let Some(job) = prepare_job.as_mut() {
            join_completed_timeline_cue_worker(&mut job.worker)?;
        }
        if let Some(probe) = topology_probe.as_mut() {
            join_completed_timeline_cue_worker(&mut probe.worker)?;
        }
        for worker in retired_workers {
            worker
                .join()
                .map_err(|_| "Retired Timeline cue audio worker panicked".to_string())?;
        }
        // Dropping the completed receivers only after Join closes any late
        // PreparedTimelineCueDestination (including its explicit stream).
        drop(prepare_job);
        drop(topology_probe);
        Ok(())
    }

    /// Retire every independently clocked CUE owner before ASIO PROGRAM
    /// Stop/Close. Unlike the Start preflight above, Stop must continue after
    /// recovering a poisoned lifecycle guard: leaving an already-published WDM
    /// stream alive is less safe than preserving the poison as a visible
    /// terminal warning while the output router is stopped.
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn close_routes_for_asio_stop(&self) -> Option<String> {
        let mut warnings = Vec::<String>::new();
        let mut admission_poisoned = false;
        let route_gate = self
            .external_wdm_timeline_route_gate
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let _admission = match self.settings_update.lock() {
            Ok(guard) => guard,
            Err(poisoned) => {
                admission_poisoned = true;
                warnings.push(
                    "Timeline cue audio admission lock was poisoned during ASIO Stop/Close; restart is required"
                        .to_owned(),
                );
                poisoned.into_inner()
            }
        };

        let (attachment, prepare_job, topology_probe) = match self.state.lock() {
            Ok(mut state) => {
                state.normal_admission_open = false;
                state.active_asio_cue_delivery = None;
                clear_asio_retry_barrier(&mut state);
                state.applied = None;
                if admission_poisoned {
                    state.blocked_settings_revision = Some(state.settings_revision);
                    state.lifecycle = TimelineCueAudioLifecycle::Fault;
                    state.last_error = Some(
                        "Timeline cue audio admission lock was poisoned during ASIO Stop/Close; attachment retired and restart is required"
                            .to_owned(),
                    );
                } else {
                    state.lifecycle = TimelineCueAudioLifecycle::WaitingForProgramOutput;
                    state.last_error = None;
                }
                let mut prepare_job = state.prepare_job.take();
                if let Some(worker) = prepare_job.as_mut().and_then(|job| job.worker.take()) {
                    state.retired_workers.push(worker);
                }
                let mut topology_probe = state.topology_probe.take();
                if let Some(worker) = topology_probe
                    .as_mut()
                    .and_then(|probe| probe.worker.take())
                {
                    state.retired_workers.push(worker);
                }
                (state.attachment.take(), prepare_job, topology_probe)
            }
            Err(poisoned) => {
                let mut state = poisoned.into_inner();
                let warning = "Timeline cue audio state lock was poisoned during ASIO Stop/Close; attachment retired and restart is required".to_owned();
                let attachment = state.attachment.take();
                let mut prepare_job = state.prepare_job.take();
                if let Some(worker) = prepare_job.as_mut().and_then(|job| job.worker.take()) {
                    state.retired_workers.push(worker);
                }
                let mut topology_probe = state.topology_probe.take();
                if let Some(worker) = topology_probe
                    .as_mut()
                    .and_then(|probe| probe.worker.take())
                {
                    state.retired_workers.push(worker);
                }
                state.applied = None;
                state.normal_admission_open = false;
                state.blocked_settings_revision = Some(state.settings_revision);
                state.lifecycle = TimelineCueAudioLifecycle::Fault;
                state.active_asio_cue_delivery = None;
                state.asio_retry_barrier = None;
                state.last_error = Some(warning.clone());
                warnings.push(warning);
                (attachment, prepare_job, topology_probe)
            }
        };
        // Do not hold the route gate while retiring the stream/control or
        // dropping late worker receivers below.
        drop(route_gate);

        if let Some(attachment) = attachment {
            attachment.retire();
        }
        // Dropping the result receivers makes every late prepared stream close
        // in its worker when publication fails.  Keep the JoinHandles in the
        // runtime quarantine and never wait for device I/O before Router
        // Stop/Close has fenced PROGRAM output.
        drop(prepare_job);
        drop(topology_probe);

        (!warnings.is_empty()).then(|| warnings.join("; "))
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn reopen_normal_routes_after_explicit_selection(&self) -> Result<(), String> {
        self.preflight_normal_routes_after_explicit_selection()?;
        let _route_gate = self
            .external_wdm_timeline_route_gate
            .lock()
            .map_err(|_| "External WDM Timeline route gate was poisoned".to_owned())?;
        let _admission = self
            .settings_update
            .lock()
            .map_err(|_| "Timeline cue audio admission lock was poisoned".to_string())?;
        let mut state = self
            .state
            .lock()
            .map_err(|_| "Timeline cue audio lifecycle lock was poisoned".to_string())?;
        if state.prepare_job.is_some()
            || state.topology_probe.is_some()
            || !state.retired_workers.is_empty()
            || state.attachment.is_some()
        {
            return Err(
                "Normal CUE admission cannot reopen while a retired route is still owned"
                    .to_string(),
            );
        }
        state.normal_admission_open = true;
        state.active_asio_cue_delivery = None;
        state.blocked_settings_revision = None;
        clear_asio_retry_barrier(&mut state);
        state.lifecycle = TimelineCueAudioLifecycle::WaitingForProgramOutput;
        state.last_error = None;
        Ok(())
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn preflight_normal_routes_after_explicit_selection(&self) -> Result<(), String> {
        if self.reap_finished_timeline_cue_workers() {
            return Err("Retired Timeline cue audio worker panicked".to_owned());
        }
        let _route_gate = self
            .external_wdm_timeline_route_gate
            .lock()
            .map_err(|_| "External WDM Timeline route gate was poisoned".to_owned())?;
        let _admission = self
            .settings_update
            .lock()
            .map_err(|_| "Timeline cue audio admission lock was poisoned".to_string())?;
        let state = self
            .state
            .lock()
            .map_err(|_| "Timeline cue audio lifecycle lock was poisoned".to_string())?;
        if state.prepare_job.is_some()
            || state.topology_probe.is_some()
            || !state.retired_workers.is_empty()
            || state.attachment.is_some()
        {
            return Err(
                "Normal CUE admission cannot reopen while a retired route is still owned"
                    .to_string(),
            );
        }
        Ok(())
    }

    fn initialize(
        &self,
        settings_path: PathBuf,
        loaded: Result<timeline_cue_audio::MachineTimelineCueAudioSettingsV1, String>,
    ) {
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let route_gate = self.external_wdm_timeline_route_gate.lock().ok();
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        if route_gate.is_none() {
            return;
        }
        let Ok(mut state) = self.state.lock() else {
            return;
        };
        state.settings_path = Some(settings_path);
        state.initialized = true;
        match loaded {
            Ok(settings) => {
                state.desired = settings;
                state.lifecycle = TimelineCueAudioLifecycle::DisabledByProject;
                state.last_error = None;
            }
            Err(error) => {
                state.lifecycle = TimelineCueAudioLifecycle::Fault;
                state.blocked_settings_revision = Some(state.settings_revision);
                state.last_error = Some(error);
            }
        }
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        drop(route_gate);
    }

    fn publish_settings(
        &self,
        settings: timeline_cue_audio::MachineTimelineCueAudioSettingsV1,
    ) -> Result<u64, String> {
        settings.clone().validated()?;
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let route_gate = self
            .external_wdm_timeline_route_gate
            .lock()
            .map_err(|_| "External WDM Timeline route gate was poisoned".to_owned())?;
        let (revision, retired) = {
            let mut state = self
                .state
                .lock()
                .map_err(|_| "Timeline cue audio lifecycle lock was poisoned".to_string())?;
            if state.desired == settings {
                return Ok(state.settings_revision);
            }
            let revision = state
                .settings_revision
                .checked_add(1)
                .ok_or_else(|| "Timeline cue audio settings revision is exhausted".to_string())?;
            let retired = state.attachment.take();
            clear_asio_retry_barrier(&mut state);
            state.desired = settings;
            state.settings_revision = revision;
            state.applied = None;
            state.blocked_settings_revision = None;
            state.lifecycle = TimelineCueAudioLifecycle::Applying;
            state.last_error = None;
            state.config_count = state.config_count.saturating_add(1);
            (revision, retired)
        };
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        drop(route_gate);
        if let Some(attachment) = retired {
            attachment.retire();
        }
        Ok(revision)
    }

    fn status(&self) -> Result<TimelineCueAudioStatus, String> {
        let mut state = match self.state.try_lock() {
            Ok(state) => state,
            Err(TryLockError::WouldBlock) => {
                return Err("Timeline cue audio status is busy; retry".to_string())
            }
            Err(TryLockError::Poisoned(poisoned)) => {
                let state = poisoned.into_inner();
                return Err(state.last_error.clone().unwrap_or_else(|| {
                    "Timeline cue audio state lock was poisoned; restart is required".to_string()
                }));
            }
        };
        let status_revision = state
            .status_revision
            .checked_add(1)
            .filter(|revision| *revision <= VIDEO_CLIP_RUNTIME_GENERATION_MAX)
            .ok_or_else(|| {
                "Timeline cue audio status revision is exhausted; restart is required".to_string()
            })?;
        state.status_revision = status_revision;
        let (
            output_clock_epoch,
            schedule_generation,
            source_fence,
            next_output_frame,
            fault,
            callback_live,
        ) = if let Some(attachment) = state.attachment.as_ref() {
            (
                attachment.output_clock_epoch,
                attachment.engine_identity.schedule_generation,
                attachment.source_fence,
                attachment.control.next_output_frame(),
                attachment.control.fault_status(),
                attachment.last_observed_output_frame > 0
                    && attachment.last_output_progress_at.elapsed()
                        < TIMELINE_CUE_AUDIO_PREPARE_TIMEOUT,
            )
        } else {
            (
                0,
                0,
                0,
                0,
                timeline_cue_audio::TimelineCueFaultStatus {
                    code: timeline_cue_audio::TimelineCueFaultCode::None,
                    count: 0,
                    sequence: 0,
                },
                false,
            )
        };
        let effective_settings = Self::effective_settings(&state);
        // A resolved device is an active-output observation only while the
        // matching attachment is still published and Running. Keep the
        // state value for retry diagnostics, but never expose a retired or
        // faulted output as currently live in the status DTO.
        let resolved_device_name = (state.lifecycle == TimelineCueAudioLifecycle::Running
            && state.applied.is_some()
            && state.attachment.is_some())
        .then(|| state.resolved_device_name.clone())
        .flatten();
        Ok(TimelineCueAudioStatus {
            runtime_incarnation: state.runtime_incarnation,
            status_revision,
            desired_settings: state.desired.clone(),
            applied_settings: state.applied.clone(),
            settings_revision: state.settings_revision,
            lifecycle: state.lifecycle,
            requested_device_name: effective_settings.device_name,
            resolved_device_name,
            requested_topology_fingerprint: effective_settings.topology_fingerprint,
            observed_topology_fingerprint: state.observed_topology_fingerprint.clone(),
            topology_generation: state.topology_generation,
            endpoints: state.endpoints.clone(),
            output_clock_epoch,
            schedule_generation,
            source_fence,
            next_output_frame,
            callback_live,
            fault_code: format!("{:?}", fault.code),
            fault_count: fault.count,
            fault_sequence: fault.sequence,
            last_error: state.last_error.clone(),
            rotation_count: state.rotation_count,
            stall_count: state.stall_count,
            config_count: state.config_count,
        })
    }

    fn spawn_prepare(
        &self,
        fingerprint: TimelineCueAudioPrepareFingerprint,
        settings: timeline_cue_audio::MachineTimelineCueAudioSettingsV1,
        program: Option<TimelineCueProgramDestination>,
    ) -> Result<(), String> {
        self.spawn_prepare_with_after_worker_spawn(fingerprint, settings, program, || {})
    }

    fn spawn_prepare_with_after_worker_spawn(
        &self,
        fingerprint: TimelineCueAudioPrepareFingerprint,
        settings: timeline_cue_audio::MachineTimelineCueAudioSettingsV1,
        program: Option<TimelineCueProgramDestination>,
        after_worker_spawn: impl FnOnce(),
    ) -> Result<(), String> {
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let route_gate = self
            .external_wdm_timeline_route_gate
            .lock()
            .map_err(|_| "External WDM Timeline route gate was poisoned".to_owned())?;
        let admission = self
            .settings_update
            .lock()
            .map_err(|_| "Timeline cue audio admission lock was poisoned".to_string())?;
        let state_result = self
            .state
            .lock()
            .map_err(|_| "Timeline cue audio lifecycle lock was poisoned".to_string());
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        drop(route_gate);
        let normal_admission_open = state_result?.normal_admission_open;
        if !normal_admission_open {
            return Ok(());
        }
        let (sender, receiver) = mpsc::sync_channel(1);
        let worker = std::thread::Builder::new()
            .name("syndocal-timeline-cue-audio-prepare".to_string())
            .spawn(move || {
                let result = match settings.route {
                    timeline_cue_audio::TimelineCueAudioRoute::FollowProgram => program
                        .ok_or_else(|| "Program audio output is not available".to_string())
                        .and_then(prepare_follow_program_timeline_cue_destination)
                        .map(|destination| (destination, Vec::new())),
                    timeline_cue_audio::TimelineCueAudioRoute::ExplicitDevice => {
                        prepare_explicit_timeline_cue_destination(&settings)
                    }
                };
                let _ = sender.send(result);
            })
            .map_err(|error| {
                format!("Timeline cue audio prepare worker could not start: {error}")
            })?;
        after_worker_spawn();
        // Do not reacquire the route gate while the admission guard is held:
        // the final media commit takes gate -> admission.  The worker is now
        // detached from this short admission section and publication below
        // revalidates its fingerprint under the route gate.
        drop(admission);
        let state_result = {
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            let route_gate = self
                .external_wdm_timeline_route_gate
                .lock()
                .map_err(|_| "External WDM Timeline route gate was poisoned".to_owned())?;
            let state = self.state.lock();
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            drop(route_gate);
            state
        };
        let mut state = match state_result {
            Ok(state) => state,
            Err(poisoned) => {
                drop(receiver);
                let error =
                    "Timeline cue audio state lock was poisoned before prepare worker publication"
                        .to_owned();
                let mut state = poisoned.into_inner();
                state.retired_workers.push(worker);
                let (attachment, finished_workers) =
                    transition_timeline_cue_audio_to_terminal_state(
                        &mut state,
                        "normal prepare worker publication",
                        error.clone(),
                        TimelineCueAudioLifecycle::Fault,
                        true,
                    );
                drop(state);
                if let Some(attachment) = attachment {
                    attachment.retire();
                }
                for worker in finished_workers {
                    let _ = worker.join();
                }
                return Err(error);
            }
        };
        if state.prepare_job.is_none()
            && state.topology_probe.is_none()
            && state.settings_revision == fingerprint.settings_revision
            && state.normal_admission_open
        {
            state.prepare_job = Some(TimelineCueAudioPrepareJob {
                fingerprint,
                started_at: Instant::now(),
                receiver,
                timed_out: false,
                worker: Some(worker),
            });
            state.lifecycle = TimelineCueAudioLifecycle::Applying;
        } else {
            // The worker may already be inside device/asset preparation. Keep
            // its JoinHandle owned until a later poll can reap it; dropping a
            // handle here would detach a late normal-output publisher.
            state.retired_workers.push(worker);
        }
        Ok(())
    }

    fn poll_or_spawn_topology_probe(&self) {
        if self.reap_finished_timeline_cue_workers() {
            return;
        }
        let mut retired = None;
        let mut spawn = false;
        let mut finished_worker = None;
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let route_gate = match self.external_wdm_timeline_route_gate.lock() {
            Ok(route_gate) => route_gate,
            Err(_) => {
                self.terminal_fault_and_retire_normal_runtime(
                    "topology probe polling",
                    "External WDM Timeline route gate was poisoned during topology probe polling"
                        .to_owned(),
                );
                return;
            }
        };
        let state_result = self.state.lock();
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        drop(route_gate);
        let mut state = match state_result {
            Ok(state) => state,
            Err(poisoned) => {
                drop(poisoned.into_inner());
                self.terminal_fault_and_retire_normal_runtime(
                    "topology probe polling",
                    "Timeline cue audio state lock was poisoned during topology probe polling"
                        .to_owned(),
                );
                return;
            }
        };
        {
            if let Some(probe) = state.topology_probe.as_mut() {
                match probe.receiver.try_recv() {
                    Ok(Ok((fingerprint, endpoints))) => {
                        let timed_out = probe.timed_out;
                        finished_worker = probe.worker.take();
                        let worker_result = finished_worker
                            .as_ref()
                            .map(|_| Ok(()))
                            .unwrap_or_else(|| {
                                Err("Timeline cue audio topology worker handle was already consumed".to_string())
                        });
                        state.topology_probe = None;
                        state.last_topology_probe_at = Instant::now();
                        if let Some(worker) = finished_worker.take() {
                            state.retired_workers.push(worker);
                        }
                        if let Err(error) = worker_result {
                            retired = state.attachment.take();
                            state.applied = None;
                            state.blocked_settings_revision = Some(state.settings_revision);
                            state.lifecycle = TimelineCueAudioLifecycle::Fault;
                            state.last_error = Some(error);
                        } else if timed_out {
                            retired = state.attachment.take();
                            state.applied = None;
                            state.blocked_settings_revision = Some(state.settings_revision);
                            state.lifecycle = TimelineCueAudioLifecycle::Stalled;
                            state.last_error = Some(
                                "Timeline cue audio ignored a late topology result after its 750 ms timeout"
                                    .to_string(),
                            );
                        } else {
                            if state.observed_topology_fingerprint.as_deref() != Some(&fingerprint)
                            {
                                state.topology_generation =
                                    state.topology_generation.saturating_add(1);
                            }
                            state.observed_topology_fingerprint = Some(fingerprint.clone());
                            state.endpoints = endpoints;
                            let expected = state
                                .applied
                                .as_ref()
                                .and_then(|settings| settings.topology_fingerprint.as_deref());
                            if expected != Some(&fingerprint) {
                                retired = state.attachment.take();
                                state.applied = None;
                                state.blocked_settings_revision = Some(state.settings_revision);
                                state.lifecycle = TimelineCueAudioLifecycle::TopologyChanged;
                                state.last_error = Some(
                                    "Timeline cue audio topology changed; explicitly reselect the device"
                                        .to_string(),
                                );
                            }
                        }
                    }
                    Ok(Err(error)) => {
                        finished_worker = probe.worker.take();
                        let worker_result = finished_worker
                            .as_ref()
                            .map(|_| Ok(()))
                            .unwrap_or_else(|| {
                                Err("Timeline cue audio topology worker handle was already consumed".to_string())
                            });
                        state.topology_probe = None;
                        retired = state.attachment.take();
                        state.applied = None;
                        state.blocked_settings_revision = Some(state.settings_revision);
                        state.lifecycle = TimelineCueAudioLifecycle::Fault;
                        state.last_error = Some(worker_result.err().unwrap_or(error));
                    }
                    Err(mpsc::TryRecvError::Disconnected) => {
                        finished_worker = probe.worker.take();
                        let worker_result = finished_worker
                            .as_ref()
                            .map(|_| Ok(()))
                            .unwrap_or_else(|| {
                                Err("Timeline cue audio topology worker handle was already consumed".to_string())
                            });
                        state.topology_probe = None;
                        retired = state.attachment.take();
                        state.applied = None;
                        state.blocked_settings_revision = Some(state.settings_revision);
                        state.lifecycle = TimelineCueAudioLifecycle::Fault;
                        state.last_error = Some(worker_result.err().unwrap_or_else(|| {
                            "Timeline cue audio topology worker disconnected".to_string()
                        }));
                    }
                    Err(mpsc::TryRecvError::Empty) => {
                        if !probe.timed_out
                            && probe.started_at.elapsed() >= TIMELINE_CUE_AUDIO_PREPARE_TIMEOUT
                        {
                            probe.timed_out = true;
                            retired = state.attachment.take();
                            state.applied = None;
                            state.blocked_settings_revision = Some(state.settings_revision);
                            state.stall_count = state.stall_count.saturating_add(1);
                            state.lifecycle = TimelineCueAudioLifecycle::Stalled;
                            state.last_error = Some(
                                "Timeline cue audio topology probe exceeded 750 ms; the single worker is quarantined and restart is required"
                                    .to_string(),
                            );
                        }
                    }
                }
            } else if state.normal_admission_open
                && state.prepare_job.is_none()
                && state.attachment.as_ref().is_some_and(|attachment| {
                    attachment.route == timeline_cue_audio::TimelineCueAudioRoute::ExplicitDevice
                })
                && state.last_topology_probe_at.elapsed() >= Duration::from_secs(2)
            {
                spawn = true;
            }
            if let Some(worker) = finished_worker.take() {
                state.retired_workers.push(worker);
            }
        }
        drop(state);
        if let Some(attachment) = retired {
            attachment.retire();
        }
        if !spawn {
            return;
        }
        let normal_admission_open = {
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            let route_gate = match self.external_wdm_timeline_route_gate.lock() {
                Ok(route_gate) => route_gate,
                Err(_) => {
                    self.terminal_fault_and_retire_normal_runtime(
                        "topology probe admission",
                        "External WDM Timeline route gate was poisoned before topology probe admission"
                            .to_owned(),
                    );
                    return;
                }
            };
            let admission = match self.settings_update.lock() {
                Ok(admission) => admission,
                Err(poisoned) => {
                    drop(poisoned.into_inner());
                    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                    drop(route_gate);
                    self.terminal_fault_and_retire_normal_runtime(
                        "topology probe admission",
                        "Timeline cue audio admission lock was poisoned during topology probe; attachment retired and restart is required"
                            .to_owned(),
                    );
                    return;
                }
            };
            let state_result = self.state.lock();
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            drop(route_gate);
            drop(admission);
            match state_result {
                Ok(state) => state.normal_admission_open,
                Err(poisoned) => {
                    drop(poisoned.into_inner());
                    self.terminal_fault_and_retire_normal_runtime(
                        "topology probe publication",
                        "Timeline cue audio state lock was poisoned before topology probe publication"
                            .to_owned(),
                    );
                    return;
                }
            }
        };
        if !normal_admission_open {
            return;
        }
        let (sender, receiver) = mpsc::sync_channel(1);
        let worker = match std::thread::Builder::new()
            .name("syndocal-timeline-cue-audio-topology".to_string())
            .spawn(move || {
                let result = enumerate_timeline_cue_audio_outputs()
                    .map(|(_, fingerprint, endpoints)| (fingerprint, endpoints));
                let _ = sender.send(result);
            }) {
            Ok(worker) => worker,
            Err(_) => {
                self.fail_prepare("Timeline cue audio topology worker could not start".to_string());
                return;
            }
        };
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let route_gate = match self.external_wdm_timeline_route_gate.lock() {
            Ok(route_gate) => route_gate,
            Err(_) => {
                worker.join().ok();
                self.terminal_fault_and_retire_normal_runtime(
                    "topology probe worker publication",
                    "External WDM Timeline route gate was poisoned before topology probe worker publication"
                        .to_owned(),
                );
                return;
            }
        };
        let admission = match self.settings_update.lock() {
            Ok(admission) => admission,
            Err(poisoned) => {
                #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                drop(route_gate);
                drop(poisoned.into_inner());
                self.terminal_fault_and_retire_normal_runtime(
                    "topology probe worker publication",
                    "Timeline cue audio admission lock was poisoned before topology probe worker publication"
                        .to_owned(),
                );
                worker.join().ok();
                return;
            }
        };
        let state_result = self.state.lock();
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        drop(route_gate);
        drop(admission);
        let mut state = match state_result {
            Ok(state) => state,
            Err(poisoned) => {
                let mut state = poisoned.into_inner();
                state.retired_workers.push(worker);
                drop(state);
                self.terminal_fault_and_retire_normal_runtime(
                    "topology probe worker publication",
                    "Timeline cue audio state lock was poisoned before topology probe worker publication"
                        .to_owned(),
                );
                return;
            }
        };
        if state.topology_probe.is_none()
            && state.prepare_job.is_none()
            && state.normal_admission_open
        {
            state.topology_probe = Some(TimelineCueAudioTopologyProbe {
                started_at: Instant::now(),
                timed_out: false,
                receiver,
                worker: Some(worker),
            });
        } else {
            state.retired_workers.push(worker);
        }
    }

    #[cfg(any(
        test,
        not(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))
    ))]
    fn sync(
        &self,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
        audio: &Arc<Mutex<MediaAudioPlayback>>,
    ) {
        self.sync_normal(timeline, audio);
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn sync_with_output_router(
        &self,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
        audio: &Arc<Mutex<MediaAudioPlayback>>,
        output_router: Option<&Arc<audio_output_router::RouterSlot>>,
        asio_output_runtime: Option<&Arc<Mutex<asio_output_runtime::AsioOutputRuntime>>>,
    ) {
        // The test seam has no process-wide Router/runtime and intentionally
        // keeps the legacy in-memory mixer path. Production always supplies
        // both owners from MediaAudioSyncRuntime::start.
        if output_router.is_none() && asio_output_runtime.is_none() {
            self.sync_normal(timeline, audio);
            return;
        }
        let Some(output_router) = output_router else {
            self.retire_timeline_cue_attachment_for_router_state(
                TimelineCueAudioLifecycle::Fault,
                "ASIO output router process owner is unavailable during Timeline cue sync"
                    .to_string(),
            );
            return;
        };
        let router_state = match output_router.snapshot() {
            Ok(snapshot) => snapshot.state,
            Err(error) => {
                self.retire_timeline_cue_attachment_for_router_state(
                    TimelineCueAudioLifecycle::Fault,
                    router_error("Timeline cue sync router snapshot", error),
                );
                return;
            }
        };
        if router_state == audio_output_router::State::AsioActive {
            let delivery_result = {
                let _route_gate = match self.external_wdm_timeline_route_gate.try_lock() {
                    Ok(route_gate) => route_gate,
                    Err(TryLockError::WouldBlock | TryLockError::Poisoned(_)) => return,
                };
                match self.state.try_lock() {
                    Ok(state) => Ok(state.active_asio_cue_delivery.clone()),
                    Err(TryLockError::WouldBlock) => {
                        // Lock contention is not evidence that the published CUE
                        // delivery disappeared. Preserve the attachment and retry
                        // on the next scheduler tick.
                        return;
                    }
                    Err(TryLockError::Poisoned(_)) => Err(
                        "Timeline cue audio state lock was poisoned during ASIO CUE delivery observation"
                            .to_owned(),
                    ),
                }
            };
            let delivery = match delivery_result {
                Ok(delivery) => delivery,
                Err(error) => {
                    self.retire_timeline_cue_attachment_for_router_state(
                        TimelineCueAudioLifecycle::Fault,
                        error,
                    );
                    return;
                }
            };
            match delivery {
                Some(ActiveAsioCueDelivery::SameAsio) => {
                    let Some(asio_output_runtime) = asio_output_runtime else {
                        self.retire_timeline_cue_attachment_for_router_state(
                            TimelineCueAudioLifecycle::Fault,
                            "ASIO output runtime owner is unavailable during Timeline cue sync"
                                .to_string(),
                        );
                        return;
                    };
                    self.sync_asio_active(timeline, asio_output_runtime);
                }
                Some(ActiveAsioCueDelivery::ExplicitWdm { .. }) => {
                    // The external endpoint is an explicit, independently
                    // clocked CUE route. PROGRAM remains owned exclusively by
                    // the active ASIO session; this path may never fall back to
                    // FollowProgram or an OS default device.
                    self.retire_incompatible_asio_cue_attachment();
                    self.sync_normal(timeline, audio);
                }
                None => self.retire_timeline_cue_attachment_for_router_state(
                    TimelineCueAudioLifecycle::Fault,
                    "ASIO CUE delivery was not published for the active session".to_string(),
                ),
            }
        } else if router_state == audio_output_router::State::Normal {
            // Normal is the only state that owns the legacy CUE admission.
            // Every transitional/locked/faulted ASIO state stays silent and
            // must not probe or open a normal device as an implicit fallback.
            self.retire_incompatible_asio_cue_attachment();
            self.sync_normal(timeline, audio);
        } else {
            self.retire_timeline_cue_attachment_for_router_state(
                if router_state == audio_output_router::State::Fault {
                    TimelineCueAudioLifecycle::Fault
                } else {
                    TimelineCueAudioLifecycle::WaitingForProgramOutput
                },
                format!(
                    "Timeline cue audio is unavailable while the output router is {router_state:?}"
                ),
            );
        }
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn take_timeline_cue_attachment_for_retirement<F>(
        &self,
        operation: &str,
        retire_state: F,
    ) -> Option<TimelineCueAudioAttachment>
    where
        F: FnOnce(&mut TimelineCueAudioRuntimeState) -> Option<TimelineCueAudioAttachment>,
    {
        let state_result = {
            // A poisoned route gate is recovered deliberately: leaving the
            // attachment live after a route-writer panic would violate the
            // fail-closed retirement boundary.
            let route_gate = self
                .external_wdm_timeline_route_gate
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            let state = self.state.lock();
            let result = state.map(|mut state| (retire_state(&mut state), Vec::new()));
            drop(route_gate);
            result
        };
        let (retired, finished_workers) = match state_result {
            Ok(result) => result,
            Err(poisoned) => {
                // A poisoned lifecycle lock is not a reason to leave a live
                // WDM/ASIO stream or a late normal-output publisher behind.
                // Consume the poisoned guard, drop every result receiver, keep
                // unfinished workers runtime-owned, reap finished workers, and
                // keep every future admission fail-closed.
                let mut state = poisoned.into_inner();
                transition_timeline_cue_audio_to_terminal_state(
                    &mut state,
                    operation,
                    String::new(),
                    TimelineCueAudioLifecycle::Fault,
                    true,
                )
            }
        };
        for worker in finished_workers {
            let _ = worker.join();
        }
        retired
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn retire_timeline_cue_attachment(&self) {
        let retired = self.take_timeline_cue_attachment_for_retirement(
            "Timeline cue attachment retirement",
            |state| {
                let retired = state.attachment.take();
                if retired.is_some() {
                    state.applied = None;
                    if state.lifecycle == TimelineCueAudioLifecycle::Running {
                        state.lifecycle = TimelineCueAudioLifecycle::WaitingForProgramOutput;
                    }
                }
                retired
            },
        );
        if let Some(attachment) = retired {
            attachment.retire();
        }
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn retire_incompatible_asio_cue_attachment(&self) {
        let retired = self.take_timeline_cue_attachment_for_retirement(
            "incompatible ASIO CUE attachment retirement",
            |state| {
                let is_asio = state.attachment.as_ref().is_some_and(|attachment| {
                    matches!(
                        &attachment.output,
                        TimelineCueAudioAttachmentOutput::AsioCue { .. }
                    )
                });
                if !is_asio {
                    return None;
                }
                state.applied = None;
                state.lifecycle = TimelineCueAudioLifecycle::WaitingForProgramOutput;
                state.last_error = Some(
                    "ASIO Timeline CUE attachment was retired before returning to Normal output"
                        .to_string(),
                );
                state.blocked_settings_revision = None;
                state.attachment.take()
            },
        );
        if let Some(attachment) = retired {
            attachment.retire();
        }
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn retire_timeline_cue_attachment_for_router_state(
        &self,
        lifecycle: TimelineCueAudioLifecycle,
        error: String,
    ) {
        let (attachment, finished_workers) = {
            let route_gate = self
                .external_wdm_timeline_route_gate
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            let (mut state, state_poisoned) = match self.state.lock() {
                Ok(state) => (state, false),
                Err(poisoned) => (poisoned.into_inner(), true),
            };
            let transition = transition_timeline_cue_audio_to_terminal_state(
                &mut state,
                "router-state retirement",
                error,
                lifecycle,
                state_poisoned,
            );
            drop(route_gate);
            transition
        };
        if let Some(attachment) = attachment {
            attachment.retire();
        }
        for worker in finished_workers {
            let _ = worker.join();
        }
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn retire_asio_for_output_retry(
        &self,
        error: String,
        fallback_identity: Option<TimelineCueEngineIdentity>,
    ) {
        let retired = self.take_timeline_cue_attachment_for_retirement(
            "ASIO output retry retirement",
            |state| {
                let barrier = state
                    .attachment
                    .as_ref()
                    .map(|attachment| attachment.engine_identity.clone())
                    .or(fallback_identity);
                state.asio_retry_barrier = barrier;
                state.applied = None;
                state.lifecycle = TimelineCueAudioLifecycle::Applying;
                state.last_error = Some(error);
                state.attachment.take()
            },
        );
        if let Some(attachment) = retired {
            attachment.retire();
        }
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn create_asio_attachment(
        &self,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
        asio_output_runtime: &Arc<Mutex<asio_output_runtime::AsioOutputRuntime>>,
        expected_output_identity: asio_timeline_output::TimelineOutputIdentity,
        settings: &timeline_cue_audio::MachineTimelineCueAudioSettingsV1,
        settings_revision: u64,
    ) -> Result<TimelineCueAudioAttachment, String> {
        // Validate the complete engine authority before allocating or
        // publishing a source.  A malformed/stale event batch must not leave
        // an otherwise valid ASIO sink behind when construction is rejected.
        let engine_identity = timeline_cue_engine_identity(timeline)?;
        let canonical_anchor_frame = timeline_cue_canonical_frame(timeline.position_ms)?;
        let (output_clock_epoch, source_fence) = {
            let route_gate = self
                .external_wdm_timeline_route_gate
                .lock()
                .map_err(|_| "External WDM Timeline route gate was poisoned".to_owned())?;
            let state = self
                .state
                .lock()
                .map_err(|_| "Timeline cue audio lifecycle lock was poisoned".to_string())?;
            let epochs = (
                state
                    .next_output_clock_epoch
                    .checked_add(1)
                    .ok_or_else(|| "Timeline cue audio output epoch is exhausted".to_string())?,
                state
                    .next_source_fence
                    .checked_add(1)
                    .ok_or_else(|| "Timeline cue audio source fence is exhausted".to_string())?,
            );
            drop(state);
            drop(route_gate);
            epochs
        };
        let authority = timeline_cue_audio::TimelineCueAuthority {
            fence: timeline_cue_audio::TimelineCueFence {
                output_clock_epoch,
                schedule_generation: engine_identity.schedule_generation,
                source_fence,
            },
            clock: timeline_cue_audio::TimelineCueClockMap {
                canonical_anchor_frame,
                output_anchor_frame: 0,
            },
        };
        let assets = timeline_cue_audio::GuideAssetBank::prepare_embedded(
            timeline_cue_audio::TIMELINE_CUE_CANONICAL_SAMPLE_RATE,
        )?;
        let (control, source) = timeline_cue_audio::create_timeline_cue_audio_source(
            timeline_cue_audio::TIMELINE_CUE_CANONICAL_SAMPLE_RATE,
            2,
            timeline_cue_audio::MAX_TIMELINE_CUE_QUEUE_CAPACITY,
            assets,
            authority,
            settings.click_gain,
            settings.guide_gain,
        )?;
        #[cfg(test)]
        let source_instance_token = match next_timeline_cue_audio_source_instance_token() {
            Ok(token) => token,
            Err(error) => {
                control.retire();
                return Err(error);
            }
        };
        // Do not attach the physical source yet.  The attachment is first
        // published and fed so the exact-anchor/future batch is in the
        // control queue before an ASIO callback can advance output_frame.
        // Revalidate the route now, then `activate_pending_source` performs
        // the final identity check immediately after admission.
        match asio_output_runtime.lock() {
            Ok(mut runtime) => {
                let current = runtime
                    .current_output_identity(protocol::TimelineAudioOutputBus::Cue)
                    .map_err(|error| error.to_string());
                match current {
                    Ok(current) if current == expected_output_identity => {}
                    Ok(current) => {
                        control.retire();
                        return Err(format!(
                            "ASIO CUE output identity changed before attachment: expected {expected_output_identity:?}, got {current:?}"
                        ));
                    }
                    Err(error) => {
                        control.retire();
                        return Err(error);
                    }
                }
            }
            Err(_) => {
                control.retire();
                return Err("ASIO output runtime lock was poisoned".to_string());
            }
        }
        Ok(TimelineCueAudioAttachment {
            control,
            output: TimelineCueAudioAttachmentOutput::AsioCue {
                identity: expected_output_identity,
                sink: None,
            },
            pending_source: Some(source),
            #[cfg(test)]
            source_instance_token,
            #[cfg(test)]
            source_test_counters: TimelineCueAudioSourceTestCounters::default(),
            cue_test_sinks: Vec::new(),
            route: settings.route,
            settings_revision,
            program_device_generation: None,
            engine_identity,
            output_clock_epoch,
            canonical_anchor_frame,
            source_fence,
            next_sequence: 1,
            last_click_key: None,
            last_guide_generation: None,
            last_guide_sequence: 0,
            blocked_event_identity: None,
            last_observed_output_frame: 0,
            last_output_progress_at: Instant::now(),
        })
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn sync_asio_active(
        &self,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
        asio_output_runtime: &Arc<Mutex<asio_output_runtime::AsioOutputRuntime>>,
    ) {
        if self.reap_finished_timeline_cue_workers() {
            return;
        }
        let project_enabled = timeline.metronome_enabled || timeline.guide_enabled;
        let (settings, settings_revision) = {
            let (route_gate, mut state) = match self.lock_external_wdm_route_state() {
                Ok(guards) => guards,
                Err(poisoned) => {
                    self.terminal_fault_and_retire_normal_runtime(
                        "ASIO scheduler admission",
                        poisoned,
                    );
                    return;
                }
            };
            if state.normal_admission_open
                || state.prepare_job.is_some()
                || state.topology_probe.is_some()
                || !state.retired_workers.is_empty()
            {
                let retired = state.attachment.take();
                state.lifecycle = TimelineCueAudioLifecycle::Fault;
                state.blocked_settings_revision = Some(state.settings_revision);
                state.last_error = Some(
                    "ASIO Active encountered a legacy Timeline cue audio worker; normal route is quarantined"
                        .to_string(),
                );
                drop(state);
                drop(route_gate);
                if let Some(attachment) = retired {
                    attachment.retire();
                }
                return;
            }
            if !state.initialized {
                return;
            }
            if !project_enabled {
                let retired = state.attachment.take();
                state.asio_retry_barrier = None;
                state.lifecycle = TimelineCueAudioLifecycle::DisabledByProject;
                state.applied = None;
                drop(state);
                drop(route_gate);
                if let Some(attachment) = retired {
                    attachment.retire();
                }
                return;
            }
            if state.blocked_settings_revision == Some(state.settings_revision) {
                let retired = state.attachment.take();
                drop(state);
                if let Some(attachment) = retired {
                    attachment.retire();
                }
                return;
            }
            (state.desired.clone(), state.settings_revision)
        };

        // This is the authoritative ASIO session/transport observation.  It
        // both rejects a non-Active/faulted runtime and lets us retire a sink
        // that became stale even when the engine identity did not change.
        let current_output_identity_result = match asio_output_runtime.lock() {
            Ok(mut runtime) => {
                runtime.current_output_identity(protocol::TimelineAudioOutputBus::Cue)
            }
            Err(_) => Err("ASIO output runtime lock was poisoned".to_string()),
        };
        let current_output_identity = match current_output_identity_result {
            Ok(identity) => identity,
            Err(error) => {
                self.retire_timeline_cue_attachment();
                self.fail_prepare(error);
                return;
            }
        };
        let (should_attach, output_identity_rotated) = match self.lock_external_wdm_route_state() {
            Ok((route_gate, state)) => {
                let output_identity_rotated = state.attachment.as_ref().is_some_and(|attachment| {
                    matches!(
                        &attachment.output,
                        TimelineCueAudioAttachmentOutput::AsioCue { identity, .. }
                            if *identity != current_output_identity
                    )
                });
                let should_attach = !state.attachment.as_ref().is_some_and(|attachment| {
                    matches!(
                        &attachment.output,
                        TimelineCueAudioAttachmentOutput::AsioCue { identity, .. }
                            if *identity == current_output_identity
                    ) && attachment.settings_revision == settings_revision
                });
                drop(state);
                drop(route_gate);
                (should_attach, output_identity_rotated)
            }
            Err(error) => {
                self.terminal_fault_and_retire_normal_runtime("ASIO attachment observation", error);
                return;
            }
        };

        if should_attach {
            let mut attachment = match self.create_asio_attachment(
                timeline,
                asio_output_runtime,
                current_output_identity,
                &settings,
                settings_revision,
            ) {
                Ok(attachment) => attachment,
                Err(error) => {
                    if error.contains("identity changed") {
                        self.retire_asio_for_output_retry(
                            error,
                            timeline_cue_engine_identity(timeline).ok(),
                        );
                    } else {
                        self.retire_timeline_cue_attachment();
                        self.fail_prepare(error);
                    }
                    return;
                }
            };
            let (route_gate, mut state) = match self.lock_external_wdm_route_state() {
                Ok(guards) => guards,
                Err(error) => {
                    attachment.retire();
                    self.terminal_fault_and_retire_normal_runtime(
                        "ASIO attachment publication",
                        error,
                    );
                    return;
                }
            };
            if state.normal_admission_open
                || state.settings_revision != settings_revision
                || state.blocked_settings_revision == Some(settings_revision)
            {
                drop(state);
                drop(route_gate);
                attachment.retire();
                return;
            }
            let suppress_current_events = state
                .asio_retry_barrier
                .as_ref()
                .is_some_and(|barrier| barrier == &attachment.engine_identity)
                || (output_identity_rotated
                    && state
                        .attachment
                        .as_ref()
                        .is_some_and(|old| old.engine_identity == attachment.engine_identity));
            let old = state.attachment.take();
            if suppress_current_events {
                // A transport-only rotation can race one engine snapshot. Do
                // not replay that snapshot into the fresh ASIO sink; the next
                // engine authority change re-arms publication.
                attachment.blocked_event_identity = Some(attachment.engine_identity.clone());
            }
            state.asio_retry_barrier = None;
            state.next_output_clock_epoch = attachment.output_clock_epoch;
            state.next_source_fence = attachment.source_fence;
            state.rotation_count = state.rotation_count.saturating_add(1);
            state.applied = Some(settings);
            // The source is still detached. `feed_attachment_with_asio` must
            // admit its first batch and activate it before exposing Running.
            state.lifecycle = TimelineCueAudioLifecycle::Applying;
            state.last_error = None;
            state.attachment = Some(attachment);
            drop(state);
            drop(route_gate);
            if let Some(old) = old {
                old.retire();
            }
        }
        self.feed_attachment_with_asio(timeline, asio_output_runtime, current_output_identity);
    }

    fn sync_normal(
        &self,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
        audio: &Arc<Mutex<MediaAudioPlayback>>,
    ) {
        self.sync_normal_with_after_initial_state(timeline, audio, || {});
    }

    fn sync_normal_with_after_initial_state(
        &self,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
        audio: &Arc<Mutex<MediaAudioPlayback>>,
        after_initial_state: impl FnOnce(),
    ) {
        if self.reap_finished_timeline_cue_workers() {
            return;
        }
        // An explicit authoring monitor is also the destination for every
        // Timeline media clip. Guide/Click are optional, so a project that
        // contains only library media must still keep the exact WDM
        // attachment published before its first clip becomes active.
        let project_content_enabled = timeline.metronome_enabled
            || timeline.guide_enabled
            || !timeline.clips.is_empty()
            || !timeline.child_clips.is_empty();
        let mut retired = None;
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let route_gate = match self.external_wdm_timeline_route_gate.lock() {
            Ok(route_gate) => route_gate,
            Err(_) => {
                self.terminal_fault_and_retire_normal_runtime(
                    "normal scheduler admission",
                    "External WDM Timeline route gate was poisoned during normal scheduler admission"
                        .to_owned(),
                );
                return;
            }
        };
        let state_result = self.state.lock();
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        drop(route_gate);
        let project_enabled = match state_result {
            Ok(mut state) => {
                #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                let external_cue_delivery_active = matches!(
                    state.active_asio_cue_delivery,
                    Some(ActiveAsioCueDelivery::ExplicitWdm { .. })
                );
                #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
                let external_cue_delivery_active = false;
                let project_enabled = project_content_enabled || external_cue_delivery_active;
                if !state.normal_admission_open {
                    retired = state.attachment.take();
                    state.applied = None;
                    state.lifecycle = TimelineCueAudioLifecycle::WaitingForProgramOutput;
                } else if !state.initialized
                    || (state.blocked_settings_revision == Some(state.settings_revision)
                        && state.prepare_job.is_none())
                {
                    return;
                } else if !project_enabled {
                    retired = state.attachment.take();
                    state.lifecycle = TimelineCueAudioLifecycle::DisabledByProject;
                    state.applied = None;
                }
                project_enabled
            }
            Err(poisoned) => {
                drop(poisoned.into_inner());
                self.terminal_fault_and_retire_normal_runtime(
                    "normal scheduler admission",
                    "Timeline cue audio state lock was poisoned during normal scheduler admission"
                        .to_owned(),
                );
                return;
            }
        };
        if let Some(attachment) = retired {
            attachment.retire();
        }
        after_initial_state();
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let route_gate = match self.external_wdm_timeline_route_gate.try_lock() {
            Ok(route_gate) => route_gate,
            Err(TryLockError::WouldBlock | TryLockError::Poisoned(_)) => return,
        };
        let state_result = self.state.try_lock();
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        drop(route_gate);
        match state_result {
            Ok(state) if !state.normal_admission_open => return,
            Ok(state) => drop(state),
            Err(TryLockError::WouldBlock) => return,
            Err(TryLockError::Poisoned(poisoned)) => {
                drop(poisoned.into_inner());
                self.terminal_fault_and_retire_normal_runtime(
                    "normal scheduler revalidation",
                    "Timeline cue audio state lock was poisoned during normal scheduler revalidation"
                        .to_owned(),
                );
                return;
            }
        }
        if !project_enabled {
            return;
        }

        self.poll_or_spawn_topology_probe();

        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let route_gate = match self.external_wdm_timeline_route_gate.try_lock() {
            Ok(route_gate) => route_gate,
            Err(TryLockError::WouldBlock | TryLockError::Poisoned(_)) => return,
        };
        let state_result = self.state.try_lock();
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        drop(route_gate);
        let route = match state_result {
            Ok(state) => Self::effective_settings(&state).route,
            Err(TryLockError::WouldBlock) => return,
            Err(TryLockError::Poisoned(poisoned)) => {
                drop(poisoned.into_inner());
                self.terminal_fault_and_retire_normal_runtime(
                    "normal route observation",
                    "Timeline cue audio state lock was poisoned during normal route observation"
                        .to_owned(),
                );
                return;
            }
        };
        let program = if route == timeline_cue_audio::TimelineCueAudioRoute::FollowProgram {
            match audio.try_lock() {
                Ok(playback) => timeline_cue_program_destination(&playback),
                Err(TryLockError::WouldBlock) => {
                    // A busy Program mixer is not evidence that the physical
                    // stream disappeared. Preserve the exact attachment and
                    // retry this observational capture on the next worker tick.
                    return;
                }
                Err(TryLockError::Poisoned(_)) => {
                    self.fail_prepare("Media audio playback lock was poisoned".to_string());
                    return;
                }
            }
        } else {
            None
        };

        let mut completed = None;
        let mut spawn = None;
        let mut retired_worker = None;
        let mut retired_after_prepare_timeout = None;
        let mut prepare_timed_out = false;
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let route_gate = match self.external_wdm_timeline_route_gate.lock() {
            Ok(route_gate) => route_gate,
            Err(_) => {
                self.terminal_fault_and_retire_normal_runtime(
                    "normal prepare polling",
                    "External WDM Timeline route gate was poisoned during normal prepare polling"
                        .to_owned(),
                );
                return;
            }
        };
        let state_result = self.state.lock();
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        drop(route_gate);
        let mut state = match state_result {
            Ok(state) => state,
            Err(poisoned) => {
                drop(poisoned.into_inner());
                self.terminal_fault_and_retire_normal_runtime(
                    "normal prepare polling",
                    "Timeline cue audio state lock was poisoned during normal prepare polling"
                        .to_owned(),
                );
                return;
            }
        };
        {
            if let Some(job) = state.prepare_job.as_mut() {
                match job.receiver.try_recv() {
                    Ok(result) => {
                        let fingerprint = job.fingerprint;
                        let timed_out = job.timed_out;
                        retired_worker = job.worker.take();
                        let worker_result =
                            retired_worker.as_ref().map(|_| Ok(())).unwrap_or_else(|| {
                                Err(
                                    "Timeline cue audio prepare worker handle was already consumed"
                                        .to_string(),
                                )
                            });
                        completed = Some((
                            fingerprint,
                            timed_out,
                            worker_result.map(|()| result).unwrap_or_else(Err),
                        ));
                        state.prepare_job = None;
                    }
                    Err(mpsc::TryRecvError::Disconnected) => {
                        retired_worker = job.worker.take();
                        let worker_result =
                            retired_worker.as_ref().map(|_| Ok(())).unwrap_or_else(|| {
                                Err(
                                    "Timeline cue audio prepare worker handle was already consumed"
                                        .to_string(),
                                )
                            });
                        completed = Some((
                            job.fingerprint,
                            job.timed_out,
                            Err(worker_result.err().unwrap_or_else(|| {
                                "Timeline cue audio prepare worker disconnected".to_string()
                            })),
                        ));
                        state.prepare_job = None;
                    }
                    Err(mpsc::TryRecvError::Empty) => {
                        if !job.timed_out
                            && job.started_at.elapsed() >= TIMELINE_CUE_AUDIO_PREPARE_TIMEOUT
                        {
                            job.timed_out = true;
                            prepare_timed_out = true;
                            state.stall_count = state.stall_count.saturating_add(1);
                            state.lifecycle = TimelineCueAudioLifecycle::Stalled;
                            state.blocked_settings_revision = Some(state.settings_revision);
                            state.last_error = Some(
                                "Timeline cue audio preparation exceeded 750 ms; the single worker is quarantined"
                                    .to_string(),
                            );
                        }
                    }
                }
            }
            if prepare_timed_out {
                retired_after_prepare_timeout = state.attachment.take();
                state.applied = None;
            }
            if let Some(worker) = retired_worker.take() {
                state.retired_workers.push(worker);
            }
            if completed.is_none() {
                let program_generation = program.as_ref().map(|value| value.device_generation);
                let effective_settings = Self::effective_settings(&state);
                let attachment_valid = state.attachment.as_ref().is_some_and(|attachment| {
                    attachment.settings_revision == state.settings_revision
                        && attachment.route == effective_settings.route
                        && attachment.program_device_generation == program_generation
                });
                if !attachment_valid
                    && state.normal_admission_open
                    && state.prepare_job.is_none()
                    && state.topology_probe.is_none()
                {
                    if route == timeline_cue_audio::TimelineCueAudioRoute::FollowProgram
                        && program.is_none()
                    {
                        state.lifecycle = TimelineCueAudioLifecycle::WaitingForProgramOutput;
                    } else {
                        spawn = Some((
                            TimelineCueAudioPrepareFingerprint {
                                settings_revision: state.settings_revision,
                                program_device_generation: program_generation,
                            },
                            effective_settings,
                        ));
                    }
                }
            }
        }
        drop(state);
        if let Some(attachment) = retired_after_prepare_timeout {
            attachment.retire();
        }
        if prepare_timed_out {
            return;
        }

        if let Some((fingerprint, timed_out, result)) = completed {
            if !timed_out {
                self.complete_prepare(fingerprint, result, timeline, program.as_ref());
            }
        }
        if let Some((fingerprint, settings)) = spawn {
            if let Err(error) = self.spawn_prepare(fingerprint, settings, program) {
                self.fail_prepare(error);
            }
            return;
        }
        self.feed_attachment(timeline, program.as_ref());
    }

    fn complete_prepare(
        &self,
        fingerprint: TimelineCueAudioPrepareFingerprint,
        result: Result<
            (
                PreparedTimelineCueDestination,
                Vec<TimelineCueAudioEndpointSummary>,
            ),
            String,
        >,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
        program: Option<&TimelineCueProgramDestination>,
    ) {
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let route_gate = match self.external_wdm_timeline_route_gate.try_lock() {
            Ok(route_gate) => route_gate,
            Err(TryLockError::WouldBlock | TryLockError::Poisoned(_)) => return,
        };
        let state_result = self.state.try_lock();
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        drop(route_gate);
        let current = match state_result {
            Ok(state) => {
                state
                    .normal_admission_open
                    .then_some(TimelineCueAudioPrepareFingerprint {
                        settings_revision: state.settings_revision,
                        program_device_generation: program.map(|value| value.device_generation),
                    })
            }
            Err(TryLockError::WouldBlock) => return,
            Err(TryLockError::Poisoned(poisoned)) => {
                drop(poisoned.into_inner());
                self.terminal_fault_and_retire_normal_runtime(
                    "normal prepare completion preflight",
                    "Timeline cue audio state lock was poisoned during normal prepare completion preflight"
                        .to_owned(),
                );
                return;
            }
        };
        if current != Some(fingerprint) {
            return;
        }
        let (destination, endpoints) = match result {
            Ok(result) => result,
            Err(error) => {
                self.fail_prepare(error);
                return;
            }
        };
        let identity = match timeline_cue_engine_identity(timeline) {
            Ok(identity) => identity,
            Err(error) => {
                self.fail_prepare(error);
                return;
            }
        };
        let canonical_anchor_frame = match timeline_cue_canonical_frame(timeline.position_ms) {
            Ok(frame) => frame,
            Err(error) => {
                self.fail_prepare(error);
                return;
            }
        };
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let route_gate = match self.external_wdm_timeline_route_gate.lock() {
            Ok(route_gate) => route_gate,
            Err(_) => {
                self.terminal_fault_and_retire_normal_runtime(
                    "normal prepare completion",
                    "External WDM Timeline route gate was poisoned during normal prepare completion"
                        .to_owned(),
                );
                return;
            }
        };
        let state_result = self.state.lock();
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        drop(route_gate);
        let mut state = match state_result {
            Ok(state) => state,
            Err(poisoned) => {
                drop(poisoned.into_inner());
                self.terminal_fault_and_retire_normal_runtime(
                    "normal prepare completion",
                    "Timeline cue audio state lock was poisoned during normal prepare completion"
                        .to_owned(),
                );
                return;
            }
        };
        if !state.normal_admission_open {
            return;
        }
        let Some(output_clock_epoch) = state.next_output_clock_epoch.checked_add(1) else {
            let retired = state.attachment.take();
            state.applied = None;
            state.lifecycle = TimelineCueAudioLifecycle::Fault;
            state.last_error = Some("Timeline cue audio output epoch is exhausted".to_string());
            state.blocked_settings_revision = Some(state.settings_revision);
            drop(state);
            if let Some(attachment) = retired {
                attachment.retire();
            }
            return;
        };
        let Some(source_fence) = state.next_source_fence.checked_add(1) else {
            let retired = state.attachment.take();
            state.applied = None;
            state.lifecycle = TimelineCueAudioLifecycle::Fault;
            state.last_error = Some("Timeline cue audio source fence is exhausted".to_string());
            state.blocked_settings_revision = Some(state.settings_revision);
            drop(state);
            if let Some(attachment) = retired {
                attachment.retire();
            }
            return;
        };
        let authority = timeline_cue_audio::TimelineCueAuthority {
            fence: timeline_cue_audio::TimelineCueFence {
                output_clock_epoch,
                schedule_generation: identity.schedule_generation.max(1),
                source_fence,
            },
            clock: timeline_cue_audio::TimelineCueClockMap {
                canonical_anchor_frame,
                output_anchor_frame: 0,
            },
        };
        let settings = Self::effective_settings(&state);
        let created = timeline_cue_audio::create_timeline_cue_audio_source(
            destination.output_sample_rate,
            destination.channels,
            timeline_cue_audio::MAX_TIMELINE_CUE_QUEUE_CAPACITY,
            destination.assets,
            authority,
            settings.click_gain,
            settings.guide_gain,
        );
        let (control, source) = match created {
            Ok(created) => created,
            Err(error) => {
                let retired = state.attachment.take();
                state.applied = None;
                state.lifecycle = TimelineCueAudioLifecycle::Fault;
                state.last_error = Some(error);
                state.blocked_settings_revision = Some(state.settings_revision);
                drop(state);
                if let Some(attachment) = retired {
                    attachment.retire();
                }
                return;
            }
        };
        #[cfg(test)]
        let source_instance_token = match next_timeline_cue_audio_source_instance_token() {
            Ok(token) => token,
            Err(error) => {
                control.retire();
                let retired = state.attachment.take();
                state.applied = None;
                state.lifecycle = TimelineCueAudioLifecycle::Fault;
                state.last_error = Some(error);
                state.blocked_settings_revision = Some(state.settings_revision);
                drop(state);
                if let Some(attachment) = retired {
                    attachment.retire();
                }
                return;
            }
        };
        if let Some(old) = state.attachment.take() {
            old.retire();
        }
        state.next_output_clock_epoch = output_clock_epoch;
        state.next_source_fence = source_fence;
        state.rotation_count = state.rotation_count.saturating_add(1);
        state.resolved_device_name = destination.resolved_device_name.clone();
        state.observed_topology_fingerprint = destination.topology_fingerprint.clone();
        if !endpoints.is_empty() {
            state.endpoints = endpoints;
            state.topology_generation = state.topology_generation.saturating_add(1);
        }
        state.applied = Some(settings.clone());
        // The source is still detached. `feed_attachment` must admit its
        // first batch and activate it before exposing Running.
        state.lifecycle = TimelineCueAudioLifecycle::Applying;
        state.last_error = None;
        state.attachment = Some(TimelineCueAudioAttachment {
            control,
            output: TimelineCueAudioAttachmentOutput::Legacy {
                mixer: destination.mixer,
                _explicit_stream: destination.explicit_stream,
            },
            pending_source: Some(source),
            #[cfg(test)]
            source_instance_token,
            #[cfg(test)]
            source_test_counters: TimelineCueAudioSourceTestCounters::default(),
            cue_test_sinks: Vec::new(),
            route: settings.route,
            settings_revision: state.settings_revision,
            program_device_generation: destination.program_device_generation,
            engine_identity: identity,
            output_clock_epoch,
            canonical_anchor_frame,
            source_fence,
            next_sequence: 1,
            last_click_key: None,
            last_guide_generation: None,
            last_guide_sequence: 0,
            blocked_event_identity: None,
            last_observed_output_frame: 0,
            last_output_progress_at: Instant::now(),
        });
        drop(state);
        self.feed_attachment(timeline, program);
    }

    fn fail_prepare(&self, error: String) {
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let route_gate = match self.external_wdm_timeline_route_gate.lock() {
            Ok(route_gate) => route_gate,
            Err(_) => {
                self.terminal_fault_and_retire_normal_runtime(
                    "prepare failure publication",
                    "External WDM Timeline route gate was poisoned during prepare failure publication"
                        .to_owned(),
                );
                return;
            }
        };
        let state_result = self.state.lock();
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        drop(route_gate);
        let retired = match state_result {
            Ok(mut state) => {
                state.lifecycle = if error.contains("missing") {
                    TimelineCueAudioLifecycle::MissingDevice
                } else if error.contains("ambiguous") {
                    TimelineCueAudioLifecycle::AmbiguousDevice
                } else if error.contains("topology changed") {
                    TimelineCueAudioLifecycle::TopologyChanged
                } else {
                    TimelineCueAudioLifecycle::Fault
                };
                state.applied = None;
                state.blocked_settings_revision = Some(state.settings_revision);
                state.last_error = Some(error);
                state.attachment.take()
            }
            Err(poisoned) => {
                drop(poisoned.into_inner());
                self.terminal_fault_and_retire_normal_runtime(
                    "prepare failure publication",
                    "Timeline cue audio state lock was poisoned during prepare failure publication"
                        .to_owned(),
                );
                return;
            }
        };
        if let Some(attachment) = retired {
            attachment.retire();
        }
    }

    fn retire_taken_attachment_as_fault(
        state: &mut TimelineCueAudioRuntimeState,
        attachment: TimelineCueAudioAttachment,
        error: String,
    ) {
        attachment.retire();
        state.applied = None;
        state.blocked_settings_revision = Some(state.settings_revision);
        state.lifecycle = TimelineCueAudioLifecycle::Fault;
        state.last_error = Some(error);
    }

    fn feed_attachment(
        &self,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
        program: Option<&TimelineCueProgramDestination>,
    ) {
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        self.feed_attachment_inner(timeline, program, None, None);
        #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
        self.feed_attachment_inner(timeline, program);
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn feed_attachment_with_asio(
        &self,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
        asio_output_runtime: &Arc<Mutex<asio_output_runtime::AsioOutputRuntime>>,
        expected_output_identity: asio_timeline_output::TimelineOutputIdentity,
    ) {
        self.feed_attachment_inner(
            timeline,
            None,
            Some(asio_output_runtime),
            Some(expected_output_identity),
        );
    }

    fn feed_attachment_inner(
        &self,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
        program: Option<&TimelineCueProgramDestination>,
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        asio_output_runtime: Option<&Arc<Mutex<asio_output_runtime::AsioOutputRuntime>>>,
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        expected_output_identity: Option<asio_timeline_output::TimelineOutputIdentity>,
    ) {
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let mut asio_runtime_guard = match asio_output_runtime {
            Some(runtime) => match runtime.lock() {
                Ok(runtime) => Some(runtime),
                Err(_) => {
                    self.retire_timeline_cue_attachment();
                    self.fail_prepare("ASIO output runtime lock was poisoned".to_string());
                    return;
                }
            },
            None => None,
        };
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        if let (Some(runtime), Some(expected)) =
            (asio_runtime_guard.as_mut(), expected_output_identity)
        {
            match runtime.current_output_identity(protocol::TimelineAudioOutputBus::Cue) {
                Ok(current) if current == expected => {}
                Ok(current) => {
                    drop(asio_runtime_guard);
                    self.retire_asio_for_output_retry(format!(
                        "ASIO CUE output identity changed before Timeline cue publication: expected {expected:?}, got {current:?}"
                    ), None);
                    return;
                }
                Err(error) => {
                    drop(asio_runtime_guard);
                    self.retire_timeline_cue_attachment();
                    self.fail_prepare(error);
                    return;
                }
            }
        }
        let identity = match timeline_cue_engine_identity(timeline) {
            Ok(identity) => identity,
            Err(error) => {
                #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                let route_gate = match self.external_wdm_timeline_route_gate.try_lock() {
                    Ok(route_gate) => route_gate,
                    Err(TryLockError::WouldBlock | TryLockError::Poisoned(_)) => return,
                };
                let state_result = self.state.try_lock();
                #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                drop(route_gate);
                match state_result {
                    Ok(mut state) => {
                        if let Some(attachment) = state.attachment.take() {
                            attachment.retire();
                        }
                        state.applied = None;
                        state.lifecycle = TimelineCueAudioLifecycle::Fault;
                        state.last_error = Some(error);
                        state.blocked_settings_revision = Some(state.settings_revision);
                    }
                    Err(TryLockError::WouldBlock) => {}
                    Err(TryLockError::Poisoned(poisoned)) => {
                        drop(poisoned.into_inner());
                        self.terminal_fault_and_retire_normal_runtime(
                            "Timeline cue identity failure",
                            "Timeline cue audio state lock was poisoned while publishing an identity failure"
                                .to_owned(),
                        );
                    }
                }
                return;
            }
        };
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let route_gate = match self.external_wdm_timeline_route_gate.try_lock() {
            Ok(route_gate) => route_gate,
            Err(TryLockError::WouldBlock | TryLockError::Poisoned(_)) => return,
        };
        let state_result = self.state.try_lock();
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        drop(route_gate);
        let mut state = match state_result {
            Ok(state) => state,
            Err(TryLockError::WouldBlock) => return,
            Err(TryLockError::Poisoned(poisoned)) => {
                drop(poisoned.into_inner());
                self.terminal_fault_and_retire_normal_runtime(
                    "Timeline cue feed",
                    "Timeline cue audio state lock was poisoned during Timeline cue feed"
                        .to_owned(),
                );
                return;
            }
        };
        let Some(mut attachment) = state.attachment.take() else {
            return;
        };
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        if let Some(expected) = expected_output_identity {
            let attachment_identity = match &attachment.output {
                TimelineCueAudioAttachmentOutput::AsioCue { identity, .. } => *identity,
                TimelineCueAudioAttachmentOutput::Legacy { .. } => {
                    Self::retire_taken_attachment_as_fault(
                        &mut state,
                        attachment,
                        "ASIO Active encountered a legacy Timeline cue attachment".to_string(),
                    );
                    return;
                }
            };
            if attachment_identity != expected {
                let engine_identity = attachment.engine_identity.clone();
                attachment.retire();
                state.asio_retry_barrier = Some(engine_identity);
                state.applied = None;
                state.lifecycle = TimelineCueAudioLifecycle::Applying;
                state.last_error = Some(
                    "ASIO CUE attachment identity changed before Timeline cue publication"
                        .to_string(),
                );
                return;
            }
        }
        let observed_output_frame = attachment.control.next_output_frame();
        if observed_output_frame != attachment.last_observed_output_frame {
            attachment.last_observed_output_frame = observed_output_frame;
            attachment.last_output_progress_at = Instant::now();
        } else if attachment.last_output_progress_at.elapsed() >= TIMELINE_CUE_AUDIO_PREPARE_TIMEOUT
        {
            attachment.retire();
            state.applied = None;
            state.blocked_settings_revision = Some(state.settings_revision);
            state.lifecycle = TimelineCueAudioLifecycle::Stalled;
            state.stall_count = state.stall_count.saturating_add(1);
            state.last_error =
                Some("Timeline cue audio callback has not advanced for 750 ms".to_string());
            return;
        }
        if matches!(
            &attachment.output,
            TimelineCueAudioAttachmentOutput::Legacy { .. }
        ) && attachment.route == timeline_cue_audio::TimelineCueAudioRoute::FollowProgram
            && program.map(|value| value.device_generation) != attachment.program_device_generation
        {
            attachment.retire();
            state.applied = None;
            state.lifecycle = TimelineCueAudioLifecycle::WaitingForProgramOutput;
            return;
        }
        if identity != attachment.engine_identity {
            let canonical_anchor_frame = match timeline_cue_canonical_frame(timeline.position_ms) {
                Ok(frame) => frame,
                Err(error) => {
                    Self::retire_taken_attachment_as_fault(&mut state, attachment, error);
                    return;
                }
            };
            let Some(output_clock_epoch) = state.next_output_clock_epoch.checked_add(1) else {
                Self::retire_taken_attachment_as_fault(
                    &mut state,
                    attachment,
                    "Timeline cue audio output epoch is exhausted".to_string(),
                );
                return;
            };
            let Some(source_fence) = state.next_source_fence.checked_add(1) else {
                Self::retire_taken_attachment_as_fault(
                    &mut state,
                    attachment,
                    "Timeline cue audio source fence is exhausted".to_string(),
                );
                return;
            };
            let authority = timeline_cue_audio::TimelineCueAuthority {
                fence: timeline_cue_audio::TimelineCueFence {
                    output_clock_epoch,
                    schedule_generation: identity.schedule_generation.max(1),
                    source_fence,
                },
                clock: timeline_cue_audio::TimelineCueClockMap {
                    canonical_anchor_frame,
                    output_anchor_frame: 0,
                },
            };
            if let Err(error) = attachment.control.publish_authority(authority) {
                Self::retire_taken_attachment_as_fault(&mut state, attachment, error);
                return;
            }
            let source_result = attachment.control.new_source();
            let output_result = match source_result {
                Ok(source) => {
                    #[cfg(test)]
                    let source_instance_token =
                        match next_timeline_cue_audio_source_instance_token() {
                            Ok(token) => token,
                            Err(error) => {
                                Self::retire_taken_attachment_as_fault(
                                    &mut state, attachment, error,
                                );
                                return;
                            }
                        };
                    match &mut attachment.output {
                        TimelineCueAudioAttachmentOutput::Legacy { .. } => {
                            attachment.pending_source = Some(source);
                            #[cfg(test)]
                            {
                                attachment.source_instance_token = source_instance_token;
                            }
                            Ok(())
                        }
                        #[cfg(all(
                            target_os = "windows",
                            target_arch = "x86_64",
                            feature = "asio"
                        ))]
                        TimelineCueAudioAttachmentOutput::AsioCue {
                            identity: asio_identity,
                            sink,
                        } => (|| {
                            let expected = expected_output_identity.ok_or_else(|| {
                                "ASIO output identity is unavailable during Timeline cue rotation"
                                    .to_string()
                            })?;
                            if *asio_identity != expected {
                                return Err(format!(
                                "ASIO CUE attachment identity changed before rotation: expected {expected:?}, got {:?}",
                                *asio_identity
                            ));
                            }
                            if let Some(previous_sink) = sink.take() {
                                #[cfg(test)]
                                attachment
                                    .source_test_counters
                                    .retirements
                                    .fetch_add(1, Ordering::Relaxed);
                                previous_sink.stop();
                            }
                            attachment.pending_source = Some(source);
                            #[cfg(test)]
                            {
                                attachment.source_instance_token = source_instance_token;
                            }
                            Ok(())
                        })(),
                    }
                }
                Err(error) => Err(error),
            };
            if let Err(error) = output_result {
                if error.contains("identity changed") {
                    set_asio_retry_barrier(&mut state, attachment.engine_identity.clone());
                    state.applied = None;
                    state.lifecycle = TimelineCueAudioLifecycle::Applying;
                    state.last_error = Some(error);
                    attachment.retire();
                    return;
                }
                Self::retire_taken_attachment_as_fault(&mut state, attachment, error);
                return;
            }
            attachment.output_clock_epoch = output_clock_epoch;
            attachment.canonical_anchor_frame = canonical_anchor_frame;
            attachment.source_fence = source_fence;
            attachment.engine_identity = identity.clone();
            attachment.next_sequence = 1;
            attachment.last_click_key = None;
            attachment.last_guide_generation = None;
            attachment.last_guide_sequence = 0;
            attachment.blocked_event_identity = None;
            state.next_output_clock_epoch = output_clock_epoch;
            state.next_source_fence = source_fence;
            state.rotation_count = state.rotation_count.saturating_add(1);
        }
        let fence = timeline_cue_audio::TimelineCueFence {
            output_clock_epoch: attachment.output_clock_epoch,
            schedule_generation: attachment.engine_identity.schedule_generation.max(1),
            source_fence: attachment.source_fence,
        };
        // A rotated/new attachment is anchored at the current Timeline
        // position. The engine deliberately retains historical click/Guide
        // entries as watermarks, but mapping any such entry would require a
        // negative output frame. Skip only those pre-anchor entries; never
        // clamp or rewrite them, and keep the exact-anchor event admissible.
        let canonical_anchor_frame = attachment.canonical_anchor_frame;
        if attachment.blocked_event_identity.as_ref() == Some(&identity) {
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            let activation_result = Self::activate_pending_source(
                &mut attachment,
                asio_runtime_guard.as_mut().map(|runtime| &mut **runtime),
                expected_output_identity,
            );
            #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
            let activation_result = Self::activate_pending_source(&mut attachment);
            if let Err(error) = activation_result {
                #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                if error.contains("identity changed") {
                    let engine_identity = attachment.engine_identity.clone();
                    attachment.retire();
                    set_asio_retry_barrier(&mut state, engine_identity);
                    state.applied = None;
                    state.lifecycle = TimelineCueAudioLifecycle::Applying;
                    state.last_error = Some(error);
                    return;
                }
                Self::retire_taken_attachment_as_fault(&mut state, attachment, error);
                return;
            }
            state.lifecycle = TimelineCueAudioLifecycle::Running;
            state.attachment = Some(attachment);
            return;
        }
        let mut pending = Vec::<(u64, u8, timeline_cue_audio::TimelineCueEventKind, u16)>::new();
        if timeline.metronome_enabled {
            for click in &timeline.click_events {
                let key = (
                    click.sample_frame,
                    click.measure,
                    click.beat,
                    click.count_in,
                );
                if attachment.last_click_key.is_some_and(|last| key <= last) {
                    continue;
                }
                if click.sample_frame < canonical_anchor_frame {
                    continue;
                }
                pending.push((
                    click.sample_frame,
                    1,
                    timeline_cue_audio::TimelineCueEventKind::Click {
                        accented: click.downbeat || click.count_in,
                    },
                    1_000,
                ));
            }
        }
        if timeline.guide_enabled {
            let current_generation = timeline.guide_cues.last().map(|guide| guide.generation);
            for guide in &timeline.guide_cues {
                if Some(guide.generation) != current_generation {
                    continue;
                }
                if attachment.last_guide_generation == Some(guide.generation)
                    && guide.sequence <= attachment.last_guide_sequence
                {
                    continue;
                }
                if guide.sample_frame < canonical_anchor_frame {
                    continue;
                }
                pending.push((
                    guide.sample_frame,
                    0,
                    timeline_cue_audio::TimelineCueEventKind::Guide {
                        asset: native_timeline_guide_asset_key(guide.asset),
                    },
                    guide.playback_rate_milli,
                ));
            }
        }
        pending.sort_by_key(|(frame, priority, _, _)| (*frame, *priority));
        let mut events = Vec::with_capacity(pending.len());
        let mut next_sequence = attachment.next_sequence;
        for (canonical_frame, _, kind, playback_rate_milli) in pending {
            events.push(timeline_cue_audio::TimelineCueEvent {
                canonical_frame,
                sequence: next_sequence,
                kind,
                playback_rate_milli,
            });
            let Some(next) = next_sequence.checked_add(1) else {
                Self::retire_taken_attachment_as_fault(
                    &mut state,
                    attachment,
                    "Timeline cue audio event sequence is exhausted".to_string(),
                );
                return;
            };
            next_sequence = next;
        }
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        if let (Some(runtime), Some(expected)) =
            (asio_runtime_guard.as_mut(), expected_output_identity)
        {
            let attachment_identity = match &attachment.output {
                TimelineCueAudioAttachmentOutput::AsioCue { identity, .. } => *identity,
                TimelineCueAudioAttachmentOutput::Legacy { .. } => {
                    Self::retire_taken_attachment_as_fault(
                        &mut state,
                        attachment,
                        "ASIO Active encountered a legacy Timeline cue attachment".to_string(),
                    );
                    return;
                }
            };
            match runtime.current_output_identity(protocol::TimelineAudioOutputBus::Cue) {
                Ok(current) if current == expected && attachment_identity == expected => {}
                Ok(current) => {
                    let engine_identity = attachment.engine_identity.clone();
                    attachment.retire();
                    state.asio_retry_barrier = Some(engine_identity);
                    state.applied = None;
                    state.lifecycle = TimelineCueAudioLifecycle::Applying;
                    state.last_error = Some(format!(
                        "ASIO CUE output identity changed before Timeline cue enqueue: expected {expected:?}, got {current:?}"
                    ));
                    return;
                }
                Err(error) => {
                    attachment.retire();
                    state.applied = None;
                    state.blocked_settings_revision = Some(state.settings_revision);
                    state.lifecycle = TimelineCueAudioLifecycle::Fault;
                    state.last_error = Some(error);
                    return;
                }
            }
        }
        let latest_click_key = timeline.click_events.last().map(|click| {
            (
                click.sample_frame,
                click.measure,
                click.beat,
                click.count_in,
            )
        });
        let latest_guide_progress = timeline
            .guide_cues
            .last()
            .map(|guide| (guide.generation, guide.sequence));
        let enqueue_succeeded = if !events.is_empty() {
            if let Err(error) = attachment.control.enqueue_batch(fence, &events) {
                // An active source must not survive a failed publication:
                // retaining its mixer/Sink would allow stale queued audio to
                // continue while the visible state reports Fault.  The
                // attachment is retired before returning, and its event
                // watermarks remain unchanged because this branch never
                // reaches the successful watermark commit below.
                Self::retire_taken_attachment_as_fault(&mut state, attachment, error);
                return;
            } else {
                attachment.next_sequence = next_sequence;
                true
            }
        } else {
            // A batch containing only retained pre-anchor history is still a
            // successful observation. Advance the watermarks so that the
            // same history is not reconsidered on every scheduler tick.
            true
        };
        if enqueue_succeeded {
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            let activation_result = Self::activate_pending_source(
                &mut attachment,
                asio_runtime_guard.as_mut().map(|runtime| &mut **runtime),
                expected_output_identity,
            );
            #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
            let activation_result = Self::activate_pending_source(&mut attachment);
            if let Err(error) = activation_result {
                #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                if error.contains("identity changed") {
                    let engine_identity = attachment.engine_identity.clone();
                    attachment.retire();
                    set_asio_retry_barrier(&mut state, engine_identity);
                    state.applied = None;
                    state.lifecycle = TimelineCueAudioLifecycle::Applying;
                    state.last_error = Some(error);
                    return;
                }
                Self::retire_taken_attachment_as_fault(&mut state, attachment, error);
                return;
            }
        }
        if enqueue_succeeded {
            if let Some(key) = latest_click_key {
                // The Timeline projection is ordered; preserve its existing
                // last-entry watermark contract rather than changing it to a
                // max-over-history policy.
                attachment.last_click_key = Some(key);
            }
            if let Some((generation, sequence)) = latest_guide_progress {
                attachment.last_guide_generation = Some(generation);
                attachment.last_guide_sequence = sequence;
            }
        }
        let output_frame = attachment.control.next_output_frame();
        if output_frame != attachment.last_observed_output_frame {
            attachment.last_observed_output_frame = output_frame;
            attachment.last_output_progress_at = Instant::now();
        }
        if attachment.blocked_event_identity.is_none() {
            state.lifecycle = TimelineCueAudioLifecycle::Running;
        }
        state.attachment = Some(attachment);
    }
}

#[derive(Default)]
struct MediaAudioPlayback {
    /// On the Windows ASIO product path, the PROGRAM stream is sealed in a
    /// router-issued lease. It must never be replaced or dropped directly by
    /// media playback.
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    normal_output: Option<normal_audio_output::NormalAudioOutput>,
    /// A failed Router retirement retains the exact stream for an explicit
    /// retry. Keeping only an error string here would leak an exclusive route.
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    pending_normal_output_retirements: Vec<PendingNormalOutputRetirement>,
    #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
    stream: Option<DirectMediaAudioOutput>,
    #[cfg(test)]
    timeline_test_mixer: Option<rodio::mixer::Mixer>,
    device_name: Option<String>,
    requested_device_name: Option<String>,
    /// Runtime-only ABA fence for output-stream replacement. Timeline decoder
    /// preparation happens without holding `media_audio`; installation must
    /// reject a stream/mixer captured before any intervening device rotation.
    audio_device_generation: u64,
    /// Runtime-only fence for the independently clocked explicit WDM CUE
    /// assignment. Zero means no external CUE assignment; one means selected
    /// but not currently publishable; larger values identify a live mixer.
    hybrid_cue_output_generation: u64,
    /// Distinguishes the Normal authoring monitor (all Timeline buses) from
    /// the show-ASIO split CUE route (CUE bus only). The epoch alone cannot
    /// express that ownership transition.
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    external_wdm_timeline_owner: Option<ExplicitWdmTimelineOwner>,
    sinks: HashMap<VideoLayerId, rodio::Sink>,
    sources: HashMap<VideoLayerId, MediaAudioSourceConfig>,
    last_resync_at: HashMap<VideoLayerId, Instant>,
    timeline_sinks: HashMap<TimelineAudioSinkKey, rodio::Sink>,
    timeline_sources: HashMap<TimelineAudioSinkKey, TimelineAudioSourceConfig>,
    /// Converts Rodio's output-time `Sink::get_pos` back into Timeline's
    /// authoritative source-time coordinates. It is runtime-only and is
    /// retired with the sink; no project image can restore a stale clock.
    timeline_source_clocks: HashMap<TimelineAudioSinkKey, TimelineAudioSourceClock>,
    timeline_failures: HashMap<TimelineAudioSinkKey, TimelineAudioPlaybackFailure>,
    timeline_last_resync_at: HashMap<TimelineAudioSinkKey, Instant>,
    timeline_transport: TimelineAudioTransportState,
    timeline_source_projection_authority: Option<engine::TimelineAudioProjectionAuthority>,
    resync_count: u64,
    last_drift_ms: i64,
    max_abs_drift_ms: u64,
    last_sync_error: Option<String>,
    timeline_last_sync_error: Option<String>,
    #[cfg(test)]
    timeline_start_attempt_count: u64,
    #[cfg(test)]
    timeline_stop_count: u64,
    #[cfg(test)]
    timeline_last_install_source_position_ms: HashMap<TimelineAudioSinkKey, u64>,
}

/// Root clips retain their historic id domain. Child clips are isolated by the root activation,
/// the full nested Scene Block path, and source clip id, so parallel placements at any supported
/// nesting depth never steal or stop one another's sink.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
enum TimelineAudioSinkKey {
    Root(TimelineAudioClipId),
    Child {
        parent_event_id: TimelineEventId,
        parent_iteration: u64,
        path: Arc<[ChildTimelineTransportPathSegment]>,
        clip_id: TimelineAudioClipId,
    },
    DirectChild {
        parent_cue_id: CueId,
        generation: u64,
        path: Arc<[ChildTimelineTransportPathSegment]>,
        clip_id: TimelineAudioClipId,
    },
    Follow {
        source_timeline_id: TimelineId,
        target_timeline_id: TimelineId,
        generation: u64,
        target_root: bool,
        path: Arc<[ChildTimelineTransportPathSegment]>,
        clip_id: TimelineAudioClipId,
    },
}

#[derive(Debug, Clone)]
struct MediaAudioSourceConfig {
    path: PathBuf,
    volume: f32,
    requested_device_name: Option<String>,
}

#[derive(Debug, Clone, PartialEq)]
struct TimelineAudioSourceConfig {
    path: PathBuf,
    gain: f32,
    offset_ms: u64,
    /// Authoritative runtime varispeed. This deliberately changes pitch with
    /// duration because Timeline audio uses Rodio's `Sink::set_speed`.
    speed_milli: u32,
    /// This is a logical source identity. Device/channel selection remains a
    /// separate machine-local router concern; until that integration lands,
    /// a PROGRAM/CUE change must still retire the old sink before rebuilding.
    output_bus: protocol::TimelineAudioOutputBus,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TimelineAudioSourceClock {
    /// Source-time position at `output_anchor_ms`, including the initial
    /// decoder seek or a successful drift re-seek.
    source_anchor_ms: u64,
    /// Rodio output-time position sampled at the same instant. `Sink::get_pos`
    /// is not source time while varispeed is active.
    output_anchor_ms: u64,
}

#[derive(Debug, Clone, PartialEq)]
struct TimelineAudioPlaybackFailure {
    source: TimelineAudioSourceConfig,
    error: String,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct TimelineAudioTransportState {
    playing: bool,
    position_ms: u64,
    transport_revision: u64,
    synced_at: Option<Instant>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TimelineAudioTransportAction {
    Stop,
    Recue,
    Sync,
}

#[derive(Debug, Clone)]
struct TimelineAudioPrepareRequest {
    key: TimelineAudioSinkKey,
    clip: TimelineAudioClipSummary,
    source_position_ms: u64,
    volume: f32,
    source: TimelineAudioSourceConfig,
}

struct TimelineAudioSeekRequest {
    key: TimelineAudioSinkKey,
    clip_id: TimelineAudioClipId,
    sink: rodio::Sink,
    source_position_ms: u64,
    speed_milli: u32,
}

struct TimelineAudioSyncPlan {
    authority: engine::TimelineAudioProjectionAuthority,
    device_generation: u64,
    hybrid_cue_output_generation: u64,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    external_wdm_timeline_owner: Option<ExplicitWdmTimelineOwner>,
    requested_device_name: Option<String>,
    mixer: Option<rodio::mixer::Mixer>,
    prepares: Vec<TimelineAudioPrepareRequest>,
    seeks: Vec<TimelineAudioSeekRequest>,
    errors: Vec<String>,
    /// CUE belongs to an independently owned monitor route. Its failures stay
    /// visible, but they must never fault PROGRAM/Follow settlement.
    cue_errors: Vec<String>,
}

enum PreparedMediaAudioOutput {
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    Router(normal_audio_output::NormalAudioOutput),
    #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
    Direct {
        stream: DirectMediaAudioOutput,
        mixer: rodio::mixer::Mixer,
        device_name: Option<String>,
        requested_device_name: Option<String>,
    },
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio", test))]
    Test { mixer: rodio::mixer::Mixer },
}

impl PreparedMediaAudioOutput {
    fn mixer(&self) -> rodio::mixer::Mixer {
        match self {
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            Self::Router(output) => output.mixer(),
            #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
            Self::Direct { mixer, .. } => mixer.clone(),
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio", test))]
            Self::Test { mixer } => mixer.clone(),
        }
    }
}

/// Owns a newly-published PROGRAM output until the timeline prepare commit has
/// transferred it into `MediaAudioPlayback`. Every early return remains
/// router-governed: the Drop path only retires the sealed lease after the
/// playback mutex is no longer held.
struct PreparedMediaAudioOutputGuard {
    output: Option<PreparedMediaAudioOutput>,
    audio: Arc<Mutex<MediaAudioPlayback>>,
}

impl PreparedMediaAudioOutputGuard {
    fn empty(audio: Arc<Mutex<MediaAudioPlayback>>) -> Self {
        Self {
            output: None,
            audio,
        }
    }

    fn install_candidate(&mut self, output: PreparedMediaAudioOutput) {
        debug_assert!(self.output.is_none());
        self.output = Some(output);
    }

    fn output_mut(&mut self) -> &mut Option<PreparedMediaAudioOutput> {
        &mut self.output
    }
}

impl Drop for PreparedMediaAudioOutputGuard {
    fn drop(&mut self) {
        if let Some(output) = self.output.take() {
            retire_uncommitted_prepared_media_output(&self.audio, output);
        }
    }
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn with_media_audio_retirement_owner<T>(
    audio: &Arc<Mutex<MediaAudioPlayback>>,
    update: impl FnOnce(&mut MediaAudioPlayback) -> T,
) -> T {
    let mut playback = audio
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    update(&mut playback)
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn record_pending_normal_output_retirement(
    audio: &Arc<Mutex<MediaAudioPlayback>>,
    pending: PendingNormalOutputRetirement,
    detail: String,
) {
    // A poisoned media mutex still owns a valid playback value.  This path is
    // the last owner of a Router retirement lease, so abandoning `pending`
    // here would separate the Router receipt from the live OS resource. Keep
    // the lease in the same explicit reaper queue even after poison; callers
    // continue to fail closed and surface the diagnostic.
    with_media_audio_retirement_owner(audio, |playback| {
        playback.pending_normal_output_retirements.push(pending);
        playback.last_sync_error = Some(detail);
    });
}

fn retire_uncommitted_prepared_media_output(
    audio: &Arc<Mutex<MediaAudioPlayback>>,
    output: PreparedMediaAudioOutput,
) {
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    {
        // In the ASIO product build Router is the only prepared-output
        // variant. Keep this a direct destructure so the compiler cannot
        // mistake a fail-closed retirement path for an optional branch.
        match output {
            PreparedMediaAudioOutput::Router(output) => {
                retire_normal_output_lease(audio, output, "stale prepared PROGRAM output");
            }
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio", test))]
            PreparedMediaAudioOutput::Test { .. } => {}
        }
    }
    #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
    {
        // The ordinary Rodio route is intentionally retired by its owning
        // direct output. The Router-specific guard has nothing to do here.
        let _ = (audio, output);
    }
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn retire_normal_output_lease(
    audio: &Arc<Mutex<MediaAudioPlayback>>,
    output: normal_audio_output::NormalAudioOutput,
    context: &str,
) {
    match output.into_retirement() {
        Ok(task) => match task.perform() {
            normal_audio_output::NormalAudioOutputRetirement::Retired => {}
            normal_audio_output::NormalAudioOutputRetirement::Retry(pending) => {
                record_pending_normal_output_retirement(
                    audio,
                    pending,
                    format!("{context}: normal PROGRAM retirement requires retry"),
                );
            }
        },
        Err((output, error)) => record_pending_normal_output_retirement(
            audio,
            PendingNormalOutputRetirement::Unadmitted(output),
            format!("{context}: {error}"),
        ),
    }
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn retry_pending_normal_output_retirements(
    audio: &Arc<Mutex<MediaAudioPlayback>>,
) -> Result<(), String> {
    loop {
        let pending = {
            let mut playback = audio
                .lock()
                .map_err(|_| "Media audio playback lock was poisoned".to_string())?;
            playback.pending_normal_output_retirements.pop()
        };
        let Some(pending) = pending else {
            return Ok(());
        };
        let task = pending.into_retirement().map_err(|(pending, error)| {
            record_pending_normal_output_retirement(
                audio,
                pending,
                format!("normal PROGRAM retirement retry admission: {error}"),
            );
            error
        })?;
        match task.perform() {
            normal_audio_output::NormalAudioOutputRetirement::Retired => {}
            normal_audio_output::NormalAudioOutputRetirement::Retry(pending) => {
                let detail = "normal PROGRAM retirement retry failed; route remains fail-closed";
                record_pending_normal_output_retirement(audio, pending, detail.to_string());
                return Err(detail.to_string());
            }
        }
    }
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
struct NormalProgramOutputBinding {
    mixer: rodio::mixer::Mixer,
    generation: u64,
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn take_active_normal_program_output(
    playback: &mut MediaAudioPlayback,
    drain_timeline: bool,
) -> Result<
    (
        Option<normal_audio_output::NormalAudioOutput>,
        Vec<rodio::Sink>,
    ),
    String,
> {
    let owns_external_authoring_route =
        playback.external_wdm_timeline_owner == Some(ExplicitWdmTimelineOwner::NormalAuthoring);
    let preserve_external_authoring_timeline = !drain_timeline && owns_external_authoring_route;
    if playback.normal_output.is_none()
        && !preserve_external_authoring_timeline
        && playback.sinks.is_empty()
        && playback.timeline_sinks.is_empty()
    {
        return Ok((None, Vec::new()));
    }
    let next_generation = playback.next_audio_device_generation()?;
    // Detach every sink while holding state, then stop them after the mutex
    // is released and before the Router receives the stream retirement. Rodio
    // control calls must never turn a media state lock into an OS-I/O lock.
    let mut sinks = playback
        .sinks
        .drain()
        .map(|(_, sink)| sink)
        .collect::<Vec<_>>();
    if !preserve_external_authoring_timeline {
        #[cfg(test)]
        {
            playback.timeline_stop_count = playback
                .timeline_stop_count
                .saturating_add(playback.timeline_sinks.len() as u64);
        }
        sinks.extend(playback.timeline_sinks.drain().map(|(_, sink)| sink));
        playback.timeline_sources.clear();
        playback.timeline_source_clocks.clear();
        playback.timeline_failures.clear();
        playback.timeline_last_resync_at.clear();
        playback.timeline_source_projection_authority = None;
        playback.hybrid_cue_output_generation = 0;
        playback.external_wdm_timeline_owner = None;
    }
    playback.sources.clear();
    playback.last_resync_at.clear();
    playback.device_name = None;
    playback.requested_device_name = None;
    playback.audio_device_generation = next_generation;
    Ok((playback.normal_output.take(), sinks))
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn retire_active_normal_program_output(
    audio: &Arc<Mutex<MediaAudioPlayback>>,
    context: &str,
    drain_timeline: bool,
) -> Result<(), String> {
    let detached = {
        let mut playback = audio
            .lock()
            .map_err(|_| "Media audio playback lock was poisoned".to_string())?;
        take_active_normal_program_output(&mut playback, drain_timeline)?
    };
    let (output, sinks) = detached;
    for sink in sinks {
        sink.stop();
    }
    if let Some(output) = output {
        retire_normal_output_lease(audio, output, context);
    }
    retry_pending_normal_output_retirements(audio)
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn ensure_normal_program_output(
    audio: &Arc<Mutex<MediaAudioPlayback>>,
    slot: &Arc<audio_output_router::RouterSlot>,
    requested_device_name: Option<String>,
) -> Result<NormalProgramOutputBinding, String> {
    retry_pending_normal_output_retirements(audio)?;
    let requested_device_name = requested_device_name
        .as_deref()
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .map(str::to_string);
    let existing = {
        let playback = audio
            .lock()
            .map_err(|_| "Media audio playback lock was poisoned".to_string())?;
        playback.normal_output.as_ref().and_then(|output| {
            (playback.requested_device_name == requested_device_name).then(|| {
                NormalProgramOutputBinding {
                    mixer: output.mixer(),
                    generation: playback.audio_device_generation,
                }
            })
        })
    };
    if let Some(binding) = existing {
        return Ok(binding);
    }
    retire_active_normal_program_output(audio, "normal PROGRAM replacement", false)?;
    let output = match normal_audio_output::NormalAudioOutput::open(slot, requested_device_name) {
        Ok(output) => output,
        Err(error) => {
            let detail = error.detail().to_string();
            for pending in error.into_pending_retirements() {
                record_pending_normal_output_retirement(audio, pending, detail.clone());
            }
            return Err(detail);
        }
    };
    let mut prepared = Some(PreparedMediaAudioOutput::Router(output));
    let installed = {
        let mut playback = audio
            .lock()
            .map_err(|_| "Media audio playback lock was poisoned".to_string())?;
        playback
            .install_prepared_output(&mut prepared)
            .map(|_| NormalProgramOutputBinding {
                mixer: playback
                    .active_program_mixer()
                    .expect("installed normal PROGRAM output exposes a mixer"),
                generation: playback.audio_device_generation,
            })
    };
    if let Some(prepared) = prepared.take() {
        retire_uncommitted_prepared_media_output(audio, prepared);
    }
    installed
}

struct PreparedTimelineAudioClip {
    request: TimelineAudioPrepareRequest,
    sink: Option<rodio::Sink>,
    decoder: Option<rodio::Decoder<std::io::BufReader<fs::File>>>,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    asio_identity: Option<asio_timeline_output::TimelineOutputIdentity>,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    explicit_wdm_timeline_fence: Option<ExternalWdmTimelineRouteFence>,
}

impl PreparedTimelineAudioClip {
    fn stop(&mut self) {
        if let Some(sink) = self.sink.take() {
            sink.stop();
        }
    }
}

fn stop_prepared_timeline_audio_clips(prepared_clips: Vec<PreparedTimelineAudioClipResult>) {
    for mut prepared in prepared_clips.into_iter().flatten() {
        prepared.stop();
    }
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn prepared_explicit_wdm_timeline_fence(
    prepared_clips: &[PreparedTimelineAudioClipResult],
) -> Result<Option<ExternalWdmTimelineRouteFence>, String> {
    let mut expected = None;
    for fence in prepared_clips.iter().filter_map(|prepared| {
        prepared
            .as_ref()
            .ok()
            .and_then(|prepared| prepared.explicit_wdm_timeline_fence)
    }) {
        if expected.is_some_and(|expected| expected != fence) {
            return Err(
                "Prepared Timeline sinks span more than one external WDM output fence".to_owned(),
            );
        }
        expected = Some(fence);
    }
    Ok(expected)
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
type PendingNormalOutputRetirement = normal_audio_output::PendingNormalAudioOutputRetirement;

type PreparedTimelineAudioClipError = (TimelineAudioPrepareRequest, String);
type PreparedTimelineAudioClipResult =
    Result<PreparedTimelineAudioClip, Box<PreparedTimelineAudioClipError>>;

const MEDIA_AUDIO_RESYNC_THRESHOLD_MS: u64 = 75;
const MEDIA_AUDIO_RESYNC_COOLDOWN: Duration = Duration::from_millis(250);
const TIMELINE_AUDIO_SPEED_MIN_MILLI: u32 = 250;
const TIMELINE_AUDIO_SPEED_MAX_MILLI: u32 = 4_000;

fn validate_timeline_audio_speed(speed_milli: u32) -> Result<f32, String> {
    if !(TIMELINE_AUDIO_SPEED_MIN_MILLI..=TIMELINE_AUDIO_SPEED_MAX_MILLI).contains(&speed_milli) {
        return Err(format!(
            "Timeline audio playback rate must be within {TIMELINE_AUDIO_SPEED_MIN_MILLI}..={TIMELINE_AUDIO_SPEED_MAX_MILLI} milli (got {speed_milli}); zero is an invalid-rate sentinel"
        ));
    }
    Ok(speed_milli as f32 / 1_000.0)
}

fn timeline_audio_sink_output_position_ms(sink: &rodio::Sink) -> u64 {
    sink.get_pos().as_millis().min(u128::from(u64::MAX)) as u64
}

/// Converts Timeline source-time into the output-time coordinate expected by
/// `rodio::Sink::try_seek` when `Sink::set_speed` is active.
///
/// Rodio's `Speed::try_seek` multiplies the Sink coordinate by the speed before
/// seeking its wrapped decoder. We therefore divide the authoritative source
/// position by the fixed-point millirate here. The division deliberately rounds
/// down: the exact fixed-point source coordinate can be at, but never after,
/// the requested Timeline source position. This is a seek-coordinate conversion,
/// not a drift calculation; it stays integer-only and rejects the same invalid
/// rate sentinel as attachment.
fn timeline_audio_sink_output_position_for_source_ms(
    source_position_ms: u64,
    speed_milli: u32,
) -> Result<u64, String> {
    if !(TIMELINE_AUDIO_SPEED_MIN_MILLI..=TIMELINE_AUDIO_SPEED_MAX_MILLI).contains(&speed_milli) {
        return Err(format!(
            "Timeline audio Sink seek rejected invalid playback rate {speed_milli} milli"
        ));
    }
    let output_position_ms =
        u128::from(source_position_ms).saturating_mul(1_000) / u128::from(speed_milli);
    Ok(output_position_ms.min(u128::from(u64::MAX)) as u64)
}

/// Seeks a Speed-wrapped Rodio Sink to an authoritative Timeline source
/// position. Decoder seeks intentionally remain in raw source-time elsewhere.
fn seek_timeline_audio_sink_to_source_ms(
    sink: &rodio::Sink,
    source_position_ms: u64,
    speed_milli: u32,
) -> Result<(), String> {
    let output_position_ms =
        timeline_audio_sink_output_position_for_source_ms(source_position_ms, speed_milli)?;
    sink.try_seek(Duration::from_millis(output_position_ms))
        .map_err(|error| error.to_string())
}

/// Deterministically maps Rodio output-time into source-time. This uses only
/// integer arithmetic so resync decisions cannot accumulate float error.
fn timeline_audio_source_position_at_output_time(
    clock: TimelineAudioSourceClock,
    output_position_ms: u64,
    speed_milli: u32,
) -> Result<u64, String> {
    if !(TIMELINE_AUDIO_SPEED_MIN_MILLI..=TIMELINE_AUDIO_SPEED_MAX_MILLI).contains(&speed_milli) {
        return Err(format!(
            "Timeline audio source clock rejected invalid playback rate {speed_milli} milli"
        ));
    }
    let elapsed_output_ms = output_position_ms.saturating_sub(clock.output_anchor_ms);
    let elapsed_source_ms =
        u128::from(elapsed_output_ms).saturating_mul(u128::from(speed_milli)) / 1_000;
    let elapsed_source_ms = elapsed_source_ms.min(u128::from(u64::MAX)) as u64;
    Ok(clock.source_anchor_ms.saturating_add(elapsed_source_ms))
}

fn timeline_audio_source_drift_ms(actual_source_ms: u64, desired_source_ms: u64) -> i64 {
    let drift = i128::from(actual_source_ms) - i128::from(desired_source_ms);
    drift.clamp(i128::from(i64::MIN), i128::from(i64::MAX)) as i64
}
const MEDIA_AUDIO_SYNC_INTERVAL: Duration = Duration::from_millis(25);
const MEDIA_AUDIO_SYNC_IDLE_INTERVAL: Duration = Duration::from_millis(250);
const TIMELINE_AUDIO_PREPARE_TRANSACTION_BUDGET: Duration = Duration::from_millis(750);

#[derive(Debug, Clone, PartialEq)]
struct ProgramAudioHandoffConfig {
    enabled: bool,
    volume: f32,
    device_name: Option<String>,
}

impl Default for ProgramAudioHandoffConfig {
    fn default() -> Self {
        Self {
            enabled: false,
            volume: 0.8,
            device_name: None,
        }
    }
}

impl ProgramAudioHandoffConfig {
    fn validated(enabled: bool, volume: f32, device_name: Option<String>) -> Result<Self, String> {
        if !volume.is_finite() {
            return Err("Program audio monitor volume must be finite".to_string());
        }
        Ok(Self {
            enabled,
            volume: volume.clamp(0.0, 2.0),
            device_name: device_name
                .map(|name| name.trim().to_string())
                .filter(|name| !name.is_empty()),
        })
    }
}

#[derive(Debug, Clone, PartialEq)]
struct ProgramAudioHandoffPlan {
    layer_id: VideoLayerId,
    volume: f32,
    device_name: Option<String>,
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
struct ProgramAudioSourceRequest {
    layer_id: VideoLayerId,
    path: PathBuf,
    position_ms: u64,
    speed: f32,
    volume: f32,
    requested_device_name: Option<String>,
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
struct PreparedProgramAudioHandoff {
    request: ProgramAudioSourceRequest,
    output_generation: u64,
    sink: rodio::Sink,
}

#[derive(Debug, Clone, PartialEq)]
enum ProgramAudioJobKind {
    Handoff(ProgramAudioHandoffPlan),
    StopAll,
    ReconfigureActive {
        previous_volume: f32,
        volume: f32,
        device_name: Option<String>,
    },
}

#[derive(Debug, Clone, PartialEq)]
struct ProgramAudioJob {
    generation: u64,
    kind: ProgramAudioJobKind,
}

#[derive(Debug, Default)]
struct ProgramAudioHandoffState {
    config: ProgramAudioHandoffConfig,
    last_action: Option<protocol::AutoVjAction>,
    owned_layer_id: Option<VideoLayerId>,
    desired_layer_id: Option<VideoLayerId>,
    pending_job: Option<ProgramAudioJob>,
    suspended: bool,
}

impl ProgramAudioHandoffState {
    fn configure(
        &mut self,
        config: ProgramAudioHandoffConfig,
        current_action: Option<&protocol::AutoVjAction>,
    ) {
        let was_enabled = self.config.enabled;
        self.config = config;
        // Enabling Program Audio never replays an action that already reached Program.
        if !was_enabled && self.config.enabled {
            self.last_action = current_action.cloned();
        }
    }

    fn next_plan(&mut self, status: &protocol::AutoVjStatus) -> Option<ProgramAudioHandoffPlan> {
        if self.suspended {
            return None;
        }
        let Some(action) = status.last_action.as_ref() else {
            if !status.armed {
                self.last_action = None;
            }
            return None;
        };
        if self.last_action.as_ref() == Some(action) {
            return None;
        }
        self.last_action = Some(action.clone());
        self.config.enabled.then(|| ProgramAudioHandoffPlan {
            layer_id: action.layer_id,
            volume: self.config.volume,
            device_name: self.config.device_name.clone(),
        })
    }

    fn suppress_through(&mut self, action: Option<&protocol::AutoVjAction>) {
        self.last_action = action.cloned();
    }

    fn suppress_stopped_layer_action(
        &mut self,
        layer_id: VideoLayerId,
        action: Option<&protocol::AutoVjAction>,
    ) {
        if action.is_some_and(|action| action.layer_id == layer_id) {
            self.suppress_through(action);
        }
    }

    fn manual_take_plan(&self, layer_id: VideoLayerId) -> Option<ProgramAudioHandoffPlan> {
        self.config.enabled.then(|| ProgramAudioHandoffPlan {
            layer_id,
            volume: self.config.volume,
            device_name: self.config.device_name.clone(),
        })
    }

    fn reset_for_project_change(&mut self) {
        self.last_action = None;
        self.owned_layer_id = None;
        self.desired_layer_id = None;
        self.pending_job = None;
        self.suspended = false;
    }

    fn needs_low_latency_poll(&self, status: &protocol::AutoVjStatus) -> bool {
        self.pending_job.is_some() || (self.config.enabled && status.armed && !self.suspended)
    }
}

#[derive(Debug, Default)]
struct ProgramAudioHandoffCoordinator {
    state: Mutex<ProgramAudioHandoffState>,
    generation: AtomicU64,
    wake: Condvar,
}

impl ProgramAudioHandoffCoordinator {
    fn invalidate_in_flight(&self) -> u64 {
        let generation = self
            .generation
            .fetch_add(1, Ordering::AcqRel)
            .saturating_add(1);
        self.wake.notify_all();
        generation
    }

    fn queue_locked(&self, state: &mut ProgramAudioHandoffState, kind: ProgramAudioJobKind) -> u64 {
        let generation = self.invalidate_in_flight();
        if let ProgramAudioJobKind::Handoff(plan) = &kind {
            state.desired_layer_id = Some(plan.layer_id);
        }
        state.pending_job = Some(ProgramAudioJob { generation, kind });
        generation
    }
}

fn media_audio_resync_required(drift_ms: i64, cooldown_elapsed: Duration) -> bool {
    drift_ms.unsigned_abs() > MEDIA_AUDIO_RESYNC_THRESHOLD_MS
        && cooldown_elapsed >= MEDIA_AUDIO_RESYNC_COOLDOWN
}

fn timeline_audio_transport_action(
    previous: TimelineAudioTransportState,
    playing: bool,
    position_ms: u64,
    transport_revision: u64,
    now: Instant,
) -> TimelineAudioTransportAction {
    if !playing {
        return TimelineAudioTransportAction::Stop;
    }
    if !previous.playing {
        return TimelineAudioTransportAction::Recue;
    }
    if previous.transport_revision != transport_revision {
        return TimelineAudioTransportAction::Recue;
    }
    let elapsed_ms = previous
        .synced_at
        .map(|synced_at| now.saturating_duration_since(synced_at).as_millis())
        .unwrap_or(0)
        .min(u128::from(u64::MAX)) as u64;
    let expected_ms = previous.position_ms.saturating_add(elapsed_ms);
    if expected_ms.abs_diff(position_ms) > MEDIA_AUDIO_RESYNC_THRESHOLD_MS {
        TimelineAudioTransportAction::Recue
    } else {
        TimelineAudioTransportAction::Sync
    }
}

fn timeline_audio_active_clips(
    timeline: &engine::TimelineAudioRuntimeSnapshot,
) -> Vec<(TimelineAudioSinkKey, TimelineAudioClipSummary, u64, u32)> {
    let mut active = timeline
        .clips
        .iter()
        .filter(|clip| {
            clip.duration_ms > 0
                && timeline.position_ms >= clip.start_ms
                && timeline.position_ms < clip.start_ms.saturating_add(clip.duration_ms)
        })
        .cloned()
        .map(|clip| {
            (
                TimelineAudioSinkKey::Root(clip.id),
                clip,
                timeline.position_ms,
                1_000,
            )
        })
        .collect::<Vec<_>>();
    active.extend(timeline.child_clips.iter().map(|child| {
        let key = match child.root {
            engine::ChildTimelineAudioRuntimeRoot::Direct {
                parent_cue_id,
                generation,
            } => TimelineAudioSinkKey::DirectChild {
                parent_cue_id,
                generation,
                path: Arc::clone(&child.path),
                clip_id: child.clip.id,
            },
            engine::ChildTimelineAudioRuntimeRoot::Timeline {
                parent_event_id,
                parent_iteration,
            } => TimelineAudioSinkKey::Child {
                parent_event_id,
                parent_iteration,
                path: Arc::clone(&child.path),
                clip_id: child.clip.id,
            },
            engine::ChildTimelineAudioRuntimeRoot::Follow {
                source_timeline_id,
                target_timeline_id,
                generation,
                target_root,
            } => TimelineAudioSinkKey::Follow {
                source_timeline_id,
                target_timeline_id,
                generation,
                target_root,
                path: Arc::clone(&child.path),
                clip_id: child.clip.id,
            },
        };
        (
            key,
            child.clip.clone(),
            child.position_ms,
            child.playback_rate_milli,
        )
    }));
    active
}

fn timeline_audio_clip_volume(clip: &TimelineAudioClipSummary, position_ms: u64) -> f32 {
    let local_ms = position_ms
        .saturating_sub(clip.start_ms)
        .min(clip.duration_ms);
    let fade_in = if clip.fade_in_ms == 0 {
        1.0
    } else {
        local_ms as f32 / clip.fade_in_ms as f32
    };
    let remaining_ms = clip.duration_ms.saturating_sub(local_ms);
    let fade_out = if clip.fade_out_ms == 0 {
        1.0
    } else {
        remaining_ms as f32 / clip.fade_out_ms as f32
    };
    clip.gain.clamp(0.0, 2.0) * fade_in.clamp(0.0, 1.0).min(fade_out.clamp(0.0, 1.0))
}

fn reconfigured_program_audio_volume(
    current_volume: f32,
    previous_base_volume: f32,
    next_base_volume: f32,
    layer_opacity: f32,
) -> f32 {
    let next_base_volume = next_base_volume.clamp(0.0, 2.0);
    if previous_base_volume > f32::EPSILON {
        (current_volume * (next_base_volume / previous_base_volume)).clamp(0.0, 2.0)
    } else {
        (next_base_volume * layer_opacity.clamp(0.0, 1.0).sqrt()).clamp(0.0, 2.0)
    }
}

struct MediaAudioSyncRuntime {
    stop: Arc<AtomicBool>,
    program_handoff: Arc<ProgramAudioHandoffCoordinator>,
    worker: Option<std::thread::JoinHandle<()>>,
}

/// Return the one pending captured Audio consumer, if the current Follow
/// generation actually requires backend audio settlement. Empty/no-audio
/// quorums are represented by the engine as N/A and must not be fabricated by
/// the audio worker.
fn pending_timeline_follow_audio_settlement_ack_for_context(
    engine: &EngineHandle,
    context: TimelineAudioFollowContext,
    result: TimelineFollowSettlementAckResult,
) -> Option<TimelineFollowSettlementAck> {
    let runtime = engine.timeline_follow_runtime_status(context.epoch);
    if runtime.epoch != context.epoch
        || runtime.generation != context.generation
        || runtime.source_timeline_id != context.source_timeline_id
        || runtime.target_timeline_id != context.target_timeline_id
    {
        return None;
    }
    pending_timeline_follow_audio_settlement_ack_from_runtime(&runtime, result)
}

fn pending_timeline_follow_audio_settlement_ack_from_runtime(
    runtime: &TimelineFollowRuntimeStatusSnapshot,
    result: TimelineFollowSettlementAckResult,
) -> Option<TimelineFollowSettlementAck> {
    let pending = runtime
        .settlement
        .as_ref()?
        .domains
        .iter()
        .find(|domain| domain.domain == TimelineFollowSettlementDomain::Audio)?
        .consumers
        .iter()
        .any(|consumer| {
            consumer.consumer_id == TimelineFollowSettlementConsumerId::Audio
                && consumer.state == TimelineFollowSettlementState::Pending
        });
    pending.then_some(TimelineFollowSettlementAck {
        epoch: runtime.epoch,
        generation: runtime.generation,
        domain: TimelineFollowSettlementDomain::Audio,
        consumer_id: TimelineFollowSettlementConsumerId::Audio,
        result,
    })
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum TimelineAudioPrepareFault {
    BudgetExhausted(String),
    Ordinary(String),
}

impl TimelineAudioPrepareFault {
    fn budget(message: impl Into<String>) -> Self {
        Self::BudgetExhausted(message.into())
    }

    fn ordinary(message: impl Into<String>) -> Self {
        Self::Ordinary(message.into())
    }
}

impl std::fmt::Display for TimelineAudioPrepareFault {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::BudgetExhausted(message) | Self::Ordinary(message) => {
                formatter.write_str(message)
            }
        }
    }
}

impl From<String> for TimelineAudioPrepareFault {
    fn from(message: String) -> Self {
        Self::Ordinary(message)
    }
}

enum TimelineAudioCommitAttempt {
    Busy,
    Completed(Result<(), TimelineAudioPrepareFault>),
}

#[derive(Debug, Default)]
struct TimelineAudioPrepareCommitState {
    cancelled: bool,
    finalized: bool,
}

fn sync_timeline_audio_without_blocking_playback_lock(
    engine: &EngineHandle,
    audio: &Arc<Mutex<MediaAudioPlayback>>,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    output_router: Option<Arc<audio_output_router::RouterSlot>>,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    asio_output_runtime: Option<Arc<Mutex<asio_output_runtime::AsioOutputRuntime>>>,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    timeline_cue_audio: Option<Arc<TimelineCueAudioRuntime>>,
    timeline: &engine::TimelineAudioRuntimeSnapshot,
    commit_state: &Arc<Mutex<TimelineAudioPrepareCommitState>>,
    mut before_prepare: impl FnMut(),
    mut before_commit_lock: impl FnMut(),
) -> Result<engine::TimelineAudioProjectionAuthority, TimelineAudioPrepareFault> {
    let transaction_deadline = Instant::now() + TIMELINE_AUDIO_PREPARE_TRANSACTION_BUDGET;
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    retry_pending_normal_output_retirements(audio).map_err(TimelineAudioPrepareFault::ordinary)?;
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    let preflight_router_state = if timeline_audio_active_clips(timeline).is_empty() {
        None
    } else {
        output_router
            .as_ref()
            .map(|slot| {
                slot.snapshot()
                    .map(|snapshot| snapshot.state)
                    .map_err(|error| {
                        TimelineAudioPrepareFault::ordinary(router_error("snapshot", error))
                    })
            })
            .transpose()?
    };
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    let asio_cue_route_preflight = if matches!(
        preflight_router_state.as_ref(),
        Some(audio_output_router::State::AsioActive)
    ) {
        let runtime = timeline_cue_audio.as_ref().ok_or_else(|| {
            TimelineAudioPrepareFault::ordinary(
                "Timeline cue audio runtime owner is unavailable during ASIO CUE route observation",
            )
        })?;
        Some(
            runtime
                .asio_cue_route_snapshot_blocking()
                .map_err(TimelineAudioPrepareFault::ordinary)?,
        )
    } else {
        None
    };
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    let normal_authoring_route_preflight = if matches!(
        preflight_router_state.as_ref(),
        Some(audio_output_router::State::Normal)
    ) {
        let runtime = timeline_cue_audio.as_ref().ok_or_else(|| {
            TimelineAudioPrepareFault::ordinary(
                "Timeline authoring monitor owner is unavailable during Normal output observation",
            )
        })?;
        Some(
            runtime
                .normal_authoring_route_snapshot_blocking()
                .map_err(TimelineAudioPrepareFault::ordinary)?,
        )
    } else {
        None
    };
    let mut plan = audio
        .lock()
        .map_err(|_| "Timeline audio playback lock was poisoned".to_string())?
        .plan_timeline_audio_sync(timeline)?;
    let authority = plan.authority;

    // Tests use this seam to hold an arbitrarily slow media preparation while
    // proving status/control can still take the playback mutex. Production
    // invokes a no-op and proceeds to the same decoder/device path.
    before_prepare();
    let authority_is_current = || {
        engine
            .video_audio_runtime_snapshot()
            .timeline_audio
            .source_projection_authority
            == authority
    };
    if !authority_is_current() {
        for seek in std::mem::take(&mut plan.seeks) {
            seek.sink.stop();
        }
        return Err(TimelineAudioPrepareFault::ordinary(
            "Timeline audio source projection changed before preparation",
        ));
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    let use_asio_output = if plan.prepares.is_empty() {
        false
    } else if cfg!(test) && output_router.is_none() && plan.mixer.is_some() {
        // Unit tests install an in-memory mixer without acquiring the
        // process-global Windows output Router. This path is not reachable in
        // production and must not weaken the AsioActive/Normal authority gate.
        false
    } else {
        output_router.as_ref().ok_or_else(|| {
            TimelineAudioPrepareFault::ordinary(
                "Audio output router process owner is unavailable during Timeline preparation",
            )
        })?;
        match preflight_router_state.ok_or_else(|| {
            TimelineAudioPrepareFault::ordinary(
                "Audio output router state was unavailable during Timeline preparation",
            )
        })? {
            audio_output_router::State::Normal => false,
            audio_output_router::State::AsioActive => true,
            state => {
                return Err(TimelineAudioPrepareFault::ordinary(format!(
                    "Timeline audio preparation is blocked while the output router is {state:?}"
                )))
            }
        }
    };
    #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
    let use_asio_output = false;

    let mut prepared_output = PreparedMediaAudioOutputGuard::empty(Arc::clone(audio));
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    let use_explicit_authoring_monitor = matches!(
        normal_authoring_route_preflight.as_ref(),
        Some(NormalAuthoringRouteSnapshot::ExplicitWdm(_))
    );
    #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
    let use_explicit_authoring_monitor = false;
    let mixer = if use_asio_output {
        None
    } else if use_explicit_authoring_monitor {
        // The selected authoring monitor owns every Timeline audio source in
        // Normal mode. Never open or reuse PROGRAM/default output as fallback.
        None
    } else if plan.prepares.is_empty() {
        plan.mixer.clone()
    } else if let Some(mixer) = plan.mixer.clone() {
        Some(mixer)
    } else {
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        {
            let slot = output_router.as_ref().ok_or_else(|| {
                TimelineAudioPrepareFault::ordinary(
                    "Normal PROGRAM output router process owner is unavailable",
                )
            })?;
            let output = match normal_audio_output::NormalAudioOutput::open(
                slot,
                plan.requested_device_name.clone(),
            ) {
                Ok(output) => output,
                Err(error) => {
                    let detail = error.detail().to_string();
                    for pending in error.into_pending_retirements() {
                        record_pending_normal_output_retirement(audio, pending, detail.clone());
                    }
                    return Err(TimelineAudioPrepareFault::ordinary(detail));
                }
            };
            let output = PreparedMediaAudioOutput::Router(output);
            let mixer = output.mixer();
            prepared_output.install_candidate(output);
            Some(mixer)
        }
        #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
        {
            let output = prepare_media_audio_output(plan.requested_device_name.as_deref())?;
            let mixer = output.mixer();
            prepared_output.install_candidate(output);
            Some(mixer)
        }
    };
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    let asio_cue_route = if use_asio_output {
        asio_cue_route_preflight.unwrap_or(AsioCueRouteSnapshot::Unavailable)
    } else {
        AsioCueRouteSnapshot::Unavailable
    };
    let mut prepared_clips: Vec<PreparedTimelineAudioClipResult> =
        Vec::with_capacity(plan.prepares.len());
    for request in std::mem::take(&mut plan.prepares) {
        if Instant::now() >= transaction_deadline {
            drop(request);
            stop_prepared_timeline_audio_clips(prepared_clips);
            for seek in std::mem::take(&mut plan.seeks) {
                seek.sink.stop();
            }
            return Err(TimelineAudioPrepareFault::budget(
                "Timeline audio decoder preparation transaction exceeded its budget",
            ));
        }
        if !authority_is_current() {
            prepared_clips.push(Err(Box::new((
                request,
                "Timeline audio source projection changed during decoder preparation".to_string(),
            ))));
            continue;
        }
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        if let Some(NormalAuthoringRouteSnapshot::ExplicitWdm(output)) =
            normal_authoring_route_preflight.as_ref()
        {
            match output {
                Some(output) => prepared_clips
                    .push(prepare_explicit_wdm_timeline_audio_clip(request, output)),
                None => prepared_clips.push(Err(Box::new((
                    request,
                    "Timeline authoring monitor is selected but its exact WDM output is not publishable"
                        .to_owned(),
                )))),
            }
            continue;
        }
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        if use_asio_output {
            if request.source.output_bus == protocol::TimelineAudioOutputBus::Cue {
                match &asio_cue_route {
                    AsioCueRouteSnapshot::ExplicitWdm(Some(output)) => {
                        prepared_clips
                            .push(prepare_explicit_wdm_timeline_audio_clip(request, output));
                        continue;
                    }
                    AsioCueRouteSnapshot::ExplicitWdm(None) => {
                        prepared_clips.push(Err(Box::new((
                            request,
                            "Explicit WDM CUE output is selected but is not publishable".to_owned(),
                        ))));
                        continue;
                    }
                    AsioCueRouteSnapshot::Unavailable => {
                        prepared_clips.push(Err(Box::new((
                            request,
                            "ASIO CUE assignment is unavailable during Timeline preparation"
                                .to_owned(),
                        ))));
                        continue;
                    }
                    AsioCueRouteSnapshot::Busy => {
                        prepared_clips.push(Err(Box::new((
                            request,
                            "ASIO CUE assignment remained busy during Timeline preparation"
                                .to_owned(),
                        ))));
                        continue;
                    }
                    AsioCueRouteSnapshot::SameAsio => {}
                }
            }
            let Some(runtime) = asio_output_runtime.as_ref() else {
                prepared_clips.push(Err(Box::new((
                    request,
                    "show-ASIO output runtime owner is unavailable during Timeline preparation"
                        .to_owned(),
                ))));
                continue;
            };
            prepared_clips.push(prepare_asio_timeline_audio_clip(request, runtime));
            continue;
        }
        let Some(mixer) = mixer.as_ref() else {
            prepared_clips.push(Err(Box::new((
                request,
                "Normal PROGRAM output mixer is unavailable during Timeline preparation".to_owned(),
            ))));
            continue;
        };
        prepared_clips.push(prepare_timeline_audio_clip(request, mixer));
    }
    let seek_results = std::mem::take(&mut plan.seeks)
        .into_iter()
        .map(|seek| {
            let result = if authority_is_current() {
                seek_timeline_audio_sink_to_source_ms(
                    &seek.sink,
                    seek.source_position_ms,
                    seek.speed_milli,
                )
            } else {
                Err("source projection changed before drift resync".to_string())
            };
            (seek, result)
        })
        .collect::<Vec<_>>();
    let mut current = engine.video_audio_runtime_snapshot();
    // Decoder/open work may span many ordinary 44 Hz position ticks. Those
    // ticks intentionally share one semantic generation, so rebase every
    // paused prepared sink to the latest source position before taking the
    // playback mutex. A stop/seek/source mutation still rotates the semantic
    // fence and rejects the whole install below.
    before_commit_lock();
    let mut plan = Some(plan);
    let mut seek_results = Some(seek_results);
    let mut sources_attached = false;
    loop {
        if Instant::now() > transaction_deadline {
            stop_prepared_timeline_audio_clips(prepared_clips);
            for (seek, _) in seek_results.take().unwrap_or_default() {
                seek.sink.stop();
            }
            return Err(TimelineAudioPrepareFault::budget(
                "Timeline audio position did not stabilize within the decoder preparation budget"
                    .to_string(),
            ));
        }
        if !sources_attached {
            prepared_clips =
                rebase_prepared_timeline_audio_clips(&current.timeline_audio, prepared_clips);
            prepared_clips = seek_prepared_timeline_audio_decoders(prepared_clips);
        }
        let latest = engine.video_audio_runtime_snapshot();
        if latest.timeline_audio.source_projection_authority != authority {
            stop_prepared_timeline_audio_clips(prepared_clips);
            for (seek, _) in seek_results.take().unwrap_or_default() {
                seek.sink.stop();
            }
            return Err(TimelineAudioPrepareFault::ordinary(
                "Timeline audio source projection changed before sink install",
            ));
        }
        if latest.timeline_audio.publication_generation != timeline.publication_generation {
            stop_prepared_timeline_audio_clips(prepared_clips);
            for (seek, _) in seek_results.take().unwrap_or_default() {
                seek.sink.stop();
            }
            return Err(TimelineAudioPrepareFault::ordinary(
                "Timeline audio transport changed before sink install",
            ));
        }
        if !sources_attached
            && prepared_timeline_audio_clips_need_rebase(&latest.timeline_audio, &prepared_clips)
        {
            current = latest;
            continue;
        }
        if !sources_attached {
            // Do not consume decoders into the ASIO-owned mixers while the
            // short media commit lock is known to be busy. Keeping them
            // detached lets ordinary 44 Hz position ticks rebase exactly;
            // the probe guard is dropped before any ASIO runtime lock is
            // acquired, preserving the runtime -> media drain lock order.
            match audio.try_lock() {
                Ok(probe) => drop(probe),
                Err(TryLockError::WouldBlock) => {
                    current = latest;
                    std::thread::sleep(Duration::from_millis(2));
                    continue;
                }
                Err(TryLockError::Poisoned(_)) => {
                    stop_prepared_timeline_audio_clips(prepared_clips);
                    for (seek, _) in seek_results.take().unwrap_or_default() {
                        seek.sink.stop();
                    }
                    return Err(TimelineAudioPrepareFault::ordinary(
                        "Timeline audio playback lock was poisoned",
                    ));
                }
            }
            prepared_clips = append_prepared_timeline_audio_decoders(
                prepared_clips,
                #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                asio_output_runtime.as_ref(),
                #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                timeline_cue_audio.as_ref(),
                #[cfg(all(test, target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                None,
            );
            sources_attached = true;
        }
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let explicit_wdm_commit_fence = match prepared_explicit_wdm_timeline_fence(&prepared_clips)
        {
            Ok(fence) => fence,
            Err(error) => {
                stop_prepared_timeline_audio_clips(prepared_clips);
                for (seek, _) in seek_results.take().unwrap_or_default() {
                    seek.sink.stop();
                }
                return Err(TimelineAudioPrepareFault::ordinary(error));
            }
        };
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let expected_external_wdm_timeline_fence =
            plan.as_ref().map(|plan| ExternalWdmTimelineRouteFence {
                owner: plan.external_wdm_timeline_owner,
                generation: plan.hybrid_cue_output_generation,
            });
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let external_wdm_commit_required = timeline_cue_audio.is_some()
            || explicit_wdm_commit_fence.is_some()
            || expected_external_wdm_timeline_fence
                .is_some_and(|fence| fence.owner.is_some() || fence.generation != 0);
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        if external_wdm_commit_required
            && explicit_wdm_commit_fence != expected_external_wdm_timeline_fence
        {
            stop_prepared_timeline_audio_clips(prepared_clips);
            for (seek, _) in seek_results.take().unwrap_or_default() {
                seek.sink.stop();
            }
            return Err(TimelineAudioPrepareFault::ordinary(
                "External WDM Timeline route changed during preparation",
            ));
        }
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let explicit_wdm_commit_guard = if external_wdm_commit_required {
            let Some(cue_runtime) = timeline_cue_audio.as_ref() else {
                stop_prepared_timeline_audio_clips(prepared_clips);
                for (seek, _) in seek_results.take().unwrap_or_default() {
                    seek.sink.stop();
                }
                return Err(TimelineAudioPrepareFault::ordinary(
                    "External WDM Timeline runtime owner is unavailable before sink commit",
                ));
            };
            let expected_fence = expected_external_wdm_timeline_fence
                .expect("Timeline audio plan always carries an external WDM fence");
            let guard = match explicit_wdm_commit_fence {
                Some(output_fence) => cue_runtime.lock_explicit_wdm_timeline_commit(output_fence),
                None => cue_runtime.lock_external_wdm_timeline_commit(expected_fence),
            };
            match guard {
                Ok(fence) => Some(fence),
                Err(error) => {
                    stop_prepared_timeline_audio_clips(prepared_clips);
                    for (seek, _) in seek_results.take().unwrap_or_default() {
                        seek.sink.stop();
                    }
                    return Err(TimelineAudioPrepareFault::ordinary(error));
                }
            }
        } else {
            None
        };
        let publication_generation = latest.timeline_audio.publication_generation;
        let attempt =
            engine.with_timeline_audio_projection_fence(authority, publication_generation, || {
                let mut commit_state = match commit_state.lock() {
                    Ok(state) => state,
                    Err(_) => {
                        return TimelineAudioCommitAttempt::Completed(Err(
                            TimelineAudioPrepareFault::ordinary(
                                "Timeline audio prepare commit fence was poisoned",
                            ),
                        ));
                    }
                };
                if commit_state.cancelled {
                    return TimelineAudioCommitAttempt::Completed(Err(
                        TimelineAudioPrepareFault::ordinary(
                            "Timeline audio prepare was cancelled before sink install",
                        ),
                    ));
                }
                match audio.try_lock() {
                    Ok(mut playback) => {
                        if Instant::now() > transaction_deadline {
                            stop_prepared_timeline_audio_clips(std::mem::take(
                                &mut prepared_clips,
                            ));
                            for (seek, _) in seek_results.take().unwrap_or_default() {
                                seek.sink.stop();
                            }
                            return TimelineAudioCommitAttempt::Completed(Err(
                                TimelineAudioPrepareFault::budget(
                                    "Timeline audio decoder preparation transaction exceeded its budget",
                                ),
                            ));
                        }
                        // This state lock is the exact timeout/install
                        // linearization point. Once finalization begins the
                        // coordinator waits for this short device commit and
                        // can no longer publish a contradictory timeout.
                        commit_state.finalized = true;
                        TimelineAudioCommitAttempt::Completed(
                            playback.commit_timeline_audio_sync(
                                plan.take().expect("Timeline audio plan commits once"),
                                &latest.timeline_audio,
                                prepared_output.output_mut(),
                                std::mem::take(&mut prepared_clips),
                                seek_results
                                    .take()
                                    .expect("Timeline audio seeks commit once"),
                            ).map_err(TimelineAudioPrepareFault::ordinary),
                        )
                    }
                    Err(TryLockError::WouldBlock) => TimelineAudioCommitAttempt::Busy,
                    Err(TryLockError::Poisoned(_)) => TimelineAudioCommitAttempt::Completed(Err(
                        TimelineAudioPrepareFault::ordinary(
                            "Timeline audio playback lock was poisoned",
                        ),
                    )),
                }
            });
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        drop(explicit_wdm_commit_guard);
        match attempt {
            Ok(TimelineAudioCommitAttempt::Completed(result)) => {
                result?;
                return Ok(authority);
            }
            Ok(TimelineAudioCommitAttempt::Busy) => {
                current = engine.video_audio_runtime_snapshot();
                std::thread::sleep(Duration::from_millis(2));
            }
            Err(error) => {
                stop_prepared_timeline_audio_clips(prepared_clips);
                for (seek, _) in seek_results.take().unwrap_or_default() {
                    seek.sink.stop();
                }
                return Err(TimelineAudioPrepareFault::ordinary(error));
            }
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct TimelineAudioPrepareFingerprint {
    authority: engine::TimelineAudioProjectionAuthority,
    publication_generation: u64,
    audio_device_generation: u64,
    hybrid_cue_output_generation: u64,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    external_wdm_timeline_owner: Option<ExplicitWdmTimelineOwner>,
    requested_device_name: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct TimelineAudioFollowContext {
    epoch: u64,
    generation: u64,
    source_timeline_id: Option<TimelineId>,
    target_timeline_id: Option<TimelineId>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct TimelineAudioPrepareContext {
    fingerprint: TimelineAudioPrepareFingerprint,
    follow: TimelineAudioFollowContext,
}

struct TimelineAudioPrepareJob {
    context: TimelineAudioPrepareContext,
    started_at: Instant,
    receiver:
        mpsc::Receiver<Result<engine::TimelineAudioProjectionAuthority, TimelineAudioPrepareFault>>,
    worker: Option<std::thread::JoinHandle<()>>,
    result: Option<Result<engine::TimelineAudioProjectionAuthority, TimelineAudioPrepareFault>>,
    timed_out: bool,
    commit_state: Arc<Mutex<TimelineAudioPrepareCommitState>>,
}

#[derive(Debug)]
enum TimelineAudioPreparePoll {
    Pending,
    Quarantined,
    Obsolete,
    Completed {
        context: TimelineAudioPrepareContext,
        result: Result<(), String>,
    },
    TimedOut {
        context: TimelineAudioPrepareContext,
        error: String,
    },
}

#[derive(Default)]
struct TimelineAudioPrepareCoordinator {
    active: Option<TimelineAudioPrepareJob>,
    blocked: Option<TimelineAudioPrepareFingerprint>,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    output_router: Option<Arc<audio_output_router::RouterSlot>>,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    asio_output_runtime: Option<Arc<Mutex<asio_output_runtime::AsioOutputRuntime>>>,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    timeline_cue_audio: Option<Arc<TimelineCueAudioRuntime>>,
    #[cfg(test)]
    before_prepare: Option<Arc<dyn Fn() + Send + Sync>>,
    #[cfg(test)]
    before_commit_lock: Option<Arc<dyn Fn() + Send + Sync>>,
    #[cfg(test)]
    spawn_count: u64,
    #[cfg(test)]
    reap_count: u64,
}

impl TimelineAudioPrepareCoordinator {
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn cancel_pending_commit(&mut self) {
        let Some(job) = self.active.as_mut() else {
            return;
        };
        if let Ok(mut commit_state) = job.commit_state.lock() {
            if !commit_state.finalized {
                commit_state.cancelled = true;
            }
        }
    }

    fn shutdown(&mut self) {
        let Some(mut job) = self.active.take() else {
            self.blocked = None;
            return;
        };
        if let Ok(mut commit_state) = job.commit_state.lock() {
            if !commit_state.finalized {
                commit_state.cancelled = true;
            }
        }
        if let Some(worker) = job.worker.take() {
            let _ = worker.join();
            #[cfg(test)]
            {
                self.reap_count = self.reap_count.saturating_add(1);
            }
        }
        self.blocked = None;
    }

    fn context(
        engine: &EngineHandle,
        audio: &Arc<Mutex<MediaAudioPlayback>>,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
    ) -> Option<TimelineAudioPrepareContext> {
        let playback = audio.try_lock().ok()?;
        let audio_device_generation = playback.audio_device_generation;
        let hybrid_cue_output_generation = playback.hybrid_cue_output_generation;
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let external_wdm_timeline_owner = playback.external_wdm_timeline_owner;
        let requested_device_name = playback.requested_device_name.clone();
        drop(playback);
        let epoch = engine.output_ownership_status().epoch;
        let follow = engine.timeline_follow_runtime_status(epoch);
        Some(TimelineAudioPrepareContext {
            fingerprint: TimelineAudioPrepareFingerprint {
                authority: timeline.source_projection_authority,
                publication_generation: timeline.publication_generation,
                audio_device_generation,
                hybrid_cue_output_generation,
                #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                external_wdm_timeline_owner,
                requested_device_name,
            },
            follow: TimelineAudioFollowContext {
                epoch: follow.epoch,
                generation: follow.generation,
                source_timeline_id: follow.source_timeline_id,
                target_timeline_id: follow.target_timeline_id,
            },
        })
    }

    fn poll_or_spawn(
        &mut self,
        engine: &EngineHandle,
        audio: &Arc<Mutex<MediaAudioPlayback>>,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
    ) -> TimelineAudioPreparePoll {
        let current_context = Self::context(engine, audio, timeline);
        if let Some(job) = self.active.as_mut() {
            if job.result.is_none() {
                match job.receiver.try_recv() {
                    Ok(result) => job.result = Some(result),
                    Err(mpsc::TryRecvError::Empty) => {}
                    Err(mpsc::TryRecvError::Disconnected) => {
                        job.result = Some(Err(TimelineAudioPrepareFault::ordinary(
                            "Timeline audio prepare worker disconnected",
                        )));
                    }
                }
            }
            let finished = job
                .worker
                .as_ref()
                .is_some_and(|worker| worker.is_finished());
            if finished && job.result.is_some() {
                let mut job = self.active.take().expect("observed active prepare job");
                if let Some(worker) = job.worker.take() {
                    let _ = worker.join();
                }
                #[cfg(test)]
                {
                    self.reap_count = self.reap_count.saturating_add(1);
                }
                if job.timed_out {
                    return TimelineAudioPreparePoll::Quarantined;
                }
                if current_context.as_ref() != Some(&job.context) {
                    return TimelineAudioPreparePoll::Obsolete;
                }
                let result = job
                    .result
                    .take()
                    .expect("finished prepare job carries one result");
                return match result {
                    Ok(_) => TimelineAudioPreparePoll::Completed {
                        context: job.context,
                        result: Ok(()),
                    },
                    Err(TimelineAudioPrepareFault::BudgetExhausted(error)) => {
                        self.blocked = Some(job.context.fingerprint.clone());
                        TimelineAudioPreparePoll::TimedOut {
                            context: job.context,
                            error,
                        }
                    }
                    Err(TimelineAudioPrepareFault::Ordinary(error)) => {
                        TimelineAudioPreparePoll::Completed {
                            context: job.context,
                            result: Err(error),
                        }
                    }
                };
            }
            if !job.timed_out
                && job.started_at.elapsed() >= TIMELINE_AUDIO_PREPARE_TRANSACTION_BUDGET
            {
                let mut commit_state = match job.commit_state.lock() {
                    Ok(state) => state,
                    Err(_) => {
                        job.result = Some(Err(TimelineAudioPrepareFault::ordinary(
                            "Timeline audio prepare commit fence was poisoned",
                        )));
                        return TimelineAudioPreparePoll::Pending;
                    }
                };
                if commit_state.finalized {
                    return TimelineAudioPreparePoll::Pending;
                }
                commit_state.cancelled = true;
                job.timed_out = true;
                self.blocked = Some(job.context.fingerprint.clone());
                if current_context.as_ref() != Some(&job.context) {
                    return TimelineAudioPreparePoll::Obsolete;
                }
                return TimelineAudioPreparePoll::TimedOut {
                    context: job.context.clone(),
                    error: "Timeline audio decoder preparation timed out; the source is quarantined until its in-flight worker exits or the semantic generation or output device changes"
                        .to_string(),
                };
            }
            return if job.timed_out {
                TimelineAudioPreparePoll::Quarantined
            } else {
                TimelineAudioPreparePoll::Pending
            };
        }
        let Some(context) = current_context else {
            return TimelineAudioPreparePoll::Pending;
        };
        if self.blocked.as_ref() == Some(&context.fingerprint) {
            return TimelineAudioPreparePoll::Quarantined;
        }

        let worker_engine = engine.clone();
        let worker_audio = Arc::clone(audio);
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let worker_output_router = self.output_router.clone();
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let worker_asio_output_runtime = self.asio_output_runtime.clone();
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let worker_timeline_cue_audio = self.timeline_cue_audio.clone();
        let worker_timeline = timeline.clone();
        #[cfg(test)]
        let before_prepare = self.before_prepare.clone();
        #[cfg(test)]
        let before_commit_lock = self.before_commit_lock.clone();
        let commit_state = Arc::new(Mutex::new(TimelineAudioPrepareCommitState::default()));
        let worker_commit_state = Arc::clone(&commit_state);
        let (sender, receiver) = mpsc::sync_channel(1);
        let worker = std::thread::Builder::new()
            .name("syndocal-timeline-audio-prepare".to_string())
            .spawn(move || {
                let result = sync_timeline_audio_without_blocking_playback_lock(
                    &worker_engine,
                    &worker_audio,
                    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                    worker_output_router,
                    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                    worker_asio_output_runtime,
                    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                    worker_timeline_cue_audio,
                    &worker_timeline,
                    &worker_commit_state,
                    || {
                        #[cfg(test)]
                        if let Some(before_prepare) = before_prepare.as_ref() {
                            before_prepare();
                        }
                    },
                    || {
                        #[cfg(test)]
                        if let Some(before_commit_lock) = before_commit_lock.as_ref() {
                            before_commit_lock();
                        }
                    },
                );
                let _ = sender.send(result);
            });
        let worker = match worker {
            Ok(worker) => worker,
            Err(error) => {
                return TimelineAudioPreparePoll::Completed {
                    context,
                    result: Err(format!(
                        "Timeline audio prepare worker could not start: {error}"
                    )),
                };
            }
        };
        self.active = Some(TimelineAudioPrepareJob {
            context,
            started_at: Instant::now(),
            receiver,
            worker: Some(worker),
            result: None,
            timed_out: false,
            commit_state,
        });
        #[cfg(test)]
        {
            self.spawn_count = self.spawn_count.saturating_add(1);
        }
        TimelineAudioPreparePoll::Pending
    }
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn stop_timeline_audio_after_transport_failure(audio: &Arc<Mutex<MediaAudioPlayback>>) {
    match audio.lock() {
        Ok(mut playback) => playback.stop_all_timeline(),
        // The poison marker is deliberately retained by consuming only this
        // emergency guard. Normal sync still observes the poisoned mutex and
        // refuses to publish new Timeline PROGRAM audio.
        Err(poisoned) => poisoned.into_inner().stop_all_timeline(),
    }
}

impl MediaAudioSyncRuntime {
    #[cfg(test)]
    fn idle_for_tests(program_handoff: Arc<ProgramAudioHandoffCoordinator>) -> Self {
        Self {
            stop: Arc::new(AtomicBool::new(true)),
            program_handoff,
            worker: None,
        }
    }

    fn start(
        engine: EngineHandle,
        audio: Arc<Mutex<MediaAudioPlayback>>,
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        output_router: Option<Arc<audio_output_router::RouterSlot>>,
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        asio_output_runtime: Option<Arc<Mutex<asio_output_runtime::AsioOutputRuntime>>>,
        program_handoff: Arc<ProgramAudioHandoffCoordinator>,
        timeline_cue_audio: Arc<TimelineCueAudioRuntime>,
    ) -> Self {
        let stop = Arc::new(AtomicBool::new(false));
        let worker_stop = Arc::clone(&stop);
        let worker_handoff = Arc::clone(&program_handoff);
        let worker_timeline_cue_audio = Arc::clone(&timeline_cue_audio);
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let worker_output_router = output_router;
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let worker_asio_output_runtime = asio_output_runtime;
        let worker = std::thread::Builder::new()
            .name("syndocal-media-audio-sync".to_string())
            .spawn(move || {
                let mut timeline_prepare = TimelineAudioPrepareCoordinator {
                    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                    output_router: worker_output_router.clone(),
                    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                    asio_output_runtime: worker_asio_output_runtime.clone(),
                    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                    timeline_cue_audio: Some(Arc::clone(&worker_timeline_cue_audio)),
                    ..TimelineAudioPrepareCoordinator::default()
                };
                #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                let mut asio_timeline_transport =
                    asio_timeline_transport::AsioTimelineTransportObserver::new();
                #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                let mut last_asio_timeline_transport_error: Option<String> = None;
                while !worker_stop.load(Ordering::Acquire) {
                    let mut snapshot = engine.video_audio_runtime_snapshot();
                    let job = worker_handoff.state.lock().ok().and_then(|mut state| {
                        if state.pending_job.is_none() {
                            if let Some(plan) = state.next_plan(&snapshot.auto_vj_status) {
                                worker_handoff
                                    .queue_locked(&mut state, ProgramAudioJobKind::Handoff(plan));
                            }
                        }
                        state.pending_job.take()
                    });
                    if let Some(job) = job {
                        execute_program_audio_job(
                            &worker_handoff,
                            &audio,
                            #[cfg(all(
                                target_os = "windows",
                                target_arch = "x86_64",
                                feature = "asio"
                            ))]
                            worker_output_router.as_ref(),
                            snapshot.layers.as_slice(),
                            job,
                        );
                        // The Timeline projection is re-read immediately below,
                        // after any slow Program device/decode work completes.
                    }

                    // Re-read immediately before planning. Decoder open,
                    // output-device creation and seek all run after the short
                    // planning lock has been released; commit revalidates the
                    // exact source authority and device generation.
                    snapshot = engine.video_audio_runtime_snapshot();
                    if let Ok(mut playback) = audio.try_lock() {
                        if !playback.sinks.is_empty() {
                            playback.sync_to_video_layers(&snapshot.layers);
                        }
                    }
                    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                    let asio_timeline_transport_error = match (
                        worker_output_router.as_ref(),
                        worker_asio_output_runtime.as_ref(),
                    ) {
                        (Some(slot), Some(runtime)) => match slot.snapshot() {
                            Ok(router)
                                if router.state == audio_output_router::State::AsioActive =>
                            {
                                let semantic = asio_timeline_transport::TimelineSemanticStamp::new(
                                    snapshot.timeline_audio.source_projection_authority.epoch,
                                    snapshot
                                        .timeline_audio
                                        .source_projection_authority
                                        .generation,
                                    snapshot.timeline_audio.publication_generation,
                                    snapshot.timeline_audio.transport_revision,
                                    snapshot.timeline_audio.playing,
                                );
                                match runtime.lock() {
                                    Ok(mut runtime) => {
                                        asio_timeline_transport::synchronize_active_runtime(
                                            &mut asio_timeline_transport,
                                            &mut runtime,
                                            semantic,
                                        )
                                        .err()
                                    }
                                    Err(_) => Some(
                                        "ASIO Timeline transport runtime lock was poisoned"
                                            .to_owned(),
                                    ),
                                }
                            }
                            Ok(_) => None,
                            Err(error) => {
                                Some(router_error("Timeline transport observation", error))
                            }
                        },
                        (Some(slot), None) => match slot.snapshot() {
                            Ok(router)
                                if router.state == audio_output_router::State::AsioActive =>
                            {
                                Some(
                                    "ASIO Timeline transport runtime owner is unavailable"
                                        .to_owned(),
                                )
                            }
                            Ok(_) => None,
                            Err(error) => {
                                Some(router_error("Timeline transport observation", error))
                            }
                        },
                        (None, _) => None,
                    };
                    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                    if let Some(error) = asio_timeline_transport_error.as_ref() {
                        // Prevent a decoder prepared against the retired
                        // semantic image from installing after this output
                        // fence failed. The commit-state lock is the same short
                        // linearization point used by timeout cancellation.
                        timeline_prepare.cancel_pending_commit();
                        stop_timeline_audio_after_transport_failure(&audio);
                        worker_timeline_cue_audio.retire_timeline_cue_attachment();
                        worker_timeline_cue_audio.fail_prepare(error.clone());
                        if last_asio_timeline_transport_error.as_deref() != Some(error.as_str()) {
                            eprintln!("ASIO Timeline transport failed closed: {error}");
                        }
                    }
                    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                    {
                        last_asio_timeline_transport_error = asio_timeline_transport_error.clone();
                    }
                    let applied_projection_authority =
                        snapshot.timeline_audio.source_projection_authority;
                    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                    let allow_timeline_audio_sync = asio_timeline_transport_error.is_none();
                    #[cfg(not(all(
                        target_os = "windows",
                        target_arch = "x86_64",
                        feature = "asio"
                    )))]
                    let allow_timeline_audio_sync = true;
                    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                    if allow_timeline_audio_sync {
                        // Publish or refresh the selected CUE destination
                        // before logical CUE clips are prepared.
                        worker_timeline_cue_audio.sync_with_output_router(
                            &snapshot.timeline_audio,
                            &audio,
                            worker_output_router.as_ref(),
                            worker_asio_output_runtime.as_ref(),
                        );
                    }
                    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                    {
                        worker_timeline_cue_audio
                            .observe_external_wdm_timeline_route_on_worker_tick(&audio);
                    }
                    #[cfg(not(all(
                        target_os = "windows",
                        target_arch = "x86_64",
                        feature = "asio"
                    )))]
                    worker_timeline_cue_audio.sync(&snapshot.timeline_audio, &audio);
                    let mut timeline_sync_result = if allow_timeline_audio_sync {
                        match timeline_prepare.poll_or_spawn(
                            &engine,
                            &audio,
                            &snapshot.timeline_audio,
                        ) {
                            TimelineAudioPreparePoll::Completed { context, result } => {
                                Some((context, result))
                            }
                            TimelineAudioPreparePoll::TimedOut { context, error } => {
                                Some((context, Err(error)))
                            }
                            TimelineAudioPreparePoll::Pending
                            | TimelineAudioPreparePoll::Quarantined
                            | TimelineAudioPreparePoll::Obsolete => None,
                        }
                    } else {
                        None
                    };
                    let current = engine.video_audio_runtime_snapshot();
                    let active = audio
                        .try_lock()
                        .map(|playback| {
                            !playback.sinks.is_empty()
                                || !playback.timeline_sinks.is_empty()
                                || current.timeline_audio.playing
                        })
                        .unwrap_or(false);
                    let after_sync = engine.video_audio_runtime_snapshot();
                    if after_sync.timeline_audio.source_projection_authority
                        != applied_projection_authority
                    {
                        if let Ok(mut audio) = audio.lock() {
                            audio.retire_stale_timeline_source_projection();
                        }
                        // The result belonged to the retired projection. It
                        // may clean up its own sinks, but it can never be
                        // attributed to the newly-current Follow generation.
                        timeline_sync_result = None;
                        snapshot = after_sync.clone();
                    }
                    // Never hold the Rodio/device mutex across an engine
                    // publication acknowledgement. The ACK is generation
                    // fenced, so a Follow that retired while device work was
                    // in flight simply rejects this stale report.
                    if let Some((context, timeline_sync_result)) = timeline_sync_result {
                        let current_context = TimelineAudioPrepareCoordinator::context(
                            &engine,
                            &audio,
                            &after_sync.timeline_audio,
                        );
                        let audio_ack_result = match timeline_sync_result {
                            Ok(()) => TimelineFollowSettlementAckResult::Applied,
                            Err(fault) => TimelineFollowSettlementAckResult::Fault { fault },
                        };
                        if current_context.as_ref() == Some(&context) {
                            if let Some(acknowledgement) =
                                pending_timeline_follow_audio_settlement_ack_for_context(
                                    &engine,
                                    context.follow,
                                    audio_ack_result,
                                )
                            {
                                let _ = engine.acknowledge_timeline_follow_settlement_published(
                                    acknowledgement,
                                    Instant::now() + Duration::from_secs(2),
                                );
                            }
                        }
                    }
                    let low_latency_poll = worker_handoff
                        .state
                        .lock()
                        .map(|state| state.needs_low_latency_poll(&snapshot.auto_vj_status))
                        .unwrap_or(false);
                    let wait_for = if active || low_latency_poll {
                        MEDIA_AUDIO_SYNC_INTERVAL
                    } else {
                        MEDIA_AUDIO_SYNC_IDLE_INTERVAL
                    };
                    match worker_handoff.state.lock() {
                        Ok(state) if state.pending_job.is_none() => {
                            let _ = worker_handoff.wake.wait_timeout(state, wait_for);
                        }
                        Ok(_) => {}
                        Err(_) => std::thread::sleep(wait_for),
                    }
                }
                // Never detach the nested decoder/output prepare worker when
                // the owning media runtime stops. Cancellation closes its
                // short commit window; joining here keeps every filesystem,
                // decoder and Router lease owned until the outer worker exits.
                timeline_prepare.shutdown();
            })
            .expect("failed to start media audio sync worker");
        Self {
            stop,
            program_handoff,
            worker: Some(worker),
        }
    }
}

impl Drop for MediaAudioSyncRuntime {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::Release);
        self.program_handoff.wake.notify_all();
        if let Some(worker) = self.worker.take() {
            let _ = worker.join();
        }
    }
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn program_audio_source_request(
    layers: &[protocol::VideoLayerSummary],
    plan: &ProgramAudioHandoffPlan,
) -> Result<Option<ProgramAudioSourceRequest>, String> {
    let Some(layer) = layers.iter().find(|layer| layer.id == plan.layer_id) else {
        return Err(format!(
            "Auto VJ Program audio target layer {} was not found",
            plan.layer_id
        ));
    };
    let has_monitorable_audio = layer.source.kind == VideoSourceKind::File
        && layer
            .source
            .metadata
            .map(|metadata| metadata.has_audio)
            .unwrap_or(true);
    let Some(path) = layer
        .source
        .path
        .as_deref()
        .filter(|path| !path.trim().is_empty())
        .filter(|_| has_monitorable_audio)
    else {
        return Ok(None);
    };
    if layer.state.speed < 0.0 {
        return Err(
            "Reverse video audio monitoring is not supported for Auto VJ Program audio".to_string(),
        );
    }
    Ok(Some(ProgramAudioSourceRequest {
        layer_id: plan.layer_id,
        path: PathBuf::from(path),
        position_ms: layer.state.position_ms,
        speed: layer.state.speed,
        volume: plan.volume.clamp(0.0, 2.0),
        requested_device_name: plan
            .device_name
            .as_deref()
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .map(str::to_string),
    }))
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn prepare_program_audio_handoff(
    audio: &Arc<Mutex<MediaAudioPlayback>>,
    slot: &Arc<audio_output_router::RouterSlot>,
    request: ProgramAudioSourceRequest,
) -> Result<PreparedProgramAudioHandoff, String> {
    let output = ensure_normal_program_output(audio, slot, request.requested_device_name.clone())?;
    // File/device decoding is intentionally outside `media_audio`: a slow
    // filesystem or decoder may not hold the playback state mutex.
    let file = fs::File::open(&request.path).map_err(|error| {
        format!(
            "Failed to open media audio '{}': {error}",
            request.path.display()
        )
    })?;
    let decoder = rodio::Decoder::try_from(file).map_err(|error| {
        format!(
            "Failed to decode media audio '{}': {error}",
            request.path.display()
        )
    })?;
    let sink = rodio::Sink::connect_new(&output.mixer);
    sink.append(decoder);
    sink.set_volume(request.volume);
    sink.set_speed(if request.speed > f32::EPSILON {
        request.speed.clamp(0.25, 4.0)
    } else {
        1.0
    });
    if request.position_ms > 0 {
        sink.try_seek(Duration::from_millis(request.position_ms))
            .map_err(|error| format!("Failed to seek media audio: {error}"))?;
    }
    Ok(PreparedProgramAudioHandoff {
        request,
        output_generation: output.generation,
        sink,
    })
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn commit_program_audio_handoff(
    coordinator: &ProgramAudioHandoffCoordinator,
    audio: &Arc<Mutex<MediaAudioPlayback>>,
    generation: u64,
    prepared: PreparedProgramAudioHandoff,
) -> bool {
    let mut prepared = Some(prepared);
    let mut retired_sinks = Vec::new();
    let committed = audio
        .lock()
        .map(|mut playback| {
            let Some(prepared_ref) = prepared.as_ref() else {
                return false;
            };
            if coordinator.generation.load(Ordering::Acquire) != generation
                || playback.audio_device_generation != prepared_ref.output_generation
                || playback.normal_output.is_none()
                || !playback.pending_normal_output_retirements.is_empty()
            {
                return false;
            }
            let prepared = prepared.take().expect("prepared PROGRAM sink commits once");
            let active_layer_ids = playback.sinks.keys().copied().collect::<Vec<_>>();
            for layer_id in active_layer_ids {
                if layer_id != prepared.request.layer_id {
                    if let Some(sink) = playback.sinks.remove(&layer_id) {
                        retired_sinks.push(sink);
                    }
                    playback.sources.remove(&layer_id);
                    playback.last_resync_at.remove(&layer_id);
                }
            }
            if let Some(previous) = playback.sinks.remove(&prepared.request.layer_id) {
                retired_sinks.push(previous);
            }
            playback.sources.insert(
                prepared.request.layer_id,
                MediaAudioSourceConfig {
                    path: prepared.request.path.clone(),
                    volume: prepared.request.volume,
                    requested_device_name: prepared.request.requested_device_name.clone(),
                },
            );
            playback
                .last_resync_at
                .insert(prepared.request.layer_id, Instant::now());
            playback
                .sinks
                .insert(prepared.request.layer_id, prepared.sink);
            playback.last_sync_error = None;
            true
        })
        .unwrap_or(false);
    for sink in retired_sinks {
        sink.stop();
    }
    if let Some(prepared) = prepared {
        prepared.sink.stop();
    }
    committed
}

/// Detaches a single PROGRAM monitor sink under the state mutex and performs
/// the Rodio stop only after releasing it. Error paths use this too, so a
/// failed decode/authority check cannot accidentally reintroduce OS work
/// under `media_audio`.
#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn stop_program_audio_layer_outside_lock(
    audio: &Arc<Mutex<MediaAudioPlayback>>,
    layer_id: VideoLayerId,
    detail: Option<String>,
) {
    let sink = audio.lock().ok().and_then(|mut playback| {
        playback.sources.remove(&layer_id);
        playback.last_resync_at.remove(&layer_id);
        playback.last_sync_error = detail;
        playback.sinks.remove(&layer_id)
    });
    if let Some(sink) = sink {
        sink.stop();
    }
}

/// Used by ASIO quiesce and explicit PROGRAM stop. It clears state first but
/// preserves the stop-before-stream-retirement ordering at the caller.
#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn stop_all_program_audio_sinks_outside_lock(audio: &Arc<Mutex<MediaAudioPlayback>>) {
    let sinks = audio
        .lock()
        .map(|mut playback| {
            playback.sources.clear();
            playback.last_resync_at.clear();
            playback
                .sinks
                .drain()
                .map(|(_, sink)| sink)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    for sink in sinks {
        sink.stop();
    }
}

/// Rebuilds PROGRAM monitoring through the Router when its selected normal
/// device changes. The old lease is explicitly drained first; every decode or
/// commit failure is surfaced after the route has been retired, never hidden
/// by leaving an old stream under a changed device selection.
#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn reconfigure_normal_program_audio_route(
    coordinator: &ProgramAudioHandoffCoordinator,
    audio: &Arc<Mutex<MediaAudioPlayback>>,
    slot: &Arc<audio_output_router::RouterSlot>,
    layers: &[protocol::VideoLayerSummary],
    generation: u64,
    previous_volume: f32,
    volume: f32,
    device_name: Option<&str>,
) -> Result<(), String> {
    let requested_device_name = device_name
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .map(str::to_owned);
    let requests = {
        let mut playback = audio
            .lock()
            .map_err(|_| "Media audio playback lock was poisoned".to_string())?;
        if coordinator.generation.load(Ordering::Acquire) != generation {
            return Err("PROGRAM audio reconfigure became stale before planning".to_string());
        }
        if playback.requested_device_name == requested_device_name {
            let volumes = playback
                .sources
                .iter()
                .filter_map(|(layer_id, source)| {
                    let layer = layers.iter().find(|layer| layer.id == *layer_id)?;
                    Some((
                        *layer_id,
                        reconfigured_program_audio_volume(
                            source.volume,
                            previous_volume,
                            volume,
                            layer.state.opacity,
                        ),
                    ))
                })
                .collect::<Vec<_>>();
            for (layer_id, next_volume) in volumes {
                if let Some(sink) = playback.sinks.get(&layer_id) {
                    sink.set_volume(next_volume);
                }
                if let Some(source) = playback.sources.get_mut(&layer_id) {
                    source.volume = next_volume;
                    source.requested_device_name = requested_device_name.clone();
                }
            }
            return Ok(());
        }
        playback
            .sources
            .iter()
            .filter_map(|(layer_id, source)| {
                let layer = layers.iter().find(|layer| layer.id == *layer_id)?;
                (layer.state.speed >= 0.0).then(|| ProgramAudioSourceRequest {
                    layer_id: *layer_id,
                    path: source.path.clone(),
                    position_ms: layer.state.position_ms,
                    speed: layer.state.speed,
                    volume: reconfigured_program_audio_volume(
                        source.volume,
                        previous_volume,
                        volume,
                        layer.state.opacity,
                    ),
                    requested_device_name: requested_device_name.clone(),
                })
            })
            .collect::<Vec<_>>()
    };

    retire_active_normal_program_output(audio, "normal PROGRAM device replacement", false)?;
    if requests.is_empty() {
        // A selected device change still installs the route deliberately so
        // its availability is validated now rather than deferred to a later
        // video-layer handoff.
        ensure_normal_program_output(audio, slot, requested_device_name)?;
        return Ok(());
    }
    for request in requests {
        let prepared = prepare_program_audio_handoff(audio, slot, request)?;
        if !commit_program_audio_handoff(coordinator, audio, generation, prepared) {
            return Err("PROGRAM audio reconfigure became stale before commit".to_string());
        }
    }
    Ok(())
}

fn execute_program_audio_job(
    coordinator: &ProgramAudioHandoffCoordinator,
    audio: &Arc<Mutex<MediaAudioPlayback>>,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    output_router: Option<&Arc<audio_output_router::RouterSlot>>,
    layers: &[protocol::VideoLayerSummary],
    job: ProgramAudioJob,
) {
    let generation = job.generation;
    if coordinator.generation.load(Ordering::Acquire) != generation {
        return;
    }
    let ownership = match job.kind {
        ProgramAudioJobKind::Handoff(plan) => {
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            let active = match program_audio_source_request(layers, &plan) {
                Ok(Some(request)) => match output_router {
                    Some(slot) => match prepare_program_audio_handoff(audio, slot, request) {
                        Ok(prepared) => {
                            commit_program_audio_handoff(coordinator, audio, generation, prepared)
                        }
                        Err(error) => {
                            stop_program_audio_layer_outside_lock(
                                audio,
                                plan.layer_id,
                                Some(error),
                            );
                            false
                        }
                    },
                    None => {
                        stop_program_audio_layer_outside_lock(
                            audio,
                            plan.layer_id,
                            Some(
                                "Normal PROGRAM output router process owner is unavailable"
                                    .to_string(),
                            ),
                        );
                        false
                    }
                },
                Ok(None) => {
                    stop_program_audio_layer_outside_lock(audio, plan.layer_id, None);
                    false
                }
                Err(error) => {
                    stop_program_audio_layer_outside_lock(audio, plan.layer_id, Some(error));
                    false
                }
            };
            #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
            let active = audio
                .lock()
                .map(|mut audio| {
                    if coordinator.generation.load(Ordering::Acquire) != generation {
                        return false;
                    }
                    let active = audio.apply_program_handoff(layers, &plan);
                    if coordinator.generation.load(Ordering::Acquire) != generation {
                        audio.stop(plan.layer_id);
                        false
                    } else {
                        active
                    }
                })
                .unwrap_or(false);
            Some((active.then_some(plan.layer_id), Some(plan.layer_id)))
        }
        ProgramAudioJobKind::StopAll => {
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            {
                if coordinator.generation.load(Ordering::Acquire) != generation {
                    return;
                }
                stop_all_program_audio_sinks_outside_lock(audio);
            }
            #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
            if let Ok(mut audio) = audio.lock() {
                if coordinator.generation.load(Ordering::Acquire) != generation {
                    return;
                }
                audio.stop_all();
            }
            Some((None, None))
        }
        ProgramAudioJobKind::ReconfigureActive {
            previous_volume,
            volume,
            device_name,
        } => {
            #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
            if let Ok(mut audio) = audio.lock() {
                if coordinator.generation.load(Ordering::Acquire) != generation {
                    return;
                }
                audio.reconfigure_active(layers, previous_volume, volume, device_name.as_deref());
            }
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            {
                let result = match output_router {
                    Some(slot) => reconfigure_normal_program_audio_route(
                        coordinator,
                        audio,
                        slot,
                        layers,
                        generation,
                        previous_volume,
                        volume,
                        device_name.as_deref(),
                    ),
                    None => {
                        Err("Normal PROGRAM output router process owner is unavailable".to_string())
                    }
                };
                if let Err(error) = result {
                    if let Ok(mut playback) = audio.lock() {
                        playback.last_sync_error = Some(error);
                    }
                }
            }
            None
        }
    };
    if let Some((owned_layer_id, desired_layer_id)) = ownership {
        if let Ok(mut state) = coordinator.state.lock() {
            // The generation must be rechecked while holding the state lock.
            // Otherwise a newer queued job can be overwritten by this completion.
            if coordinator.generation.load(Ordering::Acquire) == generation {
                state.owned_layer_id = owned_layer_id;
                state.desired_layer_id = desired_layer_id;
            }
        }
    }
}

