#[derive(Debug)]
struct LiveAudioInputCaptureTelemetry {
    started_at: Instant,
    dropped_chunks: AtomicU64,
    dropped_frames: AtomicU64,
    callback_count: AtomicU64,
    last_callback_frames: AtomicU64,
    min_callback_frames: AtomicU64,
    max_callback_frames: AtomicU64,
    capture_to_worker_us: AtomicU64,
    max_capture_to_worker_us: AtomicU64,
    queue_depth_high_water: AtomicU64,
    worker_heartbeat_us: AtomicU64,
}

impl Default for LiveAudioInputCaptureTelemetry {
    fn default() -> Self {
        Self {
            started_at: Instant::now(),
            dropped_chunks: AtomicU64::new(0),
            dropped_frames: AtomicU64::new(0),
            callback_count: AtomicU64::new(0),
            last_callback_frames: AtomicU64::new(0),
            min_callback_frames: AtomicU64::new(u64::MAX),
            max_callback_frames: AtomicU64::new(0),
            capture_to_worker_us: AtomicU64::new(0),
            max_capture_to_worker_us: AtomicU64::new(0),
            queue_depth_high_water: AtomicU64::new(0),
            worker_heartbeat_us: AtomicU64::new(0),
        }
    }
}

impl LiveAudioInputCaptureTelemetry {
    fn elapsed_us(&self) -> u64 {
        self.started_at.elapsed().as_micros().min(u64::MAX as u128) as u64
    }

    fn mark_worker_heartbeat(&self) {
        self.worker_heartbeat_us
            .store(self.elapsed_us(), Ordering::Release);
    }

    fn worker_heartbeat_is_stale_at(&self, now_us: u64) -> bool {
        now_us.saturating_sub(self.worker_heartbeat_us.load(Ordering::Acquire))
            >= LIVE_AUDIO_STALE_AFTER.as_micros() as u64
    }

    fn worker_heartbeat_is_stale(&self) -> bool {
        self.worker_heartbeat_is_stale_at(self.elapsed_us())
    }
}

#[derive(Debug)]
struct LiveAudioSampleChunk {
    samples: Box<[f32; LIVE_AUDIO_CAPTURE_SLOT_FRAMES]>,
    len: usize,
    callback_at: Instant,
    device_delay: Duration,
}

impl LiveAudioSampleChunk {
    fn new() -> Self {
        Self {
            samples: Box::new([0.0; LIVE_AUDIO_CAPTURE_SLOT_FRAMES]),
            len: 0,
            callback_at: Instant::now(),
            device_delay: Duration::ZERO,
        }
    }
}

#[derive(Debug, Default)]
struct LiveAudioInputSafety {
    terminal_fault: AtomicBool,
    terminal_fault_finalized: AtomicBool,
    clear_pending: AtomicBool,
    shutdown_requested: AtomicBool,
}

impl LiveAudioInputSafety {
    fn terminal_faulted(&self) -> bool {
        self.terminal_fault.load(Ordering::Acquire)
    }

    fn mark_terminal_fault(&self) {
        self.terminal_fault.store(true, Ordering::Release);
    }

    fn claim_terminal_fault_finalization(&self) -> bool {
        self.mark_terminal_fault();
        self.terminal_fault_finalized
            .compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire)
            .is_ok()
    }

    fn request_shutdown(&self) {
        self.shutdown_requested.store(true, Ordering::Release);
        self.mark_terminal_fault();
    }

    fn shutdown_requested(&self) -> bool {
        self.shutdown_requested.load(Ordering::Acquire)
    }

    fn clear_pending(&self) -> bool {
        self.clear_pending.load(Ordering::Acquire)
    }

    fn record_clear_result(&self, result: &Result<(), String>) {
        self.clear_pending.store(result.is_err(), Ordering::Release);
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct DeferredLiveAudioTerminalFault {
    source: u32,
    kind: u32,
}

#[derive(Debug, Default)]
struct DeferredLiveAudioTerminalFaultLatch {
    encoded: AtomicU64,
}

impl DeferredLiveAudioTerminalFaultLatch {
    fn latch(&self, source: u32, kind: u32) -> bool {
        if source == 0 || source == u32::MAX {
            return false;
        }
        let encoded = (u64::from(source) << 32) | u64::from(kind);
        self.encoded
            .compare_exchange(0, encoded, Ordering::AcqRel, Ordering::Acquire)
            .is_ok()
    }

    fn claim(&self) -> Option<DeferredLiveAudioTerminalFault> {
        loop {
            let encoded = self.encoded.load(Ordering::Acquire);
            if encoded == 0 || encoded == LIVE_AUDIO_TERMINAL_EVENT_HANDLED {
                return None;
            }
            if self
                .encoded
                .compare_exchange(
                    encoded,
                    LIVE_AUDIO_TERMINAL_EVENT_HANDLED,
                    Ordering::AcqRel,
                    Ordering::Acquire,
                )
                .is_ok()
            {
                return Some(DeferredLiveAudioTerminalFault {
                    source: (encoded >> 32) as u32,
                    kind: encoded as u32,
                });
            }
        }
    }
}

#[derive(Debug)]
struct LiveAudioInputWatchdog {
    last_chunk_at: Instant,
    stale: bool,
}

impl LiveAudioInputWatchdog {
    fn new(now: Instant) -> Self {
        Self {
            last_chunk_at: now,
            stale: false,
        }
    }

    fn receive_wait(&self, now: Instant) -> Duration {
        if self.stale {
            LIVE_AUDIO_RECEIVE_POLL_INTERVAL
        } else {
            LIVE_AUDIO_STALE_AFTER
                .saturating_sub(now.saturating_duration_since(self.last_chunk_at))
                .min(LIVE_AUDIO_RECEIVE_POLL_INTERVAL)
        }
    }

    fn mark_stale_if_due(&mut self, now: Instant) -> bool {
        if self.stale || now.saturating_duration_since(self.last_chunk_at) < LIVE_AUDIO_STALE_AFTER
        {
            return false;
        }
        self.stale = true;
        true
    }

    fn record_chunk(&mut self, now: Instant) -> bool {
        let recovered = self.stale
            || now.saturating_duration_since(self.last_chunk_at) >= LIVE_AUDIO_STALE_AFTER;
        self.last_chunk_at = now;
        self.stale = false;
        recovered
    }

    fn defer_recovery(&mut self) {
        self.stale = true;
    }
}

enum LiveAudioCaptureStream {
    #[cfg(not(target_os = "macos"))]
    Wasapi {
        _stream: rodio::cpal::Stream,
    },
    #[cfg(target_os = "macos")]
    Mac {
        owner: mac_audio_resources::MacAudioInputStream,
    },
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    Asio {
        _session: asio_bridge_v2::AsioStreamSession<asio_bridge_v2::VtableTransport>,
    },
}

struct LiveAudioInput {
    generation: Arc<AtomicU64>,
    generation_gate: Arc<Mutex<()>>,
    stream: Option<LiveAudioCaptureStream>,
    stop: Arc<AtomicBool>,
    worker: Option<std::thread::JoinHandle<()>>,
    status: Arc<Mutex<LiveAudioInputStatus>>,
    safety: Arc<LiveAudioInputSafety>,
    ready_capture_chunks: Arc<crossbeam_queue::ArrayQueue<LiveAudioSampleChunk>>,
    capture_telemetry: Arc<LiveAudioInputCaptureTelemetry>,
    engine: EngineHandle,
}

/// Drops the capture stream, explicitly stopping and closing an ABI v2 ASIO
/// session so its raw bridge handle is released exactly once. Returns the
/// visible close failure, if any; the handle is consumed regardless.
fn close_live_audio_capture_stream(stream: Option<LiveAudioCaptureStream>) -> Option<String> {
    match stream {
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        Some(LiveAudioCaptureStream::Asio { _session }) => {
            // Close owns the raw bridge handle even on failure; the operator
            // must explicitly start again either way.
            teardown_asio_v2_stream(_session).err()
        }
        other => {
            drop(other);
            None
        }
    }
}

impl Drop for LiveAudioInput {
    fn drop(&mut self) {
        self.safety.mark_terminal_fault();
        let stream_close_failure = close_live_audio_capture_stream(self.stream.take());
        self.stop.store(true, Ordering::Relaxed);
        if let Some(worker) = self.worker.as_ref() {
            worker.thread().unpark();
        }
        if let Some(worker) = self.worker.take() {
            let _ = worker.join();
        }
        let _generation_gate = self
            .generation_gate
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let clear_pending = !send_current_live_audio_clear_bounded(&self.engine, &self.generation);
        if let Ok(mut status) = self.status.lock() {
            status.running = false;
            status.stale = false;
            status.safety_clear_pending = clear_pending;
            status.bass = 0.0;
            status.mid = 0.0;
            status.high = 0.0;
            status.bands.fill(0.0);
            status.band_count = 0;
            status.rms = 0.0;
            status.peak = 0.0;
            status.spectral_flux = 0.0;
            status.spectral_centroid = 0.0;
            status.spectral_density_fast = 0.0;
            status.spectral_density_slow = 0.0;
            status.kick_strength = 0.0;
            status.snare_strength = 0.0;
            status.kick_event = false;
            status.snare_event = false;
            status.onset = false;
            status.onset_strength = 0.0;
            status.bpm = None;
            status.bpm_confidence = 0.0;
            status.beat_phase = 0.0;
            status.feature_sequence = 0;
            status.last_error = stream_close_failure.or_else(|| {
                clear_pending.then(|| {
                    "Live audio stopped, but the engine safety clear is still pending".to_string()
                })
            });
        }
    }
}

#[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
fn prepare_media_audio_output(
    requested_device_name: Option<&str>,
) -> Result<PreparedMediaAudioOutput, String> {
    #[cfg(target_os = "macos")]
    {
        let output = mac_audio_resources::MacAudioOutput::open(requested_device_name, true)?;
        let mixer = output.mixer().clone();
        let device_name = requested_device_name
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .map(str::to_owned)
            .or_else(|| output.device_name().map(str::to_owned));
        return Ok(PreparedMediaAudioOutput::Direct {
            stream: output,
            mixer,
            device_name,
            requested_device_name: requested_device_name
                .map(str::trim)
                .filter(|name| !name.is_empty())
                .map(str::to_owned),
        });
    }
    #[cfg(not(target_os = "macos"))]
    {
    use rodio::cpal::traits::{DeviceTrait, HostTrait};

    let requested_device_name = requested_device_name
        .map(str::trim)
        .filter(|name| !name.is_empty());
    let host = rodio::cpal::default_host();
    let device = match requested_device_name {
        Some(name) => host
            .output_devices()
            .map_err(|error| format!("Failed to list audio output devices: {error}"))?
            .find(|device| device.name().ok().as_deref() == Some(name))
            .ok_or_else(|| format!("Audio output device '{name}' was not found"))?,
        None => host
            .default_output_device()
            .ok_or_else(|| "No default audio output device is available".to_string())?,
    };
    let resolved_name = device.name().ok();
    let stream = rodio::OutputStreamBuilder::from_device(device)
        .and_then(|builder| builder.open_stream_or_fallback())
        .map_err(|error| format!("Failed to open audio output: {error}"))?;
    let mixer = stream.mixer().clone();
    Ok(PreparedMediaAudioOutput::Direct {
        stream,
        mixer,
        device_name: requested_device_name.map(str::to_string).or(resolved_name),
        requested_device_name: requested_device_name.map(str::to_string),
    })
    }
}

fn prepare_timeline_audio_clip(
    request: TimelineAudioPrepareRequest,
    mixer: &rodio::mixer::Mixer,
) -> PreparedTimelineAudioClipResult {
    let speed = match validate_timeline_audio_speed(request.source.speed_milli) {
        Ok(speed) => speed,
        Err(error) => return Err(Box::new((request, error))),
    };
    let file = match fs::File::open(&request.clip.path) {
        Ok(file) => file,
        Err(error) => {
            let message = format!(
                "Timeline audio clip {} could not open '{}': {error}",
                request.clip.id, request.clip.path
            );
            return Err(Box::new((request, message)));
        }
    };
    let decoder = match rodio::Decoder::try_from(file) {
        Ok(decoder) => decoder,
        Err(error) => {
            let message = format!(
                "Timeline audio clip {} could not decode '{}': {error}",
                request.clip.id, request.clip.path
            );
            return Err(Box::new((request, message)));
        }
    };
    let sink = rodio::Sink::connect_new(mixer);
    sink.pause();
    sink.set_volume(request.volume.clamp(0.0, 2.0));
    sink.set_speed(speed);
    Ok(PreparedTimelineAudioClip {
        request,
        sink: Some(sink),
        decoder: Some(decoder),
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        asio_identity: None,
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        explicit_wdm_timeline_fence: None,
    })
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn prepare_explicit_wdm_timeline_audio_clip(
    request: TimelineAudioPrepareRequest,
    output: &ExplicitWdmTimelineOutputSnapshot,
) -> PreparedTimelineAudioClipResult {
    let mut prepared = prepare_timeline_audio_clip(request, &output.mixer)?;
    prepared.explicit_wdm_timeline_fence = Some(ExternalWdmTimelineRouteFence {
        owner: Some(output.owner),
        generation: output.output_clock_epoch,
    });
    Ok(prepared)
}

#[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
fn prepare_asio_timeline_audio_clip(
    request: TimelineAudioPrepareRequest,
    runtime: &Arc<Mutex<asio_output_runtime::AsioOutputRuntime>>,
) -> PreparedTimelineAudioClipResult {
    if let Err(error) = validate_timeline_audio_speed(request.source.speed_milli) {
        return Err(Box::new((request, error)));
    }
    let identity = match runtime
        .lock()
        .map_err(|_| "show-ASIO output runtime lock was poisoned".to_owned())
        .and_then(|mut runtime| runtime.current_output_identity(request.source.output_bus))
    {
        Ok(identity) => identity,
        Err(error) => return Err(Box::new((request, error))),
    };
    let file = match fs::File::open(&request.clip.path) {
        Ok(file) => file,
        Err(error) => {
            let message = format!(
                "Timeline audio clip {} could not open '{}': {error}",
                request.clip.id, request.clip.path
            );
            return Err(Box::new((request, message)));
        }
    };
    let decoder = match rodio::Decoder::try_from(file) {
        Ok(decoder) => decoder,
        Err(error) => {
            let message = format!(
                "Timeline audio clip {} could not decode '{}': {error}",
                request.clip.id, request.clip.path
            );
            return Err(Box::new((request, message)));
        }
    };
    Ok(PreparedTimelineAudioClip {
        request,
        sink: None,
        decoder: Some(decoder),
        asio_identity: Some(identity),
        explicit_wdm_timeline_fence: None,
    })
}

fn rebase_prepared_timeline_audio_clips(
    current: &engine::TimelineAudioRuntimeSnapshot,
    prepared_clips: Vec<PreparedTimelineAudioClipResult>,
) -> Vec<PreparedTimelineAudioClipResult> {
    let active = timeline_audio_active_clips(current)
        .into_iter()
        .map(|(key, clip, position_ms, speed)| (key, (clip, position_ms, speed)))
        .collect::<HashMap<_, _>>();
    prepared_clips
        .into_iter()
        .map(|prepared| {
            let mut prepared = prepared?;
            let Some((clip, position_ms, speed)) = active.get(&prepared.request.key) else {
                return Ok(prepared);
            };
            if clip.path != prepared.request.clip.path
                || clip.offset_ms != prepared.request.clip.offset_ms
                || *speed != prepared.request.source.speed_milli
            {
                return Ok(prepared);
            }
            let source_position_ms = position_ms
                .saturating_sub(clip.start_ms)
                .saturating_add(clip.offset_ms);
            if source_position_ms == prepared.request.source_position_ms {
                return Ok(prepared);
            }
            prepared.request.source_position_ms = source_position_ms;
            Ok(prepared)
        })
        .collect()
}

fn seek_prepared_timeline_audio_decoders(
    prepared_clips: Vec<PreparedTimelineAudioClipResult>,
) -> Vec<PreparedTimelineAudioClipResult> {
    use rodio::Source;

    prepared_clips
        .into_iter()
        .map(|prepared| {
            let mut prepared = prepared?;
            let Some(decoder) = prepared.decoder.as_mut() else {
                prepared.stop();
                return Err(Box::new((
                    prepared.request,
                    "Timeline audio decoder was already consumed before sink install".to_string(),
                )));
            };
            if prepared.request.source_position_ms > 0 {
                if let Err(error) =
                    decoder.try_seek(Duration::from_millis(prepared.request.source_position_ms))
                {
                    prepared.stop();
                    let message = format!(
                        "Timeline audio clip {} decoder seek failed: {error}",
                        prepared.request.clip.id
                    );
                    return Err(Box::new((prepared.request, message)));
                }
            }
            Ok(prepared)
        })
        .collect()
}

fn append_prepared_timeline_audio_decoders(
    prepared_clips: Vec<PreparedTimelineAudioClipResult>,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    asio_output_runtime: Option<&Arc<Mutex<asio_output_runtime::AsioOutputRuntime>>>,
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    timeline_cue_audio: Option<&Arc<TimelineCueAudioRuntime>>,
    #[cfg(all(test, target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    mut before_explicit_wdm_postcheck: Option<&mut dyn FnMut()>,
) -> Vec<PreparedTimelineAudioClipResult> {
    prepared_clips
        .into_iter()
        .map(|prepared| {
            let mut prepared = prepared?;
            let Some(decoder) = prepared.decoder.take() else {
                prepared.stop();
                return Err(Box::new((
                    prepared.request,
                    "Timeline audio decoder was already consumed before sink append".to_string(),
                )));
            };
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            if let Some(output_fence) = prepared.explicit_wdm_timeline_fence {
                let Some(cue_runtime) = timeline_cue_audio else {
                    prepared.stop();
                    return Err(Box::new((
                        prepared.request,
                        "Explicit WDM CUE runtime owner is unavailable during Timeline source attachment"
                            .to_owned(),
                    )));
                };
                let current = cue_runtime
                    .explicit_wdm_output_is_current_blocking(output_fence)
                    .map_err(|error| Box::new((prepared.request.clone(), error)))?;
                if !current {
                    prepared.stop();
                    return Err(Box::new((
                        prepared.request,
                        "Explicit WDM CUE output changed before Timeline source attachment"
                            .to_owned(),
                    )));
                }
                let Some(sink) = prepared.sink.as_ref() else {
                    return Err(Box::new((
                        prepared.request,
                        "Explicit WDM CUE sink was missing before source append".to_owned(),
                    )));
                };
                sink.append(decoder);
                #[cfg(all(
                    test,
                    target_os = "windows",
                    target_arch = "x86_64",
                    feature = "asio"
                ))]
                if let Some(before_postcheck) = before_explicit_wdm_postcheck.as_deref_mut() {
                    before_postcheck();
                }
                let current = cue_runtime
                    .explicit_wdm_output_is_current_blocking(output_fence)
                    .map_err(|error| Box::new((prepared.request.clone(), error)))?;
                if !current {
                    prepared.stop();
                    return Err(Box::new((
                        prepared.request,
                        "Explicit WDM CUE output changed during Timeline source attachment"
                            .to_owned(),
                    )));
                }
                return Ok(prepared);
            }
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            if let Some(identity) = prepared.asio_identity.take() {
                let Some(runtime) = asio_output_runtime else {
                    return Err(Box::new((
                        prepared.request,
                        "show-ASIO output runtime owner is unavailable during Timeline source attachment"
                            .to_owned(),
                    )));
                };
                let sink = match runtime
                    .lock()
                    .map_err(|_| "show-ASIO output runtime lock was poisoned".to_owned())
                    .and_then(|mut runtime| runtime.attach_source(identity, decoder, true))
                {
                    Ok(sink) => sink,
                    Err(error) => return Err(Box::new((prepared.request, error))),
                };
                sink.set_volume(prepared.request.volume.clamp(0.0, 2.0));
                let speed = match validate_timeline_audio_speed(prepared.request.source.speed_milli) {
                    Ok(speed) => speed,
                    Err(error) => return Err(Box::new((prepared.request, error))),
                };
                sink.set_speed(speed);
                prepared.sink = Some(sink);
                return Ok(prepared);
            }
            let Some(sink) = prepared.sink.as_ref() else {
                return Err(Box::new((
                    prepared.request,
                    "Timeline audio sink was missing before source append".to_owned(),
                )));
            };
            sink.append(decoder);
            Ok(prepared)
        })
        .collect()
}

fn prepared_timeline_audio_clips_need_rebase(
    current: &engine::TimelineAudioRuntimeSnapshot,
    prepared_clips: &[PreparedTimelineAudioClipResult],
) -> bool {
    let active = timeline_audio_active_clips(current)
        .into_iter()
        .map(|(key, clip, position_ms, speed)| (key, (clip, position_ms, speed)))
        .collect::<HashMap<_, _>>();
    prepared_clips.iter().any(|prepared| {
        let Ok(prepared) = prepared else {
            return false;
        };
        let Some((clip, position_ms, speed)) = active.get(&prepared.request.key) else {
            return false;
        };
        if clip.path != prepared.request.clip.path
            || clip.offset_ms != prepared.request.clip.offset_ms
            || *speed != prepared.request.source.speed_milli
        {
            return false;
        }
        let source_position_ms = position_ms
            .saturating_sub(clip.start_ms)
            .saturating_add(clip.offset_ms);
        source_position_ms.abs_diff(prepared.request.source_position_ms)
            > MEDIA_AUDIO_RESYNC_THRESHOLD_MS
    })
}

impl MediaAudioPlayback {
    fn active_program_mixer(&self) -> Option<rodio::mixer::Mixer> {
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        {
            self.normal_output
                .as_ref()
                .map(normal_audio_output::NormalAudioOutput::mixer)
        }
        #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
        {
            self.stream.as_ref().map(|stream| stream.mixer().clone())
        }
    }

    fn playback_mixer(&self) -> Option<rodio::mixer::Mixer> {
        self.active_program_mixer().or_else(|| {
            #[cfg(test)]
            {
                self.timeline_test_mixer.clone()
            }
            #[cfg(not(test))]
            {
                None
            }
        })
    }

    fn accept_timeline_source_projection_authority(
        &mut self,
        current: engine::TimelineAudioProjectionAuthority,
    ) -> Result<(), String> {
        let Some(previous) = self.timeline_source_projection_authority else {
            self.timeline_source_projection_authority = Some(current);
            return Ok(());
        };
        if current == previous {
            return Ok(());
        }
        if (current.epoch, current.generation) < (previous.epoch, previous.generation) {
            self.retire_stale_timeline_source_projection();
            return Err("Timeline audio source projection authority regressed".to_string());
        }
        let expected = protocol::control_plane_command::next_timeline_transport_authority(
            previous.epoch,
            previous.generation,
        )
        .map(|(epoch, generation)| engine::TimelineAudioProjectionAuthority { epoch, generation });
        if expected != Some(current) {
            // The worker did not observe every projection (for example
            // A->muted B->A while a decoder was opening). Retire sinks and
            // cached failures exactly once before rearming the current A.
            self.stop_all_timeline();
        }
        self.timeline_source_projection_authority = Some(current);
        Ok(())
    }

    fn retire_stale_timeline_source_projection(&mut self) {
        self.stop_all_timeline();
        self.timeline_source_projection_authority = None;
    }

    #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
    fn ensure_output_stream(&mut self, requested_device_name: Option<&str>) -> Result<(), String> {
        // Unit tests inject an in-memory mixer. It is not an OS route and is
        // therefore safe to exercise the timeline state machine without
        // asking a test-held mutex to publish a real Router lease.
        #[cfg(test)]
        if self.timeline_test_mixer.is_some() {
            return Ok(());
        }
        let requested_device_name = requested_device_name
            .map(str::trim)
            .filter(|name| !name.is_empty());
        if self.stream.is_some() && self.requested_device_name.as_deref() == requested_device_name {
            return Ok(());
        }
        let prepared = prepare_media_audio_output(requested_device_name)?;
        let mut prepared = Some(prepared);
        self.install_prepared_output(&mut prepared)?;
        Ok(())
    }

    /// The ASIO build never opens a Rodio stream while `media_audio` is held.
    /// Callers must first perform Router admission through the external
    /// coordinator, then this method may only confirm the installed lease.
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn ensure_output_stream(&mut self, requested_device_name: Option<&str>) -> Result<(), String> {
        // Unit tests inject an in-memory mixer and must never publish a real
        // Windows output route. Keep this test-only seam symmetric with the
        // non-ASIO implementation while production remains Router-only.
        #[cfg(test)]
        if self.timeline_test_mixer.is_some() {
            return Ok(());
        }
        let requested_device_name = requested_device_name
            .map(str::trim)
            .filter(|name| !name.is_empty());
        if self.normal_output.is_some()
            && self.requested_device_name.as_deref() == requested_device_name
            && self.pending_normal_output_retirements.is_empty()
        {
            Ok(())
        } else {
            Err(
                "Normal PROGRAM output requires Router admission outside the media playback lock"
                    .to_string(),
            )
        }
    }

    fn next_audio_device_generation(&self) -> Result<u64, String> {
        self.audio_device_generation.checked_add(1).ok_or_else(|| {
            "Media audio output device generation is exhausted; restart is required before another output stream can be installed"
                .to_string()
        })
    }

    fn install_prepared_output(
        &mut self,
        prepared: &mut Option<PreparedMediaAudioOutput>,
    ) -> Result<(), String> {
        // Reserve the next ABA fence before stopping any sink or replacing the
        // stream. Exhaustion is a permanent fail-closed boundary; generation
        // zero/one can never be recycled after u64::MAX.
        let next_device_generation = self.next_audio_device_generation()?;
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        if self.normal_output.is_some() || !self.pending_normal_output_retirements.is_empty() {
            return Err(
                "Normal PROGRAM output replacement requires explicit Router retirement first"
                    .to_string(),
            );
        }
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        if !self.sinks.is_empty() || !self.timeline_sinks.is_empty() {
            return Err(
                "Normal PROGRAM output install cannot stop active sinks while the media lock is held"
                    .to_string(),
            );
        }
        // All fail-closed preconditions must run before ownership leaves the
        // caller's PreparedMediaAudioOutputGuard.  Once taken, a Router lease
        // may only be installed below; an early return would otherwise drop
        // the live resource without its retirement receipt.
        let prepared = prepared
            .take()
            .ok_or_else(|| "Prepared media audio output was missing at install".to_string())?;
        #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
        {
            for (_, sink) in self.sinks.drain() {
                sink.stop();
            }
            for (_, sink) in self.timeline_sinks.drain() {
                sink.stop();
            }
        }
        self.sources.clear();
        self.last_resync_at.clear();
        self.timeline_sources.clear();
        self.timeline_source_clocks.clear();
        self.timeline_failures.clear();
        self.timeline_last_resync_at.clear();
        match prepared {
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            PreparedMediaAudioOutput::Router(output) => {
                self.device_name = output.device_name();
                self.requested_device_name = output.requested_device_name();
                self.normal_output = Some(output);
            }
            #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
            PreparedMediaAudioOutput::Direct {
                stream,
                device_name,
                requested_device_name,
                ..
            } => {
                self.stream = Some(stream);
                self.device_name = device_name;
                self.requested_device_name = requested_device_name;
            }
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio", test))]
            PreparedMediaAudioOutput::Test { mixer } => {
                self.timeline_test_mixer = Some(mixer);
            }
        }
        self.audio_device_generation = next_device_generation;
        Ok(())
    }

    #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
    fn apply_program_handoff(
        &mut self,
        layers: &[protocol::VideoLayerSummary],
        plan: &ProgramAudioHandoffPlan,
    ) -> bool {
        let active_layer_ids = self.sinks.keys().copied().collect::<Vec<_>>();
        for layer_id in active_layer_ids {
            if layer_id != plan.layer_id {
                self.stop(layer_id);
            }
        }

        let Some(layer) = layers.iter().find(|layer| layer.id == plan.layer_id) else {
            self.stop(plan.layer_id);
            self.last_sync_error = Some(format!(
                "Auto VJ Program audio target layer {} was not found",
                plan.layer_id
            ));
            return false;
        };
        let has_monitorable_audio = layer.source.kind == VideoSourceKind::File
            && layer
                .source
                .metadata
                .map(|metadata| metadata.has_audio)
                .unwrap_or(true);
        let Some(path) = layer
            .source
            .path
            .as_deref()
            .filter(|path| !path.trim().is_empty())
            .filter(|_| has_monitorable_audio)
        else {
            self.stop(plan.layer_id);
            self.last_sync_error = None;
            return false;
        };
        if layer.state.speed < 0.0 {
            self.stop(plan.layer_id);
            self.last_sync_error = Some(
                "Reverse video audio monitoring is not supported for Auto VJ Program audio"
                    .to_string(),
            );
            return false;
        }
        match self.play(
            plan.layer_id,
            Path::new(path),
            layer.state.position_ms,
            layer.state.speed,
            plan.volume,
            plan.device_name.as_deref(),
        ) {
            Ok(()) => {
                self.last_sync_error = None;
                true
            }
            Err(error) => {
                self.stop(plan.layer_id);
                self.last_sync_error = Some(error);
                false
            }
        }
    }

    fn play(
        &mut self,
        layer_id: VideoLayerId,
        path: &Path,
        position_ms: u64,
        speed: f32,
        volume: f32,
        requested_device_name: Option<&str>,
    ) -> Result<(), String> {
        if let Some(previous) = self.sinks.remove(&layer_id) {
            previous.stop();
        }
        let requested_device_name = requested_device_name
            .map(str::trim)
            .filter(|name| !name.is_empty());
        self.ensure_output_stream(requested_device_name)?;
        let file = fs::File::open(path)
            .map_err(|error| format!("Failed to open media audio '{}': {error}", path.display()))?;
        let decoder = rodio::Decoder::try_from(file).map_err(|error| {
            format!("Failed to decode media audio '{}': {error}", path.display())
        })?;
        let mixer = self
            .playback_mixer()
            .ok_or_else(|| "Audio output stream was not initialized".to_string())?;
        let sink = rodio::Sink::connect_new(&mixer);
        sink.append(decoder);
        sink.set_volume(volume.clamp(0.0, 2.0));
        sink.set_speed(if speed > f32::EPSILON {
            speed.clamp(0.25, 4.0)
        } else {
            1.0
        });
        if position_ms > 0 {
            sink.try_seek(Duration::from_millis(position_ms))
                .map_err(|error| format!("Failed to seek media audio: {error}"))?;
        }
        self.sinks.insert(layer_id, sink);
        self.sources.insert(
            layer_id,
            MediaAudioSourceConfig {
                path: path.to_path_buf(),
                volume: volume.clamp(0.0, 2.0),
                requested_device_name: requested_device_name.map(str::to_string),
            },
        );
        self.last_resync_at.insert(layer_id, Instant::now());
        Ok(())
    }

    fn stop(&mut self, layer_id: VideoLayerId) {
        if let Some(sink) = self.sinks.remove(&layer_id) {
            sink.stop();
        }
        self.sources.remove(&layer_id);
        self.last_resync_at.remove(&layer_id);
    }

    fn stop_all(&mut self) {
        let layer_ids = self.sinks.keys().copied().collect::<Vec<_>>();
        for layer_id in layer_ids {
            self.stop(layer_id);
        }
    }

    #[cfg(test)]
    fn play_timeline_clip(
        &mut self,
        source_projection_is_current: &mut impl FnMut() -> bool,
        key: TimelineAudioSinkKey,
        clip: &TimelineAudioClipSummary,
        source_position_ms: u64,
        volume: f32,
        speed_milli: u32,
    ) -> Result<(), String> {
        #[cfg(test)]
        {
            self.timeline_start_attempt_count = self.timeline_start_attempt_count.saturating_add(1);
        }
        if let Some(previous) = self.timeline_sinks.remove(&key) {
            previous.stop();
        }
        self.timeline_source_clocks.remove(&key);
        let requested_device_name = self.requested_device_name.clone();
        let file = fs::File::open(&clip.path).map_err(|error| {
            format!(
                "Timeline audio clip {} could not open '{}': {error}",
                clip.id, clip.path
            )
        })?;
        let decoder = rodio::Decoder::try_from(file).map_err(|error| {
            format!(
                "Timeline audio clip {} could not decode '{}': {error}",
                clip.id, clip.path
            )
        })?;
        if !source_projection_is_current() {
            return Err(
                "Timeline audio source projection changed while its decoder was opening"
                    .to_string(),
            );
        }
        self.ensure_output_stream(requested_device_name.as_deref())?;
        let mixer = self
            .playback_mixer()
            .ok_or_else(|| "Audio output stream was not initialized".to_string())?;
        let sink = rodio::Sink::connect_new(&mixer);
        let speed = validate_timeline_audio_speed(speed_milli)?;
        sink.append(decoder);
        sink.set_volume(volume.clamp(0.0, 2.0));
        sink.set_speed(speed);
        if source_position_ms > 0 {
            seek_timeline_audio_sink_to_source_ms(&sink, source_position_ms, speed_milli)
                .map_err(|error| format!("Timeline audio clip {} seek failed: {error}", clip.id))?;
        }
        let source_clock = TimelineAudioSourceClock {
            source_anchor_ms: source_position_ms,
            output_anchor_ms: timeline_audio_sink_output_position_ms(&sink),
        };
        sink.play();
        self.timeline_sinks.insert(key.clone(), sink);
        self.timeline_sources.insert(
            key.clone(),
            TimelineAudioSourceConfig {
                path: PathBuf::from(&clip.path),
                gain: clip.gain.clamp(0.0, 2.0),
                offset_ms: clip.offset_ms,
                speed_milli,
                output_bus: clip.output_bus,
            },
        );
        self.timeline_source_clocks
            .insert(key.clone(), source_clock);
        self.timeline_last_resync_at.insert(key, Instant::now());
        Ok(())
    }

    fn stop_timeline_clip(&mut self, key: TimelineAudioSinkKey) {
        if let Some(sink) = self.timeline_sinks.remove(&key) {
            #[cfg(test)]
            {
                self.timeline_stop_count = self.timeline_stop_count.saturating_add(1);
            }
            sink.stop();
        }
        self.timeline_sources.remove(&key);
        self.timeline_source_clocks.remove(&key);
        self.timeline_failures.remove(&key);
        self.timeline_last_resync_at.remove(&key);
    }

    fn stop_all_timeline(&mut self) {
        let keys = self.timeline_sinks.keys().cloned().collect::<Vec<_>>();
        for key in keys {
            self.stop_timeline_clip(key);
        }
        self.timeline_failures.clear();
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
    fn observe_external_wdm_timeline_route(
        &mut self,
        fence: Option<ExternalWdmTimelineRouteFence>,
    ) {
        let Some(fence) = fence else {
            // A busy or poisoned lifecycle lock is not evidence that an old
            // WDM route remains owned. Fail closed at the playback boundary,
            // then let the next worker tick republish a fresh exact route if
            // the runtime becomes observable again.
            self.stop_all_timeline();
            self.hybrid_cue_output_generation = 0;
            self.external_wdm_timeline_owner = None;
            return;
        };
        if self.hybrid_cue_output_generation == fence.generation
            && self.external_wdm_timeline_owner == fence.owner
        {
            return;
        }
        let authoring_monitor_changed = self.external_wdm_timeline_owner
            == Some(ExplicitWdmTimelineOwner::NormalAuthoring)
            || fence.owner == Some(ExplicitWdmTimelineOwner::NormalAuthoring);
        if authoring_monitor_changed {
            // The Normal authoring monitor owns every Timeline bus. Entering,
            // leaving, or replacing it must retire all prior Timeline sinks.
            self.stop_all_timeline();
        } else {
            let cue_keys = self
                .timeline_sources
                .iter()
                .filter_map(|(key, source)| {
                    (source.output_bus == protocol::TimelineAudioOutputBus::Cue)
                        .then(|| key.clone())
                })
                .collect::<Vec<_>>();
            for key in cue_keys {
                self.stop_timeline_clip(key);
            }
            self.timeline_failures.retain(|_, failure| {
                failure.source.output_bus != protocol::TimelineAudioOutputBus::Cue
            });
        }
        self.hybrid_cue_output_generation = fence.generation;
        self.external_wdm_timeline_owner = fence.owner;
    }

    fn apply_timeline_transport_barrier(
        &mut self,
        action: TimelineAudioTransportAction,
        muted: bool,
    ) -> bool {
        if muted || matches!(action, TimelineAudioTransportAction::Stop) {
            self.stop_all_timeline();
            return false;
        }
        if matches!(action, TimelineAudioTransportAction::Recue) {
            self.stop_all_timeline();
        }
        true
    }

    /// Sync only program Timeline clips. Metronome and Guide are intentionally
    /// outside this result: neither is a Follow audio-settlement consumer, so
    /// their device failures must not incorrectly fault a captured Follow.
    fn plan_timeline_audio_sync(
        &mut self,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
    ) -> Result<TimelineAudioSyncPlan, String> {
        self.accept_timeline_source_projection_authority(timeline.source_projection_authority)?;
        let now = Instant::now();
        let action = timeline_audio_transport_action(
            self.timeline_transport,
            timeline.playing,
            timeline.position_ms,
            timeline.transport_revision,
            now,
        );
        self.timeline_transport = TimelineAudioTransportState {
            playing: timeline.playing,
            position_ms: timeline.position_ms,
            transport_revision: timeline.transport_revision,
            synced_at: Some(now),
        };
        let mut plan = TimelineAudioSyncPlan {
            authority: timeline.source_projection_authority,
            device_generation: self.audio_device_generation,
            hybrid_cue_output_generation: self.hybrid_cue_output_generation,
            #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
            external_wdm_timeline_owner: self.external_wdm_timeline_owner,
            requested_device_name: self.requested_device_name.clone(),
            mixer: self.active_program_mixer().or_else(|| {
                #[cfg(test)]
                {
                    self.timeline_test_mixer.clone()
                }
                #[cfg(not(test))]
                {
                    None
                }
            }),
            prepares: Vec::new(),
            seeks: Vec::new(),
            errors: Vec::new(),
            cue_errors: Vec::new(),
        };
        if !self.apply_timeline_transport_barrier(action, timeline.muted) {
            self.timeline_last_sync_error = None;
            return Ok(plan);
        }

        let active_clips = timeline_audio_active_clips(timeline);
        let active_ids = active_clips
            .iter()
            .map(|(key, _, _, _)| key.clone())
            .collect::<HashSet<_>>();
        let stale_ids = self
            .timeline_sinks
            .keys()
            .filter(|&key| !active_ids.contains(key))
            .cloned()
            .collect::<Vec<_>>();
        for key in stale_ids {
            self.stop_timeline_clip(key);
        }
        self.timeline_failures
            .retain(|key, _| active_ids.contains(key));

        for (key, clip, local_position_ms, speed_milli) in active_clips {
            let source_position_ms = local_position_ms
                .saturating_sub(clip.start_ms)
                .saturating_add(clip.offset_ms);
            let volume = timeline_audio_clip_volume(&clip, local_position_ms);
            let source = TimelineAudioSourceConfig {
                path: PathBuf::from(&clip.path),
                gain: clip.gain.clamp(0.0, 2.0),
                offset_ms: clip.offset_ms,
                speed_milli,
                output_bus: clip.output_bus,
            };
            if let Err(error) = validate_timeline_audio_speed(speed_milli) {
                self.stop_timeline_clip(key.clone());
                self.timeline_failures.insert(
                    key,
                    TimelineAudioPlaybackFailure {
                        source,
                        error: error.clone(),
                    },
                );
                if clip.output_bus == protocol::TimelineAudioOutputBus::Cue {
                    plan.cue_errors.push(error);
                    continue;
                }
                return Err(error);
            }
            let source_changed = self.timeline_sources.get(&key).is_some_and(|current| {
                current.path != source.path
                    || current.offset_ms != source.offset_ms
                    || current.speed_milli != source.speed_milli
                    || current.output_bus != source.output_bus
            });
            if source_changed {
                self.stop_timeline_clip(key.clone());
            }
            if !self.timeline_sinks.contains_key(&key) {
                if let Some(failure) = self.timeline_failures.get(&key) {
                    if failure.source == source
                        && matches!(action, TimelineAudioTransportAction::Sync)
                    {
                        if failure.source.output_bus == protocol::TimelineAudioOutputBus::Cue {
                            plan.cue_errors.push(failure.error.clone());
                        } else {
                            plan.errors.push(failure.error.clone());
                        }
                        continue;
                    }
                }
                self.timeline_failures.remove(&key);
                #[cfg(test)]
                {
                    self.timeline_start_attempt_count =
                        self.timeline_start_attempt_count.saturating_add(1);
                }
                plan.prepares.push(TimelineAudioPrepareRequest {
                    key,
                    clip,
                    source_position_ms,
                    volume,
                    source,
                });
                continue;
            }
            if let Some(source_state) = self.timeline_sources.get_mut(&key) {
                source_state.gain = clip.gain.clamp(0.0, 2.0);
                source_state.offset_ms = clip.offset_ms;
                source_state.speed_milli = speed_milli;
                source_state.output_bus = clip.output_bus;
            }
            let Some(sink) = self.timeline_sinks.get(&key) else {
                continue;
            };
            sink.set_volume(volume.clamp(0.0, 2.0));
            if sink.empty() {
                continue;
            }
            let Some(source_clock) = self.timeline_source_clocks.get(&key).copied() else {
                let error = format!(
                    "Timeline audio clip {} lost its source-time clock; sink was retired fail-closed",
                    clip.id
                );
                self.stop_timeline_clip(key.clone());
                if clip.output_bus == protocol::TimelineAudioOutputBus::Cue {
                    plan.cue_errors.push(error);
                } else {
                    plan.errors.push(error);
                }
                continue;
            };
            let actual_source_ms = match timeline_audio_source_position_at_output_time(
                source_clock,
                timeline_audio_sink_output_position_ms(sink),
                speed_milli,
            ) {
                Ok(position_ms) => position_ms,
                Err(error) => {
                    self.stop_timeline_clip(key.clone());
                    if clip.output_bus == protocol::TimelineAudioOutputBus::Cue {
                        plan.cue_errors.push(error);
                    } else {
                        plan.errors.push(error);
                    }
                    continue;
                }
            };
            let drift_ms = timeline_audio_source_drift_ms(actual_source_ms, source_position_ms);
            self.last_drift_ms = drift_ms;
            self.max_abs_drift_ms = self.max_abs_drift_ms.max(drift_ms.unsigned_abs());
            let cooldown_elapsed = self
                .timeline_last_resync_at
                .get(&key)
                .map(|last| now.saturating_duration_since(*last))
                .unwrap_or(Duration::MAX);
            if media_audio_resync_required(drift_ms, cooldown_elapsed) {
                let sink = self
                    .timeline_sinks
                    .remove(&key)
                    .expect("Timeline seek plan must own the observed sink");
                plan.seeks.push(TimelineAudioSeekRequest {
                    key,
                    clip_id: clip.id,
                    sink,
                    source_position_ms,
                    speed_milli,
                });
            }
        }
        Ok(plan)
    }

    fn commit_timeline_audio_sync(
        &mut self,
        plan: TimelineAudioSyncPlan,
        current: &engine::TimelineAudioRuntimeSnapshot,
        prepared_output: &mut Option<PreparedMediaAudioOutput>,
        prepared_clips: Vec<PreparedTimelineAudioClipResult>,
        seek_results: Vec<(TimelineAudioSeekRequest, Result<(), String>)>,
    ) -> Result<(), String> {
        #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
        let external_wdm_owner_changed =
            self.external_wdm_timeline_owner != plan.external_wdm_timeline_owner;
        #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
        let external_wdm_owner_changed = false;
        if current.source_projection_authority != plan.authority
            || self.timeline_source_projection_authority != Some(plan.authority)
            || self.audio_device_generation != plan.device_generation
            || self.hybrid_cue_output_generation != plan.hybrid_cue_output_generation
            || external_wdm_owner_changed
            || self.requested_device_name != plan.requested_device_name
        {
            stop_prepared_timeline_audio_clips(prepared_clips);
            for (seek, _) in seek_results {
                seek.sink.stop();
            }
            return Err(
                "Timeline audio source projection or output device changed during preparation"
                    .to_string(),
            );
        }

        if prepared_output.is_some() {
            self.install_prepared_output(prepared_output)?;
            self.timeline_source_projection_authority = Some(plan.authority);
        }
        let active = timeline_audio_active_clips(current)
            .into_iter()
            .map(|(key, clip, position_ms, speed_milli)| {
                let source = TimelineAudioSourceConfig {
                    path: PathBuf::from(&clip.path),
                    gain: clip.gain.clamp(0.0, 2.0),
                    offset_ms: clip.offset_ms,
                    speed_milli,
                    output_bus: clip.output_bus,
                };
                Ok((key, (clip, position_ms, source)))
            })
            .collect::<Result<HashMap<_, _>, String>>()?;
        let now = Instant::now();
        let mut errors = plan.errors;
        let mut cue_errors = plan.cue_errors;
        for (seek, result) in seek_results {
            let current_source = active.get(&seek.key).map(|(_, _, source)| source);
            let still_current = active.contains_key(&seek.key)
                && self.timeline_sources.contains_key(&seek.key)
                && !self.timeline_sinks.contains_key(&seek.key);
            if !still_current {
                seek.sink.stop();
                self.timeline_source_clocks.remove(&seek.key);
                continue;
            }
            match result {
                Ok(()) => {
                    self.resync_count = self.resync_count.saturating_add(1);
                    let speed_milli = current_source
                        .expect("current Timeline source must exist for an admitted drift re-seek")
                        .speed_milli;
                    // `speed_milli` is an immutable source identity guard. It
                    // is revalidated here so a malformed stale seek cannot
                    // install a clock under an invalid rate.
                    if let Err(error) = validate_timeline_audio_speed(speed_milli) {
                        seek.sink.stop();
                        self.timeline_source_clocks.remove(&seek.key);
                        if current_source.is_some_and(|source| {
                            source.output_bus == protocol::TimelineAudioOutputBus::Cue
                        }) {
                            cue_errors.push(error);
                        } else {
                            errors.push(error);
                        }
                        continue;
                    }
                    self.timeline_source_clocks.insert(
                        seek.key.clone(),
                        TimelineAudioSourceClock {
                            source_anchor_ms: seek.source_position_ms,
                            output_anchor_ms: timeline_audio_sink_output_position_ms(&seek.sink),
                        },
                    );
                    self.timeline_last_resync_at.insert(seek.key.clone(), now);
                    self.timeline_sinks.insert(seek.key, seek.sink);
                }
                Err(error) => {
                    seek.sink.stop();
                    self.timeline_source_clocks.remove(&seek.key);
                    let error = format!(
                        "Timeline audio clip {} drift resync failed: {error}",
                        seek.clip_id
                    );
                    if current_source.is_some_and(|source| {
                        source.output_bus == protocol::TimelineAudioOutputBus::Cue
                    }) {
                        cue_errors.push(error);
                    } else {
                        errors.push(error);
                    }
                }
            }
        }
        for prepared in prepared_clips {
            match prepared {
                Ok(mut prepared) => {
                    let Some((current_clip, current_position_ms, current_source)) =
                        active.get(&prepared.request.key)
                    else {
                        prepared.stop();
                        continue;
                    };
                    if current_source.path != prepared.request.source.path
                        || current_source.offset_ms != prepared.request.source.offset_ms
                        || current_source.speed_milli != prepared.request.source.speed_milli
                        || current_source.output_bus != prepared.request.source.output_bus
                        || self.timeline_sinks.contains_key(&prepared.request.key)
                    {
                        prepared.stop();
                        continue;
                    }
                    let Some(sink) = prepared.sink.take() else {
                        let cue_only = prepared.request.source.output_bus
                            == protocol::TimelineAudioOutputBus::Cue;
                        let error = format!(
                            "Timeline audio clip {} had no attached sink at commit",
                            prepared.request.clip.id
                        );
                        self.timeline_failures.insert(
                            prepared.request.key,
                            TimelineAudioPlaybackFailure {
                                source: prepared.request.source,
                                error: error.clone(),
                            },
                        );
                        if cue_only {
                            cue_errors.push(error);
                        } else {
                            errors.push(error);
                        }
                        continue;
                    };
                    sink.set_volume(
                        timeline_audio_clip_volume(current_clip, *current_position_ms)
                            .clamp(0.0, 2.0),
                    );
                    #[cfg(test)]
                    self.timeline_last_install_source_position_ms.insert(
                        prepared.request.key.clone(),
                        prepared.request.source_position_ms,
                    );
                    self.timeline_source_clocks.insert(
                        prepared.request.key.clone(),
                        TimelineAudioSourceClock {
                            source_anchor_ms: prepared.request.source_position_ms,
                            output_anchor_ms: timeline_audio_sink_output_position_ms(&sink),
                        },
                    );
                    sink.play();
                    self.timeline_sources
                        .insert(prepared.request.key.clone(), current_source.clone());
                    self.timeline_last_resync_at
                        .insert(prepared.request.key.clone(), now);
                    self.timeline_failures.remove(&prepared.request.key);
                    self.timeline_sinks.insert(prepared.request.key, sink);
                }
                Err(error) => {
                    let (request, error) = *error;
                    let cue_only =
                        request.source.output_bus == protocol::TimelineAudioOutputBus::Cue;
                    self.timeline_failures.insert(
                        request.key,
                        TimelineAudioPlaybackFailure {
                            source: request.source,
                            error: error.clone(),
                        },
                    );
                    if cue_only {
                        cue_errors.push(error);
                    } else {
                        errors.push(error);
                    }
                }
            }
        }
        let settlement_error = (!errors.is_empty()).then(|| errors.join("; "));
        errors.extend(cue_errors);
        self.timeline_last_sync_error = (!errors.is_empty()).then(|| errors.join("; "));
        settlement_error.map_or(Ok(()), Err)
    }

    #[cfg(test)]
    fn sync_to_timeline_audio_evidenced_with_fence(
        &mut self,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
        mut source_projection_is_current: impl FnMut() -> bool,
    ) -> Result<(), String> {
        self.accept_timeline_source_projection_authority(timeline.source_projection_authority)?;
        let now = Instant::now();
        let action = timeline_audio_transport_action(
            self.timeline_transport,
            timeline.playing,
            timeline.position_ms,
            timeline.transport_revision,
            now,
        );
        self.timeline_transport = TimelineAudioTransportState {
            playing: timeline.playing,
            position_ms: timeline.position_ms,
            transport_revision: timeline.transport_revision,
            synced_at: Some(now),
        };
        if !self.apply_timeline_transport_barrier(action, timeline.muted) {
            self.timeline_last_sync_error = None;
            return Ok(());
        }

        let mut active_clips = timeline
            .clips
            .iter()
            .filter(|clip| {
                clip.duration_ms > 0
                    && timeline.position_ms >= clip.start_ms
                    && timeline.position_ms < clip.start_ms.saturating_add(clip.duration_ms)
            })
            .map(|clip| {
                (
                    TimelineAudioSinkKey::Root(clip.id),
                    clip,
                    timeline.position_ms,
                    1_000,
                )
            })
            .collect::<Vec<_>>();
        active_clips.extend(timeline.child_clips.iter().map(|child| {
            let key = match child.root {
                engine::ChildTimelineAudioRuntimeRoot::Direct {
                    parent_cue_id,
                    generation,
                } => TimelineAudioSinkKey::DirectChild {
                    parent_cue_id,
                    generation,
                    path: Arc::clone(&child.path),
                    clip_id: child.clip.id,
                },
                engine::ChildTimelineAudioRuntimeRoot::Timeline {
                    parent_event_id,
                    parent_iteration,
                } => TimelineAudioSinkKey::Child {
                    parent_event_id,
                    parent_iteration,
                    path: Arc::clone(&child.path),
                    clip_id: child.clip.id,
                },
                engine::ChildTimelineAudioRuntimeRoot::Follow {
                    source_timeline_id,
                    target_timeline_id,
                    generation,
                    target_root,
                } => TimelineAudioSinkKey::Follow {
                    source_timeline_id,
                    target_timeline_id,
                    generation,
                    target_root,
                    path: Arc::clone(&child.path),
                    clip_id: child.clip.id,
                },
            };
            (
                key,
                &child.clip,
                child.position_ms,
                child.playback_rate_milli,
            )
        }));
        let active_ids = active_clips
            .iter()
            .map(|(key, _, _, _)| key.clone())
            .collect::<HashSet<_>>();
        let stale_ids = self
            .timeline_sinks
            .keys()
            .filter(|&key| !active_ids.contains(key))
            .cloned()
            .collect::<Vec<_>>();
        for key in stale_ids {
            self.stop_timeline_clip(key);
        }
        self.timeline_failures
            .retain(|key, _| active_ids.contains(key));

        let mut errors = Vec::new();
        let mut cue_errors = Vec::new();
        for (key, clip, local_position_ms, speed_milli) in active_clips {
            let source_position_ms = local_position_ms
                .saturating_sub(clip.start_ms)
                .saturating_add(clip.offset_ms);
            let volume = timeline_audio_clip_volume(clip, local_position_ms);
            let source_config = TimelineAudioSourceConfig {
                path: PathBuf::from(&clip.path),
                gain: clip.gain.clamp(0.0, 2.0),
                offset_ms: clip.offset_ms,
                speed_milli,
                output_bus: clip.output_bus,
            };
            if let Err(error) = validate_timeline_audio_speed(speed_milli) {
                self.stop_timeline_clip(key.clone());
                self.timeline_failures.insert(
                    key,
                    TimelineAudioPlaybackFailure {
                        source: source_config,
                        error: error.clone(),
                    },
                );
                if clip.output_bus == protocol::TimelineAudioOutputBus::Cue {
                    cue_errors.push(error);
                } else {
                    errors.push(error);
                }
                continue;
            }
            let source_changed = self.timeline_sources.get(&key).is_some_and(|source| {
                source.path.as_path() != Path::new(&clip.path)
                    || source.offset_ms != clip.offset_ms
                    || source.speed_milli != speed_milli
                    || source.output_bus != clip.output_bus
            });
            if source_changed {
                self.stop_timeline_clip(key.clone());
            }
            if !self.timeline_sinks.contains_key(&key) {
                if let Some(failure) = self.timeline_failures.get(&key) {
                    if failure.source == source_config
                        && matches!(action, TimelineAudioTransportAction::Sync)
                    {
                        if clip.output_bus == protocol::TimelineAudioOutputBus::Cue {
                            cue_errors.push(failure.error.clone());
                        } else {
                            errors.push(failure.error.clone());
                        }
                        continue;
                    }
                }
                self.timeline_failures.remove(&key);
                if let Err(error) = self.play_timeline_clip(
                    &mut source_projection_is_current,
                    key.clone(),
                    clip,
                    source_position_ms,
                    volume,
                    speed_milli,
                ) {
                    self.stop_timeline_clip(key.clone());
                    self.timeline_failures.insert(
                        key.clone(),
                        TimelineAudioPlaybackFailure {
                            source: source_config,
                            error: error.clone(),
                        },
                    );
                    if clip.output_bus == protocol::TimelineAudioOutputBus::Cue {
                        cue_errors.push(error);
                    } else {
                        errors.push(error);
                    }
                    continue;
                }
            }
            if let Some(source) = self.timeline_sources.get_mut(&key) {
                source.gain = clip.gain.clamp(0.0, 2.0);
                source.offset_ms = clip.offset_ms;
                source.speed_milli = speed_milli;
                source.output_bus = clip.output_bus;
            }
            let Some(sink) = self.timeline_sinks.get(&key) else {
                continue;
            };
            sink.set_volume(volume.clamp(0.0, 2.0));
            if sink.empty() {
                continue;
            }
            let Some(source_clock) = self.timeline_source_clocks.get(&key).copied() else {
                let error = format!(
                    "Timeline audio clip {} lost its source-time clock; sink was retired fail-closed",
                    clip.id
                );
                self.stop_timeline_clip(key.clone());
                if clip.output_bus == protocol::TimelineAudioOutputBus::Cue {
                    cue_errors.push(error);
                } else {
                    errors.push(error);
                }
                continue;
            };
            let actual_source_ms = match timeline_audio_source_position_at_output_time(
                source_clock,
                timeline_audio_sink_output_position_ms(sink),
                speed_milli,
            ) {
                Ok(position_ms) => position_ms,
                Err(error) => {
                    self.stop_timeline_clip(key.clone());
                    if clip.output_bus == protocol::TimelineAudioOutputBus::Cue {
                        cue_errors.push(error);
                    } else {
                        errors.push(error);
                    }
                    continue;
                }
            };
            let drift_ms = timeline_audio_source_drift_ms(actual_source_ms, source_position_ms);
            self.last_drift_ms = drift_ms;
            self.max_abs_drift_ms = self.max_abs_drift_ms.max(drift_ms.unsigned_abs());
            let cooldown_elapsed = self
                .timeline_last_resync_at
                .get(&key)
                .map(|last| now.saturating_duration_since(*last))
                .unwrap_or(Duration::MAX);
            if media_audio_resync_required(drift_ms, cooldown_elapsed) {
                match seek_timeline_audio_sink_to_source_ms(sink, source_position_ms, speed_milli) {
                    Ok(()) => {
                        self.resync_count = self.resync_count.saturating_add(1);
                        self.timeline_source_clocks.insert(
                            key.clone(),
                            TimelineAudioSourceClock {
                                source_anchor_ms: source_position_ms,
                                output_anchor_ms: timeline_audio_sink_output_position_ms(sink),
                            },
                        );
                        self.timeline_last_resync_at.insert(key, now);
                    }
                    Err(error) => {
                        let error = format!(
                            "Timeline audio clip {} drift resync failed: {error}",
                            clip.id
                        );
                        if clip.output_bus == protocol::TimelineAudioOutputBus::Cue {
                            cue_errors.push(error);
                        } else {
                            errors.push(error);
                        }
                    }
                }
            }
        }
        self.timeline_last_sync_error = (!errors.is_empty() || !cue_errors.is_empty()).then(|| {
            errors
                .iter()
                .chain(cue_errors.iter())
                .cloned()
                .collect::<Vec<_>>()
                .join("; ")
        });
        (!errors.is_empty())
            .then(|| errors.join("; "))
            .map_or(Ok(()), Err)
    }

    #[cfg(test)]
    fn sync_to_timeline_audio_evidenced(
        &mut self,
        timeline: &engine::TimelineAudioRuntimeSnapshot,
    ) -> Result<(), String> {
        self.sync_to_timeline_audio_evidenced_with_fence(timeline, || true)
    }

    #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
    fn reconfigure_active(
        &mut self,
        layers: &[protocol::VideoLayerSummary],
        previous_volume: f32,
        volume: f32,
        device_name: Option<&str>,
    ) {
        let device_name = device_name.map(str::trim).filter(|name| !name.is_empty());
        let requested_device_changed = self.requested_device_name.as_deref() != device_name;
        let active = self
            .sources
            .iter()
            .filter_map(|(layer_id, source)| {
                let layer = layers.iter().find(|layer| layer.id == *layer_id)?;
                let next_volume = reconfigured_program_audio_volume(
                    source.volume,
                    previous_volume,
                    volume,
                    layer.state.opacity,
                );
                Some((
                    *layer_id,
                    source.path.clone(),
                    layer.state.position_ms,
                    layer.state.speed,
                    next_volume,
                ))
            })
            .collect::<Vec<_>>();

        if !requested_device_changed {
            for (layer_id, _, _, _, next_volume) in active {
                if let Some(sink) = self.sinks.get(&layer_id) {
                    sink.set_volume(next_volume);
                }
                if let Some(source) = self.sources.get_mut(&layer_id) {
                    source.volume = next_volume;
                    source.requested_device_name = device_name.map(str::to_string);
                }
            }
            return;
        }

        self.stop_all();
        self.stop_all_timeline();
        self.stream = None;
        self.device_name = None;
        self.requested_device_name = None;
        let mut errors = Vec::new();
        for (layer_id, path, position_ms, speed, next_volume) in active {
            if speed < 0.0 {
                errors.push(format!(
                    "Reverse video audio monitoring is not supported for layer {layer_id}"
                ));
                continue;
            }
            if let Err(error) = self.play(
                layer_id,
                &path,
                position_ms,
                speed,
                next_volume,
                device_name,
            ) {
                errors.push(error);
            }
        }
        self.last_sync_error = (!errors.is_empty()).then(|| errors.join("; "));
    }

    fn set_volume(&mut self, layer_id: VideoLayerId, volume: f32) -> Result<(), String> {
        let sink = self
            .sinks
            .get(&layer_id)
            .ok_or_else(|| format!("Video layer {layer_id} audio monitor is not active"))?;
        sink.set_volume(volume.clamp(0.0, 2.0));
        if let Some(source) = self.sources.get_mut(&layer_id) {
            source.volume = volume.clamp(0.0, 2.0);
        }
        Ok(())
    }

    fn sync_to_video_layers(&mut self, layers: &[protocol::VideoLayerSummary]) {
        let now = Instant::now();
        let mut remove = Vec::new();
        let mut restart = Vec::new();
        for (layer_id, sink) in &self.sinks {
            let Some(layer) = layers.iter().find(|layer| layer.id == *layer_id) else {
                remove.push(*layer_id);
                continue;
            };
            let speed = if layer.state.speed > f32::EPSILON {
                layer.state.speed.clamp(0.25, 4.0)
            } else {
                1.0
            };
            sink.set_speed(speed);
            if layer.state.playing {
                sink.play();
            } else {
                sink.pause();
            }
            if sink.empty() {
                if layer.state.playing && layer.state.loop_enabled {
                    if let Some(source) = self.sources.get(layer_id).cloned() {
                        restart.push((*layer_id, source, layer.state.position_ms, speed));
                    }
                }
                continue;
            }
            let actual_ms = sink.get_pos().as_millis().min(i64::MAX as u128) as i64;
            let desired_ms = layer.state.position_ms.min(i64::MAX as u64) as i64;
            let drift_ms = actual_ms.saturating_sub(desired_ms);
            self.last_drift_ms = drift_ms;
            self.max_abs_drift_ms = self.max_abs_drift_ms.max(drift_ms.unsigned_abs());
            let cooldown_elapsed = self
                .last_resync_at
                .get(layer_id)
                .map(|last| now.saturating_duration_since(*last))
                .unwrap_or(Duration::MAX);
            if media_audio_resync_required(drift_ms, cooldown_elapsed) {
                match sink.try_seek(Duration::from_millis(layer.state.position_ms)) {
                    Ok(()) => {
                        self.resync_count = self.resync_count.saturating_add(1);
                        self.last_resync_at.insert(*layer_id, now);
                        self.last_sync_error = None;
                    }
                    Err(error) => {
                        self.last_sync_error = Some(format!(
                            "Audio resync failed for video layer {layer_id}: {error}"
                        ));
                    }
                }
            }
        }
        for layer_id in remove {
            self.stop(layer_id);
        }
        for (layer_id, source, position_ms, speed) in restart {
            match self.play(
                layer_id,
                &source.path,
                position_ms,
                speed,
                source.volume,
                source.requested_device_name.as_deref(),
            ) {
                Ok(()) => {
                    self.resync_count = self.resync_count.saturating_add(1);
                    self.last_sync_error = None;
                }
                Err(error) => self.last_sync_error = Some(error),
            }
        }
    }

    fn status(&mut self) -> VideoAudioMonitorStatus {
        self.sinks.retain(|_, sink| !sink.empty());
        self.sources
            .retain(|layer_id, _| self.sinks.contains_key(layer_id));
        self.last_resync_at
            .retain(|layer_id, _| self.sinks.contains_key(layer_id));
        let mut active_layer_ids = self.sinks.keys().copied().collect::<Vec<_>>();
        active_layer_ids.sort_unstable();
        VideoAudioMonitorStatus {
            output_open: {
                #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio"))]
                {
                    self.normal_output.is_some()
                }
                #[cfg(not(all(target_os = "windows", target_arch = "x86_64", feature = "asio")))]
                {
                    self.stream.is_some()
                }
            },
            device_name: self.device_name.clone(),
            active_layer_ids,
            resync_count: self.resync_count,
            last_drift_ms: self.last_drift_ms,
            max_abs_drift_ms: self.max_abs_drift_ms,
            last_sync_error: self
                .timeline_last_sync_error
                .clone()
                .or_else(|| self.last_sync_error.clone()),
        }
    }
}

