#[tauri::command]
fn download_gdtf_from_url(window: WebviewWindow, url: String) -> Result<Option<String>, String> {
    let trimmed_url = validate_gdtf_download_url(&url)?;
    let Some(path) = parented_file_dialog(&window)
        .add_filter("GDTF Fixture", &["gdtf"])
        .set_file_name(gdtf_download_file_name_from_url(trimmed_url))
        .save_file()
    else {
        return Ok(None);
    };
    let path = normalize_gdtf_save_path(path)?;

    let status = Command::new(curl_binary_name())
        .args([
            "-L",
            "--fail",
            "--silent",
            "--show-error",
            "--max-time",
            "60",
            "-o",
        ])
        .arg(&path)
        .arg(trimmed_url)
        .status()
        .map_err(|error| format!("Failed to start curl for GDTF download: {error}"))?;

    if !status.success() {
        let _ = fs::remove_file(&path);
        return Err(format!(
            "GDTF download failed with status {}",
            status
                .code()
                .map(|code| code.to_string())
                .unwrap_or_else(|| "terminated".to_string())
        ));
    }

    gdtf::load_profile(&path).map_err(|error| {
        let _ = fs::remove_file(&path);
        format!("Downloaded file is not a valid GDTF archive: {error}")
    })?;

    Ok(Some(path.to_string_lossy().to_string()))
}

#[tauri::command]
fn search_gdtf_share(request: GdtfShareSearchRequest) -> Result<GdtfShareSearchResponse, String> {
    validate_gdtf_share_credentials(&request.user, &request.password)?;
    let cookie_path = gdtf_share_cookie_path();
    let result = (|| {
        login_gdtf_share(&request.user, &request.password, &cookie_path)?;
        let catalog = fetch_gdtf_share_catalog(&cookie_path)?;
        let fixtures = extract_gdtf_share_fixtures(&catalog);
        if fixtures.is_empty() {
            return Err(
                "GDTF Share catalog response did not contain fixture records Syndocal can read"
                    .to_string(),
            );
        }
        Ok(filter_gdtf_share_results(
            fixtures,
            GdtfShareFilterOptions {
                manufacturer: request.manufacturer.as_deref().unwrap_or_default(),
                fixture: request.fixture.as_deref().unwrap_or_default(),
                query: request.query.as_deref().unwrap_or_default(),
                mode: request.mode.as_deref().unwrap_or_default(),
                min_footprint: request.min_footprint,
                max_footprint: request.max_footprint,
                release_only: request.release_only.unwrap_or(false),
                tested_in_visualizer: request.tested_in_visualizer.unwrap_or(false),
                tested_in_real_life: request.tested_in_real_life.unwrap_or(false),
                limit: request.limit.unwrap_or(40),
            },
        ))
    })();
    let _ = fs::remove_file(&cookie_path);
    result
}

#[tauri::command]
fn download_gdtf_from_share(
    window: WebviewWindow,
    request: GdtfShareDownloadRequest,
) -> Result<Option<String>, String> {
    validate_gdtf_share_credentials(&request.user, &request.password)?;
    validate_gdtf_share_download_identity(&request)?;
    let Some(path) = parented_file_dialog(&window)
        .add_filter("GDTF Fixture", &["gdtf"])
        .set_file_name(gdtf_share_download_file_name(&request))
        .save_file()
    else {
        return Ok(None);
    };
    let path = normalize_gdtf_save_path(path)?;

    let cookie_path = gdtf_share_cookie_path();
    let result = (|| {
        login_gdtf_share(&request.user, &request.password, &cookie_path)?;
        download_gdtf_share_file(&request, &cookie_path, &path)?;
        gdtf::load_profile(&path).map_err(|error| {
            let _ = fs::remove_file(&path);
            format!("Downloaded GDTF Share file is not a valid GDTF archive: {error}")
        })?;
        Ok(Some(path.to_string_lossy().to_string()))
    })();
    let _ = fs::remove_file(&cookie_path);
    result
}

#[tauri::command]
fn list_gdtf_fixture_cache(app: tauri::AppHandle) -> Result<Vec<GdtfFixtureCacheEntry>, String> {
    let directory = app_data_subdirectory_path(&app, FIXTURE_PROFILE_CACHE_DIRECTORY)?;
    inspect_gdtf_fixture_cache_directory(&directory)
}

#[tauri::command]
fn cache_gdtf_from_share(
    app: tauri::AppHandle,
    request: GdtfShareDownloadRequest,
) -> Result<GdtfFixtureCacheEntry, String> {
    validate_gdtf_share_credentials(&request.user, &request.password)?;
    validate_gdtf_share_download_identity(&request)?;
    let directory = app_data_subdirectory(&app, FIXTURE_PROFILE_CACHE_DIRECTORY)?;
    let metadata = gdtf_fixture_cache_metadata(&request);
    let path = gdtf_fixture_cache_path(&directory, &metadata);
    if path.is_file() {
        let entry = inspect_gdtf_cache_file(&path, Some(metadata.clone()))?;
        if entry.health == "healthy" || entry.health == "warnings" {
            return Ok(entry);
        }
    }

    let partial_path = directory.join(format!(
        ".{}-{}-{}.partial",
        safe_file_stem(&metadata.key),
        std::process::id(),
        current_unix_ms()
    ));
    let cookie_path = gdtf_share_cookie_path();
    let result = (|| {
        login_gdtf_share(&request.user, &request.password, &cookie_path)?;
        download_gdtf_share_file(&request, &cookie_path, &partial_path)?;
        gdtf::load_profile(&partial_path)
            .map_err(|error| format!("Downloaded GDTF Share cache file is invalid: {error}"))?;
        if path.exists() {
            fs::remove_file(&path).map_err(|error| {
                format!(
                    "Unable to replace invalid fixture cache '{}': {error}",
                    path.display()
                )
            })?;
        }
        fs::rename(&partial_path, &path).map_err(|error| {
            format!(
                "Unable to finalize fixture cache '{}': {error}",
                path.display()
            )
        })?;
        write_gdtf_fixture_cache_metadata(&path, &metadata)?;
        inspect_gdtf_cache_file(&path, Some(metadata.clone()))
    })();
    let _ = fs::remove_file(&cookie_path);
    let _ = fs::remove_file(&partial_path);
    result
}

