#[tauri::command]
fn repair_fixture_profile(
    window: WebviewWindow,
    state: State<'_, AppState>,
    args: FlatInvokeArgs<Value>,
) -> Result<ProjectTransactionCommandResult, String> {
    let fixture_id = args.get_required("fixtureId")?;
    let profile_path = args.get_required("profilePath")?;
    let mode_name = args.get_optional("modeName")?;
    let profile = args.get_required("profile")?;
    let project_transaction_id = args.get_required("projectTransactionId")?;
    let expected_epoch = args.get_required("expectedEpoch")?;
    let owner_id = args.get_required("ownerId")?;
    repair_fixture_profile_for_window_label_with_resolve_observer(
        &state,
        FixtureProfileRepairRequest {
            fixture_id,
            profile_path,
            mode_name,
            profile,
            project_transaction_id,
            expected_epoch,
            owner_id,
            window_label: window.label().to_string(),
        },
        || {},
    )
}

struct FixtureProfileRepairRequest {
    fixture_id: FixtureId,
    profile_path: String,
    mode_name: Option<String>,
    profile: FixtureProfileSummary,
    project_transaction_id: u64,
    expected_epoch: u64,
    owner_id: String,
    window_label: String,
}

fn repair_fixture_profile_for_window_label_with_resolve_observer(
    state: &AppState,
    request: FixtureProfileRepairRequest,
    before_resolve: impl FnOnce(),
) -> Result<ProjectTransactionCommandResult, String> {
    repair_fixture_profile_for_window_label_with_resolve_and_publish(
        state,
        request,
        before_resolve,
        |engine, fixture_id, profile, mode_name| {
            engine.repair_fixture_profile_published_classified(fixture_id, profile, mode_name)
        },
    )
}

fn repair_fixture_profile_for_window_label_with_resolve_and_publish(
    state: &AppState,
    request: FixtureProfileRepairRequest,
    before_resolve: impl FnOnce(),
    publish: impl FnOnce(
        &EngineHandle,
        FixtureId,
        FixtureProfileSummary,
        Option<String>,
    ) -> Result<(), FixturePatchPublicationFailure>,
) -> Result<ProjectTransactionCommandResult, String> {
    let FixtureProfileRepairRequest {
        fixture_id,
        profile_path,
        mode_name,
        profile,
        project_transaction_id,
        expected_epoch,
        owner_id,
        window_label,
    } = request;
    let window_label = window_label.as_str();
    let request_digest = project_transaction_command_request_digest(
        "repair_fixture_profile",
        &(&fixture_id, &profile_path, &mode_name, &profile),
    )?;
    let (_external_admission, coordinator, transaction_admission) =
        lock_renderer_ticketed_project_mutation(
            state,
            window_label,
            "repair_fixture_profile",
            project_transaction_id,
            expected_epoch,
            &owner_id,
        )?;
    let pending = project_transaction_for_owner_epoch(
        &coordinator,
        project_transaction_id,
        expected_epoch,
        &owner_id,
    )?;
    if let Some(result) = project_transaction_existing_command_result(
        &pending,
        "repair_fixture_profile",
        &request_digest,
    )? {
        return Ok(result);
    }
    let prepare_fence = project_checkpoint_for_coordinator(state, &coordinator)?;
    let snapshot = state.engine.persistence_snapshot()?;
    let custom_profiles = coordinator.ancillary.custom_profiles.clone();
    drop(coordinator);
    drop(_external_admission);

    // GDTF/profile resolution can perform filesystem I/O. The transaction
    // lane remains in flight, but neither global mutation lock is held.
    before_resolve();
    let fixture = snapshot
        .fixtures
        .iter()
        .find(|fixture| fixture.id == fixture_id)
        .ok_or_else(|| format!("Fixture {fixture_id} was not found"))?;
    let profile =
        resolve_patch_profile_against_authority(&profile_path, Some(&profile), &custom_profiles)?;
    if !profile
        .manufacturer
        .trim()
        .eq_ignore_ascii_case(fixture.manufacturer.trim())
        || !profile
            .name
            .trim()
            .eq_ignore_ascii_case(fixture.profile_name.trim())
    {
        return Err(format!(
            "Replacement profile identity '{} {}' does not match fixture '{} {}'",
            profile.manufacturer, profile.name, fixture.manufacturer, fixture.profile_name
        ));
    }
    let requested_mode = mode_name
        .as_deref()
        .map(str::trim)
        .filter(|mode| !mode.is_empty())
        .unwrap_or(fixture.mode_name.as_str());
    let replacement_mode = gdtf::find_dmx_mode(&profile, Some(requested_mode))
        .ok_or_else(|| format!("Replacement DMX mode '{requested_mode}' was not found"))?;
    if !fixture_profile_repair_layout_matches(&fixture.controls, &replacement_mode.controls) {
        return Err(format!(
            "Replacement profile mode '{requested_mode}' does not exactly match the patched attribute, geometry, offset and resolution layout"
        ));
    }
    let replacement_mode_name = replacement_mode.name.clone();
    let (_external_admission, mut coordinator, _final_transaction_admission) =
        lock_renderer_ticketed_project_mutation(
            state,
            window_label,
            "repair_fixture_profile",
            project_transaction_id,
            expected_epoch,
            &owner_id,
        )?;
    let final_pending = project_transaction_for_owner_epoch(
        &coordinator,
        project_transaction_id,
        expected_epoch,
        &owner_id,
    )?;
    if let Some(result) = project_transaction_existing_command_result(
        &final_pending,
        "repair_fixture_profile",
        &request_digest,
    )? {
        return Ok(result);
    }
    if project_checkpoint_for_coordinator(state, &coordinator)? != prepare_fence {
        return Err(
            "Project changed while resolving the replacement fixture profile; retry Repair"
                .to_string(),
        );
    }
    let mut candidate_ancillary = coordinator.ancillary.clone();
    let source_path = profile.source_path.trim();
    if !source_path.is_empty() {
        candidate_ancillary
            .custom_profiles
            .insert(source_path.to_string(), profile.clone());
    }
    let prepared_ancillary = prepare_direct_project_ancillary_mutation(
        state,
        &coordinator,
        snapshot,
        candidate_ancillary,
    )?;
    let prepared_result_publication = prepare_project_transaction_command_result_publication(
        state,
        &coordinator,
        &final_pending,
    )?;

    match publish(
        &state.engine,
        fixture_id,
        profile,
        Some(replacement_mode_name),
    ) {
        Ok(()) => {}
        Err(FixturePatchPublicationFailure::Definitive(error)) => return Err(error),
        Err(FixturePatchPublicationFailure::Indeterminate(error)) => {
            return Err(mark_project_transaction_publication_indeterminate(
                state,
                &mut coordinator,
                prepared_result_publication,
                error,
            ));
        }
    }
    commit_direct_project_ancillary_mutation_after_preflight(
        state,
        &mut coordinator,
        prepared_ancillary,
    );
    let result = ProjectTransactionCommandResult::RepairFixtureProfile {
        request_digest,
        fixture_id,
    };
    prepared_result_publication.commit(&mut coordinator, result.clone());
    drop(transaction_admission);
    Ok(result)
}

#[tauri::command]
fn create_custom_fixture_profile(
    request: CustomFixtureProfileRequest,
) -> Result<FixtureProfileSummary, String> {
    // Retained for older clients, but intentionally mirrors the pure preview
    // command.  Profile creation must not mutate project state or the cache;
    // Patch is the sole authoritative commit boundary.
    validate_custom_fixture_profile_request(&request)?;
    Ok(custom_fixture_profile_from_request(request))
}

#[tauri::command]
fn preview_custom_fixture_profile(
    request: CustomFixtureProfileRequest,
) -> Result<FixtureProfileSummary, String> {
    validate_custom_fixture_profile_request(&request)?;
    Ok(custom_fixture_profile_from_request(request))
}

#[tauri::command]
fn save_custom_fixture_profile(
    window: WebviewWindow,
    request: CustomFixtureProfileRequest,
) -> Result<Option<String>, String> {
    validate_custom_fixture_profile_request(&request)?;
    let profile_file = CustomFixtureProfileFile {
        version: PROJECT_FILE_VERSION,
        request,
    };
    let Some(path) = parented_file_dialog(&window)
        .add_filter("Syndocal Fixture Profile", &["fixture"])
        .set_file_name(format!(
            "{}.fixture",
            safe_file_stem(&profile_file.request.name)
        ))
        .save_file()
    else {
        return Ok(None);
    };
    let path = normalize_custom_fixture_profile_save_path(path)?;
    let json = serde_json::to_string_pretty(&profile_file).map_err(|error| error.to_string())?;
    fs::write(&path, json).map_err(|error| error.to_string())?;
    Ok(Some(path.to_string_lossy().to_string()))
}

#[tauri::command]
fn load_custom_fixture_profile(
    window: WebviewWindow,
) -> Result<Option<FixtureProfileSummary>, String> {
    let Some(path) = parented_file_dialog(&window)
        .add_filter("Syndocal Fixture Profile", &["fixture"])
        .pick_file()
    else {
        return Ok(None);
    };
    let json = fs::read_to_string(&path).map_err(|error| error.to_string())?;
    let profile_file: CustomFixtureProfileFile =
        serde_json::from_str(&json).map_err(|error| error.to_string())?;
    validate_custom_fixture_profile_file(&profile_file)?;
    let profile = custom_fixture_profile_from_request(profile_file.request);
    Ok(Some(profile))
}

#[tauri::command]
fn use_fixture_profile(
    state: State<'_, AppState>,
    fixture_id: FixtureId,
) -> Result<FixtureProfileSummary, String> {
    let snapshot = state.engine.snapshot();
    let fixture = snapshot
        .fixtures
        .iter()
        .find(|fixture| fixture.id == fixture_id)
        .ok_or_else(|| format!("Fixture {fixture_id} was not found"))?;
    let profile = fixture_profile_from_patched_fixture(fixture);
    Ok(profile)
}

