#[tauri::command]
fn set_fixture_transform(
    window: WebviewWindow,
    state: State<'_, AppState>,
    request: SetFixtureTransformRequest,
) -> Result<(), String> {
    let SetFixtureTransformRequest {
        fixture_id,
        position,
        rotation,
        project_transaction_id,
        expected_epoch,
        owner_id,
    } = request;
    validate_fixture_transform(&position, &rotation)?;
    stage_project_transaction_unit_result(
        apply_stage_project_mutation_in_project_transaction(
            &state,
            StageProjectTransactionRequest {
                project_transaction_id,
                expected_epoch,
                owner_id,
                window_label: window.label().to_string(),
                command_name: "set_fixture_transform",
            },
            |_| Ok((fixture_id, position, rotation)),
            |_, (fixture_id, position, rotation)| {
                Ok(PreparedStageProjectMutation {
                    mutation: StageProjectMutation::SetFixtureTransform {
                        fixture_id,
                        position,
                        rotation,
                    },
                    stage_object_id: None,
                    label: None,
                })
            },
        )?,
        "set_fixture_transform",
    )
}

#[tauri::command]
fn set_fixture_transforms(
    window: WebviewWindow,
    state: State<'_, AppState>,
    request: SetFixtureTransformsRequest,
) -> Result<(), String> {
    let SetFixtureTransformsRequest {
        transforms,
        project_transaction_id,
        expected_epoch,
        owner_id,
    } = request;
    validate_fixture_transform_batch(&transforms)?;
    stage_project_transaction_unit_result(
        apply_stage_project_mutation_in_project_transaction(
            &state,
            StageProjectTransactionRequest {
                project_transaction_id,
                expected_epoch,
                owner_id,
                window_label: window.label().to_string(),
                command_name: "set_fixture_transforms",
            },
            move |_| Ok(transforms),
            |_, transforms| {
                Ok(PreparedStageProjectMutation {
                    mutation: StageProjectMutation::SetFixtureTransforms {
                        transforms: transforms
                            .into_iter()
                            .map(|transform| StageFixtureTransform {
                                fixture_id: transform.fixture_id,
                                position: transform.position,
                                rotation: transform.rotation,
                            })
                            .collect(),
                    },
                    stage_object_id: None,
                    label: None,
                })
            },
        )?,
        "set_fixture_transforms",
    )
}

