#[tauri::command]
fn connect_midi_clock(
    state: State<'_, AppState>,
    input_index: usize,
    expected_epoch: Option<u64>,
) -> Result<(), String> {
    let _external_admission = lock_project_external_command_admission(&state)?;
    let coordinator = lock_project_coordinator(&state)?;
    ensure_optional_project_epoch_matches(&coordinator, expected_epoch)?;
    ensure_no_pending_project_transaction(&coordinator)?;
    let coordinator_epoch = coordinator.epoch;
    let callback_epoch = Arc::clone(&state.project_callback_epoch);
    let captured_callback_epoch = callback_epoch.load(Ordering::Acquire);
    let previous = state
        .midi_clock
        .lock()
        .map_err(|_| "MIDI state lock was poisoned".to_string())?
        .take();
    drop(previous);
    let engine = state.engine.clone();
    let callback_epoch_for_worker = Arc::clone(&callback_epoch);
    let project_transaction_active_for_worker = Arc::clone(&state.project_transaction_active);
    let project_external_command_admission_for_worker =
        Arc::clone(&state.project_external_command_admission);
    let callback_installed = Arc::new(AtomicBool::new(false));
    let callback_installed_for_worker = Arc::clone(&callback_installed);
    let connection = io::midi::connect_midi_clock(input_index, move |event| match event {
        MidiClockEvent::ClockPulse => {
            send_engine_command_if_callback_epoch(
                &engine,
                &callback_epoch_for_worker,
                &project_transaction_active_for_worker,
                &project_external_command_admission_for_worker,
                &callback_installed_for_worker,
                captured_callback_epoch,
                EngineCommand::MidiClockPulse,
            );
        }
        MidiClockEvent::Start => {
            send_engine_command_if_callback_epoch(
                &engine,
                &callback_epoch_for_worker,
                &project_transaction_active_for_worker,
                &project_external_command_admission_for_worker,
                &callback_installed_for_worker,
                captured_callback_epoch,
                EngineCommand::SeekTimeline(0),
            );
            send_engine_command_if_callback_epoch(
                &engine,
                &callback_epoch_for_worker,
                &project_transaction_active_for_worker,
                &project_external_command_admission_for_worker,
                &callback_installed_for_worker,
                captured_callback_epoch,
                EngineCommand::SetTimelinePlaying(true),
            );
        }
        MidiClockEvent::Continue => {
            send_engine_command_if_callback_epoch(
                &engine,
                &callback_epoch_for_worker,
                &project_transaction_active_for_worker,
                &project_external_command_admission_for_worker,
                &callback_installed_for_worker,
                captured_callback_epoch,
                EngineCommand::SetTimelinePlaying(true),
            );
        }
        MidiClockEvent::Stop => {
            send_engine_command_if_callback_epoch(
                &engine,
                &callback_epoch_for_worker,
                &project_transaction_active_for_worker,
                &project_external_command_admission_for_worker,
                &callback_installed_for_worker,
                captured_callback_epoch,
                EngineCommand::SetTimelinePlaying(false),
            );
        }
        MidiClockEvent::SongPositionPointer(sixteenth_notes) => {
            send_engine_command_if_callback_epoch(
                &engine,
                &callback_epoch_for_worker,
                &project_transaction_active_for_worker,
                &project_external_command_admission_for_worker,
                &callback_installed_for_worker,
                captured_callback_epoch,
                EngineCommand::MidiSongPositionPointer(sixteenth_notes),
            );
        }
        MidiClockEvent::Timecode(timecode) => {
            send_engine_command_if_callback_epoch(
                &engine,
                &callback_epoch_for_worker,
                &project_transaction_active_for_worker,
                &project_external_command_admission_for_worker,
                &callback_installed_for_worker,
                captured_callback_epoch,
                EngineCommand::SyncTimelineTimecode {
                    position_ms: timecode.position_ms(),
                    source: protocol::ClockSource::MidiTimecode,
                },
            );
        }
    })
    .map_err(|error| error.to_string())?;
    if !project_input_installation_is_current(
        coordinator.epoch,
        coordinator_epoch,
        &callback_epoch,
        captured_callback_epoch,
    ) {
        drop(connection);
        return Err("Project changed while MIDI clock input was opening".to_string());
    }
    let mut guard = state
        .midi_clock
        .lock()
        .map_err(|_| "MIDI state lock was poisoned".to_string())?;
    *guard = Some(connection);
    callback_installed.store(true, Ordering::Release);
    Ok(())
}

#[tauri::command]
fn disconnect_midi_clock(
    state: State<'_, AppState>,
    expected_epoch: Option<u64>,
) -> Result<(), String> {
    let _external_admission = lock_project_external_command_admission(&state)?;
    let _coordinator = lock_project_coordinator(&state)?;
    ensure_optional_project_epoch_matches(&_coordinator, expected_epoch)?;
    let connection = state
        .midi_clock
        .lock()
        .map_err(|_| "MIDI state lock was poisoned".to_string())?
        .take();
    drop(connection);
    Ok(())
}

#[tauri::command]
fn connect_midi_control(
    state: State<'_, AppState>,
    input_index: usize,
    mappings: Vec<MidiControlMapping>,
    expected_epoch: Option<u64>,
) -> Result<(), String> {
    let received_mappings = validate_midi_control_mappings(mappings)?;
    let _external_admission = lock_project_external_command_admission(&state)?;
    let coordinator = lock_project_coordinator(&state)?;
    ensure_optional_project_epoch_matches(&coordinator, expected_epoch)?;
    ensure_no_pending_project_transaction(&coordinator)?;
    if received_mappings != coordinator.mappings.midi_mappings {
        return Err(
            "MIDI control mappings changed locally; refresh before connecting input".to_string(),
        );
    }
    let mappings = coordinator.mappings.midi_mappings.clone();
    if mappings.is_empty() {
        return Err("At least one MIDI control mapping is required".to_string());
    }
    let coordinator_epoch = coordinator.epoch;
    let callback_epoch = Arc::clone(&state.project_mapping_callback_epoch);
    let captured_callback_epoch = callback_epoch.load(Ordering::Acquire);
    let previous = state
        .midi_control
        .lock()
        .map_err(|_| "MIDI control state lock was poisoned".to_string())?
        .take();
    drop(previous);
    let engine = state.engine.clone();
    let operator_selection = Arc::clone(&state.operator_selection);
    let callback_epoch_for_worker = Arc::clone(&callback_epoch);
    let project_transaction_active_for_worker = Arc::clone(&state.project_transaction_active);
    let project_external_command_admission_for_worker =
        Arc::clone(&state.project_external_command_admission);
    let callback_installed = Arc::new(AtomicBool::new(false));
    let callback_installed_for_worker = Arc::clone(&callback_installed);
    let connection = io::midi::connect_midi_control(input_index, mappings, move |event| {
        if midi_control_event_requires_fail_closed(&event) {
            return;
        }
        let command = match event {
            MidiControlEvent::SetAttribute {
                fixture_id,
                attribute,
                value,
            } => EngineCommand::SetAttribute {
                fixture_id,
                attribute,
                value,
            },
            MidiControlEvent::SetSelectedFeatureFader {
                target_index,
                value,
            } => match operator_feature_fader_command(
                &engine,
                &operator_selection,
                target_index,
                value,
            ) {
                Ok((command, _)) => command,
                Err(error) => {
                    eprintln!("Ignoring MIDI selected feature fader: {error}");
                    return;
                }
            },
            MidiControlEvent::SetFixtureHighlight {
                fixture_id,
                enabled,
            } => EngineCommand::SetFixtureHighlight {
                fixture_id,
                enabled,
            },
            MidiControlEvent::SetFixtureSolo {
                fixture_id,
                enabled,
            } => EngineCommand::SetFixtureSolo {
                fixture_id,
                enabled,
            },
            MidiControlEvent::SetFixturePark {
                fixture_id,
                enabled,
            } => EngineCommand::SetFixturePark {
                fixture_id,
                enabled,
            },
            MidiControlEvent::SetGroupHighlight { group_id, enabled } => {
                EngineCommand::SetGroupHighlight { group_id, enabled }
            }
            MidiControlEvent::SetGroupSolo { group_id, enabled } => {
                EngineCommand::SetGroupSolo { group_id, enabled }
            }
            MidiControlEvent::SetGroupPark { group_id, enabled } => {
                EngineCommand::SetGroupPark { group_id, enabled }
            }
            MidiControlEvent::TriggerCue(cue_id) => EngineCommand::TriggerCue(cue_id),
            MidiControlEvent::TriggerCueWithDirection { cue_id, direction } => {
                EngineCommand::TriggerCueWithDirection { cue_id, direction }
            }
            MidiControlEvent::ReleaseCue(cue_id) => EngineCommand::ReleaseCue(cue_id),
            MidiControlEvent::TriggerCueListNext(anchor_cue_id) => {
                let Some(cue_list_id) = engine
                    .snapshot()
                    .cues
                    .iter()
                    .find(|cue| cue.id == anchor_cue_id)
                    .map(|cue| cue.cue_list_id)
                else {
                    eprintln!(
                        "Ignoring MIDI Bank Next: anchor Scene {anchor_cue_id} was not found"
                    );
                    return;
                };
                EngineCommand::TriggerCueListNext(cue_list_id)
            }
            MidiControlEvent::TriggerNextCue => EngineCommand::TriggerNextCue,
            MidiControlEvent::TriggerPreviousCue => EngineCommand::TriggerPreviousCue,
            MidiControlEvent::SetEffectEnabled { effect_id, enabled } => {
                EngineCommand::SetEffectEnabled { effect_id, enabled }
            }
            MidiControlEvent::SetNodeGraphEnabled { graph_id, enabled } => {
                EngineCommand::SetNodeGraphEnabled { graph_id, enabled }
            }
            MidiControlEvent::SetVideoParam {
                layer_id,
                param,
                value,
            } => EngineCommand::SetVideoLayerParam {
                layer_id,
                param,
                value,
            },
            MidiControlEvent::AddVideoCuePoint {
                layer_id,
                position_ms,
            } => EngineCommand::AddVideoCuePoint {
                layer_id,
                position_ms,
            },
            MidiControlEvent::RemoveVideoCuePoint {
                layer_id,
                position_ms,
            } => EngineCommand::RemoveVideoCuePoint {
                layer_id,
                position_ms,
            },
            MidiControlEvent::JumpVideoCuePoint {
                layer_id,
                cue_point_index,
            } => EngineCommand::JumpVideoCuePoint {
                layer_id,
                cue_point_index,
            },
            MidiControlEvent::JumpVideoCuePointRelative {
                layer_id,
                direction,
            } => EngineCommand::JumpVideoCuePointRelative {
                layer_id,
                direction,
            },
            MidiControlEvent::SetVideoLayerEnabled { layer_id, enabled } => {
                EngineCommand::SetVideoLayerEnabled { layer_id, enabled }
            }
            MidiControlEvent::SetVideoLayerSolo { layer_id, solo } => {
                EngineCommand::SetVideoLayerSolo { layer_id, solo }
            }
            MidiControlEvent::SetVideoPlaying { layer_id, playing } => {
                EngineCommand::SetVideoLayerPlaying { layer_id, playing }
            }
            MidiControlEvent::SetVideoLoop {
                layer_id,
                enabled,
                loop_start_ms,
                loop_end_ms,
            } => EngineCommand::SetVideoLayerLoop {
                layer_id,
                enabled,
                loop_start_ms,
                loop_end_ms,
            },
            MidiControlEvent::FadeVideoLayerOpacity {
                layer_id,
                opacity,
                duration_ms,
            } => EngineCommand::FadeVideoLayerOpacity {
                layer_id,
                opacity,
                duration_ms,
            },
            MidiControlEvent::SetVideoOutputEnabled { output_id, enabled } => {
                EngineCommand::SetVideoOutputEnabled { output_id, enabled }
            }
            MidiControlEvent::SetVideoOutputOpacity { output_id, opacity } => {
                EngineCommand::SetVideoOutputOpacity { output_id, opacity }
            }
            MidiControlEvent::FadeVideoOutputOpacity {
                output_id,
                opacity,
                duration_ms,
            } => EngineCommand::FadeVideoOutputOpacity {
                output_id,
                opacity,
                duration_ms,
            },
            MidiControlEvent::SetVideoOutputMappingField {
                output_id,
                field,
                value,
            } => EngineCommand::SetVideoOutputMappingField {
                output_id,
                field,
                value,
            },
            MidiControlEvent::ApplyVideoOutputMappingPreset { output_id, label } => {
                EngineCommand::ApplyVideoOutputMappingPreset { output_id, label }
            }
            MidiControlEvent::SetVideoOutputBlackout {
                output_id,
                blackout,
            } => EngineCommand::SetVideoOutputBlackout {
                output_id,
                blackout,
            },
            MidiControlEvent::SetTimelinePlaying(playing) => {
                EngineCommand::SetTimelinePlaying(playing)
            }
            MidiControlEvent::SeekTimeline { position_ms } => {
                EngineCommand::SeekTimeline(position_ms)
            }
            MidiControlEvent::SeekTimelineBeat { direction } => {
                EngineCommand::SeekTimelineBeat { direction }
            }
            MidiControlEvent::ToggleTimelineLoop => {
                EngineCommand::ApplyTrustedTimelineLoopRuntime {
                    action: TrustedTimelineLoopRuntimeAction::Toggle,
                }
            }
            MidiControlEvent::ScaleTimelineLoop(scale) => {
                EngineCommand::ApplyTrustedTimelineLoopRuntime {
                    action: TrustedTimelineLoopRuntimeAction::Scale(scale),
                }
            }
            MidiControlEvent::SetBpm(bpm) => EngineCommand::SetBpm(bpm),
            MidiControlEvent::TapBpm => EngineCommand::TapBpm,
            MidiControlEvent::LightingMaster(master) => EngineCommand::SetLightingMaster(master),
            MidiControlEvent::VideoMaster(master) => EngineCommand::SetVideoMasterOpacity(master),
            MidiControlEvent::SetGroupSubmaster { group_id, level } => {
                EngineCommand::SetGroupSubmaster { group_id, level }
            }
            MidiControlEvent::SetCueFadePaused(paused) => EngineCommand::SetCueFadePaused(paused),
            MidiControlEvent::Blackout(enabled) => EngineCommand::Blackout(enabled),
            MidiControlEvent::AllBlackout(enabled) => EngineCommand::SetAllBlackout(enabled),
            MidiControlEvent::VideoBlackout(enabled) => EngineCommand::SetVideoBlackout(enabled),
            MidiControlEvent::ClearFixtureFlags { kind } => {
                match parse_fixture_flag_clear_kind(&kind) {
                    Ok(kind) => EngineCommand::ClearFixtureFlags(kind),
                    Err(error) => {
                        eprintln!("Ignoring MIDI clear fixture flags command: {error}");
                        return;
                    }
                }
            }
        };
        if external_unversioned_semantic_command_requires_fail_closed(
            ExternalControlIngress::MidiControl,
            &command,
        ) {
            return;
        }
        send_engine_command_if_callback_epoch(
            &engine,
            &callback_epoch_for_worker,
            &project_transaction_active_for_worker,
            &project_external_command_admission_for_worker,
            &callback_installed_for_worker,
            captured_callback_epoch,
            command,
        );
    })
    .map_err(|error| error.to_string())?;
    if !project_input_installation_is_current(
        coordinator.epoch,
        coordinator_epoch,
        &callback_epoch,
        captured_callback_epoch,
    ) {
        drop(connection);
        return Err("Project changed while MIDI control input was opening".to_string());
    }
    let mut guard = state
        .midi_control
        .lock()
        .map_err(|_| "MIDI control state lock was poisoned".to_string())?;
    *guard = Some(connection);
    callback_installed.store(true, Ordering::Release);
    Ok(())
}

#[tauri::command]
fn disconnect_midi_control(
    state: State<'_, AppState>,
    expected_epoch: Option<u64>,
) -> Result<(), String> {
    let _external_admission = lock_project_external_command_admission(&state)?;
    let _coordinator = lock_project_coordinator(&state)?;
    ensure_optional_project_epoch_matches(&_coordinator, expected_epoch)?;
    let connection = state
        .midi_control
        .lock()
        .map_err(|_| "MIDI control state lock was poisoned".to_string())?
        .take();
    drop(connection);
    Ok(())
}

#[tauri::command]
fn connect_midi_feedback(
    state: State<'_, AppState>,
    output_index: usize,
    expected_epoch: Option<u64>,
) -> Result<(), String> {
    let _external_admission = lock_project_external_command_admission(&state)?;
    let coordinator = lock_project_coordinator(&state)?;
    ensure_optional_project_epoch_matches(&coordinator, expected_epoch)?;
    ensure_no_pending_project_transaction(&coordinator)?;
    let coordinator_epoch = coordinator.epoch;
    let callback_epoch = Arc::clone(&state.project_mapping_callback_epoch);
    let captured_callback_epoch = callback_epoch.load(Ordering::Acquire);
    let runtime = state
        .midi_feedback_runtime
        .lock()
        .map_err(|_| "MIDI feedback runtime lock was poisoned".to_string())?
        .take();
    drop(runtime);
    let previous = state
        .midi_feedback
        .lock()
        .map_err(|_| "MIDI feedback state lock was poisoned".to_string())?
        .take();
    drop(previous);
    let connection =
        io::midi::connect_midi_feedback_output(output_index).map_err(|error| error.to_string())?;
    if !project_input_installation_is_current(
        coordinator.epoch,
        coordinator_epoch,
        &callback_epoch,
        captured_callback_epoch,
    ) {
        drop(connection);
        return Err("Project changed while MIDI feedback output was opening".to_string());
    }
    let mut guard = state
        .midi_feedback
        .lock()
        .map_err(|_| "MIDI feedback state lock was poisoned".to_string())?;
    *guard = Some(connection);
    *state
        .midi_feedback_last_error
        .lock()
        .map_err(|_| "MIDI feedback error state lock was poisoned".to_string())? = None;
    Ok(())
}

#[tauri::command]
fn disconnect_midi_feedback(
    state: State<'_, AppState>,
    expected_epoch: Option<u64>,
) -> Result<(), String> {
    let _external_admission = lock_project_external_command_admission(&state)?;
    let _coordinator = lock_project_coordinator(&state)?;
    ensure_optional_project_epoch_matches(&_coordinator, expected_epoch)?;
    let runtime = state
        .midi_feedback_runtime
        .lock()
        .map_err(|_| "MIDI feedback runtime lock was poisoned".to_string())?
        .take();
    drop(runtime);
    let output = state
        .midi_feedback
        .lock()
        .map_err(|_| "MIDI feedback state lock was poisoned".to_string())?
        .take();
    drop(output);
    *state
        .midi_feedback_last_error
        .lock()
        .map_err(|_| "MIDI feedback error state lock was poisoned".to_string())? = None;
    Ok(())
}

#[tauri::command]
fn set_midi_feedback_auto(
    state: State<'_, AppState>,
    enabled: bool,
    mappings: Vec<MidiControlMapping>,
    expected_epoch: Option<u64>,
) -> Result<MidiFeedbackRuntimeStatus, String> {
    let received_mappings = validate_midi_control_mappings(mappings)?;
    let _external_admission = lock_project_external_command_admission(&state)?;
    let coordinator = lock_project_coordinator(&state)?;
    ensure_optional_project_epoch_matches(&coordinator, expected_epoch)?;
    if received_mappings != coordinator.mappings.midi_mappings {
        return Err(
            "MIDI control mappings changed locally; refresh before changing feedback".to_string(),
        );
    }
    let mappings = coordinator.mappings.midi_mappings.clone();
    let coordinator_epoch = coordinator.epoch;
    let callback_epoch = Arc::clone(&state.project_mapping_callback_epoch);
    let captured_callback_epoch = callback_epoch.load(Ordering::Acquire);
    let previous = state
        .midi_feedback_runtime
        .lock()
        .map_err(|_| "MIDI feedback runtime lock was poisoned".to_string())?
        .take();
    drop(previous);
    *state
        .midi_feedback_last_error
        .lock()
        .map_err(|_| "MIDI feedback error state lock was poisoned".to_string())? = None;

    if enabled {
        if mappings.is_empty() {
            return Err("At least one MIDI mapping is required for auto feedback".to_string());
        }
        if state
            .midi_feedback
            .lock()
            .map_err(|_| "MIDI feedback state lock was poisoned".to_string())?
            .is_none()
        {
            return Err("MIDI feedback output is not connected".to_string());
        }
        let callback_installed = Arc::new(AtomicBool::new(false));
        let runtime = MidiFeedbackRuntime::start(
            state.engine.clone(),
            Arc::clone(&state.midi_feedback),
            Arc::clone(&state.operator_selection),
            mappings,
            Arc::clone(&state.midi_feedback_last_error),
            (
                Arc::clone(&callback_epoch),
                captured_callback_epoch,
                Arc::clone(&callback_installed),
            ),
        )?;
        if !project_input_installation_is_current(
            coordinator.epoch,
            coordinator_epoch,
            &callback_epoch,
            captured_callback_epoch,
        ) {
            drop(runtime);
            return Err("Project changed while MIDI feedback was starting".to_string());
        }
        *state
            .midi_feedback_runtime
            .lock()
            .map_err(|_| "MIDI feedback runtime lock was poisoned".to_string())? = Some(runtime);
        callback_installed.store(true, Ordering::Release);
    }

    let runtime = state
        .midi_feedback_runtime
        .lock()
        .map_err(|_| "MIDI feedback runtime lock was poisoned".to_string())?;
    Ok(MidiFeedbackRuntimeStatus {
        enabled: runtime
            .as_ref()
            .is_some_and(MidiFeedbackRuntime::is_running),
        last_error: None,
    })
}

#[tauri::command]
fn midi_feedback_status(state: State<'_, AppState>) -> Result<MidiFeedbackRuntimeStatus, String> {
    let enabled = state
        .midi_feedback_runtime
        .lock()
        .map_err(|_| "MIDI feedback runtime lock was poisoned".to_string())?
        .as_ref()
        .is_some_and(MidiFeedbackRuntime::is_running);
    let last_error = state
        .midi_feedback_last_error
        .lock()
        .map_err(|_| "MIDI feedback error state lock was poisoned".to_string())?
        .clone();
    Ok(MidiFeedbackRuntimeStatus {
        enabled,
        last_error,
    })
}

#[tauri::command]
fn send_midi_feedback(
    state: State<'_, AppState>,
    mappings: Vec<MidiControlMapping>,
    force: Option<bool>,
) -> Result<usize, String> {
    let received_mappings = validate_midi_control_mappings(mappings)?;
    let coordinator = lock_project_coordinator(&state)?;
    if received_mappings != coordinator.mappings.midi_mappings {
        return Err(
            "MIDI control mappings changed locally; refresh before sending feedback".to_string(),
        );
    }
    let mappings = coordinator.mappings.midi_mappings.clone();
    let snapshot = state.engine.snapshot();
    let operator_selection = state
        .operator_selection
        .lock()
        .map_err(|_| "Operator selection state lock was poisoned".to_string())?
        .clone();
    let messages = io::midi::build_feedback_messages_with_operator_selection(
        &snapshot,
        &mappings,
        Some(&operator_selection),
    );
    let mut guard = state
        .midi_feedback
        .lock()
        .map_err(|_| "MIDI feedback state lock was poisoned".to_string())?;
    let output = guard
        .as_mut()
        .ok_or_else(|| "MIDI feedback output is not connected".to_string())?;
    output
        .send_feedback_messages_with_force(&messages, force.unwrap_or(true))
        .map_err(|error| error.to_string())
}

#[tauri::command]
fn learn_midi_control(
    state: State<'_, AppState>,
    input_index: usize,
    expected_epoch: Option<u64>,
) -> Result<Option<LearnedMidiControl>, String> {
    // Do not hold the operation locks while the user moves a controller, but
    // bracket the wait with exact-epoch admission checks. A late A result can
    // therefore never be applied to B by an eager frontend reconnect.
    {
        let _admission = lock_project_external_command_admission(&state)?;
        let coordinator = lock_project_coordinator(&state)?;
        ensure_optional_project_epoch_matches(&coordinator, expected_epoch)?;
    }
    let learned = io::midi::learn_midi_control(input_index, Duration::from_secs(10))
        .map_err(|error| error.to_string())?;
    {
        let _admission = lock_project_external_command_admission(&state)?;
        let coordinator = lock_project_coordinator(&state)?;
        ensure_optional_project_epoch_matches(&coordinator, expected_epoch)?;
    }
    Ok(learned)
}

#[tauri::command]
fn save_midi_mappings(
    window: WebviewWindow,
    mappings: Vec<MidiControlMapping>,
) -> Result<Option<String>, String> {
    let mappings = validate_midi_control_mappings(mappings)?;
    let Some(path) = parented_file_dialog(&window)
        .add_filter("Syndocal MIDI Mapping", &["midimap"])
        .set_file_name("syndocal.midimap")
        .save_file()
    else {
        return Ok(None);
    };
    let file = MidiMappingFile {
        version: 1,
        mappings,
    };
    let json = serde_json::to_string_pretty(&file).map_err(|error| error.to_string())?;
    fs::write(&path, json).map_err(|error| error.to_string())?;
    Ok(Some(path.to_string_lossy().to_string()))
}

#[tauri::command]
fn load_midi_mappings(window: WebviewWindow) -> Result<Option<Vec<MidiControlMapping>>, String> {
    let Some(path) = parented_file_dialog(&window)
        .add_filter("Syndocal MIDI Mapping", &["midimap"])
        .pick_file()
    else {
        return Ok(None);
    };
    let json = fs::read_to_string(&path).map_err(|error| error.to_string())?;
    let file: MidiMappingFile = serde_json::from_str(&json).map_err(|error| error.to_string())?;
    if file.version != 1 {
        return Err(format!("Unsupported MIDI mapping version {}", file.version));
    }
    Ok(Some(validate_midi_control_mappings(file.mappings)?))
}

