fn next_rdm_transaction_number() -> u8 {
    RDM_TRANSACTION_NUMBER
        .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |current| {
            Some(if current == u8::MAX { 1 } else { current + 1 })
        })
        .unwrap_or(1)
}

fn parse_rdm_uid(value: &str) -> Result<io::rdm::RdmUid, String> {
    let bytes = parse_hex_bytes(value)?;
    if bytes.len() != 6 {
        return Err("RDM UID must contain exactly 12 hexadecimal digits".to_string());
    }
    let mut uid = [0_u8; 6];
    uid.copy_from_slice(&bytes);
    Ok(io::rdm::RdmUid(uid))
}

fn format_rdm_uid(uid: io::rdm::RdmUid) -> String {
    format!(
        "{:02X}{:02X}:{:02X}{:02X}{:02X}{:02X}",
        uid.0[0], uid.0[1], uid.0[2], uid.0[3], uid.0[4], uid.0[5]
    )
}

fn parse_hex_bytes(value: &str) -> Result<Vec<u8>, String> {
    let compact = value
        .chars()
        .filter(|character| {
            !character.is_ascii_whitespace() && *character != ':' && *character != '-'
        })
        .collect::<String>();
    if compact.len() % 2 != 0
        || !compact
            .chars()
            .all(|character| character.is_ascii_hexdigit())
    {
        return Err("Hex data must contain complete hexadecimal byte pairs".to_string());
    }
    (0..compact.len())
        .step_by(2)
        .map(|index| {
            u8::from_str_radix(&compact[index..index + 2], 16).map_err(|error| error.to_string())
        })
        .collect()
}

fn format_hex_bytes(bytes: &[u8]) -> String {
    bytes
        .iter()
        .map(|byte| format!("{byte:02X}"))
        .collect::<Vec<_>>()
        .join(" ")
}

fn reorder_cue_lists_in_candidate(
    mut snapshot: EngineSnapshot,
    cue_list_ids: &[protocol::CueListId],
) -> Result<EngineSnapshot, String> {
    if cue_list_ids.is_empty() {
        return Err("Bank reorder must contain every Bank".to_string());
    }
    if cue_list_ids.len() != snapshot.cue_lists.len() {
        return Err(format!(
            "Bank reorder must contain all {} Banks exactly once",
            snapshot.cue_lists.len()
        ));
    }
    let mut by_id = snapshot
        .cue_lists
        .into_iter()
        .map(|cue_list| (cue_list.id, cue_list))
        .collect::<HashMap<_, _>>();
    let mut seen = HashSet::with_capacity(cue_list_ids.len());
    let mut reordered = Vec::with_capacity(cue_list_ids.len());
    for cue_list_id in cue_list_ids {
        if !seen.insert(*cue_list_id) {
            return Err(format!("Bank reorder contains duplicate ID {cue_list_id}"));
        }
        reordered.push(
            by_id
                .remove(cue_list_id)
                .ok_or_else(|| format!("Bank {cue_list_id} was not found"))?,
        );
    }
    if !by_id.is_empty() {
        return Err("Bank reorder omitted an existing Bank".to_string());
    }
    snapshot.cue_lists = reordered;
    Ok(snapshot)
}

fn delete_cue_list_in_candidate(
    mut snapshot: EngineSnapshot,
    cue_list_id: protocol::CueListId,
) -> Result<EngineSnapshot, String> {
    if snapshot.cue_lists.len() <= 1 {
        return Err("At least one Bank must remain".to_string());
    }
    if !snapshot
        .cue_lists
        .iter()
        .any(|cue_list| cue_list.id == cue_list_id)
    {
        return Err(format!("Bank {cue_list_id} was not found"));
    }
    let removed_cue_ids = snapshot
        .cues
        .iter()
        .filter(|cue| cue.cue_list_id == cue_list_id)
        .map(|cue| cue.id)
        .collect::<HashSet<_>>();
    snapshot
        .cue_lists
        .retain(|cue_list| cue_list.id != cue_list_id);
    snapshot.cues.retain(|cue| cue.cue_list_id != cue_list_id);
    snapshot
        .playback_executors
        .retain(|executor| executor.cue_list_id != cue_list_id);
    snapshot
        .active_group_cue_ids
        .retain(|_, cue_id| !removed_cue_ids.contains(cue_id));
    snapshot
        .cue_live_modifiers
        .retain(|modifier| !removed_cue_ids.contains(&modifier.cue_id));
    snapshot.active_cue_id = snapshot
        .active_cue_id
        .filter(|cue_id| !removed_cue_ids.contains(cue_id));
    if snapshot
        .active_fade
        .as_ref()
        .is_some_and(|fade| removed_cue_ids.contains(&fade.cue_id))
    {
        snapshot.active_fade = None;
    }
    snapshot
        .timeline
        .events
        .retain(|event| !removed_cue_ids.contains(&event.cue_id));
    let remaining_event_ids = snapshot
        .timeline
        .events
        .iter()
        .map(|event| event.id)
        .collect::<HashSet<_>>();
    for event in &mut snapshot.timeline.events {
        if event
            .jump_to_event_id
            .is_some_and(|target_id| !remaining_event_ids.contains(&target_id))
        {
            event.jump_to_event_id = None;
        }
    }
    Ok(snapshot)
}

fn add_empty_cue_in_candidate(
    mut snapshot: EngineSnapshot,
    cue_id: CueId,
    cue_list_id: protocol::CueListId,
) -> Result<EngineSnapshot, String> {
    if cue_id == 0 {
        return Err("Empty Cue ID must be greater than zero".to_string());
    }
    if !snapshot
        .cue_lists
        .iter()
        .any(|cue_list| cue_list.id == cue_list_id)
    {
        return Err(format!("Bank {cue_list_id} was not found"));
    }
    if snapshot.cues.iter().any(|cue| cue.id == cue_id) {
        return Err(format!("Cue {cue_id} already exists"));
    }
    snapshot.cues.push(protocol::CueSummary {
        id: cue_id,
        cue_list_id,
        cue_number: cue_id.to_string(),
        label: "New Scene".to_string(),
        ..protocol::CueSummary::default()
    });
    Ok(snapshot)
}

/// Thin adapter over the engine's single authoritative Bank label policy.
/// The exact submitted string is validated and later stored verbatim: no
/// trim, truncation, case folding, or normalization is applied here or in the
/// engine. See `engine::validate_cue_list_label` for the accepted alphabet,
/// the 64-scalar bound, and the Unicode equivalence/case policy.
fn validate_cue_list_label(label: &str) -> Result<String, String> {
    validate_engine_cue_list_label(label)?;
    Ok(label.to_string())
}

fn ensure_cue_list_label_available(
    snapshot: &EngineSnapshot,
    cue_list_id: Option<protocol::CueListId>,
    label: &str,
) -> Result<(), String> {
    if snapshot.cue_lists.iter().any(|cue_list| {
        Some(cue_list.id) != cue_list_id && engine::cue_list_labels_collide(label, &cue_list.label)
    }) {
        return Err(format!("Bank name '{label}' is already in use"));
    }
    Ok(())
}

/// Candidates stage the exact image the engine will publish, so they accept
/// only the already-validated exact string produced by
/// `engine::validate_cue_list_label`. Unvalidated input fails closed here
/// instead of being silently rewritten; this re-check keeps candidate and
/// engine verdicts identical by construction.
fn ensure_normalized_cue_list_label(label: &str) -> Result<(), String> {
    engine::validate_cue_list_label(label)
}

fn create_cue_list_in_candidate(
    mut snapshot: EngineSnapshot,
    cue_list_id: protocol::CueListId,
    label: &str,
) -> Result<EngineSnapshot, String> {
    if cue_list_id == 0 {
        return Err("Bank ID must be greater than zero".to_string());
    }
    ensure_normalized_cue_list_label(label)?;
    if snapshot
        .cue_lists
        .iter()
        .any(|cue_list| cue_list.id == cue_list_id)
    {
        return Err(format!("Bank {cue_list_id} already exists"));
    }
    ensure_cue_list_label_available(&snapshot, None, label)?;
    snapshot.cue_lists.push(protocol::CueListSummary {
        id: cue_list_id,
        label: label.to_string(),
        active_cue_id: None,
    });
    Ok(snapshot)
}

fn rename_cue_list_in_candidate(
    mut snapshot: EngineSnapshot,
    cue_list_id: protocol::CueListId,
    label: &str,
) -> Result<EngineSnapshot, String> {
    ensure_normalized_cue_list_label(label)?;
    if !snapshot
        .cue_lists
        .iter()
        .any(|cue_list| cue_list.id == cue_list_id)
    {
        return Err(format!("Bank {cue_list_id} was not found"));
    }
    ensure_cue_list_label_available(&snapshot, Some(cue_list_id), label)?;
    if let Some(cue_list) = snapshot
        .cue_lists
        .iter_mut()
        .find(|cue_list| cue_list.id == cue_list_id)
    {
        cue_list.label = label.to_string();
    }
    Ok(snapshot)
}

fn commit_authoritative_cue_list_reorder(
    state: &AppState,
    expected_epoch: u64,
    owner_id: &str,
    expected_authority: &MediaAssetPrepareAuthority,
    cue_list_ids: &[protocol::CueListId],
) -> Result<ProjectHistoryMutationResult, String> {
    let (_external_admission, mut coordinator) = (
        lock_project_external_command_admission(state)?,
        lock_project_coordinator(state)?,
    );
    validate_authoritative_media_asset_commit(
        state,
        &mut coordinator,
        expected_epoch,
        owner_id,
        expected_authority,
    )?;
    if state.project_transaction_active.load(Ordering::Acquire) {
        return Err("Project transaction is active; retry the Bank reorder".to_string());
    }

    let before_snapshot = state.engine.persistence_snapshot()?;
    let before_project =
        project_file_for_save_from_parts(before_snapshot.clone(), &coordinator.ancillary);
    let before = ProjectCheckpoint {
        hash: project_checkpoint_hash(&before_project, &coordinator.mappings)?,
        project: before_project,
        mappings: coordinator.mappings.clone(),
        epoch: coordinator.epoch,
        revision: coordinator.revision,
    };
    let candidate_snapshot = reorder_cue_lists_in_candidate(before_snapshot, cue_list_ids)?;
    let after_project =
        project_file_for_save_from_parts(candidate_snapshot, &coordinator.ancillary);
    let after = ProjectCheckpoint {
        project: after_project,
        mappings: coordinator.mappings.clone(),
        epoch: coordinator.epoch,
        revision: coordinator.revision,
        hash: String::new(),
    };
    let plan = prepare_internal_media_asset_commit(
        &coordinator,
        "Reorder Banks",
        "cue-lists-order",
        before,
        after,
        current_unix_ms().min(u64::MAX as u128) as u64,
    )?;
    run_admitted_internal_media_asset_transaction(
        &state.project_transaction_active,
        &mut coordinator,
        plan,
        || {
            state
                .engine
                .reorder_cue_lists_published(cue_list_ids.to_vec())
        },
    )?;
    Ok(ProjectHistoryMutationResult {
        history_status: project_history_status_for_coordinator(&coordinator),
        authority: project_authority_bundle_from_coordinator(state, &coordinator),
    })
}

fn commit_authoritative_cue_list_delete(
    state: &AppState,
    expected_epoch: u64,
    owner_id: &str,
    expected_authority: &MediaAssetPrepareAuthority,
    cue_list_id: protocol::CueListId,
) -> Result<ProjectHistoryMutationResult, String> {
    let (_external_admission, mut coordinator) = (
        lock_project_external_command_admission(state)?,
        lock_project_coordinator(state)?,
    );
    validate_authoritative_media_asset_commit(
        state,
        &mut coordinator,
        expected_epoch,
        owner_id,
        expected_authority,
    )?;
    if state.project_transaction_active.load(Ordering::Acquire) {
        return Err("Project transaction is active; retry the Bank delete".to_string());
    }

    let before_snapshot = state.engine.persistence_snapshot()?;
    let before_project =
        project_file_for_save_from_parts(before_snapshot.clone(), &coordinator.ancillary);
    let before = ProjectCheckpoint {
        hash: project_checkpoint_hash(&before_project, &coordinator.mappings)?,
        project: before_project,
        mappings: coordinator.mappings.clone(),
        epoch: coordinator.epoch,
        revision: coordinator.revision,
    };
    let candidate_snapshot = delete_cue_list_in_candidate(before_snapshot, cue_list_id)?;
    let after_project =
        project_file_for_save_from_parts(candidate_snapshot, &coordinator.ancillary);
    let after = ProjectCheckpoint {
        project: after_project,
        mappings: coordinator.mappings.clone(),
        epoch: coordinator.epoch,
        revision: coordinator.revision,
        hash: String::new(),
    };
    let plan = prepare_internal_media_asset_commit(
        &coordinator,
        "Delete Bank",
        "cue-lists-delete",
        before,
        after,
        current_unix_ms().min(u64::MAX as u128) as u64,
    )?;
    run_admitted_internal_media_asset_transaction(
        &state.project_transaction_active,
        &mut coordinator,
        plan,
        || state.engine.delete_cue_list_published(cue_list_id),
    )?;
    Ok(ProjectHistoryMutationResult {
        history_status: project_history_status_for_coordinator(&coordinator),
        authority: project_authority_bundle_from_coordinator(state, &coordinator),
    })
}

/// Prepare the exact captured Scene image before allocating its identity or
/// opening publication. The programmer/video preview applies only to the
/// capture input; it must not silently become a separately persisted project
/// mutation.
fn prepare_captured_scene_create(
    before_snapshot: &EngineSnapshot,
    label: String,
    fade_ms: u64,
    authored_beats: Option<f32>,
    capture_scope: CueCaptureScope,
    effect_targets: Vec<CueEffectTarget>,
) -> Result<CapturedSceneCreate, String> {
    let label = label.trim().to_string();
    if label.is_empty() {
        return Err("Cue label is required".to_string());
    }
    validate_cue_authored_beats(authored_beats)?;
    let mut capture_snapshot = before_snapshot.clone();
    use_authored_video_snapshot(&mut capture_snapshot);
    apply_programmer_preview_to_snapshot(&mut capture_snapshot);
    let (targets, video_targets, video_output_targets, node_graph_targets, _) =
        cue_targets_from_snapshot_with_scope(&capture_snapshot, &capture_scope)?;
    let effect_targets = copy_cue_effect_params_on_capture(&capture_snapshot, effect_targets)?;
    let group_id = match &capture_scope {
        CueCaptureScope::SelectedGroup { group_id } => Some(normalize_group_id(group_id)?),
        _ => None,
    };
    validate_cue_effect_targets(&capture_snapshot, &effect_targets)?;
    ensure_cue_targets_present(
        &targets,
        &video_targets,
        &video_output_targets,
        &node_graph_targets,
        &effect_targets,
        false,
        "creating",
    )?;
    Ok(CapturedSceneCreate {
        label,
        group_id,
        fade_ms,
        authored_beats,
        targets,
        video_targets,
        video_output_targets,
        node_graph_targets,
        effect_targets,
    })
}

fn commit_authoritative_scene_create(
    state: &AppState,
    expected_epoch: u64,
    owner_id: &str,
    expected_authority: &MediaAssetPrepareAuthority,
    cue_list_id: protocol::CueListId,
    requested_create: AuthoritativeSceneCreateKind,
) -> Result<SceneCreationMutationReceipt, String> {
    commit_authoritative_scene_create_with_publication(
        state,
        expected_epoch,
        owner_id,
        expected_authority,
        cue_list_id,
        requested_create,
        |prepared_create, cue_id, cue_list_id| match prepared_create {
            PreparedAuthoritativeSceneCreateKind::Empty => {
                state.engine.create_empty_cue_published(cue_id, cue_list_id)
            }
            PreparedAuthoritativeSceneCreateKind::CaptureCurrent(captured) => {
                state.engine.create_cue_published(
                    cue_id,
                    cue_list_id,
                    captured.label,
                    captured.group_id,
                    RecallMode::Coexist,
                    captured.fade_ms,
                    captured.authored_beats,
                    captured.targets,
                    captured.video_targets,
                    captured.video_output_targets,
                    captured.node_graph_targets,
                    captured.effect_targets,
                )
            }
        },
    )
}

/// Testable composition seam for the one authoritative Scene-create core.
/// Production passes only the real engine publisher above; this private
/// function exists so both classified terminal outcomes can be proven without
/// manufacturing a second local snapshot authority.
fn commit_authoritative_scene_create_with_publication(
    state: &AppState,
    expected_epoch: u64,
    owner_id: &str,
    expected_authority: &MediaAssetPrepareAuthority,
    cue_list_id: protocol::CueListId,
    requested_create: AuthoritativeSceneCreateKind,
    publish: impl FnOnce(
        PreparedAuthoritativeSceneCreateKind,
        protocol::CueId,
        protocol::CueListId,
    ) -> Result<(), SnapshotPublicationFailure>,
) -> Result<SceneCreationMutationReceipt, String> {
    let (_external_admission, mut coordinator) = (
        lock_project_external_command_admission(state)?,
        lock_project_coordinator(state)?,
    );
    validate_authoritative_media_asset_commit(
        state,
        &mut coordinator,
        expected_epoch,
        owner_id,
        expected_authority,
    )?;
    if state.project_transaction_active.load(Ordering::Acquire) {
        return Err("Project transaction is active; retry the Scene create".to_string());
    }

    let before_snapshot = state.engine.persistence_snapshot()?;
    let before_project =
        project_file_for_save_from_parts(before_snapshot.clone(), &coordinator.ancillary);
    let before = ProjectCheckpoint {
        hash: project_checkpoint_hash(&before_project, &coordinator.mappings)?,
        project: before_project,
        mappings: coordinator.mappings.clone(),
        epoch: coordinator.epoch,
        revision: coordinator.revision,
    };
    let prepared_create = match requested_create {
        AuthoritativeSceneCreateKind::Empty => PreparedAuthoritativeSceneCreateKind::Empty,
        AuthoritativeSceneCreateKind::CaptureCurrent {
            label,
            fade_ms,
            authored_beats,
            capture_scope,
            effect_targets,
        } => PreparedAuthoritativeSceneCreateKind::CaptureCurrent(prepare_captured_scene_create(
            &before_snapshot,
            label,
            fade_ms,
            authored_beats,
            capture_scope,
            effect_targets,
        )?),
    };
    let cue_id = state.engine.allocate_cue_id();
    let candidate_snapshot = match &prepared_create {
        PreparedAuthoritativeSceneCreateKind::Empty => {
            add_empty_cue_in_candidate(before_snapshot.clone(), cue_id, cue_list_id)
        }
        PreparedAuthoritativeSceneCreateKind::CaptureCurrent(captured) => {
            add_captured_scene_in_candidate(before_snapshot.clone(), cue_id, cue_list_id, captured)
        }
    };
    let candidate_snapshot = match candidate_snapshot {
        Ok(snapshot) => snapshot,
        Err(error) => {
            let _ = state.engine.release_cue_id_if_last(cue_id);
            return Err(error);
        }
    };
    let after_project =
        project_file_for_save_from_parts(candidate_snapshot, &coordinator.ancillary);
    let after = ProjectCheckpoint {
        project: after_project,
        mappings: coordinator.mappings.clone(),
        epoch: coordinator.epoch,
        revision: coordinator.revision,
        hash: String::new(),
    };
    let plan = match prepare_internal_media_asset_commit(
        &coordinator,
        match &prepared_create {
            PreparedAuthoritativeSceneCreateKind::Empty => "Create Empty Scene",
            PreparedAuthoritativeSceneCreateKind::CaptureCurrent(_) => "Create Scene from Current",
        },
        "",
        before,
        after,
        current_unix_ms().min(u64::MAX as u128) as u64,
    ) {
        Ok(plan) => plan,
        Err(error) => {
            let _ = state.engine.release_cue_id_if_last(cue_id);
            return Err(error);
        }
    };
    // Both Scene-create modes publish through the classified admitted
    // snapshot protocol. A definitive rejection restores A and lets us
    // reclaim the tail reservation. An admitted ACK loss is indeterminate:
    // B may already be live, so the reservation stays consumed and the
    // global project-mutation fence remains armed until restart.
    let publication = run_admitted_internal_media_asset_transaction_with_publication_outcome(
        &state.project_external_command_admission,
        &state.project_transaction_active,
        &mut coordinator,
        plan,
        || publish(prepared_create, cue_id, cue_list_id),
    );
    if let Err(error) = publication {
        if matches!(&error, AdmittedPublicationError::Definitive(_)) {
            let _ = state.engine.release_cue_id_if_last(cue_id);
        }
        return Err(error.into_message());
    }
    Ok(SceneCreationMutationReceipt {
        mutation: ProjectHistoryMutationResult {
            history_status: project_history_status_for_coordinator(&coordinator),
            authority: project_authority_bundle_from_coordinator(state, &coordinator),
        },
        cue_id,
    })
}

const CUE_LIST_CREATE_HISTORY_LABEL: &str = "Create Bank";
const CUE_LIST_RENAME_HISTORY_LABEL: &str = "Rename Bank";
const CUE_LIST_RENAME_COALESCE_KEY_PREFIX: &str = "cue-lists-rename";

/// The exact per-Bank rename undo identity. Two renames of DIFFERENT Banks
/// never coalesce; rapid renames of the SAME Bank within the history window
/// collapse into one Undo step.
fn cue_list_rename_coalesce_key(cue_list_id: protocol::CueListId) -> String {
    format!("{CUE_LIST_RENAME_COALESCE_KEY_PREFIX}:{cue_list_id}")
}

/// Authoritative Bank create result: the same complete mutation receipt the
/// reorder/delete commands return, plus the allocated Bank ID. The ID is the
/// allocation that the acknowledged engine publication committed; no second
/// unsynchronized snapshot read is required.
#[derive(Debug, Clone, Serialize)]
struct CueListMutationReceipt {
    #[serde(flatten)]
    mutation: ProjectHistoryMutationResult,
    cue_list_id: protocol::CueListId,
}

fn commit_authoritative_cue_list_create(
    state: &AppState,
    expected_epoch: u64,
    owner_id: &str,
    expected_authority: &MediaAssetPrepareAuthority,
    label: &str,
) -> Result<CueListMutationReceipt, String> {
    let (_external_admission, mut coordinator) = (
        lock_project_external_command_admission(state)?,
        lock_project_coordinator(state)?,
    );
    validate_authoritative_media_asset_commit(
        state,
        &mut coordinator,
        expected_epoch,
        owner_id,
        expected_authority,
    )?;
    if state.project_transaction_active.load(Ordering::Acquire) {
        return Err("Project transaction is active; retry the Bank create".to_string());
    }

    let before_snapshot = state.engine.persistence_snapshot()?;
    let before_project =
        project_file_for_save_from_parts(before_snapshot.clone(), &coordinator.ancillary);
    let before = ProjectCheckpoint {
        hash: project_checkpoint_hash(&before_project, &coordinator.mappings)?,
        project: before_project,
        mappings: coordinator.mappings.clone(),
        epoch: coordinator.epoch,
        revision: coordinator.revision,
    };
    // Allocate only inside the fenced window and reclaim the tail on every
    // pre-publication failure so a rejected create cannot leak an identity
    // while concurrent reservations stay monotonic.
    let cue_list_id = state.engine.allocate_cue_list_id();
    let candidate_snapshot = match create_cue_list_in_candidate(before_snapshot, cue_list_id, label)
    {
        Ok(snapshot) => snapshot,
        Err(error) => {
            let _ = state.engine.release_cue_list_id_if_last(cue_list_id);
            return Err(error);
        }
    };
    let after_project =
        project_file_for_save_from_parts(candidate_snapshot, &coordinator.ancillary);
    let after = ProjectCheckpoint {
        project: after_project,
        mappings: coordinator.mappings.clone(),
        epoch: coordinator.epoch,
        revision: coordinator.revision,
        hash: String::new(),
    };
    // Bank creates NEVER coalesce: each create is its own Undo step, so a
    // rapid burst of creates is fully reversible one step at a time.
    let plan = match prepare_internal_media_asset_commit(
        &coordinator,
        CUE_LIST_CREATE_HISTORY_LABEL,
        "",
        before,
        after,
        current_unix_ms().min(u64::MAX as u128) as u64,
    ) {
        Ok(plan) => plan,
        Err(error) => {
            let _ = state.engine.release_cue_list_id_if_last(cue_list_id);
            return Err(error);
        }
    };
    if let Err(publication_error) =
        run_admitted_internal_media_asset_transaction_with_publication_outcome(
            &state.project_external_command_admission,
            &state.project_transaction_active,
            &mut coordinator,
            plan,
            || {
                state
                    .engine
                    .create_cue_list_published(cue_list_id, label.to_string())
            },
        )
    {
        match publication_error {
            AdmittedPublicationError::Definitive(error) => {
                // Nothing was published; the tail reservation is reclaimable.
                let _ = state.engine.release_cue_list_id_if_last(cue_list_id);
                return Err(error);
            }
            AdmittedPublicationError::Indeterminate(error) => {
                // The engine may have applied and published B. The ID stays
                // reserved (no ABA reuse) and the global mutation fence is
                // already armed by the runner.
                return Err(error);
            }
        }
    }
    Ok(CueListMutationReceipt {
        mutation: ProjectHistoryMutationResult {
            history_status: project_history_status_for_coordinator(&coordinator),
            authority: project_authority_bundle_from_coordinator(state, &coordinator),
        },
        cue_list_id,
    })
}

fn commit_authoritative_cue_list_rename(
    state: &AppState,
    expected_epoch: u64,
    owner_id: &str,
    expected_authority: &MediaAssetPrepareAuthority,
    cue_list_id: protocol::CueListId,
    label: &str,
) -> Result<ProjectHistoryMutationResult, String> {
    let (_external_admission, mut coordinator) = (
        lock_project_external_command_admission(state)?,
        lock_project_coordinator(state)?,
    );
    validate_authoritative_media_asset_commit(
        state,
        &mut coordinator,
        expected_epoch,
        owner_id,
        expected_authority,
    )?;
    if state.project_transaction_active.load(Ordering::Acquire) {
        return Err("Project transaction is active; retry the Bank rename".to_string());
    }

    let before_snapshot = state.engine.persistence_snapshot()?;
    let before_project =
        project_file_for_save_from_parts(before_snapshot.clone(), &coordinator.ancillary);
    let before = ProjectCheckpoint {
        hash: project_checkpoint_hash(&before_project, &coordinator.mappings)?,
        project: before_project,
        mappings: coordinator.mappings.clone(),
        epoch: coordinator.epoch,
        revision: coordinator.revision,
    };
    let candidate_snapshot = rename_cue_list_in_candidate(before_snapshot, cue_list_id, label)?;
    let after_project =
        project_file_for_save_from_parts(candidate_snapshot, &coordinator.ancillary);
    let after = ProjectCheckpoint {
        project: after_project,
        mappings: coordinator.mappings.clone(),
        epoch: coordinator.epoch,
        revision: coordinator.revision,
        hash: String::new(),
    };
    let plan = prepare_internal_media_asset_commit(
        &coordinator,
        CUE_LIST_RENAME_HISTORY_LABEL,
        &cue_list_rename_coalesce_key(cue_list_id),
        before,
        after,
        current_unix_ms().min(u64::MAX as u128) as u64,
    )?;
    if let Err(publication_error) =
        run_admitted_internal_media_asset_transaction_with_publication_outcome(
            &state.project_external_command_admission,
            &state.project_transaction_active,
            &mut coordinator,
            plan,
            || {
                state
                    .engine
                    .rename_cue_list_published(cue_list_id, label.to_string())
            },
        )
    {
        return Err(publication_error.into_message());
    }
    Ok(ProjectHistoryMutationResult {
        history_status: project_history_status_for_coordinator(&coordinator),
        authority: project_authority_bundle_from_coordinator(state, &coordinator),
    })
}

