fn set_group_color_for_window_label(
    state: &AppState,
    group_id: String,
    color: Option<String>,
    context: RendererTicketedProjectMutationContext<'_>,
) -> Result<(), String> {
    if group_id.trim().is_empty() {
        return Err("Group id is required".to_string());
    }
    if let Some(color) = &color {
        validate_video_cue_point_color(color)?;
    }
    let color = normalize_fixture_group_color(color)?;
    let (_external_admission, mut coordinator, _transaction_admission) =
        lock_renderer_ticketed_project_mutation(
            state,
            context.window_label,
            "set_group_color",
            context.project_transaction_id,
            context.expected_epoch,
            context.owner_id,
        )?;
    let affects_project_groups = coordinator
        .ancillary
        .fixture_groups
        .iter()
        .any(|group| group.id == group_id);
    let mut candidate_snapshot = state.engine.persistence_snapshot()?;
    match color.clone() {
        Some(color) => {
            candidate_snapshot
                .group_colors
                .insert(group_id.clone(), color);
        }
        None => {
            candidate_snapshot.group_colors.remove(&group_id);
        }
    }
    let mut candidate_ancillary = coordinator.ancillary.clone();
    if affects_project_groups {
        let group = candidate_ancillary
            .fixture_groups
            .iter_mut()
            .find(|group| group.id == group_id)
            .expect("membership was checked above");
        group.color = color.clone();
    }
    let published_snapshot = candidate_snapshot.clone();
    let prepared = publish_direct_project_ancillary_mutation(
        state,
        &coordinator,
        candidate_snapshot,
        candidate_ancillary,
        || publish_fixture_group_state_candidate(&state.engine, &published_snapshot),
    )?;
    commit_direct_project_ancillary_mutation_after_preflight(state, &mut coordinator, prepared);
    Ok(())
}

fn validate_cue_authored_beats(authored_beats: Option<f32>) -> Result<(), String> {
    let Some(authored_beats) = authored_beats else {
        return Ok(());
    };
    if !authored_beats.is_finite()
        || !(protocol::MIN_CUE_AUTHORED_BEATS..=protocol::MAX_CUE_AUTHORED_BEATS)
            .contains(&authored_beats)
    {
        return Err(format!(
            "Cue authored beats must be a finite value from {} to {} (received {authored_beats})",
            protocol::MIN_CUE_AUTHORED_BEATS,
            protocol::MAX_CUE_AUTHORED_BEATS
        ));
    }
    Ok(())
}

fn validate_cue_mib_fixture_ids(
    cue: &protocol::CueSummary,
    fixture_ids: &[FixtureId],
) -> Result<(), String> {
    if fixture_ids.len() > 256 {
        return Err("A Cue MIB filter can contain at most 256 fixtures".to_string());
    }
    let target_ids = cue
        .targets
        .iter()
        .map(|target| target.fixture_id)
        .chain(
            cue.palette_targets
                .iter()
                .flat_map(|target| target.fixture_ids.iter().copied()),
        )
        .collect::<HashSet<_>>();
    let mut seen = HashSet::new();
    for fixture_id in fixture_ids {
        if !seen.insert(*fixture_id) {
            return Err(format!("MIB fixture {fixture_id} is duplicated"));
        }
        if !target_ids.contains(fixture_id) {
            return Err(format!(
                "MIB fixture {fixture_id} is not targeted by this Cue"
            ));
        }
    }
    Ok(())
}

fn validate_cue_parts_for_summary(
    cue: &protocol::CueSummary,
    parts: &[protocol::CuePartSummary],
) -> Result<(), String> {
    if parts.len() > 16 {
        return Err("A cue can contain at most 16 parts".to_string());
    }
    let target_ids = cue
        .targets
        .iter()
        .map(|target| target.fixture_id)
        .collect::<HashSet<_>>();
    let video_layer_ids = cue
        .video_targets
        .iter()
        .map(|target| target.layer_id)
        .collect::<HashSet<_>>();
    let video_output_ids = cue
        .video_output_targets
        .iter()
        .map(|target| target.output_id)
        .collect::<HashSet<_>>();
    let mut numbers = HashSet::new();
    let mut assigned = HashSet::new();
    let mut assigned_video_layers = HashSet::new();
    let mut assigned_video_outputs = HashSet::new();
    for part in parts {
        if part.number == 0 || part.number > 999 || !numbers.insert(part.number) {
            return Err("Cue Part numbers must be unique values from 1 to 999".to_string());
        }
        if part.label.trim().is_empty() {
            return Err(format!("Cue Part {} label is required", part.number));
        }
        for fixture_id in &part.fixture_ids {
            if !target_ids.contains(fixture_id) {
                return Err(format!(
                    "Cue Part {} references fixture {} outside this cue",
                    part.number, fixture_id
                ));
            }
            if !assigned.insert(*fixture_id) {
                return Err(format!(
                    "Fixture {} is assigned to more than one Cue Part",
                    fixture_id
                ));
            }
        }
        for layer_id in &part.video_layer_ids {
            if !video_layer_ids.contains(layer_id) {
                return Err(format!(
                    "Cue Part {} references video layer {} outside this cue",
                    part.number, layer_id
                ));
            }
            if !assigned_video_layers.insert(*layer_id) {
                return Err(format!(
                    "Video layer {} is assigned to more than one Cue Part",
                    layer_id
                ));
            }
        }
        for output_id in &part.video_output_ids {
            if !video_output_ids.contains(output_id) {
                return Err(format!(
                    "Cue Part {} references video output {} outside this cue",
                    part.number, output_id
                ));
            }
            if !assigned_video_outputs.insert(*output_id) {
                return Err(format!(
                    "Video output {} is assigned to more than one Cue Part",
                    output_id
                ));
            }
        }
    }
    Ok(())
}

#[tauri::command]
fn move_cue(state: State<'_, AppState>, cue_id: CueId, delta: i32) -> Result<(), String> {
    if delta == 0 {
        return Ok(());
    }
    if !state
        .engine
        .snapshot()
        .cues
        .iter()
        .any(|cue| cue.id == cue_id)
    {
        return Err(format!("Cue {cue_id} was not found"));
    }
    state
        .engine
        .send(EngineCommand::MoveCue { cue_id, delta })
        .map_err(|error| error.to_string())
}

#[tauri::command]
fn duplicate_cue(
    state: State<'_, AppState>,
    source_cue_id: CueId,
    label: String,
) -> Result<CueId, String> {
    let label = label.trim().to_string();
    if label.is_empty() {
        return Err("Cue label is required".to_string());
    }
    if !state
        .engine
        .snapshot()
        .cues
        .iter()
        .any(|cue| cue.id == source_cue_id)
    {
        return Err(format!("Cue {source_cue_id} was not found"));
    }
    let cue_id = state.engine.allocate_cue_id();
    state
        .engine
        .send(EngineCommand::DuplicateCue {
            source_cue_id,
            cue_id,
            label,
        })
        .map_err(|error| error.to_string())?;
    Ok(cue_id)
}

