/// Reserve a server-owned staged operation for an old wire-compatible IPC
/// call. It resolves the owner from the invoking window, captures the current
/// A authority under external admission, and applies the same server-side
/// Operator policy used by A1 before any path is opened or hashed.
fn reserve_legacy_media_asset_compatibility_operation(
    state: &AppState,
    window: &WebviewWindow,
) -> Result<LegacyMediaAssetCompatibilityOperation, String> {
    let window_label = window.label().to_string();
    // A Destroyed retirement installs a temporary or permanent label fence
    // before owner/lease cleanup. Check it before resolving the legacy owner;
    // otherwise a raw compatibility call could retain the stale owner while
    // retirement is in flight.
    state.ensure_window_authority_not_blocked(&window_label)?;
    let _external_admission = lock_project_external_command_admission(state)?;
    let mut coordinator = lock_project_coordinator(state)?;
    // Resolve the concrete window generation only while the same admission
    // boundary that excludes owner rotation is held. Looking it up before this
    // boundary left an ABA gap: A could read X, rotate to Y, and B could claim
    // the now-free X before the old operation reserved its server token.
    let (owner_id, owner_incarnation) = {
        let owners = state
            .project_transaction_owners
            .lock()
            .map_err(|_| "Project transaction owner registry lock was poisoned".to_string())?;
        let owner_id =
            legacy_media_asset_compatibility_owner_for_window_label(&owners, &window_label)?;
        let incarnations = state
            .project_transaction_owner_incarnations
            .lock()
            .map_err(|_| {
                "Project transaction owner incarnation registry lock was poisoned".to_string()
            })?;
        let owner_incarnation = incarnations.get(&window_label).copied().ok_or_else(|| {
            "Legacy media compatibility IPC requires a registered renderer incarnation".to_string()
        })?;
        (owner_id, owner_incarnation)
    };
    // Recheck after owner lookup while admission is held. A Destroyed marker
    // installed between the entry check and this point must reject before any
    // compatibility operation handle is reserved.
    state.ensure_window_authority_not_blocked(&window_label)?;
    reconcile_project_checkpoint_for_coordinator(state, &mut coordinator)?;
    ensure_project_transaction_owner_registered(state, &owner_id)?;
    ensure_no_pending_project_transaction(&coordinator)?;
    ensure_project_operator_authoritative_mutation_allowed(state, &coordinator, &owner_id)?;
    let authority = media_asset_prepare_authority(&coordinator);
    let handle = state
        .media_asset_operations
        .reserve_legacy_compatibility(owner_id.clone(), authority.clone())?;
    Ok(LegacyMediaAssetCompatibilityOperation {
        request_id: handle.request_id,
        operation_generation: handle.generation,
        window_label,
        owner_id,
        owner_incarnation,
        authority,
    })
}

/// Best-effort cleanup for pre-admission compatibility failures. A failed
/// cleanup must not replace the original prepare/finalize error; the registry
/// reaper remains the final retained-handle backstop. Once A1 admission won,
/// cancel intentionally returns false and its terminal receipt owns cleanup.
fn cancel_legacy_media_asset_compatibility_operation(
    state: &AppState,
    operation: &LegacyMediaAssetCompatibilityOperation,
) {
    let _ = state.media_asset_operations.cancel_exact(
        operation.request_id,
        operation.operation_generation,
        operation.owner_id.clone(),
    );
}

/// Hash/probe a prepared batch under an already-owned operation guard, recheck
/// the authority, and store the prepared record. Shared by the legacy
/// `prepare_local_media_assets` (which allocates its own generation) and the
/// staged `prepare_reserved_media_assets` (which adopts a slot the client
/// reserved before hashing). The guard is moved in so it drops — removing the
/// active entry — exactly when preparation completes or fails.
async fn run_prepared_local_media_asset_batch(
    state: &AppState,
    operation: MediaAssetOperationGuard,
    kind: VideoSourceKind,
    paths: Vec<String>,
    context: MediaAssetPrepareBatchContext<'_>,
) -> Result<MediaAssetImportReport, String> {
    let MediaAssetPrepareBatchContext {
        expected_epoch,
        owner_id,
        authority,
        legacy_operation,
    } = context;
    let registry = Arc::clone(&state.media_asset_operations);
    let handle = operation.handle();
    let request_id = handle.request_id;
    let cancel = operation.cancellation_flag();
    let admission = operation.admission();
    let prepare_cancel = Arc::clone(&cancel);
    let prepared_result = tauri::async_runtime::spawn_blocking(move || {
        prepare_local_media_asset_batch(kind, paths, prepare_cancel.as_ref())
    })
    .await
    .map_err(|error| format!("Local media asset prepare worker failed: {error}"))?;
    let (assets, entries) = prepared_result?;
    if operation.cancelled() {
        return Err("Media asset operation was cancelled".to_string());
    }
    // A prepared A image must never be applied to a replaced B project. A
    // normal concurrent mutation also invalidates preparation because its
    // catalog dedupe inventory changed under this report.
    let current_authority =
        capture_media_asset_prepare_authority(state, owner_id, expected_epoch, legacy_operation)?;
    if current_authority != authority {
        return Err(
            "Project changed while local media assets were being prepared; retry the import"
                .to_string(),
        );
    }
    let token = if assets.is_empty() {
        None
    } else {
        Some(registry.store_prepared_from_active(
            &handle,
            owner_id,
            PreparedMediaAssetImport {
                request_id,
                operation_generation: handle.generation,
                owner_id: owner_id.to_string(),
                authority: authority.clone(),
                assets,
                entries: entries.clone(),
                cancel,
                admission,
                finalized_sources: None,
                expires_at: Instant::now() + MEDIA_ASSET_PREPARED_IMPORT_TTL,
            },
        )?)
    };
    Ok(media_asset_import_report(
        request_id,
        handle.generation,
        token,
        &authority,
        entries,
    ))
}

/// Reserve an operation and hand its exact identity to the client *before* any
/// hashing begins, so an AbortSignal can cancel the very first hashed chunk of
/// the subsequent `prepare_reserved_media_assets`. This is the missing
/// first-phase-cancellation seam: the legacy `prepare_local_media_assets` only
/// reveals the generation in its reply, after hashing has already run.
#[tauri::command]
fn start_media_asset_operation(
    window: WebviewWindow,
    state: State<'_, AppState>,
    request_id: u64,
    expected_epoch: u64,
    owner_id: String,
) -> Result<MediaAssetOperationStartReport, String> {
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    project_transaction_owner_binding_for_window(&state, window.label(), &owner_id)?;
    // Capture (and reconcile) the authority first so a busy/replaced project
    // fails fast before a generation is burned, and the client learns the exact
    // A baseline it will later fence its staged commit against.
    let authority = capture_media_asset_prepare_authority(&state, &owner_id, expected_epoch, None)?;
    // Bind the exact authority (A) into the reservation and return the same A to
    // the client. The staged prepare adopts this A and refuses to run against any
    // other current authority.
    let handle =
        state
            .media_asset_operations
            .reserve(request_id, owner_id.clone(), authority.clone())?;
    Ok(MediaAssetOperationStartReport {
        request_id: handle.request_id,
        operation_generation: handle.generation,
        project_epoch: authority.epoch,
        project_revision: authority.revision,
        checkpoint_hash: authority.checkpoint_hash,
    })
}

/// Reserve a read-only availability inspection before any file is opened. This
/// path intentionally uses the non-reconciling catalog capture, so reserving a
/// long verified inspection cannot advance revision or history.
#[tauri::command]
fn start_media_asset_availability_operation(
    window: WebviewWindow,
    state: State<'_, AppState>,
    request_id: u64,
    expected_epoch: u64,
    owner_id: String,
) -> Result<MediaAssetOperationStartReport, String> {
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    project_transaction_owner_binding_for_window(&state, window.label(), &owner_id)?;
    let (authority, _) =
        capture_media_asset_availability_inventory(&state, &owner_id, expected_epoch)?;
    let handle = state.media_asset_operations.reserve_availability(
        request_id,
        owner_id,
        authority.clone(),
    )?;
    Ok(MediaAssetOperationStartReport {
        request_id: handle.request_id,
        operation_generation: handle.generation,
        project_epoch: authority.epoch,
        project_revision: authority.revision,
        checkpoint_hash: authority.checkpoint_hash,
    })
}

/// Staged prepare that adopts a reserved operation. Because the reservation
/// already exists, a `cancel_media_asset_operation` for this exact
/// {request_id, generation, owner_id} can win before or during the first hashed
/// chunk. Kept separate from `prepare_local_media_assets` so the legacy
/// single-call flow stays byte-for-byte compatible.
async fn prepare_reserved_media_assets_impl(
    state: &AppState,
    operation_identity: MediaAssetOperationIdentity,
    kind: VideoSourceKind,
    paths: Vec<String>,
    expected_epoch: u64,
    owner_id: &str,
    legacy_operation: Option<&LegacyMediaAssetCompatibilityOperation>,
) -> Result<MediaAssetImportReport, String> {
    let (request_id, operation_generation) = operation_identity;
    let (operation, reserved_authority) = state.media_asset_operations.adopt_reserved(
        request_id,
        operation_generation,
        owner_id.to_string(),
    )?;
    // Recapture the current authority and require it still equals the exact A the
    // client was told at Start. This rejects a same-epoch revision/hash mutation
    // between Start and Prepare *before* any hashing, token, or publication, so a
    // prepared A image can never be silently rebound onto a replaced B. Epoch
    // replacement is still rejected by the `expected_epoch` check inside the
    // capture. Either early return drops the adopted `operation` guard, releasing
    // the slot so a later cancel/adopt reports the truth.
    let current_authority =
        capture_media_asset_prepare_authority(state, owner_id, expected_epoch, legacy_operation)?;
    ensure_reserved_media_asset_authority_unchanged(&reserved_authority, &current_authority)?;
    run_prepared_local_media_asset_batch(
        state,
        operation,
        kind,
        paths,
        MediaAssetPrepareBatchContext {
            expected_epoch,
            owner_id,
            authority: reserved_authority,
            legacy_operation,
        },
    )
    .await
}

#[tauri::command]
async fn prepare_reserved_media_assets(
    state: State<'_, AppState>,
    request_id: u64,
    operation_generation: u64,
    kind: VideoSourceKind,
    paths: Vec<String>,
    expected_epoch: u64,
    owner_id: String,
) -> Result<MediaAssetImportReport, String> {
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    prepare_reserved_media_assets_impl(
        &state,
        (request_id, operation_generation),
        kind,
        paths,
        expected_epoch,
        &owner_id,
        None,
    )
    .await
}

/// Prepare local files outside a pending project transaction. The result
/// exposes only an opaque server token; hashes, fingerprints and sources stay
/// in the backend store until the exact owner/ticket commit arrives.
#[tauri::command]
async fn prepare_local_media_assets(
    state: State<'_, AppState>,
    request_id: u64,
    kind: VideoSourceKind,
    paths: Vec<String>,
    expected_epoch: u64,
    owner_id: String,
) -> Result<MediaAssetImportReport, String> {
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    let authority = capture_media_asset_prepare_authority(&state, &owner_id, expected_epoch, None)?;
    let operation = state
        .media_asset_operations
        .begin(request_id, owner_id.clone())?;
    run_prepared_local_media_asset_batch(
        &state,
        operation,
        kind,
        paths,
        MediaAssetPrepareBatchContext {
            expected_epoch,
            owner_id: &owner_id,
            authority,
            legacy_operation: None,
        },
    )
    .await
}

#[tauri::command]
fn cancel_media_asset_operation(
    window: WebviewWindow,
    state: State<'_, AppState>,
    request_id: u64,
    operation_generation: u64,
    owner_id: String,
) -> Result<bool, String> {
    project_transaction_owner_binding_for_window(&state, window.label(), &owner_id)?;
    state
        .media_asset_operations
        .cancel_exact(request_id, operation_generation, owner_id)
}

async fn run_media_asset_availability_inspection(
    state: &AppState,
    operation: MediaAssetOperationGuard,
    authority: MediaAssetPrepareAuthority,
    inspection: (Vec<MediaAssetSummary>, Vec<MediaAssetId>, bool),
    expected_epoch: u64,
    owner_id: &str,
) -> Result<MediaAssetAvailabilityReport, String> {
    let (assets, asset_ids, verify_hash) = inspection;
    let handle = operation.handle();
    let cancel = operation.cancellation_flag();
    let availability = tauri::async_runtime::spawn_blocking(move || {
        inspect_media_asset_availability_batch(&assets, &asset_ids, verify_hash, cancel.as_ref())
    })
    .await
    .map_err(|error| format!("Media asset availability worker failed: {error}"))??;
    let (current_authority, _) =
        capture_media_asset_availability_inventory(state, owner_id, expected_epoch)?;
    if current_authority != authority {
        return Err(
            "Project changed while media asset availability was being inspected; retry".to_string(),
        );
    }
    // Completion is the read command's linearization point. A cancel which won
    // at any point through the final authority capture makes this CAS fail and
    // no report is returned. Once this CAS wins, an exact cancel returns false,
    // so cancel=true and a successful report can never coexist.
    match operation.admission().try_admit() {
        Ok(MediaAssetCommitAdmission::Admitted) => {}
        Ok(MediaAssetCommitAdmission::AlreadyAdmitted) => {
            return Err("Media asset availability operation already completed".to_string())
        }
        Err(()) => return Err("Media asset operation was cancelled".to_string()),
    }
    // Availability is machine-local runtime truth.  Publish each terminal
    // verdict to the engine after the read-only inspection linearizes so the
    // Timeline renderer can fail closed without doing filesystem I/O on its
    // render tick.  The map is cleared on project replacement and is never
    // included in authored persistence/history.
    for verdict in &availability {
        let asset_id = match verdict {
            MediaAssetAvailability::AvailableVerified { asset_id }
            | MediaAssetAvailability::AvailableUnverified { asset_id }
            | MediaAssetAvailability::Missing { asset_id }
            | MediaAssetAvailability::HashMismatch { asset_id, .. }
            | MediaAssetAvailability::Unreadable { asset_id, .. }
            | MediaAssetAvailability::LiveSource { asset_id } => *asset_id,
        };
        let available = matches!(
            verdict,
            MediaAssetAvailability::AvailableVerified { .. }
                | MediaAssetAvailability::AvailableUnverified { .. }
                | MediaAssetAvailability::LiveSource { .. }
        );
        state
            .engine
            .set_media_asset_availability(asset_id, available)?;
    }
    Ok(MediaAssetAvailabilityReport {
        request_id: handle.request_id,
        operation_generation: handle.generation,
        project_epoch: authority.epoch,
        project_revision: authority.revision,
        checkpoint_hash: authority.checkpoint_hash,
        availability,
    })
}

/// Inspect machine-local availability without opening a project transaction or
/// mutating catalog/history state. The second exact capture prevents a report
/// for project A being presented as a report for a replaced project B.
#[tauri::command]
async fn inspect_media_asset_availability(
    state: State<'_, AppState>,
    request_id: u64,
    asset_ids: Vec<MediaAssetId>,
    verify_hash: bool,
    expected_epoch: u64,
    owner_id: String,
) -> Result<MediaAssetAvailabilityReport, String> {
    if verify_hash {
        return Err(
            "Verified availability requires start_media_asset_availability_operation followed by inspect_reserved_media_asset_availability"
                .to_string(),
        );
    }
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    let (authority, assets) =
        capture_media_asset_availability_inventory(&state, &owner_id, expected_epoch)?;
    let registry = Arc::clone(&state.media_asset_operations);
    let operation = registry.begin_for(
        request_id,
        owner_id.clone(),
        MediaAssetOperationPurpose::Availability,
    )?;
    run_media_asset_availability_inspection(
        &state,
        operation,
        authority,
        (assets, asset_ids, false),
        expected_epoch,
        &owner_id,
    )
    .await
}

/// Adopt a purpose-bound availability reservation and run the potentially long
/// verified inspection under its already-known cancellation identity.
#[tauri::command]
async fn inspect_reserved_media_asset_availability(
    state: State<'_, AppState>,
    request_id: u64,
    operation_generation: u64,
    asset_ids: Vec<MediaAssetId>,
    verify_hash: bool,
    expected_epoch: u64,
    owner_id: String,
) -> Result<MediaAssetAvailabilityReport, String> {
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    let (operation, reserved_authority) = state
        .media_asset_operations
        .adopt_reserved_availability(request_id, operation_generation, owner_id.clone())?;
    let (current_authority, assets) =
        capture_media_asset_availability_inventory(&state, &owner_id, expected_epoch)?;
    ensure_reserved_media_asset_authority_unchanged(&reserved_authority, &current_authority)?;
    run_media_asset_availability_inspection(
        &state,
        operation,
        reserved_authority,
        (assets, asset_ids, verify_hash),
        expected_epoch,
        &owner_id,
    )
    .await
}

/// Hash/probe a relink replacement under an already-owned operation guard,
/// recheck the authority, and store the prepared relink record. Shared by the
/// legacy `prepare_media_asset_relink_impl` (which allocates its own generation
/// with `begin`) and the staged `prepare_reserved_media_asset_relink` (which
/// adopts a slot the client reserved before hashing). The guard is moved in so
/// it drops — removing the active entry — exactly when preparation completes or
/// fails. `authority`/`original_asset` are captured by the caller so the reserved
/// path can fence them against its Start authority before any hashing.
#[allow(clippy::too_many_arguments)]
async fn run_prepared_media_asset_relink_batch(
    state: &AppState,
    operation: MediaAssetOperationGuard,
    asset_id: MediaAssetId,
    replacement_path: String,
    policy: MediaAssetRelinkPolicy,
    expected_epoch: u64,
    owner_id: &str,
    authority: MediaAssetPrepareAuthority,
    original_asset: MediaAssetSummary,
    legacy_operation: Option<&LegacyMediaAssetCompatibilityOperation>,
) -> Result<MediaAssetRelinkPrepareReport, String> {
    let registry = Arc::clone(&state.media_asset_operations);
    let handle = operation.handle();
    let request_id = handle.request_id;
    let cancel = operation.cancellation_flag();
    let admission = operation.admission();
    let worker_asset = original_asset.clone();
    let worker_cancel = Arc::clone(&cancel);
    let decision = tauri::async_runtime::spawn_blocking(move || {
        prepare_media_asset_relink_decision(
            &worker_asset,
            replacement_path,
            policy,
            worker_cancel.as_ref(),
        )
    })
    .await
    .map_err(|error| format!("Media asset relink prepare worker failed: {error}"))??;
    if operation.cancelled() {
        return Err("Media asset operation was cancelled".to_string());
    }
    let (current_authority, _) = capture_media_asset_relink_prepare_asset(
        state,
        asset_id,
        expected_epoch,
        owner_id,
        legacy_operation,
    )?;
    if current_authority != authority {
        return Err("Project changed while media asset relink was prepared; retry".to_string());
    }
    match decision {
        PreparedMediaAssetRelinkDecision::Outcome(outcome) => Ok(MediaAssetRelinkPrepareReport {
            request_id,
            operation_generation: handle.generation,
            prepared_relink_token: None,
            project_epoch: authority.epoch,
            project_revision: authority.revision,
            checkpoint_hash: authority.checkpoint_hash,
            outcome: Some(outcome),
        }),
        PreparedMediaAssetRelinkDecision::Ready {
            replacement,
            adopted_replacement,
            legacy_source_identity,
        } => {
            let token = registry.store_prepared_relink_from_active(
                &handle,
                owner_id,
                PreparedMediaAssetRelink {
                    request_id,
                    operation_generation: handle.generation,
                    owner_id: owner_id.to_string(),
                    asset_id,
                    authority: authority.clone(),
                    original_asset,
                    replacement: *replacement,
                    adopted_replacement,
                    legacy_source_identity,
                    cancel,
                    admission,
                    finalized_replacement_source: None,
                    finalized_legacy_source: None,
                    expires_at: Instant::now() + MEDIA_ASSET_PREPARED_IMPORT_TTL,
                },
            )?;
            Ok(MediaAssetRelinkPrepareReport {
                request_id,
                operation_generation: handle.generation,
                prepared_relink_token: Some(token),
                project_epoch: authority.epoch,
                project_revision: authority.revision,
                checkpoint_hash: authority.checkpoint_hash,
                outcome: None,
            })
        }
    }
}

async fn prepare_media_asset_relink_impl(
    state: &AppState,
    request_id: u64,
    asset_id: MediaAssetId,
    replacement_path: String,
    policy: MediaAssetRelinkPolicy,
    expected_epoch: u64,
    owner_id: String,
) -> Result<MediaAssetRelinkPrepareReport, String> {
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    let operation = state
        .media_asset_operations
        .begin(request_id, owner_id.clone())?;
    let (authority, original_asset) =
        capture_media_asset_relink_prepare_asset(state, asset_id, expected_epoch, &owner_id, None)?;
    run_prepared_media_asset_relink_batch(
        state,
        operation,
        asset_id,
        replacement_path,
        policy,
        expected_epoch,
        &owner_id,
        authority,
        original_asset,
        None,
    )
    .await
}

/// Staged relink preparation that adopts a slot reserved by
/// `start_media_asset_operation`, so relink hashing runs under a preannounced
/// generation an `AbortSignal` can cancel before the first hashed chunk — the
/// first-phase-cancellation seam the import staged path already has. Additive:
/// the legacy single-call `relink_media_asset` / `prepare_media_asset_relink`
/// entry points are unchanged.
async fn prepare_reserved_media_asset_relink_impl(
    state: &AppState,
    operation_identity: MediaAssetOperationIdentity,
    asset_id: MediaAssetId,
    replacement_path: String,
    policy: MediaAssetRelinkPolicy,
    context: MediaAssetRelinkPrepareContext<'_>,
) -> Result<MediaAssetRelinkPrepareReport, String> {
    let (request_id, operation_generation) = operation_identity;
    let MediaAssetRelinkPrepareContext {
        expected_epoch,
        owner_id,
        legacy_operation,
    } = context;
    let (operation, reserved_authority) = state.media_asset_operations.adopt_reserved(
        request_id,
        operation_generation,
        owner_id.to_string(),
    )?;
    // Capture the relink authority (and the exact original asset) and require it
    // still equals the exact A the client was told at Start. A same-epoch
    // revision/hash mutation between Start and Prepare is rejected before any
    // hashing/token/publication; the adopted `operation` guard drops on the early
    // return, releasing the slot. Epoch replacement is still rejected inside the
    // capture.
    let (authority, original_asset) = capture_media_asset_relink_prepare_asset(
        state,
        asset_id,
        expected_epoch,
        owner_id,
        legacy_operation,
    )?;
    ensure_reserved_media_asset_authority_unchanged(&reserved_authority, &authority)?;
    run_prepared_media_asset_relink_batch(
        state,
        operation,
        asset_id,
        replacement_path,
        policy,
        expected_epoch,
        owner_id,
        authority,
        original_asset,
        legacy_operation,
    )
    .await
}

#[tauri::command]
async fn prepare_reserved_media_asset_relink(
    state: State<'_, AppState>,
    args: FlatInvokeArgs<Value>,
) -> Result<MediaAssetRelinkPrepareReport, String> {
    read_flat_invoke_args!(args;
        request_id: u64 => "requestId",
        operation_generation: u64 => "operationGeneration",
        asset_id: MediaAssetId => "assetId",
        replacement_path: String => "replacementPath",
        policy: MediaAssetRelinkPolicy => "policy",
        expected_epoch: u64 => "expectedEpoch",
        owner_id: String => "ownerId",
    );
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    prepare_reserved_media_asset_relink_impl(
        &state,
        (request_id, operation_generation),
        asset_id,
        replacement_path,
        policy,
        MediaAssetRelinkPrepareContext {
            expected_epoch,
            owner_id: &owner_id,
            legacy_operation: None,
        },
    )
    .await
}

