/// Staged compatibility commit for a single File layer. New UI callers must
/// prepare and finalize the local bytes before opening the generic ticket.
#[tauri::command]
fn commit_prepared_video_file_layer(
    window: WebviewWindow,
    state: State<'_, AppState>,
    args: FlatInvokeArgs<Value>,
) -> Result<VideoLayerId, String> {
    read_flat_invoke_args!(args;
        label: String => "label",
        prepared_import_token: u64 => "preparedImportToken",
        request_id: u64 => "requestId",
        operation_generation: u64 => "operationGeneration",
        project_transaction_id: u64 => "projectTransactionId",
        expected_epoch: u64 => "expectedEpoch",
        owner_id: String => "ownerId",
    );
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    project_transaction_owner_binding_for_window(&state, window.label(), &owner_id)?;
    let label = normalize_video_layer_label(label)?;
    let receipt_key = media_asset_commit_receipt_key(
        MediaAssetCommitReceiptKind::Layers,
        prepared_import_token,
        request_id,
        operation_generation,
        project_transaction_id,
        &owner_id,
    );
    if let Some(MediaAssetCommitReceipt::Layers(layer_ids)) =
        state.media_asset_operations.commit_receipt(&receipt_key)
    {
        return layer_ids
            .into_iter()
            .next()
            .ok_or_else(|| "Video layer add published no layer".to_string());
    }
    let prepared = state.media_asset_operations.prepared_exact(
        prepared_import_token,
        request_id,
        operation_generation,
        &owner_id,
    )?;
    require_legacy_prepared_media_all_or_nothing(&prepared, "Video layer add")?;
    require_prepared_local_media_kind(&prepared.assets, VideoSourceKind::File, "Video layer add")?;
    let receipt = commit_prepared_media_asset_layers(
        &state,
        prepared_import_token,
        request_id,
        operation_generation,
        project_transaction_id,
        expected_epoch,
        &owner_id,
        vec![label],
        None,
        receipt_key,
        None,
    )?;
    media_asset_commit_receipt_layer_ids(&receipt)
        .into_iter()
        .next()
        .ok_or_else(|| "Video layer add published no layer".to_string())
}

/// Staged compatibility commit for the historical batch-layer affordance.
#[tauri::command]
fn commit_prepared_local_media_layers(
    window: WebviewWindow,
    state: State<'_, AppState>,
    args: FlatInvokeArgs<Value>,
) -> Result<Vec<VideoLayerId>, String> {
    read_flat_invoke_args!(args;
        kind: VideoSourceKind => "kind",
        prepared_import_token: u64 => "preparedImportToken",
        request_id: u64 => "requestId",
        operation_generation: u64 => "operationGeneration",
        project_transaction_id: u64 => "projectTransactionId",
        expected_epoch: u64 => "expectedEpoch",
        owner_id: String => "ownerId",
    );
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    project_transaction_owner_binding_for_window(&state, window.label(), &owner_id)?;
    if !matches!(kind, VideoSourceKind::File | VideoSourceKind::StillImage) {
        return Err("Batch media import supports video files and still images only".to_string());
    }
    let receipt_key = media_asset_commit_receipt_key(
        MediaAssetCommitReceiptKind::Layers,
        prepared_import_token,
        request_id,
        operation_generation,
        project_transaction_id,
        &owner_id,
    );
    if let Some(MediaAssetCommitReceipt::Layers(layer_ids)) =
        state.media_asset_operations.commit_receipt(&receipt_key)
    {
        return Ok(layer_ids);
    }
    let prepared = state.media_asset_operations.prepared_exact(
        prepared_import_token,
        request_id,
        operation_generation,
        &owner_id,
    )?;
    require_legacy_prepared_media_all_or_nothing(&prepared, "Batch media import")?;
    require_prepared_local_media_kind(&prepared.assets, kind, "Batch media import")?;
    let labels = prepared
        .assets
        .iter()
        .map(|asset| asset.label.clone())
        .collect();
    let receipt = commit_prepared_media_asset_layers(
        &state,
        prepared_import_token,
        request_id,
        operation_generation,
        project_transaction_id,
        expected_epoch,
        &owner_id,
        labels,
        None,
        receipt_key,
        None,
    )?;
    Ok(media_asset_commit_receipt_layer_ids(&receipt))
}

fn safe_first_run_vj_output(output_id: VideoOutputId) -> VideoOutputSummary {
    VideoOutputSummary {
        id: output_id,
        label: "VJ Program".to_string(),
        kind: VideoOutputKind::Display,
        enabled: false,
        composition_id: 1,
        fullscreen: false,
        monitor_id: Some(0),
        monitor_identity: None,
        width: 1920,
        height: 1080,
        endpoint_name: None,
        opacity: 1.0,
        blackout: true,
        mapping: VideoOutputMapping::default(),
    }
}

fn validate_bootstrap_vj_prepared_import(
    prepared: &PreparedMediaAssetImport,
    kind: VideoSourceKind,
) -> Result<(), String> {
    if kind != VideoSourceKind::File {
        return Err("First-run VJ setup requires local video files".to_string());
    }
    require_legacy_prepared_media_all_or_nothing(prepared, "First-run VJ setup")?;
    require_prepared_local_media_kind(
        &prepared.assets,
        VideoSourceKind::File,
        "First-run VJ setup",
    )
}

/// Staged first-run setup commit. The preflight has intentionally completed
/// before the generic transaction ticket exists.
#[tauri::command]
fn commit_prepared_bootstrap_vj_show(
    window: WebviewWindow,
    state: State<'_, AppState>,
    args: FlatInvokeArgs<Value>,
) -> Result<VjFirstRunSetupResult, String> {
    read_flat_invoke_args!(args;
        kind: VideoSourceKind => "kind",
        prepared_import_token: u64 => "preparedImportToken",
        request_id: u64 => "requestId",
        operation_generation: u64 => "operationGeneration",
        project_transaction_id: u64 => "projectTransactionId",
        expected_epoch: u64 => "expectedEpoch",
        owner_id: String => "ownerId",
    );
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    project_transaction_owner_binding_for_window(&state, window.label(), &owner_id)?;
    let receipt_key = media_asset_commit_receipt_key(
        MediaAssetCommitReceiptKind::Bootstrap,
        prepared_import_token,
        request_id,
        operation_generation,
        project_transaction_id,
        &owner_id,
    );
    // Check the receipt before allocating a fresh output ID so an exact retry
    // returns the original show's IDs rather than a new (unpublished) output.
    if let Some(MediaAssetCommitReceipt::Bootstrap(result)) =
        state.media_asset_operations.commit_receipt(&receipt_key)
    {
        return Ok(result);
    }
    let prepared = state.media_asset_operations.prepared_exact(
        prepared_import_token,
        request_id,
        operation_generation,
        &owner_id,
    )?;
    require_legacy_prepared_media_all_or_nothing(&prepared, "Still image layer add")?;
    validate_bootstrap_vj_prepared_import(&prepared, kind)?;
    ensure_video_output_backend_available(&VideoOutputKind::Display)?;
    let _first_run = state
        .vj_first_run
        .lock()
        .map_err(|_| "First-run VJ setup lock is unavailable".to_string())?;
    let output_id = state.engine.allocate_video_output_id();
    let composition_id: CompositionId = 1;
    let labels = prepared
        .assets
        .iter()
        .map(|asset| asset.label.clone())
        .collect();
    let receipt = commit_prepared_media_asset_layers(
        &state,
        prepared_import_token,
        request_id,
        operation_generation,
        project_transaction_id,
        expected_epoch,
        &owner_id,
        labels,
        Some(safe_first_run_vj_output(output_id)),
        receipt_key,
        Some((output_id, composition_id)),
    )?;
    // A duplicate that lost the single-flight race returns the first publisher's
    // terminal Bootstrap result — including its original output ID — so both
    // callers report the same show rather than this call's unpublished output ID.
    match receipt {
        MediaAssetCommitReceipt::Bootstrap(result) => Ok(result),
        other => Err(format!(
            "First-run VJ setup received an unexpected commit receipt: {other:?}"
        )),
    }
}

/// Staged compatibility commit for one StillImage layer.
#[tauri::command]
fn commit_prepared_still_image_layer(
    window: WebviewWindow,
    state: State<'_, AppState>,
    args: FlatInvokeArgs<Value>,
) -> Result<VideoLayerId, String> {
    read_flat_invoke_args!(args;
        label: String => "label",
        prepared_import_token: u64 => "preparedImportToken",
        request_id: u64 => "requestId",
        operation_generation: u64 => "operationGeneration",
        project_transaction_id: u64 => "projectTransactionId",
        expected_epoch: u64 => "expectedEpoch",
        owner_id: String => "ownerId",
    );
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    project_transaction_owner_binding_for_window(&state, window.label(), &owner_id)?;
    let label = normalize_video_layer_label(label)?;
    let receipt_key = media_asset_commit_receipt_key(
        MediaAssetCommitReceiptKind::Layers,
        prepared_import_token,
        request_id,
        operation_generation,
        project_transaction_id,
        &owner_id,
    );
    if let Some(MediaAssetCommitReceipt::Layers(layer_ids)) =
        state.media_asset_operations.commit_receipt(&receipt_key)
    {
        return layer_ids
            .into_iter()
            .next()
            .ok_or_else(|| "Still image layer add published no layer".to_string());
    }
    let prepared = state.media_asset_operations.prepared_exact(
        prepared_import_token,
        request_id,
        operation_generation,
        &owner_id,
    )?;
    require_prepared_local_media_kind(
        &prepared.assets,
        VideoSourceKind::StillImage,
        "Still image layer add",
    )?;
    let receipt = commit_prepared_media_asset_layers(
        &state,
        prepared_import_token,
        request_id,
        operation_generation,
        project_transaction_id,
        expected_epoch,
        &owner_id,
        vec![label],
        None,
        receipt_key,
        None,
    )?;
    media_asset_commit_receipt_layer_ids(&receipt)
        .into_iter()
        .next()
        .ok_or_else(|| "Still image layer add published no layer".to_string())
}

/// The legacy IPC's historic batch rule is all-or-nothing for invalid input,
/// while repeated paths are intentionally a successful first-wins no-op. The
/// staged preparer reports those two cases separately; make the compatibility
/// decision before Finalize/Published so no valid prefix can escape.
fn require_legacy_media_asset_compatibility_all_or_nothing(
    report: &MediaAssetImportReport,
    operation: &str,
) -> Result<(), String> {
    if report.failed > 0 {
        return Err(format!(
            "{operation} rejected {} failed input(s); no media was added",
            report.failed
        ));
    }
    Ok(())
}

/// One old IPC invocation is adapted to the same server-owned long-I/O and
/// authoritative short-publication boundary as new UI callers. There is no
/// renderer ticket and no pending generic project transaction while hashing or
/// finalizing; `commit_prepared_media_asset_layers_authoritative` owns history,
/// revision, and the definitive Published ACK.
async fn legacy_media_asset_compatibility_prepare_finalize_local_media(
    state: &AppState,
    operation: &LegacyMediaAssetCompatibilityOperation,
    kind: VideoSourceKind,
    paths: Vec<String>,
    history_label: &str,
) -> Result<u64, String> {
    let prepared = prepare_reserved_media_assets_impl(
        state,
        (operation.request_id, operation.operation_generation),
        kind,
        paths,
        operation.authority.epoch,
        &operation.owner_id,
        Some(operation),
    )
    .await?;
    require_legacy_media_asset_compatibility_all_or_nothing(&prepared, history_label)?;
    let prepared_import_token = prepared.prepared_import_token.ok_or_else(|| {
        format!("{history_label} prepared no unique local media file; no media was added")
    })?;
    let finalized = finalize_prepared_media_assets_impl(
        state,
        prepared_import_token,
        operation.request_id,
        operation.operation_generation,
        operation.authority.epoch,
        &operation.owner_id,
        Some(operation),
    )
    .await?;
    require_legacy_media_asset_compatibility_all_or_nothing(&finalized, history_label)?;
    Ok(prepared_import_token)
}

#[allow(clippy::too_many_arguments)]
async fn legacy_media_asset_compatibility_commit_layers(
    state: &AppState,
    window: &WebviewWindow,
    kind: VideoSourceKind,
    paths: Vec<String>,
    shape: MediaAssetAuthoritativeRequestShape,
    labels: Option<Vec<String>>,
    history_label: &str,
    bootstrap: bool,
) -> Result<MediaAssetAuthoritativeTerminalResult, String> {
    let operation = reserve_legacy_media_asset_compatibility_operation(state, window)?;
    let required_kind = kind.clone();
    let result = async {
        let prepared_import_token = legacy_media_asset_compatibility_prepare_finalize_local_media(
            state,
            &operation,
            kind,
            paths,
            history_label,
        )
        .await?;
        commit_prepared_media_asset_layers_authoritative(
            state,
            prepared_import_token,
            operation.request_id,
            operation.operation_generation,
            operation.authority.epoch,
            operation.authority.revision,
            operation.authority.checkpoint_hash.clone(),
            &operation.owner_id,
            shape,
            labels,
            required_kind,
            history_label,
            bootstrap,
            Some(&operation),
        )
    }
    .await;
    if result.is_err() {
        cancel_legacy_media_asset_compatibility_operation(state, &operation);
    }
    result
}

#[derive(Debug, Clone)]
struct LegacyMediaAssetRefreshTarget {
    asset_id: MediaAssetId,
    source: VideoSourceSummary,
}

/// Resolve the source from the catalog relationship rather than trusting a
/// mutable layer projection. A legacy row lacking the reference is rejected
/// fail-closed: raw `SetVideoLayerSource` is no longer allowed to invent it.
fn legacy_media_asset_refresh_target(
    snapshot: &EngineSnapshot,
    layer_id: VideoLayerId,
) -> Result<LegacyMediaAssetRefreshTarget, String> {
    let video = snapshot.authored_video.as_ref().unwrap_or(&snapshot.video);
    let layer = video
        .layers
        .iter()
        .find(|layer| layer.id == layer_id)
        .ok_or_else(|| format!("Video layer {layer_id} was not found"))?;
    let asset_id = layer.media_asset_id.ok_or_else(|| {
        format!(
            "Video layer {layer_id} has no media asset reference; refresh requires an acknowledged media asset update"
        )
    })?;
    let asset = video
        .media_assets
        .iter()
        .find(|asset| asset.id == asset_id)
        .ok_or_else(|| {
            format!("Media asset {asset_id} was not found for video layer {layer_id}")
        })?;
    if layer.source != asset.source {
        return Err(format!(
            "Video layer {layer_id} source diverged from media asset {asset_id}; refresh requires project repair"
        ));
    }
    if !matches!(
        asset.source.kind,
        VideoSourceKind::File | VideoSourceKind::StillImage
    ) {
        return Err("Live video inputs do not expose local file metadata".to_string());
    }
    if asset
        .source
        .path
        .as_deref()
        .is_none_or(|path| path.trim().is_empty())
    {
        return Err("Video layer local media source path is required".to_string());
    }
    Ok(LegacyMediaAssetRefreshTarget {
        asset_id,
        source: asset.source.clone(),
    })
}

fn legacy_media_asset_refresh_message(source: &VideoSourceSummary) -> Result<String, String> {
    match source.kind {
        VideoSourceKind::File => Ok(if source.metadata.is_some() {
            "Refreshed video file metadata".to_string()
        } else {
            "Refreshed video codec; ffprobe returned no stream metadata".to_string()
        }),
        VideoSourceKind::StillImage => Ok("Refreshed still image metadata".to_string()),
        VideoSourceKind::Camera
        | VideoSourceKind::ScreenCapture
        | VideoSourceKind::Ndi
        | VideoSourceKind::Spout
        | VideoSourceKind::Syphon => {
            Err("Live video inputs do not expose local file metadata".to_string())
        }
    }
}

/// Transitional wire-compatible route. The existing renderer still invokes
/// `{ label, path }`; the result remains a bare `VideoLayerId`, while the
/// implementation is the A1 hash/finalize/Published/history path.
#[tauri::command]
async fn add_video_file_layer(
    window: WebviewWindow,
    state: State<'_, AppState>,
    label: String,
    path: String,
) -> Result<VideoLayerId, String> {
    let label = normalize_video_layer_label(label)?;
    let shape = media_asset_authoritative_shape(
        MediaAssetAuthoritativeCommitKind::VideoFileLayer,
        &[&label],
    );
    match legacy_media_asset_compatibility_commit_layers(
        &state,
        &window,
        VideoSourceKind::File,
        vec![path],
        shape,
        Some(vec![label]),
        "Add video file layer",
        false,
    )
    .await?
    {
        MediaAssetAuthoritativeTerminalResult::Layers(result) if result.layer_ids.len() == 1 => {
            Ok(result.layer_ids[0])
        }
        MediaAssetAuthoritativeTerminalResult::Layers(_) => Err(
            "Authoritative video file layer add published an unexpected layer count".to_string(),
        ),
        MediaAssetAuthoritativeTerminalResult::Failure(failure) => Err(failure.message),
        other => Err(format!(
            "Authoritative video file layer add received an unexpected terminal result: {other:?}"
        )),
    }
}

#[cfg(test)]
fn prepare_legacy_local_media_layers(
    kind: VideoSourceKind,
    paths: Vec<String>,
) -> Result<Vec<(String, VideoSourceSummary)>, String> {
    const MAX_BATCH_MEDIA_FILES: usize = 64;
    if !matches!(kind, VideoSourceKind::File | VideoSourceKind::StillImage) {
        return Err("Batch media import supports video files and still images only".to_string());
    }
    if paths.is_empty() {
        return Err("Select at least one media file".to_string());
    }
    if paths.len() > MAX_BATCH_MEDIA_FILES {
        return Err(format!(
            "Batch media import is limited to {MAX_BATCH_MEDIA_FILES} files at a time"
        ));
    }
    let mut seen = HashSet::new();
    let mut prepared = Vec::new();
    for path in paths {
        let context = if kind == VideoSourceKind::File {
            "Video file"
        } else {
            "Still image"
        };
        let path = validate_existing_file_path(path, context)?;
        let dedupe_key = if cfg!(windows) {
            path.to_ascii_lowercase()
        } else {
            path.clone()
        };
        if !seen.insert(dedupe_key) {
            continue;
        }
        let label = Path::new(&path)
            .file_stem()
            .and_then(|value| value.to_str())
            .filter(|value| !value.trim().is_empty())
            .unwrap_or("Media")
            .to_string();
        let source = if kind == VideoSourceKind::File {
            let probe = video::probe_video_file_metadata(&path).ok();
            VideoSourceSummary {
                kind: VideoSourceKind::File,
                codec: probe
                    .as_ref()
                    .and_then(|probe| probe.codec.clone())
                    .or_else(|| video::infer_video_codec_from_path(&path)),
                metadata: probe.and_then(|probe| probe.metadata),
                path: Some(path),
                name: None,
            }
        } else {
            VideoSourceSummary {
                kind: VideoSourceKind::StillImage,
                metadata: video::probe_still_image_metadata(&path).ok(),
                path: Some(path),
                name: None,
                codec: None,
            }
        };
        prepared.push((normalize_video_layer_label(label)?, source));
    }
    if prepared.is_empty() {
        return Err("No unique media files were selected".to_string());
    }
    Ok(prepared)
}

