/// Run output-control mutations away from the Tauri event-loop thread. The
/// physical lane may create a native window, initialize a GPU surface, or
/// retire a renderer; none of those operations may synchronously join an
/// event-loop-affine worker while the UI is serving its window messages.
async fn execute_output_control_off_event_loop(
    app: tauri::AppHandle,
    window: WebviewWindow,
    operation_id: &'static str,
    request: OutputControlCommandRequestV2,
) -> OutputControlResponseV2 {
    let replay_request = request.clone();
    match tauri::async_runtime::spawn_blocking(move || {
        let state = app.state::<AppState>();
        let query_state = app.state::<ControlPlaneQueryState>();
        control_plane_runtime::execute_output_control_for_operation(
            &app,
            &window,
            &state,
            &query_state,
            operation_id,
            request,
        )
    })
    .await
    {
        Ok(response) => response,
        Err(_) => control_plane_runtime::output_control_executor_failure(&replay_request),
    }
}

async fn execute_output_lease_lifecycle_off_event_loop(
    app: tauri::AppHandle,
    window: WebviewWindow,
    operation_id: &'static str,
    request: OutputControlCommandRequestV2,
) -> OutputControlResponseV2 {
    let replay_request = request.clone();
    match tauri::async_runtime::spawn_blocking(move || {
        let state = app.state::<AppState>();
        let query_state = app.state::<ControlPlaneQueryState>();
        control_plane_runtime::execute_output_lease_lifecycle_for_operation(
            &app,
            &window,
            &state,
            &query_state,
            operation_id,
            request,
        )
    })
    .await
    {
        Ok(response) => response,
        Err(_) => control_plane_runtime::output_control_executor_failure(&replay_request),
    }
}

#[tauri::command]
async fn query_output_control_authority_v1(
    app: tauri::AppHandle,
    window: WebviewWindow,
) -> Result<OutputControlAuthorityBundleV1, String> {
    let window_label = window.label().to_string();
    tauri::async_runtime::spawn_blocking(move || {
        let state = app.state::<AppState>();
        let query_state = app.state::<ControlPlaneQueryState>();
        control_plane_runtime::issue_output_control_authority_for_window_label(
            &window_label,
            &state,
            &query_state,
        )
    })
    .await
    .map_err(|error| format!("Output control authority query worker failed: {error}"))?
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
struct Dsf2026ArtNetAcceptanceProbeStatusQueryV1 {
    operation_id: String,
    status: Dsf2026ArtNetAcceptanceProbeStatus,
}

/// Read only the fixed probe's durable one-shot status for the calling local
/// renderer.  It intentionally exposes no route or lease authority and takes
/// only the journal lock, so normal Art-Net/Spout and safety paths cannot be
/// blocked by this UI status refresh.
fn query_dsf2026_artnet_acceptance_probe_status_for_window(
    window_label: &str,
    state: &AppState,
) -> Result<Dsf2026ArtNetAcceptanceProbeStatusQueryV1, String> {
    state.ensure_window_authority_not_blocked(window_label)?;
    let journal = match state.output_lease_durable_receipts.try_lock() {
        Ok(journal) => journal,
        Err(TryLockError::WouldBlock) => {
            return Err("DSF2026 Art-Net probe status is busy".to_string())
        }
        Err(TryLockError::Poisoned(_)) => {
            return Err("DSF2026 Art-Net probe status journal lock was poisoned".to_string())
        }
    };
    Ok(Dsf2026ArtNetAcceptanceProbeStatusQueryV1 {
        operation_id: OUTPUT_DSF2026_ARTNET_ACCEPTANCE_PROBE_STATUS_QUERY_OPERATION_ID.to_string(),
        status: journal.dsf2026_artnet_acceptance_probe_status(),
    })
}

/// Read-only durable UI status for the fixed probe.  A status refresh cannot
