fn validate_operator_policy(policy: &OperatorPolicy) -> Result<(), String> {
    let credential = &policy.credential;
    if credential.scheme != OPERATOR_CREDENTIAL_SCHEME {
        return Err(format!(
            "Operator credential scheme must be {OPERATOR_CREDENTIAL_SCHEME}"
        ));
    }
    if !(OPERATOR_CREDENTIAL_MIN_ITERATIONS..=OPERATOR_CREDENTIAL_MAX_ITERATIONS)
        .contains(&credential.iterations)
    {
        return Err(format!(
            "Operator credential iterations must be from {OPERATOR_CREDENTIAL_MIN_ITERATIONS} to {OPERATOR_CREDENTIAL_MAX_ITERATIONS}"
        ));
    }
    let salt = base64::engine::general_purpose::STANDARD
        .decode(&credential.salt_b64)
        .map_err(|_| "Operator credential salt is not valid base64".to_string())?;
    if salt.len() < 16 || salt.len() > 64 {
        return Err("Operator credential salt must decode to 16-64 bytes".to_string());
    }
    let verifier = base64::engine::general_purpose::STANDARD
        .decode(&credential.verifier_b64)
        .map_err(|_| "Operator credential verifier is not valid base64".to_string())?;
    if verifier.len() != 32 {
        return Err("Operator credential verifier must decode to 32 bytes".to_string());
    }
    Ok(())
}

fn hmac_sha256(key: &[u8], data: &[u8]) -> [u8; 32] {
    const BLOCK_BYTES: usize = 64;
    let mut key_block = [0_u8; BLOCK_BYTES];
    if key.len() > BLOCK_BYTES {
        key_block[..32].copy_from_slice(&Sha256::digest(key));
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }
    let mut inner_pad = [0x36_u8; BLOCK_BYTES];
    let mut outer_pad = [0x5c_u8; BLOCK_BYTES];
    for index in 0..BLOCK_BYTES {
        inner_pad[index] ^= key_block[index];
        outer_pad[index] ^= key_block[index];
    }
    let mut inner = Sha256::new();
    inner.update(inner_pad);
    inner.update(data);
    let inner_digest = inner.finalize();
    let mut outer = Sha256::new();
    outer.update(outer_pad);
    outer.update(inner_digest);
    outer.finalize().into()
}

/// PBKDF2-HMAC-SHA256 for the project's fixed 32-byte Operator verifier. This
/// deliberately computes one RFC 8018 block; the stored verifier length is
/// already validated as exactly 32 bytes.
fn operator_pbkdf2_sha256(password: &[u8], salt: &[u8], iterations: u32) -> [u8; 32] {
    debug_assert!(iterations > 0);
    let mut first_input = Vec::with_capacity(salt.len() + 4);
    first_input.extend_from_slice(salt);
    first_input.extend_from_slice(&1_u32.to_be_bytes());
    let mut u = hmac_sha256(password, &first_input);
    let mut verifier = u;
    for _ in 1..iterations {
        u = hmac_sha256(password, &u);
        for (target, value) in verifier.iter_mut().zip(u) {
            *target ^= value;
        }
    }
    verifier
}

fn operator_password_matches_policy(
    policy: &OperatorPolicy,
    password: &[u8],
) -> Result<bool, String> {
    validate_operator_policy(policy)?;
    let salt = base64::engine::general_purpose::STANDARD
        .decode(&policy.credential.salt_b64)
        .map_err(|_| "Operator credential salt is not valid base64".to_string())?;
    let expected = base64::engine::general_purpose::STANDARD
        .decode(&policy.credential.verifier_b64)
        .map_err(|_| "Operator credential verifier is not valid base64".to_string())?;
    let actual = operator_pbkdf2_sha256(password, &salt, policy.credential.iterations);
    let mut difference = 0_u8;
    for (left, right) in actual.iter().zip(expected.iter()) {
        difference |= left ^ right;
    }
    Ok(difference == 0)
}

fn validate_operator_password_input(password: &str) -> Result<(), String> {
    // Match the existing Web Crypto policy creator's JavaScript `length`
    // contract (UTF-16 code units), including previously saved non-BMP passwords.
    if password.encode_utf16().count() < OPERATOR_PASSWORD_MIN_CHARACTERS
        || password.len() > OPERATOR_PASSWORD_MAX_BYTES
    {
        return Err(format!(
            "Operator password must contain at least {OPERATOR_PASSWORD_MIN_CHARACTERS} characters and at most {OPERATOR_PASSWORD_MAX_BYTES} UTF-8 bytes"
        ));
    }
    Ok(())
}

fn project_operator_session_for_policy<'a>(
    sessions: &'a mut HashMap<String, ProjectOperatorSession>,
    coordinator: &ProjectCoordinator,
    owner_id: &str,
) -> Option<&'a mut ProjectOperatorSession> {
    let Some(policy) = coordinator.ancillary.operator_policy.clone() else {
        sessions.remove(owner_id);
        return None;
    };
    let reset = sessions.get(owner_id).is_none_or(|session| {
        session.project_epoch != coordinator.epoch || session.policy != policy
    });
    if reset {
        sessions.insert(
            owner_id.to_string(),
            ProjectOperatorSession {
                project_epoch: coordinator.epoch,
                unlocked: !policy.lock_on_load,
                policy,
            },
        );
    }
    sessions.get_mut(owner_id)
}

/// Server-side Operator admission for backend-owned authoritative mutations.
/// Terminal receipt lookup intentionally happens before this check: a lock
/// engaged after B committed may not erase the caller's ability to learn that
/// definitive result. The check is repeated only on the not-yet-published path.
fn ensure_project_operator_authoritative_mutation_allowed(
    state: &AppState,
    coordinator: &ProjectCoordinator,
    owner_id: &str,
) -> Result<(), String> {
    let mut sessions = state
        .project_operator_sessions
        .lock()
        .map_err(|_| "Project operator session registry lock was poisoned".to_string())?;
    project_operator_sessions_allow_authoritative_mutation(&mut sessions, coordinator, owner_id)
}

fn project_operator_sessions_allow_authoritative_mutation(
    sessions: &mut HashMap<String, ProjectOperatorSession>,
    coordinator: &ProjectCoordinator,
    owner_id: &str,
) -> Result<(), String> {
    let Some(session) = project_operator_session_for_policy(sessions, coordinator, owner_id) else {
        return Ok(());
    };
    if session.unlocked {
        return Ok(());
    }
    let mode = match session.policy.lock_mode {
        OperatorLockMode::Full => "Full",
        OperatorLockMode::Partial => "Partial",
    };
    Err(format!(
        "Operator {mode} Lock blocks project mutations for this renderer session"
    ))
}

/// Runtime slot transport deliberately remains available during Partial Lock:
/// it neither changes authored bytes nor history. Full Lock remains an
/// operator safety fence for both authoring and performance commands.
fn ensure_project_operator_video_clip_slot_runtime_allowed(
    state: &AppState,
    coordinator: &ProjectCoordinator,
    owner_id: &str,
) -> Result<(), String> {
    let mut sessions = state
        .project_operator_sessions
        .lock()
        .map_err(|_| "Project operator session registry lock was poisoned".to_string())?;
    let Some(session) = project_operator_session_for_policy(&mut sessions, coordinator, owner_id)
    else {
        return Ok(());
    };
    if session.unlocked || session.policy.lock_mode == OperatorLockMode::Partial {
        return Ok(());
    }
    Err(
        "Operator Full Lock blocks video clip slot runtime commands for this renderer session"
            .to_string(),
    )
}

#[tauri::command]
fn lock_project_operator_session(
    window: WebviewWindow,
    state: State<'_, AppState>,
    owner_id: String,
) -> Result<OperatorLockMode, String> {
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    let _external_admission = lock_project_external_command_admission(&state)?;
    let coordinator = lock_project_coordinator(&state)?;
    project_transaction_owner_binding_for_window(&state, window.label(), &owner_id)?;
    let mut sessions = state
        .project_operator_sessions
        .lock()
        .map_err(|_| "Project operator session registry lock was poisoned".to_string())?;
    let session = project_operator_session_for_policy(&mut sessions, &coordinator, &owner_id)
        .ok_or_else(|| "Configure an Operator policy before locking this project".to_string())?;
    session.unlocked = false;
    Ok(session.policy.lock_mode)
}

#[tauri::command]
async fn unlock_project_operator_session(
    window: WebviewWindow,
    state: State<'_, AppState>,
    owner_id: String,
    password: String,
) -> Result<(), String> {
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    validate_operator_password_input(&password)?;
    let window_label = window.label().to_string();
    let (project_epoch, owner_incarnation, policy) = {
        let _external_admission = lock_project_external_command_admission(&state)?;
        let coordinator = lock_project_coordinator(&state)?;
        let owner_incarnation =
            project_transaction_owner_binding_for_window(&state, &window_label, &owner_id)?;
        let policy = coordinator
            .ancillary
            .operator_policy
            .clone()
            .ok_or_else(|| "This project has no Operator policy".to_string())?;
        validate_operator_policy(&policy)?;
        (coordinator.epoch, owner_incarnation, policy)
    };
    let verification_policy = policy.clone();
    let verified = tauri::async_runtime::spawn_blocking(move || {
        let mut password_bytes = password.into_bytes();
        let result = operator_password_matches_policy(&verification_policy, &password_bytes);
        password_bytes.fill(0);
        result
    })
    .await
    .map_err(|error| format!("Operator password verification worker failed: {error}"))??;
    if !verified {
        return Err("Operator password is incorrect".to_string());
    }

    // Password work is intentionally outside project locks. Revalidate the
    // exact policy and epoch before granting this owner an unlocked session.
    let _external_admission = lock_project_external_command_admission(&state)?;
    let coordinator = lock_project_coordinator(&state)?;
    let current_incarnation =
        project_transaction_owner_binding_for_window(&state, &window_label, &owner_id)?;
    if current_incarnation != owner_incarnation {
        return Err("Operator unlock belongs to a retired renderer incarnation".to_string());
    }
    if coordinator.epoch != project_epoch
        || coordinator.ancillary.operator_policy.as_ref() != Some(&policy)
    {
        return Err("Project Operator policy changed while the password was verified".to_string());
    }
    let mut sessions = state
        .project_operator_sessions
        .lock()
        .map_err(|_| "Project operator session registry lock was poisoned".to_string())?;
    sessions.insert(
        owner_id,
        ProjectOperatorSession {
            project_epoch,
            policy,
            unlocked: true,
        },
    );
    Ok(())
}

#[tauri::command]
fn get_operator_policy(state: State<'_, AppState>) -> Result<Option<OperatorPolicy>, String> {
    let coordinator = lock_project_coordinator(&state)?;
    Ok(coordinator.ancillary.operator_policy.clone())
}

#[tauri::command]
fn set_operator_policy(
    window: WebviewWindow,
    state: State<'_, AppState>,
    policy: OperatorPolicy,
    project_transaction_id: u64,
    expected_epoch: u64,
    owner_id: String,
) -> Result<(), String> {
    set_operator_policy_for_window_label(
        &state,
        window.label(),
        policy,
        project_transaction_id,
        expected_epoch,
        &owner_id,
    )
}

fn set_operator_policy_for_window_label(
    state: &AppState,
    window_label: &str,
    policy: OperatorPolicy,
    project_transaction_id: u64,
    expected_epoch: u64,
    owner_id: &str,
) -> Result<(), String> {
    validate_operator_policy(&policy)?;
    let (_external_admission, mut coordinator, _transaction_admission) =
        lock_renderer_ticketed_project_mutation(
            state,
            window_label,
            "set_operator_policy",
            project_transaction_id,
            expected_epoch,
            owner_id,
        )?;
    // Preflight the legacy compatibility mirror before producing a candidate;
    // after the authoritative assignment this path must not return an error.
    drop(
        state
            .operator_policy
            .lock()
            .map_err(|_| "Operator policy state lock was poisoned".to_string())?,
    );
    let mut candidate_ancillary = coordinator.ancillary.clone();
    candidate_ancillary.operator_policy = Some(policy);
    let prepared = prepare_direct_project_ancillary_mutation(
        state,
        &coordinator,
        state.engine.persistence_snapshot()?,
        candidate_ancillary,
    )?;
    commit_direct_project_ancillary_mutation_after_preflight(state, &mut coordinator, prepared);
    *state
        .operator_policy
        .lock()
        .unwrap_or_else(|poison| poison.into_inner()) =
        coordinator.ancillary.operator_policy.clone();
    Ok(())
}

#[tauri::command]
fn clear_operator_policy(
    window: WebviewWindow,
    state: State<'_, AppState>,
    project_transaction_id: u64,
    expected_epoch: u64,
    owner_id: String,
) -> Result<(), String> {
    clear_operator_policy_for_window_label(
        &state,
        window.label(),
        project_transaction_id,
        expected_epoch,
        &owner_id,
    )
}

fn clear_operator_policy_for_window_label(
    state: &AppState,
    window_label: &str,
    project_transaction_id: u64,
    expected_epoch: u64,
    owner_id: &str,
) -> Result<(), String> {
    let (_external_admission, mut coordinator, _transaction_admission) =
        lock_renderer_ticketed_project_mutation(
            state,
            window_label,
            "clear_operator_policy",
            project_transaction_id,
            expected_epoch,
            owner_id,
        )?;
    drop(
        state
            .operator_policy
            .lock()
            .map_err(|_| "Operator policy state lock was poisoned".to_string())?,
    );
    let mut candidate_ancillary = coordinator.ancillary.clone();
    candidate_ancillary.operator_policy = None;
    let prepared = prepare_direct_project_ancillary_mutation(
        state,
        &coordinator,
        state.engine.persistence_snapshot()?,
        candidate_ancillary,
    )?;
    commit_direct_project_ancillary_mutation_after_preflight(state, &mut coordinator, prepared);
    *state
        .operator_policy
        .lock()
        .unwrap_or_else(|poison| poison.into_inner()) = None;
    Ok(())
}

#[tauri::command]
fn load_user_template(
    window: WebviewWindow,
    state: State<'_, AppState>,
    owner_id: String,
    expected_epoch: u64,
    expected_revision: u64,
    expected_checkpoint_hash: String,
) -> Result<Option<UserTemplateLoadResult>, String> {
    let entry_owner_incarnation =
        project_transaction_owner_binding_for_window(&state, window.label(), &owner_id)?;
    let Some(path) = parented_file_dialog(&window)
        .add_filter("Syndocal User Template", &["sdctemplate"])
        .pick_file()
    else {
        return Ok(None);
    };
    validate_user_template_open_path(&path)?;
    let metadata = fs::metadata(&path).map_err(|error| error.to_string())?;
    if metadata.len() > USER_TEMPLATE_MAX_BYTES {
        return Err(format!(
            "User template is larger than the {} MiB safety limit",
            USER_TEMPLATE_MAX_BYTES / 1024 / 1024
        ));
    }
    let bytes = fs::read(&path).map_err(|error| error.to_string())?;
    let template: UserTemplateFile =
        serde_json::from_slice(&bytes).map_err(|error| error.to_string())?;
    let template = normalize_user_template_file(template)?;
    let UserTemplateFile {
        label,
        project,
        midi_mappings,
        osc_mappings,
        dmx_mappings,
        dj_track_triggers,
        ..
    } = template;
    let loaded = with_project_replacement_invocation(
        &state,
        window.label(),
        "load_user_template",
        owner_id,
        (
            Some(entry_owner_incarnation),
            expected_epoch,
            expected_revision,
            expected_checkpoint_hash,
        ),
        || {
            load_project_from_file_with_control_mappings_and_disposition(
                &state,
                // Ownership fencing controls effective output. Do not rewrite the
                // template's authored output intent: a later explicit Arm must be
                // able to restore the saved DMX/video configuration unchanged.
                project,
                ProjectControlMappings {
                    midi_mappings: midi_mappings.clone(),
                    osc_mappings: osc_mappings.clone(),
                    dmx_mappings: dmx_mappings.clone(),
                    dj_track_triggers: dj_track_triggers.clone(),
                    legacy_dj_transition_discarded: false,
                },
                format!("Template {label}"),
                None,
                ProjectAuthorityDisposition::UnsavedReplacement,
            )
        },
    )?;
    Ok(Some(UserTemplateLoadResult {
        path: path.to_string_lossy().to_string(),
        current_project_path: loaded.current_project_path.clone(),
        label,
        profiles: loaded.profiles,
        midi_mappings,
        osc_mappings,
        dmx_mappings,
        dj_track_triggers,
        warnings: loaded.warnings,
        project_epoch: loaded.project_epoch,
        project_revision: loaded.project_revision,
        checkpoint_hash: loaded.checkpoint_hash,
        history_generation: loaded.history_generation,
        authority_disposition_generation: loaded.authority_disposition_generation,
        authority_disposition: loaded.authority_disposition,
        authority: loaded.authority,
    }))
}

#[cfg(test)]
fn project_json_for_write(project: &ProjectFile) -> Result<String, String> {
    project_json_for_write_with_control_mappings(project, Vec::new(), Vec::new(), Vec::new())
}

#[cfg(test)]
fn project_json_for_write_with_control_mappings(
    project: &ProjectFile,
    midi_mappings: Vec<MidiControlMapping>,
    osc_mappings: Vec<OscControlMapping>,
    dmx_mappings: Vec<DmxControlMapping>,
) -> Result<String, String> {
    project_json_for_write_with_control_mappings_and_dj(
        project,
        midi_mappings,
        osc_mappings,
        dmx_mappings,
        Vec::new(),
    )
}

fn project_json_for_write_with_control_mappings_and_dj(
    project: &ProjectFile,
    midi_mappings: Vec<MidiControlMapping>,
    osc_mappings: Vec<OscControlMapping>,
    dmx_mappings: Vec<DmxControlMapping>,
    dj_track_triggers: Vec<protocol::DjTrackTriggerMapping>,
) -> Result<String, String> {
    let value = project_root_value_with_control_mappings_and_dj(
        project,
        midi_mappings,
        osc_mappings,
        dmx_mappings,
        dj_track_triggers,
    )?;
    let json = serde_json::to_string_pretty(&value).map_err(|error| error.to_string())?;
    if json.len() as u64 > PROJECT_FILE_MAX_BYTES {
        return Err(format!(
            "Project JSON is {} bytes; the limit is {PROJECT_FILE_MAX_BYTES} bytes",
            json.len()
        ));
    }
    Ok(json)
}

fn project_root_value_with_control_mappings_and_dj(
    project: &ProjectFile,
    midi_mappings: Vec<MidiControlMapping>,
    osc_mappings: Vec<OscControlMapping>,
    dmx_mappings: Vec<DmxControlMapping>,
    dj_track_triggers: Vec<protocol::DjTrackTriggerMapping>,
) -> Result<Value, String> {
    validate_project_file(project)?;
    let mappings = ProjectControlMappings {
        midi_mappings: validate_midi_control_mappings(midi_mappings)?,
        osc_mappings: validate_osc_control_mappings(osc_mappings)?,
        dmx_mappings: validate_dmx_control_mappings(dmx_mappings)?,
        dj_track_triggers: validate_dj_track_triggers(dj_track_triggers)?,
        legacy_dj_transition_discarded: false,
    };
    validate_dj_track_triggers_against_snapshot(&mappings.dj_track_triggers, &project.snapshot)?;
    let mut value = serde_json::to_value(project).map_err(|error| error.to_string())?;
    let root = value
        .as_object_mut()
        .ok_or_else(|| "Project root must be a JSON object".to_string())?;
    if !mappings.midi_mappings.is_empty() {
        root.insert(
            "midi_mappings".to_string(),
            serde_json::to_value(&mappings.midi_mappings).map_err(|error| error.to_string())?,
        );
    }
    if !mappings.osc_mappings.is_empty() {
        root.insert(
            "osc_mappings".to_string(),
            serde_json::to_value(&mappings.osc_mappings).map_err(|error| error.to_string())?,
        );
    }
    if !mappings.dmx_mappings.is_empty() {
        root.insert(
            "dmx_mappings".to_string(),
            serde_json::to_value(&mappings.dmx_mappings).map_err(|error| error.to_string())?,
        );
    }
    if !mappings.dj_track_triggers.is_empty() {
        root.insert(
            "dj_track_triggers".to_string(),
            serde_json::to_value(&mappings.dj_track_triggers).map_err(|error| error.to_string())?,
        );
    }
    Ok(value)
}

fn project_file_for_save_with_coordinator(
    state: &AppState,
    coordinator: &ProjectCoordinator,
) -> Result<ProjectFile, String> {
    Ok(project_file_for_save_from_parts(
        state.engine.persistence_snapshot()?,
        &coordinator.ancillary,
    ))
}

fn project_checkpoint_hash(
    project: &ProjectFile,
    mappings: &ProjectControlMappings,
) -> Result<String, String> {
    // Hash compact canonical root JSON, never the human-readable pretty file
    // bytes.  A formatting-only rewrite must not invalidate a navigation CAS.
    let root = project_root_value_with_control_mappings_and_dj(
        project,
        mappings.midi_mappings.clone(),
        mappings.osc_mappings.clone(),
        mappings.dmx_mappings.clone(),
        mappings.dj_track_triggers.clone(),
    )?;
    let canonical = serde_json::to_vec(&root).map_err(|error| error.to_string())?;
    let digest = Sha256::digest(canonical);
    Ok(digest.iter().map(|byte| format!("{byte:02x}")).collect())
}

fn project_checkpoint_for_coordinator(
    state: &AppState,
    coordinator: &ProjectCoordinator,
) -> Result<ProjectCheckpoint, String> {
    let project = project_file_for_save_with_coordinator(state, coordinator)?;
    let hash = project_checkpoint_hash(&project, &coordinator.mappings)?;
    Ok(ProjectCheckpoint {
        project,
        mappings: coordinator.mappings.clone(),
        epoch: coordinator.epoch,
        revision: coordinator.revision,
        hash,
    })
}

/// Capture the actual persistence surface at a coordinator boundary.  Engine
/// commands are intentionally available to live MIDI/OSC/DMX and remote paths,
/// so `checkpoint_hash` is a cache for UI/history tokens rather than the sole
/// authority.  Reconcile it from `persistence_snapshot` before deciding that a
/// save ticket or historic source is still current.
fn reconcile_project_checkpoint_for_coordinator(
    state: &AppState,
    coordinator: &mut ProjectCoordinator,
) -> Result<ProjectCheckpoint, String> {
    let mut checkpoint = project_checkpoint_for_coordinator(state, coordinator)?;
    reconcile_project_checkpoint_metadata(coordinator, &mut checkpoint)?;
    Ok(checkpoint)
}

/// Advance the authority revision when the canonical persistence image was
/// changed by an admitted external command. Kept separate from the engine
/// capture so the generation invariant has an SDK-free regression seam.
fn reconcile_project_checkpoint_metadata(
    coordinator: &mut ProjectCoordinator,
    checkpoint: &mut ProjectCheckpoint,
) -> Result<(), String> {
    // A live MIDI/OSC/DMX/remote command is allowed to alter the engine
    // persistence image outside a frontend transaction.  Its canonical hash
    // must never be published at the coordinator's old revision: that would
    // make an exact B token indistinguishable from A to the frontend.
    if checkpoint.hash != coordinator.checkpoint_hash {
        if !coordinator.history.pending.is_empty() {
            return Err(
                "Live project persistence changed while a project transaction was active; cancel or complete the transaction before reconciling authority"
                    .to_string(),
            );
        }
        let next_revision = checked_project_revision_after_mutation(coordinator)?;
        let next_history_generation = checked_project_history_generation_after_change(coordinator)?;
        let next_publication_generation =
            checked_project_authority_publication_generation_after_change(coordinator)?;
        coordinator.revision = next_revision;
        coordinator.checkpoint_hash = checkpoint.hash.clone();
        // A command admitted outside the transaction/history protocol is
        // intentionally non-Undoable. Both stacks name an older persistence
        // source, so leave no stale Undo/Redo CAS token visible to the UI.
        coordinator.history.undo.clear();
        coordinator.history.redo.clear();
        coordinator.history_generation = next_history_generation;
        commit_project_authority_publication_after_preflight(
            coordinator,
            next_publication_generation,
            ProjectAuthorityPublicationKind::Mutation,
        );
        checkpoint.revision = next_revision;
    } else {
        checkpoint.revision = coordinator.revision;
    }
    Ok(())
}

fn project_save_ticket_for_coordinator(
    state: &AppState,
    coordinator: &mut ProjectCoordinator,
) -> Result<ProjectSaveTicket, String> {
    ensure_no_pending_project_transaction(coordinator)?;
    let checkpoint = reconcile_project_checkpoint_for_coordinator(state, coordinator)?;
    Ok(ProjectSaveTicket {
        checkpoint,
        current_project_path: coordinator.ancillary.current_project_path.clone(),
        path_generation: coordinator.path_generation,
        authority_disposition_generation: coordinator.authority_disposition_generation,
        save_reservation_generation: None,
    })
}

fn project_publication_shape_hash_v1(
    request: &ProjectPublicationRequestV1,
) -> Result<String, String> {
    let bytes = serde_json::to_vec(request)
        .map_err(|error| format!("Unable to encode project publication shape: {error}"))?;
    Ok(sha256_hex(&bytes))
}

#[derive(Debug)]
enum BeginProjectPublicationV1 {
    New {
        ticket: Box<ProjectSaveTicket>,
        pending: PersistedProjectPublicationPendingV1,
    },
    Resume {
        ticket: Box<ProjectSaveTicket>,
        pending: PersistedProjectPublicationPendingV1,
    },
    Existing(Box<ProjectPublicationStatusV1>),
}

fn project_publication_request_key_matches(
    request: &ProjectPublicationRequestV1,
    other: &ProjectPublicationRequestV1,
) -> bool {
    request.origin_id == other.origin_id && request.request_id == other.request_id
}

fn project_publication_terminal_status_v1(
    terminal: &PersistedProjectPublicationTerminalV1,
    authority: Option<ProjectAuthorityBundle>,
) -> ProjectPublicationStatusV1 {
    ProjectPublicationStatusV1 {
        request: terminal.request.clone(),
        shape_hash: terminal.shape_hash.clone(),
        surface: terminal.surface,
        state: match terminal.outcome {
            ProjectPublicationTerminalOutcomeV1::Succeeded => "succeeded",
            ProjectPublicationTerminalOutcomeV1::Cancelled => "cancelled",
            ProjectPublicationTerminalOutcomeV1::Abandoned => "abandoned",
            ProjectPublicationTerminalOutcomeV1::Failed => "failed",
            ProjectPublicationTerminalOutcomeV1::Indeterminate => "indeterminate",
        }
        .to_string(),
        target_path: terminal.target_path.clone(),
        artifact_digest: terminal.artifact_digest.clone(),
        backup: terminal.backup.clone(),
        recovery_authority_serial: terminal.recovery_authority_serial,
        authority,
        error: terminal.error.clone(),
        warning: terminal.warning.clone(),
    }
}

fn project_publication_pending_status_v1(
    pending: &PersistedProjectPublicationPendingV1,
    recovery_authority_serial: u64,
) -> ProjectPublicationStatusV1 {
    ProjectPublicationStatusV1 {
        request: pending.request.clone(),
        shape_hash: pending.shape_hash.clone(),
        surface: pending.surface,
        state: match pending.phase {
            ProjectPublicationPendingPhaseV1::Reserved => "reserved",
            ProjectPublicationPendingPhaseV1::Selecting => "selecting",
            ProjectPublicationPendingPhaseV1::Selected => "selected",
            ProjectPublicationPendingPhaseV1::Prepared => "prepared",
        }
        .to_string(),
        target_path: pending
            .target_path
            .as_ref()
            .map(|path| path.to_string_lossy().to_string()),
        artifact_digest: pending.prepared_digest.clone(),
        backup: None,
        recovery_authority_serial,
        authority: None,
        error: pending.indeterminate_error.clone(),
        warning: None,
    }
}

fn publication_terminal_authority_if_current(
    state: &AppState,
    coordinator: &ProjectCoordinator,
    terminal: &PersistedProjectPublicationTerminalV1,
) -> Option<ProjectAuthorityBundle> {
    if !matches!(
        terminal.surface,
        ProjectPublicationSurfaceV1::Save | ProjectPublicationSurfaceV1::SaveAs
    ) {
        // Template and backup publication never adopt or mutate project
        // authority. Returning a coincidentally matching E/R/H bundle would
        // falsely describe them as project saves and violates the V1 receipt
        // invariant consumed by the renderer.
        return None;
    }
    let path_is_current = coordinator.authority_disposition
        == ProjectAuthorityDisposition::CleanAtPath
        && coordinator
            .ancillary
            .current_project_path
            .as_ref()
            .map(|path| path.to_string_lossy().to_string())
            == terminal.target_path;
    (terminal.outcome == ProjectPublicationTerminalOutcomeV1::Succeeded
        && coordinator.epoch == terminal.project_epoch
        && coordinator.revision == terminal.project_revision
        && coordinator.checkpoint_hash == terminal.checkpoint_hash
        && path_is_current)
        .then(|| project_authority_bundle_from_coordinator(state, coordinator))
}

fn begin_project_publication_v1(
    state: &AppState,
    coordinator: &mut ProjectCoordinator,
    journal_path: &Path,
    request: ProjectPublicationRequestV1,
    expected_surface: ProjectPublicationSurfaceV1,
) -> Result<BeginProjectPublicationV1, String> {
    let request = normalize_project_publication_request_v1(request)?;
    if request.surface != expected_surface {
        return Err("Project publication request was sent to the wrong surface".to_string());
    }
    let shape_hash = project_publication_shape_hash_v1(&request)?;
    let mut durable = load_project_recovery_authority_state_from_path(journal_path)?;
    if let Some(terminal) = durable
        .publication_journal
        .terminals
        .iter()
        .find(|terminal| project_publication_request_key_matches(&request, &terminal.request))
    {
        if terminal.shape_hash != shape_hash || terminal.surface != expected_surface {
            return Err(
                "Project publication request ID was already used with a different shape"
                    .to_string(),
            );
        }
        return Ok(BeginProjectPublicationV1::Existing(Box::new(
            project_publication_terminal_status_v1(
                terminal,
                publication_terminal_authority_if_current(state, coordinator, terminal),
            ),
        )));
    }
    if let Some(pending) = durable
        .publication_journal
        .pending
        .iter()
        .find(|pending| project_publication_request_key_matches(&request, &pending.request))
        .cloned()
    {
        if pending.shape_hash != shape_hash || pending.surface != expected_surface {
            return Err(
                "Project publication request ID was already used with a different shape"
                    .to_string(),
            );
        }
        if matches!(
            pending.phase,
            ProjectPublicationPendingPhaseV1::Selecting
                | ProjectPublicationPendingPhaseV1::Prepared
        ) {
            return Ok(BeginProjectPublicationV1::Existing(Box::new(
                project_publication_pending_status_v1(&pending, durable.serial),
            )));
        }
        let mut ticket = project_save_ticket_for_coordinator(state, coordinator)?;
        if ticket.checkpoint.epoch != pending.project_epoch
            || ticket.checkpoint.revision != pending.project_revision
            || ticket.checkpoint.hash != pending.checkpoint_hash
            || ticket.path_generation != pending.path_generation
            || ticket.authority_disposition_generation != pending.authority_disposition_generation
        {
            return Err(
                "Project authority changed before the pending publication could resume".to_string(),
            );
        }
        ticket.save_reservation_generation = Some(pending.reservation_generation);
        coordinator.latest_save_reservation_generation = coordinator
            .latest_save_reservation_generation
            .max(durable.publication_journal.latest_reservation_generation);
        coordinator.next_save_reservation_generation = coordinator
            .next_save_reservation_generation
            .max(durable.publication_journal.latest_reservation_generation);
        return Ok(BeginProjectPublicationV1::Resume {
            ticket: Box::new(ticket),
            pending,
        });
    }
    if durable.publication_journal.pending.len() >= MAX_PROJECT_PUBLICATION_PENDING
        || durable
            .publication_journal
            .pending
            .len()
            .checked_add(durable.publication_journal.terminals.len())
            .is_none_or(|count| count >= MAX_PROJECT_PUBLICATION_TERMINALS)
    {
        return Err(
            "Project publication receipt capacity is full; acknowledge completed publications or abandon an unresolved request"
                .to_string(),
        );
    }
    if durable
        .publication_journal
        .pending
        .iter()
        .any(|pending| pending.request.origin_id == request.origin_id)
        || durable
            .publication_journal
            .terminals
            .iter()
            .any(|terminal| terminal.request.origin_id == request.origin_id)
    {
        return Err(
            "Project publication origin already has an unresolved request; query and acknowledge or abandon it before beginning the next request"
                .to_string(),
        );
    }
    let origin_index = durable
        .publication_journal
        .origins
        .iter()
        .position(|origin| origin.origin_id == request.origin_id);
    match origin_index {
        Some(index) => {
            let expected = durable.publication_journal.origins[index]
                .high_water_request_id
                .checked_add(1)
                .filter(|value| *value <= VIDEO_CLIP_RUNTIME_GENERATION_MAX)
                .ok_or_else(|| {
                    "Project publication request sequence is exhausted; create a new renderer origin"
                        .to_string()
                })?;
            if request.request_id != expected {
                return Err(format!(
                    "Project publication request sequence must be {expected}, received {}",
                    request.request_id
                ));
            }
        }
        None => {
            if durable.publication_journal.origins.len() >= MAX_PROJECT_PUBLICATION_ORIGINS {
                return Err("Project publication origin capacity is full".to_string());
            }
            if request.request_id != 1 {
                return Err(
                    "A new project publication origin must begin with request ID 1".to_string(),
                );
            }
        }
    }
    let mut ticket = project_save_ticket_for_coordinator(state, coordinator)?;
    if ticket.checkpoint.epoch != request.expected_project_epoch
        || ticket.checkpoint.revision != request.expected_project_revision
        || ticket.checkpoint.hash != request.expected_checkpoint_hash
        || ticket.checkpoint.hash != request.mapping_authority_hash
    {
        return Err(
            "Project authority or mappings changed before publication reservation".to_string(),
        );
    }
    let authoritative_source_path = ticket
        .current_project_path
        .as_ref()
        .map(|path| path.to_string_lossy().to_string());
    if request.source_path.is_some() && request.source_path != authoritative_source_path {
        return Err("Project publication source path is stale".to_string());
    }
    let reservation_generation = durable
        .publication_journal
        .latest_reservation_generation
        .max(coordinator.latest_save_reservation_generation)
        .checked_add(1)
        .ok_or_else(|| {
            "Project publication reservation space is exhausted; restart Syndocal".to_string()
        })?;
    ticket.save_reservation_generation = Some(reservation_generation);
    let pending = PersistedProjectPublicationPendingV1 {
        request: request.clone(),
        shape_hash,
        surface: expected_surface,
        project_epoch: ticket.checkpoint.epoch,
        project_revision: ticket.checkpoint.revision,
        checkpoint_hash: ticket.checkpoint.hash.clone(),
        path_generation: ticket.path_generation,
        authority_disposition_generation: ticket.authority_disposition_generation,
        recovery_authority_serial_before: coordinator.recovery_authority_serial,
        expected_recovery_authority_serial_after: matches!(
            expected_surface,
            ProjectPublicationSurfaceV1::Save | ProjectPublicationSurfaceV1::SaveAs
        )
        .then(|| {
            coordinator
                .recovery_authority_serial
                .checked_add(1)
                .ok_or_else(|| {
                    "Project recovery authority serial is exhausted; restart Syndocal".to_string()
                })
        })
        .transpose()?,
        reservation_generation,
        source_path: request.source_path.clone(),
        reason: request.reason.clone(),
        phase: ProjectPublicationPendingPhaseV1::Reserved,
        target_path: None,
        staging_path: None,
        prepared_digest: None,
        indeterminate_error: None,
    };
    let mut candidate = durable.publication_journal.clone();
    match origin_index {
        Some(index) => candidate.origins[index].high_water_request_id = request.request_id,
        None => candidate.origins.push(PersistedProjectPublicationOriginV1 {
            origin_id: request.origin_id.clone(),
            high_water_request_id: request.request_id,
            acknowledged_request_id: 0,
            acknowledged_shape_hash: None,
        }),
    }
    candidate.latest_reservation_generation = reservation_generation;
    candidate.pending.push(pending.clone());
    validate_project_publication_journal_v1(&candidate)?;
    durable.publication_journal = candidate;
    persist_project_recovery_authority_state_to_path(journal_path, &durable)?;
    coordinator.next_save_reservation_generation = reservation_generation;
    coordinator.latest_save_reservation_generation = reservation_generation;
    Ok(BeginProjectPublicationV1::New {
        ticket: Box::new(ticket),
        pending,
    })
}

fn persist_project_publication_target_v1(
    journal_path: &Path,
    request: &ProjectPublicationRequestV1,
    shape_hash: &str,
    target_path: &Path,
    allow_reserved: bool,
) -> Result<PersistedProjectPublicationPendingV1, String> {
    let mut durable = load_project_recovery_authority_state_from_path(journal_path)?;
    let pending = durable
        .publication_journal
        .pending
        .iter_mut()
        .find(|pending| project_publication_request_key_matches(request, &pending.request))
        .ok_or_else(|| "Project publication request is no longer pending".to_string())?;
    if pending.shape_hash != shape_hash {
        return Err(
            "Project publication request shape changed before target selection".to_string(),
        );
    }
    if pending.reservation_generation != durable.publication_journal.latest_reservation_generation {
        return Err("A newer project publication superseded this target selection".to_string());
    }
    if pending.phase != ProjectPublicationPendingPhaseV1::Selecting
        && !(allow_reserved && pending.phase == ProjectPublicationPendingPhaseV1::Reserved)
    {
        if pending.target_path.as_deref() == Some(target_path) {
            return Ok(pending.clone());
        }
        return Err("Project publication request already selected a different target".to_string());
    }
    pending.phase = ProjectPublicationPendingPhaseV1::Selected;
    pending.target_path = Some(target_path.to_path_buf());
    let result = pending.clone();
    persist_project_recovery_authority_state_to_path(journal_path, &durable)?;
    Ok(result)
}

fn persist_project_publication_selecting_v1(
    journal_path: &Path,
    request: &ProjectPublicationRequestV1,
    shape_hash: &str,
) -> Result<bool, String> {
    let mut durable = load_project_recovery_authority_state_from_path(journal_path)?;
    let pending = durable
        .publication_journal
        .pending
        .iter_mut()
        .find(|pending| project_publication_request_key_matches(request, &pending.request))
        .ok_or_else(|| "Project publication request is no longer pending".to_string())?;
    if pending.shape_hash != shape_hash {
        return Err("Project publication request shape changed before dialog".to_string());
    }
    if pending.reservation_generation != durable.publication_journal.latest_reservation_generation {
        return Err("A newer project publication superseded this target selection".to_string());
    }
    match pending.phase {
        ProjectPublicationPendingPhaseV1::Reserved => {
            pending.phase = ProjectPublicationPendingPhaseV1::Selecting;
            persist_project_recovery_authority_state_to_path(journal_path, &durable)?;
            Ok(true)
        }
        ProjectPublicationPendingPhaseV1::Selecting => Ok(false),
        ProjectPublicationPendingPhaseV1::Selected | ProjectPublicationPendingPhaseV1::Prepared => {
            Ok(false)
        }
    }
}

fn persist_project_publication_staging_v1(
    journal_path: &Path,
    request: &ProjectPublicationRequestV1,
    shape_hash: &str,
    target_path: &Path,
    staging_path: &Path,
) -> Result<PersistedProjectPublicationPendingV1, String> {
    let mut durable = load_project_recovery_authority_state_from_path(journal_path)?;
    let pending = durable
        .publication_journal
        .pending
        .iter_mut()
        .find(|pending| project_publication_request_key_matches(request, &pending.request))
        .ok_or_else(|| "Project publication request is no longer pending".to_string())?;
    if pending.shape_hash != shape_hash || pending.target_path.as_deref() != Some(target_path) {
        return Err("Project publication target changed before staging".to_string());
    }
    if pending.reservation_generation != durable.publication_journal.latest_reservation_generation {
        return Err("A newer project publication superseded this staging reservation".to_string());
    }
    if let Some(current) = pending.staging_path.as_deref() {
        if current == staging_path {
            return Ok(pending.clone());
        }
        return Err("Project publication request already reserved different staging".to_string());
    }
    if pending.phase != ProjectPublicationPendingPhaseV1::Selected {
        return Err("Project publication target is not ready for staging".to_string());
    }
    pending.staging_path = Some(staging_path.to_path_buf());
    let result = pending.clone();
    persist_project_recovery_authority_state_to_path(journal_path, &durable)?;
    Ok(result)
}

fn persist_project_publication_prepared_digest_v1(
    journal_path: &Path,
    request: &ProjectPublicationRequestV1,
    shape_hash: &str,
    target_path: &Path,
    temporary_path: &Path,
    prepared_digest: &str,
) -> Result<PersistedProjectPublicationPendingV1, String> {
    validate_project_publication_shape_hash(prepared_digest)?;
    let mut durable = load_project_recovery_authority_state_from_path(journal_path)?;
    let pending = durable
        .publication_journal
        .pending
        .iter_mut()
        .find(|pending| project_publication_request_key_matches(request, &pending.request))
        .ok_or_else(|| "Project publication request is no longer pending".to_string())?;
    if pending.shape_hash != shape_hash || pending.target_path.as_deref() != Some(target_path) {
        return Err("Project publication target changed before preparation".to_string());
    }
    if pending.staging_path.as_deref() != Some(temporary_path) {
        return Err("Project publication staging changed before preparation".to_string());
    }
    if pending.reservation_generation != durable.publication_journal.latest_reservation_generation {
        return Err("A newer project publication superseded this prepared file".to_string());
    }
    if pending.phase == ProjectPublicationPendingPhaseV1::Prepared {
        if pending.prepared_digest.as_deref() == Some(prepared_digest) {
            return Ok(pending.clone());
        }
        return Err("Project publication request already prepared different bytes".to_string());
    }
    if pending.phase != ProjectPublicationPendingPhaseV1::Selected {
        return Err("Project publication target has not been selected".to_string());
    }
    pending.phase = ProjectPublicationPendingPhaseV1::Prepared;
    pending.prepared_digest = Some(prepared_digest.to_string());
    let result = pending.clone();
    persist_project_recovery_authority_state_to_path(journal_path, &durable)?;
    Ok(result)
}

struct ProjectPublicationTerminalCommitV1 {
    outcome: ProjectPublicationTerminalOutcomeV1,
    target_path: Option<String>,
    artifact_digest: Option<String>,
    backup: Option<ProjectBackupSummary>,
    recovery_authority_serial: u64,
    error: Option<String>,
    warning: Option<String>,
}

fn persist_project_publication_terminal_v1(
    journal_path: &Path,
    request: &ProjectPublicationRequestV1,
    shape_hash: &str,
    commit: ProjectPublicationTerminalCommitV1,
) -> Result<PersistedProjectPublicationTerminalV1, String> {
    let mut durable = load_project_recovery_authority_state_from_path(journal_path)?;
    if let Some(terminal) = durable
        .publication_journal
        .terminals
        .iter()
        .find(|terminal| project_publication_request_key_matches(request, &terminal.request))
    {
        if terminal.shape_hash == shape_hash
            && terminal.outcome == commit.outcome
            && terminal.target_path == commit.target_path
            && terminal.artifact_digest == commit.artifact_digest
            && terminal.backup == commit.backup
            && terminal.recovery_authority_serial == commit.recovery_authority_serial
            && terminal.error == commit.error
            && terminal.warning == commit.warning
        {
            return Ok(terminal.clone());
        }
        return Err(
            "Project publication terminal receipt conflicts with durable truth".to_string(),
        );
    }
    let index = durable
        .publication_journal
        .pending
        .iter()
        .position(|pending| project_publication_request_key_matches(request, &pending.request))
        .ok_or_else(|| "Project publication request is no longer pending".to_string())?;
    let pending = durable.publication_journal.pending[index].clone();
    if pending.shape_hash != shape_hash {
        return Err("Project publication request shape changed before terminal commit".to_string());
    }
    let terminal = PersistedProjectPublicationTerminalV1 {
        request: request.clone(),
        shape_hash: shape_hash.to_string(),
        surface: pending.surface,
        outcome: commit.outcome,
        project_epoch: pending.project_epoch,
        project_revision: pending.project_revision,
        checkpoint_hash: pending.checkpoint_hash,
        target_path: commit.target_path,
        artifact_digest: commit.artifact_digest,
        backup: commit.backup,
        recovery_authority_serial: commit.recovery_authority_serial,
        error: commit.error,
        warning: commit.warning,
    };
    durable.publication_journal.pending.remove(index);
    durable.publication_journal.terminals.push(terminal.clone());
    persist_project_recovery_authority_state_to_path(journal_path, &durable)?;
    Ok(terminal)
}

fn mark_project_publication_indeterminate_v1(
    journal_path: &Path,
    request: &ProjectPublicationRequestV1,
    shape_hash: &str,
    error: String,
) -> Result<(), String> {
    let mut durable = load_project_recovery_authority_state_from_path(journal_path)?;
    let pending = durable
        .publication_journal
        .pending
        .iter_mut()
        .find(|pending| project_publication_request_key_matches(request, &pending.request))
        .ok_or_else(|| "Project publication request is no longer pending".to_string())?;
    if pending.shape_hash != shape_hash
        || pending.phase != ProjectPublicationPendingPhaseV1::Prepared
    {
        return Err("Only the exact prepared publication may become indeterminate".to_string());
    }
    pending.indeterminate_error = Some(error);
    persist_project_recovery_authority_state_to_path(journal_path, &durable)
}

fn project_publication_success_backup_summary(
    surface: ProjectPublicationSurfaceV1,
    target: &Path,
) -> Result<Option<ProjectBackupSummary>, String> {
    if surface != ProjectPublicationSurfaceV1::Backup {
        return Ok(None);
    }
    let backup = read_project_backup(target)?;
    let bytes = fs::metadata(target)
        .map_err(|error| format!("Unable to inspect published backup: {error}"))?
        .len();
    Ok(Some(ProjectBackupSummary {
        id: backup.id,
        created_at_unix_ms: backup.created_at_unix_ms,
        source_path: backup.source_path,
        reason: backup.reason,
        bytes,
    }))
}

#[derive(Debug, Clone)]
struct PreparedProjectPublicationReconcilePlanV1 {
    pending: PersistedProjectPublicationPendingV1,
    recovery_authority_serial: u64,
}

#[derive(Debug)]
enum ProjectPublicationLookupV1 {
    Missing,
    Status(Box<ProjectPublicationStatusV1>),
    Prepared(Box<PreparedProjectPublicationReconcilePlanV1>),
}

#[derive(Debug)]
struct PreparedProjectPublicationObservationV1 {
    actual_digest: Result<Option<String>, String>,
    backup: Result<Option<ProjectBackupSummary>, String>,
}

fn snapshot_project_publication_lookup_v1(
    state: &AppState,
    coordinator: &ProjectCoordinator,
    journal_path: &Path,
    request: &ProjectPublicationRequestV1,
    shape_hash: &str,
) -> Result<ProjectPublicationLookupV1, String> {
    let durable = load_project_recovery_authority_state_from_path(journal_path)?;
    if let Some(terminal) = durable
        .publication_journal
        .terminals
        .iter()
        .find(|terminal| project_publication_request_key_matches(request, &terminal.request))
    {
        if terminal.shape_hash != shape_hash {
            return Err(
                "Project publication request ID was already used with a different shape"
                    .to_string(),
            );
        }
        return Ok(ProjectPublicationLookupV1::Status(Box::new(
            project_publication_terminal_status_v1(
                terminal,
                publication_terminal_authority_if_current(state, coordinator, terminal),
            ),
        )));
    }
    let Some(pending) = durable
        .publication_journal
        .pending
        .iter()
        .find(|pending| project_publication_request_key_matches(request, &pending.request))
        .cloned()
    else {
        return Ok(ProjectPublicationLookupV1::Missing);
    };
    if pending.shape_hash != shape_hash {
        return Err(
            "Project publication request ID was already used with a different shape".to_string(),
        );
    }
    if pending.phase == ProjectPublicationPendingPhaseV1::Prepared {
        return Ok(ProjectPublicationLookupV1::Prepared(Box::new(
            PreparedProjectPublicationReconcilePlanV1 {
                pending,
                recovery_authority_serial: durable.serial,
            },
        )));
    }
    Ok(ProjectPublicationLookupV1::Status(Box::new(
        project_publication_pending_status_v1(&pending, durable.serial),
    )))
}

fn observe_prepared_project_publication_v1(
    plan: &PreparedProjectPublicationReconcilePlanV1,
) -> PreparedProjectPublicationObservationV1 {
    let target = plan
        .pending
        .target_path
        .as_deref()
        .expect("validated prepared project publication has a target");
    let actual_digest = strong_target_file_digest(target);
    let backup = match &actual_digest {
        Ok(Some(actual)) if plan.pending.prepared_digest.as_deref() == Some(actual.as_str()) => {
            project_publication_success_backup_summary(plan.pending.surface, target)
        }
        Ok(_) => Ok(None),
        Err(error) => Err(error.clone()),
    };
    PreparedProjectPublicationObservationV1 {
        actual_digest,
        backup,
    }
}

fn prepared_project_publication_has_durable_ownership_witness_v1(
    pending: &PersistedProjectPublicationPendingV1,
    durable: &PersistedProjectRecoveryAuthorityState,
) -> bool {
    pending
        .expected_recovery_authority_serial_after
        .is_none_or(|expected_serial| {
            durable.serial == expected_serial
                && durable.last_transition == ProjectRecoveryAuthorityTransition::CleanSave
        })
}

fn prepared_project_publication_observation_will_terminalize_v1(
    journal_path: &Path,
    plan: &PreparedProjectPublicationReconcilePlanV1,
    observation: &PreparedProjectPublicationObservationV1,
) -> Result<bool, String> {
    let durable = load_project_recovery_authority_state_from_path(journal_path)?;
    if durable
        .publication_journal
        .terminals
        .iter()
        .any(|terminal| {
            project_publication_request_key_matches(&plan.pending.request, &terminal.request)
        })
    {
        return Ok(false);
    }
    let Some(current) = durable.publication_journal.pending.iter().find(|pending| {
        project_publication_request_key_matches(&plan.pending.request, &pending.request)
    }) else {
        return Ok(false);
    };
    if current != &plan.pending || durable.serial != plan.recovery_authority_serial {
        return Ok(false);
    }
    let expected_digest = current
        .prepared_digest
        .as_deref()
        .ok_or_else(|| "Prepared project publication is missing its digest".to_string())?;
    if !prepared_project_publication_has_durable_ownership_witness_v1(current, &durable) {
        return Ok(durable.pending_clean_save.is_none());
    }
    Ok(match &observation.actual_digest {
        Ok(Some(actual)) if actual == expected_digest => observation.backup.is_ok(),
        Ok(_) => true,
        Err(_) => false,
    })
}

fn claim_prepared_project_publication_reconciliation_v1<'a>(
    state: &'a AppState,
    plan: &PreparedProjectPublicationReconcilePlanV1,
) -> Result<ProjectPublicationReconcileClaimGuardV1<'a>, String> {
    let claim = ProjectPublicationReconcileClaimV1 {
        origin_id: plan.pending.request.origin_id.clone(),
        request_id: plan.pending.request.request_id,
        shape_hash: plan.pending.shape_hash.clone(),
        recovery_authority_serial: plan.recovery_authority_serial,
        reservation_generation: plan.pending.reservation_generation,
    };
    let mut slot = state
        .project_publication_reconcile_claim
        .lock()
        .map_err(|_| "Project publication reconciliation claim was poisoned".to_string())?;
    if slot.is_some() {
        return Err(
            "Another project publication receipt reconciliation is already active; retry"
                .to_string(),
        );
    }
    *slot = Some(claim.clone());
    drop(slot);
    Ok(ProjectPublicationReconcileClaimGuardV1 {
        slot: &state.project_publication_reconcile_claim,
        claim,
    })
}

fn ensure_no_project_publication_reconciliation_v1(state: &AppState) -> Result<(), String> {
    if state
        .project_publication_reconcile_claim
        .lock()
        .map_err(|_| "Project publication reconciliation claim was poisoned".to_string())?
        .is_some()
    {
        return Err(
            "Project publication receipt reconciliation is active; retry publication".to_string(),
        );
    }
    Ok(())
}

fn commit_prepared_project_publication_observation_v1(
    state: &AppState,
    coordinator: &mut ProjectCoordinator,
    journal_path: &Path,
    plan: &PreparedProjectPublicationReconcilePlanV1,
    observation: PreparedProjectPublicationObservationV1,
) -> Result<ProjectPublicationStatusV1, String> {
    let durable = load_project_recovery_authority_state_from_path(journal_path)?;
    if let Some(terminal) = durable
        .publication_journal
        .terminals
        .iter()
        .find(|terminal| {
            project_publication_request_key_matches(&plan.pending.request, &terminal.request)
        })
    {
        if terminal.shape_hash != plan.pending.shape_hash {
            return Err(
                "Project publication request ID was already used with a different shape"
                    .to_string(),
            );
        }
        return Ok(project_publication_terminal_status_v1(
            terminal,
            publication_terminal_authority_if_current(state, coordinator, terminal),
        ));
    }
    let Some(current) = durable.publication_journal.pending.iter().find(|pending| {
        project_publication_request_key_matches(&plan.pending.request, &pending.request)
    }) else {
        return Err(
            "Project publication request changed while its target was inspected".to_string(),
        );
    };
    if current != &plan.pending || durable.serial != plan.recovery_authority_serial {
        return Ok(project_publication_pending_status_v1(
            current,
            durable.serial,
        ));
    }
    let expected_digest = current
        .prepared_digest
        .as_deref()
        .ok_or_else(|| "Prepared project publication is missing its digest".to_string())?;
    if !prepared_project_publication_has_durable_ownership_witness_v1(current, &durable) {
        // Exact target bytes alone cannot prove that this request replaced a
        // pre-existing identical Save target. CleanSave's durable serial is
        // the ownership witness for Save/Save As reconciliation.
        if durable.pending_clean_save.is_some() {
            return Ok(project_publication_pending_status_v1(
                current,
                durable.serial,
            ));
        }
        let terminal = persist_project_publication_terminal_v1(
            journal_path,
            &current.request,
            &current.shape_hash,
            ProjectPublicationTerminalCommitV1 {
                outcome: ProjectPublicationTerminalOutcomeV1::Failed,
                target_path: None,
                artifact_digest: None,
                backup: None,
                recovery_authority_serial: durable.serial,
                error: Some(
                    "Prepared Save did not publish its durable CleanSave ownership witness"
                        .to_string(),
                ),
                warning: None,
            },
        )?;
        refresh_project_publication_fault_latch_v1(state, journal_path)?;
        return Ok(project_publication_terminal_status_v1(&terminal, None));
    }
    match observation.actual_digest {
        Ok(Some(actual)) if actual == expected_digest => {
            let backup = observation.backup?;
            let target = current
                .target_path
                .as_deref()
                .ok_or_else(|| "Prepared project publication is missing its target".to_string())?;
            let restore_save_effects = matches!(
                current.surface,
                ProjectPublicationSurfaceV1::Save | ProjectPublicationSurfaceV1::SaveAs
            ) && coordinator.epoch == current.project_epoch
                && coordinator.revision == current.project_revision
                && coordinator.checkpoint_hash == current.checkpoint_hash
                && coordinator.path_generation == current.path_generation
                && coordinator.authority_disposition_generation
                    == current.authority_disposition_generation;
            let restored_path_generation = restore_save_effects
                .then(|| {
                    if coordinator.ancillary.current_project_path.as_deref() == Some(target) {
                        Ok(coordinator.path_generation)
                    } else {
                        coordinator.path_generation.checked_add(1).ok_or_else(|| {
                            "Project path generation is exhausted; restart Syndocal before reconciling Save"
                                .to_string()
                        })
                    }
                })
                .transpose()?;
            let restored_disposition_generation = restore_save_effects
                .then(|| checked_project_authority_disposition_generation_after_change(coordinator))
                .transpose()?;
            let mut current_path_mirror = restore_save_effects
                .then(|| {
                    state
                        .current_project_path
                        .lock()
                        .map_err(|_| "Current project path lock was poisoned".to_string())
                })
                .transpose()?;
            let terminal = persist_project_publication_terminal_v1(
                journal_path,
                &current.request,
                &current.shape_hash,
                ProjectPublicationTerminalCommitV1 {
                    outcome: ProjectPublicationTerminalOutcomeV1::Succeeded,
                    target_path: Some(target.to_string_lossy().to_string()),
                    artifact_digest: Some(expected_digest.to_string()),
                    backup,
                    recovery_authority_serial: coordinator.recovery_authority_serial,
                    error: None,
                    warning: None,
                },
            )?;
            if let (Some(path_generation), Some(disposition_generation)) =
                (restored_path_generation, restored_disposition_generation)
            {
                coordinator.path_generation = path_generation;
                coordinator.ancillary.current_project_path = Some(target.to_path_buf());
                if let Some(current_path_mirror) = current_path_mirror.as_mut() {
                    **current_path_mirror = coordinator.ancillary.current_project_path.clone();
                }
                commit_project_authority_disposition_after_preflight(
                    coordinator,
                    disposition_generation,
                    ProjectAuthorityDisposition::CleanAtPath,
                );
            }
            refresh_project_publication_fault_latch_v1(state, journal_path)?;
            Ok(project_publication_terminal_status_v1(
                &terminal,
                publication_terminal_authority_if_current(state, coordinator, &terminal),
            ))
        }
        Ok(_) => {
            let terminal = persist_project_publication_terminal_v1(
                journal_path,
                &current.request,
                &current.shape_hash,
                ProjectPublicationTerminalCommitV1 {
                    outcome: ProjectPublicationTerminalOutcomeV1::Failed,
                    target_path: None,
                    artifact_digest: None,
                    backup: None,
                    recovery_authority_serial: durable.serial,
                    error: Some(
                        "Prepared project publication target is missing or does not match the reserved artifact"
                            .to_string(),
                    ),
                    warning: None,
                },
            )?;
            refresh_project_publication_fault_latch_v1(state, journal_path)?;
            Ok(project_publication_terminal_status_v1(&terminal, None))
        }
        Err(error) => {
            mark_project_publication_indeterminate_v1(
                journal_path,
                &current.request,
                &current.shape_hash,
                error.clone(),
            )?;
            state
                .project_external_command_admission
                .recovery_authority_faulted
                .store(true, Ordering::Release);
            Err(error)
        }
    }
}

