/// Register the current generation of one concrete webview. Only the owner
/// displaced from this same window may be recovered here; a live pane's
/// transaction is never stolen merely because the main renderer reloaded.
#[tauri::command]
fn register_project_transaction_owner(
    window: WebviewWindow,
    state: State<'_, AppState>,
    owner_id: String,
) -> Result<Option<ProjectHistoryMutationResult>, String> {
    register_project_transaction_owner_for_window_label(&state, window.label(), owner_id)
}

fn register_project_transaction_owner_for_window_label(
    state: &AppState,
    window_label: &str,
    owner_id: String,
) -> Result<Option<ProjectHistoryMutationResult>, String> {
    validate_project_transaction_window_label(window_label)?;
    let owner_id = normalize_project_transaction_owner_id(owner_id)?;
    let _owner_rotation = state
        .project_transaction_owner_rotation
        .lock()
        .map_err(|_| "Project transaction owner rotation lock was poisoned".to_string())?;
    state.ensure_window_authority_not_blocked(window_label)?;
    let _external_admission = lock_project_transaction_owner_lifecycle_admission(state)?;
    let mut coordinator = lock_project_coordinator(state)?;
    if state.project_transaction_active.load(Ordering::Acquire)
        && coordinator.history.pending.is_empty()
    {
        return Err(
            "Project transaction is active; retry owner registration after Display output publication"
                .to_string(),
        );
    }
    let mut owners = state
        .project_transaction_owners
        .lock()
        .map_err(|_| "Project transaction owner registry lock was poisoned".to_string())?;
    ensure_project_transaction_owner_unique_to_window(&owners, window_label, &owner_id)?;
    let retired_preview_owner = owners.get(window_label).cloned();
    let same_incarnation = retired_preview_owner.as_deref() == Some(owner_id.as_str());
    let mut incarnations = state
        .project_transaction_owner_incarnations
        .lock()
        .map_err(|_| {
            "Project transaction owner incarnation registry lock was poisoned".to_string()
        })?;
    let next_incarnation = if same_incarnation {
        incarnations.get(window_label).copied().ok_or_else(|| {
            "Registered project owner is missing its backend incarnation".to_string()
        })?
    } else {
        allocate_project_transaction_owner_incarnation(state)?
    };
    let retired_incarnation = retired_preview_owner
        .as_deref()
        .filter(|_| !same_incarnation)
        .map(|_| {
            incarnations.get(window_label).copied().ok_or_else(|| {
                "Retired project transaction owner is missing its backend incarnation".to_string()
            })
        })
        .transpose()?;
    // Hold both registries through recovery and the owner/session handoff. The
    // external-admission and coordinator locks already exclude concurrent
    // operator mutations; taking owners before sessions is the only nested
    // registry order. Acquiring sessions before retirement means a failed
    // cancellation leaves both maps untouched.
    let mut sessions = state
        .project_operator_sessions
        .lock()
        .map_err(|_| "Project operator session registry lock was poisoned".to_string())?;
    let mut output_lease_registry = state
        .output_lease_registry
        .lock()
        .map_err(|_| "Output lease registry lock was poisoned".to_string())?;
    let mut receipts = state
        .project_transaction_receipts
        .lock()
        .map_err(|_| "Project transaction receipt registry lock was poisoned".to_string())?;
    let mut highwaters = state
        .project_transaction_operation_highwaters
        .lock()
        .map_err(|_| "Project transaction operation high-water lock was poisoned".to_string())?;
    let mut lanes = state
        .project_transaction_lanes
        .lock()
        .map_err(|_| "Project transaction lane registry lock was poisoned".to_string())?;
    let mut retired_owner_bindings = state
        .project_transaction_retired_owner_bindings
        .lock()
        .map_err(|_| {
            "Project transaction retired-owner binding registry lock was poisoned".to_string()
        })?;
    if !same_incarnation {
        ensure_project_transaction_owner_binding_not_retired(
            &retired_owner_bindings,
            &owner_id,
            window_label,
        )?;
    }
    let retired_binding_key = retired_preview_owner
        .as_deref()
        .filter(|_| !same_incarnation)
        .map(|retired_owner| {
            preflight_project_transaction_owner_binding_retirement(
                &retired_owner_bindings,
                retired_owner,
                window_label,
            )
        })
        .transpose()?;
    let retired_terminal_operation_ids = retired_preview_owner
        .as_deref()
        .zip(retired_incarnation)
        .map(|(retired_owner, retired_incarnation)| {
            preflight_terminal_project_transaction_compaction_for_retired_owner_binding(
                &receipts,
                &lanes,
                retired_owner,
                window_label,
                retired_incarnation,
            )
        })
        .transpose()?
        .unwrap_or_default();
    let output_lease_candidate = if !same_incarnation {
        retired_preview_owner
            .as_deref()
            .map(|retired_owner| {
                let retired_incarnation = retired_incarnation.ok_or_else(|| {
                    "Retired project transaction owner is missing its backend incarnation"
                        .to_string()
                })?;
                preflight_output_lease_owner_retirement(
                    state,
                    &output_lease_registry,
                    window_label,
                    retired_owner,
                    retired_incarnation,
                )
            })
            .transpose()?
    } else {
        None
    };
    let recovered = transition_project_transaction_window_owner_with_operator_session(
        &mut owners,
        &mut sessions,
        &mut coordinator,
        window_label,
        Some(owner_id.clone()),
        |previous_owner, coordinator| {
            let Some(previous_owner) = previous_owner else {
                return Ok(None);
            };
            let recovered = if let Some(pending) =
                project_transaction_for_retired_owner(&coordinator.history, previous_owner)?
            {
                let operation_id = pending.client_operation_id.clone();
                let operation_lane = (!operation_id.is_empty())
                    .then(|| {
                        lanes.get(&operation_id).cloned().ok_or_else(|| {
                            format!(
                                "Project transaction cancellation completed without lane {operation_id}"
                            )
                        })
                    })
                    .transpose()?;
                let result = finalize_retired_project_transaction_locked(
                    state,
                    coordinator,
                    pending,
                    operation_lane,
                    &mut receipts,
                    &mut lanes,
                )?;
                Some(result)
            } else {
                None
            };
            compact_preflighted_terminal_project_transactions_for_retired_owner_binding(
                &mut receipts,
                &mut lanes,
                &retired_terminal_operation_ids,
            );
            let key = retired_binding_key.as_ref().ok_or_else(|| {
                "Project transaction owner retirement was not preflighted".to_string()
            })?;
            retired_owner_bindings.insert(key.clone());
            Ok(recovered)
        },
    )?;
    if let (Some(retired_owner), Some(retired_incarnation)) =
        (retired_preview_owner.as_deref(), retired_incarnation)
    {
        highwaters.remove(&project_transaction_operation_highwater_key(
            retired_owner,
            window_label,
            retired_incarnation,
        ));
    }
    incarnations.insert(window_label.to_string(), next_incarnation);
    if let Some(candidate) = output_lease_candidate {
        *output_lease_registry = candidate;
    }
    drop(sessions);
    drop(output_lease_registry);
    drop(incarnations);
    drop(owners);
    drop(coordinator);
    drop(lanes);
    drop(highwaters);
    drop(receipts);
    drop(retired_owner_bindings);
    if retired_preview_owner.as_deref() != Some(owner_id.as_str()) {
        if let Some(retired_owner) = retired_preview_owner.as_deref() {
            state
                .media_asset_operations
                .purge_preview_sessions_for_owner(retired_owner);
            state
                .media_asset_operations
                .purge_video_clip_slot_authoritative_for_owner(retired_owner);
            state
                .media_asset_operations
                .purge_video_effect_catalog_authoritative_for_owner(retired_owner);
            state.authored_control_plane.retire_principal(retired_owner);
            state.runtime_control_plane.retire_principal(retired_owner);
        }
    }
    Ok(recovered)
}

/// An owner generation belongs to exactly one concrete WebView label. Owner
/// IDs are correlation identities, not secrets: a raw caller can repeat an
/// observed string, so allowing the same value under a second label would also
/// share the first window's Operator unlock session. Check this while the
/// registry lock is held and before retiring/replacing any existing owner so a
/// rejected alias leaves registry, transaction, and session state unchanged.
fn ensure_project_transaction_owner_unique_to_window(
    owners: &HashMap<String, String>,
    window_label: &str,
    owner_id: &str,
) -> Result<(), String> {
    if owners
        .iter()
        .any(|(label, candidate)| label != window_label && candidate == owner_id)
    {
        return Err(
            "Project transaction owner ID is already registered to another renderer window"
                .to_string(),
        );
    }
    Ok(())
}

fn project_transaction_for_retired_owner(
    history: &ProjectHistory,
    retired_owner_id: &str,
) -> Result<Option<PendingProjectTransaction>, String> {
    if history.pending.len() > 1 {
        return Err("Project history contains multiple pending transactions; restart Syndocal to preserve recovery safety".to_string());
    }
    Ok(history
        .pending
        .values()
        .next()
        .filter(|pending| pending.owner_id == retired_owner_id)
        .cloned())
}

#[cfg(test)]
fn retire_project_transaction_owner_for_window_incarnation(
    state: &AppState,
    window_label: &str,
    expected_retired_incarnation: Option<u64>,
) -> Result<Option<ProjectHistoryMutationResult>, String> {
    let _owner_rotation = state
        .project_transaction_owner_rotation
        .lock()
        .map_err(|_| "Project transaction owner rotation lock was poisoned".to_string())?;
    retire_project_transaction_owner_for_window_incarnation_under_rotation(
        state,
        window_label,
        expected_retired_incarnation,
    )
}

fn retire_project_transaction_owner_for_window_incarnation_under_rotation(
    state: &AppState,
    window_label: &str,
    expected_retired_incarnation: Option<u64>,
) -> Result<Option<ProjectHistoryMutationResult>, String> {
    let _external_admission = lock_project_transaction_owner_lifecycle_admission(state)?;
    let mut coordinator = lock_project_coordinator(state)?;
    if state.project_transaction_active.load(Ordering::Acquire)
        && coordinator.history.pending.is_empty()
    {
        return Err(
            "Project transaction is active; retry owner retirement after Display output publication"
                .to_string(),
        );
    }
    let mut owners = state
        .project_transaction_owners
        .lock()
        .map_err(|_| "Project transaction owner registry lock was poisoned".to_string())?;
    let retired_preview_owner = owners.get(window_label).cloned();
    let mut incarnations = state
        .project_transaction_owner_incarnations
        .lock()
        .map_err(|_| {
            "Project transaction owner incarnation registry lock was poisoned".to_string()
        })?;
    if let Some(expected) = expected_retired_incarnation {
        if incarnations.get(window_label).copied() != Some(expected) {
            return Ok(None);
        }
    }
    // Match registration's atomic owner/session boundary. In particular, an
    // orphan cancellation failure must leave its previous session available
    // under the still-registered owner instead of orphaning its lock state.
    let mut sessions = state
        .project_operator_sessions
        .lock()
        .map_err(|_| "Project operator session registry lock was poisoned".to_string())?;
    let mut output_lease_registry = state
        .output_lease_registry
        .lock()
        .map_err(|_| "Output lease registry lock was poisoned".to_string())?;
    let mut receipts = state
        .project_transaction_receipts
        .lock()
        .map_err(|_| "Project transaction receipt registry lock was poisoned".to_string())?;
    let mut highwaters = state
        .project_transaction_operation_highwaters
        .lock()
        .map_err(|_| "Project transaction operation high-water lock was poisoned".to_string())?;
    let mut lanes = state
        .project_transaction_lanes
        .lock()
        .map_err(|_| "Project transaction lane registry lock was poisoned".to_string())?;
    let mut retired_owner_bindings = state
        .project_transaction_retired_owner_bindings
        .lock()
        .map_err(|_| {
            "Project transaction retired-owner binding registry lock was poisoned".to_string()
        })?;
    let retired_binding_key = retired_preview_owner
        .as_deref()
        .map(|retired_owner| {
            preflight_project_transaction_owner_binding_retirement(
                &retired_owner_bindings,
                retired_owner,
                window_label,
            )
        })
        .transpose()?;
    let retired_incarnation = retired_preview_owner
        .as_deref()
        .map(|_| {
            incarnations.get(window_label).copied().ok_or_else(|| {
                "Retired project transaction owner is missing its backend incarnation".to_string()
            })
        })
        .transpose()?;
    let retired_terminal_operation_ids = retired_preview_owner
        .as_deref()
        .zip(retired_incarnation)
        .map(|(retired_owner, retired_incarnation)| {
            preflight_terminal_project_transaction_compaction_for_retired_owner_binding(
                &receipts,
                &lanes,
                retired_owner,
                window_label,
                retired_incarnation,
            )
        })
        .transpose()?
        .unwrap_or_default();
    let output_lease_candidate = retired_preview_owner
        .as_deref()
        .map(|retired_owner| {
            let retired_incarnation = retired_incarnation.ok_or_else(|| {
                "Retired project transaction owner is missing its backend incarnation".to_string()
            })?;
            preflight_output_lease_owner_retirement(
                state,
                &output_lease_registry,
                window_label,
                retired_owner,
                retired_incarnation,
            )
        })
        .transpose()?;
    let recovered = transition_project_transaction_window_owner_with_operator_session(
        &mut owners,
        &mut sessions,
        &mut coordinator,
        window_label,
        None,
        |retired_owner, coordinator| {
            let Some(retired_owner) = retired_owner else {
                return Ok(None);
            };
            let recovered = if let Some(pending) =
                project_transaction_for_retired_owner(&coordinator.history, retired_owner)?
            {
                let operation_id = pending.client_operation_id.clone();
                let operation_lane = (!operation_id.is_empty())
                    .then(|| {
                        lanes.get(&operation_id).cloned().ok_or_else(|| {
                            format!(
                                "Project transaction cancellation completed without lane {operation_id}"
                            )
                        })
                    })
                    .transpose()?;
                let result = finalize_retired_project_transaction_locked(
                    state,
                    coordinator,
                    pending,
                    operation_lane,
                    &mut receipts,
                    &mut lanes,
                )?;
                Some(result)
            } else {
                None
            };
            compact_preflighted_terminal_project_transactions_for_retired_owner_binding(
                &mut receipts,
                &mut lanes,
                &retired_terminal_operation_ids,
            );
            let key = retired_binding_key.as_ref().ok_or_else(|| {
                "Project transaction owner retirement was not preflighted".to_string()
            })?;
            retired_owner_bindings.insert(key.clone());
            Ok(recovered)
        },
    )?;
    if let (Some(retired_owner), Some(retired_incarnation)) =
        (retired_preview_owner.as_deref(), retired_incarnation)
    {
        highwaters.remove(&project_transaction_operation_highwater_key(
            retired_owner,
            window_label,
            retired_incarnation,
        ));
    }
    incarnations.remove(window_label);
    if let Some(candidate) = output_lease_candidate {
        *output_lease_registry = candidate;
    }
    drop(sessions);
    drop(output_lease_registry);
    drop(incarnations);
    drop(owners);
    drop(coordinator);
    drop(lanes);
    drop(highwaters);
    drop(receipts);
    drop(retired_owner_bindings);
    if let Some(retired_owner) = retired_preview_owner.as_deref() {
        state
            .media_asset_operations
            .purge_preview_sessions_for_owner(retired_owner);
        state
            .media_asset_operations
            .purge_video_clip_slot_authoritative_for_owner(retired_owner);
        state
            .media_asset_operations
            .purge_video_effect_catalog_authoritative_for_owner(retired_owner);
        state.authored_control_plane.retire_principal(retired_owner);
        state.runtime_control_plane.retire_principal(retired_owner);
    }
    Ok(recovered)
}

#[cfg(test)]
fn retire_project_transaction_owner_for_window(
    state: &AppState,
    window_label: &str,
) -> Result<Option<ProjectHistoryMutationResult>, String> {
    retire_project_transaction_owner_for_window_incarnation(state, window_label, None)
}

/// Retire one destroyed renderer's AppState and query authority as one
/// fail-closed lifecycle boundary. The AppState owner incarnation is the
/// stale-callback guard; query binding is lazy and therefore is not a second
/// required generation. Owner/lease retirement is attempted first, then query
/// retirement is always attempted as a best-effort fence even when the
/// AppState transition fails. A blocked-label record prevents any new
/// authority from being issued; only restart can recover a dead label.
fn handle_destroyed_window_authority_retirement(
    state: &AppState,
    query: &ControlPlaneQueryState,
    window_label: &str,
) -> Result<(), String> {
    let expected_retired_incarnation = match state.project_transaction_owner_incarnations.lock() {
        Ok(incarnations) => incarnations.get(window_label).copied(),
        Err(error) => {
            return fail_closed_destroyed_window_authority_owner_capture(
                state,
                query,
                window_label,
                format!(
                    "Project transaction owner incarnation registry lock was poisoned: {error}"
                ),
            );
        }
    };
    handle_destroyed_window_authority_retirement_for_incarnation(
        state,
        query,
        window_label,
        expected_retired_incarnation,
    )
}

fn fail_closed_destroyed_window_authority_owner_capture(
    state: &AppState,
    query: &ControlPlaneQueryState,
    window_label: &str,
    capture_error: String,
) -> Result<(), String> {
    let mut errors = vec![format!("owner incarnation capture failed: {capture_error}")];
    if let Err(error) = state.begin_window_authority_retirement(window_label) {
        errors.push(format!("retirement fence installation failed: {error}"));
    }
    if let Err(error) = query.retire_window(window_label) {
        errors.push(format!("query retirement failed: {error}"));
    }
    match state.record_window_authority_retirement_failure(window_label) {
        Ok(()) => errors.push("window authority was permanently blocked".to_string()),
        Err(error) => errors.push(format!("fail-closed block registry unavailable: {error}")),
    }
    Err(format!(
        "Destroyed window '{window_label}' authority retirement failed; {}",
        errors.join("; ")
    ))
}

fn handle_destroyed_window_authority_retirement_for_incarnation(
    state: &AppState,
    query: &ControlPlaneQueryState,
    window_label: &str,
    expected_retired_incarnation: Option<u64>,
) -> Result<(), String> {
    // A callback without the concrete AppState owner generation is not
    // authorized to retire a label. Query binding is lazy, so a missing query
    // generation only skips query cleanup; owner/lease retirement is still
    // required for a registered renderer.
    let Some(expected_retired_incarnation) = expected_retired_incarnation else {
        return Ok(());
    };
    handle_destroyed_window_authority_retirement_for_incarnation_with_hook(
        state,
        query,
        window_label,
        expected_retired_incarnation,
        || {},
    )
}

/// Destroyed retirement's linearization seam. The production callback passes
/// an empty hook; tests use it to attempt a new Begin and an authored command
/// after owner/lease retirement has failed but before query retirement. The
/// temporary label fence must reject both operations during that interval.
fn handle_destroyed_window_authority_retirement_for_incarnation_with_hook(
    state: &AppState,
    query: &ControlPlaneQueryState,
    window_label: &str,
    expected_retired_incarnation: u64,
    after_owner_retirement: impl FnOnce(),
) -> Result<(), String> {
    // Keep the same rotation guard from marker installation through owner,
    // query, and final promotion. A Begin which acquired its operation gate
    // before this guard is therefore linearized before retirement; one which
    // arrives after the marker is rejected by the post-gate revalidation.
    let _owner_rotation = state
        .project_transaction_owner_rotation
        .lock()
        .map_err(|_| "Project transaction owner rotation lock was poisoned".to_string())?;
    let owner_matches = state
        .project_transaction_owner_incarnations
        .lock()
        .map_err(|_| {
            "Project transaction owner incarnation registry lock was poisoned".to_string()
        })?
        .get(window_label)
        .copied()
        == Some(expected_retired_incarnation);
    if !owner_matches {
        // A stale callback is a strict no-op. It must not install a temporary
        // fence, retire a replacement owner, or touch the query generation.
        return Ok(());
    }
    let mut owner_error = match validate_project_transaction_window_label(window_label) {
        Ok(()) => match state.begin_window_authority_retirement(window_label) {
            Ok(()) => retire_project_transaction_owner_for_window_incarnation_under_rotation(
                state,
                window_label,
                Some(expected_retired_incarnation),
            )
            .err(),
            Err(error) => Some(format!("retirement fence installation failed: {error}")),
        },
        Err(error) => Some(format!("window label validation failed: {error}")),
    };
    after_owner_retirement();
    let query_error = query.retire_window(window_label).err();
    if owner_error.is_none() && query_error.is_none() {
        if let Err(error) = state.complete_window_authority_retirement(window_label) {
            owner_error = Some(format!("retirement fence release failed: {error}"));
        } else {
            return Ok(());
        }
    }
    // Failure promotion removes the temporary marker only in the same
    // authority-barrier critical section that inserts the permanent block.
    let block_error = state
        .record_window_authority_retirement_failure(window_label)
        .err();
    let mut errors = Vec::with_capacity(3);
    if let Some(error) = owner_error {
        errors.push(format!("owner/lease retirement failed: {error}"));
    }
    if let Some(error) = query_error {
        errors.push(format!("query retirement failed: {error}"));
    }
    if let Some(error) = block_error {
        errors.push(format!("fail-closed block registry unavailable: {error}"));
    } else {
        errors.push("window authority was permanently blocked".to_string());
    }
    Err(format!(
        "Destroyed window '{window_label}' authority retirement failed; {}",
        errors.join("; ")
    ))
}

fn transition_project_transaction_window_owner<T>(
    owners: &mut HashMap<String, String>,
    window_label: &str,
    next_owner: Option<String>,
    finalize_retired: impl FnOnce(Option<&str>) -> Result<Option<T>, String>,
) -> Result<Option<T>, String> {
    let previous_owner = owners.get(window_label).cloned();
    // A renderer can repeat registration after a transport retry. It has not
    // retired itself, so recovery must not cancel its own pending transaction
    // or reset the associated Operator session.
    if previous_owner.as_deref() == next_owner.as_deref() {
        return Ok(None);
    }
    // Finalize first. If checkpoint/hash/history preparation fails, the map
    // remains byte-for-byte unchanged and the retired owner stays retryable.
    let finalized = finalize_retired(previous_owner.as_deref())?;
    if let Some(next_owner) = next_owner {
        owners.insert(window_label.to_string(), next_owner);
    } else {
        owners.remove(window_label);
    }
    Ok(finalized)
}

/// Move the exact current Operator-session state together with a same-window
/// owner transition. The session is authoritative only when it was issued for
/// the coordinator's current epoch and exact policy; a stale policy/epoch must
/// fall back to the normal policy default for the new owner. A fresh owner can
/// never inherit an unrelated stale entry, and a same-owner retry is a strict
/// no-op.
fn transition_project_operator_session_owner(
    sessions: &mut HashMap<String, ProjectOperatorSession>,
    coordinator: &ProjectCoordinator,
    previous_owner: Option<&str>,
    next_owner: Option<&str>,
) {
    if previous_owner == next_owner {
        return;
    }
    let previous_session = previous_owner.and_then(|owner_id| sessions.remove(owner_id));
    let Some(next_owner) = next_owner else {
        return;
    };

    // A newly registered identity must not reuse a stale record which happens
    // to share its string. It receives only the predecessor's exact current
    // lock/unlock state, otherwise `project_operator_session_for_policy` mints
    // the policy-default session on first use.
    sessions.remove(next_owner);
    let Some(policy) = coordinator.ancillary.operator_policy.as_ref() else {
        return;
    };
    let Some(session) = previous_session else {
        return;
    };
    if session.project_epoch == coordinator.epoch && session.policy == *policy {
        sessions.insert(next_owner.to_string(), session);
    }
}

/// One locked transition boundary for both owner correlation and Operator
/// admission state. The caller holds external admission, coordinator, owners,
/// and sessions in that order. Retirement runs first; only its successful,
/// infallible completion can make either registry visible under the successor.
fn transition_project_transaction_window_owner_with_operator_session<T>(
    owners: &mut HashMap<String, String>,
    sessions: &mut HashMap<String, ProjectOperatorSession>,
    coordinator: &mut ProjectCoordinator,
    window_label: &str,
    next_owner: Option<String>,
    finalize_retired: impl FnOnce(Option<&str>, &mut ProjectCoordinator) -> Result<Option<T>, String>,
) -> Result<Option<T>, String> {
    let previous_owner = owners.get(window_label).cloned();
    let next_owner_for_session = next_owner.clone();
    let finalized = transition_project_transaction_window_owner(
        owners,
        window_label,
        next_owner,
        |retired_owner| finalize_retired(retired_owner, coordinator),
    )?;
    transition_project_operator_session_owner(
        sessions,
        coordinator,
        previous_owner.as_deref(),
        next_owner_for_session.as_deref(),
    );
    Ok(finalized)
}

fn cancel_pending_project_transaction_locked(
    state: &AppState,
    coordinator: &mut ProjectCoordinator,
    pending: PendingProjectTransaction,
) -> Result<ProjectHistoryMutationResult, String> {
    let operation_lane = (!pending.client_operation_id.is_empty())
        .then(|| project_transaction_lane_for_operation(state, &pending.client_operation_id))
        .transpose()?;
    cancel_pending_project_transaction_locked_with_lane(state, coordinator, pending, operation_lane)
}

fn project_transaction_requires_command_result(command_name: &str) -> bool {
    matches!(command_name, "patch_fixtures" | "repair_fixture_profile")
        || is_stage_project_transaction_command(command_name)
}

fn is_stage_project_transaction_command(command_name: &str) -> bool {
    matches!(
        command_name,
        "set_fixture_transform"
            | "set_fixture_transforms"
            | "set_stage_map_config"
            | "save_stage_map_preset"
            | "apply_stage_map_preset"
            | "remove_stage_map_preset"
            | "import_stage_map_preset"
            | "add_stage_object"
            | "set_stage_object"
            | "remove_stage_object"
    )
}

fn project_transaction_command_result_matches_name(
    command_name: &str,
    result: &ProjectTransactionCommandResult,
) -> bool {
    match (command_name, result) {
        ("patch_fixtures", ProjectTransactionCommandResult::PatchFixtures { .. })
        | (
            "repair_fixture_profile",
            ProjectTransactionCommandResult::RepairFixtureProfile { .. },
        ) => true,
        (
            command_name,
            ProjectTransactionCommandResult::StageProjectMutation {
                command_name: stored_command_name,
                ..
            },
        ) => {
            is_stage_project_transaction_command(command_name)
                && stored_command_name == command_name
        }
        _ => false,
    }
}

/// Complete one already-admitted transaction from either the renderer Commit
/// route or an owner-retirement recovery. The operation lane is closed before
/// coordinator mutation, and every fallible checkpoint/history/counter step is
/// prepared before assigning the authoritative B image.
fn commit_pending_project_transaction_locked_with_lane(
    state: &AppState,
    coordinator: &mut ProjectCoordinator,
    pending: PendingProjectTransaction,
    operation_lane: Option<Arc<ProjectTransactionLane>>,
) -> Result<ProjectHistoryMutationResult, String> {
    if pending.command_indeterminate_error.is_some() {
        return Err(
            "Project transaction command publication is indeterminate and cannot be committed"
                .to_string(),
        );
    }
    if project_transaction_requires_command_result(&pending.command_name) {
        let result = pending.command_result.as_ref().ok_or_else(|| {
            "Published PATCH/Repair transaction cannot commit before its exact command result"
                .to_string()
        })?;
        if !project_transaction_command_result_matches_name(&pending.command_name, result) {
            return Err(
                "Published PATCH/Repair transaction command result does not match its command"
                    .to_string(),
            );
        }
    } else if let Some(result) = pending.command_result.as_ref() {
        if !project_transaction_command_result_matches_name(&pending.command_name, result) {
            return Err(
                "Project transaction command result does not match its command".to_string(),
            );
        }
    }

    let transaction_id = pending.transaction_id;
    let next_history_generation = checked_project_history_generation_after_change(coordinator)?;
    let mut after = project_checkpoint_for_coordinator(state, coordinator)?;
    let changed =
        pending.before.project != after.project || pending.before.mappings != after.mappings;
    let prepared_revision_and_hash = if changed {
        let revision = checked_project_revision_after_mutation(coordinator)?;
        let hash = project_checkpoint_hash(&after.project, &after.mappings)?;
        after.revision = revision;
        after.hash = hash.clone();
        Some((revision, hash))
    } else {
        None
    };
    let next_publication_generation = prepared_revision_and_hash
        .is_some()
        .then(|| checked_project_authority_publication_generation_after_change(coordinator))
        .transpose()?;
    let mut next_history = coordinator.history.clone();
    commit_project_history_entry(
        &mut next_history,
        pending,
        after,
        current_unix_ms().min(u64::MAX as u128) as u64,
    )?;
    next_history.pending.remove(&transaction_id);
    if let Some(lane) = operation_lane.as_ref() {
        lane.close()?;
    }
    if let Some((revision, hash)) = prepared_revision_and_hash {
        coordinator.revision = revision;
        coordinator.checkpoint_hash = hash;
        commit_project_authority_publication_after_preflight(
            coordinator,
            next_publication_generation
                .expect("a changed transaction preflights its mutation publication"),
            ProjectAuthorityPublicationKind::Mutation,
        );
    }
    coordinator.history = next_history;
    coordinator.history_generation = next_history_generation;
    state
        .project_transaction_active
        .store(false, Ordering::Release);
    Ok(ProjectHistoryMutationResult {
        history_status: project_history_status_for_coordinator(coordinator),
        authority: project_authority_bundle_from_coordinator(state, coordinator),
    })
}

/// Retirement already owns the lane registry so it can close and compact the
/// exact operation atomically without recursively locking that registry.
fn cancel_pending_project_transaction_locked_with_lane(
    state: &AppState,
    coordinator: &mut ProjectCoordinator,
    pending: PendingProjectTransaction,
    operation_lane: Option<Arc<ProjectTransactionLane>>,
) -> Result<ProjectHistoryMutationResult, String> {
    let transaction_id = pending.transaction_id;
    // Cancel likewise removes an observable pending reservation whether or
    // not it creates an Interrupted Undo entry.
    let next_history_generation = checked_project_history_generation_after_change(coordinator)?;

    // Cancellation is not a rollback: live engine commands can have already
    // produced hardware/runtime effects. Preserve a changed persistence image
    // as an explicit interrupted entry so Undo remains truthful. All fallible
    // capture/hash work occurs before removing the reservation.
    let after = project_checkpoint_for_coordinator(state, coordinator)?;
    let (next_history, prepared_revision_and_hash) = prepare_cancelled_project_transaction_history(
        coordinator,
        pending,
        after,
        current_unix_ms().min(u64::MAX as u128) as u64,
    )?;
    let next_publication_generation = prepared_revision_and_hash
        .is_some()
        .then(|| checked_project_authority_publication_generation_after_change(coordinator))
        .transpose()?;
    if let Some(lane) = operation_lane.as_ref() {
        lane.close()?;
    }
    if let Some(live_pending) = coordinator.history.pending.get_mut(&transaction_id) {
        live_pending.closing = true;
    }
    if let Some((revision, hash)) = prepared_revision_and_hash {
        coordinator.revision = revision;
        coordinator.checkpoint_hash = hash;
        commit_project_authority_publication_after_preflight(
            coordinator,
            next_publication_generation
                .expect("a changed cancellation preflights its mutation publication"),
            ProjectAuthorityPublicationKind::Mutation,
        );
    }
    coordinator.history = next_history;
    coordinator.history_generation = next_history_generation;
    state
        .project_transaction_active
        .store(false, Ordering::Release);
    Ok(ProjectHistoryMutationResult {
        history_status: project_history_status_for_coordinator(coordinator),
        authority: project_authority_bundle_from_coordinator(state, coordinator),
    })
}

/// Builds the truthful cancellation result without touching the live
/// coordinator. This is intentionally shared by the command and tests: a
/// partial engine mutation becomes an interrupted Undo entry only after every
/// fallible checkpoint/hash/history operation has succeeded.
fn prepare_cancelled_project_transaction_history(
    coordinator: &ProjectCoordinator,
    pending: PendingProjectTransaction,
    mut after: ProjectCheckpoint,
    committed_at_unix_ms: u64,
) -> Result<(ProjectHistory, Option<(u64, String)>), String> {
    let transaction_id = pending.transaction_id;
    let changed =
        pending.before.project != after.project || pending.before.mappings != after.mappings;
    let prepared_revision_and_hash = if changed {
        let revision = checked_project_revision_after_mutation(coordinator)?;
        let hash = project_checkpoint_hash(&after.project, &after.mappings)?;
        after.revision = revision;
        after.hash = hash.clone();
        Some((revision, hash))
    } else {
        None
    };
    let mut next_history = coordinator.history.clone();
    if changed {
        let interrupted = PendingProjectTransaction {
            label: format!("Interrupted: {}", pending.label),
            coalesce_key: String::new(),
            ..pending
        };
        commit_project_history_entry(&mut next_history, interrupted, after, committed_at_unix_ms)?;
    }
    next_history.pending.remove(&transaction_id);
    Ok((next_history, prepared_revision_and_hash))
}

#[tauri::command]
fn clear_project_history(
    window: WebviewWindow,
    state: State<'_, AppState>,
    owner_id: String,
    expected_epoch: u64,
    expected_history_generation: u64,
) -> Result<ProjectHistoryMutationResult, String> {
    let _external_admission = lock_project_external_command_admission(&state)?;
    let mut coordinator = lock_project_coordinator(&state)?;
    ensure_no_pending_project_transaction(&coordinator)?;
    project_transaction_owner_binding_for_window(&state, window.label(), &owner_id)?;
    ensure_project_operator_authoritative_mutation_allowed(&state, &coordinator, &owner_id)?;
    ensure_project_epoch_matches(&coordinator, expected_epoch)?;
    if coordinator.history_generation != expected_history_generation {
        return Err(format!(
            "Project history changed before clear (expected generation {expected_history_generation}, current generation {})",
            coordinator.history_generation
        ));
    }
    let history_changed = !coordinator.history.undo.is_empty()
        || !coordinator.history.redo.is_empty()
        || !coordinator.history.pending.is_empty();
    let next_history_generation = history_changed
        .then(|| checked_project_history_generation_after_change(&coordinator))
        .transpose()?;
    coordinator.history.pending.clear();
    coordinator.history.undo.clear();
    coordinator.history.redo.clear();
    if let Some(next_history_generation) = next_history_generation {
        coordinator.history_generation = next_history_generation;
    }
    state
        .project_transaction_active
        .store(false, Ordering::Release);
    Ok(ProjectHistoryMutationResult {
        history_status: project_history_status_for_coordinator(&coordinator),
        authority: project_authority_bundle_from_coordinator(&state, &coordinator),
    })
}

fn validate_history_navigation_cas(
    coordinator: &ProjectCoordinator,
    current: &ProjectCheckpoint,
    entry: Option<&ProjectHistoryEntry>,
    expected_epoch: Option<u64>,
    expected_entry_id: Option<u64>,
    expected_checkpoint_hash: Option<&str>,
    source_checkpoint: impl FnOnce(&ProjectHistoryEntry) -> &ProjectCheckpoint,
) -> Result<(), String> {
    if let Some(expected_epoch) = expected_epoch {
        if expected_epoch != coordinator.epoch {
            return Err(format!(
                "Project history is stale (expected epoch {expected_epoch}, current epoch {})",
                coordinator.epoch
            ));
        }
    }
    let Some(entry) = entry else {
        if expected_entry_id.is_some() || expected_checkpoint_hash.is_some() {
            return Err("Project history changed before navigation could start".to_string());
        }
        return Ok(());
    };
    let source = source_checkpoint(entry);
    // This backend-side comparison is mandatory even for legacy callers that
    // have not supplied frontend CAS tokens.  A top entry only navigates from
    // the exact checkpoint it was recorded against.
    if current.epoch != source.epoch
        || current.revision != source.revision
        || current.hash != source.hash
    {
        return Err("Project history no longer matches the current project checkpoint".to_string());
    }
    if let Some(expected_entry_id) = expected_entry_id {
        if expected_entry_id != entry.entry_id {
            return Err("Project history changed before navigation could start".to_string());
        }
    }
    if let Some(expected_checkpoint_hash) = expected_checkpoint_hash {
        if expected_checkpoint_hash != source.hash {
            return Err(
                "Project history checkpoint changed before navigation could start".to_string(),
            );
        }
    }
    Ok(())
}

fn navigate_project_history(
    state: &AppState,
    window_label: &str,
    owner_id: &str,
    undo: bool,
    expected_epoch: Option<u64>,
    expected_entry_id: Option<u64>,
    expected_checkpoint_hash: Option<String>,
) -> Result<ProjectHistoryNavigationResult, String> {
    project_transaction_owner_binding_for_window(state, window_label, owner_id)?;
    execute_managed_project_replacement_boundary(
        state,
        "Managed output lease project history replacement",
    )?;
    // Match all external replacement paths: lifecycle -> stop/join ->
    // coordinator.  The polling worker never takes lifecycle.
    let _lifecycle_guard = lock_standby_sync_lifecycle_for_project_swap(state)?;
    stop_standby_sync_for_project_swap(state)?;
    let _external_admission = lock_project_external_command_admission(state)?;
    let mut coordinator = lock_project_coordinator(state)?;
    project_transaction_owner_binding_for_window(state, window_label, owner_id)?;
    ensure_project_operator_authoritative_mutation_allowed(state, &coordinator, owner_id)?;
    navigate_project_history_with_coordinator(
        state,
        &mut coordinator,
        undo,
        expected_epoch,
        expected_entry_id,
        expected_checkpoint_hash,
        |state, prepared, coordinator| {
            replace_prepared_project_snapshot_with_coordinator(
                state,
                prepared,
                coordinator,
                project_replacement_plan!(
                    ProjectReplacementCoordinatorEffect::RevisionMutation,
                    false,
                    no_project_replacement_validation,
                    no_project_replacement_capture,
                    None
                ),
            )
            .map(|(result, (), _)| result)
        },
    )
}

/// The coordinator-owned Undo/Redo core.  The caller owns the lifecycle and
/// external-admission guards; the replacement callback is the one platform
/// boundary which needs a real Tauri app handle for output retirement and
/// recovery-authority persistence.  Keeping every history CAS, stack move,
/// post-publication rewrite, and authoritative result assignment here gives
/// headless tests the exact production coordinator path without forging an
/// `AppHandle<MockRuntime>` as `AppHandle<Wry>`.
fn navigate_project_history_with_coordinator<Replace>(
    state: &AppState,
    coordinator: &mut ProjectCoordinator,
    undo: bool,
    expected_epoch: Option<u64>,
    expected_entry_id: Option<u64>,
    expected_checkpoint_hash: Option<String>,
    replace: Replace,
) -> Result<ProjectHistoryNavigationResult, String>
where
    Replace: FnOnce(
        &AppState,
        PreparedProjectLoad,
        &mut ProjectCoordinator,
    ) -> Result<ProjectLoadResult, String>,
{
    // Undo/Redo is an identity-adjacent publication. It may not consume or
    // silently discard a Begin→Commit reservation from an in-flight edit.
    ensure_no_pending_project_transaction(coordinator)?;
    let current = reconcile_project_checkpoint_for_coordinator(state, coordinator)?;
    let top = if undo {
        coordinator.history.undo.last()
    } else {
        coordinator.history.redo.last()
    };
    validate_history_navigation_cas(
        coordinator,
        &current,
        top,
        expected_epoch,
        expected_entry_id,
        expected_checkpoint_hash.as_deref(),
        |entry| {
            if undo {
                &entry.after
            } else {
                &entry.before
            }
        },
    )?;
    // Preparation is deliberately before pop.  A malformed historic payload
    // therefore leaves the top entry intact instead of silently losing Undo.
    let prepared = if let Some(entry) = top {
        let target = if undo {
            entry.before.clone()
        } else {
            entry.after.clone()
        };
        let current_path = coordinator.ancillary.current_project_path.clone();
        Some(prepare_project_load(
            target.project,
            target.mappings,
            format!("{} {}", if undo { "Undo" } else { "Redo" }, entry.label),
            current_path.as_deref(),
        )?)
    } else {
        None
    };
    // `prepare_project_load` is fallible and intentionally happens before
    // popping. A direct live command can also arrive while it runs, so prove
    // the historical source is still the persistence snapshot immediately
    // before consuming the stack entry.
    let current = reconcile_project_checkpoint_for_coordinator(state, coordinator)?;
    let top = if undo {
        coordinator.history.undo.last()
    } else {
        coordinator.history.redo.last()
    };
    validate_history_navigation_cas(
        coordinator,
        &current,
        top,
        expected_epoch,
        expected_entry_id,
        expected_checkpoint_hash.as_deref(),
        |entry| {
            if undo {
                &entry.after
            } else {
                &entry.before
            }
        },
    )?;
    // A successful Undo/Redo moves one entry between stacks. Check its
    // separate status generation before popping or publishing so the final
    // post-ACK coordinator mutation is assignment-only.
    let next_history_generation = top
        .is_some()
        .then(|| checked_project_history_generation_after_change(coordinator))
        .transpose()?;
    let next_publication_generation = top
        .is_some()
        .then(|| checked_project_authority_publication_generation_after_change(coordinator))
        .transpose()?;
    let next_mapping_replacement_generation = top
        .is_some()
        .then(|| checked_project_mapping_replacement_generation_after_change(coordinator))
        .transpose()?;
    // The remaining source-stack entry meets this entry at the target image.
    // Its revision can differ after an earlier navigation publication, but
    // its epoch and content must agree before we publish or consume anything.
    let source_stack = if undo {
        &coordinator.history.undo
    } else {
        &coordinator.history.redo
    };
    if let Some(adjacent) = source_stack.iter().rev().nth(1) {
        let top = top.expect("an adjacent entry requires a history top");
        let target = if undo { &top.before } else { &top.after };
        let adjacent_source = if undo {
            &adjacent.after
        } else {
            &adjacent.before
        };
        if adjacent_source.epoch != target.epoch || adjacent_source.hash != target.hash {
            return Err("Adjacent project history does not match the navigation target".to_string());
        }
    }
    let entry = if undo {
        coordinator.history.undo.pop()
    } else {
        coordinator.history.redo.pop()
    };
    let Some(entry) = entry else {
        return Ok(ProjectHistoryNavigationResult {
            history_status: project_history_status_for_coordinator(coordinator),
            authority: project_authority_bundle_from_coordinator(state, coordinator),
        });
    };
    let target_checkpoint = if undo {
        entry.before.clone()
    } else {
        entry.after.clone()
    };
    let mut prepared = prepared.expect("history top was prepared before it was popped");
    prepared.authority_disposition = ProjectAuthorityDisposition::HistoryNavigation;
    // `prepare_project_load` canonicalizes every embedded fixture profile to
    // the exact `snapshot://fixture/{id}` identity the Engine publishes. Keep
    // that canonical project as the moved history image; reusing the authored
    // source-path spelling from `target_checkpoint` would make the next
    // reconcile misclassify a successful Undo/Redo as an external mutation.
    let canonical_target_project = project_file_from_prepared_load(&prepared);
    let mut replacement_result = match replace(state, prepared, coordinator) {
        Ok(result) => result,
        Err(error) => {
            if undo {
                coordinator.history.undo.push(entry);
            } else {
                coordinator.history.redo.push(entry);
            }
            return Err(error);
        }
    };
    // Replacement advances the coordinator revision. Rewrite the source side
    // of the moved entry to that actual post-navigation checkpoint, so the
    // next Undo/Redo validates B→A→B→A rather than comparing stale metadata
    // from the entry's original timeline.
    let actual_target = ProjectCheckpoint {
        project: canonical_target_project,
        mappings: target_checkpoint.mappings,
        epoch: coordinator.epoch,
        revision: coordinator.revision,
        hash: coordinator.checkpoint_hash.clone(),
    };
    let adjacent = if undo {
        coordinator.history.undo.last_mut()
    } else {
        coordinator.history.redo.last_mut()
    };
    if let Some(adjacent) = adjacent {
        if undo {
            adjacent.after = actual_target.clone();
        } else {
            adjacent.before = actual_target.clone();
        }
    }
    let entry = rewrite_navigated_project_history_entry(entry, undo, actual_target);
    if undo {
        coordinator.history.redo.push(entry);
    } else {
        coordinator.history.undo.push(entry);
    }
    coordinator.history_generation =
        next_history_generation.expect("a moved history entry preflights its status generation");
    commit_project_authority_publication_after_preflight(
        coordinator,
        next_publication_generation
            .expect("a moved history entry preflights its publication generation"),
        ProjectAuthorityPublicationKind::HistoryNavigation,
    );
    coordinator.mapping_replacement_generation = next_mapping_replacement_generation
        .expect("a moved history entry preflights its mapping replacement generation");
    let history_status = project_history_status_for_coordinator(coordinator);
    let authority = project_authority_bundle_from_coordinator(state, coordinator);
    // The replacement helper intentionally suppressed its normal event: the
    // moved history entry is only complete after it has been rewritten and
    // pushed to the opposite stack. Emit exactly that final paired image.
    replacement_result.project_epoch = authority.project_epoch;
    replacement_result.project_revision = authority.project_revision;
    replacement_result.history_generation = authority.history_generation;
    replacement_result.checkpoint_hash = authority.checkpoint_hash.clone();
    replacement_result.authority_disposition_generation =
        authority.authority_disposition_generation;
    replacement_result.authority_disposition = authority.authority_disposition;
    replacement_result.current_project_path = authority.current_project_path.clone();
    replacement_result.authority = Some(authority.clone());
    if let Ok(app) = project_swap_app_handle(state) {
        let _ = app.emit(PROJECT_AUTHORITY_REPLACED_EVENT, replacement_result);
    }
    Ok(ProjectHistoryNavigationResult {
        history_status,
        authority,
    })
}

/// A navigation publication increments coordinator revision. Rewrite the side
/// that will be used as the next navigation source to that exact post-publish
/// checkpoint; otherwise B→Undo(A)→Redo(B) would compare a stale A/B token.
fn rewrite_navigated_project_history_entry(
    mut entry: ProjectHistoryEntry,
    undo: bool,
    actual_target: ProjectCheckpoint,
) -> ProjectHistoryEntry {
    if undo {
        entry.before = actual_target;
    } else {
        entry.after = actual_target;
    }
    entry
}

#[tauri::command]
fn undo_project_transaction(
    window: WebviewWindow,
    state: State<'_, AppState>,
    owner_id: String,
    expected_epoch: u64,
    expected_entry_id: u64,
    expected_checkpoint_hash: String,
) -> Result<ProjectHistoryNavigationResult, String> {
    navigate_project_history(
        &state,
        window.label(),
        &owner_id,
        true,
        Some(expected_epoch),
        Some(expected_entry_id),
        Some(expected_checkpoint_hash),
    )
}

#[tauri::command]
fn redo_project_transaction(
    window: WebviewWindow,
    state: State<'_, AppState>,
    owner_id: String,
    expected_epoch: u64,
    expected_entry_id: u64,
    expected_checkpoint_hash: String,
) -> Result<ProjectHistoryNavigationResult, String> {
    navigate_project_history(
        &state,
        window.label(),
        &owner_id,
        false,
        Some(expected_epoch),
        Some(expected_entry_id),
        Some(expected_checkpoint_hash),
    )
}

fn app_data_subdirectory_path(app: &tauri::AppHandle, name: &str) -> Result<PathBuf, String> {
    let directory = app
        .path()
        .app_local_data_dir()
        .map_err(|error| format!("Unable to resolve Syndocal application data: {error}"))?
        .join(name);
    Ok(directory)
}

fn app_data_subdirectory(app: &tauri::AppHandle, name: &str) -> Result<PathBuf, String> {
    let directory = app_data_subdirectory_path(app, name)?;
    fs::create_dir_all(&directory)
        .map_err(|error| format!("Unable to create {}: {error}", directory.display()))?;
    Ok(directory)
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct PersistedOutputOwnershipState {
    version: u32,
    role: MachineOutputRole,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct PersistedProjectRecoveryAuthorityState {
    version: u32,
    serial: u64,
    #[serde(default)]
    last_transition: ProjectRecoveryAuthorityTransition,
    /// Two-phase durable Save intent.  Present only between a pending CleanSave
    /// journal write and its commit/rollback.  `#[serde(default)]` plus
    /// `skip_serializing_if` keep every no-pending record byte-identical to the
    /// original v1 journal, so existing files deserialize unchanged and files
    /// this build writes without a pending stay readable by older builds.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pending_clean_save: Option<PendingProjectCleanSave>,
    #[serde(
        default,
        skip_serializing_if = "PersistedProjectPublicationJournalV1::is_empty"
    )]
    publication_journal: PersistedProjectPublicationJournalV1,
}

/// Durable binding that lets startup decide, without metadata/time heuristics,
/// whether an interrupted CleanSave actually replaced its target.  The digest is
/// taken over the exact prepared file bytes that were about to be atomically
/// renamed onto `target_path`; an exact re-hash of the target after restart is
/// the only evidence that the intended save landed.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct PendingProjectCleanSave {
    /// Committed recovery serial this CleanSave publishes once the replace is
    /// proven durable (the S+1 that must not be observed until then).
    serial: u64,
    /// Normalized, canonical-parent target path suitable for an exact reopen on
    /// restart, so a Windows path alias cannot hide or misidentify the target.
    /// Stored as a `PathBuf` and serialized through serde's `PathBuf`
    /// implementation, so a valid path round-trips exactly.  A non-Unicode path
    /// is reported as an encode error at journal-write time rather than being
    /// silently corrupted by `to_string_lossy` (which maps invalid units to
    /// U+FFFD and could even alias two distinct targets onto one key).
    target_path: PathBuf,
    /// SHA-256 hex digest of the exact prepared bytes destined for `target_path`.
    digest: String,
}

fn validate_pending_project_clean_save(
    committed_serial: u64,
    pending: &PendingProjectCleanSave,
) -> Result<(), String> {
    let expected = committed_serial.checked_add(1).ok_or_else(|| {
        "Project recovery authority journal has a pending CleanSave after an exhausted serial"
            .to_string()
    })?;
    if pending.serial != expected {
        return Err(format!(
            "Project recovery authority journal has invalid pending CleanSave serial {} (expected {expected})",
            pending.serial
        ));
    }
    if pending.digest.len() != 64
        || !pending
            .digest
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    {
        return Err(
            "Project recovery authority journal has an invalid pending CleanSave SHA-256 digest"
                .to_string(),
        );
    }
    if !pending.target_path.is_absolute() || pending.target_path.file_name().is_none() {
        return Err(format!(
            "Project recovery authority journal has an invalid pending CleanSave target path: {}",
            pending.target_path.display()
        ));
    }
    Ok(())
}

fn validate_project_publication_origin_id(origin: &str) -> Result<(), String> {
    if origin != origin.trim()
        || origin.is_empty()
        || origin.len() > 96
        || !origin
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
    {
        return Err(
            "Project publication origin must contain 1-96 ASCII letters, digits, '-' or '_'"
                .to_string(),
        );
    }
    Ok(())
}

fn validate_project_publication_request_v1(
    request: &ProjectPublicationRequestV1,
) -> Result<(), String> {
    if request.schema_version != PROJECT_PUBLICATION_REQUEST_SCHEMA_VERSION {
        return Err(format!(
            "Unsupported project publication request schema version {}",
            request.schema_version
        ));
    }
    validate_project_publication_origin_id(&request.origin_id)?;
    if normalize_project_transaction_owner_id(request.owner_id.clone())? != request.owner_id {
        return Err("Project publication owner ID must already be canonical".to_string());
    }
    if request.request_id == 0 || request.request_id > VIDEO_CLIP_RUNTIME_GENERATION_MAX {
        return Err("Project publication request ID is outside the safe range".to_string());
    }
    if request.expected_project_epoch > VIDEO_CLIP_RUNTIME_GENERATION_MAX
        || request.expected_project_revision > VIDEO_CLIP_RUNTIME_GENERATION_MAX
    {
        return Err("Project publication authority is outside the safe range".to_string());
    }
    validate_project_publication_shape_hash(&request.expected_checkpoint_hash)?;
    validate_project_publication_shape_hash(&request.mapping_authority_hash)?;
    let expected_policy = match request.surface {
        ProjectPublicationSurfaceV1::Save => ProjectPublicationTargetPolicyV1::CurrentOrDialog,
        ProjectPublicationSurfaceV1::SaveAs | ProjectPublicationSurfaceV1::UserTemplate => {
            ProjectPublicationTargetPolicyV1::Dialog
        }
        ProjectPublicationSurfaceV1::Backup => ProjectPublicationTargetPolicyV1::ManagedUnique,
    };
    if request.target_policy != expected_policy {
        return Err("Project publication target policy does not match its surface".to_string());
    }
    if request
        .source_path
        .as_ref()
        .is_some_and(|path| path.len() > 4096)
        || request
            .reason
            .as_ref()
            .is_some_and(|reason| reason.len() > 160)
    {
        return Err("Project publication request metadata is too long".to_string());
    }
    Ok(())
}

fn normalize_project_publication_request_v1(
    request: ProjectPublicationRequestV1,
) -> Result<ProjectPublicationRequestV1, String> {
    if let Some(reason) = request.reason.as_deref() {
        if reason != reason.trim() || reason.is_empty() || reason.chars().count() > 80 {
            return Err(
                "Project publication reason must be canonical, nonempty, and at most 80 characters"
                    .to_string(),
            );
        }
    }
    if let Some(source_path) = request.source_path.as_deref() {
        let source = Path::new(source_path);
        if !source.is_absolute()
            || source
                .components()
                .any(|component| matches!(component, std::path::Component::ParentDir))
            || !is_syndocal_project_path(source)
        {
            return Err(
                "Project publication source path must be an absolute canonical .sdc path"
                    .to_string(),
            );
        }
    }
    validate_project_publication_request_v1(&request)?;
    Ok(request)
}

fn validate_project_publication_shape_hash(shape_hash: &str) -> Result<(), String> {
    if shape_hash.len() != 64
        || !shape_hash
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    {
        return Err("Project publication shape hash is invalid".to_string());
    }
    Ok(())
}

fn validate_project_publication_target_path_v1(
    surface: ProjectPublicationSurfaceV1,
    path: &Path,
) -> Result<(), String> {
    if !path.is_absolute() || path.file_name().is_none() {
        return Err("Project publication target path must be absolute".to_string());
    }
    let expected_extension = match surface {
        ProjectPublicationSurfaceV1::Save | ProjectPublicationSurfaceV1::SaveAs => "sdc",
        ProjectPublicationSurfaceV1::UserTemplate => "sdctemplate",
        ProjectPublicationSurfaceV1::Backup => "json",
    };
    if path.extension() != Some(OsStr::new(expected_extension)) {
        return Err(format!(
            "Project publication target must use the .{expected_extension} extension"
        ));
    }
    Ok(())
}

fn validate_project_publication_journal_v1(
    journal: &PersistedProjectPublicationJournalV1,
) -> Result<(), String> {
    if journal.origins.len() > MAX_PROJECT_PUBLICATION_ORIGINS
        || journal.pending.len() > MAX_PROJECT_PUBLICATION_PENDING
        || journal.terminals.len() > MAX_PROJECT_PUBLICATION_TERMINALS
    {
        return Err("Project publication receipt journal exceeds its bounded capacity".to_string());
    }
    for (index, origin) in journal.origins.iter().enumerate() {
        validate_project_publication_origin_id(&origin.origin_id)?;
        if origin.high_water_request_id == 0
            || origin.high_water_request_id > VIDEO_CLIP_RUNTIME_GENERATION_MAX
        {
            return Err(
                "Project publication receipt journal origin is outside the safe range".to_string(),
            );
        }
        if origin.acknowledged_request_id > origin.high_water_request_id
            || origin.acknowledged_request_id > VIDEO_CLIP_RUNTIME_GENERATION_MAX
            || (origin.acknowledged_request_id == 0) != origin.acknowledged_shape_hash.is_none()
        {
            return Err(
                "Project publication receipt journal has an invalid acknowledgement tombstone"
                    .to_string(),
            );
        }
        if let Some(shape_hash) = origin.acknowledged_shape_hash.as_deref() {
            validate_project_publication_shape_hash(shape_hash)?;
        }
        if journal.origins[index + 1..]
            .iter()
            .any(|other| other.origin_id == origin.origin_id)
        {
            return Err("Project publication receipt journal has duplicate origins".to_string());
        }
    }
    let mut seen = HashSet::new();
    for pending in &journal.pending {
        validate_project_publication_request_v1(&pending.request)?;
        validate_project_publication_shape_hash(&pending.shape_hash)?;
        if project_publication_shape_hash_v1(&pending.request)? != pending.shape_hash
            || pending.request.surface != pending.surface
        {
            return Err("Project publication pending receipt has a noncanonical shape".to_string());
        }
        if pending.reservation_generation == 0
            || pending.reservation_generation > journal.latest_reservation_generation
        {
            return Err(
                "Project publication pending receipt has an invalid reservation generation"
                    .to_string(),
            );
        }
        let expected_clean_save_serial = if matches!(
            pending.surface,
            ProjectPublicationSurfaceV1::Save | ProjectPublicationSurfaceV1::SaveAs
        ) {
            Some(
                pending
                    .recovery_authority_serial_before
                    .checked_add(1)
                    .ok_or_else(|| {
                        "Project publication pending receipt exhausted its recovery serial"
                            .to_string()
                    })?,
            )
        } else {
            None
        };
        if pending.expected_recovery_authority_serial_after != expected_clean_save_serial {
            return Err(
                "Project publication pending receipt has an invalid recovery serial fence"
                    .to_string(),
            );
        }
        let selected = matches!(
            pending.phase,
            ProjectPublicationPendingPhaseV1::Selected | ProjectPublicationPendingPhaseV1::Prepared
        );
        if selected != pending.target_path.is_some() {
            return Err(
                "Project publication pending receipt has inconsistent target selection".to_string(),
            );
        }
        if let Some(staging) = pending.staging_path.as_deref() {
            let target = pending.target_path.as_deref().ok_or_else(|| {
                "Project publication pending receipt has staging without a target".to_string()
            })?;
            let target_parent = target.parent().ok_or_else(|| {
                "Project publication target has no parent for staging".to_string()
            })?;
            let target_name = target.file_name().and_then(OsStr::to_str).ok_or_else(|| {
                "Project publication target has no filename for staging".to_string()
            })?;
            let staging_name = staging
                .file_name()
                .and_then(OsStr::to_str)
                .ok_or_else(|| "Project publication staging path has no filename".to_string())?;
            if staging.parent() != Some(target_parent)
                || !staging_name.starts_with(&format!(".{target_name}."))
                || !staging_name.ends_with(".tmp")
            {
                return Err(
                    "Project publication pending receipt has an unsafe staging path".to_string(),
                );
            }
        }
        let prepared = pending.phase == ProjectPublicationPendingPhaseV1::Prepared;
        if prepared != pending.prepared_digest.is_some() {
            return Err(
                "Project publication pending receipt has inconsistent prepared digest".to_string(),
            );
        }
        if prepared && pending.staging_path.is_none() {
            return Err(
                "Prepared project publication is missing its durable staging path".to_string(),
            );
        }
        if let Some(digest) = pending.prepared_digest.as_deref() {
            validate_project_publication_shape_hash(digest)?;
        }
        if pending
            .indeterminate_error
            .as_deref()
            .is_some_and(str::is_empty)
            || (pending.indeterminate_error.is_some()
                && pending.phase != ProjectPublicationPendingPhaseV1::Prepared)
        {
            return Err(
                "Project publication pending receipt has an invalid indeterminate fault"
                    .to_string(),
            );
        }
        if let Some(path) = pending.target_path.as_deref() {
            validate_project_publication_target_path_v1(pending.surface, path)?;
        }
        let key = (
            pending.request.origin_id.clone(),
            pending.request.request_id,
        );
        if !seen.insert(key) {
            return Err("Project publication receipt journal has duplicate requests".to_string());
        }
    }
    for terminal in &journal.terminals {
        validate_project_publication_request_v1(&terminal.request)?;
        validate_project_publication_shape_hash(&terminal.shape_hash)?;
        if project_publication_shape_hash_v1(&terminal.request)? != terminal.shape_hash
            || terminal.request.surface != terminal.surface
        {
            return Err(
                "Project publication terminal receipt has a noncanonical shape".to_string(),
            );
        }
        if let Some(path) = terminal.target_path.as_deref() {
            validate_project_publication_target_path_v1(terminal.surface, Path::new(path))?;
        }
        match terminal.outcome {
            ProjectPublicationTerminalOutcomeV1::Succeeded => {
                if terminal.target_path.is_none() {
                    return Err(
                        "Successful project publication terminal is missing its target".to_string(),
                    );
                }
                let artifact_digest = terminal.artifact_digest.as_deref().ok_or_else(|| {
                    "Successful project publication terminal is missing its artifact digest"
                        .to_string()
                })?;
                validate_project_publication_shape_hash(artifact_digest)?;
                if terminal
                    .warning
                    .as_deref()
                    .is_some_and(|warning| warning.is_empty() || warning.len() > 512)
                {
                    return Err(
                        "Successful project publication terminal has an invalid warning"
                            .to_string(),
                    );
                }
            }
            ProjectPublicationTerminalOutcomeV1::Cancelled
            | ProjectPublicationTerminalOutcomeV1::Abandoned => {
                if terminal.target_path.is_some()
                    || terminal.backup.is_some()
                    || terminal.artifact_digest.is_some()
                    || terminal.error.is_some()
                    || terminal.warning.is_some()
                {
                    return Err(
                        "Cancelled project publication terminal contains publication data"
                            .to_string(),
                    );
                }
            }
            ProjectPublicationTerminalOutcomeV1::Failed
            | ProjectPublicationTerminalOutcomeV1::Indeterminate => {
                if terminal.error.as_deref().is_none_or(str::is_empty) {
                    return Err(
                        "Failed project publication terminal is missing its error".to_string()
                    );
                }
                if terminal.artifact_digest.is_some() {
                    return Err(
                        "Failed project publication terminal contains an artifact digest"
                            .to_string(),
                    );
                }
                if terminal.warning.is_some() {
                    return Err(
                        "Failed project publication terminal contains a success warning"
                            .to_string(),
                    );
                }
            }
        }
        if terminal.surface == ProjectPublicationSurfaceV1::Backup {
            if terminal.outcome == ProjectPublicationTerminalOutcomeV1::Succeeded
                && terminal.backup.is_none()
            {
                return Err("Successful backup terminal is missing its summary".to_string());
            }
        } else if terminal.backup.is_some() {
            return Err("Non-backup project publication contains a backup summary".to_string());
        }
        let key = (
            terminal.request.origin_id.clone(),
            terminal.request.request_id,
        );
        if !seen.insert(key) {
            return Err("Project publication receipt journal has duplicate requests".to_string());
        }
    }
    for (origin_id, request_id) in seen {
        let origin = journal
            .origins
            .iter()
            .find(|origin| origin.origin_id == origin_id)
            .ok_or_else(|| {
                "Project publication receipt journal has a request without an origin".to_string()
            })?;
        if request_id > origin.high_water_request_id {
            return Err(
                "Project publication receipt journal high-water mark is behind a request"
                    .to_string(),
            );
        }
    }
    Ok(())
}

fn output_ownership_state_path(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    app.path()
        .app_local_data_dir()
        .map(|directory| directory.join(OUTPUT_OWNERSHIP_STATE_FILE))
        .map_err(|error| format!("Unable to resolve Syndocal output ownership state path: {error}"))
}

fn output_lease_receipt_state_path(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    app.path()
        .app_local_data_dir()
        .map(|directory| directory.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE))
        .map_err(|error| {
            format!("Unable to resolve Syndocal output-lease receipt state path: {error}")
        })
}

fn validate_output_lease_receipt_state(
    state: &PersistedOutputLeaseReceiptState,
) -> Result<(), String> {
    if state.version != OUTPUT_LEASE_DURABLE_RECEIPT_STATE_VERSION {
        return Err(format!(
            "Unsupported output-lease receipt state version {}",
            state.version
        ));
    }
    if state.receipts.len() > MAX_DURABLE_OUTPUT_LEASE_RECEIPTS {
        return Err(format!(
            "Output-lease receipt state exceeds {} retained records",
            MAX_DURABLE_OUTPUT_LEASE_RECEIPTS
        ));
    }
    if state.origins.len() > MAX_DURABLE_OUTPUT_LEASE_ORIGINS {
        return Err(format!(
            "Output-lease receipt state exceeds {} request origins",
            MAX_DURABLE_OUTPUT_LEASE_ORIGINS
        ));
    }
    if state.pending.len() > MAX_DURABLE_OUTPUT_LEASE_RECEIPTS {
        return Err(format!(
            "Output-lease receipt state exceeds {} pending records",
            MAX_DURABLE_OUTPUT_LEASE_RECEIPTS
        ));
    }
    if state.dsf2026_artnet_acceptance_probe_terminals.len()
        > MAX_DURABLE_DSF2026_OUTPUT_CONTROL_TERMINALS
    {
        return Err(format!(
            "Output-lease receipt state exceeds {} DSF2026 public terminal records",
            MAX_DURABLE_DSF2026_OUTPUT_CONTROL_TERMINALS
        ));
    }
    if state.managed_exact_both_output_control_terminals.len()
        > MAX_DURABLE_MANAGED_EXACT_BOTH_OUTPUT_CONTROL_TERMINALS
    {
        return Err(format!(
            "Output-lease receipt state exceeds {} managed exact-Both public terminal records",
            MAX_DURABLE_MANAGED_EXACT_BOTH_OUTPUT_CONTROL_TERMINALS
        ));
    }
    for (index, terminal) in state
        .dsf2026_artnet_acceptance_probe_terminals
        .iter()
        .enumerate()
    {
        OutputLeaseOwner::new(&terminal.principal, &terminal.window_label, 1, 1).map_err(|_| {
            format!(
                "Output-lease receipt state has invalid DSF2026 terminal caller at index {index}"
            )
        })?;
        terminal.response.validate().map_err(|_| {
            format!(
                "Output-lease receipt state has invalid DSF2026 terminal response at index {index}"
            )
        })?;
        let OutputControlResponseV2::Receipt(receipt) = &terminal.response else {
            return Err(format!(
                "Output-lease receipt state has non-receipt DSF2026 terminal at index {index}"
            ));
        };
        if !is_dsf2026_artnet_acceptance_probe_operation(&receipt.operation_id) {
            return Err(format!(
                "Output-lease receipt state has unexpected DSF2026 terminal operation at index {index}"
            ));
        }
        let expected_private_domain = match receipt.operation_id.as_str() {
            OUTPUT_DSF2026_ARTNET_ACCEPTANCE_PROBE_OPERATION_ID => {
                OUTPUT_LEASE_DSF2026_PROBE_DOMAIN
            }
            OUTPUT_DSF2026_ARTNET_ACCEPTANCE_PROBE_RECONCILE_OPERATION_ID => {
                OUTPUT_LEASE_DSF2026_PROBE_RECONCILE_DOMAIN
            }
            _ => unreachable!("validated DSF2026 operation"),
        };
        if !state.receipts.iter().any(|private_receipt| {
            private_receipt.key.principal == terminal.principal
                && private_receipt.key.domain == expected_private_domain
                && private_receipt.key.request_id == receipt.request_id
        }) {
            return Err(format!(
                "Output-lease receipt state has DSF2026 public terminal without its private receipt at index {index}"
            ));
        }
        if state.dsf2026_artnet_acceptance_probe_terminals[index + 1..]
            .iter()
            .any(|other| {
                other.principal == terminal.principal
                    && other.window_label == terminal.window_label
                    && matches!(
                        &other.response,
                        OutputControlResponseV2::Receipt(other_receipt)
                            if other_receipt.operation_id == receipt.operation_id
                                && other_receipt.request_id == receipt.request_id
                    )
            })
        {
            return Err(
                "Output-lease receipt state has duplicate DSF2026 public terminals".to_string(),
            );
        }
    }
    if !state.dsf2026_artnet_acceptance_probe_terminals.is_empty()
        && !state.dsf2026_artnet_acceptance_probe_consumed
    {
        return Err(
            "Output-lease receipt state has DSF2026 public terminal without consumed budget"
                .to_string(),
        );
    }
    for (index, terminal) in state
        .managed_exact_both_output_control_terminals
        .iter()
        .enumerate()
    {
        OutputLeaseOwner::new(&terminal.principal, &terminal.window_label, 1, 1).map_err(|_| {
            format!(
                "Output-lease receipt state has invalid managed exact-Both terminal caller at index {index}"
            )
        })?;
        terminal.response.validate().map_err(|_| {
            format!(
                "Output-lease receipt state has invalid managed exact-Both terminal response at index {index}"
            )
        })?;
        let OutputControlResponseV2::Receipt(receipt) = &terminal.response else {
            return Err(format!(
                "Output-lease receipt state has non-receipt managed exact-Both terminal at index {index}"
            ));
        };
        if !is_managed_exact_both_output_control_replay_operation(&receipt.operation_id) {
            return Err(format!(
                "Output-lease receipt state has unexpected managed exact-Both terminal operation at index {index}"
            ));
        }
        if !state.receipts.iter().any(|lease_receipt| {
            lease_receipt.key.principal == terminal.principal
                && lease_receipt.key.domain == OUTPUT_LEASE_OUTPUT_CONTROL_DOMAIN
                && lease_receipt.key.request_id == receipt.request_id
        }) {
            return Err(format!(
                "Output-lease receipt state has managed exact-Both public terminal without its canonical public lease receipt at index {index}"
            ));
        }
        if state.managed_exact_both_output_control_terminals[index + 1..]
            .iter()
            .any(|other| {
                other.principal == terminal.principal
                    && other.window_label == terminal.window_label
                    && matches!(
                        &other.response,
                        OutputControlResponseV2::Receipt(other_receipt)
                            if other_receipt.operation_id == receipt.operation_id
                                && other_receipt.request_id == receipt.request_id
                    )
            })
        {
            return Err(
                "Output-lease receipt state has duplicate managed exact-Both public terminals"
                    .to_string(),
            );
        }
    }
    if state
        .receipts
        .iter()
        .any(|receipt| receipt.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN)
        && !state.dsf2026_artnet_acceptance_probe_consumed
    {
        return Err(
            "Output-lease receipt state has DSF2026 physical receipt without consumed budget"
                .to_string(),
        );
    }
    for (index, origin) in state.origins.iter().enumerate() {
        let origin_key = output_lease::OutputLeaseRequestKey::new(
            origin.principal.clone(),
            origin.domain.clone(),
            origin.high_water_request_id,
        )
        .map_err(|error| {
            format!(
                "Output-lease receipt state has invalid request origin at index {index}: {error:?}"
            )
        })?;
        output_lease::validate_persisted_request_key(&origin_key).map_err(|error| {
            format!(
                "Output-lease receipt state has invalid request origin at index {index}: {error:?}"
            )
        })?;
        if state.origins[index + 1..]
            .iter()
            .any(|other| other.principal == origin.principal && other.domain == origin.domain)
        {
            return Err("Output-lease receipt state has duplicate request origins".to_string());
        }
    }
    for (index, receipt) in state.receipts.iter().enumerate() {
        output_lease::validate_persisted_receipt(receipt).map_err(|error| {
            format!("Output-lease receipt state has invalid receipt at index {index}: {error:?}")
        })?;
        if state.receipts[index + 1..]
            .iter()
            .any(|other| other.key == receipt.key)
        {
            return Err("Output-lease receipt state has duplicate request receipts".to_string());
        }
        let Some(origin) = state.origins.iter().find(|origin| {
            origin.principal == receipt.key.principal && origin.domain == receipt.key.domain
        }) else {
            return Err(format!(
                "Output-lease receipt state has receipt without origin for request {}",
                receipt.key.request_id
            ));
        };
        if receipt.key.request_id > origin.high_water_request_id {
            return Err(format!(
                "Output-lease receipt state high-water mark is behind request {}",
                receipt.key.request_id
            ));
        }
    }
    for (index, pending) in state.pending.iter().enumerate() {
        output_lease::validate_persisted_request_key(&pending.key).map_err(|error| {
            format!(
                "Output-lease receipt state has invalid pending request at index {index}: {error:?}"
            )
        })?;
        output_lease::validate_persisted_shape_hash(&pending.shape_hash).map_err(|error| {
            format!(
                "Output-lease receipt state has invalid pending shape at index {index}: {error:?}"
            )
        })?;
        if state.pending[index + 1..]
            .iter()
            .any(|other| other.key == pending.key)
        {
            return Err("Output-lease receipt state has duplicate pending requests".to_string());
        }
        if state
            .receipts
            .iter()
            .any(|receipt| receipt.key == pending.key)
        {
            return Err(
                "Output-lease receipt state has terminal and pending duplicate".to_string(),
            );
        }
        let Some(origin) = state.origins.iter().find(|origin| {
            origin.principal == pending.key.principal && origin.domain == pending.key.domain
        }) else {
            return Err(format!(
                "Output-lease receipt state has pending request without origin {}",
                pending.key.request_id
            ));
        };
        if state.pending[index + 1..].iter().any(|other| {
            other.key.principal == pending.key.principal && other.key.domain == pending.key.domain
        }) {
            return Err(
                "Output-lease receipt state has multiple pending requests for one origin"
                    .to_string(),
            );
        }
        if pending.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN {
            let Some(window_label) = pending.window_label.as_deref() else {
                return Err(
                    "Output-lease receipt state has DSF2026 Pending without its local window label"
                        .to_string(),
                );
            };
            OutputLeaseOwner::new(&pending.key.principal, window_label, 1, 1).map_err(|_| {
                format!(
                    "Output-lease receipt state has invalid DSF2026 Pending local window at index {index}"
                )
            })?;
            if state.pending[index + 1..]
                .iter()
                .any(|other| other.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN)
            {
                return Err(
                    "Output-lease receipt state has multiple DSF2026 Pending records".to_string(),
                );
            }
        } else if pending.window_label.is_some() {
            return Err(
                "Output-lease receipt state has a local window label on a non-DSF Pending record"
                    .to_string(),
            );
        }
        if pending.key.request_id > origin.high_water_request_id {
            return Err(format!(
                "Output-lease receipt state high-water mark is behind pending request {}",
                pending.key.request_id
            ));
        }
    }
    for origin in &state.origins {
        let retained_receipts = state.receipts.iter().filter(|receipt| {
            receipt.key.principal == origin.principal && receipt.key.domain == origin.domain
        });
        let max_retained_request_id = retained_receipts
            .map(|receipt| receipt.key.request_id)
            .max();
        let has_pending = state.pending.iter().any(|pending| {
            pending.key.principal == origin.principal && pending.key.domain == origin.domain
        });
        if !origin.replay_guard
            && (has_pending || max_retained_request_id != Some(origin.high_water_request_id))
        {
            return Err(format!(
                "Output-lease receipt state has an unguarded origin with incomplete terminal evidence {}",
                origin.high_water_request_id
            ));
        }
    }
    Ok(())
}

/// Migrate the durable journal only when its physical meaning can be
/// preserved. Version 1 did not bind DSF2026 Pending to a local window, so a
/// restart cannot safely decide who may acknowledge that unobservable send.
/// Refuse that one ambiguous legacy state rather than assigning it to a new
/// renderer principal or re-enabling a probe.
fn migrate_output_lease_receipt_state_to_current(
    state: &mut PersistedOutputLeaseReceiptState,
) -> Result<bool, String> {
    match state.version {
        OUTPUT_LEASE_DURABLE_RECEIPT_STATE_VERSION => Ok(false),
        1 => {
            if state
                .pending
                .iter()
                .any(|pending| pending.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN)
            {
                return Err(
                    "Legacy DSF2026 Pending receipt lacks a fixed local window label; restart refuses reconciliation and any new probe"
                        .to_string(),
                );
            }
            // Version 1 stored some successful fixed probe receipts before
            // the global marker was made explicit. Retain the one-shot budget
            // during this safe migration rather than relying on in-memory
            // upgrade behavior.
            state.dsf2026_artnet_acceptance_probe_consumed |= state
                .receipts
                .iter()
                .any(|receipt| receipt.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN);
            state.version = OUTPUT_LEASE_DURABLE_RECEIPT_STATE_VERSION;
            Ok(true)
        }
        version => Err(format!(
            "Unsupported output-lease receipt state version {version}"
        )),
    }
}

fn load_output_lease_receipt_state_from_path(
    path: &Path,
) -> Result<PersistedOutputLeaseReceiptState, String> {
    let file = match fs::File::open(path) {
        Ok(file) => file,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Ok(PersistedOutputLeaseReceiptState::default())
        }
        Err(error) => {
            return Err(format!(
                "Unable to read output-lease receipt state {}: {error}",
                path.display()
            ))
        }
    };
    let declared_len = file
        .metadata()
        .map_err(|error| {
            format!(
                "Unable to inspect output-lease receipt state {}: {error}",
                path.display()
            )
        })?
        .len();
    if declared_len > MAX_OUTPUT_LEASE_DURABLE_RECEIPT_STATE_BYTES {
        return Err(format!(
            "Output-lease receipt state {} exceeds the {} byte safety limit",
            path.display(),
            MAX_OUTPUT_LEASE_DURABLE_RECEIPT_STATE_BYTES
        ));
    }
    let read_limit = MAX_OUTPUT_LEASE_DURABLE_RECEIPT_STATE_BYTES
        .checked_add(1)
        .ok_or_else(|| "Output-lease receipt state byte limit is exhausted".to_string())?;
    let capacity = usize::try_from(declared_len.min(read_limit)).map_err(|_| {
        "Output-lease receipt state size cannot be represented on this platform".to_string()
    })?;
    let mut bytes = Vec::with_capacity(capacity);
    file.take(read_limit)
        .read_to_end(&mut bytes)
        .map_err(|error| {
            format!(
                "Unable to read output-lease receipt state {}: {error}",
                path.display()
            )
        })?;
    if bytes.len() as u64 > MAX_OUTPUT_LEASE_DURABLE_RECEIPT_STATE_BYTES {
        return Err(format!(
            "Output-lease receipt state {} grew beyond the {} byte safety limit",
            path.display(),
            MAX_OUTPUT_LEASE_DURABLE_RECEIPT_STATE_BYTES
        ));
    }
    let raw_state: serde_json::Value = serde_json::from_slice(&bytes).map_err(|error| {
        format!(
            "Output-lease receipt state {} is corrupt: {error}",
            path.display()
        )
    })?;
    let mut state: PersistedOutputLeaseReceiptState = serde_json::from_value(raw_state.clone())
        .map_err(|error| {
            format!(
                "Output-lease receipt state {} is corrupt: {error}",
                path.display()
            )
        })?;
    // `replay_guard` was added additively.  Preserve an explicitly serialized
    // value exactly; only synthesize a value for an older journal that has no
    // field.  A legacy origin is guarded when its high-water mark is ahead of
    // every retained request, or while a legacy Pending marker exists.  This
    // is conservative for an evicted terminal or an in-doubt physical attempt
    // without making ordinary retained receipts permanently uncollectable.
    let raw_origins = raw_state
        .get("origins")
        .and_then(serde_json::Value::as_array);
    for (index, origin) in state.origins.iter_mut().enumerate() {
        let has_explicit_guard = raw_origins
            .and_then(|origins| origins.get(index))
            .and_then(serde_json::Value::as_object)
            .is_some_and(|value| value.contains_key("replay_guard"));
        if has_explicit_guard {
            continue;
        }
        let max_retained_request_id = state
            .receipts
            .iter()
            .filter(|receipt| {
                receipt.key.principal == origin.principal && receipt.key.domain == origin.domain
            })
            .map(|receipt| receipt.key.request_id)
            .chain(state.pending.iter().filter_map(|pending| {
                (pending.key.principal == origin.principal && pending.key.domain == origin.domain)
                    .then_some(pending.key.request_id)
            }))
            .max()
            .unwrap_or(0);
        let has_pending = state.pending.iter().any(|pending| {
            pending.key.principal == origin.principal && pending.key.domain == origin.domain
        });
        origin.replay_guard = has_pending || origin.high_water_request_id > max_retained_request_id;
    }
    let migrated = migrate_output_lease_receipt_state_to_current(&mut state).map_err(|error| {
        format!(
            "Output-lease receipt state {} cannot be safely migrated: {error}",
            path.display()
        )
    })?;
    validate_output_lease_receipt_state(&state).map_err(|error| {
        format!(
            "Output-lease receipt state {} is invalid: {error}",
            path.display()
        )
    })?;
    if migrated {
        persist_output_lease_receipt_state_to_path(path, &state)?;
    }
    Ok(state)
}

fn persist_output_lease_receipt_state_to_path(
    path: &Path,
    state: &PersistedOutputLeaseReceiptState,
) -> Result<(), String> {
    validate_output_lease_receipt_state(state)?;
    let parent = path.parent().ok_or_else(|| {
        format!(
            "Output-lease receipt state path has no parent: {}",
            path.display()
        )
    })?;
    fs::create_dir_all(parent).map_err(|error| {
        format!(
            "Unable to create output-lease receipt state directory {}: {error}",
            parent.display()
        )
    })?;
    let bytes = serde_json::to_vec(state)
        .map_err(|error| format!("Unable to encode output-lease receipt state: {error}"))?;
    if bytes.len() as u64 > MAX_OUTPUT_LEASE_DURABLE_RECEIPT_STATE_BYTES {
        return Err(format!(
            "Output-lease receipt state {} exceeds the {} byte safety limit",
            path.display(),
            MAX_OUTPUT_LEASE_DURABLE_RECEIPT_STATE_BYTES
        ));
    }
    let file_name = path
        .file_name()
        .and_then(OsStr::to_str)
        .unwrap_or(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE);
    let temp = parent.join(format!(
        ".{file_name}.{}.{}.{}.tmp",
        std::process::id(),
        current_unix_ms(),
        PROJECT_SAVE_TEMP_SEQUENCE.fetch_add(1, Ordering::Relaxed),
    ));
    let result = (|| {
        let mut file = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temp)
            .map_err(|error| {
                format!(
                    "Unable to create temporary output-lease receipt state {}: {error}",
                    temp.display()
                )
            })?;
        file.write_all(&bytes).map_err(|error| {
            format!(
                "Unable to write temporary output-lease receipt state {}: {error}",
                temp.display()
            )
        })?;
        file.sync_all().map_err(|error| {
            format!(
                "Unable to flush temporary output-lease receipt state {}: {error}",
                temp.display()
            )
        })?;
        drop(file);
        replace_file_atomically(&temp, path)
    })();
    if result.is_err() {
        let _ = fs::remove_file(&temp);
    }
    result
}

fn project_recovery_authority_state_path(app: &tauri::AppHandle) -> Result<PathBuf, String> {
    app.path()
        .app_local_data_dir()
        .map(|directory| directory.join(PROJECT_RECOVERY_AUTHORITY_STATE_FILE))
        .map_err(|error| {
            format!("Unable to resolve project recovery authority state path: {error}")
        })
}

fn load_project_recovery_authority_state_from_path(
    path: &Path,
) -> Result<PersistedProjectRecoveryAuthorityState, String> {
    let bytes = match fs::read(path) {
        Ok(bytes) if bytes.len() as u64 <= MAX_PROJECT_RECOVERY_AUTHORITY_STATE_BYTES => bytes,
        Ok(_) => {
            return Err(format!(
                "Project recovery authority state {} exceeds the {} byte safety limit",
                path.display(),
                MAX_PROJECT_RECOVERY_AUTHORITY_STATE_BYTES
            ))
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            return Ok(PersistedProjectRecoveryAuthorityState {
                version: PROJECT_RECOVERY_AUTHORITY_STATE_VERSION,
                serial: 0,
                last_transition: ProjectRecoveryAuthorityTransition::LegacyUnknown,
                pending_clean_save: None,
                publication_journal: PersistedProjectPublicationJournalV1::default(),
            });
        }
        Err(error) => {
            return Err(format!(
                "Unable to read project recovery authority state {}: {error}",
                path.display()
            ));
        }
    };
    let state: PersistedProjectRecoveryAuthorityState =
        serde_json::from_slice(&bytes).map_err(|error| {
            format!(
                "Project recovery authority state {} is corrupt: {error}",
                path.display()
            )
        })?;
    if state.version != PROJECT_RECOVERY_AUTHORITY_STATE_VERSION {
        return Err(format!(
            "Unsupported project recovery authority state version {} in {}",
            state.version,
            path.display()
        ));
    }
    if let Some(pending) = state.pending_clean_save.as_ref() {
        validate_pending_project_clean_save(state.serial, pending)?;
    }
    validate_project_publication_journal_v1(&state.publication_journal)?;
    Ok(state)
}

fn persist_project_recovery_authority_serial_to_path(
    path: &Path,
    serial: u64,
    last_transition: ProjectRecoveryAuthorityTransition,
) -> Result<(), String> {
    persist_project_recovery_authority_state_to_path(
        path,
        &PersistedProjectRecoveryAuthorityState {
            version: PROJECT_RECOVERY_AUTHORITY_STATE_VERSION,
            serial,
            last_transition,
            pending_clean_save: None,
            publication_journal: load_project_recovery_authority_state_from_path(path)?
                .publication_journal,
        },
    )
}

/// Durably record a pending CleanSave intent.  The committed serial/transition
/// the coordinator and browser checkpoints observe are written unchanged; only
/// the additive `pending_clean_save` binding is added, so a crash before the
/// target replace leaves the previously eligible recovery serial intact.
fn persist_pending_project_clean_save_to_path(
    path: &Path,
    committed_serial: u64,
    committed_transition: ProjectRecoveryAuthorityTransition,
    pending: PendingProjectCleanSave,
) -> Result<(), String> {
    persist_project_recovery_authority_state_to_path(
        path,
        &PersistedProjectRecoveryAuthorityState {
            version: PROJECT_RECOVERY_AUTHORITY_STATE_VERSION,
            serial: committed_serial,
            last_transition: committed_transition,
            pending_clean_save: Some(pending),
            publication_journal: load_project_recovery_authority_state_from_path(path)?
                .publication_journal,
        },
    )
}

/// Atomically persist the full recovery authority record (serial, transition,
/// and any pending CleanSave).  This is the single durable write seam used by
/// the serial-only wrapper, the pending write, and the commit/rollback steps, so
/// every recovery authority mutation shares the same temp-write + fsync +
/// atomic-rename contract.
fn persist_project_recovery_authority_state_to_path(
    path: &Path,
    state: &PersistedProjectRecoveryAuthorityState,
) -> Result<(), String> {
    if let Some(pending) = state.pending_clean_save.as_ref() {
        validate_pending_project_clean_save(state.serial, pending)?;
    }
    validate_project_publication_journal_v1(&state.publication_journal)?;
    let parent = path.parent().ok_or_else(|| {
        format!(
            "Project recovery authority state path has no parent: {}",
            path.display()
        )
    })?;
    fs::create_dir_all(parent).map_err(|error| {
        format!(
            "Unable to create project recovery authority state directory {}: {error}",
            parent.display()
        )
    })?;
    let bytes = serde_json::to_vec(state)
        .map_err(|error| format!("Unable to encode project recovery authority state: {error}"))?;
    if bytes.len() as u64 > MAX_PROJECT_RECOVERY_AUTHORITY_STATE_BYTES {
        return Err(format!(
            "Project recovery authority state exceeds the {} byte safety limit",
            MAX_PROJECT_RECOVERY_AUTHORITY_STATE_BYTES
        ));
    }
    let file_name = path
        .file_name()
        .and_then(OsStr::to_str)
        .unwrap_or(PROJECT_RECOVERY_AUTHORITY_STATE_FILE);
    let temp = parent.join(format!(
        ".{file_name}.{}.{}.{}.tmp",
        std::process::id(),
        current_unix_ms(),
        PROJECT_SAVE_TEMP_SEQUENCE.fetch_add(1, Ordering::Relaxed),
    ));
    let result = (|| {
        let mut file = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temp)
            .map_err(|error| {
                format!(
                    "Unable to create temporary project recovery authority state {}: {error}",
                    temp.display()
                )
            })?;
        file.write_all(&bytes).map_err(|error| {
            format!(
                "Unable to write temporary project recovery authority state {}: {error}",
                temp.display()
            )
        })?;
        file.sync_all().map_err(|error| {
            format!(
                "Unable to flush temporary project recovery authority state {}: {error}",
                temp.display()
            )
        })?;
        drop(file);
        replace_file_atomically(&temp, path)
    })();
    if result.is_err() {
        let _ = fs::remove_file(&temp);
    }
    result
}

/// Persist before an invalidating publication. If the later publication
/// fails, the advanced serial intentionally remains fail-closed: a still
/// valid older recovery image may be hidden, but it can never be offered for
/// a project authority whose publication may already have committed.
fn prepare_next_project_recovery_authority_serial(
    current: u64,
    last_transition: ProjectRecoveryAuthorityTransition,
    persist: impl FnOnce(u64, ProjectRecoveryAuthorityTransition) -> Result<(), String>,
) -> Result<u64, String> {
    let next = current.checked_add(1).ok_or_else(|| {
        "Project recovery authority serial is exhausted; restart Syndocal before changing project authority"
            .to_string()
    })?;
    persist(next, last_transition)?;
    Ok(next)
}

fn advance_project_recovery_authority_serial_before_publication(
    state: &AppState,
    coordinator: &mut ProjectCoordinator,
    last_transition: ProjectRecoveryAuthorityTransition,
) -> Result<u64, String> {
    let app = project_swap_app_handle(state)?;
    let path = project_recovery_authority_state_path(&app)?;
    advance_project_recovery_authority_serial_with_persist(
        coordinator,
        last_transition,
        |next, transition| {
            persist_project_recovery_authority_serial_to_path(&path, next, transition)
        },
    )
}

/// Exact durable serial/transition commit shared by registered recovery
/// commands and the process-boundary E3 harness. The caller supplies only the
/// persistence destination; checked serial allocation and the live
/// coordinator commit remain the production implementation.
fn advance_project_recovery_authority_serial_with_persist(
    coordinator: &mut ProjectCoordinator,
    last_transition: ProjectRecoveryAuthorityTransition,
    persist: impl FnOnce(u64, ProjectRecoveryAuthorityTransition) -> Result<(), String>,
) -> Result<u64, String> {
    let next = prepare_next_project_recovery_authority_serial(
        coordinator.recovery_authority_serial,
        last_transition.clone(),
        persist,
    )?;
    coordinator.recovery_authority_serial = next;
    coordinator.recovery_authority_last_transition = last_transition;
    Ok(next)
}

/// SHA-256 hex digest, matching the strong-digest style used for project
/// checkpoint hashing.  Kept as a small seam so the two-phase Save journal binds
/// bytes with the same strong digest used elsewhere on the project surface.
fn sha256_hex(bytes: &[u8]) -> String {
    let digest = Sha256::digest(bytes);
    digest.iter().map(|byte| format!("{byte:02x}")).collect()
}

/// Digest the exact prepared bytes that are about to be renamed onto the target.
/// Reading the temp back guarantees the journal binds precisely the bytes the
/// atomic replace will publish, never a separately serialized copy that could
/// drift from what actually lands.
fn strong_prepared_file_digest(path: &Path) -> Result<String, String> {
    let bytes = fs::read(path).map_err(|error| {
        format!(
            "Unable to read prepared project file {} for save journaling: {error}",
            path.display()
        )
    })?;
    Ok(sha256_hex(&bytes))
}

/// Digest the current target bytes for startup reconciliation.  `Ok(None)` means
/// the target is absent (the intended replace did not land); a hard read error
/// is surfaced so reconciliation can stay fail-safe rather than guess whether
/// the exact bytes landed.
fn strong_target_file_digest(path: &Path) -> Result<Option<String>, String> {
    match fs::read(path) {
        Ok(bytes) => Ok(Some(sha256_hex(&bytes))),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
        Err(error) => Err(format!(
            "Unable to read project file {} for recovery reconciliation: {error}",
            path.display()
        )),
    }
}

/// Resolve a target into a normalized, canonical-parent absolute form suitable
/// for an exact reopen after restart.  Canonicalizing the parent (which always
/// exists while a Save is in flight, since the prepared temp was written beside
/// the target) resolves `..`, relative components, and directory symlinks, and
/// on Windows yields an extended-length path, so no path alias can hide or
/// misidentify the target during reconciliation.  The target file itself need
/// not exist yet, so a first Save As to a brand-new path is handled.  The result
/// is returned as a `PathBuf` and persisted through serde's `PathBuf` support,
/// so the exact os-level path (not a `to_string_lossy` approximation) is what
/// reconciliation reopens on restart.
fn normalized_recovery_target_key(path: &Path) -> Result<PathBuf, String> {
    let file_name = path
        .file_name()
        .ok_or_else(|| format!("Project path has no file name: {}", path.display()))?;
    let parent = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty());
    let canonical_parent = match parent {
        Some(parent) => fs::canonicalize(parent).map_err(|error| {
            format!(
                "Unable to resolve project directory {} for save journaling: {error}",
                parent.display()
            )
        })?,
        None => fs::canonicalize(Path::new(".")).map_err(|error| {
            format!("Unable to resolve current directory for save journaling: {error}")
        })?,
    };
    Ok(canonical_parent.join(file_name))
}

/// Startup decision for an interrupted CleanSave, kept pure so every branch is
/// deterministically testable.  Only an exact digest match commits the pending
/// serial; a mismatch or missing target rolls back to the committed serial; an
/// unreadable target is left pending so a healthier later run can decide without
/// ever losing recoverability.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PendingCleanSaveReconciliation {
    Commit,
    Rollback,
    Retain,
}

fn reconcile_pending_clean_save_decision(
    pending_digest: &str,
    target_digest: &Result<Option<String>, String>,
) -> PendingCleanSaveReconciliation {
    match target_digest {
        Ok(Some(actual)) if actual == pending_digest => PendingCleanSaveReconciliation::Commit,
        Ok(_) => PendingCleanSaveReconciliation::Rollback,
        Err(_) => PendingCleanSaveReconciliation::Retain,
    }
}

/// The committed recovery authority a durable CleanSave journal step reached.
#[derive(Debug, Clone, PartialEq, Eq)]
struct CleanSaveJournalCommit {
    serial: u64,
    transition: ProjectRecoveryAuthorityTransition,
}

/// Once the exact prepared bytes have landed, the durable pending record is
/// already sufficient crash evidence for startup to converge to `S+1`. A
/// failure while compacting that pending record into the committed journal
/// must therefore not leave the live coordinator at `S`: subsequent browser
/// recovery captures would be stamped with the obsolete serial and suppressed
/// when startup reconciles the pending save. Log the cleanup failure, but
/// return the landed authority so the caller advances in-memory state now.
fn landed_clean_save_commit(
    pending_serial: u64,
    journal_commit: Result<(), String>,
    context: &str,
) -> CleanSaveJournalCommit {
    if let Err(error) = journal_commit {
        eprintln!(
            "{context}; the exact saved bytes and pending CleanSave serial {pending_serial} are durable, but compacting the recovery journal failed: {error}. Startup will reconcile the retained pending record."
        );
    }
    CleanSaveJournalCommit {
        serial: pending_serial,
        transition: ProjectRecoveryAuthorityTransition::CleanSave,
    }
}

fn rollback_indeterminate_clean_save(
    committed_serial: u64,
    recovery_authority_faulted: &AtomicBool,
    rollback: impl FnOnce() -> Result<(), String>,
) -> Result<(), String> {
    match rollback() {
        Ok(()) => Ok(()),
        Err(error) => {
            recovery_authority_faulted.store(true, Ordering::Release);
            Err(format!(
                "rolling back the pending recovery journal failed: {error}. Project mutation is now blocked until Syndocal restarts and reconciles the target digest (committed serial {committed_serial})"
            ))
        }
    }
}

/// Two-phase durable CleanSave journal shared by `finalize_project_save_ticket`.
///
/// The caller holds save-publication -> external-admission -> coordinator across
/// this whole call, so no concurrent authority publication can interleave the
/// pending write, the target replace, and the commit/rollback.
///
///   1. Preflight the next serial, resolve the exact-reopen target key, and hash
///      the prepared bytes.  None of this changes the committed serial, so a
///      failure here is inert and the target is never touched.
///   2. Persist a PENDING CleanSave: committed serial S is written unchanged, but
///      the journal now binds {S+1, target, digest}.
///   3. Replace the target.
///      - Ok  -> durably commit S+1 CleanSave (clears pending) and report it.
///      - Err -> do NOT blindly roll back.  A spurious or post-rename replace
///        error can still leave the exact prepared bytes on the target, so
///        immediately re-hash the target and compare it to the pending
///        digest:
///       * exact match  -> the bytes DID land, so durably commit S+1
///         CleanSave (never roll a landed save back) and return the
///         committed outcome so the live coordinator advances with the
///         journal. The low-level replace anomaly is logged truthfully.
///       * mismatch/missing -> the bytes did not land, so durably clear
///         pending, retain committed S (dirty-A recovery stays
///         eligible), and return the original replace error.
///       * target unreadable -> keep pending intact and return a
///         compound error so startup reconciliation retries.
///         If the final commit compaction fails after exact bytes landed,
///         pending is left on disk and the live S+1 outcome is still
///         returned; startup reconciles to that same serial. A rollback
///         write failure remains a compound error because bytes did not
///         land and the live authority must stay at S.
fn run_project_clean_save_journal(
    journal_path: &Path,
    committed_serial: u64,
    committed_transition: &ProjectRecoveryAuthorityTransition,
    target_path: &Path,
    prepared_temp: &Path,
    recovery_authority_faulted: &AtomicBool,
    replace_target: impl FnOnce() -> Result<(), String>,
) -> Result<CleanSaveJournalCommit, String> {
    let pending_serial = committed_serial.checked_add(1).ok_or_else(|| {
        "Project recovery authority serial is exhausted; restart Syndocal before saving".to_string()
    })?;
    let target_key = normalized_recovery_target_key(target_path)?;
    let digest = strong_prepared_file_digest(prepared_temp)?;
    // Clone the digest into the pending record so the owned `digest` stays
    // available for post-replace inspection below; it must not be moved away
    // while a failed replace still needs to be compared against the target.
    persist_pending_project_clean_save_to_path(
        journal_path,
        committed_serial,
        committed_transition.clone(),
        PendingProjectCleanSave {
            serial: pending_serial,
            target_path: target_key,
            digest: digest.clone(),
        },
    )?;
    match replace_target() {
        Ok(()) => {
            // Only after the replace is proven does the committed serial advance
            // to S+1; a failure here is truthful and startup-reconcilable because
            // the pending record plus the now-matching target still resolve to
            // this same commit on the next run.
            let journal_commit = persist_project_recovery_authority_serial_to_path(
                journal_path,
                pending_serial,
                ProjectRecoveryAuthorityTransition::CleanSave,
            );
            Ok(landed_clean_save_commit(
                pending_serial,
                journal_commit,
                "Project file replacement completed",
            ))
        }
        Err(replace_error) => {
            // The replace reported failure, but that does not prove the bytes
            // never landed.  Re-hash the target and compare it to the exact
            // pending digest before deciding, so a save whose bytes actually
            // reached disk is committed rather than rolled back.
            let target_digest = strong_target_file_digest(target_path);
            // Bind the decision first so the shared borrow of `target_digest`
            // ends here; the Retain arm then moves the read error out of it.
            let decision = reconcile_pending_clean_save_decision(&digest, &target_digest);
            match decision {
                PendingCleanSaveReconciliation::Commit => {
                    // Exact bytes are present on the target despite the error:
                    // durably commit S+1 CleanSave (which clears pending).  A
                    // landed save must never roll the serial back.  If this
                    // commit write fails, pending is left on disk so startup
                    // reconciliation re-commits from the still-matching target.
                    let journal_commit = persist_project_recovery_authority_serial_to_path(
                        journal_path,
                        pending_serial,
                        ProjectRecoveryAuthorityTransition::CleanSave,
                    );
                    // Exact bytes plus a durable CleanSave journal are the
                    // authoritative success outcome. Returning Err here would
                    // skip the caller's coordinator assignment and leave the
                    // live process at S while disk is already at S+1.
                    eprintln!(
                        "Project save replace reported an error, but the exact saved bytes are present on {target} and CleanSave serial {pending_serial} was durably committed: {replace_error}",
                        target = target_path.display(),
                    );
                    Ok(landed_clean_save_commit(
                        pending_serial,
                        journal_commit,
                        &format!(
                            "{replace_error}; however the exact saved bytes are present on {target}",
                            target = target_path.display(),
                        ),
                    ))
                }
                PendingCleanSaveReconciliation::Rollback => {
                    // Mismatched or missing target: the intended bytes did not
                    // land, so durably clear pending and retain committed S, then
                    // return the original replace error.  If the rollback write
                    // fails, pending is left on disk (a mismatch/missing target
                    // still reconciles to a rollback on the next run).
                    rollback_indeterminate_clean_save(
                        committed_serial,
                        recovery_authority_faulted,
                        || {
                            persist_project_recovery_authority_serial_to_path(
                                journal_path,
                                committed_serial,
                                committed_transition.clone(),
                            )
                        },
                    )
                    .map_err(|rollback_error| format!("{replace_error}; {rollback_error}"))?;
                    Err(replace_error)
                }
                PendingCleanSaveReconciliation::Retain => {
                    // The replace itself reported failure, so prefer preserving
                    // recovery at committed S when the target cannot be read.
                    // If that rollback also fails, the durable pending could
                    // later reconcile either way; latch all mutation/capture
                    // admission until restart resolves it.
                    let read_error = target_digest.err().unwrap_or_default();
                    match rollback_indeterminate_clean_save(
                        committed_serial,
                        recovery_authority_faulted,
                        || {
                            persist_project_recovery_authority_serial_to_path(
                                journal_path,
                                committed_serial,
                                committed_transition.clone(),
                            )
                        },
                    ) {
                        Ok(()) => Err(format!(
                            "{replace_error}; the target {target} could not be read to confirm whether the exact saved bytes landed: {read_error}. Recovery authority was rolled back to serial {committed_serial}; the project remains unsaved.",
                            target = target_path.display(),
                        )),
                        Err(rollback_error) => {
                            Err(format!(
                                "{replace_error}; the target {target} could not be read to classify the Save ({read_error}), and {rollback_error}",
                                target = target_path.display(),
                            ))
                        }
                    }
                }
            }
        }
    }
}

/// Load the recovery authority journal and reconcile any interrupted CleanSave
/// by hashing the exact target bytes.  Used at startup so the committed serial a
/// coordinator adopts already reflects whether an in-flight Save actually
/// landed: an exact match commits S+1 CleanSave, a mismatch or missing target
/// clears pending and retains S, and an unreadable target is a hard error that
/// fails startup truthfully (leaving the pending record durable) rather than
/// silently exposing S while the real outcome is unknown.
fn load_and_reconcile_project_recovery_authority_state_from_path(
    path: &Path,
) -> Result<ProjectRecoveryAuthorityStatus, String> {
    load_and_reconcile_project_recovery_authority_state_with_target_digest(
        path,
        strong_target_file_digest,
    )
}

/// Startup's durable recovery installation boundary. A fresh process adopts
/// only the reconciled serial/tag pair; no prior runtime project image or
/// disposition is inferred from the journal.
fn install_project_recovery_authority_from_path(
    state: &AppState,
    path: &Path,
) -> Result<ProjectRecoveryAuthorityStatus, String> {
    let recovery_authority = load_and_reconcile_project_recovery_authority_state_from_path(path)?;
    let durable = load_project_recovery_authority_state_from_path(path)?;
    let unresolved_publication = durable
        .publication_journal
        .pending
        .iter()
        .any(|pending| pending.phase == ProjectPublicationPendingPhaseV1::Prepared);
    let mut coordinator = state.project_coordinator.lock().map_err(|_| {
        "Project coordinator lock was poisoned during recovery authority initialization".to_string()
    })?;
    coordinator.recovery_authority_serial = recovery_authority.recovery_authority_serial;
    coordinator.recovery_authority_last_transition = recovery_authority.last_transition.clone();
    state
        .project_external_command_admission
        .recovery_authority_faulted
        .store(unresolved_publication, Ordering::Release);
    Ok(recovery_authority)
}

/// Reconciliation core with the target-digest step exposed as an injectable
/// production seam.  Startup passes `strong_target_file_digest`; tests pass a
/// deterministic digest result so the unreadable-target branch can be exercised
/// without relying on flaky per-file ACL manipulation.  The `Retain` decision
/// (a hard target read error) is surfaced as an `Err` that names the target and
/// the underlying read error, and the pending record is intentionally left on
/// disk so a healthier later run can reconcile it.
fn load_and_reconcile_project_recovery_authority_state_with_target_digest(
    path: &Path,
    target_digest: impl FnOnce(&Path) -> Result<Option<String>, String>,
) -> Result<ProjectRecoveryAuthorityStatus, String> {
    let state = load_project_recovery_authority_state_from_path(path)?;
    let Some(pending) = state.pending_clean_save.clone() else {
        return Ok(ProjectRecoveryAuthorityStatus {
            recovery_authority_serial: state.serial,
            last_transition: state.last_transition,
        });
    };
    let target_digest = target_digest(pending.target_path.as_path());
    // Bind the decision first so the shared borrow of `target_digest` ends here;
    // the Retain arm then moves the read error out of it.
    let decision = reconcile_pending_clean_save_decision(&pending.digest, &target_digest);
    match decision {
        PendingCleanSaveReconciliation::Commit => {
            // Exact bytes landed: commit S+1 CleanSave and clear pending.  A
            // failure here is fail-safe: pending plus a matching target remain,
            // so a later run reconciles to the same commit.
            persist_project_recovery_authority_serial_to_path(
                path,
                pending.serial,
                ProjectRecoveryAuthorityTransition::CleanSave,
            )?;
            Ok(ProjectRecoveryAuthorityStatus {
                recovery_authority_serial: pending.serial,
                last_transition: ProjectRecoveryAuthorityTransition::CleanSave,
            })
        }
        PendingCleanSaveReconciliation::Rollback => {
            // The intended save did not land: clear pending and retain the
            // committed serial so the dirty-project recovery image at S stays
            // eligible.
            persist_project_recovery_authority_serial_to_path(
                path,
                state.serial,
                state.last_transition.clone(),
            )?;
            Ok(ProjectRecoveryAuthorityStatus {
                recovery_authority_serial: state.serial,
                last_transition: state.last_transition,
            })
        }
        PendingCleanSaveReconciliation::Retain => {
            // The target could not be read, so whether the interrupted Save
            // landed is genuinely unknown.  Fail startup truthfully instead of
            // silently exposing the committed serial S, and leave the pending
            // record durable (no journal write here) so a healthier later run
            // reconciles it against a readable target.
            let read_error = target_digest.err().unwrap_or_default();
            Err(format!(
                "Project recovery reconciliation could not read the interrupted Save target {target} to confirm whether the exact saved bytes landed: {read_error}. The pending Save recovery journal was left intact for a later startup to reconcile.",
                target = pending.target_path.display(),
            ))
        }
    }
}

fn load_output_ownership_role_from_path(path: &Path) -> Result<Option<MachineOutputRole>, String> {
    let bytes = match fs::read(path) {
        Ok(bytes) => bytes,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => {
            return Err(format!(
                "Unable to read machine output ownership state {}: {error}",
                path.display()
            ));
        }
    };
    let state: PersistedOutputOwnershipState = serde_json::from_slice(&bytes).map_err(|error| {
        format!(
            "Machine output ownership state {} is corrupt: {error}",
            path.display()
        )
    })?;
    if state.version != OUTPUT_OWNERSHIP_STATE_VERSION {
        return Err(format!(
            "Unsupported machine output ownership state version {} in {}",
            state.version,
            path.display()
        ));
    }
    Ok(Some(state.role))
}

#[cfg(test)]
fn resolve_output_ownership_role_from_path(path: &Path) -> Result<MachineOutputRole, String> {
    load_output_ownership_role_from_path(path).map(|role| role.unwrap_or_default())
}

/// Read the preferred local role without arming any output. A true first run
/// may create the preferred Both record only while the engine is still in its
/// startup-denied state; every later launch still requires an explicit arm.
fn load_or_initialize_output_ownership_preference(
    path: &Path,
) -> Result<MachineOutputRole, String> {
    match load_output_ownership_role_from_path(path)? {
        Some(role) => Ok(role),
        None => {
            persist_output_ownership_role_to_path(path, MachineOutputRole::Both)?;
            Ok(MachineOutputRole::Both)
        }
    }
}

fn replace_file_atomically(temp: &Path, target: &Path) -> Result<(), String> {
    #[cfg(target_os = "windows")]
    {
        use std::os::windows::ffi::OsStrExt;
        use windows::core::PCWSTR;
        use windows::Win32::Storage::FileSystem::{
            MoveFileExW, MOVEFILE_REPLACE_EXISTING, MOVEFILE_WRITE_THROUGH,
        };

        let temp_wide = temp
            .as_os_str()
            .encode_wide()
            .chain(std::iter::once(0))
            .collect::<Vec<_>>();
        let target_wide = target
            .as_os_str()
            .encode_wide()
            .chain(std::iter::once(0))
            .collect::<Vec<_>>();
        unsafe {
            MoveFileExW(
                PCWSTR(temp_wide.as_ptr()),
                PCWSTR(target_wide.as_ptr()),
                MOVEFILE_REPLACE_EXISTING | MOVEFILE_WRITE_THROUGH,
            )
            .map_err(|error| format!("Unable to atomically replace {}: {error}", target.display()))
        }
    }
    #[cfg(not(target_os = "windows"))]
    {
        fs::rename(temp, target)
            .map_err(|error| format!("Unable to atomically replace {}: {error}", target.display()))
    }
}

fn persist_output_ownership_role_to_path(
    path: &Path,
    role: MachineOutputRole,
) -> Result<(), String> {
    let parent = path.parent().ok_or_else(|| {
        format!(
            "Machine output ownership state path has no parent: {}",
            path.display()
        )
    })?;
    fs::create_dir_all(parent).map_err(|error| {
        format!(
            "Unable to create machine output ownership state directory {}: {error}",
            parent.display()
        )
    })?;
    let bytes = serde_json::to_vec(&PersistedOutputOwnershipState {
        version: OUTPUT_OWNERSHIP_STATE_VERSION,
        role,
    })
    .map_err(|error| format!("Unable to encode machine output ownership state: {error}"))?;
    let nonce = current_unix_ms().min(u128::from(u64::MAX));
    let file_name = path
        .file_name()
        .and_then(OsStr::to_str)
        .unwrap_or(OUTPUT_OWNERSHIP_STATE_FILE);
    let temp = parent.join(format!(".{file_name}.{}.{}.tmp", std::process::id(), nonce));
    let result = (|| {
        let mut file = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temp)
            .map_err(|error| {
                format!(
                    "Unable to create temporary machine output ownership state {}: {error}",
                    temp.display()
                )
            })?;
        file.write_all(&bytes).map_err(|error| {
            format!(
                "Unable to write temporary machine output ownership state {}: {error}",
                temp.display()
            )
        })?;
        file.sync_all().map_err(|error| {
            format!(
                "Unable to flush temporary machine output ownership state {}: {error}",
                temp.display()
            )
        })?;
        drop(file);
        replace_file_atomically(&temp, path)
    })();
    if result.is_err() {
        let _ = fs::remove_file(&temp);
    }
    result
}

fn persist_output_ownership_target_after_preparation<F>(
    path: &Path,
    role: MachineOutputRole,
    prepare: F,
) -> Result<(), String>
where
    F: FnOnce() -> Result<(), String>,
{
    persist_output_ownership_target_after_preparation_with(
        path,
        role,
        prepare,
        persist_output_ownership_role_to_path,
    )
}

fn persist_output_ownership_target_after_preparation_with<F, P>(
    path: &Path,
    role: MachineOutputRole,
    prepare: F,
    persist: P,
) -> Result<(), String>
where
    F: FnOnce() -> Result<(), String>,
    P: FnOnce(&Path, MachineOutputRole) -> Result<(), String>,
{
    prepare()?;
    persist(path, role)
}

fn project_backup_path(directory: &Path, id: u64) -> PathBuf {
    directory.join(format!("backup-{id}.json"))
}

fn project_backup_id_from_reserved_target(directory: &Path, target: &Path) -> Result<u64, String> {
    if target.parent() != Some(directory) || target.extension() != Some(OsStr::new("json")) {
        return Err("Reserved project backup target is outside its managed directory".to_string());
    }
    let id = target
        .file_stem()
        .and_then(OsStr::to_str)
        .and_then(|stem| stem.strip_prefix("backup-"))
        .ok_or_else(|| "Reserved project backup target has an invalid filename".to_string())?
        .parse::<u64>()
        .map_err(|_| "Reserved project backup target has an invalid ID".to_string())?;
    if project_backup_path(directory, id) != target {
        return Err("Reserved project backup target is not canonical".to_string());
    }
    Ok(id)
}

fn application_update_settings_from(
    endpoint: Option<&str>,
    pubkey: Option<&str>,
    channel: Option<&str>,
) -> Result<Option<ApplicationUpdateSettings>, String> {
    let endpoint = endpoint.map(str::trim).filter(|value| !value.is_empty());
    let pubkey = pubkey.map(str::trim).filter(|value| !value.is_empty());
    if endpoint.is_none() && pubkey.is_none() {
        return Ok(None);
    }
    let endpoint = endpoint.ok_or_else(|| {
        "Update signing public key is configured but the HTTPS endpoint is missing".to_string()
    })?;
    let pubkey = pubkey.ok_or_else(|| {
        "Update endpoint is configured but the signing public key is missing".to_string()
    })?;
    if endpoint.len() > 2_048 {
        return Err("Update endpoint is longer than 2048 bytes".to_string());
    }
    if pubkey.len() > 8_192 {
        return Err("Update signing public key is longer than 8192 bytes".to_string());
    }
    let decoded_pubkey = base64::engine::general_purpose::STANDARD
        .decode(pubkey)
        .map_err(|error| format!("Update signing public key is not valid base64: {error}"))?;
    let decoded_pubkey = std::str::from_utf8(&decoded_pubkey)
        .map_err(|_| "Update signing public key does not decode to UTF-8".to_string())?;
    PublicKey::decode(decoded_pubkey)
        .map_err(|error| format!("Update signing public key is invalid: {error}"))?;
    let endpoint = tauri::Url::parse(endpoint)
        .map_err(|error| format!("Update endpoint is invalid: {error}"))?;
    if endpoint.scheme() != "https" {
        return Err("Update endpoint must use HTTPS".to_string());
    }
    if endpoint.host_str().is_none()
        || !endpoint.username().is_empty()
        || endpoint.password().is_some()
        || endpoint.query().is_some()
        || endpoint.fragment().is_some()
    {
        return Err(
            "Update endpoint must have a host and must not contain credentials, a query, or a fragment"
                .to_string(),
        );
    }
    let channel = channel
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("stable")
        .to_ascii_lowercase();
    if !matches!(channel.as_str(), "stable" | "beta" | "nightly") {
        return Err("Update channel must be stable, beta, or nightly".to_string());
    }
    Ok(Some(ApplicationUpdateSettings {
        endpoint,
        pubkey: pubkey.to_string(),
        channel,
    }))
}

fn application_update_settings() -> Result<Option<ApplicationUpdateSettings>, String> {
    application_update_settings_from(
        APPLICATION_UPDATE_ENDPOINT,
        APPLICATION_UPDATE_PUBKEY,
        APPLICATION_UPDATE_CHANNEL,
    )
}

fn application_update_release_identity_from(
    endpoint: Option<&str>,
    pubkey: Option<&str>,
    channel: Option<&str>,
) -> Result<ApplicationUpdateReleaseIdentity, String> {
    let settings =
        application_update_settings_from(endpoint, pubkey, channel)?.ok_or_else(|| {
            "Signed application updates are not configured for this build".to_string()
        })?;
    Ok(ApplicationUpdateReleaseIdentity {
        endpoint: settings.endpoint.to_string(),
        channel: settings.channel,
        public_key_fingerprint: sha256_hex(settings.pubkey.as_bytes()),
    })
}

fn application_update_release_identity_json_from(
    endpoint: Option<&str>,
    pubkey: Option<&str>,
    channel: Option<&str>,
) -> Result<String, String> {
    serde_json::to_string(&application_update_release_identity_from(
        endpoint, pubkey, channel,
    )?)
    .map_err(|error| format!("Unable to serialize updater release identity: {error}"))
}

fn application_update_release_identity_json() -> Result<String, String> {
    application_update_release_identity_json_from(
        APPLICATION_UPDATE_ENDPOINT,
        APPLICATION_UPDATE_PUBKEY,
        APPLICATION_UPDATE_CHANNEL,
    )
}

fn updater_release_identity_cli_requested(mut args: impl Iterator<Item = OsString>) -> bool {
    matches!(args.next().as_deref(), Some(value) if value == OsStr::new(PRINT_UPDATER_RELEASE_IDENTITY_ARG))
        && args.next().is_none()
}

fn application_update_configuration_for_version(
    current_version: impl Into<String>,
) -> ApplicationUpdateConfiguration {
    let current_version = current_version.into();
    match application_update_settings() {
        Ok(Some(settings)) => ApplicationUpdateConfiguration {
            enabled: true,
            current_version,
            channel: settings.channel,
            endpoint_origin: Some(settings.endpoint.origin().ascii_serialization()),
            reason: None,
        },
        Ok(None) => ApplicationUpdateConfiguration {
            enabled: false,
            current_version,
            channel: APPLICATION_UPDATE_CHANNEL
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .unwrap_or("stable")
                .to_ascii_lowercase(),
            endpoint_origin: None,
            reason: Some(
                "This build has no signed update endpoint. Install releases manually until the release pipeline embeds one."
                    .to_string(),
            ),
        },
        Err(error) => ApplicationUpdateConfiguration {
            enabled: false,
            current_version,
            channel: "invalid".to_string(),
            endpoint_origin: None,
            reason: Some(error),
        },
    }
}

fn configured_application_updater(
    app: &tauri::AppHandle,
) -> Result<(tauri_plugin_updater::Updater, ApplicationUpdateSettings), String> {
    let settings = application_update_settings()?.ok_or_else(|| {
        "Signed application updates are not configured for this build".to_string()
    })?;
    let updater = app
        .updater_builder()
        .pubkey(settings.pubkey.clone())
        .endpoints(vec![settings.endpoint.clone()])
        .map_err(|error| error.to_string())?
        .timeout(Duration::from_secs(15))
        .build()
        .map_err(|error| error.to_string())?;
    Ok((updater, settings))
}

/// Returns the local-only AI/control-plane operation inventory.  This is
/// window-bound discovery only; it registers no MCP, HTTP, or remote adapter.
#[tauri::command]
fn get_control_plane_operation_registry(
    window: WebviewWindow,
) -> Result<protocol::control_plane::OperationRegistry, String> {
    control_plane::registry_for_window(window.label()).map_err(|error| error.to_string())
}

/// Returns the local-only version-2 canonical/source inventory. This remains
/// window-bound discovery only; no caller-owner or external adapter is
/// accepted by this command.
#[tauri::command]
fn get_control_plane_canonical_registry(
    window: WebviewWindow,
) -> Result<protocol::control_plane_registry_v2::CanonicalControlPlaneRegistry, String> {
    control_plane::canonical_registry_for_window(window.label()).map_err(|error| error.to_string())
}

#[cfg(test)]
#[test]
fn canonical_registry_command_uses_only_webview_window_injection() {
    let _: fn(
        WebviewWindow,
    ) -> Result<
        protocol::control_plane_registry_v2::CanonicalControlPlaneRegistry,
        String,
    > = get_control_plane_canonical_registry;
}

#[tauri::command]
fn get_application_update_configuration(app: tauri::AppHandle) -> ApplicationUpdateConfiguration {
    application_update_configuration_for_version(app.package_info().version.to_string())
}

#[tauri::command]
async fn check_application_update(app: tauri::AppHandle) -> Result<ApplicationUpdateCheck, String> {
    let current_version = app.package_info().version.to_string();
    let (updater, settings) = configured_application_updater(&app)?;
    let update = updater.check().await.map_err(|error| error.to_string())?;
    Ok(match update {
        Some(update) => ApplicationUpdateCheck {
            available: true,
            current_version,
            channel: settings.channel,
            version: Some(update.version),
            date: update.date.map(|date| date.to_string()),
            notes: update
                .body
                .map(|body| body.trim().chars().take(2_000).collect())
                .filter(|body: &String| !body.is_empty()),
        },
        None => ApplicationUpdateCheck {
            available: false,
            current_version,
            channel: settings.channel,
            version: None,
            date: None,
            notes: None,
        },
    })
}

fn verify_application_update_backup_artifact_v1(
    terminal: &PersistedProjectPublicationTerminalV1,
) -> Result<ProjectBackupSummary, String> {
    let target = terminal
        .target_path
        .as_deref()
        .map(PathBuf::from)
        .ok_or_else(|| "Application update backup receipt is missing its target".to_string())?;
    let expected_digest = terminal
        .artifact_digest
        .as_deref()
        .ok_or_else(|| "Application update backup receipt is missing its digest".to_string())?;
    let actual_digest = strong_target_file_digest(&target)?
        .ok_or_else(|| "Application update backup artifact is missing".to_string())?;
    if actual_digest != expected_digest {
        return Err(
            "Application update backup artifact was modified after publication".to_string(),
        );
    }
    let backup =
        project_publication_success_backup_summary(ProjectPublicationSurfaceV1::Backup, &target)?
            .ok_or_else(|| "Application update backup artifact could not be verified".to_string())?;
    if terminal.backup.as_ref() != Some(&backup) {
        return Err("Application update backup artifact does not match its receipt".to_string());
    }
    Ok(backup)
}

fn revalidate_application_update_publication_claim_v1(
    state: &AppState,
    journal_path: &Path,
    window_label: &str,
    request: &ProjectPublicationRequestV1,
    terminal: &PersistedProjectPublicationTerminalV1,
    update_claim: &ApplicationUpdatePublicationClaim,
) -> Result<(), String> {
    let _publication = state
        .project_save_publication
        .lock()
        .map_err(|_| "Project publication lock was poisoned".to_string())?;
    let _external_admission = lock_project_recovery_maintenance_admission(state)?;
    let coordinator = lock_project_coordinator(state)?;
    ensure_project_publication_mutation_owner_allowed(
        state,
        &coordinator,
        window_label,
        &request.owner_id,
    )?;
    let durable = load_project_recovery_authority_state_from_path(journal_path)?;
    let current = durable
        .publication_journal
        .terminals
        .iter()
        .find(|candidate| project_publication_request_key_matches(request, &candidate.request))
        .ok_or_else(|| {
            "Application update backup receipt changed during verification".to_string()
        })?;
    if current != terminal {
        return Err("Application update backup receipt changed during verification".to_string());
    }
    let claim = state
        .application_update_publication_claim
        .lock()
        .map_err(|_| "Application update publication claim lock was poisoned".to_string())?;
    if claim.as_ref() != Some(update_claim) {
        return Err("Application update publication claim changed during verification".to_string());
    }
    Ok(())
}

#[tauri::command]
async fn install_application_update(
    window: WebviewWindow,
    app: tauri::AppHandle,
    expected_version: String,
    backup_request: ProjectPublicationRequestV1,
) -> Result<ProjectBackupSummary, String> {
    let expected_version = expected_version.trim();
    if expected_version.is_empty() || expected_version.chars().count() > 64 {
        return Err("Expected update version must contain 1-64 characters".to_string());
    }
    let state = app.state::<AppState>();
    let request = normalize_project_publication_request_v1(backup_request)?;
    validate_application_update_backup_request_v1(expected_version, &request)?;
    let shape_hash = project_publication_shape_hash_v1(&request)?;
    let journal_path = project_recovery_authority_state_path(&app)?;
    let (terminal, update_claim) = {
        let _publication = state
            .project_save_publication
            .lock()
            .map_err(|_| "Project publication lock was poisoned".to_string())?;
        let _external_admission = lock_project_recovery_maintenance_admission(&state)?;
        let coordinator = lock_project_coordinator(&state)?;
        ensure_project_publication_mutation_owner_allowed(
            &state,
            &coordinator,
            window.label(),
            &request.owner_id,
        )?;
        let durable = load_project_recovery_authority_state_from_path(&journal_path)?;
        let terminal = durable
            .publication_journal
            .terminals
            .iter()
            .find(|terminal| project_publication_request_key_matches(&request, &terminal.request))
            .ok_or_else(|| {
                "Application update requires an unacknowledged durable backup success receipt"
                    .to_string()
            })?
            .clone();
        if terminal.shape_hash != shape_hash
            || terminal.surface != ProjectPublicationSurfaceV1::Backup
            || terminal.outcome != ProjectPublicationTerminalOutcomeV1::Succeeded
        {
            return Err(
                "Application update backup receipt does not match the exact successful request"
                    .to_string(),
            );
        }
        let backup_id = terminal
            .backup
            .as_ref()
            .map(|backup| backup.id)
            .ok_or_else(|| {
                "Application update backup receipt is missing its summary".to_string()
            })?;
        let update_claim = ApplicationUpdatePublicationClaim {
            origin_id: request.origin_id.clone(),
            request_id: request.request_id,
            shape_hash: shape_hash.clone(),
            backup_id,
        };
        let mut claim = state
            .application_update_publication_claim
            .lock()
            .map_err(|_| "Application update publication claim lock was poisoned".to_string())?;
        if claim.is_some() {
            return Err("Another application update install is already in progress".to_string());
        }
        *claim = Some(update_claim.clone());
        (terminal, update_claim)
    };
    let install_result = async {
        let backup = verify_application_update_backup_artifact_v1(&terminal)?;
        revalidate_application_update_publication_claim_v1(
            &state,
            &journal_path,
            window.label(),
            &request,
            &terminal,
            &update_claim,
        )?;
        let (updater, _) = configured_application_updater(&app)?;
        let update = updater
            .check()
            .await
            .map_err(|error| error.to_string())?
            .ok_or_else(|| "The selected update is no longer available".to_string())?;
        if update.version != expected_version {
            return Err(format!(
                "The available update changed from {expected_version} to {}; check again before installing",
                update.version
            ));
        }

        let final_backup = verify_application_update_backup_artifact_v1(&terminal)?;
        if final_backup != backup {
            return Err(
                "Application update backup artifact changed while checking for updates".to_string(),
            );
        }
        revalidate_application_update_publication_claim_v1(
            &state,
            &journal_path,
            window.label(),
            &request,
            &terminal,
            &update_claim,
        )?;

        let progress_app = app.clone();
        let mut downloaded_bytes = 0_u64;
        let finish_app = app.clone();
        update
            .download_and_install(
                move |chunk_bytes, total_bytes| {
                    downloaded_bytes = downloaded_bytes.saturating_add(chunk_bytes as u64);
                    let _ = progress_app.emit(
                        APPLICATION_UPDATE_PROGRESS_EVENT,
                        ApplicationUpdateProgress {
                            phase: "downloading".to_string(),
                            downloaded_bytes,
                            total_bytes,
                        },
                    );
                },
                move || {
                    let _ = finish_app.emit(
                        APPLICATION_UPDATE_PROGRESS_EVENT,
                        ApplicationUpdateProgress {
                            phase: "verifying".to_string(),
                            downloaded_bytes: 0,
                            total_bytes: None,
                        },
                    );
                },
            )
            .await
            .map_err(|error| error.to_string())?;
        let _ = app.emit(
            APPLICATION_UPDATE_PROGRESS_EVENT,
            ApplicationUpdateProgress {
                phase: "verified".to_string(),
                downloaded_bytes: 0,
                total_bytes: None,
            },
        );
        Ok::<ProjectBackupSummary, String>(final_backup)
    }
    .await;
    {
        let mut claim = state
            .application_update_publication_claim
            .lock()
            .map_err(|_| "Application update publication claim lock was poisoned".to_string())?;
        if claim.as_ref() != Some(&update_claim) {
            return Err("Application update publication claim changed unexpectedly".to_string());
        }
        *claim = None;
    }
    install_result
}

fn validate_application_update_backup_request_v1(
    expected_version: &str,
    request: &ProjectPublicationRequestV1,
) -> Result<(), String> {
    if request.surface != ProjectPublicationSurfaceV1::Backup {
        return Err("Application update requires a durable backup publication receipt".to_string());
    }
    let expected_backup_reason = format!("before update {expected_version}");
    if expected_backup_reason.chars().count() > 80
        || request.reason.as_deref() != Some(expected_backup_reason.as_str())
    {
        return Err(
            "Application update backup receipt is not bound to the selected update version"
                .to_string(),
        );
    }
    Ok(())
}

fn read_project_backup(path: &Path) -> Result<ProjectBackupEnvelope, String> {
    let json = fs::read_to_string(path)
        .map_err(|error| format!("Unable to read project backup {}: {error}", path.display()))?;
    let backup: ProjectBackupEnvelope = serde_json::from_str(&json)
        .map_err(|error| format!("Invalid project backup {}: {error}", path.display()))?;
    if backup.version != PROJECT_BACKUP_VERSION {
        return Err(format!(
            "Unsupported project backup version {} in {}",
            backup.version,
            path.display()
        ));
    }
    validate_app_name("project backup", &backup.app)?;
    validate_project_file(&backup.project)?;
    Ok(backup)
}

fn list_project_backups_in(directory: &Path) -> Result<Vec<ProjectBackupSummary>, String> {
    if !directory.exists() {
        return Ok(Vec::new());
    }
    let mut backups = Vec::new();
    for entry in fs::read_dir(directory)
        .map_err(|error| format!("Unable to list project backups: {error}"))?
    {
        let entry = entry.map_err(|error| format!("Unable to inspect project backup: {error}"))?;
        let path = entry.path();
        if !entry.file_name().to_string_lossy().starts_with("backup-")
            || path.extension() != Some(OsStr::new("json"))
        {
            continue;
        }
        let Ok(backup) = read_project_backup(&path) else {
            continue;
        };
        let bytes = entry.metadata().map(|metadata| metadata.len()).unwrap_or(0);
        backups.push(ProjectBackupSummary {
            id: backup.id,
            created_at_unix_ms: backup.created_at_unix_ms,
            source_path: backup.source_path,
            reason: backup.reason,
            bytes,
        });
    }
    backups.sort_by_key(|backup| std::cmp::Reverse(backup.id));
    Ok(backups)
}

fn reserve_unique_project_backup_id(directory: &Path, now_unix_ms: u64) -> Result<u64, String> {
    let mut observed = PROJECT_BACKUP_ID_SEQUENCE.load(Ordering::Acquire);
    loop {
        let mut candidate = now_unix_ms.max(observed.checked_add(1).ok_or_else(|| {
            "Project backup ID space is exhausted; remove backups and restart Syndocal".to_string()
        })?);
        while project_backup_path(directory, candidate).exists() {
            candidate = candidate.checked_add(1).ok_or_else(|| {
                "Project backup ID space is exhausted; remove backups and restart Syndocal"
                    .to_string()
            })?;
        }
        match PROJECT_BACKUP_ID_SEQUENCE.compare_exchange(
            observed,
            candidate,
            Ordering::AcqRel,
            Ordering::Acquire,
        ) {
            Ok(_) => return Ok(candidate),
            Err(current) => observed = current,
        }
    }
}

fn publish_new_file_atomically(temp: &Path, target: &Path) -> Result<(), String> {
    #[cfg(target_os = "windows")]
    {
        use std::os::windows::ffi::OsStrExt;
        use windows::core::PCWSTR;
        use windows::Win32::Storage::FileSystem::{MoveFileExW, MOVEFILE_WRITE_THROUGH};

        let temp_wide = temp
            .as_os_str()
            .encode_wide()
            .chain(std::iter::once(0))
            .collect::<Vec<_>>();
        let target_wide = target
            .as_os_str()
            .encode_wide()
            .chain(std::iter::once(0))
            .collect::<Vec<_>>();
        unsafe {
            MoveFileExW(
                PCWSTR(temp_wide.as_ptr()),
                PCWSTR(target_wide.as_ptr()),
                MOVEFILE_WRITE_THROUGH,
            )
            .map_err(|error| {
                format!(
                    "Unable to publish new project backup {}: {error}",
                    target.display()
                )
            })
        }
    }
    #[cfg(not(target_os = "windows"))]
    {
        fs::hard_link(temp, target).map_err(|error| {
            format!(
                "Unable to publish new project backup {}: {error}",
                target.display()
            )
        })?;
        fs::remove_file(temp).map_err(|error| {
            format!(
                "Unable to retire prepared project backup {}: {error}",
                temp.display()
            )
        })
    }
}

#[derive(Debug)]
struct PreparedProjectBackupV1 {
    summary: ProjectBackupSummary,
    target_path: PathBuf,
    temporary_path: PathBuf,
}

fn prepare_project_backup_v1(
    directory: &Path,
    ticket: &ProjectSaveTicket,
    source_path: Option<String>,
    reason: String,
    id: u64,
    temporary_path: &Path,
) -> Result<PreparedProjectBackupV1, String> {
    let mappings = ProjectControlMappings {
        midi_mappings: validate_midi_control_mappings(
            ticket.checkpoint.mappings.midi_mappings.clone(),
        )?,
        osc_mappings: validate_osc_control_mappings(
            ticket.checkpoint.mappings.osc_mappings.clone(),
        )?,
        dmx_mappings: validate_dmx_control_mappings(
            ticket.checkpoint.mappings.dmx_mappings.clone(),
        )?,
        dj_track_triggers: validate_dj_track_triggers(
            ticket.checkpoint.mappings.dj_track_triggers.clone(),
        )?,
        legacy_dj_transition_discarded: false,
    };
    validate_dj_track_triggers_against_snapshot(
        &mappings.dj_track_triggers,
        &ticket.checkpoint.project.snapshot,
    )?;
    let reason = reason.trim().chars().take(80).collect::<String>();
    let envelope = ProjectBackupEnvelope {
        version: PROJECT_BACKUP_VERSION,
        app: APP_NAME.to_string(),
        id,
        created_at_unix_ms: id,
        source_path: source_path.clone(),
        reason: reason.clone(),
        project: ticket.checkpoint.project.clone(),
        midi_mappings: mappings.midi_mappings,
        osc_mappings: mappings.osc_mappings,
        dmx_mappings: mappings.dmx_mappings,
        dj_track_triggers: mappings.dj_track_triggers,
    };
    let bytes = serde_json::to_vec_pretty(&envelope).map_err(|error| error.to_string())?;
    let target_path = project_backup_path(directory, id);
    prepare_project_save_bytes_at(temporary_path, &bytes)?;
    Ok(PreparedProjectBackupV1 {
        summary: ProjectBackupSummary {
            id,
            created_at_unix_ms: id,
            source_path,
            reason,
            bytes: bytes.len() as u64,
        },
        target_path,
        temporary_path: temporary_path.to_path_buf(),
    })
}

fn finalize_project_backup_publication_v1(
    state: &AppState,
    prepared: &PreparedProjectBackupV1,
    ticket: &ProjectSaveTicket,
    publication_binding: ProjectPublicationMutationBinding<'_>,
) -> Result<(), String> {
    let _publication = state
        .project_save_publication
        .lock()
        .map_err(|_| "Project publication lock was poisoned".to_string())?;
    ensure_no_project_publication_reconciliation_v1(state)?;
    let _external_admission = lock_project_external_command_admission(state)?;
    let mut coordinator = lock_project_coordinator(state)?;
    ensure_project_publication_mutation_owner_allowed(
        state,
        &coordinator,
        publication_binding.window_label,
        publication_binding.owner_id,
    )?;
    if !project_save_ticket_is_current(state, &mut coordinator, ticket)? {
        return Err(
            "Project changed while the backup was preparing; the stale backup was rejected before publication"
                .to_string(),
        );
    }
    publish_new_file_atomically(&prepared.temporary_path, &prepared.target_path)?;
    Ok(())
}

fn verify_project_backup_publication_v1(
    prepared: &PreparedProjectBackupV1,
) -> Result<ProjectBackupSummary, String> {
    let published = read_project_backup(&prepared.target_path)?;
    if published.id != prepared.summary.id
        || published.created_at_unix_ms != prepared.summary.created_at_unix_ms
        || published.source_path != prepared.summary.source_path
        || published.reason != prepared.summary.reason
    {
        return Err("Published project backup did not match its reserved receipt".to_string());
    }
    Ok(prepared.summary.clone())
}

fn retain_project_backups_after_publication_v1(
    directory: &Path,
    journal_path: &Path,
) -> Result<(), String> {
    let durable = load_project_recovery_authority_state_from_path(journal_path)?;
    let protected = durable
        .publication_journal
        .pending
        .iter()
        .filter(|pending| pending.surface == ProjectPublicationSurfaceV1::Backup)
        .filter_map(|pending| pending.target_path.clone())
        .chain(
            durable
                .publication_journal
                .terminals
                .iter()
                .filter(|terminal| terminal.surface == ProjectPublicationSurfaceV1::Backup)
                .filter_map(|terminal| terminal.target_path.as_deref().map(PathBuf::from)),
        )
        .collect::<HashSet<_>>();
    let backups = list_project_backups_in(directory)?;
    for expired in backups.iter().skip(PROJECT_BACKUP_RETENTION) {
        let path = project_backup_path(directory, expired.id);
        if protected.contains(&path) {
            continue;
        }
        fs::remove_file(&path).map_err(|error| {
            format!(
                "Project backup was published, but retention cleanup failed for backup {}: {error}",
                expired.id
            )
        })?;
    }
    Ok(())
}

fn complete_project_backup_publication_v1(
    state: &AppState,
    journal_path: &Path,
    pending: &PersistedProjectPublicationPendingV1,
    prepared: &PreparedProjectBackupV1,
    directory: &Path,
) -> Result<ProjectPublicationStatusV1, String> {
    let summary = match verify_project_backup_publication_v1(prepared) {
        Ok(summary) => summary,
        Err(error) => {
            latch_project_publication_failure_v1(state, journal_path, pending, &error)?;
            return Err(error);
        }
    };
    let warning = retain_project_backups_after_publication_v1(directory, journal_path).err();
    persist_project_publication_success_v1(
        state,
        journal_path,
        pending,
        &prepared.target_path,
        Some(summary),
        warning,
    )
}

#[tauri::command]
fn save_project_backup_v1(
    window: WebviewWindow,
    app: tauri::AppHandle,
    state: State<'_, AppState>,
    request: ProjectPublicationRequestV1,
) -> Result<ProjectPublicationStatusV1, String> {
    let (journal_path, begin) = begin_project_publication_command_v1(
        &window,
        &state,
        request,
        ProjectPublicationSurfaceV1::Backup,
    )?;
    let (ticket, pending) = match begin {
        BeginProjectPublicationV1::Existing(status) => return Ok(*status),
        BeginProjectPublicationV1::New { ticket, pending }
        | BeginProjectPublicationV1::Resume { ticket, pending } => (*ticket, pending),
    };
    let directory = app_data_subdirectory(&app, PROJECT_BACKUP_DIRECTORY)?;
    fs::create_dir_all(&directory)
        .map_err(|error| format!("Unable to create project backup directory: {error}"))?;
    let selected = if pending.target_path.is_some() {
        pending
    } else {
        let backup_id = reserve_unique_project_backup_id(
            &directory,
            current_unix_ms().min(u64::MAX as u128) as u64,
        )?;
        let target_path = project_backup_path(&directory, backup_id);
        persist_project_publication_auto_target_v1(&state, &journal_path, &pending, &target_path)?
    };
    let target_path = selected
        .target_path
        .as_deref()
        .ok_or_else(|| "Project backup target was not persisted".to_string())?;
    let backup_id = project_backup_id_from_reserved_target(&directory, target_path)?;
    let temporary_path = selected
        .staging_path
        .clone()
        .map(Ok)
        .unwrap_or_else(|| project_save_temporary_path(target_path))?;
    let staged = persist_project_publication_staging_for_state_v1(
        &state,
        &journal_path,
        &selected,
        target_path,
        &temporary_path,
    )?;
    let prepared = prepare_project_backup_v1(
        &directory,
        &ticket,
        staged.source_path.clone(),
        staged.reason.clone().unwrap_or_default(),
        backup_id,
        &temporary_path,
    )?;
    let prepared_pending = match persist_project_publication_prepared_v1(
        &state,
        &journal_path,
        &staged,
        &prepared.target_path,
        &prepared.temporary_path,
    ) {
        Ok(pending) => pending,
        Err(error) => {
            remove_project_publication_staging_v1(&prepared.temporary_path)?;
            return Err(error);
        }
    };
    match finalize_project_backup_publication_v1(
        &state,
        &prepared,
        &ticket,
        ProjectPublicationMutationBinding {
            window_label: window.label(),
            owner_id: &prepared_pending.request.owner_id,
        },
    ) {
        Ok(()) => complete_project_backup_publication_v1(
            &state,
            &journal_path,
            &prepared_pending,
            &prepared,
            &directory,
        ),
        Err(error) => match strong_target_file_digest(&prepared.target_path) {
            Ok(Some(actual))
                if prepared_pending.prepared_digest.as_deref() == Some(actual.as_str()) =>
            {
                remove_project_publication_staging_v1(&prepared.temporary_path)?;
                complete_project_backup_publication_v1(
                    &state,
                    &journal_path,
                    &prepared_pending,
                    &prepared,
                    &directory,
                )
            }
            Ok(_) => persist_project_publication_failed_v1(
                &state,
                &journal_path,
                &prepared_pending,
                error,
            ),
            Err(read_error) => {
                let indeterminate =
                    format!("{error}; the backup target could not be inspected: {read_error}");
                latch_project_publication_failure_v1(
                    &state,
                    &journal_path,
                    &prepared_pending,
                    &indeterminate,
                )?;
                Err(indeterminate)
            }
        },
    }
}

#[cfg(test)]
fn write_project_backup_in(
    directory: &Path,
    project: ProjectFile,
    source_path: Option<String>,
    reason: String,
    mappings: ProjectControlMappings,
) -> Result<ProjectBackupSummary, String> {
    fs::create_dir_all(directory)
        .map_err(|error| format!("Unable to create project backup directory: {error}"))?;
    let mut id = current_unix_ms().min(u64::MAX as u128) as u64;
    while project_backup_path(directory, id).exists() {
        id = id.saturating_add(1);
    }
    let mappings = ProjectControlMappings {
        midi_mappings: validate_midi_control_mappings(mappings.midi_mappings)?,
        osc_mappings: validate_osc_control_mappings(mappings.osc_mappings)?,
        dmx_mappings: validate_dmx_control_mappings(mappings.dmx_mappings)?,
        dj_track_triggers: validate_dj_track_triggers(mappings.dj_track_triggers)?,
        legacy_dj_transition_discarded: false,
    };
    validate_dj_track_triggers_against_snapshot(&mappings.dj_track_triggers, &project.snapshot)?;
    let envelope = ProjectBackupEnvelope {
        version: PROJECT_BACKUP_VERSION,
        app: APP_NAME.to_string(),
        id,
        created_at_unix_ms: id,
        source_path,
        reason: reason.trim().chars().take(80).collect(),
        project,
        midi_mappings: mappings.midi_mappings,
        osc_mappings: mappings.osc_mappings,
        dmx_mappings: mappings.dmx_mappings,
        dj_track_triggers: mappings.dj_track_triggers,
    };
    let bytes = serde_json::to_vec_pretty(&envelope).map_err(|error| error.to_string())?;
    let path = project_backup_path(directory, id);
    let temporary_path = directory.join(format!(".backup-{id}.tmp"));
    {
        let mut file = fs::File::create(&temporary_path)
            .map_err(|error| format!("Unable to create project backup: {error}"))?;
        file.write_all(&bytes)
            .and_then(|_| file.sync_all())
            .map_err(|error| format!("Unable to write project backup: {error}"))?;
    }
    if let Err(error) = fs::rename(&temporary_path, &path) {
        let _ = fs::remove_file(&temporary_path);
        return Err(format!("Unable to commit project backup: {error}"));
    }

    let mut backups = list_project_backups_in(directory)?;
    for expired in backups.iter().skip(PROJECT_BACKUP_RETENTION) {
        let _ = fs::remove_file(project_backup_path(directory, expired.id));
    }
    backups = list_project_backups_in(directory)?;
    backups
        .into_iter()
        .find(|backup| backup.id == id)
        .ok_or_else(|| "Project backup was written but could not be verified".to_string())
}

#[tauri::command]
fn list_project_backups(app: tauri::AppHandle) -> Result<Vec<ProjectBackupSummary>, String> {
    let directory = app_data_subdirectory(&app, PROJECT_BACKUP_DIRECTORY)?;
    list_project_backups_in(&directory)
}

#[tauri::command]
fn load_project_backup(
    app: tauri::AppHandle,
    window: WebviewWindow,
    state: State<'_, AppState>,
    args: FlatInvokeArgs<Value>,
) -> Result<ProjectLoadResult, String> {
    read_flat_invoke_args!(args;
        backup_id: u64 => "backupId",
        owner_id: String => "ownerId",
        expected_epoch: u64 => "expectedEpoch",
        expected_revision: u64 => "expectedRevision",
        expected_checkpoint_hash: String => "expectedCheckpointHash",
    );
    let entry_owner_incarnation =
        project_transaction_owner_binding_for_window(&state, window.label(), &owner_id)?;
    let directory = app_data_subdirectory(&app, PROJECT_BACKUP_DIRECTORY)?;
    let backup = read_project_backup(&project_backup_path(&directory, backup_id))?;
    let current_path = backup
        .source_path
        .as_deref()
        .map(Path::new)
        .filter(|path| is_syndocal_project_path(path));
    with_project_replacement_invocation(
        &state,
        window.label(),
        "load_project_backup",
        owner_id,
        (
            Some(entry_owner_incarnation),
            expected_epoch,
            expected_revision,
            expected_checkpoint_hash,
        ),
        || {
            load_project_from_file_with_control_mappings_and_disposition(
                &state,
                backup.project,
                ProjectControlMappings {
                    midi_mappings: backup.midi_mappings,
                    osc_mappings: backup.osc_mappings,
                    dmx_mappings: backup.dmx_mappings,
                    dj_track_triggers: backup.dj_track_triggers,
                    legacy_dj_transition_discarded: false,
                },
                format!("Backup {}", backup.created_at_unix_ms),
                current_path,
                ProjectAuthorityDisposition::UnsavedReplacement,
            )
        },
    )
}

#[tauri::command]
fn delete_project_backup(
    app: tauri::AppHandle,
    state: State<'_, AppState>,
    backup_id: u64,
) -> Result<(), String> {
    let directory = app_data_subdirectory(&app, PROJECT_BACKUP_DIRECTORY)?;
    let journal_path = project_recovery_authority_state_path(&app)?;
    let _publication = state
        .project_save_publication
        .lock()
        .map_err(|_| "Project publication lock was poisoned".to_string())?;
    ensure_project_backup_not_claimed(&state, backup_id)?;
    ensure_project_backup_not_durably_referenced_v1(&journal_path, &directory, backup_id)?;
    let path = project_backup_path(&directory, backup_id);
    if !path.exists() {
        return Ok(());
    }
    fs::remove_file(&path).map_err(|error| {
        format!(
            "Unable to delete project backup {}: {error}",
            path.display()
        )
    })
}

fn standby_checksum(bytes: &[u8]) -> String {
    let mut hash = 0xcbf2_9ce4_8422_2325_u64;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    format!("{hash:016x}")
}

fn standby_session_id() -> String {
    format!(
        "{}-{}",
        std::process::id(),
        current_unix_ms().min(u64::MAX as u128)
    )
}

fn validate_standby_sync_directory(directory: &str) -> Result<PathBuf, String> {
    let trimmed = directory.trim();
    if trimmed.is_empty() {
        return Err("Select a shared standby synchronization directory".to_string());
    }
    let path = PathBuf::from(trimmed);
    if !path.is_dir() {
        return Err(format!(
            "Standby synchronization directory was not found: {}",
            path.display()
        ));
    }
    Ok(path)
}

fn standby_manifest_file_name(session_id: &str, generation: u64) -> String {
    format!("syndocal-standby-{session_id}-{generation}.json")
}

fn standby_project_file_name(session_id: &str, generation: u64) -> String {
    format!("syndocal-standby-{session_id}-{generation}.sdc")
}

fn write_immutable_sync_file(path: &Path, bytes: &[u8]) -> Result<(), String> {
    if path.exists() {
        return Err(format!(
            "Standby synchronization generation already exists: {}",
            path.display()
        ));
    }
    let file_name = path
        .file_name()
        .and_then(OsStr::to_str)
        .ok_or_else(|| "Invalid standby synchronization file name".to_string())?;
    let temporary_path = path.with_file_name(format!(".{file_name}.tmp"));
    {
        let mut file = fs::File::create(&temporary_path).map_err(|error| {
            format!(
                "Unable to create standby synchronization file {}: {error}",
                temporary_path.display()
            )
        })?;
        file.write_all(bytes)
            .and_then(|_| file.sync_all())
            .map_err(|error| {
                format!(
                    "Unable to write standby synchronization file {}: {error}",
                    temporary_path.display()
                )
            })?;
    }
    if let Err(error) = fs::rename(&temporary_path, path) {
        let _ = fs::remove_file(&temporary_path);
        return Err(format!(
            "Unable to commit standby synchronization file {}: {error}",
            path.display()
        ));
    }
    Ok(())
}

fn read_standby_manifest(path: &Path) -> Result<StandbySyncManifest, String> {
    let bytes = fs::read(path).map_err(|error| {
        format!(
            "Unable to read standby manifest {}: {error}",
            path.display()
        )
    })?;
    let manifest: StandbySyncManifest = serde_json::from_slice(&bytes)
        .map_err(|error| format!("Invalid standby manifest {}: {error}", path.display()))?;
    if manifest.version != STANDBY_SYNC_VERSION {
        return Err(format!(
            "Unsupported standby manifest version {} in {}",
            manifest.version,
            path.display()
        ));
    }
    validate_app_name("standby manifest", &manifest.app)?;
    if manifest.project_file.is_empty()
        || Path::new(&manifest.project_file).file_name() != Some(OsStr::new(&manifest.project_file))
        || !has_extension(Path::new(&manifest.project_file), "sdc")
    {
        return Err(format!(
            "Invalid standby project file reference in {}",
            path.display()
        ));
    }
    Ok(manifest)
}

fn list_standby_manifests(directory: &Path) -> Result<Vec<StandbySyncManifest>, String> {
    let mut manifests = Vec::new();
    for entry in fs::read_dir(directory).map_err(|error| {
        format!(
            "Unable to list standby synchronization directory {}: {error}",
            directory.display()
        )
    })? {
        let entry = entry
            .map_err(|error| format!("Unable to inspect standby synchronization entry: {error}"))?;
        let path = entry.path();
        let name = entry.file_name();
        let name = name.to_string_lossy();
        if !name.starts_with("syndocal-standby-") || !has_extension(&path, "json") {
            continue;
        }
        if let Ok(manifest) = read_standby_manifest(&path) {
            manifests.push(manifest);
        }
    }
    manifests.sort_by(|left, right| {
        right
            .written_at_unix_ms
            .cmp(&left.written_at_unix_ms)
            .then_with(|| right.generation.cmp(&left.generation))
    });
    Ok(manifests)
}

fn cleanup_standby_generations(directory: &Path, session_id: &str) -> Result<(), String> {
    let manifests = list_standby_manifests(directory)?;
    for manifest in manifests
        .into_iter()
        .filter(|manifest| manifest.session_id == session_id)
        .skip(STANDBY_SYNC_RETENTION)
    {
        let _ = fs::remove_file(directory.join(&manifest.project_file));
        let _ = fs::remove_file(directory.join(standby_manifest_file_name(
            &manifest.session_id,
            manifest.generation,
        )));
    }
    Ok(())
}

fn write_standby_checkpoint_in(
    directory: &Path,
    project: &ProjectFile,
    mappings: &ProjectControlMappings,
    session_id: &str,
    generation: u64,
    written_at_unix_ms: u64,
) -> Result<StandbySyncManifest, String> {
    validate_project_file(project)?;
    let project_bytes = project_json_for_write_with_control_mappings_and_dj(
        project,
        mappings.midi_mappings.clone(),
        mappings.osc_mappings.clone(),
        mappings.dmx_mappings.clone(),
        mappings.dj_track_triggers.clone(),
    )?
    .into_bytes();
    let project_file = standby_project_file_name(session_id, generation);
    write_immutable_sync_file(&directory.join(&project_file), &project_bytes)?;

    let manifest = StandbySyncManifest {
        version: STANDBY_SYNC_VERSION,
        app: APP_NAME.to_string(),
        session_id: session_id.to_string(),
        generation,
        written_at_unix_ms,
        project_file,
        project_bytes: project_bytes.len() as u64,
        project_checksum: standby_checksum(&project_bytes),
    };
    let manifest_bytes = serde_json::to_vec_pretty(&manifest).map_err(|error| error.to_string())?;
    write_immutable_sync_file(
        &directory.join(standby_manifest_file_name(session_id, generation)),
        &manifest_bytes,
    )?;
    cleanup_standby_generations(directory, session_id)?;
    Ok(manifest)
}

fn read_standby_checkpoint_manifest(
    directory: &Path,
    manifest: StandbySyncManifest,
) -> Result<StandbyCheckpoint, String> {
    let path = directory.join(&manifest.project_file);
    let bytes = fs::read(&path)
        .map_err(|error| format!("Unable to read standby project {}: {error}", path.display()))?;
    if bytes.len() as u64 != manifest.project_bytes
        || standby_checksum(&bytes) != manifest.project_checksum
    {
        return Err(format!(
            "Standby project integrity check failed: {}",
            path.display()
        ));
    }
    let value: Value = serde_json::from_slice(&bytes)
        .map_err(|error| format!("Invalid standby project {}: {error}", path.display()))?;
    let (project, mappings) = project_and_control_mappings_from_value(value)
        .map_err(|error| format!("Invalid standby project {}: {error}", path.display()))?;
    validate_project_file(&project)
        .map_err(|error| format!("Invalid standby project {}: {error}", path.display()))?;
    Ok(StandbyCheckpoint {
        manifest,
        project,
        mappings,
    })
}

#[cfg(test)]
fn select_latest_standby_manifest_for_session(
    manifests: &[StandbySyncManifest],
    session_id: &str,
) -> Option<StandbySyncManifest> {
    manifests
        .iter()
        .filter(|manifest| manifest.session_id == session_id)
        .max_by_key(|manifest| manifest.generation)
        .cloned()
}

fn validate_exact_standby_takeover_manifest(
    manifest: &StandbySyncManifest,
    expected: &StandbyCheckpointIdentity,
) -> Result<(), String> {
    let actual = standby_checkpoint_identity(manifest);
    if actual != *expected {
        return Err(format!(
            "Standby takeover checkpoint is stale: expected {} generation {}, observed {} generation {}",
            expected.session_id,
            expected.generation,
            actual.session_id,
            actual.generation,
        ));
    }
    let expected_project_file =
        standby_project_file_name(&expected.session_id, expected.generation);
    if manifest.project_file != expected_project_file {
        return Err(format!(
            "Standby takeover checkpoint integrity failed: expected project file {}, observed {}",
            expected_project_file, manifest.project_file
        ));
    }
    Ok(())
}

fn strict_standby_manifest_path_for_exact_takeover(
    directory: &Path,
    expected: &StandbyCheckpointIdentity,
) -> Result<PathBuf, String> {
    if expected.session_id.is_empty()
        || expected.session_id.len() > 128
        || !expected.session_id.is_ascii()
        || expected
            .session_id
            .bytes()
            .any(|byte| byte.is_ascii_control() || matches!(byte, b'/' | b'\\'))
        || expected.generation == 0
    {
        return Err("Standby takeover checkpoint identity is invalid".to_string());
    }

    const MANIFEST_PREFIX: &str = "syndocal-standby-";
    const MANIFEST_SUFFIX: &str = ".json";
    let prefix = format!("{MANIFEST_PREFIX}{}-", expected.session_id);
    let mut exact_path = None;
    for entry in fs::read_dir(directory).map_err(|error| {
        format!(
            "Unable to list standby synchronization directory {}: {error}",
            directory.display()
        )
    })? {
        let entry = entry
            .map_err(|error| format!("Unable to inspect standby synchronization entry: {error}"))?;
        let name = entry.file_name();
        let Some(name) = name.to_str() else {
            continue;
        };
        if !name.starts_with(&prefix) || !name.ends_with(MANIFEST_SUFFIX) {
            continue;
        }
        let generation_text = &name[prefix.len()..name.len() - MANIFEST_SUFFIX.len()];
        // A longer hyphenated session ID (for example primary-a-b) also
        // shares the shorter primary-a prefix. Only a canonical decimal
        // suffix is an unambiguous candidate for this expected session.
        // Tails without a hyphen cannot be another session ID, so malformed
        // or non-canonical values must fail closed instead of allowing exact
        // takeover to fall back to an older checkpoint. Hyphenated tails are
        // retained as possible longer-session collisions (for example
        // primary-a-b generation 99 produces the tail b-99).
        let generation = match generation_text.parse::<u64>() {
            Ok(generation) if generation_text == generation.to_string() => generation,
            Ok(_) | Err(_) if !generation_text.contains('-') => {
                return Err(format!(
                    "Invalid standby manifest generation candidate {generation_text:?} for session {}",
                    expected.session_id
                ));
            }
            Ok(_) | Err(_) => continue,
        };
        if generation > expected.generation {
            return Err(format!(
                "Standby takeover checkpoint is stale: newer generation {} was observed for session {}",
                generation, expected.session_id
            ));
        }
        if generation == expected.generation && exact_path.replace(entry.path()).is_some() {
            return Err(format!(
                "Duplicate standby manifest candidate for session {} generation {}",
                expected.session_id, expected.generation
            ));
        }
    }
    exact_path.ok_or_else(|| {
        format!(
            "Standby takeover checkpoint is stale: no manifest for session {} generation {}",
            expected.session_id, expected.generation
        )
    })
}

/// Exact control-plane reads scan filenames before parsing JSON. A malformed
/// newer candidate therefore cannot disappear through the general reader's
/// valid-manifest filter and cause fallback to an older checkpoint.
fn read_standby_checkpoint_for_exact_takeover(
    directory: &Path,
    expected: &StandbyCheckpointIdentity,
) -> Result<StandbyCheckpoint, String> {
    let manifest_path = strict_standby_manifest_path_for_exact_takeover(directory, expected)?;
    let manifest = read_standby_manifest(&manifest_path)?;
    validate_exact_standby_takeover_manifest(&manifest, expected)?;
    read_standby_checkpoint_manifest(directory, manifest)
}

fn read_standby_checkpoint_for_session(
    directory: &Path,
    session_id: Option<&str>,
) -> Result<Option<StandbyCheckpoint>, String> {
    let mut manifests = list_standby_manifests(directory)?;
    if let Some(session_id) = session_id {
        manifests.retain(|manifest| manifest.session_id == session_id);
        manifests.sort_by_key(|manifest| std::cmp::Reverse(manifest.generation));
    }
    let mut last_error = None;
    for manifest in manifests {
        match read_standby_checkpoint_manifest(directory, manifest) {
            Ok(checkpoint) => return Ok(Some(checkpoint)),
            Err(error) => last_error = Some(error),
        }
    }
    Err(last_error
        .unwrap_or_else(|| "No valid standby synchronization checkpoint was found".to_string()))
}

fn standby_checkpoint_requires_identity_apply(
    state: &AppState,
    project: &ProjectFile,
    mappings: &ProjectControlMappings,
) -> Result<bool, String> {
    let mut coordinator = lock_project_coordinator(state)?;
    let current = reconcile_project_checkpoint_for_coordinator(state, &mut coordinator)?;
    let incoming_hash = project_checkpoint_hash(project, mappings)?;
    // Generations are a heartbeat transport detail. A same-content primary
    // checkpoint must not repeatedly retire inputs/reset runtime or create
    // artificial project identity history on the Standby machine.
    Ok(project_checkpoint_content_requires_identity_apply(
        &current,
        mappings,
        &incoming_hash,
    ))
}

/// Poll transport generations are heartbeats, not project identities. This
/// pure decision keeps the same bytes from repeatedly retiring inputs.
fn project_checkpoint_content_requires_identity_apply(
    current: &ProjectCheckpoint,
    incoming_mappings: &ProjectControlMappings,
    incoming_hash: &str,
) -> bool {
    current.hash != incoming_hash || current.mappings != *incoming_mappings
}

#[cfg(test)]
fn read_standby_checkpoint_in(directory: &Path) -> Result<Option<StandbyCheckpoint>, String> {
    read_standby_checkpoint_for_session(directory, None)
}

fn observe_active_primary_sessions(
    manifests: &[StandbySyncManifest],
    activity: &mut HashMap<String, (u64, Instant)>,
) -> Vec<String> {
    let now = Instant::now();
    let mut latest_by_session = HashMap::<String, u64>::new();
    for manifest in manifests {
        latest_by_session
            .entry(manifest.session_id.clone())
            .and_modify(|generation| *generation = (*generation).max(manifest.generation))
            .or_insert(manifest.generation);
    }
    activity.retain(|session_id, _| latest_by_session.contains_key(session_id));
    for (session_id, generation) in latest_by_session {
        match activity.get_mut(&session_id) {
            Some((observed_generation, observed_at)) if *observed_generation != generation => {
                *observed_generation = generation;
                *observed_at = now;
            }
            None => {
                activity.insert(session_id, (generation, now));
            }
            _ => {}
        }
    }
    let mut active = activity
        .iter()
        .filter(|(_, (_, observed_at))| {
            observed_at.elapsed() < Duration::from_millis(STANDBY_SYNC_STALE_MS)
        })
        .map(|(session_id, _)| session_id.clone())
        .collect::<Vec<_>>();
    active.sort();
    active
}

fn update_standby_status(
    status: &Arc<Mutex<StandbySyncStatus>>,
    update: impl FnOnce(&mut StandbySyncStatus),
) {
    if let Ok(mut status) = status.lock() {
        update(&mut status);
    }
}

fn sleep_until_standby_tick(stop: &AtomicBool, duration_ms: u64) {
    let deadline = Instant::now() + Duration::from_millis(duration_ms);
    while !stop.load(Ordering::Relaxed) && Instant::now() < deadline {
        std::thread::sleep(Duration::from_millis(50));
    }
}

fn stop_standby_sync_runtime(runtime: &mut StandbySyncRuntime) {
    if let Some(stop) = runtime.stop.take() {
        stop.store(true, Ordering::Relaxed);
    }
    if let Some(worker) = runtime.worker.take() {
        let _ = worker.join();
    }
    update_standby_status(&runtime.status, |status| {
        status.running = false;
    });
}

#[tauri::command]
fn select_standby_sync_directory(window: WebviewWindow) -> Option<String> {
    parented_file_dialog(&window)
        .pick_folder()
        .map(|path| path.to_string_lossy().to_string())
}

#[tauri::command]
fn start_standby_sync(
    app: tauri::AppHandle,
    state: State<'_, AppState>,
    directory: String,
    role: StandbySyncRole,
) -> Result<StandbySyncStatus, String> {
    let directory = validate_standby_sync_directory(&directory)?;
    if role == StandbySyncRole::Standby {
        // Capture the managed run before taking the standby lifecycle lock;
        // fail-stop may join its worker and perform DMX/native I/O.
        output_lease_keepalive_integration::execute_current_boundary(
            &app,
            &state,
            output_lease::output_lease_keepalive::OutputLeaseKeepaliveBoundary::Standby,
            "Managed output lease entering Standby",
        )?;
    }
    let _lifecycle_guard = state.standby_sync_lifecycle.lock().map_err(|_| {
        let error = "Standby synchronization lifecycle lock was poisoned".to_string();
        state
            .engine
            .mark_output_ownership_transition_failure(error.clone());
        error
    })?;
    let session_id = standby_session_id();
    let stop = Arc::new(AtomicBool::new(false));
    let status = Arc::new(Mutex::new(StandbySyncStatus {
        // Standby is published only after the ownership fence has reserved
        // and completed the all-deny transition below.
        running: role != StandbySyncRole::Standby,
        role: Some(role),
        directory: Some(directory.to_string_lossy().to_string()),
        session_id: (role == StandbySyncRole::Primary).then(|| session_id.clone()),
        ..StandbySyncStatus::default()
    }));
    // This is deliberately before every output-transition lock. A normal
    // project replacement uses the same lifecycle -> stop/join -> transition
    // order, while the polling worker itself never acquires lifecycle.
    stop_standby_sync_for_project_swap(&state)?;
    {
        let mut runtime = state
            .standby_sync
            .lock()
            .map_err(|_| "Standby synchronization lock was poisoned".to_string())?;
        runtime.status = Arc::clone(&status);
    }

    if role == StandbySyncRole::Standby {
        {
            let _transition_guard = state.output_ownership_transition.lock().map_err(|_| {
                let error = "Output ownership transition lock was poisoned".to_string();
                state
                    .engine
                    .mark_output_ownership_transition_failure(error.clone());
                error
            })?;
            let (path, transition) = match reserve_standby_output_ownership_transition(&app, &state)
            {
                Ok(reservation) => reservation,
                Err((path, error)) => {
                    let error = fail_output_ownership_transition(
                        &app,
                        &state,
                        path.as_deref(),
                        MachineOutputRole::Standby,
                        error,
                        None,
                    );
                    update_standby_status(&status, |status| {
                        status.running = false;
                        status.last_error = Some(error.clone());
                    });
                    return Err(error);
                }
            };
            if let Err(error) = apply_output_ownership_transition_after_reservation(
                &app,
                &state,
                MachineOutputRole::Standby,
                &path,
                Some(transition),
            ) {
                update_standby_status(&status, |status| {
                    status.running = false;
                    status.last_error = Some(error.clone());
                });
                return Err(error);
            }
        }
        let warm_standby_result =
            sanitize_current_project_runtime_under_authority(&state).map(|_| ());
        if let Err(error) = warm_standby_result {
            update_standby_status(&status, |status| {
                status.running = false;
                status.last_error = Some(error.clone());
            });
            return Err(error);
        }
        if !standby_sync_may_publish_running(&state.engine.output_ownership_status()) {
            let error =
                "Standby synchronization cannot publish running before the Standby ownership fence is Ready"
                    .to_string();
            state
                .engine
                .mark_output_ownership_transition_failure(error.clone());
            update_standby_status(&status, |status| {
                status.running = false;
                status.last_error = Some(error.clone());
            });
            return Err(error);
        }
        update_standby_status(&status, |status| {
            status.running = true;
        });
    }

    let mut runtime = state
        .standby_sync
        .lock()
        .map_err(|_| "Standby synchronization lock was poisoned".to_string())?;
    runtime.stop = Some(stop.clone());
    runtime.status = Arc::clone(&status);

    let worker_directory = directory.clone();
    runtime.worker = Some(std::thread::spawn(move || match role {
        StandbySyncRole::Primary => {
            let mut generation = current_unix_ms().min(u64::MAX as u128) as u64;
            let mut session_activity = HashMap::new();
            while !stop.load(Ordering::Relaxed) {
                let written_at_unix_ms = current_unix_ms().min(u64::MAX as u128) as u64;
                let result = {
                    let state = app.state::<AppState>();
                    (|| {
                        let _external_admission = lock_project_external_command_admission(&state)?;
                        let mut coordinator = lock_project_coordinator(&state)?;
                        project_save_ticket_for_coordinator(&state, &mut coordinator)
                    })()
                    .and_then(|ticket| {
                        while worker_directory
                            .join(standby_manifest_file_name(&session_id, generation))
                            .exists()
                        {
                            generation = generation.saturating_add(1);
                        }
                        write_standby_checkpoint_in(
                            &worker_directory,
                            &ticket.checkpoint.project,
                            &ticket.checkpoint.mappings,
                            &session_id,
                            generation,
                            written_at_unix_ms,
                        )
                    })
                };
                match result {
                    Ok(manifest) => {
                        let active_primary_sessions = list_standby_manifests(&worker_directory)
                            .map(|manifests| {
                                observe_active_primary_sessions(&manifests, &mut session_activity)
                            })
                            .unwrap_or_else(|_| vec![manifest.session_id.clone()]);
                        let split_brain = active_primary_sessions.len() > 1;
                        update_standby_status(&status, |status| {
                            status.generation = Some(manifest.generation);
                            status.written_at_unix_ms = Some(manifest.written_at_unix_ms);
                            status.heartbeat_age_ms = Some(0);
                            status.heartbeat_stale = false;
                            status.takeover_ready = false;
                            status.split_brain = split_brain;
                            status.active_primary_sessions = active_primary_sessions;
                            status.project_bytes = manifest.project_bytes;
                            status.last_error = split_brain.then(|| {
                                "Multiple active Primary sessions detected in this synchronization folder"
                                    .to_string()
                            });
                        });
                        generation = generation.saturating_add(1);
                    }
                    Err(error) => update_standby_status(&status, |status| {
                        status.last_error = Some(error);
                    }),
                }
                sleep_until_standby_tick(&stop, STANDBY_SYNC_INTERVAL_MS);
            }
        }
        StandbySyncRole::Standby => {
            let mut session_activity = HashMap::new();
            let mut selected_session: Option<String> = None;
            let mut observed_checkpoint: Option<(String, u64)> = None;
            let mut applied_checkpoint: Option<(String, u64)> = None;
            let mut last_progress_at = Instant::now();
            while !stop.load(Ordering::Relaxed) {
                let manifests = match list_standby_manifests(&worker_directory) {
                    Ok(manifests) => manifests,
                    Err(error) => {
                        update_standby_status(&status, |status| {
                            status.last_error = Some(error);
                        });
                        sleep_until_standby_tick(&stop, STANDBY_SYNC_POLL_MS);
                        continue;
                    }
                };
                let active_primary_sessions =
                    observe_active_primary_sessions(&manifests, &mut session_activity);
                let split_brain = active_primary_sessions.len() > 1;
                if active_primary_sessions.len() == 1 {
                    selected_session = active_primary_sessions.first().cloned();
                } else if selected_session.is_none() && !split_brain {
                    selected_session = manifests
                        .first()
                        .map(|manifest| manifest.session_id.clone());
                }
                match read_standby_checkpoint_for_session(
                    &worker_directory,
                    selected_session.as_deref(),
                ) {
                    Ok(Some(checkpoint)) => {
                        let checkpoint_identity = (
                            checkpoint.manifest.session_id.clone(),
                            checkpoint.manifest.generation,
                        );
                        let generation_changed =
                            observed_checkpoint.as_ref() != Some(&checkpoint_identity);
                        if generation_changed {
                            observed_checkpoint = Some(checkpoint_identity.clone());
                            last_progress_at = Instant::now();
                        }
                        let heartbeat_age_ms =
                            last_progress_at.elapsed().as_millis().min(u64::MAX as u128) as u64;
                        let heartbeat_stale = heartbeat_age_ms >= STANDBY_SYNC_STALE_MS;
                        let mut apply_error = None;
                        let should_apply = applied_checkpoint.as_ref()
                            != Some(&checkpoint_identity)
                            && !split_brain;
                        if should_apply {
                            let state = app.state::<AppState>();
                            // The polling worker deliberately does not take
                            // standby_sync_lifecycle. Normal replacement
                            // callers acquire it, request this stop, join us,
                            // and only then wait for output ownership.
                            match standby_checkpoint_requires_identity_apply(
                                &state,
                                &checkpoint.project,
                                &checkpoint.mappings,
                            ) {
                                Ok(false) => {
                                    // A fresh heartbeat carrying the same
                                    // canonical checkpoint is observed/applied
                                    // without triggering a replacement.
                                    applied_checkpoint = Some(checkpoint_identity);
                                }
                                Ok(true) => {
                                    if let Err(error) =
                                        load_project_from_file_with_control_mappings_in_scope(
                                            &state,
                                            ProjectLoadInput {
                                                project: checkpoint.project.clone(),
                                                mappings: checkpoint.mappings.clone(),
                                                path_label: format!(
                                                    "Warm standby generation {}",
                                                    checkpoint.manifest.generation
                                                ),
                                                current_path: None,
                                                scope: ProjectSnapshotReplacementScope::StandbyPollingWorker,
                                            },
                                            Some(stop.as_ref()),
                                        )
                                    {
                                        apply_error = Some(error);
                                    } else {
                                        applied_checkpoint = Some(checkpoint_identity);
                                    }
                                }
                                Err(error) => apply_error = Some(error),
                            }
                        }
                        update_standby_status(&status, |status| {
                            status.session_id = Some(checkpoint.manifest.session_id.clone());
                            status.generation = Some(checkpoint.manifest.generation);
                            status.written_at_unix_ms =
                                Some(checkpoint.manifest.written_at_unix_ms);
                            status.heartbeat_age_ms = Some(heartbeat_age_ms);
                            status.heartbeat_stale = heartbeat_stale;
                            status.takeover_ready = heartbeat_stale && !split_brain;
                            status.split_brain = split_brain;
                            status.active_primary_sessions = active_primary_sessions.clone();
                            status.project_bytes = checkpoint.manifest.project_bytes;
                            status.last_applied_generation = applied_checkpoint
                                .as_ref()
                                .map(|(_, generation)| *generation);
                            status.last_error = apply_error.or_else(|| {
                                split_brain.then(|| {
                                    "Multiple active Primary sessions detected; warm synchronization is fenced"
                                        .to_string()
                                })
                            });
                        });
                    }
                    Ok(None) => update_standby_status(&status, |status| {
                        status.heartbeat_age_ms = None;
                        status.heartbeat_stale = true;
                        status.takeover_ready = false;
                        status.split_brain = split_brain;
                        status.active_primary_sessions = active_primary_sessions;
                        status.last_error = split_brain.then(|| {
                            "Multiple active Primary sessions detected; warm synchronization is fenced"
                                .to_string()
                        });
                    }),
                    Err(error) => update_standby_status(&status, |status| {
                        status.last_error = Some(error);
                    }),
                }
                sleep_until_standby_tick(&stop, STANDBY_SYNC_POLL_MS);
            }
        }
    }));

    runtime
        .status
        .lock()
        .map(|status| status.clone())
        .map_err(|_| "Standby synchronization status lock was poisoned".to_string())
}

#[tauri::command]
fn stop_standby_sync(state: State<'_, AppState>) -> Result<StandbySyncStatus, String> {
    let _lifecycle_guard = state.standby_sync_lifecycle.lock().map_err(|_| {
        let error = "Standby synchronization lifecycle lock was poisoned".to_string();
        state
            .engine
            .mark_output_ownership_transition_failure(error.clone());
        error
    })?;
    // Publication has committed and the stop token was set under its output
    // guard. Runtime bookkeeping is therefore poison-recovering: a poisoned
    // mutex must not turn an applied Take Over into a false rejection.
    let mut runtime = state
        .standby_sync
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    stop_standby_sync_runtime(&mut runtime);
    runtime
        .status
        .lock()
        .map(|status| status.clone())
        .map_err(|_| "Standby synchronization status lock was poisoned".to_string())
}

#[tauri::command]
async fn standby_sync_status(app: tauri::AppHandle) -> Result<StandbySyncStatus, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let state = app.state::<AppState>();
        let status = state
            .standby_sync
            .lock()
            .map_err(|_| "Standby synchronization lock was poisoned".to_string())?
            .status
            .clone();
        status
            .lock()
            .map(|status| status.clone())
            .map_err(|_| "Standby synchronization status lock was poisoned".to_string())
    })
    .await
    .map_err(|error| format!("Standby synchronization status query worker failed: {error}"))?
}

fn lock_and_validate_standby_takeover_status<'a>(
    status: &'a Mutex<StandbySyncStatus>,
    selector: &StandbyTakeoverCheckpointSelector,
    force: bool,
) -> Result<std::sync::MutexGuard<'a, StandbySyncStatus>, String> {
    let status = status
        .lock()
        .map_err(|_| "Standby synchronization status lock was poisoned".to_string())?;
    let StandbyTakeoverCheckpointSelector::Exact(expected) = selector;
    if !status.running
        || status.role != Some(StandbySyncRole::Standby)
        || status.session_id.as_deref() != Some(expected.session_id.as_str())
        || status.generation != Some(expected.generation)
        || (!force && (status.split_brain || !status.heartbeat_stale))
    {
        return Err("Standby Take Over status changed before fenced publication".to_string());
    }
    Ok(status)
}

/// Validate and read the checkpoint while the worker is still alive. Every
/// error in this phase returns before the caller can set the stop token or
/// publish a project/output transition.
fn read_standby_takeover_checkpoint_before_stop<F>(
    directory: &Path,
    status_snapshot: &StandbySyncStatus,
    selector: &StandbyTakeoverCheckpointSelector,
    force: bool,
    validate_output_fence: F,
) -> Result<StandbyCheckpoint, String>
where
    F: FnOnce() -> Result<(), String>,
{
    validate_takeover_running_status(status_snapshot)?;
    if status_snapshot.split_brain && !force {
        return Err(
            "Multiple active Primary sessions are present; confirm forced Take Over to continue"
                .to_string(),
        );
    }
    if !status_snapshot.heartbeat_stale && !force {
        return Err(
            "Primary heartbeat is still active; confirm forced Take Over to continue".to_string(),
        );
    }

    let StandbyTakeoverCheckpointSelector::Exact(expected) = selector;
    // Re-check the status after taking lifecycle ownership. The control plane
    // validated this identity before consuming the authorization, but the polling worker
    // can advance status while the external locks are released. A changed
    // status is stale even before reading the file.
    if status_snapshot.session_id.as_deref() != Some(expected.session_id.as_str())
        || status_snapshot.generation != Some(expected.generation)
    {
        return Err("Standby takeover checkpoint is stale".to_string());
    }

    // Validate the project/output identity before reading and stopping the
    // standby worker. The replacement boundary repeats this check after
    // stop/join; this early check avoids retiring a healthy worker for an
    // already-stale authorization while lifecycle ownership is held.
    validate_output_fence()?;

    let StandbyTakeoverCheckpointSelector::Exact(expected) = selector;
    // Read the latest manifest for the authorization-bound session and reject any
    // generation advance before stopping the worker. This is intentionally
    // fail-closed and never falls back to an older checkpoint when a newer
    // manifest exists.
    let checkpoint = read_standby_checkpoint_for_exact_takeover(directory, expected)?;
    validate_exact_standby_takeover_manifest(&checkpoint.manifest, expected)?;
    Ok(checkpoint)
}

#[cfg(test)]
fn take_over_standby_core(
    state: &AppState,
    force: bool,
    selector: StandbyTakeoverCheckpointSelector,
    expected_output_fence: &OutputControlFenceV1,
) -> Result<(ProjectLoadResult, OutputControlFenceV1), String> {
    take_over_standby_core_with_optional_lease(state, force, selector, expected_output_fence, None)
        .map(|(result, fence, _)| (result, fence))
}

fn take_over_standby_core_with_lease(
    state: &AppState,
    force: bool,
    selector: StandbyTakeoverCheckpointSelector,
    expected_output_fence: &OutputControlFenceV1,
    lease_request: &OutputLeaseRequest,
    lease_now_ms: u64,
) -> Result<
    (
        ProjectLoadResult,
        OutputControlFenceV1,
        output_lease::OutputLeaseRequestReceipt,
    ),
    String,
> {
    take_over_standby_core_with_optional_lease(
        state,
        force,
        selector,
        expected_output_fence,
        Some((lease_request, lease_now_ms)),
    )
    .and_then(|(result, fence, receipt)| {
        receipt
            .map(|receipt| (result, fence, receipt))
            .ok_or_else(|| "Take Over output lease authorization was not committed".to_string())
    })
}

fn take_over_standby_core_with_optional_lease(
    state: &AppState,
    force: bool,
    selector: StandbyTakeoverCheckpointSelector,
    expected_output_fence: &OutputControlFenceV1,
    lease_authorization: Option<(&OutputLeaseRequest, u64)>,
) -> Result<
    (
        ProjectLoadResult,
        OutputControlFenceV1,
        Option<output_lease::OutputLeaseRequestReceipt>,
    ),
    String,
> {
    execute_managed_project_replacement_boundary(state, "Managed output lease Standby Take Over")?;
    let _lifecycle_guard = state.standby_sync_lifecycle.lock().map_err(|_| {
        let error = "Standby synchronization lifecycle lock was poisoned".to_string();
        state
            .engine
            .mark_output_ownership_transition_failure(error.clone());
        error
    })?;
    let (directory, status_snapshot, standby_stop, standby_status) = {
        let runtime = state
            .standby_sync
            .lock()
            .map_err(|_| "Standby synchronization lock was poisoned".to_string())?;
        let standby_status = Arc::clone(&runtime.status);
        let status = standby_status
            .lock()
            .map_err(|_| "Standby synchronization status lock was poisoned".to_string())?
            .clone();
        let directory = status
            .directory
            .as_deref()
            .map(validate_standby_sync_directory)
            .transpose()?
            .ok_or_else(|| "Standby synchronization is not configured".to_string())?;
        let standby_stop = runtime
            .stop
            .clone()
            .ok_or_else(|| "Standby synchronization worker is not running".to_string())?;
        (directory, status, standby_stop, standby_status)
    };
    let checkpoint = read_standby_takeover_checkpoint_before_stop(
        &directory,
        &status_snapshot,
        &selector,
        force,
        || {
            let _external_admission = lock_project_external_command_admission(state)?;
            let mut coordinator = lock_project_coordinator(state)?;
            if reconcile_project_checkpoint_for_coordinator(state, &mut coordinator).is_err()
                || !control_plane_runtime::exact_output_control_fence_matches(
                    state,
                    &coordinator,
                    expected_output_fence,
                )
                || ensure_no_pending_project_transaction(&coordinator).is_err()
            {
                return Err(
                    "Output control fence changed before Standby Take Over stop".to_string()
                );
            }
            Ok(())
        },
    )?;
    // Keep the worker alive until the fenced publication commits. A stale
    // authorization must not leave an otherwise healthy Standby worker stopped.
    // The commit closure sets this token while external/coordinator/output
    // guards remain held; a worker already queued behind those guards checks
    // the same token after taking the output guard and exits without
    // publishing. We join only after the guarded commit has returned.
    let path_label = format!(
        "Standby Take Over generation {}",
        checkpoint.manifest.generation
    );
    let result = load_project_from_file_with_control_mappings_in_scope_and_expected_output_fence(
        state,
        ProjectLoadInput {
            project: checkpoint.project,
            mappings: checkpoint.mappings,
            path_label,
            current_path: None,
            scope: ProjectSnapshotReplacementScope::LifecycleAlreadyHeld,
        },
        ProjectTakeoverReplacementContext {
            scope: ProjectSnapshotReplacementScope::LifecycleAlreadyHeld,
            expected_output_fence,
            standby_stop: &standby_stop,
            standby_status: &standby_status,
            selector: &selector,
            force,
            lease_authorization,
        },
    )?;
    let mut runtime = state
        .standby_sync
        .lock()
        .map_err(|_| "Standby synchronization lock was poisoned".to_string())?;
    stop_standby_sync_runtime(&mut runtime);
    Ok(result)
}

#[tauri::command]
fn take_over_standby(state: State<'_, AppState>, force: bool) -> Result<ProjectLoadResult, String> {
    let _ = (state, force);
    Err(
        "Standby Take Over is fail-closed: use the authenticated local OutputControl R4 path"
            .to_string(),
    )
}

fn diagnostic_zip_file_name(path: PathBuf) -> PathBuf {
    if path.extension().is_none() {
        path.with_extension("zip")
    } else {
        path
    }
}

fn write_diagnostic_archive<W: Write + Seek>(
    writer: W,
    entries: &[(&str, Vec<u8>)],
    crash_directory: &Path,
) -> Result<(), String> {
    let mut archive = zip::ZipWriter::new(writer);
    let options = zip::write::SimpleFileOptions::default()
        .compression_method(zip::CompressionMethod::Deflated);
    for (name, contents) in entries {
        archive
            .start_file(*name, options)
            .map_err(|error| error.to_string())?;
        archive
            .write_all(contents)
            .map_err(|error| error.to_string())?;
    }
    archive
        .start_file("README.txt", options)
        .map_err(|error| error.to_string())?;
    archive
        .write_all(b"This package contains runtime diagnostics and may include the local project path. Review it before sharing. It does not include the project file or media contents.\n")
        .map_err(|error| error.to_string())?;
    if crash_directory.exists() {
        for entry in fs::read_dir(crash_directory)
            .map_err(|error| format!("Unable to list crash reports: {error}"))?
            .flatten()
        {
            let crash_path = entry.path();
            if !crash_path.is_file() {
                continue;
            }
            let Ok(contents) = fs::read(&crash_path) else {
                continue;
            };
            let Some(file_name) = crash_path.file_name().and_then(OsStr::to_str) else {
                continue;
            };
            archive
                .start_file(format!("crash-reports/{file_name}"), options)
                .map_err(|error| error.to_string())?;
            archive
                .write_all(&contents)
                .map_err(|error| error.to_string())?;
        }
    }
    archive.finish().map_err(|error| error.to_string())?;
    Ok(())
}

#[tauri::command]
fn export_diagnostic_package(
    window: WebviewWindow,
    app: tauri::AppHandle,
    state: State<'_, AppState>,
) -> Result<Option<String>, String> {
    let captured_at_unix_ms = current_unix_ms();
    let Some(path) = parented_file_dialog(&window)
        .add_filter("Syndocal Diagnostic Package", &["zip"])
        .set_file_name(format!("syndocal-diagnostics-{captured_at_unix_ms}.zip"))
        .save_file()
    else {
        return Ok(None);
    };
    let path = diagnostic_zip_file_name(path);
    let file = fs::File::create(&path)
        .map_err(|error| format!("Unable to create diagnostic package: {error}"))?;
    let snapshot = state.engine.snapshot();
    let current_project_path = state
        .current_project_path
        .lock()
        .map_err(|_| "Current project path lock was poisoned".to_string())?
        .as_ref()
        .map(|path| path.to_string_lossy().to_string());
    let application_update =
        application_update_configuration_for_version(app.package_info().version.to_string());
    let manifest = json!({
        "version": 1,
        "app": APP_NAME,
        "app_version": env!("CARGO_PKG_VERSION"),
        "captured_at_unix_ms": captured_at_unix_ms,
        "os": env::consts::OS,
        "arch": env::consts::ARCH,
        "current_project_path": current_project_path,
        "application_update": application_update,
    });
    let project_summary = json!({
        "fixtures": snapshot.fixtures.len(),
        "cues": snapshot.cues.len(),
        "effects": snapshot.effects.len(),
        "node_graphs": snapshot.node_graphs.len(),
        "timeline_events": snapshot.timeline.events.len(),
        "timeline_automations": snapshot.timeline.automations.len(),
        "timeline_video_automations": snapshot.timeline.video_automations.len(),
        "video_layers": snapshot.video.layers.len(),
        "video_outputs": snapshot.video.outputs.len(),
        "dmx_outputs": snapshot.dmx_outputs.len(),
    });
    let telemetry = engine_telemetry_report_from_snapshot(&snapshot, captured_at_unix_ms);
    let runtime = video::video_runtime_status();
    let entries = vec![
        (
            "manifest.json",
            serde_json::to_vec_pretty(&manifest).map_err(|error| error.to_string())?,
        ),
        (
            "project-summary.json",
            serde_json::to_vec_pretty(&project_summary).map_err(|error| error.to_string())?,
        ),
        (
            "engine-telemetry.json",
            serde_json::to_vec_pretty(&telemetry).map_err(|error| error.to_string())?,
        ),
        (
            "video-runtime.json",
            serde_json::to_vec_pretty(&runtime).map_err(|error| error.to_string())?,
        ),
    ];
    let crash_directory = app_data_subdirectory(&app, CRASH_REPORT_DIRECTORY)?;
    write_diagnostic_archive(file, &entries, &crash_directory)?;
    Ok(Some(path.to_string_lossy().to_string()))
}

