fn apply_color_mapping_effect_target_override(
    mut request: ColorMappingEffectRequest,
    target_override: &EffectTargetOverride,
) -> ColorMappingEffectRequest {
    request.fixture_ids = target_override.fixture_ids.clone();
    request.target_group_ids = target_override.target_group_ids.clone();
    // Explicit cells belong to the authored matrix. A target override starts a
    // new stage-position mapping for the selected fixtures/groups.
    request.cells.clear();
    request
}

fn apply_fixture_index_chaser_effect_target_override(
    mut request: ChaserEffectRequest,
    target_override: &EffectTargetOverride,
    snapshot: &EngineSnapshot,
) -> Result<ChaserEffectRequest, String> {
    validate_chaser_effect_target_override(target_override)?;
    let fixture_ids = resolve_chaser_effect_target_override(target_override, snapshot)?;
    let single_fixture_target = fixture_ids.len() == 1;

    let active_level = request
        .steps
        .iter()
        .map(|step| step.level)
        .max()
        .filter(|level| *level > 0)
        .unwrap_or(u16::MAX);
    request.steps = fixture_ids
        .into_iter()
        .map(|fixture_id| ChaserStep {
            fixture_ids: vec![fixture_id],
            target_group_ids: Vec::new(),
            beam_targets: Vec::new(),
            level: active_level,
        })
        .collect();
    if request.steps.len() == 1 {
        request.steps.push(ChaserStep {
            fixture_ids: Vec::new(),
            target_group_ids: Vec::new(),
            beam_targets: Vec::new(),
            level: 0,
        });
    }
    if single_fixture_target {
        request.active_step_count = 1;
        request.wings = 1;
    } else {
        request.active_step_count = request
            .active_step_count
            .max(1)
            .min(request.steps.len().min(64) as u16);
        request.wings = request.wings.max(1).min(request.steps.len().min(16) as u8);
    }
    if request.features.len() == 1 && !target_override.attribute.trim().is_empty() {
        request.features[0].attribute = overridden_light_attribute(target_override);
    }
    Ok(request)
}

fn resolve_chaser_effect_target_override(
    target_override: &EffectTargetOverride,
    snapshot: &EngineSnapshot,
) -> Result<Vec<FixtureId>, String> {
    validate_effect_target_references(snapshot, &target_override.fixture_ids, &[])?;

    let mut fixture_ids = Vec::new();
    let mut seen_fixture_ids = HashSet::new();
    for fixture_id in &target_override.fixture_ids {
        if seen_fixture_ids.insert(*fixture_id) {
            fixture_ids.push(*fixture_id);
        }
    }
    for group_id in &target_override.target_group_ids {
        let mut matched = false;
        for fixture in &snapshot.fixtures {
            if fixture
                .group_ids
                .iter()
                .any(|candidate| group_matches(candidate, group_id))
            {
                matched = true;
                if seen_fixture_ids.insert(fixture.id) {
                    fixture_ids.push(fixture.id);
                }
            }
        }
        if !matched {
            return Err(format!(
                "Group '{group_id}' was not found or has no fixtures"
            ));
        }
    }
    if fixture_ids.is_empty() {
        return Err("Chaser effects require at least one resolved fixture target".to_string());
    }
    Ok(fixture_ids)
}

fn validate_color_effect_target_override(
    target_override: &EffectTargetOverride,
) -> Result<(), String> {
    if target_override.fixture_ids.is_empty() && target_override.target_group_ids.is_empty() {
        return Err("Color effects require a fixture, selection, or group target".to_string());
    }
    if !target_override.video_targets.is_empty() {
        return Err("Color effects cannot target video parameters".to_string());
    }
    validate_group_ids(&target_override.target_group_ids)
}

fn validate_chaser_effect_target_override(
    target_override: &EffectTargetOverride,
) -> Result<(), String> {
    if !target_override.video_targets.is_empty() {
        return Err("Chaser effects cannot target video parameters".to_string());
    }
    if target_override.fixture_ids.is_empty() && target_override.target_group_ids.is_empty() {
        return Err("Chaser effects require a fixture, selection, or group target".to_string());
    }
    validate_group_ids(&target_override.target_group_ids)
}

fn validate_move_effect_target_override(
    target_override: &EffectTargetOverride,
) -> Result<(), String> {
    if !target_override.video_targets.is_empty() {
        return Err("Move effects cannot target video parameters".to_string());
    }
    if target_override.fixture_ids.is_empty() && target_override.target_group_ids.is_empty() {
        return Err("Move effects require a fixture, selection, or group target".to_string());
    }
    validate_group_ids(&target_override.target_group_ids)
}

fn overridden_light_attribute(target_override: &EffectTargetOverride) -> String {
    if target_override.fixture_ids.is_empty() && target_override.target_group_ids.is_empty() {
        String::new()
    } else {
        target_override.attribute.trim().to_string()
    }
}

fn validate_effect_target_override(target_override: &EffectTargetOverride) -> Result<(), String> {
    let has_light_targets =
        !target_override.fixture_ids.is_empty() || !target_override.target_group_ids.is_empty();
    let has_video_targets = !target_override.video_targets.is_empty();
    if !has_light_targets && !has_video_targets {
        return Err("At least one fixture, group, or video layer must be targeted".to_string());
    }
    if has_light_targets && target_override.attribute.trim().is_empty() {
        return Err("Effect attribute is required".to_string());
    }
    validate_group_ids(&target_override.target_group_ids)?;
    validate_video_effect_targets(&target_override.video_targets)?;
    Ok(())
}

fn validate_effect_target_override_for_preset(
    preset: &EffectPreset,
    target_override: &EffectTargetOverride,
) -> Result<(), String> {
    match preset.effect_type {
        EffectKind::Color | EffectKind::ColorMapping => {
            validate_color_effect_target_override(target_override)
        }
        EffectKind::Chaser => {
            preset
                .chaser
                .as_ref()
                .ok_or_else(|| "Chaser effect preset is missing its request body".to_string())?;
            validate_chaser_effect_target_override(target_override)
        }
        EffectKind::Move => {
            preset
                .move_effect
                .as_ref()
                .ok_or_else(|| "Move effect preset is missing its request body".to_string())?;
            validate_move_effect_target_override(target_override)
        }
        EffectKind::Value => {
            preset
                .value
                .as_ref()
                .ok_or_else(|| "Value effect preset is missing its request body".to_string())?;
            validate_effect_target_override(target_override)
        }
        EffectKind::Curve => {
            preset
                .curve
                .as_ref()
                .ok_or_else(|| "Curve effect preset is missing its request body".to_string())?;
            validate_effect_target_override(target_override)
        }
        EffectKind::Mapping => {
            preset
                .mapping
                .as_ref()
                .ok_or_else(|| "Mapping effect preset is missing its request body".to_string())?;
            validate_effect_target_override(target_override)
        }
        EffectKind::Lfo | EffectKind::PositionWave => {
            validate_effect_target_override(target_override)
        }
    }
}

fn validate_node_graph_summary(
    graph: &NodeGraphSummary,
    snapshot: &EngineSnapshot,
) -> Result<(), String> {
    if graph.id == 0 {
        return Err("Node graph id must be greater than 0".to_string());
    }
    if graph.label.trim().is_empty() {
        return Err("Node graph label is required".to_string());
    }
    if graph.nodes.is_empty() {
        return Err("Node graph requires at least one node".to_string());
    }

    let mut node_ids = HashSet::new();
    for node in &graph.nodes {
        if node.id == 0 {
            return Err(format!("Node graph '{}' contains node id 0", graph.label));
        }
        if !node_ids.insert(node.id) {
            return Err(format!(
                "Node graph '{}' contains duplicate node id {}",
                graph.label, node.id
            ));
        }
        if node.label.trim().is_empty() {
            return Err(format!(
                "Node graph '{}' node {} has an empty label",
                graph.label, node.id
            ));
        }
        if !node.x.is_finite() || !node.y.is_finite() {
            return Err(format!(
                "Node graph '{}' node {} has non-finite coordinates",
                graph.label, node.id
            ));
        }

        match node.kind {
            NodeGraphNodeKind::Lfo => {
                if node.position_wave.is_some()
                    || node.audio.is_some()
                    || node.transform.is_some()
                    || node.output.is_some()
                {
                    return Err(format!(
                        "Node graph '{}' LFO node {} contains a non-LFO body",
                        graph.label, node.id
                    ));
                }
                let Some(lfo) = &node.lfo else {
                    return Err(format!(
                        "Node graph '{}' LFO node {} is missing its body",
                        graph.label, node.id
                    ));
                };
                if lfo.period_ms < 10 {
                    return Err(format!(
                        "Node graph '{}' LFO node {} period must be at least 10ms",
                        graph.label, node.id
                    ));
                }
                if !lfo.phase.is_finite() || !lfo.amplitude.is_finite() || !lfo.bias.is_finite() {
                    return Err(format!(
                        "Node graph '{}' LFO node {} has non-finite values",
                        graph.label, node.id
                    ));
                }
                if let Some(clock_sync) = lfo.clock_sync {
                    if !clock_sync.beats.is_finite() || clock_sync.beats <= 0.0 {
                        return Err(format!(
                            "Node graph '{}' LFO node {} clock sync beats must be greater than 0",
                            graph.label, node.id
                        ));
                    }
                }
            }
            NodeGraphNodeKind::PositionWave => {
                if node.lfo.is_some()
                    || node.audio.is_some()
                    || node.transform.is_some()
                    || node.output.is_some()
                {
                    return Err(format!(
                        "Node graph '{}' position wave node {} contains a non-position-wave body",
                        graph.label, node.id
                    ));
                }
                let Some(wave) = &node.position_wave else {
                    return Err(format!(
                        "Node graph '{}' position wave node {} is missing its body",
                        graph.label, node.id
                    ));
                };
                if !wave.origin.x.is_finite()
                    || !wave.origin.y.is_finite()
                    || !wave.origin.z.is_finite()
                    || !wave.direction.x.is_finite()
                    || !wave.direction.y.is_finite()
                    || !wave.direction.z.is_finite()
                    || !wave.speed.is_finite()
                    || !wave.wavelength.is_finite()
                    || !wave.phase.is_finite()
                {
                    return Err(format!(
                        "Node graph '{}' position wave node {} has non-finite values",
                        graph.label, node.id
                    ));
                }
                if wave.wavelength.abs() < 0.001 {
                    return Err(format!(
                        "Node graph '{}' position wave node {} wavelength must be at least 0.001",
                        graph.label, node.id
                    ));
                }
                if let Some(clock_sync) = wave.clock_sync {
                    if !clock_sync.beats.is_finite() || clock_sync.beats <= 0.0 {
                        return Err(format!(
                            "Node graph '{}' position wave node {} clock sync beats must be greater than 0",
                            graph.label, node.id
                        ));
                    }
                }
            }
            NodeGraphNodeKind::Audio => {
                if node.lfo.is_some()
                    || node.position_wave.is_some()
                    || node.transform.is_some()
                    || node.output.is_some()
                {
                    return Err(format!(
                        "Node graph '{}' audio node {} contains a non-audio body",
                        graph.label, node.id
                    ));
                }
                let Some(audio) = &node.audio else {
                    return Err(format!(
                        "Node graph '{}' audio node {} is missing its body",
                        graph.label, node.id
                    ));
                };
                if !audio.gain.is_finite() || !audio.bias.is_finite() {
                    return Err(format!(
                        "Node graph '{}' audio node {} has non-finite values",
                        graph.label, node.id
                    ));
                }
            }
            NodeGraphNodeKind::Transform => {
                if node.lfo.is_some()
                    || node.position_wave.is_some()
                    || node.audio.is_some()
                    || node.output.is_some()
                {
                    return Err(format!(
                        "Node graph '{}' transform node {} contains a non-transform body",
                        graph.label, node.id
                    ));
                }
                let Some(transform) = &node.transform else {
                    return Err(format!(
                        "Node graph '{}' transform node {} is missing its body",
                        graph.label, node.id
                    ));
                };
                if !transform.amount.is_finite()
                    || !transform.min.is_finite()
                    || !transform.max.is_finite()
                {
                    return Err(format!(
                        "Node graph '{}' transform node {} has non-finite values",
                        graph.label, node.id
                    ));
                }
                if matches!(transform.op, NodeGraphTransformOp::Clamp)
                    && transform.min > transform.max
                {
                    return Err(format!(
                        "Node graph '{}' clamp node {} min must be <= max",
                        graph.label, node.id
                    ));
                }
            }
            NodeGraphNodeKind::Output => {
                if node.lfo.is_some()
                    || node.position_wave.is_some()
                    || node.audio.is_some()
                    || node.transform.is_some()
                {
                    return Err(format!(
                        "Node graph '{}' output node {} contains a non-output body",
                        graph.label, node.id
                    ));
                }
                let Some(output) = &node.output else {
                    return Err(format!(
                        "Node graph '{}' output node {} is missing its body",
                        graph.label, node.id
                    ));
                };
                let has_light_targets =
                    !output.fixture_ids.is_empty() || !output.target_group_ids.is_empty();
                if has_light_targets && output.attribute.trim().is_empty() {
                    return Err(format!(
                        "Node graph '{}' output node {} is missing its light attribute",
                        graph.label, node.id
                    ));
                }
                if !has_light_targets && output.video_targets.is_empty() {
                    return Err(format!(
                        "Node graph '{}' output node {} requires a light or video target",
                        graph.label, node.id
                    ));
                }
                validate_group_ids(&output.target_group_ids)?;
                validate_video_effect_targets(&output.video_targets)?;
                let fixtures_by_id = snapshot
                    .fixtures
                    .iter()
                    .map(|fixture| (fixture.id, fixture))
                    .collect::<HashMap<_, _>>();
                validate_project_effect_fixture_targets(
                    snapshot,
                    &fixtures_by_id,
                    &output.fixture_ids,
                    &output.target_group_ids,
                    &output.attribute,
                    &format!("node graph '{}' output node {}", graph.label, node.id),
                )?;
                validate_effect_target_references(
                    snapshot,
                    &output.fixture_ids,
                    &output.video_targets,
                )?;
            }
        }
    }

    for edge in &graph.edges {
        if !node_ids.contains(&edge.from_node) || !node_ids.contains(&edge.to_node) {
            return Err(format!(
                "Node graph '{}' contains an edge with a missing node reference",
                graph.label
            ));
        }
        if edge.from_port.trim().is_empty() || edge.to_port.trim().is_empty() {
            return Err(format!(
                "Node graph '{}' contains an edge with an empty port",
                graph.label
            ));
        }
    }

    Ok(())
}

fn validate_node_graph_preset_file(
    file: &NodeGraphPresetFile,
    snapshot: &EngineSnapshot,
) -> Result<(), String> {
    if file.version != 1 {
        return Err(format!(
            "Unsupported node graph preset version {}",
            file.version
        ));
    }
    validate_app_name("node graph preset", &file.app)?;
    validate_node_graph_summary(&file.graph, snapshot)
}

fn validate_effect_preset(preset: &EffectPreset) -> Result<(), String> {
    if preset.version != 1 {
        return Err(format!(
            "Unsupported effect preset version {}",
            preset.version
        ));
    }
    match preset.effect_type {
        EffectKind::Lfo => {
            if preset.position_wave.is_some()
                || preset.color.is_some()
                || preset.chaser.is_some()
                || preset.move_effect.is_some()
                || preset.value.is_some()
                || preset.curve.is_some()
                || preset.mapping.is_some()
                || preset.color_mapping.is_some()
            {
                return Err("LFO effect preset must not contain another effect body".to_string());
            }
            let request = preset
                .lfo
                .as_ref()
                .ok_or_else(|| "LFO effect preset is missing its request body".to_string())?;
            validate_lfo_effect_request(request)?;
        }
        EffectKind::PositionWave => {
            if preset.lfo.is_some()
                || preset.color.is_some()
                || preset.chaser.is_some()
                || preset.move_effect.is_some()
                || preset.value.is_some()
                || preset.curve.is_some()
                || preset.mapping.is_some()
                || preset.color_mapping.is_some()
            {
                return Err(
                    "Position wave effect preset must not contain another effect body".to_string(),
                );
            }
            let request = preset.position_wave.as_ref().ok_or_else(|| {
                "Position wave effect preset is missing its request body".to_string()
            })?;
            validate_position_wave_effect_request(request)?;
        }
        EffectKind::Color => {
            if preset.lfo.is_some()
                || preset.position_wave.is_some()
                || preset.chaser.is_some()
                || preset.move_effect.is_some()
                || preset.value.is_some()
                || preset.curve.is_some()
                || preset.mapping.is_some()
                || preset.color_mapping.is_some()
            {
                return Err("Color effect preset must not contain another effect body".to_string());
            }
            let request = preset
                .color
                .as_ref()
                .ok_or_else(|| "Color effect preset is missing its request body".to_string())?;
            validate_color_effect_request(request)?;
        }
        EffectKind::Chaser => {
            if preset.lfo.is_some()
                || preset.position_wave.is_some()
                || preset.color.is_some()
                || preset.move_effect.is_some()
                || preset.value.is_some()
                || preset.curve.is_some()
                || preset.mapping.is_some()
                || preset.color_mapping.is_some()
            {
                return Err("Chaser effect preset must not contain another effect body".to_string());
            }
            let request = preset
                .chaser
                .as_ref()
                .ok_or_else(|| "Chaser effect preset is missing its request body".to_string())?;
            validate_chaser_effect_request(request)?;
        }
        EffectKind::Move => {
            if preset.lfo.is_some()
                || preset.position_wave.is_some()
                || preset.color.is_some()
                || preset.chaser.is_some()
                || preset.value.is_some()
                || preset.curve.is_some()
                || preset.mapping.is_some()
                || preset.color_mapping.is_some()
            {
                return Err("Move effect preset must not contain another effect body".to_string());
            }
            let request = preset
                .move_effect
                .as_ref()
                .ok_or_else(|| "Move effect preset is missing its request body".to_string())?;
            validate_move_effect_request(request)?;
        }
        EffectKind::Value => {
            if preset.lfo.is_some()
                || preset.position_wave.is_some()
                || preset.color.is_some()
                || preset.chaser.is_some()
                || preset.move_effect.is_some()
                || preset.curve.is_some()
                || preset.mapping.is_some()
                || preset.color_mapping.is_some()
            {
                return Err("Value effect preset must not contain another effect body".to_string());
            }
            let request = preset
                .value
                .as_ref()
                .ok_or_else(|| "Value effect preset is missing its request body".to_string())?;
            validate_value_effect_request(request)?;
        }
        EffectKind::Curve => {
            if preset.lfo.is_some()
                || preset.position_wave.is_some()
                || preset.color.is_some()
                || preset.chaser.is_some()
                || preset.move_effect.is_some()
                || preset.value.is_some()
                || preset.mapping.is_some()
                || preset.color_mapping.is_some()
            {
                return Err("Curve effect preset must not contain another effect body".to_string());
            }
            let request = preset
                .curve
                .as_ref()
                .ok_or_else(|| "Curve effect preset is missing its request body".to_string())?;
            validate_curve_effect_request(request)?;
        }
        EffectKind::Mapping => {
            if preset.lfo.is_some()
                || preset.position_wave.is_some()
                || preset.color.is_some()
                || preset.chaser.is_some()
                || preset.move_effect.is_some()
                || preset.value.is_some()
                || preset.curve.is_some()
                || preset.color_mapping.is_some()
            {
                return Err(
                    "Mapping effect preset must not contain another effect body".to_string()
                );
            }
            let request = preset
                .mapping
                .as_ref()
                .ok_or_else(|| "Mapping effect preset is missing its request body".to_string())?;
            validate_mapping_effect_request(request)?;
        }
        EffectKind::ColorMapping => {
            if preset.lfo.is_some()
                || preset.position_wave.is_some()
                || preset.color.is_some()
                || preset.chaser.is_some()
                || preset.move_effect.is_some()
                || preset.value.is_some()
                || preset.curve.is_some()
                || preset.mapping.is_some()
            {
                return Err(
                    "Colour Mapping effect preset must not contain another effect body".to_string(),
                );
            }
            let request = preset.color_mapping.as_ref().ok_or_else(|| {
                "Colour Mapping effect preset is missing its request body".to_string()
            })?;
            validate_color_mapping_effect_request(request)?;
        }
    }
    Ok(())
}

fn validate_effect_target_references(
    snapshot: &EngineSnapshot,
    fixture_ids: &[FixtureId],
    video_targets: &[VideoEffectTarget],
) -> Result<(), String> {
    for fixture_id in fixture_ids {
        if !snapshot
            .fixtures
            .iter()
            .any(|fixture| fixture.id == *fixture_id)
        {
            return Err(format!("Fixture {fixture_id} was not found"));
        }
    }
    for target in video_targets {
        validate_video_layer_ids(snapshot, &target.layer_ids)?;
    }
    Ok(())
}

fn validate_fixture_preset<'a>(
    preset: &FixturePreset,
    manufacturer: &str,
    profile_name: &str,
    mode_name: &str,
    valid_attributes: impl IntoIterator<Item = &'a str>,
) -> Result<(), String> {
    if preset.version != 1 {
        return Err(format!("Unsupported preset version {}", preset.version));
    }
    if preset.manufacturer != manufacturer
        || preset.profile_name != profile_name
        || preset.mode_name != mode_name
    {
        return Err(format!(
            "Preset is for {} {} / {}, but selected fixture is {} {} / {}",
            preset.manufacturer,
            preset.profile_name,
            preset.mode_name,
            manufacturer,
            profile_name,
            mode_name
        ));
    }
    let valid_attributes = valid_attributes.into_iter().collect::<HashSet<_>>();
    let mut preset_attributes = HashSet::new();
    for value in &preset.values {
        if !preset_attributes.insert(value.attribute.as_str()) {
            return Err(format!(
                "Preset contains duplicate attribute '{}'",
                value.attribute
            ));
        }
    }
    if let Some(value) = preset
        .values
        .iter()
        .find(|value| !valid_attributes.contains(value.attribute.as_str()))
    {
        return Err(format!(
            "Preset attribute '{}' is not available on the selected fixture mode",
            value.attribute
        ));
    }
    Ok(())
}

fn compatible_fixture_preset_targets(
    preset: &FixturePreset,
    fixtures: Vec<&PatchedFixtureSummary>,
) -> (Vec<FixtureId>, usize) {
    let mut fixture_ids = Vec::new();
    let mut skipped_count = 0usize;
    for fixture in fixtures {
        let compatible = validate_fixture_preset(
            preset,
            &fixture.manufacturer,
            &fixture.profile_name,
            &fixture.mode_name,
            fixture
                .controls
                .iter()
                .map(|control| control.attribute.as_str()),
        )
        .is_ok();
        if compatible {
            fixture_ids.push(fixture.id);
        } else {
            skipped_count += 1;
        }
    }
    (fixture_ids, skipped_count)
}

#[tauri::command]
fn get_snapshot(state: State<'_, AppState>) -> EngineSnapshotRuntimeWireResponse {
    let snapshot = state.engine.snapshot();
    EngineSnapshotRuntimeWireResponse {
        timeline_runtime: timeline_runtime_snapshot_wire(&snapshot),
        snapshot,
    }
}

#[tauri::command]
async fn get_snapshot_delta(
    app: tauri::AppHandle,
    client_revision: Option<u64>,
) -> Result<EngineSnapshotSyncResponse, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let state = app.state::<AppState>();
        let mut sync = state
            .snapshot_sync
            .lock()
            .map_err(|_| "Snapshot synchronization lock was poisoned".to_string())?;
        // Capture under the synchronization lock so concurrent windows cannot
        // publish an older captured sample after a newer one. Snapshot cloning
        // still holds this lock; reducing engine snapshot cost is a separate task.
        let current = state.engine.snapshot();
        let timeline_runtime = timeline_runtime_snapshot_wire(&current);
        let payload = sync.publish(client_revision, current)?;
        Ok(EngineSnapshotSyncResponse {
            revision: payload.revision,
            timeline_runtime,
            full: payload.full,
            delta: payload.delta,
        })
    })
    .await
    .map_err(|error| format!("Snapshot delta query worker failed: {error}"))?
}

struct StageProjectTransactionRequest {
    project_transaction_id: u64,
    expected_epoch: u64,
    owner_id: String,
    window_label: String,
    command_name: &'static str,
}

struct PreparedStageProjectMutation {
    mutation: StageProjectMutation,
    stage_object_id: Option<StageObjectId>,
    label: Option<String>,
}

/// The D4 Stage adapter over the existing ProjectTransactionReceipt lane.
/// Every route computes its normalized payload while its ticket is admitted,
/// replays the exact stored command result before reaching the engine, and
/// persists the Engine's explicit Applied/Unchanged acknowledgement before its
/// legacy-shaped reply is reconstructed by the caller.
fn apply_stage_project_mutation_in_project_transaction<C>(
    state: &AppState,
    request: StageProjectTransactionRequest,
    canonical_request: impl FnOnce(&AppState) -> Result<C, String>,
    build_mutation: impl FnOnce(&AppState, C) -> Result<PreparedStageProjectMutation, String>,
) -> Result<ProjectTransactionCommandResult, String>
where
    C: Serialize,
{
    apply_stage_project_mutation_in_project_transaction_with_publish(
        state,
        request,
        canonical_request,
        build_mutation,
        |engine, mutation| engine.apply_stage_project_mutation_published(mutation),
    )
}

fn apply_stage_project_mutation_in_project_transaction_with_publish<C>(
    state: &AppState,
    request: StageProjectTransactionRequest,
    canonical_request: impl FnOnce(&AppState) -> Result<C, String>,
    build_mutation: impl FnOnce(&AppState, C) -> Result<PreparedStageProjectMutation, String>,
    publish: impl FnOnce(
        &EngineHandle,
        StageProjectMutation,
    ) -> Result<StageProjectMutationOutcome, FixturePatchPublicationFailure>,
) -> Result<ProjectTransactionCommandResult, String>
where
    C: Serialize,
{
    let StageProjectTransactionRequest {
        project_transaction_id,
        expected_epoch,
        owner_id,
        window_label,
        command_name,
    } = request;
    let window_label = window_label.as_str();
    let (_external_admission, mut coordinator, transaction_admission) =
        lock_renderer_ticketed_project_mutation(
            state,
            window_label,
            command_name,
            project_transaction_id,
            expected_epoch,
            &owner_id,
        )?;
    // Saving a Stage preset intentionally captures the current canonical Stage
    // objects only after the ticket boundary is live. The same closure is also
    // how every other route proves its normalized request before allocation or
    // publication.
    let canonical_request = canonical_request(state)?;
    let request_digest =
        project_transaction_command_request_digest(command_name, &canonical_request)?;
    let pending = project_transaction_for_owner_epoch(
        &coordinator,
        project_transaction_id,
        expected_epoch,
        &owner_id,
    )?;
    if let Some(result) =
        project_transaction_existing_command_result(&pending, command_name, &request_digest)?
    {
        return Ok(result);
    }

    // Add allocates only after the exact user-intent digest has missed the
    // receipt. The generated ID therefore never changes the digest or turns a
    // reply-loss retry into a second allocation.
    let prepared = build_mutation(state, canonical_request)?;
    let prepared_result_publication =
        prepare_project_transaction_command_result_publication(state, &coordinator, &pending)?;
    let outcome = match publish(&state.engine, prepared.mutation) {
        Ok(outcome) => outcome,
        Err(FixturePatchPublicationFailure::Definitive(error)) => return Err(error),
        Err(FixturePatchPublicationFailure::Indeterminate(error)) => {
            return Err(mark_project_transaction_publication_indeterminate(
                state,
                &mut coordinator,
                prepared_result_publication,
                error,
            ));
        }
    };
    let result = ProjectTransactionCommandResult::StageProjectMutation {
        command_name: command_name.to_string(),
        request_digest,
        outcome: outcome.into(),
        stage_object_id: prepared.stage_object_id,
        label: prepared.label,
    };
    prepared_result_publication.commit(&mut coordinator, result.clone());
    drop(transaction_admission);
    Ok(result)
}

fn stage_project_transaction_unit_result(
    result: ProjectTransactionCommandResult,
    command_name: &str,
) -> Result<(), String> {
    match result {
        ProjectTransactionCommandResult::StageProjectMutation {
            command_name: stored_command_name,
            ..
        } if stored_command_name == command_name => Ok(()),
        _ => Err("Stage project transaction receipt did not match its unit route".to_string()),
    }
}

fn stage_project_transaction_stage_object_id_result(
    result: ProjectTransactionCommandResult,
    command_name: &str,
) -> Result<StageObjectId, String> {
    match result {
        ProjectTransactionCommandResult::StageProjectMutation {
            command_name: stored_command_name,
            stage_object_id: Some(stage_object_id),
            ..
        } if stored_command_name == command_name => Ok(stage_object_id),
        _ => {
            Err("Stage project transaction receipt did not retain the added object ID".to_string())
        }
    }
}

fn stage_project_transaction_label_result(
    result: ProjectTransactionCommandResult,
    command_name: &str,
) -> Result<String, String> {
    match result {
        ProjectTransactionCommandResult::StageProjectMutation {
            command_name: stored_command_name,
            label: Some(label),
            ..
        } if stored_command_name == command_name => Ok(label),
        _ => Err("Stage project transaction receipt did not retain its label result".to_string()),
    }
}

#[derive(Clone, Serialize)]
struct StageObjectAddIntent {
    label: String,
    kind: StageObjectKind,
    x: f32,
    z: f32,
    width: f32,
    depth: f32,
    rotation_deg: f32,
    color: Option<String>,
}

fn normalize_stage_object_add_intent(
    intent: StageObjectAddIntent,
) -> Result<StageObjectAddIntent, String> {
    // A non-zero sentinel exercises precisely the same normalization and
    // validation as the eventual allocated object without allowing the ID to
    // enter the canonical user-intent digest.
    let object = normalize_stage_object(StageObjectSummary {
        id: 1,
        label: intent.label,
        kind: intent.kind,
        x: intent.x,
        z: intent.z,
        width: intent.width,
        depth: intent.depth,
        rotation_deg: intent.rotation_deg,
        color: intent.color,
    })?;
    Ok(StageObjectAddIntent {
        label: object.label,
        kind: object.kind,
        x: object.x,
        z: object.z,
        width: object.width,
        depth: object.depth,
        rotation_deg: object.rotation_deg,
        color: object.color,
    })
}

#[tauri::command]
fn set_stage_map_config(
    window: WebviewWindow,
    state: State<'_, AppState>,
    config: StageMapConfig,
    project_transaction_id: u64,
    expected_epoch: u64,
    owner_id: String,
) -> Result<(), String> {
    validate_stage_map_config(&config)?;
    stage_project_transaction_unit_result(
        apply_stage_project_mutation_in_project_transaction(
            &state,
            StageProjectTransactionRequest {
                project_transaction_id,
                expected_epoch,
                owner_id,
                window_label: window.label().to_string(),
                command_name: "set_stage_map_config",
            },
            |_| Ok(config),
            |_, config| {
                Ok(PreparedStageProjectMutation {
                    mutation: StageProjectMutation::SetStageMapConfig(config),
                    stage_object_id: None,
                    label: None,
                })
            },
        )?,
        "set_stage_map_config",
    )
}

#[tauri::command]
fn set_touch_surface(
    state: State<'_, AppState>,
    surface: TouchSurfaceSummary,
) -> Result<(), String> {
    validate_touch_surface(&surface, &state.engine.snapshot())?;
    state.engine.set_touch_surface(surface)
}

#[tauri::command]
fn save_stage_map_preset(
    window: WebviewWindow,
    state: State<'_, AppState>,
    label: String,
    config: StageMapConfig,
    project_transaction_id: u64,
    expected_epoch: u64,
    owner_id: String,
) -> Result<String, String> {
    let label = normalize_stage_map_preset_label(label)?;
    validate_stage_map_config(&config)?;
    stage_project_transaction_label_result(
        apply_stage_project_mutation_in_project_transaction(
            &state,
            StageProjectTransactionRequest {
                project_transaction_id,
                expected_epoch,
                owner_id,
                window_label: window.label().to_string(),
                command_name: "save_stage_map_preset",
            },
            |state| {
                Ok(StageMapPresetSummary {
                    label,
                    config,
                    stage_objects: Some(canonical_stage_project_objects(
                        state.engine.snapshot().stage_objects,
                    )?),
                })
            },
            |_, preset| {
                let label = preset.label.clone();
                Ok(PreparedStageProjectMutation {
                    mutation: StageProjectMutation::SaveStageMapPreset {
                        label,
                        config: preset.config,
                        stage_objects: preset.stage_objects,
                    },
                    stage_object_id: None,
                    label: Some(preset.label),
                })
            },
        )?,
        "save_stage_map_preset",
    )
}

