    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio", test))]
    pub(crate) static TIMELINE_CUE_ASIO_ROUTER_TEST_LOCK: LazyLock<Mutex<()>> =
        LazyLock::new(|| Mutex::new(()));
    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio", test))]
    static TIMELINE_CUE_ASIO_ROUTER: LazyLock<Arc<audio_output_router::RouterSlot>> =
        LazyLock::new(audio_output_router::RouterSlot::test_slot);

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio", test))]
    fn start_test_asio_router() -> Arc<audio_output_router::RouterSlot> {
        let slot = Arc::clone(&TIMELINE_CUE_ASIO_ROUTER);
        match slot.snapshot().unwrap().state {
            audio_output_router::State::Normal => {
                slot.quiesce().unwrap();
                assert!(slot
                    .into_admitted_start_with(|| Ok(()))
                    .unwrap()
                    .perform()
                    .succeeded());
            }
            audio_output_router::State::Locked => {
                assert!(slot
                    .into_revalidation_with(|| Ok(()))
                    .unwrap()
                    .perform()
                    .succeeded());
                assert!(slot
                    .into_validated_start_with(|| Ok(()))
                    .unwrap()
                    .perform()
                    .succeeded());
            }
            audio_output_router::State::AsioActive => {}
            state => panic!("test ASIO router was left in unexpected state {state:?}"),
        }
        assert_eq!(
            slot.snapshot().unwrap().state,
            audio_output_router::State::AsioActive
        );
        slot
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio", test))]
    fn select_test_normal_router() -> Arc<audio_output_router::RouterSlot> {
        let slot = Arc::clone(&TIMELINE_CUE_ASIO_ROUTER);
        match slot.snapshot().unwrap().state {
            audio_output_router::State::AsioActive => {
                assert!(slot
                    .into_stop_with(|| Ok(()))
                    .unwrap()
                    .perform()
                    .succeeded());
            }
            audio_output_router::State::Locked => {}
            audio_output_router::State::Normal => return slot,
            state => panic!("test ASIO router was left in unexpected state {state:?}"),
        }
        slot.select_normal().unwrap();
        assert_eq!(
            slot.snapshot().unwrap().state,
            audio_output_router::State::Normal
        );
        slot
    }

    #[cfg(all(target_os = "windows", target_arch = "x86_64", feature = "asio", test))]
    #[test]
    fn asio_ready_profile_reselection_and_normal_return_cancel_the_ready_ticket() {
        let slot = audio_output_router::RouterSlot::test_slot();
        slot.quiesce().unwrap();
        assert!(slot
            .into_admitted_start_with(|| Ok(()))
            .unwrap()
            .perform()
            .succeeded());
        assert!(slot
            .into_stop_with(|| Ok(()))
            .unwrap()
            .perform()
            .succeeded());
        assert!(slot
            .into_revalidation_with(|| Ok(()))
            .unwrap()
            .perform()
            .succeeded());
        assert_eq!(
            slot.snapshot().unwrap().state,
            audio_output_router::State::AsioReady
        );

        prepare_asio_router_for_profile_reselection(&slot).unwrap();
        let after_reselection = slot.snapshot().unwrap();
        assert_eq!(after_reselection.state, audio_output_router::State::Locked);
        assert!(after_reselection.operation.is_none());
        assert!(after_reselection.session.is_none());
        assert!(matches!(
            slot.into_validated_start_with(|| Ok(())),
            Err(audio_output_router::Error::ReadyMismatch)
        ));

        assert!(slot
            .into_revalidation_with(|| Ok(()))
            .unwrap()
            .perform()
            .succeeded());
        let normal = select_normal_audio_output_router(&slot).unwrap();
        assert_eq!(normal.state, audio_output_router::State::Normal);
        assert!(normal.operation.is_none());
        assert!(normal.session.is_none());
    }

