    fn dsf2026_public_terminal_request(
        operation_id: &'static str,
        request_id: u64,
    ) -> OutputControlCommandRequestV2 {
        use protocol::control_plane_command::{OutputControlActionV2, OutputLeaseAuthorityV1};
        let lease = OutputLeaseAuthorityV1 {
            lease_id: "lease-0000000000000001".to_string(),
            generation: 1,
        };
        let action = match operation_id {
            OUTPUT_DSF2026_ARTNET_ACCEPTANCE_PROBE_OPERATION_ID => {
                OutputControlActionV2::SendDsf2026ArtNetAcceptanceProbe { lease }
            }
            OUTPUT_DSF2026_ARTNET_ACCEPTANCE_PROBE_RECONCILE_OPERATION_ID => {
                OutputControlActionV2::AcknowledgeDsf2026ArtNetAcceptanceProbeInDoubt { lease }
            }
            _ => panic!("test requires a DSF2026 operation"),
        };
        let request = OutputControlCommandRequestV2 {
            operation_id: operation_id.to_string(),
            request_id,
            expected_fence: OutputControlFenceV1 {
                process_incarnation: 1,
                session_incarnation: 1,
                project_epoch: 1,
                project_revision: 1,
                project_checkpoint_hash: "a".repeat(64),
                project_publication_generation: 1,
                output_epoch: 1,
                output_generation: 1,
                safety_blackout_epoch: 1,
                safety_blackout_generation: 1,
            },
            action,
        };
        request.validate().expect("DSF2026 public terminal request");
        request
    }

    fn dsf2026_public_terminal_response(
        request: &OutputControlCommandRequestV2,
    ) -> OutputControlResponseV2 {
        use protocol::control_plane_command::{
            OutputControlLeaseResultV2, OutputControlReceiptOutcomeV2, OutputControlReceiptV2,
            OutputControlTargetRoleV1, OutputLeaseReceiptChangeV2, OutputLeaseReceiptOutcomeV2,
            OutputLeaseReceiptPhaseV2,
        };
        let authority = match &request.action {
            protocol::control_plane_command::OutputControlActionV2::SendDsf2026ArtNetAcceptanceProbe {
                lease,
            }
            | protocol::control_plane_command::OutputControlActionV2::AcknowledgeDsf2026ArtNetAcceptanceProbeInDoubt {
                lease,
            } => lease.clone(),
            _ => panic!("test requires a DSF2026 action"),
        };
        let resources = vec![
            OutputControlTargetRoleV1::Lighting,
            OutputControlTargetRoleV1::Video,
        ];
        let response = OutputControlResponseV2::Receipt(Box::new(OutputControlReceiptV2 {
            operation_id: request.operation_id.clone(),
            request_id: request.request_id,
            shape_sha256: control_plane_runtime::hex_sha256(
                &request
                    .canonical_shape_bytes()
                    .expect("DSF2026 public terminal shape"),
            ),
            argument_fingerprint: control_plane_runtime::hex_sha256(
                &request
                    .argument_fingerprint_bytes()
                    .expect("DSF2026 public terminal arguments"),
            ),
            audit_sequence: 1,
            fence_before: request.expected_fence.clone(),
            fence_after: request.expected_fence.clone(),
            outcome: OutputControlReceiptOutcomeV2::Applied,
            lease_result: Some(OutputControlLeaseResultV2 {
                authority: authority.clone(),
                resources: resources.clone(),
                phase: OutputLeaseReceiptPhaseV2::HeldActive,
                outcome: OutputLeaseReceiptOutcomeV2::Authorized,
                audit_sequence: 1,
                changes: vec![OutputLeaseReceiptChangeV2 {
                    lease_id: authority.lease_id,
                    before_generation: Some(authority.generation),
                    after_generation: Some(authority.generation),
                    before_resources: resources.clone(),
                    after_resources: resources,
                    before_phase: Some(OutputLeaseReceiptPhaseV2::HeldActive),
                    after_phase: Some(OutputLeaseReceiptPhaseV2::HeldActive),
                }],
            }),
        }));
        response
            .validate()
            .expect("DSF2026 public terminal response");
        response
    }

    fn dsf2026_private_terminal_request_and_receipt(
        public_request: &OutputControlCommandRequestV2,
    ) -> (OutputLeaseRequest, output_lease::OutputLeaseRequestReceipt) {
        dsf2026_private_terminal_request_and_receipt_for(public_request, "local-ui", "main")
    }

    fn dsf2026_private_terminal_request_and_receipt_for(
        public_request: &OutputControlCommandRequestV2,
        principal: &str,
        window_label: &str,
    ) -> (OutputLeaseRequest, output_lease::OutputLeaseRequestReceipt) {
        let (domain, lease) = match &public_request.action {
            protocol::control_plane_command::OutputControlActionV2::SendDsf2026ArtNetAcceptanceProbe {
                lease,
            } => (OUTPUT_LEASE_DSF2026_PROBE_DOMAIN, lease),
            protocol::control_plane_command::OutputControlActionV2::AcknowledgeDsf2026ArtNetAcceptanceProbeInDoubt {
                lease,
            } => (OUTPUT_LEASE_DSF2026_PROBE_RECONCILE_DOMAIN, lease),
            _ => panic!("test requires a DSF2026 public action"),
        };
        let owner = OutputLeaseOwner::new(principal, window_label, 41, 7)
            .expect("DSF2026 private terminal owner");
        let resources =
            OutputLeaseResources::new(&[OutputLeaseResource::Lighting, OutputLeaseResource::Video])
                .expect("DSF2026 private terminal resources");
        let acquire = OutputLeaseRequest::from_action(
            principal,
            "dsf2026-private-fixture",
            1,
            OutputLeaseRequestAction::Acquire {
                owner: owner.clone(),
                resources: resources.clone(),
                project_identity: output_lease_project_identity(1),
                ttl_ms: 30_000,
            },
        )
        .expect("DSF2026 private fixture acquire request");
        let mut registry =
            OutputLeaseRegistry::fresh_process(41).expect("DSF2026 private fixture registry");
        let acquired = registry
            .submit_request(&acquire, 1)
            .expect("DSF2026 private fixture acquire receipt");
        assert_eq!(
            acquired
                .lease_id
                .expect("DSF2026 private fixture lease id")
                .encode(),
            lease.lease_id
        );
        let request = OutputLeaseRequest::from_action(
            principal,
            domain,
            public_request.request_id,
            OutputLeaseRequestAction::AuthorizeOrdinary {
                lease_id: output_lease::OutputLeaseId::decode(&lease.lease_id)
                    .expect("DSF2026 public lease id"),
                owner,
                expected_generation: lease.generation,
                exact_resources: resources,
            },
        )
        .expect("DSF2026 private terminal authorization request");
        let receipt = registry
            .submit_request(&request, 2)
            .expect("DSF2026 private terminal authorization receipt");
        (request, receipt)
    }

    fn record_dsf2026_atomic_terminal_for_test(
        journal: &mut OutputLeaseDurableReceiptJournal,
        private_request: &OutputLeaseRequest,
        private_receipt: &output_lease::OutputLeaseRequestReceipt,
        public_request: &OutputControlCommandRequestV2,
        response: &OutputControlResponseV2,
    ) -> Result<(), String> {
        let prepare = if private_request.key.domain == OUTPUT_LEASE_DSF2026_PROBE_DOMAIN {
            journal.prepare_dsf2026_artnet_acceptance_probe(private_request, "main")
        } else {
            journal.prepare(private_request)
        };
        assert_eq!(
            prepare,
            Ok(OutputLeaseDurablePrepareResult::Fresh),
            "production durable seam must create Pending before terminal persistence"
        );
        let shape_sha256 = control_plane_runtime::hex_sha256(
            &public_request
                .canonical_shape_bytes()
                .expect("DSF2026 atomic public shape"),
        );
        let argument_fingerprint = control_plane_runtime::hex_sha256(
            &public_request
                .argument_fingerprint_bytes()
                .expect("DSF2026 atomic public arguments"),
        );
        journal.record_dsf2026_output_control_terminal(
            private_receipt,
            "local-ui",
            "main",
            public_request,
            &shape_sha256,
            &argument_fingerprint,
            response,
        )
    }

    #[test]
    fn dsf2026_public_terminal_replay_survives_restart_without_confirmation_or_callback() {
        let harness = MediaAssetA6CommandHarness::new();
        let directory = unique_test_directory("dsf2026-public-terminal-replay");
        fs::create_dir_all(&directory).expect("create DSF2026 public-terminal directory");
        let path = directory.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE);
        harness
            .state
            .output_lease_durable_receipts
            .lock()
            .expect("install DSF2026 public terminal journal")
            .install_path(path.clone())
            .expect("persist DSF2026 public terminal journal");

        let request = dsf2026_public_terminal_request(
            OUTPUT_DSF2026_ARTNET_ACCEPTANCE_PROBE_OPERATION_ID,
            41,
        );
        let response = dsf2026_public_terminal_response(&request);
        let (private_request, private_receipt) =
            dsf2026_private_terminal_request_and_receipt(&request);
        let shape_sha256 = control_plane_runtime::hex_sha256(
            &request
                .canonical_shape_bytes()
                .expect("DSF2026 replay public shape"),
        );
        let argument_fingerprint = control_plane_runtime::hex_sha256(
            &request
                .argument_fingerprint_bytes()
                .expect("DSF2026 replay public arguments"),
        );
        {
            let mut journal = harness
                .state
                .output_lease_durable_receipts
                .lock()
                .expect("record atomic DSF2026 public terminal");
            record_dsf2026_atomic_terminal_for_test(
                &mut journal,
                &private_request,
                &private_receipt,
                &request,
                &response,
            )
            .expect(
                "atomically persist private lease receipt, consumed latch, and public response",
            );
        }
        let serialized = serde_json::to_vec(&response).expect("serialize DSF2026 public receipt");
        assert_eq!(
            serde_json::from_slice::<OutputControlResponseV2>(&serialized)
                .expect("deserialize DSF2026 public receipt"),
            response
        );

        let callbacks = AtomicU64::new(0);
        let replay = replay_durable_dsf2026_output_control_terminal(
            &harness.state,
            "local-ui",
            "main",
            &request,
            &shape_sha256,
            &argument_fingerprint,
        )
        .expect("same public request resolves before confirmation");
        if replay.is_none() {
            callbacks.fetch_add(1, Ordering::AcqRel);
        }
        assert_eq!(replay, Some(response.clone()));
        assert_eq!(callbacks.load(Ordering::Acquire), 0);

        let mut restarted = OutputLeaseDurableReceiptJournal::in_memory();
        restarted
            .install_path(path)
            .expect("restart loads DSF2026 public terminal response");
        *harness
            .state
            .output_lease_durable_receipts
            .lock()
            .expect("install restarted DSF2026 public terminal journal") = restarted;
        let restarted_replay = replay_durable_dsf2026_output_control_terminal(
            &harness.state,
            "local-ui",
            "main",
            &request,
            &shape_sha256,
            &argument_fingerprint,
        )
        .expect("restart same public request resolves before confirmation");
        if restarted_replay.is_none() {
            callbacks.fetch_add(1, Ordering::AcqRel);
        }
        assert_eq!(restarted_replay, Some(response));
        assert_eq!(callbacks.load(Ordering::Acquire), 0);

        assert!(
            replay_durable_dsf2026_output_control_terminal(
                &harness.state,
                "other-ui",
                "main",
                &request,
                &shape_sha256,
                &argument_fingerprint,
            )
            .is_err(),
            "a different principal is rejected before confirmation/native action"
        );
        let foreign_owner =
            OutputLeaseOwner::new("other-ui", "main", 41, 7).expect("foreign DSF2026 owner");
        let foreign_probe = OutputLeaseRequest::from_action(
            "other-ui",
            OUTPUT_LEASE_DSF2026_PROBE_DOMAIN,
            42,
            OutputLeaseRequestAction::Acquire {
                owner: foreign_owner,
                resources: OutputLeaseResources::new(&[
                    OutputLeaseResource::Lighting,
                    OutputLeaseResource::Video,
                ])
                .expect("foreign DSF2026 resources"),
                project_identity: output_lease_project_identity(0),
                ttl_ms: 30_000,
            },
        )
        .expect("foreign DSF2026 probe request");
        assert_eq!(
            harness
                .state
                .output_lease_durable_receipts
                .lock()
                .expect("inspect consumed DSF2026 journal")
                .lookup(&foreign_probe),
            Err(output_lease::OutputLeaseError::RequestCapacity),
            "a different principal is denied before its physical callback"
        );

        let mut generic_registry =
            OutputLeaseRegistry::fresh_process(41).expect("generic output-control registry");
        let generic_callbacks = Arc::new(AtomicU64::new(0));
        let generic_callback = Arc::clone(&generic_callbacks);
        submit_output_lease_candidate_with_classified_commit(
            &harness.state,
            &mut generic_registry,
            &durable_output_lease_acquire_request(1),
            1,
            "generic output-control after DSF2026 consumption",
            move || {
                generic_callback.fetch_add(1, Ordering::AcqRel);
                Ok::<(), OutputLeaseCandidateCommitFailure>(())
            },
        )
        .expect("DSF2026 consumption does not suppress the generic output-control callback");
        assert_eq!(generic_callbacks.load(Ordering::Acquire), 1);
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn dsf2026_atomic_terminal_persist_failure_retains_only_pending_and_refuses_resend_after_restart(
    ) {
        let harness = MediaAssetA6CommandHarness::new();
        let directory = unique_test_directory("dsf2026-atomic-terminal-persist-failure");
        fs::create_dir_all(&directory).expect("create DSF2026 atomic-failure directory");
        let durable_path = directory.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE);
        harness
            .state
            .output_lease_durable_receipts
            .lock()
            .expect("install DSF2026 atomic-failure journal")
            .install_path(durable_path.clone())
            .expect("persist empty DSF2026 atomic-failure journal");

        let public_request = dsf2026_public_terminal_request(
            OUTPUT_DSF2026_ARTNET_ACCEPTANCE_PROBE_OPERATION_ID,
            71,
        );
        let public_response = dsf2026_public_terminal_response(&public_request);
        let (private_request, private_receipt) =
            dsf2026_private_terminal_request_and_receipt(&public_request);
        let shape_sha256 = control_plane_runtime::hex_sha256(
            &public_request
                .canonical_shape_bytes()
                .expect("DSF2026 atomic-failure public shape"),
        );
        let argument_fingerprint = control_plane_runtime::hex_sha256(
            &public_request
                .argument_fingerprint_bytes()
                .expect("DSF2026 atomic-failure public arguments"),
        );
        let blocker = directory.join("terminal-persist-blocker");
        fs::write(&blocker, b"not a directory").expect("create terminal persistence blocker");
        {
            let mut journal = harness
                .state
                .output_lease_durable_receipts
                .lock()
                .expect("lock DSF2026 atomic-failure journal");
            assert_eq!(
                journal.prepare_dsf2026_artnet_acceptance_probe(&private_request, "main"),
                Ok(OutputLeaseDurablePrepareResult::Fresh),
                "the physical callback sees a durable Pending marker before terminal persistence"
            );
            // Fault only the terminal replacement.  The already-persisted
            // Pending state at `durable_path` models a power loss/failure
            // between physical success and the one atomic terminal write.
            journal.path = Some(blocker.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE));
            assert!(
                journal
                    .record_dsf2026_output_control_terminal(
                        &private_receipt,
                        "local-ui",
                        "main",
                        &public_request,
                        &shape_sha256,
                        &argument_fingerprint,
                        &public_response,
                    )
                    .is_err(),
                "a failed terminal replacement must not publish a partial terminal candidate"
            );
            assert_eq!(journal.state.pending.len(), 1);
            assert!(journal.state.receipts.is_empty());
            assert!(journal
                .state
                .dsf2026_artnet_acceptance_probe_terminals
                .is_empty());
            assert!(
                !journal.state.dsf2026_artnet_acceptance_probe_consumed,
                "memory cannot report consumed when no public receipt was persisted"
            );
        }

        let mut restarted = OutputLeaseDurableReceiptJournal::in_memory();
        restarted
            .install_path(durable_path)
            .expect("restart observes only the prior durable Pending marker");
        assert_eq!(
            restarted.dsf2026_artnet_acceptance_probe_status(),
            Dsf2026ArtNetAcceptanceProbeStatus::InDoubt
        );
        assert!(restarted.state.receipts.is_empty());
        assert!(restarted
            .state
            .dsf2026_artnet_acceptance_probe_terminals
            .is_empty());
        assert!(
            !restarted.state.dsf2026_artnet_acceptance_probe_consumed,
            "restart cannot observe a consumed state without its exact public receipt"
        );
        *harness
            .state
            .output_lease_durable_receipts
            .lock()
            .expect("install DSF2026 atomic-failure restart journal") = restarted;

        let owner =
            OutputLeaseOwner::new("local-ui", "main", 41, 7).expect("DSF2026 atomic-failure owner");
        let resources =
            OutputLeaseResources::new(&[OutputLeaseResource::Lighting, OutputLeaseResource::Video])
                .expect("DSF2026 atomic-failure resources");
        let active_lease = OutputLeaseRequest::from_action(
            "local-ui",
            "dsf2026-atomic-failure-fixture-lease",
            1,
            OutputLeaseRequestAction::Acquire {
                owner,
                resources,
                project_identity: output_lease_project_identity(1),
                ttl_ms: 30_000,
            },
        )
        .expect("DSF2026 atomic-failure active lease request");
        let mut registry =
            OutputLeaseRegistry::fresh_process(41).expect("DSF2026 atomic-failure registry");
        registry
            .submit_request(&active_lease, 1)
            .expect("DSF2026 atomic-failure active lease");
        let callbacks = Arc::new(AtomicU64::new(0));
        let callback = Arc::clone(&callbacks);
        assert!(
            submit_output_lease_candidate_with_classified_commit_and_durable_record(
                &harness.state,
                &mut registry,
                &private_request,
                2,
                "DSF2026 Art-Net acceptance probe terminal-persist retry",
                move || {
                    callback.fetch_add(1, Ordering::AcqRel);
                    Ok::<(), OutputLeaseCandidateCommitFailure>(())
                },
                |_durable, _receipt| Ok(()),
            )
            .is_err(),
            "the recovered Pending marker refuses a resend before the callback"
        );
        assert_eq!(
            callbacks.load(Ordering::Acquire),
            0,
            "terminal persistence failure cannot make a second physical send eligible"
        );
        assert!(
            replay_durable_dsf2026_output_control_terminal(
                &harness.state,
                "local-ui",
                "main",
                &public_request,
                &shape_sha256,
                &argument_fingerprint,
            )
            .is_err(),
            "no partial public response is replayable after a failed terminal replacement"
        );
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn durable_output_lease_receipt_survives_restart_without_reclaiming_authority() {
        let directory = unique_test_directory("output-lease-durable-reply-loss");
        fs::create_dir_all(&directory).expect("create durable output-lease directory");
        let path = directory.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE);
        let mut journal = OutputLeaseDurableReceiptJournal::in_memory();
        journal
            .install_path(path.clone())
            .expect("install durable output-lease journal");
        let request = durable_output_lease_acquire_request(1);
        let mut registry = OutputLeaseRegistry::fresh_process(41).unwrap();
        let receipt = registry
            .submit_request_with_commit(&request, 10, |receipt| journal.record(receipt))
            .expect("durable output-lease request");
        assert!(receipt.outcome.is_ok());
        assert_eq!(registry.active_lease_count(), 1);
        assert_eq!(journal.receipt_count(), 1);

        // A new backend starts with no lease authority, but the exact terminal
        // evidence remains recoverable from disk after the reply was lost.
        let mut restarted_journal = OutputLeaseDurableReceiptJournal::in_memory();
        restarted_journal
            .install_path(path.clone())
            .expect("reload durable output-lease journal");
        assert_eq!(restarted_journal.next_request_id().unwrap(), 2);
        let restarted = OutputLeaseRegistry::fresh_process(42).unwrap();
        assert_eq!(restarted.active_lease_count(), 0);
        assert_eq!(
            restarted_journal.lookup(&request).unwrap(),
            Some(receipt.clone())
        );

        // The old receipt cannot be laundered into a different command shape.
        let conflicting = OutputLeaseRequest::from_action(
            "local-ui",
            "output-control",
            1,
            OutputLeaseRequestAction::ProjectOrphan {
                project_identity: output_lease_project_identity(0),
                selected_lease_ids: Vec::new(),
                resource_scope: None,
            },
        )
        .expect("conflicting durable output-lease request");
        assert_eq!(
            restarted_journal.lookup(&conflicting),
            Err(output_lease::OutputLeaseError::Conflict)
        );
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn durable_output_lease_corrupt_or_unwritable_journal_fails_closed_before_commit() {
        let directory = unique_test_directory("output-lease-durable-corrupt");
        fs::create_dir_all(&directory).expect("create durable output-lease directory");
        let path = directory.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE);
        fs::write(&path, b"not-json").expect("write corrupt durable output-lease journal");
        assert!(load_output_lease_receipt_state_from_path(&path).is_err());

        let blocker = directory.join("parent-file");
        fs::write(&blocker, b"cannot be a parent directory").expect("write journal blocker");
        let blocked_path = blocker.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE);
        let mut journal = OutputLeaseDurableReceiptJournal {
            path: Some(blocked_path),
            state: PersistedOutputLeaseReceiptState::default(),
        };
        let mut registry = OutputLeaseRegistry::fresh_process(41).unwrap();
        let request = durable_output_lease_acquire_request(1);
        let error = registry
            .submit_request_with_commit(&request, 10, |receipt| journal.record(receipt))
            .expect_err("unwritable durable journal must reject the commit");
        assert_eq!(error, output_lease::OutputLeaseError::RequestCapacity);
        assert_eq!(registry.active_lease_count(), 0);
        assert_eq!(journal.receipt_count(), 0);
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn durable_output_lease_disk_state_rejects_oversize_unknown_and_invalid_nested_semantics() {
        let directory = unique_test_directory("output-lease-durable-validation");
        fs::create_dir_all(&directory).expect("create durable validation directory");
        let path = directory.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE);
        let request = durable_output_lease_acquire_request(1);
        let mut registry = OutputLeaseRegistry::fresh_process(41).unwrap();
        let receipt = registry
            .submit_request(&request, 10)
            .expect("create valid durable receipt");
        let mut journal = OutputLeaseDurableReceiptJournal::in_memory();
        assert_eq!(
            journal.prepare(&request).unwrap(),
            OutputLeaseDurablePrepareResult::Fresh
        );
        journal
            .record(&receipt)
            .expect("record valid durable receipt");
        let valid = serde_json::to_value(&journal.state).expect("encode valid durable state");

        let mut unguarded_high_water = valid.clone();
        unguarded_high_water["origins"][0]["high_water_request_id"] = Value::from(2_u64);
        unguarded_high_water["origins"][0]["replay_guard"] = Value::Bool(false);
        fs::write(&path, serde_json::to_vec(&unguarded_high_water).unwrap()).unwrap();
        assert!(load_output_lease_receipt_state_from_path(&path).is_err());

        let mut unguarded_without_receipt = valid.clone();
        unguarded_without_receipt["receipts"] = serde_json::json!([]);
        unguarded_without_receipt["origins"][0]["replay_guard"] = Value::Bool(false);
        fs::write(
            &path,
            serde_json::to_vec(&unguarded_without_receipt).unwrap(),
        )
        .unwrap();
        assert!(load_output_lease_receipt_state_from_path(&path).is_err());

        let pending_request = durable_output_lease_acquire_request(2);
        journal
            .prepare(&pending_request)
            .expect("prepare pending validation request");
        let mut unguarded_pending =
            serde_json::to_value(&journal.state).expect("encode pending validation state");
        unguarded_pending["origins"][0]["replay_guard"] = Value::Bool(false);
        fs::write(&path, serde_json::to_vec(&unguarded_pending).unwrap()).unwrap();
        assert!(load_output_lease_receipt_state_from_path(&path).is_err());

        let mut unknown = valid.clone();
        unknown
            .as_object_mut()
            .expect("durable state object")
            .insert("unreviewed".to_string(), Value::Bool(true));
        fs::write(&path, serde_json::to_vec(&unknown).unwrap()).unwrap();
        assert!(load_output_lease_receipt_state_from_path(&path).is_err());

        let mut invalid_key = valid.clone();
        invalid_key["receipts"][0]["key"]["principal"] = Value::String(String::new());
        fs::write(&path, serde_json::to_vec(&invalid_key).unwrap()).unwrap();
        assert!(load_output_lease_receipt_state_from_path(&path).is_err());

        let mut invalid_owner = valid.clone();
        invalid_owner["receipts"][0]["owner"]["principal"] = Value::String(String::new());
        fs::write(&path, serde_json::to_vec(&invalid_owner).unwrap()).unwrap();
        assert!(load_output_lease_receipt_state_from_path(&path).is_err());

        let mut invalid_resources = valid.clone();
        invalid_resources["receipts"][0]["resources"] = serde_json::json!(["Lighting", "Lighting"]);
        fs::write(&path, serde_json::to_vec(&invalid_resources).unwrap()).unwrap();
        assert!(load_output_lease_receipt_state_from_path(&path).is_err());

        let mut invalid_change = valid;
        invalid_change["receipts"][0]["changes"][0]["before"] = Value::Null;
        invalid_change["receipts"][0]["changes"][0]["after"] = Value::Null;
        fs::write(&path, serde_json::to_vec(&invalid_change).unwrap()).unwrap();
        assert!(load_output_lease_receipt_state_from_path(&path).is_err());

        let oversized_len = MAX_OUTPUT_LEASE_DURABLE_RECEIPT_STATE_BYTES + 1;
        let oversized = fs::File::create(&path).expect("create oversized durable state");
        oversized
            .set_len(oversized_len)
            .expect("sparsely size oversized durable state");
        drop(oversized);
        assert!(load_output_lease_receipt_state_from_path(&path).is_err());
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn takeover_durable_terminal_and_pending_retries_bypass_every_physical_publish() {
        fn authorize_request_and_receipt(
            process_incarnation: u64,
        ) -> (OutputLeaseRequest, output_lease::OutputLeaseRequestReceipt) {
            let owner =
                OutputLeaseOwner::new("takeover-owner", "takeover-window", process_incarnation, 1)
                    .unwrap();
            let resources = OutputLeaseResources::new(&[
                OutputLeaseResource::Lighting,
                OutputLeaseResource::Video,
            ])
            .unwrap();
            let acquire = OutputLeaseRequest::from_action(
                "takeover-owner",
                "takeover-output",
                1,
                OutputLeaseRequestAction::Acquire {
                    owner: owner.clone(),
                    resources: resources.clone(),
                    project_identity: output_lease_project_identity(0),
                    ttl_ms: 30_000,
                },
            )
            .unwrap();
            let mut registry = OutputLeaseRegistry::fresh_process(process_incarnation).unwrap();
            let acquired = registry.submit_request(&acquire, 0).unwrap();
            let authorize = OutputLeaseRequest::from_action(
                "takeover-owner",
                "takeover-output",
                2,
                OutputLeaseRequestAction::AuthorizeOrdinary {
                    lease_id: acquired.lease_id.unwrap(),
                    owner,
                    expected_generation: acquired.generation_after.unwrap(),
                    exact_resources: resources,
                },
            )
            .unwrap();
            let receipt = registry.submit_request(&authorize, 1).unwrap();
            (authorize, receipt)
        }

        fn current_takeover_fence(state: &AppState) -> OutputControlFenceV1 {
            let coordinator = state.project_coordinator.lock().unwrap();
            let output = state.engine.output_ownership_status();
            let safety = state.engine.safety_blackout_authority();
            OutputControlFenceV1 {
                process_incarnation: 1,
                session_incarnation: 1,
                project_epoch: coordinator.epoch,
                project_revision: coordinator.revision,
                project_checkpoint_hash: coordinator.checkpoint_hash.clone(),
                project_publication_generation: coordinator.publication_generation,
                output_epoch: output.epoch.checked_add(1).unwrap(),
                output_generation: output.generation.checked_add(1).unwrap(),
                safety_blackout_epoch: safety.epoch,
                safety_blackout_generation: safety.generation,
            }
        }

        let selector = StandbyTakeoverCheckpointSelector::Exact(StandbyCheckpointIdentity {
            session_id: "takeover-primary".to_string(),
            generation: 1,
        });
        let standby_status = Arc::new(Mutex::new(StandbySyncStatus::default()));

        let terminal_harness = MediaAssetA6CommandHarness::new();
        let (terminal_request, terminal_receipt) = authorize_request_and_receipt(41);
        {
            let mut journal = terminal_harness
                .state
                .output_lease_durable_receipts
                .lock()
                .unwrap();
            assert_eq!(
                journal.prepare(&terminal_request).unwrap(),
                OutputLeaseDurablePrepareResult::Fresh
            );
            journal.record(&terminal_receipt).unwrap();
        }
        let terminal_before = terminal_harness.state.engine.snapshot();
        let terminal_stop = Arc::new(AtomicBool::new(false));
        let terminal_fence = current_takeover_fence(&terminal_harness.state);
        let terminal = replace_prepared_project_snapshot_with_expected_output_fence(
            &terminal_harness.state,
            ProjectTakeoverReplacementRequest {
                prepared: prepare_project_load(
                    empty_project_file(),
                    ProjectControlMappings::default(),
                    "durable terminal Take Over".to_string(),
                    None,
                )
                .unwrap(),
                scope: ProjectSnapshotReplacementScope::LifecycleAlreadyHeld,
                expected_output_fence: &terminal_fence,
                standby_stop: &terminal_stop,
                standby_status: &standby_status,
                selector: &selector,
                force: false,
                lease_authorization: Some((&terminal_request, 2)),
            },
        )
        .expect("terminal Take Over retry returns durable evidence");
        assert_eq!(terminal.1, terminal_fence);
        assert_eq!(terminal.2, Some(terminal_receipt));
        assert!(!terminal_stop.load(Ordering::Acquire));
        assert_eq!(terminal_harness.state.engine.snapshot(), terminal_before);
        assert_eq!(
            terminal_harness
                .state
                .output_lease_registry
                .lock()
                .unwrap()
                .active_lease_count(),
            0,
            "durable receipt cannot reconstruct old-process authority"
        );

        let pending_harness = MediaAssetA6CommandHarness::new();
        let (pending_request, _) = authorize_request_and_receipt(41);
        pending_harness
            .state
            .output_lease_durable_receipts
            .lock()
            .unwrap()
            .prepare(&pending_request)
            .unwrap();
        let pending_before = pending_harness.state.engine.snapshot();
        let pending_stop = Arc::new(AtomicBool::new(false));
        let pending_fence = current_takeover_fence(&pending_harness.state);
        let pending = replace_prepared_project_snapshot_with_expected_output_fence(
            &pending_harness.state,
            ProjectTakeoverReplacementRequest {
                prepared: prepare_project_load(
                    empty_project_file(),
                    ProjectControlMappings::default(),
                    "durable pending Take Over".to_string(),
                    None,
                )
                .unwrap(),
                scope: ProjectSnapshotReplacementScope::LifecycleAlreadyHeld,
                expected_output_fence: &pending_fence,
                standby_stop: &pending_stop,
                standby_status: &standby_status,
                selector: &selector,
                force: false,
                lease_authorization: Some((&pending_request, 2)),
            },
        );
        assert!(pending.is_err());
        assert!(pending.unwrap_err().contains("RequestCapacity"));
        assert!(!pending_stop.load(Ordering::Acquire));
        assert_eq!(pending_harness.state.engine.snapshot(), pending_before);
    }

    #[test]
    fn takeover_unwritable_durable_prepare_rejects_before_physical_callback() {
        let harness = MediaAssetA6CommandHarness::new();
        let directory = unique_test_directory("takeover-unwritable-durable-prepare");
        fs::create_dir_all(&directory).unwrap();
        let blocker = directory.join("parent-file");
        fs::write(&blocker, b"not a directory").unwrap();
        *harness
            .state
            .output_lease_durable_receipts
            .lock()
            .unwrap()
            = OutputLeaseDurableReceiptJournal {
                path: Some(blocker.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE)),
                state: PersistedOutputLeaseReceiptState::default(),
            };
        let request = durable_output_lease_acquire_request(1);
        let physical_calls = AtomicU64::new(0);
        let prepared = prepare_output_lease_durable_physical_commit(&harness.state, &request);
        if prepared.is_ok() {
            physical_calls.fetch_add(1, Ordering::AcqRel);
        }
        assert!(prepared.is_err());
        assert_eq!(physical_calls.load(Ordering::Acquire), 0);
        assert_eq!(
            harness
                .state
                .output_lease_durable_receipts
                .lock()
                .unwrap()
                .receipt_count(),
            0
        );
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn output_lease_in_doubt_physical_commit_blocks_replay_before_callback() {
        let harness = MediaAssetA6CommandHarness::new();
        let owner = OutputLeaseOwner::new("in-doubt-owner", "in-doubt-window", 41, 1)
            .expect("in-doubt owner");
        let resources = OutputLeaseResources::new(&[OutputLeaseResource::Lighting])
            .expect("in-doubt resources");
        let acquire = OutputLeaseRequest::from_action(
            "in-doubt-owner",
            "in-doubt-output",
            1,
            OutputLeaseRequestAction::Acquire {
                owner: owner.clone(),
                resources: resources.clone(),
                project_identity: output_lease_project_identity(0),
                ttl_ms: 30_000,
            },
        )
        .expect("in-doubt acquire request");
        let mut registry = OutputLeaseRegistry::fresh_process(41).expect("in-doubt registry");
        let acquired = registry
            .submit_request(&acquire, 0)
            .expect("in-doubt acquire");
        let authorize = OutputLeaseRequest::from_action(
            "in-doubt-owner",
            "in-doubt-output",
            2,
            OutputLeaseRequestAction::AuthorizeOrdinary {
                lease_id: acquired.lease_id.expect("in-doubt lease id"),
                owner,
                expected_generation: 1,
                exact_resources: resources,
            },
        )
        .expect("in-doubt authorize request");
        {
            let mut journal = harness
                .state
                .output_lease_durable_receipts
                .lock()
                .expect("in-doubt journal lock");
            assert_eq!(
                journal
                    .prepare(&authorize)
                    .expect("prepare in-doubt request"),
                OutputLeaseDurablePrepareResult::Fresh
            );
        }
        let before = registry.clone();
        let physical_calls = Arc::new(AtomicU64::new(0));
        let calls = Arc::clone(&physical_calls);
        assert!(submit_output_lease_candidate_with_commit(
            &harness.state,
            &mut registry,
            &authorize,
            1,
            "in-doubt physical replay",
            move || {
                calls.fetch_add(1, Ordering::AcqRel);
                Ok(())
            },
        )
        .is_err());
        assert_eq!(physical_calls.load(Ordering::Acquire), 0);
        assert_eq!(registry, before);
        assert_eq!(
            harness
                .state
                .output_lease_durable_receipts
                .lock()
                .expect("in-doubt journal final lock")
                .receipt_count(),
            0
        );
    }

    #[test]
    fn published_display_terminal_record_fault_keeps_one_truth_and_pending_replay_barrier() {
        let harness = MediaAssetA6CommandHarness::new();
        let state = Arc::clone(&harness.state);
        let directory = unique_test_directory("display-terminal-record-fault");
        let active_parent = directory.join("active");
        let saved_parent = directory.join("saved-pending");
        fs::create_dir_all(&active_parent)
            .expect("create Display terminal-fault active journal directory");
        let active_path = active_parent.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE);
        state
            .output_lease_durable_receipts
            .lock()
            .expect("Display terminal-fault journal lock")
            .install_path(active_path)
            .expect("install Display terminal-fault journal");

        let authority = prepare_fake_display_add_authority(&state, "fake-display-terminal-owner");
        let monitor = native_output_qa_monitors()
            .into_iter()
            .find(|monitor| monitor.name == "DISPLAY5")
            .expect("fake terminal-fault DISPLAY5");
        let (request, spec, lease_request, lease_now) =
            build_fake_display_add_request(&state, &authority, &monitor, 2);
        let native_ops =
            FakeDisplayOutputNativeOperations::new(Arc::clone(&state), native_output_qa_monitors())
                .with_terminal_fault(active_parent.clone(), saved_parent.clone());
        let result = add_display_output_with_output_control_fence_core(
            &state,
            display_output_control_request!(
                &spec,
                &request.expected_fence,
                &lease_request,
                lease_now,
                &authority.owner_principal,
                "main",
                authority.owner_incarnation
            ),
            native_ops.clone(),
        );
        let error = result.expect_err("terminal durable record fault must remain in doubt");
        assert!(
            error.contains("durable output commit is in doubt"),
            "{error}"
        );
        assert!(state.project_transaction_active.load(Ordering::Acquire));
        assert!(get_project_checkpoint_bundle_core(
            &state,
            request.expected_fence.project_epoch,
            request.expected_fence.project_revision,
            request.expected_fence.project_checkpoint_hash.clone(),
        )
        .is_err());

        let engine_outputs = state.engine.snapshot().video.outputs;
        assert_eq!(engine_outputs.len(), 1);
        assert_eq!(engine_outputs[0].kind, VideoOutputKind::Display);
        assert_eq!(
            engine_outputs[0].monitor_identity.as_deref(),
            Some(monitor.identity.as_str())
        );
        let coordinator = state
            .project_coordinator
            .lock()
            .expect("query full-core terminal-fault project truth");
        let checkpoint = project_checkpoint_for_coordinator(&state, &coordinator)
            .expect("query full-core terminal-fault authored checkpoint");
        assert_eq!(checkpoint.project.snapshot.video.outputs, engine_outputs);
        drop(coordinator);
        assert_eq!(native_ops.visible.load(Ordering::Acquire), 1);
        assert_eq!(native_ops.presented.load(Ordering::Acquire), 1);
        assert_eq!(native_ops.published.load(Ordering::Acquire), 1);
        assert_eq!(native_ops.publication_state(), (1, 1, 1, 1));

        assert_eq!(
            state
                .output_lease_durable_receipts
                .lock()
                .expect("query full-core terminal-fault Pending")
                .lookup(&lease_request),
            Err(output_lease::OutputLeaseError::RequestCapacity)
        );
        let retry = add_display_output_with_output_control_fence_core(
            &state,
            display_output_control_request!(
                &spec,
                &request.expected_fence,
                &lease_request,
                lease_now,
                &authority.owner_principal,
                "main",
                authority.owner_incarnation
            ),
            native_ops.clone(),
        );
        assert!(retry.is_err());
        assert_eq!(
            native_ops.prepared.load(Ordering::Acquire),
            1,
            "exact retry must execute zero second native callbacks"
        );
        assert_eq!(native_ops.visible.load(Ordering::Acquire), 1);
        assert_eq!(native_ops.presented.load(Ordering::Acquire), 1);
        assert_eq!(native_ops.published.load(Ordering::Acquire), 1);
        assert_eq!(native_ops.publication_state(), (1, 1, 1, 1));
        assert_eq!(state.engine.snapshot().video.outputs.len(), 1);

        let mut restarted = OutputLeaseDurableReceiptJournal::in_memory();
        restarted
            .install_path(saved_parent.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE))
            .expect("reload full-core Display Pending after restart");
        assert_eq!(
            restarted.lookup(&lease_request),
            Err(output_lease::OutputLeaseError::RequestCapacity)
        );
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn display_candidate_pending_marker_precedes_commit_and_failed_commit_cannot_replay() {
        let harness = MediaAssetA6CommandHarness::new();
        let request = durable_output_lease_acquire_request(1);
        let mut registry = OutputLeaseRegistry::fresh_process(41).expect("display registry");
        let before = registry.clone();
        let physical_calls = Arc::new(AtomicU64::new(0));
        let calls = Arc::clone(&physical_calls);
        assert!(submit_output_lease_candidate_with_commit(
            &harness.state,
            &mut registry,
            &request,
            1,
            "display candidate rollback",
            move || {
                calls.fetch_add(1, Ordering::AcqRel);
                Err::<(), String>("native candidate acknowledgement failed".to_string())
            },
        )
        .is_err());
        assert_eq!(physical_calls.load(Ordering::Acquire), 1);
        assert_eq!(registry, before);
        let journal = harness
            .state
            .output_lease_durable_receipts
            .lock()
            .expect("display rollback journal lock");
        assert_eq!(journal.receipt_count(), 0);
        assert!(journal.state.pending.is_empty());
        drop(journal);

        let retry_calls = Arc::new(AtomicU64::new(0));
        let calls = Arc::clone(&retry_calls);
        assert!(submit_output_lease_candidate_with_commit(
            &harness.state,
            &mut registry,
            &request,
            1,
            "display candidate replay",
            move || {
                calls.fetch_add(1, Ordering::AcqRel);
                Ok::<(), String>(())
            },
        )
        .is_err());
        assert_eq!(retry_calls.load(Ordering::Acquire), 0);
        assert_eq!(registry, before);
    }

    #[test]
    fn display_candidate_uncertain_cleanup_retains_pending_and_blocks_every_retry() {
        let injected_failures = [
            "native close acknowledgement was lost",
            "native worker retirement failed",
            "engine output removal ACK was lost",
            "candidate output lease cleanup was not acknowledged",
        ];
        for (index, failure) in injected_failures.into_iter().enumerate() {
            let harness = MediaAssetA6CommandHarness::new();
            let request = durable_output_lease_acquire_request(1);
            let mut registry =
                OutputLeaseRegistry::fresh_process(41).expect("display uncertain-cleanup registry");
            let before = registry.clone();
            let physical_calls = Arc::new(AtomicU64::new(0));
            let calls = Arc::clone(&physical_calls);
            let error = submit_output_lease_candidate_with_classified_commit(
                &harness.state,
                &mut registry,
                &request,
                1,
                &format!("display uncertain cleanup {index}"),
                move || {
                    calls.fetch_add(1, Ordering::AcqRel);
                    Err::<(), _>(OutputLeaseCandidateCommitFailure::in_doubt(
                        failure.to_string(),
                    ))
                },
            )
            .expect_err("uncertain cleanup must reject the physical commit");
            assert!(error.contains("pending receipt retained"));
            assert_eq!(physical_calls.load(Ordering::Acquire), 1);
            assert_eq!(registry, before);
            {
                let journal = harness
                    .state
                    .output_lease_durable_receipts
                    .lock()
                    .expect("uncertain cleanup journal lock");
                assert_eq!(journal.receipt_count(), 0);
                assert_eq!(journal.state.pending.len(), 1);
            }

            let higher_request = durable_output_lease_acquire_request(2);
            let retry_calls = Arc::new(AtomicU64::new(0));
            let calls = Arc::clone(&retry_calls);
            assert!(submit_output_lease_candidate_with_classified_commit(
                &harness.state,
                &mut registry,
                &higher_request,
                1,
                "display uncertain cleanup replay",
                move || {
                    calls.fetch_add(1, Ordering::AcqRel);
                    Ok::<(), OutputLeaseCandidateCommitFailure>(())
                },
            )
            .is_err());
            assert_eq!(retry_calls.load(Ordering::Acquire), 0);
            assert_eq!(registry, before);
        }
    }

    #[test]
    fn dsf2026_post_send_indoubt_and_reconciliation_permanently_consume_the_one_shot() {
        let harness = MediaAssetA6CommandHarness::new();
        let directory = unique_test_directory("dsf2026-probe-indoubt");
        fs::create_dir_all(&directory).expect("create DSF2026 in-doubt journal directory");
        let path = directory.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE);
        harness
            .state
            .output_lease_durable_receipts
            .lock()
            .expect("install DSF2026 durable journal")
            .install_path(path.clone())
            .expect("persist DSF2026 durable journal");
        let request =
            durable_output_lease_acquire_request_in_domain(1, OUTPUT_LEASE_DSF2026_PROBE_DOMAIN);
        let mut registry = OutputLeaseRegistry::fresh_process(41).expect("DSF2026 registry");
        let sends = Arc::new(AtomicU64::new(0));
        let send = Arc::clone(&sends);
        let error = submit_dsf2026_artnet_acceptance_probe_candidate_with_classified_commit_and_durable_record(
            &harness.state,
            &mut registry,
            &request,
            1,
            "DSF2026 Art-Net acceptance probe",
            "main",
            move || {
                send.fetch_add(1, Ordering::AcqRel);
                // This is the post-send_to classification returned by the
                // engine helper for an error or short UDP write.
                Err::<(), _>(OutputLeaseCandidateCommitFailure::in_doubt(
                    "injected DSF2026 send_to acknowledgement loss",
                ))
            },
            |_durable, _receipt| Ok(()),
        )
        .expect_err("post-send ambiguity must retain the durable Pending marker");
        assert!(error.contains("pending receipt retained"));
        assert_eq!(sends.load(Ordering::Acquire), 1);

        for rejected_request in [
            request.clone(),
            durable_output_lease_acquire_request_in_domain(2, OUTPUT_LEASE_DSF2026_PROBE_DOMAIN),
        ] {
            let rejected_sends = Arc::clone(&sends);
            assert!(submit_output_lease_candidate_with_classified_commit(
                &harness.state,
                &mut registry,
                &rejected_request,
                1,
                "DSF2026 Art-Net acceptance probe replay",
                move || {
                    rejected_sends.fetch_add(1, Ordering::AcqRel);
                    Ok::<(), OutputLeaseCandidateCommitFailure>(())
                },
            )
            .is_err());
            assert_eq!(
                sends.load(Ordering::Acquire),
                1,
                "same request and a new request must both be rejected before a second UDP send"
            );
        }

        let mut restarted = OutputLeaseDurableReceiptJournal::in_memory();
        restarted
            .install_path(path)
            .expect("reload DSF2026 pending receipt after restart");
        assert_eq!(
            restarted.lookup(&request),
            Err(output_lease::OutputLeaseError::RequestCapacity)
        );
        assert_eq!(
            restarted.lookup(&durable_output_lease_acquire_request_in_domain(
                2,
                OUTPUT_LEASE_DSF2026_PROBE_DOMAIN,
            )),
            Err(output_lease::OutputLeaseError::RequestCapacity)
        );

        // Install the recovered journal in a fresh authority registry to
        // prove that a process restart still reaches the Pending barrier
        // before the physical callback can run.
        *harness
            .state
            .output_lease_durable_receipts
            .lock()
            .expect("install restarted DSF2026 journal") = restarted;
        let pending_reconcile_request = dsf2026_public_terminal_request(
            OUTPUT_DSF2026_ARTNET_ACCEPTANCE_PROBE_RECONCILE_OPERATION_ID,
            3,
        );
        let pending_reconcile_shape_sha256 = control_plane_runtime::hex_sha256(
            &pending_reconcile_request
                .canonical_shape_bytes()
                .expect("pending DSF2026 reconcile public shape"),
        );
        let pending_reconcile_argument_fingerprint = control_plane_runtime::hex_sha256(
            &pending_reconcile_request
                .argument_fingerprint_bytes()
                .expect("pending DSF2026 reconcile public arguments"),
        );
        assert_eq!(
            replay_durable_dsf2026_output_control_terminal(
                &harness.state,
                "local-ui",
                "main",
                &pending_reconcile_request,
                &pending_reconcile_shape_sha256,
                &pending_reconcile_argument_fingerprint,
            )
            .expect("the pending owner may reach the no-send reconciliation action"),
            None
        );
        assert_eq!(
            replay_durable_dsf2026_output_control_terminal(
                &harness.state,
                "reloaded-local-ui",
                "main",
                &pending_reconcile_request,
                &pending_reconcile_shape_sha256,
                &pending_reconcile_argument_fingerprint,
            )
            .expect("a newly registered principal at the same local window may reach no-send reconciliation"),
            None,
            "the durable journal binds InDoubt to the local window, not a retired renderer principal"
        );
        for foreign_window in ["secondary", "remote"] {
            assert!(
                replay_durable_dsf2026_output_control_terminal(
                    &harness.state,
                    "other-ui",
                    foreign_window,
                    &pending_reconcile_request,
                    &pending_reconcile_shape_sha256,
                    &pending_reconcile_argument_fingerprint,
                )
                .is_err(),
                "a different local window or remote caller cannot reconcile the Pending physical outcome"
            );
        }
        let mut restart_registry =
            OutputLeaseRegistry::fresh_process(41).expect("fresh DSF2026 restart registry");
        let restart_send = Arc::clone(&sends);
        assert!(submit_output_lease_candidate_with_classified_commit(
            &harness.state,
            &mut restart_registry,
            &durable_output_lease_acquire_request_in_domain(2, OUTPUT_LEASE_DSF2026_PROBE_DOMAIN,),
            1,
            "DSF2026 Art-Net acceptance probe restarted replay",
            move || {
                restart_send.fetch_add(1, Ordering::AcqRel);
                Ok::<(), OutputLeaseCandidateCommitFailure>(())
            },
        )
        .is_err());
        assert_eq!(
            sends.load(Ordering::Acquire),
            1,
            "a restarted process must not resend before explicit reconciliation"
        );

        // The production R4 acknowledgement reaches the no-send durable
        // transaction only after native confirmation and exact owner/fence/
        // lease checks. Exercise that candidate seam directly: its
        // reconciliation Pending removal, private lease receipt, consumed
        // latch, and public receipt share one persistence candidate.
        let reconcile_request = dsf2026_public_terminal_request(
            OUTPUT_DSF2026_ARTNET_ACCEPTANCE_PROBE_RECONCILE_OPERATION_ID,
            3,
        );
        let reconcile_response = dsf2026_public_terminal_response(&reconcile_request);
        let (reconcile_private_request, _) = dsf2026_private_terminal_request_and_receipt_for(
            &reconcile_request,
            "reloaded-local-ui",
            "main",
        );
        let reconcile_shape_sha256 = control_plane_runtime::hex_sha256(
            &reconcile_request
                .canonical_shape_bytes()
                .expect("DSF2026 reconcile public shape"),
        );
        let reconcile_argument_fingerprint = control_plane_runtime::hex_sha256(
            &reconcile_request
                .argument_fingerprint_bytes()
                .expect("DSF2026 reconcile public arguments"),
        );
        let lease_owner = OutputLeaseOwner::new("reloaded-local-ui", "main", 41, 7)
            .expect("DSF2026 reconcile owner after renderer reload");
        let lease_resources =
            OutputLeaseResources::new(&[OutputLeaseResource::Lighting, OutputLeaseResource::Video])
                .expect("DSF2026 reconcile resources");
        let lease_acquire = OutputLeaseRequest::from_action(
            "reloaded-local-ui",
            "dsf2026-reconcile-fixture-lease",
            1,
            OutputLeaseRequestAction::Acquire {
                owner: lease_owner,
                resources: lease_resources,
                project_identity: output_lease_project_identity(1),
                ttl_ms: 30_000,
            },
        )
        .expect("DSF2026 reconcile active lease request");
        restart_registry
            .submit_request(&lease_acquire, 1)
            .expect("DSF2026 reconcile active lease");
        let reconcile_callbacks = Arc::new(AtomicU64::new(0));
        let reconcile_callback = Arc::clone(&reconcile_callbacks);
        let (_, reconcile_private_receipt) =
            submit_output_lease_candidate_with_classified_commit_and_durable_record(
                &harness.state,
                &mut restart_registry,
                &reconcile_private_request,
                2,
                "DSF2026 Art-Net acceptance probe reconciliation",
                move || {
                    reconcile_callback.fetch_add(1, Ordering::AcqRel);
                    // The real acknowledgement callback is deliberately
                    // no-send.  This counter is the production callback seam.
                    Ok::<(), OutputLeaseCandidateCommitFailure>(())
                },
                |durable, private_receipt| {
                    durable.record_dsf2026_output_control_terminal(
                        private_receipt,
                        "reloaded-local-ui",
                        "main",
                        &reconcile_request,
                        &reconcile_shape_sha256,
                        &reconcile_argument_fingerprint,
                        &reconcile_response,
                    )
                },
            )
            .expect("acknowledge callback and durable public/private terminal commit atomically");
        assert_eq!(
            reconcile_callbacks.load(Ordering::Acquire),
            1,
            "the acknowledged no-send callback runs exactly once"
        );
        assert_eq!(
            reconcile_private_receipt.key.domain, OUTPUT_LEASE_DSF2026_PROBE_RECONCILE_DOMAIN,
            "the combined terminal retains the reconciliation private receipt"
        );
        assert_eq!(
            harness
                .state
                .output_lease_durable_receipts
                .lock()
                .expect("inspect no-send reconciliation journal")
                .lookup(&durable_output_lease_acquire_request(3)),
            Ok(None),
            "the probe-scoped hold must not block an unrelated output-control request"
        );
        assert_eq!(
            serde_json::from_slice::<OutputControlResponseV2>(
                &serde_json::to_vec(&reconcile_response)
                    .expect("serialize no-send DSF2026 reconciliation receipt"),
            )
            .expect("deserialize no-send DSF2026 reconciliation receipt"),
            reconcile_response
        );
        assert_eq!(
            replay_durable_dsf2026_output_control_terminal(
                &harness.state,
                "reloaded-local-ui",
                "main",
                &reconcile_request,
                &reconcile_shape_sha256,
                &reconcile_argument_fingerprint,
            )
            .expect("reconcile terminal replay"),
            Some(reconcile_response)
        );
        assert_eq!(
            sends.load(Ordering::Acquire),
            1,
            "the public reconciliation receipt is serializable and performs no UDP send"
        );
        assert_eq!(
            harness
                .state
                .output_lease_durable_receipts
                .lock()
                .expect("inspect reconciled DSF2026 journal")
                .lookup(&durable_output_lease_acquire_request_in_domain(
                    2,
                    OUTPUT_LEASE_DSF2026_PROBE_DOMAIN,
                )),
            Err(output_lease::OutputLeaseError::RequestCapacity),
            "a no-send reconciliation resolves uncertainty but never re-authorizes a fresh fixed probe"
        );
        let post_reconcile_sends = Arc::clone(&sends);
        assert!(submit_output_lease_candidate_with_classified_commit(
            &harness.state,
            &mut restart_registry,
            &durable_output_lease_acquire_request_in_domain(3, OUTPUT_LEASE_DSF2026_PROBE_DOMAIN),
            1,
            "DSF2026 Art-Net acceptance probe post-reconcile replay",
            move || {
                post_reconcile_sends.fetch_add(1, Ordering::AcqRel);
                Ok::<(), OutputLeaseCandidateCommitFailure>(())
            },
        )
        .is_err());
        assert_eq!(
            sends.load(Ordering::Acquire),
            1,
            "reconciliation must not admit a second UDP send"
        );
        let mut reconciled_restart = OutputLeaseDurableReceiptJournal::in_memory();
        reconciled_restart
            .install_path(directory.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE))
            .expect("reload reconciled DSF2026 journal");
        assert_eq!(
            reconciled_restart.dsf2026_artnet_acceptance_probe_status(),
            Dsf2026ArtNetAcceptanceProbeStatus::Consumed
        );
        assert_eq!(
            reconciled_restart.lookup(&durable_output_lease_acquire_request_in_domain(
                4,
                OUTPUT_LEASE_DSF2026_PROBE_DOMAIN,
            )),
            Err(output_lease::OutputLeaseError::RequestCapacity),
            "restart after reconciliation remains permanently fail-closed"
        );
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn dsf2026_success_replay_returns_its_receipt_but_fresh_requests_are_globally_rejected_after_restart(
    ) {
        let harness = MediaAssetA6CommandHarness::new();
        let directory = unique_test_directory("dsf2026-probe-success-one-shot");
        fs::create_dir_all(&directory).expect("create DSF2026 success journal directory");
        let path = directory.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE);
        harness
            .state
            .output_lease_durable_receipts
            .lock()
            .expect("install DSF2026 success durable journal")
            .install_path(path.clone())
            .expect("persist DSF2026 success durable journal");
        let request =
            durable_output_lease_acquire_request_in_domain(1, OUTPUT_LEASE_DSF2026_PROBE_DOMAIN);
        let mut registry =
            OutputLeaseRegistry::fresh_process(41).expect("DSF2026 success registry");
        let sends = Arc::new(AtomicU64::new(0));
        let first_send = Arc::clone(&sends);
        let (_, first_receipt) = submit_dsf2026_artnet_acceptance_probe_candidate_with_classified_commit_and_durable_record(
            &harness.state,
            &mut registry,
            &request,
            1,
            "DSF2026 Art-Net acceptance probe success",
            "main",
            move || {
                first_send.fetch_add(1, Ordering::AcqRel);
                Ok::<(), OutputLeaseCandidateCommitFailure>(())
            },
            |durable, receipt| {
                durable
                    .record(receipt)
                    .map_err(|error| format!("{error:?}"))
            },
        )
        .expect("one fixed proof is admitted exactly once");
        assert_eq!(sends.load(Ordering::Acquire), 1);
        let journal = harness
            .state
            .output_lease_durable_receipts
            .lock()
            .expect("inspect successful DSF2026 journal");
        assert_eq!(
            journal.lookup(&request),
            Ok(Some(first_receipt)),
            "same request replay returns the terminal receipt without transport"
        );
        assert_eq!(
            journal.lookup(&durable_output_lease_acquire_request_in_domain(
                2,
                OUTPUT_LEASE_DSF2026_PROBE_DOMAIN,
            )),
            Err(output_lease::OutputLeaseError::RequestCapacity),
            "a fresh request ID is a forbidden second physical attempt"
        );
        assert_eq!(
            journal.lookup(&durable_output_lease_acquire_request(2)),
            Ok(None),
            "the global probe budget does not alter the generic Art-Net/output-control domain"
        );
        assert_eq!(
            journal.dsf2026_artnet_acceptance_probe_status(),
            Dsf2026ArtNetAcceptanceProbeStatus::Consumed
        );
        drop(journal);

        let mut restarted = OutputLeaseDurableReceiptJournal::in_memory();
        restarted
            .install_path(path)
            .expect("reload successful DSF2026 journal");
        assert_eq!(
            restarted.dsf2026_artnet_acceptance_probe_status(),
            Dsf2026ArtNetAcceptanceProbeStatus::Consumed
        );
        assert_eq!(
            restarted.lookup(&durable_output_lease_acquire_request_in_domain(
                2,
                OUTPUT_LEASE_DSF2026_PROBE_DOMAIN,
            )),
            Err(output_lease::OutputLeaseError::RequestCapacity),
            "restart cannot make a second probe eligible"
        );
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn durable_output_lease_origin_gc_preserves_pending_and_allows_new_principals_after_reload() {
        let directory = unique_test_directory("output-lease-origin-gc");
        fs::create_dir_all(&directory).expect("create origin-gc directory");
        let path = directory.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE);
        let request_for = |index: usize| {
            let principal = format!("origin-principal-{index}");
            let owner = OutputLeaseOwner::new(principal.clone(), "origin-window", 41, 1)
                .expect("origin-gc owner");
            OutputLeaseRequest::from_action(
                principal,
                "output-control",
                1,
                OutputLeaseRequestAction::Acquire {
                    owner,
                    resources: OutputLeaseResources::new(&[OutputLeaseResource::Lighting])
                        .expect("origin-gc resources"),
                    project_identity: output_lease_project_identity(0),
                    ttl_ms: 30_000,
                },
            )
            .expect("origin-gc request")
        };
        let mut journal = OutputLeaseDurableReceiptJournal::in_memory();
        journal
            .install_path(path.clone())
            .expect("install origin-gc journal");

        for index in 0..129 {
            let request = request_for(index);
            let mut registry = OutputLeaseRegistry::fresh_process(41).expect("origin registry");
            let receipt = registry
                .submit_request(&request, 1)
                .expect("origin receipt");
            assert_eq!(
                journal.prepare(&request).expect("prepare origin request"),
                OutputLeaseDurablePrepareResult::Fresh
            );
            journal.record(&receipt).expect("record origin receipt");
        }
        assert_eq!(journal.receipt_count(), MAX_DURABLE_OUTPUT_LEASE_RECEIPTS);
        assert_eq!(
            journal.state.origins.len(),
            MAX_DURABLE_OUTPUT_LEASE_RECEIPTS,
            "old origins are pruned when their terminal receipt is evicted"
        );

        let mut reloaded = OutputLeaseDurableReceiptJournal::in_memory();
        reloaded
            .install_path(path.clone())
            .expect("reload origin-gc journal");
        let request = request_for(129);
        let mut registry = OutputLeaseRegistry::fresh_process(41).expect("reloaded registry");
        let receipt = registry
            .submit_request(&request, 1)
            .expect("post-reload origin receipt");
        assert_eq!(
            reloaded
                .prepare(&request)
                .expect("post-reload prepare must have a pending slot"),
            OutputLeaseDurablePrepareResult::Fresh
        );
        assert_eq!(reloaded.state.pending.len(), 1);
        reloaded.record(&receipt).expect("post-reload record");
        assert_eq!(
            reloaded.state.origins.len(),
            MAX_DURABLE_OUTPUT_LEASE_RECEIPTS
        );

        let pending_request = request_for(130);
        assert_eq!(
            reloaded
                .prepare(&pending_request)
                .expect("prepare explicit pending origin"),
            OutputLeaseDurablePrepareResult::Fresh
        );
        assert!(reloaded.lookup(&pending_request).is_err());
        assert!(reloaded
            .state
            .origins
            .iter()
            .any(|origin| origin.principal == pending_request.key.principal));
        reloaded
            .abort(&pending_request)
            .expect("abort pending origin");
        assert!(reloaded
            .state
            .origins
            .iter()
            .any(|origin| origin.principal == pending_request.key.principal));

        let mut final_reload = OutputLeaseDurableReceiptJournal::in_memory();
        final_reload
            .install_path(path.clone())
            .expect("final reload origin-gc journal");
        assert_eq!(
            final_reload.state.origins.len(),
            MAX_DURABLE_OUTPUT_LEASE_RECEIPTS + 1,
            "a safe-aborted origin remains as an exact-request replay guard"
        );
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn durable_output_lease_safe_abort_replay_guard_survives_terminal_receipt_eviction() {
        let request_for = |principal: String, request_id| {
            let owner = OutputLeaseOwner::new(principal.clone(), "safe-abort-window", 41, 1)
                .expect("safe-abort owner");
            OutputLeaseRequest::from_action(
                principal,
                "output-control",
                request_id,
                OutputLeaseRequestAction::Acquire {
                    owner,
                    resources: OutputLeaseResources::new(&[OutputLeaseResource::Lighting])
                        .expect("safe-abort resources"),
                    project_identity: output_lease_project_identity(0),
                    ttl_ms: 30_000,
                },
            )
            .expect("safe-abort request")
        };
        let mut journal = OutputLeaseDurableReceiptJournal::in_memory();
        let first = request_for("safe-abort-principal".to_string(), 1);
        let mut registry = OutputLeaseRegistry::fresh_process(41).expect("safe-abort registry");
        let first_receipt = registry
            .submit_request(&first, 1)
            .expect("safe-abort first receipt");
        assert_eq!(
            journal.prepare(&first).expect("prepare first receipt"),
            OutputLeaseDurablePrepareResult::Fresh
        );
        journal
            .record(&first_receipt)
            .expect("record first receipt");

        let safe_aborted = request_for("safe-abort-principal".to_string(), 2);
        assert_eq!(
            journal
                .prepare(&safe_aborted)
                .expect("prepare safe-aborted request"),
            OutputLeaseDurablePrepareResult::Fresh
        );
        journal
            .abort(&safe_aborted)
            .expect("safe-aborted request rollback");

        for index in 0..MAX_DURABLE_OUTPUT_LEASE_RECEIPTS {
            let request = request_for(format!("eviction-principal-{index}"), 1);
            let mut registry = OutputLeaseRegistry::fresh_process(41).expect("eviction registry");
            let receipt = registry
                .submit_request(&request, 1)
                .expect("eviction receipt");
            assert_eq!(
                journal.prepare(&request).expect("prepare eviction receipt"),
                OutputLeaseDurablePrepareResult::Fresh
            );
            journal.record(&receipt).expect("record eviction receipt");
        }
        assert!(journal
            .state
            .origins
            .iter()
            .any(|origin| origin.principal == safe_aborted.key.principal));
        assert!(
            journal.prepare(&safe_aborted).is_err(),
            "an exact SafeAbort request remains rejected after its older terminal receipt is evicted"
        );
    }

    #[test]
    fn durable_output_lease_explicit_safe_abort_guard_survives_reload_and_eviction() {
        let directory = unique_test_directory("output-lease-replay-guard-reload");
        fs::create_dir_all(&directory).expect("create replay-guard directory");
        let path = directory.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE);
        let request_for = |principal: String, request_id: u64| {
            let owner = OutputLeaseOwner::new(principal.clone(), "replay-guard-window", 41, 1)
                .expect("replay-guard owner");
            OutputLeaseRequest::from_action(
                principal,
                "output-control",
                request_id,
                OutputLeaseRequestAction::Acquire {
                    owner,
                    resources: OutputLeaseResources::new(&[OutputLeaseResource::Lighting])
                        .expect("replay-guard resources"),
                    project_identity: output_lease_project_identity(0),
                    ttl_ms: 30_000,
                },
            )
            .expect("replay-guard request")
        };
        let first = request_for("reload-safe-abort".to_string(), 1);
        let safe_aborted = request_for("reload-safe-abort".to_string(), 2);
        let mut journal = OutputLeaseDurableReceiptJournal::in_memory();
        journal
            .install_path(path.clone())
            .expect("install replay-guard journal");
        let mut registry = OutputLeaseRegistry::fresh_process(41).expect("first registry");
        let first_receipt = registry.submit_request(&first, 1).expect("first receipt");
        assert_eq!(
            journal.prepare(&first).expect("prepare first request"),
            OutputLeaseDurablePrepareResult::Fresh
        );
        journal
            .record(&first_receipt)
            .expect("record first receipt");
        assert_eq!(
            journal
                .prepare(&safe_aborted)
                .expect("prepare safe-abort request"),
            OutputLeaseDurablePrepareResult::Fresh
        );
        journal
            .abort(&safe_aborted)
            .expect("abort safe-abort request");

        let mut reloaded = OutputLeaseDurableReceiptJournal::in_memory();
        reloaded
            .install_path(path.clone())
            .expect("reload replay-guard journal");
        assert!(reloaded.state.origins.iter().any(|origin| {
            origin.principal == safe_aborted.key.principal
                && origin.high_water_request_id == safe_aborted.key.request_id
                && origin.replay_guard
        }));

        for index in 0..MAX_DURABLE_OUTPUT_LEASE_RECEIPTS {
            let request = request_for(format!("reload-eviction-{index}"), 1);
            let mut registry = OutputLeaseRegistry::fresh_process(41).expect("eviction registry");
            let receipt = registry
                .submit_request(&request, 1)
                .expect("eviction receipt");
            assert_eq!(
                reloaded
                    .prepare(&request)
                    .expect("prepare eviction request"),
                OutputLeaseDurablePrepareResult::Fresh
            );
            reloaded.record(&receipt).expect("record eviction receipt");
        }
        assert!(!reloaded
            .state
            .receipts
            .iter()
            .any(|receipt| receipt.key == first.key));
        assert!(
            reloaded.prepare(&safe_aborted).is_err(),
            "explicit replay_guard must survive reload and eviction"
        );
        let _ = fs::remove_dir_all(directory);
    }

    #[test]
    fn durable_output_lease_legacy_replay_guard_migration_uses_high_water_vs_retained_request() {
        let directory = unique_test_directory("output-lease-replay-guard-migration");
        fs::create_dir_all(&directory).expect("create migration directory");
        let path = directory.join(OUTPUT_LEASE_DURABLE_RECEIPT_STATE_FILE);
        let owner = OutputLeaseOwner::new("legacy-replay-guard", "migration-window", 41, 1)
            .expect("migration owner");
        let request = OutputLeaseRequest::from_action(
            "legacy-replay-guard".to_string(),
            "output-control",
            1,
            OutputLeaseRequestAction::Acquire {
                owner,
                resources: OutputLeaseResources::new(&[OutputLeaseResource::Lighting])
                    .expect("migration resources"),
                project_identity: output_lease_project_identity(0),
                ttl_ms: 30_000,
            },
        )
        .expect("migration request");
        let mut journal = OutputLeaseDurableReceiptJournal::in_memory();
        journal
            .install_path(path.clone())
            .expect("install migration journal");
        let mut registry = OutputLeaseRegistry::fresh_process(41).expect("migration registry");
        let receipt = registry
            .submit_request(&request, 1)
            .expect("migration receipt");
        journal
            .prepare(&request)
            .expect("prepare migration request");
        journal.record(&receipt).expect("record migration receipt");

        let mut legacy = serde_json::to_value(&journal.state).expect("encode legacy state");
        legacy["version"] = serde_json::Value::from(1_u64);
        legacy["origins"][0]
            .as_object_mut()
            .expect("legacy origin object")
            .remove("replay_guard");
        fs::write(
            &path,
            serde_json::to_vec(&legacy).expect("encode legacy journal"),
        )
        .expect("write legacy journal");
        let migrated =
            load_output_lease_receipt_state_from_path(&path).expect("load legacy journal");
        assert_eq!(
            migrated.version, OUTPUT_LEASE_DURABLE_RECEIPT_STATE_VERSION,
            "the explicit v1-to-v2 migration is atomically persisted before use"
        );
        assert!(!migrated.origins[0].replay_guard);

        legacy["origins"][0]["high_water_request_id"] = serde_json::Value::from(2_u64);
        fs::write(
            &path,
            serde_json::to_vec(&legacy).expect("encode guarded legacy journal"),
        )
        .expect("write guarded legacy journal");
        let guarded =
            load_output_lease_receipt_state_from_path(&path).expect("load guarded legacy journal");
        assert!(guarded.origins[0].replay_guard);

        let probe_pending_request =
            durable_output_lease_acquire_request_in_domain(2, OUTPUT_LEASE_DSF2026_PROBE_DOMAIN);
        let mut probe_pending = OutputLeaseDurableReceiptJournal::in_memory();
        assert_eq!(
            probe_pending.prepare_dsf2026_artnet_acceptance_probe(&probe_pending_request, "main"),
            Ok(OutputLeaseDurablePrepareResult::Fresh)
        );
        let mut ambiguous_v1 =
            serde_json::to_value(&probe_pending.state).expect("encode DSF2026 Pending state");
        ambiguous_v1["version"] = serde_json::Value::from(1_u64);
        ambiguous_v1["pending"][0]
            .as_object_mut()
            .expect("DSF2026 Pending object")
            .remove("window_label");
        fs::write(
            &path,
            serde_json::to_vec(&ambiguous_v1).expect("encode ambiguous v1 probe Pending"),
        )
        .expect("write ambiguous v1 probe Pending");
        assert!(
            load_output_lease_receipt_state_from_path(&path).is_err(),
            "a v1 DSF2026 Pending without a local window binding must fail closed rather than pick a new owner"
        );
        let _ = fs::remove_dir_all(directory);
    }

