    #[ignore = "requires SYNDOCAL_SAMPLE_MEDIA_PATH or the local Windows sample MP4"]
    fn sample_media_backend_driver_uses_production_import_timeline_transport_and_output_cores() {
        let path = env::var_os("SYNDOCAL_SAMPLE_MEDIA_PATH")
            .map(PathBuf::from)
            .unwrap_or_else(|| {
                PathBuf::from(r"C:\Users\kouty\Downloads\06.flash back背景途中経過02.mp4")
            });
        run_sample_media_backend_driver(&path).expect("sample media backend driver");
    }

    /// This backend repetition driver builds the frontend's canonical v2
    /// request and calls the production unpublished-native transaction core
    /// with only shell/GPU work injected. It covers the four-display request,
    /// lease, Engine, project, and response shape; the separate stalled-phase
    /// regression is the proof that the same core releases every long-work
    /// guard and rejects stale admission before visibility or presentation.
    fn run_native_output_qa_driver_four_sub_displays() {
        let harness = MediaAssetA6CommandHarness::new();
        let state = Arc::clone(&harness.state);
        let authority = prepare_fake_display_add_authority(&state, "renderer:native-output-qa");
        let owner_principal = authority.owner_principal.clone();
        let owner_incarnation = authority.owner_incarnation;
        let query_state = &authority.query_state;
        let monitors = native_output_qa_monitors();
        let native_ops =
            FakeDisplayOutputNativeOperations::new(Arc::clone(&state), monitors.clone());
        let mut recorder = NativeOutputQaRecorder::default();

        for (offset, monitor) in monitors
            .iter()
            .filter(|monitor| !monitor.is_editor_monitor)
            .enumerate()
        {
            let fence = query_state
                .issue_output_control_fence_for_window("main", &state)
                .expect("issue canonical Add fence");
            let action = protocol::control_plane_command::OutputControlActionV2::AddDisplay {
                spec: DisplayOutputSpecV2 {
                    label: format!("Display {}", monitor.index + 1),
                    monitor_identity: monitor.identity.clone(),
                    monitor_index: monitor.index,
                    width: monitor.physical_width,
                    height: monitor.physical_height,
                    fullscreen: true,
                },
                lease: authority.lease.clone(),
            };
            let request = OutputControlCommandRequestV2 {
                operation_id: OUTPUT_DISPLAY_ADD_OPERATION_ID.to_string(),
                request_id: offset as u64 + 2,
                expected_fence: fence.clone(),
                action,
            };
            request.validate().expect("canonical Add request");
            assert!(
                control_plane_runtime::output_action_requires_native_danger_confirmation(
                    &request.action
                )
            );
            recorder.confirmations += 1;
            let (lease_request, lease_now) = build_output_lease_authorization_request(
                &state,
                &owner_principal,
                "main",
                owner_incarnation,
                request.request_id,
                &request.action,
                fence.project_epoch,
            )
            .expect("build canonical Add lease request");
            let spec = match &request.action {
                protocol::control_plane_command::OutputControlActionV2::AddDisplay {
                    spec, ..
                } => spec.clone(),
                _ => unreachable!(),
            };
            let (applied, fence_after, lease_receipt) =
                add_display_output_with_output_control_fence_core(
                    &state,
                    display_output_control_request!(
                        &spec,
                        &request.expected_fence,
                        &lease_request,
                        lease_now,
                        &owner_principal,
                        "main",
                        owner_incarnation
                    ),
                    native_ops.clone(),
                )
                .expect("canonical QA Add production-core commit");
            let response =
                native_output_qa_receipt_response(&request, fence_after, &lease_receipt, applied);
            assert!(matches!(response, OutputControlResponseV2::Receipt(_)));
        }
        assert_eq!(native_ops.prepared.load(Ordering::Acquire), 4);
        assert_eq!(native_ops.visible.load(Ordering::Acquire), 4);
        assert_eq!(native_ops.presented.load(Ordering::Acquire), 4);
        assert_eq!(native_ops.published.load(Ordering::Acquire), 4);
        assert_eq!(native_ops.publication_state(), (4, 4, 4, 4));
        assert_eq!(recorder.confirmations, 4);
        assert!(state
            .output_lease_durable_receipts
            .lock()
            .expect("QA durable journal")
            .state
            .pending
            .is_empty());
        assert_eq!(state.engine.snapshot().video.outputs.len(), 4);
    }

    /// Headless/native-QA driver seam. It deliberately constructs the same
    /// v2 AddDisplay request that the frontend sends, walks the detected
    /// editor+four-sub-display topology, and injects a Yes confirmation only
    /// through this test callback. It is not a Tauri command and therefore
    /// cannot be reached by release, remote, MIDI, OSC, or shortcut ingress.
    #[test]
    fn native_output_qa_driver_uses_canonical_v2_add_path_for_four_sub_displays() {
        run_native_output_qa_driver_four_sub_displays();
        let source = include_str!("main.rs");
        let wrapper_start = source
            .find("fn add_display_output_with_output_control_fence(")
            .expect("release Add wrapper");
        let core_start = source[wrapper_start..]
            .find("fn add_display_output_with_output_control_fence_core")
            .map(|offset| wrapper_start + offset)
            .expect("full Add production core");
        let release_wrapper = &source[wrapper_start..core_start];
        assert!(release_wrapper.contains("add_display_output_with_output_control_fence_core("));
        assert!(release_wrapper.contains("TauriDisplayOutputNativeOperations"));
        let tauri_native_start = source
            .find("impl DisplayOutputNativeOperations for TauriDisplayOutputNativeOperations")
            .expect("release native-operation bundle");
        let tauri_native_end = source[tauri_native_start..]
            .find("fn retire_prepared_native_video_output_candidate")
            .map(|offset| tauri_native_start + offset)
            .expect("release native-operation bundle end");
        assert!(source[tauri_native_start..tauri_native_end]
            .contains("publish_display_native_candidate_registry_state("));
        let fake_native_start = source
            .find("impl DisplayOutputNativeOperations for FakeDisplayOutputNativeOperations")
            .expect("fake native-operation bundle");
        let fake_native_end = source[fake_native_start..]
            .find("fn native_output_qa_monitors")
            .map(|offset| fake_native_start + offset)
            .expect("fake native-operation bundle end");
        assert!(source[fake_native_start..fake_native_end]
            .contains("publish_display_native_candidate_registry_state("));
        let driver_start = source
            .find("fn run_native_output_qa_driver_four_sub_displays()")
            .expect("four-display production-core driver");
        let driver_end = source[driver_start..]
            .find("fn native_output_qa_driver_uses_canonical_v2_add_path_for_four_sub_displays")
            .map(|offset| driver_start + offset)
            .expect("four-display driver end");
        let driver = &source[driver_start..driver_end];
        assert!(driver.contains("add_display_output_with_output_control_fence_core("));
        assert!(!driver.contains("prepare_internal_media_asset_commit("));
        assert!(!driver.contains("submit_output_lease_candidate_with_classified_commit("));
        assert!(!driver.contains("run_unpublished_display_native_transaction("));
        let mut monitors = [
            make_video_display_monitor(
                0,
                "DISPLAY1".to_string(),
                "path-editor".to_string(),
                (2560, 1440, 0, 0, 1.0, true),
            )
            .unwrap(),
            make_video_display_monitor(
                1,
                "DISPLAY2".to_string(),
                "path-2".to_string(),
                (1920, 1080, 2560, 0, 1.0, false),
            )
            .unwrap(),
            make_video_display_monitor(
                2,
                "DISPLAY3".to_string(),
                "path-3".to_string(),
                (3840, 2160, 4480, 0, 1.0, false),
            )
            .unwrap(),
            make_video_display_monitor(
                3,
                "DISPLAY5".to_string(),
                "path-5".to_string(),
                (1920, 1080, 8320, 0, 1.0, false),
            )
            .unwrap(),
            make_video_display_monitor(
                4,
                "DISPLAY6".to_string(),
                "path-6".to_string(),
                (2560, 720, 10240, 0, 1.0, false),
            )
            .unwrap(),
        ];
        monitors[0].is_editor_monitor = true;
        let expected_fence = OutputControlFenceV1 {
            process_incarnation: 1,
            session_incarnation: 2,
            project_epoch: 3,
            project_revision: 4,
            project_checkpoint_hash: "a".repeat(64),
            project_publication_generation: 5,
            output_epoch: 6,
            output_generation: 7,
            safety_blackout_epoch: 8,
            safety_blackout_generation: 9,
        };
        let lease = protocol::control_plane_command::OutputLeaseAuthorityV1 {
            lease_id: "lease-0000000000000001".to_string(),
            generation: 1,
        };
        let mut confirmation_count = 0usize;
        let mut phases = Vec::new();
        for (request_id, monitor) in monitors
            .iter()
            .filter(|monitor| !monitor.is_editor_monitor)
            .enumerate()
        {
            let action = protocol::control_plane_command::OutputControlActionV2::AddDisplay {
                spec: DisplayOutputSpecV2 {
                    label: format!("Display {}", monitor.index + 1),
                    monitor_identity: monitor.identity.clone(),
                    monitor_index: monitor.index,
                    width: monitor.physical_width,
                    height: monitor.physical_height,
                    fullscreen: true,
                },
                lease: lease.clone(),
            };
            assert_eq!(action.operation_id(), OUTPUT_DISPLAY_ADD_OPERATION_ID);
            assert!(
                control_plane_runtime::output_action_requires_native_danger_confirmation(&action)
            );
            confirmation_count += 1; // injected Yes in this test-only driver
            let request = OutputControlCommandRequestV2 {
                operation_id: OUTPUT_DISPLAY_ADD_OPERATION_ID.to_string(),
                request_id: request_id as u64 + 1,
                expected_fence: expected_fence.clone(),
                action,
            };
            request.validate().expect("QA request must be canonical v2");
            assert!(!request
                .canonical_shape_bytes()
                .expect("QA request shape")
                .is_empty());
            phases.push((
                request.request_id,
                monitor.identity.clone(),
                monitor.physical_width,
                monitor.physical_height,
            ));
        }
        assert_eq!(
            phases.len(),
            4,
            "editor monitor must be excluded from QA adds"
        );
        assert_eq!(
            confirmation_count,
            phases.len(),
            "each add gets one injected Yes"
        );
        assert_eq!(
            phases
                .iter()
                .map(|phase| phase.1.clone())
                .collect::<BTreeSet<_>>()
                .len(),
            4,
            "each QA add must retain a distinct monitor identity"
        );
        assert_eq!(
            phases
                .iter()
                .map(|phase| (phase.2, phase.3))
                .collect::<Vec<_>>(),
            vec![(1920, 1080), (3840, 2160), (1920, 1080), (2560, 720)],
            "QA requests must preserve each authoritative physical size"
        );
    }

    #[test]
    fn native_video_output_window_builder_dpi_matrix_round_trips_physical_extent() {
        const WIDTH: u32 = 3840;
        const HEIGHT: u32 = 2160;
        for scale_factor in [1.0, 1.25, 1.5, 2.0] {
            let (logical_width, logical_height) =
                native_video_output_logical_size(WIDTH, HEIGHT, scale_factor);
            assert_eq!(
                (logical_width * scale_factor).round() as u32,
                WIDTH,
                "{}x{} at scale {} must retain its physical width",
                WIDTH,
                HEIGHT,
                scale_factor
            );
            assert_eq!(
                (logical_height * scale_factor).round() as u32,
                HEIGHT,
                "{}x{} at scale {} must retain its physical height",
                WIDTH,
                HEIGHT,
                scale_factor
            );
        }
        assert_eq!(
            native_video_output_logical_size(WIDTH, HEIGHT, 1.5),
            (2560.0, 1440.0),
            "150% DPI uses 2560x1440 logical builder pixels for a 3840x2160 physical target"
        );
        assert_eq!(
            native_video_output_logical_size(WIDTH, HEIGHT, 2.0),
            (1920.0, 1080.0),
            "200% DPI uses 1920x1080 logical builder pixels for a 3840x2160 physical target"
        );
    }

    #[test]
    fn native_video_output_nonfullscreen_activation_uses_physical_size() {
        assert_eq!(
            native_video_output_activation_geometry(3840, 2160, false),
            NativeVideoOutputActivationGeometry::PhysicalSize {
                width: 3840,
                height: 2160,
            }
        );
        assert_eq!(
            native_video_output_activation_geometry(0, 0, false),
            NativeVideoOutputActivationGeometry::PhysicalSize {
                width: 1,
                height: 1,
            }
        );
        assert_eq!(
            native_video_output_activation_geometry(3840, 2160, true),
            NativeVideoOutputActivationGeometry::Fullscreen
        );
        let accepted = wait_for_native_video_output_physical_size_with(
            3840,
            2160,
            Duration::ZERO,
            Duration::ZERO,
            || Ok(tauri::PhysicalSize::new(3840, 2160)),
            |_| {},
        )
        .expect("nonfullscreen physical client extent should be accepted");
        assert_eq!(accepted, tauri::PhysicalSize::new(3840, 2160));
    }

    #[test]
    fn native_video_output_render_extent_is_always_live_physical_client_size() {
        // The production worker obtains this pair from Window::inner_size on
        // every frame.  A stale Add spec must never remain a render-loop
        // override after a DPI/fullscreen transition.
        assert_eq!(
            native_video_output_render_extent(3840, 2160),
            Some((3840, 2160))
        );
        assert_eq!(
            native_video_output_render_extent(2560, 1440),
            Some((2560, 1440)),
            "a live physical resize is accepted instead of retaining the Add spec"
        );
        assert_eq!(native_video_output_render_extent(0, 2160), None);
    }

    #[test]
    fn native_video_output_physical_extent_mismatch_is_fail_closed() {
        let expected = (3840, 2160);
        let observed = tauri::PhysicalSize::new(2560, 1440);
        assert!(!native_video_output_physical_extent_matches(
            observed, expected.0, expected.1
        ));
        let message = format!(
            "Native video output physical client extent did not converge: expected {}x{}, observed {}x{}",
            expected.0, expected.1, observed.width, observed.height
        );
        assert!(message.contains("expected 3840x2160"));
        assert!(message.contains("observed 2560x1440"));
    }

    #[test]
    fn native_video_output_post_show_convergence_retries_then_accepts_physical_extent() {
        let mut observed = std::collections::VecDeque::from([
            tauri::PhysicalSize::new(2560, 1440),
            tauri::PhysicalSize::new(3840, 2160),
        ]);
        let result = wait_for_native_video_output_physical_size_with(
            3840,
            2160,
            Duration::from_millis(1),
            Duration::ZERO,
            || {
                Ok(observed
                    .pop_front()
                    .unwrap_or(tauri::PhysicalSize::new(3840, 2160)))
            },
            |_| {},
        )
        .expect("post-show physical extent should converge after a DPI transition");
        assert_eq!(result, tauri::PhysicalSize::new(3840, 2160));
    }

    #[test]
    fn native_video_output_post_show_convergence_times_out_and_fails_closed() {
        let result = wait_for_native_video_output_physical_size_with(
            3840,
            2160,
            Duration::ZERO,
            Duration::ZERO,
            || Ok(tauri::PhysicalSize::new(2560, 1440)),
            |_| {},
        );
        let error = result.expect_err("stuck logical extent must fail closed");
        assert!(error.contains("expected 3840x2160"));
        assert!(error.contains("observed 2560x1440"));
    }

    // ---- Native Display fail-close presentation fence ----

    fn native_display_test_engine() -> EngineHandle {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let transition = engine
            .begin_output_ownership_transition(MachineOutputRole::Both)
            .expect("test ownership transition must begin");
        transition
            .complete()
            .expect("test ownership transition must complete");
        engine
    }

    fn install_injected_display_output_extent(
        engine: &EngineHandle,
        output_id: VideoOutputId,
        width: u32,
        height: u32,
    ) {
        engine
            .send(EngineCommand::AddVideoOutput(VideoOutputSummary {
                id: output_id,
                label: format!("Injected Display {output_id}"),
                kind: VideoOutputKind::Display,
                enabled: true,
                composition_id: 1,
                fullscreen: false,
                monitor_id: Some(0),
                monitor_identity: Some(format!("monitor-{output_id}")),
                width,
                height,
                endpoint_name: None,
                opacity: 1.0,
                blackout: false,
                mapping: VideoOutputMapping::default(),
            }))
            .expect("injected Display output command must be accepted");
        wait_until_native_display_test_condition(
            || {
                engine
                    .snapshot()
                    .video
                    .outputs
                    .iter()
                    .any(|output| output.id == output_id)
            },
            "injected Display output did not publish",
        );
    }

    fn wait_until_native_display_test_condition(
        mut condition: impl FnMut() -> bool,
        message: &'static str,
    ) {
        let deadline = Instant::now() + Duration::from_secs(2);
        while !condition() {
            assert!(
                Instant::now() < deadline,
                "native Display test condition timed out: {message}"
            );
            std::thread::sleep(Duration::from_millis(2));
        }
    }

    fn injected_display_authority(
        engine: &EngineHandle,
        output_id: VideoOutputId,
    ) -> NativeDisplayPresentationAuthority {
        let sample = engine.video_presentation_sample();
        capture_native_display_presentation_authority(
            &sample,
            engine.output_ownership_status(),
            engine.safety_blackout_authority(),
            output_id,
            &video_output_window_label(output_id, false),
        )
        .expect("injected Display authority must be present and owned")
    }

    fn counted_present_slot() -> (Arc<AtomicU64>, impl FnOnce() -> Result<(), String>) {
        let presents = Arc::new(AtomicU64::new(0));
        let counter = Arc::clone(&presents);
        (presents, move || {
            counter.fetch_add(1, Ordering::AcqRel);
            Ok(())
        })
    }

    /// Same concrete renderer type the production Display worker owns, so
    /// prepare-level tests exercise the exact production render seam.
    fn test_app_video_renderer() -> AppVideoPreviewRenderer {
        video::VideoPreviewRenderer::with_frame_provider(
            video::VideoRuntimeConfig::default(),
            video::DecoderBackedFrameProvider::new(
                ndi_transport::NdiAwareVideoFrameDecoder::from_env(),
            )
            .with_prefetch(0, 33),
        )
    }

    fn assert_present_revoked(
        result: Result<(), NativeDisplayPresentError>,
        message: &str,
        expected_fragment: &str,
    ) -> String {
        match result.expect_err(message) {
            NativeDisplayPresentError::Revoked(error) => {
                assert!(
                    error.contains(expected_fragment),
                    "revocation '{error}' must mention '{expected_fragment}'"
                );
                error
            }
            NativeDisplayPresentError::Physical(error) => {
                panic!("an authority rejection is never a physical fault: {error}")
            }
        }
    }

