    #[test]
    fn media_asset_hash_streaming_is_exact_and_rejects_cancellation() {
        let directory = unique_test_directory("media-asset-hash");
        fs::create_dir_all(&directory).unwrap();
        let path = directory.join("abc.bin");
        fs::write(&path, b"abc").unwrap();
        let cancel = AtomicBool::new(false);
        let (hash, byte_size, fingerprint, metadata) =
            sha256_local_media_file_streaming(&path, &cancel, |_| Ok(None)).unwrap();
        assert_eq!(hash.algorithm, MediaHashAlgorithm::Sha256);
        assert_eq!(
            hash.hex,
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
        );
        assert_eq!(byte_size, 3);
        assert_eq!(fingerprint.byte_size, 3);
        assert_eq!(metadata, None);

        let cancelled = AtomicBool::new(true);
        let error = sha256_local_media_file_streaming(&path, &cancelled, |_| Ok(None)).unwrap_err();
        assert!(error.contains("cancelled"));

        let cancel_between_chunks = AtomicBool::new(false);
        let mut two_chunks = std::io::Cursor::new(vec![0x5au8; MEDIA_ASSET_HASH_CHUNK_BYTES + 1]);
        let error =
            stream_sha256_from_reader(&mut two_chunks, &cancel_between_chunks, |chunk_index| {
                if chunk_index == 0 {
                    cancel_between_chunks.store(true, Ordering::Release);
                }
                Ok(())
            })
            .unwrap_err();
        assert!(error.contains("cancelled"));
        assert_eq!(
            two_chunks.position(),
            MEDIA_ASSET_HASH_CHUNK_BYTES as u64,
            "cancellation after chunk one must prevent reading chunk two"
        );
        let _ = fs::remove_dir_all(&directory);
    }

    #[test]
    fn media_asset_qa_hash_pause_is_cancellable_and_concurrent_without_synthetic_failure() {
        assert_eq!(media_asset_qa_hash_pause_duration(None).unwrap(), None);
        assert_eq!(
            media_asset_qa_hash_pause_duration(Some(OsStr::new("1"))).unwrap(),
            Some(Duration::from_millis(1))
        );
        assert_eq!(
            media_asset_qa_hash_pause_duration(Some(OsStr::new("30000"))).unwrap(),
            Some(Duration::from_millis(30_000))
        );
        for invalid in ["", "0", "30001", "-1", "not-a-number"] {
            assert!(media_asset_qa_hash_pause_duration(Some(OsStr::new(invalid))).is_err());
        }

        let started = Instant::now();
        wait_at_media_asset_qa_hash_pause(&AtomicBool::new(false), Duration::from_millis(25))
            .unwrap();
        assert!(started.elapsed() >= Duration::from_millis(20));

        let cancel = Arc::new(AtomicBool::new(false));
        let cancelled_thread = {
            let cancel = Arc::clone(&cancel);
            std::thread::spawn(move || {
                wait_at_media_asset_qa_hash_pause(&cancel, Duration::from_secs(2))
            })
        };
        std::thread::sleep(Duration::from_millis(25));
        cancel.store(true, Ordering::Release);
        assert!(cancelled_thread
            .join()
            .unwrap()
            .unwrap_err()
            .contains("cancelled"));

        // Keep enough separation between the concurrent and serialized cases
        // that a busy Windows test runner cannot erase the proof with a single
        // scheduling quantum. Two serialized waits take at least 400 ms.
        let concurrent_started = Instant::now();
        let threads = (0..2)
            .map(|_| {
                std::thread::spawn(|| {
                    wait_at_media_asset_qa_hash_pause(
                        &AtomicBool::new(false),
                        Duration::from_millis(200),
                    )
                })
            })
            .collect::<Vec<_>>();
        for thread in threads {
            thread.join().unwrap().unwrap();
        }
        assert!(concurrent_started.elapsed() < Duration::from_millis(350));
    }

    #[test]
    fn media_asset_hash_and_probe_media_asset_file_coherence_keeps_one_image_across_transient_source_aba(
    ) {
        let directory = unique_test_directory("media-asset-replace-during-probe");
        fs::create_dir_all(&directory).unwrap();
        let path = directory.join("replace.bin");
        fs::write(&path, b"abc").unwrap();
        let cancel = AtomicBool::new(false);
        let original_path = path.clone();
        #[cfg(unix)]
        let parked_original = directory.join("original-parked.bin");
        let replacement = directory.join("replacement.bin");
        #[cfg(unix)]
        let saw_private_snapshot = AtomicBool::new(false);
        // The real probe receives the private snapshot on Unix, never the
        // mutable public source path. Force A->B->A on that public path while
        // the probe reads S; a success is coherent A/S and a conservative
        // version-race rejection is also safe, but hash(A)+probe(B) is not.
        let result = sha256_local_media_file_streaming(&path, &cancel, |probe_path| {
            #[cfg(unix)]
            {
                assert_ne!(probe_path, original_path.as_path());
                assert_eq!(fs::read(probe_path).unwrap(), b"abc");
                saw_private_snapshot.store(true, Ordering::Release);
                fs::write(&replacement, b"xyz").unwrap();
                fs::rename(&original_path, &parked_original).unwrap();
                fs::rename(&replacement, &original_path).unwrap();
                // The public path is B at this point, but the probe remains
                // bound to immutable S=A.
                assert_eq!(fs::read(probe_path).unwrap(), b"abc");
                fs::rename(&original_path, &replacement).unwrap();
                fs::rename(&parked_original, &original_path).unwrap();
            }
            #[cfg(windows)]
            {
                // Windows deliberately probes the guarded original handle/path;
                // an attempted replacement is denied by the retained lock.
                assert_eq!(probe_path, original_path.as_path());
                fs::write(&replacement, b"xyz").unwrap();
                assert!(fs::rename(&replacement, &original_path).is_err());
                let _ = fs::remove_file(&replacement);
            }
            Ok(None)
        });
        #[cfg(windows)]
        {
            let (hash, _, _, _) = result.unwrap();
            assert_eq!(hash.hex, format!("{:x}", Sha256::digest(b"abc")));
            assert_eq!(fs::read(&path).unwrap(), b"abc");
        }
        #[cfg(unix)]
        {
            assert!(saw_private_snapshot.load(Ordering::Acquire));
            match result {
                Ok((hash, _, _, _)) => {
                    assert_eq!(hash.hex, format!("{:x}", Sha256::digest(b"abc")));
                    assert_eq!(fs::read(&path).unwrap(), b"abc");
                }
                Err(error) => assert!(
                    error.contains("replaced") || error.contains("changed"),
                    "unexpected transient-ABA error: {error}"
                ),
            }
        }
        let _ = fs::remove_dir_all(&directory);
    }

    #[cfg(windows)]
    #[test]
    fn media_asset_finalize_retains_exclusive_source_until_token_guard_drops() {
        let directory = unique_test_directory("media-asset-finalize-exclusive");
        fs::create_dir_all(&directory).unwrap();
        let path = directory.join("candidate.bin");
        fs::write(&path, b"abc").unwrap();
        let cancel = AtomicBool::new(false);
        let (content_hash, byte_size, fingerprint, _) =
            sha256_local_media_file_streaming(&path, &cancel, |_| Ok(None)).unwrap();
        let prepared = PreparedLocalMediaAsset {
            input_index: 0,
            label: "candidate".to_string(),
            source: media_asset_commit_test_source(path.to_string_lossy().as_ref()),
            content_hash,
            byte_size,
            fingerprint,
        };
        let retained = finalize_prepared_local_media_assets(&[prepared], &cancel).unwrap();
        assert!(
            fs::OpenOptions::new().write(true).open(&path).is_err(),
            "finalized source must deny a same-process overwrite while token guard lives"
        );
        let replacement = directory.join("replacement.bin");
        fs::write(&replacement, b"xyz").unwrap();
        assert!(
            fs::rename(&replacement, &path).is_err(),
            "finalized source must deny replacement/rename while token guard lives"
        );
        drop(retained);
        assert!(fs::OpenOptions::new().write(true).open(&path).is_ok());
        let _ = fs::remove_dir_all(&directory);
    }

    #[cfg(windows)]
    #[test]
    fn media_asset_file_coherence_windows_retained_guard_cas_and_raii_are_live() {
        // This is deliberately a current-host test: Windows does not use the
        // Unix version CAS, because its finalized retained handle is the
        // stronger write/delete fence. The shared publish gate must remain a
        // harmless no-op while that guard is live, and RAII must release it.
        let directory = unique_test_directory("media-asset-file-coherence-windows");
        fs::create_dir_all(&directory).unwrap();
        let path = directory.join("clip.bin");
        fs::write(&path, b"abc").unwrap();
        let cancel = AtomicBool::new(false);
        let (content_hash, byte_size, fingerprint, _) =
            sha256_local_media_file_streaming(&path, &cancel, |_| Ok(None)).unwrap();
        let prepared = PreparedLocalMediaAsset {
            input_index: 0,
            label: "clip".to_string(),
            source: media_asset_commit_test_source(path.to_string_lossy().as_ref()),
            content_hash,
            byte_size,
            fingerprint,
        };
        let finalized = finalize_one_prepared_local_media_asset(&prepared, &cancel).unwrap();
        ensure_finalized_local_media_sources_current(&[&finalized]).unwrap();
        assert!(
            fs::OpenOptions::new().write(true).open(&path).is_err(),
            "the retained Windows finalization guard must fence writers through commit"
        );
        drop(finalized);
        assert!(
            fs::OpenOptions::new().write(true).open(&path).is_ok(),
            "dropping the finalized token must release the retained guard"
        );
        let _ = fs::remove_dir_all(&directory);
    }

