    #[test]
    fn native_video_output_worker_registry_never_overwrites_an_active_or_quarantined_label() {
        let label = "video-output-41".to_string();
        let workers = Mutex::new(HashMap::new());
        assert!(
            insert_native_video_output_worker(&workers, label.clone(), 41_u64).is_ok(),
            "first worker owns the vacant label"
        );

        let error = insert_native_video_output_worker(&workers, label.clone(), 99_u64)
            .expect_err("an active or quarantined label must never be overwritten");
        assert!(error.is_occupied());
        assert_eq!(
            error.message(),
            "Native video output worker registry already contains active or quarantined video-output-41"
        );
        assert_eq!(error.into_worker(), 99, "the losing worker remains owned");
        assert_eq!(
            workers.lock().unwrap().get(&label),
            Some(&41),
            "the incumbent worker/failure fence remains byte-for-byte reachable"
        );
    }

    #[test]
    fn occupied_candidate_cleanup_closes_only_the_candidate_shell_and_preserves_incumbent() {
        use std::cell::Cell;

        let label = "video-output-42".to_string();
        let workers = Mutex::new(HashMap::from([(label.clone(), 42_u64)]));
        let metrics = Mutex::new(HashMap::<VideoOutputId, u64>::new());
        let start_gate = Arc::new(AtomicBool::new(false));
        let commit_calls = Cell::new(0_u8);
        let (losing_candidate, publication_error) =
            publish_display_native_candidate_registry_state(
                &workers,
                &metrics,
                DisplayNativeCandidatePublication {
                    candidate: 99_u64,
                    label: label.clone(),
                    output_id: 42,
                    start_gate: Some(Arc::clone(&start_gate)),
                    commit: || {
                        commit_calls.set(commit_calls.get() + 1);
                        Ok(())
                    },
                    split: |candidate| (candidate, candidate),
                },
            )
            .expect_err("occupied native identity must reject before commit/publication");
        assert_eq!(losing_candidate, 99);
        assert!(matches!(
            publication_error,
            OutputLeaseCandidateCommitFailure::SafeAbort(ref message)
                if message == "Display native candidate identity is already published"
        ));
        assert_eq!(commit_calls.get(), 0);
        assert!(metrics.lock().unwrap().is_empty());
        assert!(!start_gate.load(Ordering::Acquire));

        let shell_only_calls = Cell::new(0_u8);
        let registered_cleanup_calls = Cell::new(0_u8);

        cleanup_native_video_output_candidate_after_start_failure(
            true,
            || {
                shell_only_calls.set(shell_only_calls.get() + 1);
                Ok(())
            },
            || {
                registered_cleanup_calls.set(registered_cleanup_calls.get() + 1);
                workers.lock().unwrap().remove(&label);
                Ok(())
            },
        )
        .expect("candidate shell cleanup succeeds");

        assert_eq!(shell_only_calls.get(), 1);
        assert_eq!(registered_cleanup_calls.get(), 0);
        assert_eq!(
            workers.lock().unwrap().get(&label),
            Some(&42),
            "the incumbent worker/failure fence remains registered"
        );
    }

    #[test]
    fn native_video_output_transition_retry_stop_allows_bounded_join() {
        let stop = Arc::new(AtomicBool::new(false));
        let worker_stop = Arc::clone(&stop);
        let (waiting_tx, waiting_rx) = std::sync::mpsc::sync_channel(1);
        let (joined_tx, joined_rx) = std::sync::mpsc::sync_channel(1);
        let worker = std::thread::spawn(move || -> Result<(), String> {
            let mut announced_wait = false;
            while native_video_output_transition_retry_wait_with(
                &worker_stop,
                Duration::from_millis(100),
                |interval| {
                    if !announced_wait {
                        waiting_tx
                            .send(())
                            .expect("test must observe transition retry wait");
                        announced_wait = true;
                    }
                    std::thread::sleep(interval);
                },
            ) {}
            Ok(())
        });

        waiting_rx
            .recv_timeout(Duration::from_secs(1))
            .expect("worker must enter the transition retry wait");
        stop.store(true, Ordering::Release);
        let joiner = std::thread::spawn(move || {
            joined_tx
                .send(
                    worker
                        .join()
                        .map_err(|_| "transition retry worker panicked".to_string())?,
                )
                .expect("test must observe worker join");
            Ok::<(), String>(())
        });

        joined_rx
            .recv_timeout(Duration::from_millis(500))
            .expect("stop during transition retry wait must permit a bounded join")
            .unwrap();
        joiner.join().unwrap().unwrap();
    }

    #[test]
    fn native_video_output_worker_is_taken_outside_registry_lock_before_join() {
        let label = "video-output-1".to_string();
        let workers = Arc::new(Mutex::new(HashMap::new()));
        let stop = Arc::new(AtomicBool::new(false));
        let (release_tx, release_rx) = std::sync::mpsc::channel();
        let worker = NativeVideoOutputWorker::new(
            Arc::clone(&stop),
            std::thread::spawn(move || -> Result<(), String> {
                release_rx
                    .recv()
                    .map_err(|error| format!("injected delayed worker release failed: {error}"))?;
                Ok(())
            }),
        );
        workers.lock().unwrap().insert(label.clone(), worker);

        let workers_for_retire = Arc::clone(&workers);
        let label_for_retire = label.clone();
        let (joining_tx, joining_rx) = std::sync::mpsc::channel();
        let retirement = std::thread::spawn(move || -> Result<(), String> {
            let mut worker =
                take_native_video_output_worker(&workers_for_retire, &label_for_retire)?
                    .expect("worker must be present before retirement");
            worker.request_stop();
            joining_tx
                .send(())
                .map_err(|error| format!("injected joining signal failed: {error}"))?;
            worker.join(&label_for_retire)
        });

        joining_rx.recv().unwrap();
        assert!(stop.load(Ordering::Acquire));
        assert!(
            workers.try_lock().is_ok(),
            "the registry mutex must be released before worker.join blocks"
        );
        release_tx.send(()).unwrap();
        retirement.join().unwrap().unwrap();
    }

    #[test]
    fn native_video_output_delayed_join_blocks_reopen_until_retirement_completes() {
        let label = "video-output-1".to_string();
        let workers = Arc::new(Mutex::new(HashMap::new()));
        let transition = Arc::new(Mutex::new(()));
        let (release_tx, release_rx) = std::sync::mpsc::channel();
        workers.lock().unwrap().insert(
            label.clone(),
            NativeVideoOutputWorker::new(
                Arc::new(AtomicBool::new(false)),
                std::thread::spawn(move || -> Result<(), String> {
                    release_rx.recv().map_err(|error| {
                        format!("injected delayed worker release failed: {error}")
                    })?;
                    Ok(())
                }),
            ),
        );

        let workers_for_retire = Arc::clone(&workers);
        let transition_for_retire = Arc::clone(&transition);
        let label_for_retire = label.clone();
        let (joining_tx, joining_rx) = std::sync::mpsc::channel();
        let retirement = std::thread::spawn(move || -> Result<(), String> {
            let _transition_guard = transition_for_retire.lock().unwrap();
            let mut worker =
                take_native_video_output_worker(&workers_for_retire, &label_for_retire)?
                    .expect("worker must be present before retirement");
            worker.request_stop();
            joining_tx
                .send(())
                .map_err(|error| format!("injected joining signal failed: {error}"))?;
            worker.join(&label_for_retire)
        });

        joining_rx.recv().unwrap();
        assert!(
            transition.try_lock().is_err(),
            "a same-label open must wait for the retirement join under the transition lock"
        );
        release_tx.send(()).unwrap();
        retirement.join().unwrap().unwrap();
        assert!(transition.try_lock().is_ok());
    }

