    #[test]
    fn direct_ancillary_preflight_blocks_engine_publish_before_revision_or_hash_failure() {
        let coordinator = ProjectCoordinator {
            revision: u64::MAX,
            ..ProjectCoordinator::default()
        };
        let before = coordinator.ancillary.clone();
        let publishes = AtomicU64::new(0);
        let result = publish_after_direct_project_ancillary_preflight(
            || {
                prepare_direct_project_ancillary_commit(
                    &coordinator,
                    EngineSnapshot::default(),
                    ProjectSwapAncillaryState::default(),
                )
            },
            || {
                publishes.fetch_add(1, Ordering::AcqRel);
                Ok(())
            },
        );
        assert!(result.is_err());
        assert_eq!(publishes.load(Ordering::Acquire), 0);
        assert_eq!(coordinator.revision, u64::MAX);
        assert_eq!(
            coordinator.ancillary.fixture_groups, before.fixture_groups,
            "preflight failure must leave the coordinator/mirror candidate untouched"
        );
        assert_eq!(
            coordinator.ancillary.current_project_path,
            before.current_project_path
        );

        let serialization_publishes = AtomicU64::new(0);
        let serialization_result = publish_after_direct_project_ancillary_preflight(
            || {
                Err::<PreparedDirectAncillaryMutation, _>(
                    "injected canonical checkpoint serialization failure".to_string(),
                )
            },
            || {
                serialization_publishes.fetch_add(1, Ordering::AcqRel);
                Ok(())
            },
        );
        assert!(serialization_result.is_err());
        assert_eq!(serialization_publishes.load(Ordering::Acquire), 0);
    }

    #[test]
    fn save_ticket_path_generation_rejects_reverse_save_as_and_normal_save_completion() {
        let checkpoint = test_project_checkpoint(empty_project_file(), 3);
        let ticket = ProjectSaveTicket {
            checkpoint: checkpoint.clone(),
            current_project_path: Some(PathBuf::from("C:/shows/A.sdc")),
            path_generation: 9,
            authority_disposition_generation: 4,
            save_reservation_generation: Some(7),
        };
        assert!(project_save_ticket_matches_current(
            &ticket,
            &checkpoint,
            &Some(PathBuf::from("C:/shows/A.sdc")),
            9,
            4,
            7,
        ));

        // SA2 completes before SA1. It alone adopts C and increments the
        // path generation; the older Save As and a concurrent normal Save
        // may have written coherent A bytes but cannot report current success.
        let adopted_path = Some(PathBuf::from("C:/shows/C.sdc"));
        assert!(!project_save_ticket_matches_current(
            &ticket,
            &checkpoint,
            &adopted_path,
            10,
            4,
            7,
        ));
    }

    #[test]
    fn prepared_save_publish_rejects_reverse_writer_before_replace_and_keeps_newer_bytes() {
        let directory = std::env::temp_dir().join(format!(
            "syndocal-save-publication-test-{}-{}",
            std::process::id(),
            PROJECT_SAVE_TEMP_SEQUENCE.fetch_add(1, Ordering::Relaxed),
        ));
        fs::create_dir_all(&directory).unwrap();
        let target = directory.join("show.sdc");
        let checkpoint = test_project_checkpoint(empty_project_file(), 3);
        let ticket_a = ProjectSaveTicket {
            checkpoint: checkpoint.clone(),
            current_project_path: Some(target.clone()),
            path_generation: 4,
            authority_disposition_generation: 2,
            save_reservation_generation: Some(1),
        };
        let ticket_b = ProjectSaveTicket {
            save_reservation_generation: Some(2),
            ..ticket_a.clone()
        };
        let temp_a = prepare_project_save_bytes(&target, b"A").unwrap();
        let temp_b = prepare_project_save_bytes(&target, b"B").unwrap();

        let b_is_current = project_save_ticket_matches_current(
            &ticket_b,
            &checkpoint,
            &Some(target.clone()),
            4,
            2,
            2,
        );
        publish_prepared_project_save_if_current(&temp_b, &target, b_is_current).unwrap();
        assert_eq!(fs::read(&target).unwrap(), b"B");

        let a_is_current = project_save_ticket_matches_current(
            &ticket_a,
            &checkpoint,
            &Some(target.clone()),
            4,
            2,
            2,
        );
        assert!(!a_is_current, "S2 reservation must invalidate stalled S1");
        assert!(publish_prepared_project_save_if_current(&temp_a, &target, a_is_current).is_err());
        assert_eq!(
            fs::read(&target).unwrap(),
            b"B",
            "a rejected older writer must fail before replacing same-target B bytes"
        );
        remove_project_publication_staging_v1(&temp_a).unwrap();

        // A Save As/template ticket is captured before its native dialog. A
        // fenced identity B published while the dialog is open invalidates
        // the A ticket before the selected path can be replaced.
        let temp_dialog_a = prepare_project_save_bytes(&target, b"dialog-A").unwrap();
        let mut identity_b = checkpoint.clone();
        identity_b.epoch = checkpoint.epoch + 1;
        let dialog_is_current = project_save_ticket_matches_current(
            &ticket_b,
            &identity_b,
            &Some(target.clone()),
            4,
            2,
            2,
        );
        assert!(!dialog_is_current);
        assert!(publish_prepared_project_save_if_current(
            &temp_dialog_a,
            &target,
            dialog_is_current
        )
        .is_err());
        assert_eq!(fs::read(&target).unwrap(), b"B");
        remove_project_publication_staging_v1(&temp_dialog_a).unwrap();
        fs::remove_dir_all(&directory).unwrap();
    }

    #[test]
    fn pending_identity_replacement_and_save_capture_are_rejected_before_publish() {
        let before = test_project_checkpoint(empty_project_file(), 0);
        let mut coordinator = ProjectCoordinator::default();
        coordinator.history.pending.insert(
            41,
            test_pending_project_transaction(41, "Edit", "fixture:1", before),
        );
        assert!(ensure_no_pending_project_transaction(&coordinator).is_err());
        // Both save-ticket capture and identity swap take this exact guard
        // before their writer/publication callbacks.
        let writer_callbacks = AtomicU64::new(0);
        if ensure_no_pending_project_transaction(&coordinator).is_ok() {
            writer_callbacks.fetch_add(1, Ordering::AcqRel);
        }
        assert_eq!(writer_callbacks.load(Ordering::Acquire), 0);
    }

    #[test]
    fn delayed_old_epoch_transaction_cannot_address_new_identity_reservation() {
        let before = test_project_checkpoint(empty_project_file(), 0);
        let mut coordinator = ProjectCoordinator {
            epoch: 1,
            next_transaction_id: 2,
            ..ProjectCoordinator::default()
        };
        let mut new_before = before.clone();
        new_before.epoch = 1;
        coordinator.history.pending.insert(
            2,
            test_pending_project_transaction(2, "B edit", "fixture:2", new_before),
        );
        // A/1 was consumed before the identity swap. It is neither a current
        // ticket nor an alias for B/2.
        assert!(project_transaction_for_epoch(&coordinator, 1, 0).is_err());
        assert!(project_transaction_for_epoch(&coordinator, 2, 1).is_ok());
    }

    #[test]
    fn cancel_partial_transaction_keeps_changed_checkpoint_undoable() {
        let before = test_project_checkpoint(empty_project_file(), 0);
        let mut changed_project = empty_project_file();
        changed_project.snapshot.blackout = true;
        let after = test_project_checkpoint(changed_project, 0);
        let mut coordinator = ProjectCoordinator::default();
        let pending =
            test_pending_project_transaction(73, "Edit fixtures", "fixture:1", before.clone());
        coordinator.history.pending.insert(73, pending.clone());

        let (history, revision_and_hash) =
            prepare_cancelled_project_transaction_history(&coordinator, pending, after, 1).unwrap();
        assert!(!history.pending.contains_key(&73));
        assert_eq!(history.undo.len(), 1);
        assert_eq!(history.undo[0].label, "Interrupted: Edit fixtures");
        assert_eq!(history.undo[0].before, before);
        assert_eq!(
            revision_and_hash.as_ref().map(|(revision, _)| *revision),
            Some(1)
        );
    }

    #[test]
    fn project_transaction_production_receipt_lifecycle_is_strict_and_idempotent() {
        let harness = MediaAssetA6CommandHarness::new();
        let state = Arc::clone(&harness.state);
        let window_label = "media-asset-a6";
        let owner_id = MEDIA_ASSET_A6_OWNER;
        let begin = |operation_id: &str, label: &str, coalesce_key: &str| {
            let (epoch, revision, checkpoint_hash) = {
                let coordinator = lock_project_coordinator(&state).unwrap();
                (
                    coordinator.epoch,
                    coordinator.revision,
                    coordinator.checkpoint_hash.clone(),
                )
            };
            begin_project_transaction_for_window_label(
                &state,
                window_label,
                begin_project_transaction_request!(
                    label,
                    coalesce_key,
                    epoch,
                    revision,
                    checkpoint_hash,
                    owner_id,
                    operation_id,
                    canonical_project_transaction_shape(
                        "test_project_transaction",
                        label,
                        coalesce_key,
                    ),
                    "test_project_transaction",
                    PROJECT_TRANSACTION_SCHEMA_VERSION
                ),
            )
        };

        state
            .project_transaction_active
            .store(true, Ordering::Release);
        assert!(begin(
            "project-op:1:e1-display-active",
            "E1 display active",
            "fixture:display"
        )
        .is_err());
        assert!(state
            .project_transaction_receipts
            .lock()
            .unwrap()
            .is_empty());
        state
            .project_transaction_active
            .store(false, Ordering::Release);
        let ticket = begin("project-op:2:e1-lifecycle-1", "E1 no-op", "fixture:e1").unwrap();
        let retry = begin("project-op:2:e1-lifecycle-1", "E1 no-op", "fixture:e1").unwrap();
        assert_eq!(retry.transaction_id, ticket.transaction_id);
        assert!(matches!(
            query_project_transaction_for_window_label(
                &state,
                window_label,
                ticket.client_operation_id.clone(),
                ticket.shape_fingerprint.clone(),
                "test_project_transaction".to_string(),
                ticket.schema_version,
                owner_id.to_string(),
            )
            .unwrap(),
            Some(ProjectTransactionRecovery::Pending { .. })
        ));
        let conflicting_shape = canonical_project_transaction_shape(
            "test_project_transaction",
            "E1 different",
            "fixture:e1",
        );
        assert!(begin_project_transaction_for_window_label(
            &state,
            window_label,
            begin_project_transaction_request!(
                "E1 different",
                "fixture:e1",
                ticket.project_epoch,
                ticket.project_revision,
                ticket.project_checkpoint_hash,
                owner_id,
                ticket.client_operation_id,
                conflicting_shape,
                "test_project_transaction",
                PROJECT_TRANSACTION_SCHEMA_VERSION
            ),
        )
        .is_err());

        let cancellation = cancel_project_transaction_for_window_label(
            &state,
            project_transaction_cancel_request!(
                window_label,
                ticket.transaction_id,
                ticket.project_epoch,
                ticket.client_operation_id.clone(),
                ticket.shape_fingerprint.clone(),
                "test_project_transaction",
                ticket.schema_version,
                owner_id
            ),
        )
        .unwrap();
        assert_eq!(cancellation.history_status.undo_depth, 0);
        let cancellation_retry = cancel_project_transaction_for_window_label(
            &state,
            project_transaction_cancel_request!(
                window_label,
                ticket.transaction_id,
                ticket.project_epoch,
                ticket.client_operation_id.clone(),
                ticket.shape_fingerprint.clone(),
                "test_project_transaction",
                ticket.schema_version,
                owner_id
            ),
        )
        .unwrap();
        assert_eq!(
            cancellation_retry.history_status.history_generation,
            cancellation.history_status.history_generation
        );
        assert!(matches!(
            query_project_transaction_for_window_label(
                &state,
                window_label,
                ticket.client_operation_id.clone(),
                ticket.shape_fingerprint.clone(),
                "test_project_transaction".to_string(),
                ticket.schema_version,
                owner_id.to_string(),
            )
            .unwrap(),
            Some(ProjectTransactionRecovery::Cancelled { .. })
        ));
        acknowledge_project_transaction_for_window_label(
            &state,
            window_label,
            ticket.client_operation_id.clone(),
            ticket.shape_fingerprint.clone(),
            "test_project_transaction".to_string(),
            ticket.schema_version,
            owner_id.to_string(),
        )
        .unwrap();
        assert!(query_project_transaction_for_window_label(
            &state,
            window_label,
            ticket.client_operation_id.clone(),
            ticket.shape_fingerprint.clone(),
            "test_project_transaction".to_string(),
            ticket.schema_version,
            owner_id.to_string(),
        )
        .is_err());
        for index in 0..2052 {
            let operation_id = format!("project-op:{}:e1-capacity", index + 3);
            let ticket = begin(&operation_id, "E1 capacity", "fixture:capacity").unwrap();
            cancel_project_transaction_for_window_label(
                &state,
                project_transaction_cancel_request!(
                    window_label,
                    ticket.transaction_id,
                    ticket.project_epoch,
                    operation_id.clone(),
                    ticket.shape_fingerprint.clone(),
                    "test_project_transaction",
                    ticket.schema_version,
                    owner_id
                ),
            )
            .unwrap();
            acknowledge_project_transaction_for_window_label(
                &state,
                window_label,
                operation_id.clone(),
                ticket.shape_fingerprint,
                "test_project_transaction".to_string(),
                ticket.schema_version,
                owner_id.to_string(),
            )
            .unwrap();
        }
        assert!(begin("project-op:2:e1-lifecycle-1", "E1 no-op", "fixture:e1").is_err());
    }

    #[test]
    fn project_transaction_begin_new_operation_respects_full_and_partial_lock_without_drift() {
        for (lock_mode, mode_name) in [
            (OperatorLockMode::Full, "Full"),
            (OperatorLockMode::Partial, "Partial"),
        ] {
            let harness = MediaAssetA6CommandHarness::new();
            let state = Arc::clone(&harness.state);
            let window_label = "media-asset-a6";
            let owner_id = MEDIA_ASSET_A6_OWNER;
            {
                let mut coordinator = state.project_coordinator.lock().unwrap();
                let mut policy = sample_operator_policy();
                policy.lock_on_load = false;
                policy.lock_mode = lock_mode;
                coordinator.ancillary.operator_policy = Some(policy);
            }
            harness.authority();
            let (epoch, revision, checkpoint_hash) = {
                let coordinator = state.project_coordinator.lock().unwrap();
                (
                    coordinator.epoch,
                    coordinator.revision,
                    coordinator.checkpoint_hash.clone(),
                )
            };
            let retry_label = "Operator lock retry";
            let retry_coalesce = "operator:retry";
            let retry_operation = format!("project-op:101:lock-retry-{mode_name}");
            let retry_shape = canonical_project_transaction_shape(
                "operator_lock_retry",
                retry_label,
                retry_coalesce,
            );
            let retry_ticket = begin_project_transaction_for_window_label(
                &state,
                window_label,
                begin_project_transaction_request!(
                    retry_label,
                    retry_coalesce,
                    epoch,
                    revision,
                    checkpoint_hash,
                    owner_id,
                    retry_operation.clone(),
                    retry_shape.clone(),
                    "operator_lock_retry",
                    PROJECT_TRANSACTION_SCHEMA_VERSION
                ),
            )
            .expect("unlocked session may create the receipt");
            state
                .project_operator_sessions
                .lock()
                .unwrap()
                .get_mut(owner_id)
                .expect("Begin creates the operator session")
                .unlocked = false;
            let retry = begin_project_transaction_for_window_label(
                &state,
                window_label,
                begin_project_transaction_request!(
                    retry_label,
                    retry_coalesce,
                    epoch,
                    revision,
                    checkpoint_hash,
                    owner_id,
                    retry_operation.clone(),
                    retry_shape.clone(),
                    "operator_lock_retry",
                    PROJECT_TRANSACTION_SCHEMA_VERSION
                ),
            )
            .expect("exact receipt retry remains available under Operator Lock");
            assert_eq!(retry.transaction_id, retry_ticket.transaction_id);
            cancel_project_transaction_for_window_label(
                &state,
                project_transaction_cancel_request!(
                    window_label,
                    retry_ticket.transaction_id,
                    retry_ticket.project_epoch,
                    retry_operation,
                    retry_shape,
                    "operator_lock_retry",
                    PROJECT_TRANSACTION_SCHEMA_VERSION,
                    owner_id
                ),
            )
            .expect("pre-lock pending cancellation remains available");

            let before_engine = serde_json::to_vec(&project_snapshot_for_save(
                state.engine.persistence_snapshot().unwrap(),
            ))
            .unwrap();
            let before_coordinator = format!("{:?}", *state.project_coordinator.lock().unwrap());
            let before_receipts =
                format!("{:?}", *state.project_transaction_receipts.lock().unwrap());
            let before_lanes = state
                .project_transaction_lanes
                .lock()
                .unwrap()
                .keys()
                .cloned()
                .collect::<HashSet<_>>();
            let before_highwaters = state
                .project_transaction_operation_highwaters
                .lock()
                .unwrap()
                .clone();
            let before_sessions = format!("{:?}", *state.project_operator_sessions.lock().unwrap());
            let before_active = state.project_transaction_active.load(Ordering::Acquire);
            let new_label = format!("Operator lock new {mode_name}");
            let new_coalesce = format!("operator:new:{mode_name}");
            let new_operation = format!("project-op:102:lock-new-{mode_name}");
            let new_shape =
                canonical_project_transaction_shape("operator_lock_new", &new_label, &new_coalesce);
            let error = begin_project_transaction_for_window_label(
                &state,
                window_label,
                begin_project_transaction_request!(
                    new_label,
                    new_coalesce,
                    epoch,
                    revision,
                    checkpoint_hash,
                    owner_id,
                    new_operation,
                    new_shape,
                    "operator_lock_new",
                    PROJECT_TRANSACTION_SCHEMA_VERSION
                ),
            )
            .expect_err("new Begin must be blocked by the active Operator Lock");
            assert!(error.contains(&format!("{mode_name} Lock")), "{error}");
            assert_eq!(
                serde_json::to_vec(&project_snapshot_for_save(
                    state.engine.persistence_snapshot().unwrap(),
                ))
                .unwrap(),
                before_engine
            );
            assert_eq!(
                format!("{:?}", *state.project_coordinator.lock().unwrap()),
                before_coordinator
            );
            assert_eq!(
                format!("{:?}", *state.project_transaction_receipts.lock().unwrap()),
                before_receipts
            );
            assert_eq!(
                state
                    .project_transaction_lanes
                    .lock()
                    .unwrap()
                    .keys()
                    .cloned()
                    .collect::<HashSet<_>>(),
                before_lanes
            );
            assert_eq!(
                *state
                    .project_transaction_operation_highwaters
                    .lock()
                    .unwrap(),
                before_highwaters
            );
            assert_eq!(
                format!("{:?}", *state.project_operator_sessions.lock().unwrap()),
                before_sessions
            );
            assert_eq!(
                state.project_transaction_active.load(Ordering::Acquire),
                before_active
            );
        }
    }

    #[test]
    fn project_transaction_commit_reply_loss_and_inflight_owner_rotation_fail_closed() {
        let harness = MediaAssetA6CommandHarness::new();
        let state = Arc::clone(&harness.state);
        let window_label = "media-asset-a6";
        let owner_id = MEDIA_ASSET_A6_OWNER;
        let begin = |operation_id: &str, schema_version: u16| {
            let (epoch, revision, checkpoint_hash) = {
                let coordinator = lock_project_coordinator(&state).unwrap();
                (
                    coordinator.epoch,
                    coordinator.revision,
                    coordinator.checkpoint_hash.clone(),
                )
            };
            let label = "E1 commit recovery";
            let coalesce = "fixture:e1-commit";
            begin_project_transaction_for_window_label(
                &state,
                window_label,
                begin_project_transaction_request!(
                    label,
                    coalesce,
                    epoch,
                    revision,
                    checkpoint_hash,
                    owner_id,
                    operation_id,
                    canonical_project_transaction_shape(
                        "test_project_transaction",
                        label,
                        coalesce
                    ),
                    "test_project_transaction",
                    schema_version
                ),
            )
        };

        assert!(begin(
            "project-op:1:e1-future-schema",
            PROJECT_TRANSACTION_SCHEMA_VERSION + 1,
        )
        .is_err());
        let committed_ticket = begin(
            "project-op:2:e1-commit-reply-loss",
            PROJECT_TRANSACTION_SCHEMA_VERSION,
        )
        .unwrap();
        let committed = commit_project_transaction_for_window_label(
            &state,
            window_label,
            commit_project_transaction_request!(
                committed_ticket.transaction_id,
                committed_ticket.project_epoch,
                committed_ticket.client_operation_id,
                committed_ticket.shape_fingerprint,
                "test_project_transaction",
                committed_ticket.schema_version,
                owner_id
            ),
        )
        .unwrap();
        let replay = commit_project_transaction_for_window_label(
            &state,
            window_label,
            commit_project_transaction_request!(
                committed_ticket.transaction_id,
                committed_ticket.project_epoch,
                committed_ticket.client_operation_id,
                committed_ticket.shape_fingerprint,
                "test_project_transaction",
                committed_ticket.schema_version,
                owner_id
            ),
        )
        .unwrap();
        assert_eq!(
            replay.history_status.history_generation,
            committed.history_status.history_generation,
            "a lost Commit reply must return the exact terminal receipt without a second history change",
        );
        assert!(matches!(
            query_project_transaction_for_window_label(
                &state,
                window_label,
                committed_ticket.client_operation_id.clone(),
                committed_ticket.shape_fingerprint.clone(),
                "test_project_transaction".to_string(),
                committed_ticket.schema_version,
                owner_id.to_string(),
            )
            .unwrap(),
            Some(ProjectTransactionRecovery::Committed { .. })
        ));
        acknowledge_project_transaction_for_window_label(
            &state,
            window_label,
            committed_ticket.client_operation_id,
            committed_ticket.shape_fingerprint,
            "test_project_transaction".to_string(),
            committed_ticket.schema_version,
            owner_id.to_string(),
        )
        .unwrap();

        let inflight_ticket = begin(
            "project-op:3:e1-inflight-retirement",
            PROJECT_TRANSACTION_SCHEMA_VERSION,
        )
        .unwrap();
        let lane =
            project_transaction_lane_for_operation(&state, &inflight_ticket.client_operation_id)
                .unwrap();
        let admitted = lane.admit().unwrap();
        assert!(register_project_transaction_owner_for_window_label(
            &state,
            window_label,
            "renderer:e1-successor".to_string(),
        )
        .is_err());
        assert_eq!(
            state
                .project_transaction_owners
                .lock()
                .unwrap()
                .get(window_label)
                .map(String::as_str),
            Some(owner_id),
            "a failed retirement must not publish the successor owner",
        );
        drop(admitted);
        register_project_transaction_owner_for_window_label(
            &state,
            window_label,
            "renderer:e1-successor".to_string(),
        )
        .unwrap();
        assert!(!state
            .project_transaction_receipts
            .lock()
            .unwrap()
            .contains_key(&inflight_ticket.client_operation_id));
        assert!(!state
            .project_transaction_lanes
            .lock()
            .unwrap()
            .contains_key(&inflight_ticket.client_operation_id));
        assert!(commit_project_transaction_for_window_label(
            &state,
            window_label,
            commit_project_transaction_request!(
                inflight_ticket.transaction_id,
                inflight_ticket.project_epoch,
                inflight_ticket.client_operation_id,
                inflight_ticket.shape_fingerprint,
                "test_project_transaction",
                inflight_ticket.schema_version,
                owner_id
            ),
        )
        .is_err());
        assert!(
            register_project_transaction_owner_for_window_label(
                &state,
                window_label,
                owner_id.to_string(),
            )
            .is_err(),
            "a same-label ABA cannot re-register the retired owner string"
        );

        let saturated = (0..MAX_PROJECT_TRANSACTION_RETIRED_OWNER_BINDINGS)
            .map(|index| {
                project_transaction_retired_owner_binding_key(
                    &format!("renderer:retired-{index}"),
                    "bounded-window",
                )
            })
            .collect::<HashSet<_>>();
        assert!(
            preflight_project_transaction_owner_binding_retirement(
                &saturated,
                "renderer:retired-0",
                "bounded-window",
            )
            .is_ok(),
            "an already-recorded tombstone remains idempotent at capacity"
        );
        assert!(
            preflight_project_transaction_owner_binding_retirement(
                &saturated,
                "renderer:new-at-capacity",
                "bounded-window",
            )
            .is_err(),
            "retired-owner capacity fails closed instead of evicting replay evidence"
        );
    }

    #[test]
    fn project_transaction_retirement_preserves_pane_owner_and_terminalizes_main_once() {
        let harness = MediaAssetA6CommandHarness::new();
        let state = Arc::clone(&harness.state);
        register_project_transaction_owner_for_window_label(
            &state,
            "pane-video",
            "renderer:pane-video".to_string(),
        )
        .unwrap();
        let begin_for = |window_label: &str, owner_id: &str, operation_id: &str| {
            let (epoch, revision, checkpoint_hash) = {
                let coordinator = lock_project_coordinator(&state).unwrap();
                (
                    coordinator.epoch,
                    coordinator.revision,
                    coordinator.checkpoint_hash.clone(),
                )
            };
            let label = format!("Retirement {window_label}");
            let coalesce = format!("retirement:{window_label}");
            begin_project_transaction_for_window_label(
                &state,
                window_label,
                begin_project_transaction_request!(
                    label,
                    coalesce,
                    epoch,
                    revision,
                    checkpoint_hash,
                    owner_id,
                    operation_id,
                    canonical_project_transaction_shape("retirement_test", &label, &coalesce),
                    "retirement_test",
                    PROJECT_TRANSACTION_SCHEMA_VERSION
                ),
            )
        };

        let pane_ticket =
            begin_for("pane-video", "renderer:pane-video", "project-op:1:e1-pane").unwrap();
        register_project_transaction_owner_for_window_label(
            &state,
            "media-asset-a6",
            "renderer:main-reload".to_string(),
        )
        .unwrap();
        assert!(state
            .project_transaction_owner_incarnations
            .lock()
            .unwrap()
            .contains_key("pane-video"));
        assert!(state
            .project_transaction_lanes
            .lock()
            .unwrap()
            .contains_key(&pane_ticket.client_operation_id));
        cancel_project_transaction_for_window_label(
            &state,
            project_transaction_cancel_request!(
                "pane-video",
                pane_ticket.transaction_id,
                pane_ticket.project_epoch,
                pane_ticket.client_operation_id.clone(),
                pane_ticket.shape_fingerprint.clone(),
                "retirement_test",
                pane_ticket.schema_version,
                "renderer:pane-video"
            ),
        )
        .unwrap();

        let main_ticket = begin_for(
            "media-asset-a6",
            "renderer:main-reload",
            "project-op:2:e1-main",
        )
        .unwrap();
        let old_request_id = state.next_output_lease_request_id.load(Ordering::Acquire);
        state
            .next_output_lease_request_id
            .store(u64::MAX, Ordering::Release);
        assert!(register_project_transaction_owner_for_window_label(
            &state,
            "media-asset-a6",
            "renderer:main-reload-2".to_string(),
        )
        .is_err());
        assert_eq!(
            state
                .project_transaction_owners
                .lock()
                .unwrap()
                .get("media-asset-a6")
                .map(String::as_str),
            Some("renderer:main-reload")
        );
        state
            .next_output_lease_request_id
            .store(old_request_id, Ordering::Release);
        register_project_transaction_owner_for_window_label(
            &state,
            "media-asset-a6",
            "renderer:main-reload-2".to_string(),
        )
        .unwrap();
        assert!(
            state
                .project_transaction_receipts
                .lock()
                .unwrap()
                .get(&main_ticket.client_operation_id)
                .is_none(),
            "a dead renderer cannot acknowledge its terminal receipt, so retirement compacts it"
        );
        assert!(
            state
                .project_transaction_lanes
                .lock()
                .unwrap()
                .get(&main_ticket.client_operation_id)
                .is_none(),
            "retirement must not leak an unreachable operation lane"
        );
        assert_eq!(
            state.project_coordinator.lock().unwrap().history.undo.len(),
            0
        );
    }

    #[test]
    fn history_navigation_rewrites_actual_sources_for_b_to_a_to_b_to_a() {
        let mut project_b = empty_project_file();
        project_b.snapshot.blackout = true;
        let a = test_project_checkpoint(empty_project_file(), 0);
        let b = test_project_checkpoint(project_b, 1);
        let entry = ProjectHistoryEntry {
            entry_id: 1,
            label: "Edit".to_string(),
            coalesce_key: String::new(),
            committed_at_unix_ms: 1,
            before: a.clone(),
            after: b.clone(),
        };
        let mut applied_a = a.clone();
        applied_a.revision = 2;
        let redo_entry = rewrite_navigated_project_history_entry(entry, true, applied_a.clone());
        assert_eq!(redo_entry.before, applied_a);

        let mut applied_b = b.clone();
        applied_b.revision = 3;
        let undo_entry =
            rewrite_navigated_project_history_entry(redo_entry, false, applied_b.clone());
        assert_eq!(undo_entry.after, applied_b);

        let mut applied_a_again = a;
        applied_a_again.revision = 4;
        let redo_entry_again =
            rewrite_navigated_project_history_entry(undo_entry, true, applied_a_again.clone());
        assert_eq!(redo_entry_again.before, applied_a_again);
    }

    #[test]
    fn same_standby_content_does_not_require_an_identity_apply() {
        let project = empty_project_file();
        let mappings = ProjectControlMappings::default();
        let hash = project_checkpoint_hash(&project, &mappings).unwrap();
        let current = ProjectCheckpoint {
            project: project.clone(),
            mappings: mappings.clone(),
            epoch: 8,
            revision: 4,
            hash: hash.clone(),
        };
        let same_hash = project_checkpoint_hash(&project, &mappings).unwrap();
        assert_eq!(hash, same_hash);
        // This is the pure transport decision used by the polling worker:
        // generation may advance, but canonical project+mappings content does
        // not justify another retirement/identity replacement.
        assert!(hash == same_hash && mappings == ProjectControlMappings::default());
        assert!(!project_checkpoint_content_requires_identity_apply(
            &current, &mappings, &same_hash,
        ));

        let mut changed_mappings = mappings.clone();
        changed_mappings.osc_mappings.push(OscControlMapping {
            address: "/changed".to_string(),
            action: OscControlAction::VideoMaster,
            fixture_id: None,
            attribute: None,
            group_id: None,
            cue_id: None,
            layer_id: None,
            video_param: None,
            cue_point_index: None,
            output_id: None,
            duration_ms: None,
            low: 0.0,
            high: 1.0,
        });
        assert_ne!(
            hash,
            project_checkpoint_hash(&project, &changed_mappings).unwrap()
        );
        assert!(project_checkpoint_content_requires_identity_apply(
            &current,
            &changed_mappings,
            &project_checkpoint_hash(&project, &changed_mappings).unwrap(),
        ));
    }

