    #[test]
    fn standby_checkpoints_are_integrity_checked_and_pruned_by_session() {
        let directory = unique_test_directory("standby-checkpoints");
        fs::create_dir_all(&directory).unwrap();
        let project = empty_project_file();
        let mappings = ProjectControlMappings::default();
        for generation in 1..=(STANDBY_SYNC_RETENTION as u64 + 2) {
            write_standby_checkpoint_in(
                &directory,
                &project,
                &mappings,
                "primary-a",
                generation,
                1_000 + generation,
            )
            .unwrap();
        }

        let manifests = list_standby_manifests(&directory).unwrap();
        assert_eq!(
            manifests
                .iter()
                .filter(|manifest| manifest.session_id == "primary-a")
                .count(),
            STANDBY_SYNC_RETENTION
        );
        let checkpoint = read_standby_checkpoint_in(&directory).unwrap().unwrap();
        assert_eq!(
            checkpoint.manifest.generation,
            STANDBY_SYNC_RETENTION as u64 + 2
        );
        assert_eq!(checkpoint.project, project);
        assert!(fs::read_dir(&directory).unwrap().all(|entry| {
            !entry
                .unwrap()
                .file_name()
                .to_string_lossy()
                .ends_with(".tmp")
        }));

        fs::write(
            directory.join(&checkpoint.manifest.project_file),
            b"corrupt",
        )
        .unwrap();
        let fallback = read_standby_checkpoint_in(&directory).unwrap().unwrap();
        assert_eq!(
            fallback.manifest.generation,
            STANDBY_SYNC_RETENTION as u64 + 1
        );

        fs::remove_dir_all(directory).unwrap();
    }

    #[test]
    fn exact_standby_reader_rejects_invalid_newer_candidates_without_local_fallback() {
        let directory = unique_test_directory("standby-exact-strict-reader");
        fs::create_dir_all(&directory).unwrap();
        let session_id = "primary-a-with-hyphens";
        let mappings = ProjectControlMappings::default();
        write_standby_checkpoint_in(
            &directory,
            &empty_project_file(),
            &mappings,
            session_id,
            10,
            1_010,
        )
        .unwrap();
        let expected_ten = StandbyCheckpointIdentity {
            session_id: session_id.to_string(),
            generation: 10,
        };
        assert_eq!(
            read_standby_checkpoint_for_exact_takeover(&directory, &expected_ten)
                .unwrap()
                .manifest
                .generation,
            10
        );

        // Empty, signed, and alphabetic tails are malformed candidates for
        // this exact session. Exact mode must fail closed for each one while
        // the general LocalLatest reader continues to ignore the malformed
        // file and return the valid generation-10 checkpoint.
        for generation_tail in ["", "+011", "alphabetic"] {
            let malformed_manifest = directory.join(format!(
                "syndocal-standby-{session_id}-{generation_tail}.json"
            ));
            fs::write(&malformed_manifest, b"{ invalid json").unwrap();
            assert!(
                read_standby_checkpoint_for_exact_takeover(&directory, &expected_ten).is_err(),
                "exact reader must reject malformed generation tail {generation_tail:?}"
            );
            assert_eq!(
                read_standby_checkpoint_for_session(&directory, Some(session_id))
                    .unwrap()
                    .unwrap()
                    .manifest
                    .generation,
                10,
                "LocalLatest fallback should remain limited to the general reader"
            );
            fs::remove_file(malformed_manifest).unwrap();
        }

        // A non-canonical numeric tail is an invalid candidate for this
        // exact session, not a longer-session collision. Exact mode must
        // reject it while the general reader keeps its existing fallback to
        // the valid generation-10 checkpoint.
        let noncanonical_manifest =
            directory.join(format!("syndocal-standby-{session_id}-011.json"));
        fs::write(&noncanonical_manifest, b"{ invalid json").unwrap();
        assert!(read_standby_checkpoint_for_exact_takeover(&directory, &expected_ten).is_err());
        assert_eq!(
            read_standby_checkpoint_for_session(&directory, Some(session_id))
                .unwrap()
                .unwrap()
                .manifest
                .generation,
            10
        );
        fs::remove_file(noncanonical_manifest).unwrap();

        // A different, longer hyphenated session shares the textual prefix
        // but must not be mistaken for this session's generation candidate.
        write_standby_checkpoint_in(
            &directory,
            &empty_project_file(),
            &mappings,
            "primary-a-with-hyphens-extra",
            99,
            1_099,
        )
        .unwrap();
        assert_eq!(
            read_standby_checkpoint_for_exact_takeover(&directory, &expected_ten)
                .unwrap()
                .manifest
                .generation,
            10
        );

        // The general reader intentionally ignores invalid manifests and can
        // fall back to generation 10. Exact mode must see the filename
        // candidate for generation 11 and reject before any fallback.
        fs::write(
            directory.join(standby_manifest_file_name(session_id, 11)),
            b"{ invalid json",
        )
        .unwrap();
        let expected_eleven = StandbyCheckpointIdentity {
            session_id: session_id.to_string(),
            generation: 11,
        };
        assert!(read_standby_checkpoint_for_exact_takeover(&directory, &expected_ten).is_err());
        assert!(read_standby_checkpoint_for_exact_takeover(&directory, &expected_eleven).is_err());
        assert_eq!(
            read_standby_checkpoint_for_session(&directory, Some(session_id))
                .unwrap()
                .unwrap()
                .manifest
                .generation,
            10
        );

        // A valid newer manifest with a corrupt project must also fail exact
        // mode at project integrity/decoding, while LocalLatest preserves its
        // existing fallback to generation 10.
        fs::remove_file(directory.join(standby_manifest_file_name(session_id, 11))).unwrap();
        let newer_manifest = write_standby_checkpoint_in(
            &directory,
            &empty_project_file(),
            &mappings,
            session_id,
            11,
            1_011,
        )
        .unwrap();
        fs::write(
            directory.join(&newer_manifest.project_file),
            b"corrupt project bytes",
        )
        .unwrap();
        assert!(read_standby_checkpoint_for_exact_takeover(&directory, &expected_ten).is_err());
        assert!(read_standby_checkpoint_for_exact_takeover(&directory, &expected_eleven).is_err());
        assert_eq!(
            read_standby_checkpoint_for_session(&directory, Some(session_id))
                .unwrap()
                .unwrap()
                .manifest
                .generation,
            10
        );

        fs::remove_dir_all(directory).unwrap();
    }

