    #[test]
    fn pane_window_lifecycle_registry_correlates_identity_closes_and_terminals() {
        let mut entries = HashMap::new();

        assert_eq!(
            PaneWindowLifecycleRegistry::establish_identity(
                &mut entries,
                "timeline",
                false,
                "inst-1"
            )
            .unwrap(),
            PaneWindowEstablishIdentity::CreatedFresh
        );
        assert_eq!(
            PaneWindowLifecycleRegistry::establish_identity(
                &mut entries,
                "timeline",
                true,
                "inst-1"
            )
            .unwrap(),
            PaneWindowEstablishIdentity::AdoptedExact
        );
        assert!(PaneWindowLifecycleRegistry::establish_identity(
            &mut entries,
            "timeline",
            false,
            "inst-2"
        )
        .unwrap_err()
        .contains("conflicting window identity"));

        PaneWindowLifecycleRegistry::arm_pending_close(&mut entries, "timeline", "inst-1", "req-1")
            .unwrap();
        assert!(PaneWindowLifecycleRegistry::arm_pending_close(
            &mut entries,
            "timeline",
            "inst-1",
            "req-2"
        )
        .unwrap_err()
        .contains("exactly one pending close"));
        assert!(PaneWindowLifecycleRegistry::arm_pending_close(
            &mut entries,
            "timeline",
            "inst-2",
            "req-2"
        )
        .unwrap_err()
        .contains("claimed 'inst-2'"));
        assert!(PaneWindowLifecycleRegistry::establish_identity(
            &mut entries,
            "timeline",
            false,
            "inst-1"
        )
        .unwrap_err()
        .contains("pending close"));

        let context =
            PaneWindowLifecycleRegistry::query_pending_close_context(&entries, "timeline")
                .expect("pending context");
        assert_eq!(
            context,
            PaneWindowPendingCloseContext {
                pane: "timeline".to_string(),
                instance_id: "inst-1".to_string(),
                request_id: "req-1".to_string(),
            }
        );
        assert_eq!(
            PaneWindowLifecycleRegistry::query_pending_close_context(&entries, "stage"),
            None
        );

        assert!(PaneWindowLifecycleRegistry::cancel_pending_close(
            &mut entries,
            "timeline",
            "inst-1",
            "req-9"
        )
        .unwrap_err()
        .contains("does not match"));
        let (canceled_instance, canceled_request) =
            PaneWindowLifecycleRegistry::cancel_pending_close(
                &mut entries,
                "timeline",
                "inst-1",
                "req-1",
            )
            .unwrap();
        assert_eq!(canceled_instance, "inst-1");
        assert_eq!(canceled_request, "req-1");
        assert!(PaneWindowLifecycleRegistry::cancel_pending_close(
            &mut entries,
            "timeline",
            "inst-1",
            "req-1"
        )
        .unwrap_err()
        .contains("no pending close"));

        PaneWindowLifecycleRegistry::arm_pending_close(&mut entries, "timeline", "inst-1", "req-2")
            .unwrap();
        assert!(
            PaneWindowLifecycleRegistry::retire_identity(&mut entries, "timeline", "inst-9")
                .unwrap_err()
                .contains("claimed 'inst-9'")
        );
        let retired =
            PaneWindowLifecycleRegistry::retire_identity(&mut entries, "timeline", "inst-1")
                .unwrap();
        assert_eq!(retired.instance_id, "inst-1");
        assert_eq!(retired.request_id.as_deref(), Some("req-2"));
        assert!(entries.get("timeline").is_none());
        assert!(
            PaneWindowLifecycleRegistry::retire_identity(&mut entries, "timeline", "inst-1")
                .unwrap_err()
                .contains("no tracked lifecycle identity")
        );

        assert!(PaneWindowLifecycleRegistry::arm_pending_close(
            &mut entries,
            "mixer",
            "inst-m",
            "req-m"
        )
        .unwrap_err()
        .contains("no tracked lifecycle identity"));
        assert!(PaneWindowLifecycleRegistry::establish_identity(
            &mut entries,
            "stage",
            true,
            "inst-s"
        )
        .unwrap_err()
        .contains("without lifecycle identity"));
    }

    #[test]
    fn pane_window_pending_close_rollback_succeeds_exactly_and_treats_mismatches_as_no_ops() {
        let mut entries = HashMap::new();
        PaneWindowLifecycleRegistry::establish_identity(&mut entries, "timeline", false, "inst-1")
            .unwrap();

        // Before anything is armed, an exact-looking rollback is still a
        // harmless no-op.
        assert!(!PaneWindowLifecycleRegistry::rollback_pending_close(
            &mut entries,
            "timeline",
            "inst-1",
            "req-1"
        ));
        assert!(entries.contains_key("timeline"));

        PaneWindowLifecycleRegistry::arm_pending_close(&mut entries, "timeline", "inst-1", "req-1")
            .unwrap();

        // A wrong instance never clears another incarnation's armed request.
        assert!(!PaneWindowLifecycleRegistry::rollback_pending_close(
            &mut entries,
            "timeline",
            "inst-other",
            "req-1"
        ));
        assert_eq!(
            PaneWindowLifecycleRegistry::query_pending_close_context(&entries, "timeline")
                .expect("armed context survives instance mismatch")
                .request_id,
            "req-1"
        );

        // A wrong request never clears the exact armed request.
        assert!(!PaneWindowLifecycleRegistry::rollback_pending_close(
            &mut entries,
            "timeline",
            "inst-1",
            "req-stale"
        ));
        assert_eq!(
            PaneWindowLifecycleRegistry::query_pending_close_context(&entries, "timeline")
                .expect("armed context survives request mismatch")
                .request_id,
            "req-1"
        );

        // Unknown panes are no-ops too.
        assert!(!PaneWindowLifecycleRegistry::rollback_pending_close(
            &mut entries,
            "stage",
            "inst-1",
            "req-1"
        ));

        // The exact instance plus exact request rolls back only the pending
        // close; the tracked identity itself survives for retries.
        assert!(PaneWindowLifecycleRegistry::rollback_pending_close(
            &mut entries,
            "timeline",
            "inst-1",
            "req-1"
        ));
        assert!(
            PaneWindowLifecycleRegistry::query_pending_close_context(&entries, "timeline")
                .is_none(),
            "a successful rollback leaves no pending request"
        );
        let entry = entries.get("timeline").expect("identity survives rollback");
        assert_eq!(entry.instance_id, "inst-1");
        assert_eq!(entry.pending_close, None);

        // Rolling the same arm back twice is a no-op the second time.
        assert!(!PaneWindowLifecycleRegistry::rollback_pending_close(
            &mut entries,
            "timeline",
            "inst-1",
            "req-1"
        ));

        // The identity stays fully reusable: re-arming and retiring still work.
        PaneWindowLifecycleRegistry::arm_pending_close(&mut entries, "timeline", "inst-1", "req-2")
            .unwrap();
        let retired =
            PaneWindowLifecycleRegistry::retire_identity(&mut entries, "timeline", "inst-1")
                .unwrap();
        assert_eq!(retired.instance_id, "inst-1");
        assert_eq!(retired.request_id.as_deref(), Some("req-2"));
    }

    #[test]
    fn project_file_v1_accepts_unknown_fields_and_defaults_added_fields() {
        let mut sample_value: Value = serde_json::from_str(PHASE1_SAMPLE_PROJECT_JSON).unwrap();
        let root = sample_value.as_object_mut().unwrap();
        root.insert("future_top_level".to_string(), json!({ "enabled": true }));
        let snapshot = root
            .get_mut("snapshot")
            .and_then(Value::as_object_mut)
            .unwrap();
        snapshot.insert("future_snapshot_field".to_string(), json!(42));
        snapshot["fixtures"][0]
            .as_object_mut()
            .unwrap()
            .insert("future_fixture_field".to_string(), json!("ignored"));
        let sample_project: ProjectFile = serde_json::from_value(sample_value).unwrap();
        validate_project_file(&sample_project).unwrap();
        assert!(sample_project
            .snapshot
            .cues
            .iter()
            .all(|cue| cue.authored_beats.is_none()));
        assert!(sample_project.snapshot.timeline.events.iter().all(|event| {
            event.time_beats.is_none()
                && event.duration_beats.is_none()
                && !event.conform_to_tempo
                && !event.loop_fill
                && event.rate.is_none()
        }));

        let mut legacy_value = serde_json::to_value(ProjectFile {
            version: PROJECT_FILE_VERSION,
            app: APP_NAME.to_string(),
            operator_policy: None,
            custom_profiles: Vec::new(),
            fixture_groups: Vec::new(),
            snapshot: EngineSnapshot::default(),
        })
        .unwrap();
        let legacy_root = legacy_value.as_object_mut().unwrap();
        legacy_root.remove("custom_profiles");
        let legacy_snapshot = legacy_root["snapshot"].as_object_mut().unwrap();
        legacy_snapshot.remove("node_graphs");
        legacy_snapshot.remove("stage_map");
        legacy_snapshot.remove("stage_map_presets");
        legacy_snapshot.remove("stage_objects");
        legacy_snapshot.remove("dmx_previews");
        legacy_snapshot.remove("palettes");
        legacy_snapshot.remove("playback_executors");
        legacy_snapshot.remove("playback_master");

        let project: ProjectFile = serde_json::from_value(legacy_value).unwrap();
        validate_project_file(&project).unwrap();

        assert!(project.custom_profiles.is_empty());
        assert!(project.snapshot.node_graphs.is_empty());
        assert_eq!(
            project.snapshot.stage_map,
            protocol::StageMapConfig::default()
        );
        assert!(project.snapshot.stage_map_presets.is_empty());
        assert!(project.snapshot.stage_objects.is_empty());
        assert!(project.snapshot.dmx_previews.is_empty());
        assert!(project.snapshot.palettes.is_empty());
        assert_eq!(
            project.snapshot.playback_executors,
            vec![protocol::PlaybackExecutorSummary::default()]
        );
        assert_eq!(project.snapshot.playback_master, 1.0);
    }

