    #[test]
    fn project_snapshot_for_save_drops_volatile_runtime_state() {
        let mut snapshot = EngineSnapshot {
            active_cue_id: Some(7),
            active_fade: Some(protocol::ActiveFadeSummary {
                cue_id: 7,
                progress: 0.5,
                remaining_ms: 1_200,
                paused: true,
            }),
            ..EngineSnapshot::default()
        };
        snapshot.timeline.playing = true;
        snapshot.timeline.position_ms = 12_345;
        snapshot.video.master_opacity = 0.5;
        snapshot.video.auto_vj.config.seed = 42;
        snapshot.video.auto_vj.config.eligible_layer_ids = vec![5, 7];
        let auto_vj_action = protocol::AutoVjAction {
            sequence: 3,
            boundary_index: 2,
            beat: 8,
            layer_id: 7,
            transition_ms: 500,
            selection_token: 99,
            seed: 42,
            show_revision: 4,
            trigger: protocol::AutoVjTrigger::LiveAudioOnset,
            live_audio_feature_sequence: Some(17),
        };
        snapshot.video.auto_vj.status = protocol::AutoVjStatus {
            mode: protocol::AutoVjMode::Running,
            armed: true,
            hold: false,
            show_revision: 4,
            action_sequence: 3,
            last_consumed_boundary: Some(2),
            next_boundary_beat: Some(12),
            last_action: Some(auto_vj_action.clone()),
            action_log: vec![auto_vj_action],
            fault: None,
            live_audio_beat_counter: 8,
            last_live_audio_feature_sequence: Some(17),
            live_audio_waiting: false,
            live_audio_generation: Some(2),
        };
        let auto_vj_config = snapshot.video.auto_vj.config.clone();
        snapshot.dmx_preview = vec![127; 512];
        snapshot.dmx_previews = vec![protocol::DmxUniversePreview {
            universe: 2,
            values: vec![255; 512],
        }];
        snapshot.telemetry.frame_counter = 99;
        snapshot.telemetry.tick_jitter_p99_us = 850;
        snapshot.telemetry.last_error = Some("send failed".to_string());
        snapshot.cue_live_modifiers = vec![protocol::CueLiveModifierState {
            cue_id: 7,
            speed: 2.0,
            size: 0.5,
            phase: 0.25,
            direction: protocol::CueLiveDirection::Reverse,
            segment: 2,
        }];
        snapshot.direct_child_timeline_transports =
            vec![protocol::DirectChildTimelineTransportSummary {
                cue_id: 7,
                position_ms: 8_000,
                duration_ms: 12_000,
                playing: true,
                generation: 3,
                count_in_remaining_ms: 0,
            }];
        snapshot.submasters = vec![protocol::SubmasterSummary {
            group_id: "front".to_string(),
            label: "Front".to_string(),
            level: 0.75,
            strobe_hz: 12.0,
            strobe_fixture_count: 4,
        }];

        let saved = project_snapshot_for_save(snapshot);

        assert!(saved.cue_live_modifiers.is_empty());
        assert!(saved.direct_child_timeline_transports.is_empty());
        assert_eq!(saved.submasters[0].strobe_hz, 0.0);
        assert_eq!(saved.submasters[0].strobe_fixture_count, 0);
        assert_eq!(saved.active_cue_id, Some(7));
        assert_eq!(saved.active_fade, None);
        assert!(!saved.timeline.playing);
        assert_eq!(saved.timeline.position_ms, 12_345);
        assert_eq!(saved.video.master_opacity, 0.5);
        assert_eq!(saved.video.auto_vj.config, auto_vj_config);
        assert_eq!(
            saved.video.auto_vj.status,
            protocol::AutoVjStatus::default()
        );
        assert!(saved.video.auto_vj.status.action_log.is_empty());
        assert!(saved.dmx_preview.is_empty());
        assert!(saved.dmx_previews.is_empty());
        assert_eq!(saved.telemetry, EngineTelemetry::default());
        let saved_json = serde_json::to_string(&saved).unwrap();
        assert!(!saved_json.contains("strobe_hz"));
        assert!(!saved_json.contains("strobe_fixture_count"));
    }

    #[test]
    fn blind_programmer_preview_updates_scene_capture_without_mutating_live_dmx() {
        let project: ProjectFile = serde_json::from_str(PHASE1_SAMPLE_PROJECT_JSON).unwrap();
        let mut snapshot = project.snapshot;
        let fixture = snapshot.fixtures.first().unwrap();
        let fixture_id = fixture.id;
        let attribute = fixture.attribute_values.first().unwrap().attribute.clone();
        let staged_value = fixture
            .attribute_values
            .first()
            .unwrap()
            .value
            .saturating_add(1);
        snapshot.dmx_previews = vec![protocol::DmxUniversePreview {
            universe: 0,
            values: vec![17; 512],
        }];
        snapshot.programmer = protocol::ProgrammerSnapshot {
            enabled: true,
            blind: true,
            values: vec![protocol::ProgrammerValueSummary {
                fixture_id,
                attribute: attribute.clone(),
                value: staged_value,
            }],
            dmx_previews: vec![protocol::DmxUniversePreview {
                universe: 0,
                values: vec![233; 512],
            }],
        };
        let live_dmx_before = snapshot.dmx_previews.clone();

        apply_programmer_preview_to_snapshot(&mut snapshot);

        assert_eq!(snapshot.dmx_previews, live_dmx_before);
        assert_eq!(
            snapshot.fixtures[0]
                .attribute_values
                .iter()
                .find(|value| value.attribute == attribute)
                .map(|value| value.value),
            Some(staged_value)
        );
    }

