    #[test]
    fn project_file_round_trips_cue_live_modifier_defaults_without_saving_latch() {
        let mut project: ProjectFile = serde_json::from_str(PHASE1_SAMPLE_PROJECT_JSON).unwrap();
        let cue_id = project.snapshot.cues[0].id;
        project.snapshot.cues[0].live_modifiers = Some(protocol::CueLiveModifierSettings {
            speed: 2.0,
            size: 0.5,
            phase: 0.25,
            direction: protocol::CueLiveDirection::Authored,
            segment: 0,
            flash: true,
        });
        validate_project_file(&project).unwrap();
        project.snapshot.output.enabled = false;
        for output in &mut project.snapshot.dmx_outputs {
            output.enabled = false;
        }
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        engine.load_project_snapshot(project.snapshot).unwrap();

        engine
            .send(EngineCommand::SetCueLiveModifier {
                cue_id,
                speed: 8.0,
                size: 1.0,
                phase: 0.0,
                direction: protocol::CueLiveDirection::Authored,
                segment: 0,
            })
            .unwrap();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(3);
        loop {
            let snapshot = engine.snapshot();
            if snapshot
                .cue_live_modifiers
                .iter()
                .any(|state| state.cue_id == cue_id && state.speed == 8.0)
            {
                break;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "engine never published the latched live modifier"
            );
            std::thread::sleep(std::time::Duration::from_millis(25));
        }

        let persisted = engine.persistence_snapshot().unwrap();
        let persisted_cue = persisted
            .cues
            .iter()
            .find(|cue| cue.id == cue_id)
            .expect("cue survives persistence");
        assert_eq!(
            persisted_cue.live_modifiers,
            Some(protocol::CueLiveModifierSettings {
                speed: 2.0,
                size: 0.5,
                phase: 0.25,
                direction: protocol::CueLiveDirection::Authored,
                segment: 0,
                flash: true,
            })
        );
        assert!(persisted.cue_live_modifiers.is_empty());
        let saved_json =
            serde_json::to_string(&project_snapshot_for_save(persisted)).expect("snapshot json");
        assert!(!saved_json.contains("cue_live_modifiers"));
        assert!(saved_json.contains("live_modifiers"));
    }

    #[test]
    fn project_save_reload_uses_authored_video_and_strips_audio_runtime() {
        let mut rendered_layer = project_video_layer(10);
        rendered_layer.state.opacity = 0.9;
        let mut authored_layer = rendered_layer.clone();
        authored_layer.state.opacity = 0.35;

        let mut graph = project_node_graph(3, 1);
        graph.audio_runtime = vec![protocol::NodeGraphAudioRuntimeStatus {
            node_id: 1,
            input_value: 0.8,
            output_value: 0.9,
            source_available: true,
            safety_zeroed: false,
            held: true,
            feature_sequence: Some(42),
        }];
        let rendered_video = protocol::VideoSnapshot {
            layers: vec![rendered_layer],
            ..protocol::VideoSnapshot::default()
        };
        let authored_video = protocol::VideoSnapshot {
            layers: vec![authored_layer],
            ..protocol::VideoSnapshot::default()
        };
        let snapshot = EngineSnapshot {
            video: rendered_video,
            authored_video: Some(authored_video),
            node_graphs: vec![graph],
            ..EngineSnapshot::default()
        };

        let saved = project_snapshot_for_save(snapshot);
        let json = serde_json::to_string(&saved).unwrap();
        let reloaded: EngineSnapshot = serde_json::from_str(&json).unwrap();

        assert_eq!(reloaded.video.layers[0].state.opacity, 0.35);
        assert_eq!(reloaded.authored_video, None);
        assert!(reloaded.node_graphs[0].audio_runtime.is_empty());
        assert!(!json.contains("authored_video"));
        assert!(!json.contains("audio_runtime"));
    }

