    #[test]
    fn embedded_sample_effect_preset_adds_retargeted_effect_to_engine() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let profile = custom_fixture_profile_from_request(CustomFixtureProfileRequest {
            manufacturer: "Syndocal".to_string(),
            name: "Preset Target Spot".to_string(),
            mode_name: "8ch".to_string(),
            attributes: vec!["Dimmer".to_string(), "ColorRed".to_string()],
        });
        let fixture_id = engine.allocate_fixture_id();
        engine
            .send(EngineCommand::PatchFixture {
                fixture_id,
                request: PatchFixtureRequest {
                    profile_path: profile.source_path.clone(),
                    mode_name: Some("8ch".to_string()),
                    label: "Preset Target".to_string(),
                    universe: 0,
                    address: 1,
                    group_ids: Vec::new(),
                    position: Vec3::default(),
                    rotation: Rotation3::default(),
                },
                profile,
            })
            .unwrap();

        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot
                .fixtures
                .iter()
                .any(|fixture| fixture.id == fixture_id)
            {
                break;
            }
            std::thread::sleep(Duration::from_millis(25));
            snapshot = engine.snapshot();
        }
        assert!(snapshot
            .fixtures
            .iter()
            .any(|fixture| fixture.id == fixture_id));

        let (_, pulse_json) = sample_effect_preset_json("pulse").unwrap();
        let pulse: EffectPreset = serde_json::from_str(pulse_json).unwrap();
        let target_override = EffectTargetOverride {
            fixture_ids: vec![fixture_id],
            target_group_ids: Vec::new(),
            attribute: "Dimmer".to_string(),
            video_targets: Vec::new(),
        };
        let effect_id =
            add_effect_preset_to_engine(&engine, pulse, Some(&target_override)).unwrap();

        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot.effects.iter().any(|effect| effect.id == effect_id) {
                break;
            }
            std::thread::sleep(Duration::from_millis(25));
            snapshot = engine.snapshot();
        }
        let effect = snapshot
            .effects
            .iter()
            .find(|effect| effect.id == effect_id)
            .expect("retargeted sample effect should be in the engine snapshot");
        assert_eq!(effect.effect_type, EffectKind::Lfo);
        assert_eq!(effect.fixture_ids, vec![fixture_id]);
        assert!(effect.target_group_ids.is_empty());
        assert_eq!(effect.attribute, "Dimmer");
        assert_eq!(effect.period_ms, Some(500));
        assert_eq!(
            effect.clock_sync,
            Some(protocol::EffectClockSync { beats: 1.0 })
        );
        assert!(effect.enabled);
    }

    #[test]
    fn effect_only_cue_loads_duplicates_recalls_and_cleans_removed_effect_refs() {
        let project = project_with_effect_only_cue();
        validate_project_file(&project).unwrap();
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        engine
            .load_project_snapshot(project.snapshot.clone())
            .unwrap();

        let mut loaded = engine.snapshot();
        for _ in 0..20 {
            if loaded.cues.iter().any(|cue| cue.id == 7)
                && loaded.effects.iter().any(|effect| effect.id == 9)
            {
                break;
            }
            std::thread::sleep(Duration::from_millis(25));
            loaded = engine.snapshot();
        }
        assert_eq!(loaded.cues.len(), 1);
        assert_eq!(
            loaded.cues[0].effect_targets,
            project.snapshot.cues[0].effect_targets
        );
        assert!(loaded.effects[0].enabled);

        engine.send(EngineCommand::TriggerCue(7)).unwrap();
        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot
                .effects
                .iter()
                .any(|effect| effect.id == 9 && !effect.enabled)
            {
                break;
            }
            std::thread::sleep(Duration::from_millis(25));
            snapshot = engine.snapshot();
        }
        assert!(snapshot
            .effects
            .iter()
            .any(|effect| effect.id == 9 && !effect.enabled));

        engine
            .send(EngineCommand::DuplicateCue {
                source_cue_id: 7,
                cue_id: 8,
                label: "Effect Look Copy".to_string(),
            })
            .unwrap();
        snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot.cues.iter().any(|cue| cue.id == 8) {
                break;
            }
            std::thread::sleep(Duration::from_millis(25));
            snapshot = engine.snapshot();
        }
        let duplicate = snapshot
            .cues
            .iter()
            .find(|cue| cue.id == 8)
            .expect("duplicated effect-only cue");
        assert_eq!(
            duplicate.effect_targets,
            project.snapshot.cues[0].effect_targets
        );

        engine.send(EngineCommand::RemoveEffect(9)).unwrap();
        snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot.effects.is_empty()
                && snapshot
                    .cues
                    .iter()
                    .all(|cue| cue.effect_targets.is_empty())
            {
                break;
            }
            std::thread::sleep(Duration::from_millis(25));
            snapshot = engine.snapshot();
        }
        assert!(snapshot.effects.is_empty());
        assert!(snapshot
            .cues
            .iter()
            .all(|cue| cue.effect_targets.is_empty()));
    }

    #[test]
    fn embedded_color_sample_adds_and_duplicates_complete_disabled_body() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let profile = custom_fixture_profile_from_request(CustomFixtureProfileRequest {
            manufacturer: "Syndocal".to_string(),
            name: "RGB Preset Target".to_string(),
            mode_name: "RGB".to_string(),
            attributes: vec![
                "ColorAdd_R".to_string(),
                "ColorAdd_G".to_string(),
                "ColorAdd_B".to_string(),
            ],
        });
        let fixture_id = engine.allocate_fixture_id();
        engine
            .send(EngineCommand::PatchFixture {
                fixture_id,
                request: PatchFixtureRequest {
                    profile_path: profile.source_path.clone(),
                    mode_name: Some("RGB".to_string()),
                    label: "RGB Preset Target".to_string(),
                    universe: 0,
                    address: 1,
                    group_ids: Vec::new(),
                    position: Vec3::default(),
                    rotation: Rotation3::default(),
                },
                profile,
            })
            .unwrap();
        for _ in 0..20 {
            if engine
                .snapshot()
                .fixtures
                .iter()
                .any(|fixture| fixture.id == fixture_id)
            {
                break;
            }
            std::thread::sleep(Duration::from_millis(25));
        }

        let (_, json) = sample_effect_preset_json("spectrum").unwrap();
        let mut preset: EffectPreset = serde_json::from_str(json).unwrap();
        preset.enabled = false;
        let target_override = EffectTargetOverride {
            fixture_ids: vec![fixture_id],
            target_group_ids: Vec::new(),
            attribute: String::new(),
            video_targets: Vec::new(),
        };
        validate_effect_target_override_for_preset(&preset, &target_override).unwrap();
        let source_id =
            add_sample_effect_preset_to_engine(&engine, preset, Some(&target_override)).unwrap();
        let source = engine
            .snapshot()
            .effects
            .into_iter()
            .find(|effect| effect.id == source_id)
            .expect("Color sample should publish before add returns");
        assert_eq!(source.effect_type, EffectKind::Color);
        assert!(!source.enabled);
        let source_color = source.color.expect("Color sample body");
        assert_eq!(source_color.fixture_ids, vec![fixture_id]);
        assert!(source_color.target_group_ids.is_empty());
        assert_eq!(source_color.stops.len(), 7);
        assert_eq!(
            source_color.interpolation,
            protocol::ColorEffectInterpolation::HsvShortest
        );

        let duplicate_id = duplicate_effect_in_engine(&engine, source_id).unwrap();
        let duplicate = engine
            .snapshot()
            .effects
            .into_iter()
            .find(|effect| effect.id == duplicate_id)
            .expect("Color duplicate should publish before duplicate returns");
        assert!(!duplicate.enabled);
        let duplicate_color = duplicate.color.expect("duplicated Color body");
        assert_eq!(duplicate_color.label, "Colour Spectrum Copy");
        assert_eq!(duplicate_color.fixture_ids, source_color.fixture_ids);
        assert_eq!(duplicate_color.stops, source_color.stops);
        assert_eq!(duplicate_color.algorithm, source_color.algorithm);
        assert_eq!(duplicate_color.interpolation, source_color.interpolation);
        assert_eq!(duplicate_color.period_ms, source_color.period_ms);
        assert_eq!(duplicate_color.clock_sync, source_color.clock_sync);
        assert_eq!(duplicate_color.phase, source_color.phase);
        assert_eq!(duplicate_color.fixture_spread, source_color.fixture_spread);
        assert_eq!(duplicate_color.blend_mode, source_color.blend_mode);
    }

    #[test]
    fn embedded_chaser_sample_expands_group_and_publishes_add_update_duplicate() {
        let engine = EngineHandle::start_for_tests(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let profile = custom_fixture_profile_from_request(CustomFixtureProfileRequest {
            manufacturer: "Syndocal".to_string(),
            name: "Chaser Target Spot".to_string(),
            mode_name: "8ch".to_string(),
            attributes: vec!["Dimmer".to_string(), "Pan".to_string()],
        });
        let first_id = engine.allocate_fixture_id();
        let second_id = engine.allocate_fixture_id();
        for (fixture_id, label, address) in [
            (first_id, "Chaser Front 1", 1),
            (second_id, "Chaser Front 2", 10),
        ] {
            engine
                .send(EngineCommand::PatchFixture {
                    fixture_id,
                    request: PatchFixtureRequest {
                        profile_path: profile.source_path.clone(),
                        mode_name: Some("8ch".to_string()),
                        label: label.to_string(),
                        universe: 0,
                        address,
                        group_ids: vec!["Front".to_string()],
                        position: Vec3::default(),
                        rotation: Rotation3::default(),
                    },
                    profile: profile.clone(),
                })
                .unwrap();
        }
        for _ in 0..20 {
            if engine.snapshot().fixtures.len() == 2 {
                break;
            }
            std::thread::sleep(Duration::from_millis(25));
        }

        let (_, json) = sample_effect_preset_json("chase").unwrap();
        let mut preset: EffectPreset = serde_json::from_str(json).unwrap();
        preset.enabled = false;
        let target_override = EffectTargetOverride {
            fixture_ids: Vec::new(),
            target_group_ids: vec!["Front".to_string()],
            attribute: "Dimmer".to_string(),
            video_targets: Vec::new(),
        };
        let source_id =
            add_sample_effect_preset_to_engine(&engine, preset, Some(&target_override)).unwrap();
        let source = engine
            .snapshot()
            .effects
            .into_iter()
            .find(|effect| effect.id == source_id)
            .expect("Chaser sample should publish before add returns");
        assert_eq!(source.effect_type, EffectKind::Chaser);
        assert!(!source.enabled);
        let mut source_request = source.chaser.expect("Chaser sample body");
        assert_eq!(source_request.steps.len(), 2);
        assert_eq!(source_request.steps[0].fixture_ids, vec![first_id]);
        assert_eq!(source_request.steps[1].fixture_ids, vec![second_id]);
        assert!(source_request
            .steps
            .iter()
            .all(|step| step.target_group_ids.is_empty()));

        source_request.direction = protocol::ChaserDirection::Random;
        source_request.random_seed = 77;
        source_request.random_cycle_count = 4;
        engine
            .update_chaser_effect(source_id, source_request.clone())
            .unwrap();
        let updated = engine
            .snapshot()
            .effects
            .into_iter()
            .find(|effect| effect.id == source_id)
            .expect("Chaser update should publish before returning");
        assert_eq!(updated.chaser.as_ref().unwrap(), &source_request);

        let duplicate_id = duplicate_effect_in_engine(&engine, source_id).unwrap();
        let duplicate = engine
            .snapshot()
            .effects
            .into_iter()
            .find(|effect| effect.id == duplicate_id)
            .expect("Chaser duplicate should publish before duplicate returns");
        assert!(!duplicate.enabled);
        let duplicate_request = duplicate.chaser.expect("duplicated Chaser body");
        assert_eq!(duplicate_request.label, "Front Dimmer Chaser Copy");
        assert_eq!(duplicate_request.steps, source_request.steps);
        assert_eq!(duplicate_request.features, source_request.features);
        assert_eq!(duplicate_request.direction, source_request.direction);
        assert_eq!(
            duplicate_request.active_step_count,
            source_request.active_step_count
        );
        assert_eq!(duplicate_request.random_seed, source_request.random_seed);
        assert_eq!(
            duplicate_request.random_cycle_count,
            source_request.random_cycle_count
        );
    }

