    /// Minimal RFC 6455 client for the app-level production-loopback proof.
    /// `tungstenite` is intentionally not a direct app dependency; this
    /// client implements only the masked, unfragmented text frames needed by
    /// the authenticated `/dj-link` contract.
    struct DjLinkLoopbackClient {
        stream: std::net::TcpStream,
    }

    impl DjLinkLoopbackClient {
        fn connect(port: u16) -> Self {
            Self::connect_path(port, "/dj-link")
        }

        fn connect_path(port: u16, path: &str) -> Self {
            let mut stream = std::net::TcpStream::connect(("127.0.0.1", port))
                .expect("connect actual Remote listener");
            stream
                .set_read_timeout(Some(Duration::from_secs(5)))
                .unwrap();
            stream
                .set_write_timeout(Some(Duration::from_secs(1)))
                .unwrap();
            stream.set_nodelay(true).unwrap();
            let request = format!(
                "GET {path} HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\nSec-WebSocket-Version: 13\r\n\r\n"
            );
            stream.write_all(request.as_bytes()).unwrap();
            let mut response = Vec::new();
            while !response.ends_with(b"\r\n\r\n") {
                assert!(response.len() < 8 * 1024, "WebSocket upgrade was oversized");
                let mut byte = [0_u8; 1];
                stream.read_exact(&mut byte).unwrap();
                response.push(byte[0]);
            }
            let response = String::from_utf8(response).unwrap();
            assert!(
                response.starts_with("HTTP/1.1 101"),
                "Remote WebSocket upgrade failed: {response:?}"
            );
            Self { stream }
        }

        fn send_json(&mut self, value: &Value) {
            let payload = value.to_string().into_bytes();
            let mut frame = Vec::with_capacity(payload.len() + 14);
            frame.push(0x81);
            match payload.len() {
                len @ 0..=125 => frame.push(0x80 | len as u8),
                len @ 126..=65_535 => {
                    frame.push(0x80 | 126);
                    frame.extend_from_slice(&(len as u16).to_be_bytes());
                }
                len => {
                    frame.push(0x80 | 127);
                    frame.extend_from_slice(&(len as u64).to_be_bytes());
                }
            }
            let mask = [0x12, 0x34, 0x56, 0x78];
            frame.extend_from_slice(&mask);
            frame.extend(
                payload
                    .iter()
                    .enumerate()
                    .map(|(index, byte)| byte ^ mask[index % mask.len()]),
            );
            self.stream.write_all(&frame).unwrap();
        }

        fn read_json(&mut self) -> Value {
            let mut header = [0_u8; 2];
            self.stream.read_exact(&mut header).unwrap();
            assert_eq!(header[0] & 0x0f, 0x1, "expected a WebSocket text frame");
            assert_eq!(header[1] & 0x80, 0, "server frames must not be masked");
            let mut len = u64::from(header[1] & 0x7f);
            if len == 126 {
                let mut extended = [0_u8; 2];
                self.stream.read_exact(&mut extended).unwrap();
                len = u64::from(u16::from_be_bytes(extended));
            } else if len == 127 {
                let mut extended = [0_u8; 8];
                self.stream.read_exact(&mut extended).unwrap();
                len = u64::from_be_bytes(extended);
            }
            assert!(len <= 1024 * 1024, "DJ Link reply exceeded test bound");
            let mut payload = vec![0_u8; len as usize];
            self.stream.read_exact(&mut payload).unwrap();
            serde_json::from_slice(&payload).unwrap()
        }

        fn read_ack(&mut self) -> protocol::DjLinkAck {
            serde_json::from_value(self.read_json()).unwrap()
        }
    }

    fn dj_link_socket_hello(token: &str, session_id: &str, event_id: &str) -> Value {
        json!({
            "v": protocol::DJ_LINK_PROTOCOL_VERSION,
            "type": "DJ_AGENT_HELLO",
            "agentId": protocol::DJ_LINK_AGENT_ID,
            "sessionId": session_id,
            "sequence": 1,
            "eventId": event_id,
            "payload": {
                "authToken": token,
                "version": protocol::DJ_LINK_PROTOCOL_VERSION,
                "capabilities": protocol::DJ_LINK_REQUIRED_CAPABILITIES
            }
        })
    }

    fn dj_link_socket_release(session_id: &str, timeline_id: &str) -> Value {
        json!({
            "v": protocol::DJ_LINK_PROTOCOL_VERSION,
            "type": "DJ_RELEASE",
            "agentId": protocol::DJ_LINK_AGENT_ID,
            "sessionId": session_id,
            "sequence": 4,
            "eventId": "production-stop-physical-release",
            "payload": {
                "state": "released",
                "timelineId": timeline_id,
                "playSessionId": "production-stop-play"
            }
        })
    }

    fn complete_dj_link_socket_snapshot_gate(client: &mut DjLinkLoopbackClient, session_id: &str) {
        client.send_json(&json!({
            "v": protocol::DJ_LINK_PROTOCOL_VERSION,
            "type": "DJ_STATE_SYNC",
            "agentId": protocol::DJ_LINK_AGENT_ID,
            "sessionId": session_id,
            "sequence": 2,
            "eventId": format!("production-stop-sync-{session_id}"),
            "payload": {
                "released": false,
                "ownerDeck": 1,
                "ownerDeckId": "rekordbox-deck-1",
                "activePlaySessionId": "production-stop-play"
            }
        }));
        let sync_ack = client.read_ack();
        assert_eq!(
            sync_ack.outcome,
            protocol::DjLinkAckOutcome::Accepted,
            "DJ Link state sync was rejected: {sync_ack:?}"
        );
        client.send_json(&json!({
            "v": protocol::DJ_LINK_PROTOCOL_VERSION,
            "type": "DJ_TIMELINE_STATE_REQUEST",
            "agentId": protocol::DJ_LINK_AGENT_ID,
            "sessionId": session_id,
            "sequence": 3,
            "eventId": format!("production-stop-state-{session_id}"),
            "payload": {}
        }));
        assert_eq!(
            client.read_ack().outcome,
            protocol::DjLinkAckOutcome::Accepted
        );
        let state = client.read_json();
        assert_eq!(state["type"], "DJ_TIMELINE_STATE");
    }

    #[test]
    fn authenticated_dj_track_active_is_blocked_before_project_mapping_is_loaded() {
        let harness = MediaAssetA6CommandHarness::new();
        let state = Arc::clone(&harness.state);
        let engine_before = state.engine.snapshot();
        let runtime_before = state.dj_link_runtime.lock().unwrap().clone();
        let mappings_before = state
            .project_coordinator
            .lock()
            .unwrap()
            .mappings
            .dj_track_triggers
            .clone();
        let active = dj_link_test_envelope(
            protocol::DjLinkMessageType::TrackActive,
            1,
            "cold-project-active",
            json!({
                "deck": 1,
                "deckId": "rekordbox-deck-1",
                "contentId": "cold-project-content",
                "trackBpm": 120.0,
                "positionAtSendSec": 0.0,
                "effectiveBpm": 120.0,
                "positionRevision": 1,
                "sampleAgeMs": 0,
                "isPlaying": true,
                "startedAt": "2026-08-26T00:00:00Z",
                "playSessionId": "cold-project-play",
                "loop": null
            }),
        );
        assert!(matches!(
            dispatch_authenticated_dj_link_event_for_project(
                false,
                active.clone(),
                &state.engine,
                state.project_coordinator.as_ref(),
                state.dj_link_runtime.as_ref(),
                state.project_external_command_admission.as_ref(),
                state.project_transaction_active.as_ref(),
            ),
            DjLinkDispatchOutcome::Rejected { code, .. } if code == "project_mapping_not_loaded"
        ));
        assert_eq!(state.engine.snapshot(), engine_before);
        assert_eq!(*state.dj_link_runtime.lock().unwrap(), runtime_before);
        assert_eq!(
            state
                .project_coordinator
                .lock()
                .unwrap()
                .mappings
                .dj_track_triggers,
            mappings_before
        );

        // The cold project has no authored Timeline phase yet, so it is not a
        // valid target for a v3 TrackActive start. Model the project-load
        // boundary before asserting that the now-admitted mapping reaches the
        // engine.
        let mut loaded_timeline = state.engine.snapshot().timeline;
        loaded_timeline.phases = vec![TimelinePhaseSummary {
            id: protocol::TimelinePhaseId(1),
            label: "Cold project loaded DJ Link phase".to_string(),
            role: protocol::TimelinePhaseRole::Intro,
            start_ms: 0,
            end_ms: 16_000,
        }];
        loaded_timeline.loop_region = Some(TimelineLoopRegionSummary {
            a_ms: 0,
            b_ms: 16_000,
            enabled: false,
            musical_length_beats: None,
        });
        state
            .engine
            .apply_timeline_bank_published(vec![loaded_timeline.clone()], loaded_timeline.id, false)
            .unwrap();
        let timeline_id = state.engine.snapshot().timeline.id;
        {
            let mut coordinator = state.project_coordinator.lock().unwrap();
            let mut mapping = dj_link_test_mapping(
                "cold-project-content",
                protocol::DjTrackSelector {
                    content_id: Some("cold-project-content".to_string()),
                    title: None,
                    artist: None,
                    title_contains: None,
                    fallback_deck: None,
                },
            );
            mapping.timeline_id = timeline_id;
            coordinator.mappings.dj_track_triggers = vec![mapping];
        }
        *state.current_project_path.lock().unwrap() = Some(PathBuf::from("loaded-project.sdc"));
        assert!(matches!(
            dispatch_authenticated_dj_link_event_for_project(
                true,
                active,
                &state.engine,
                state.project_coordinator.as_ref(),
                state.dj_link_runtime.as_ref(),
                state.project_external_command_admission.as_ref(),
                state.project_transaction_active.as_ref(),
            ),
            DjLinkDispatchOutcome::TimelineState { .. }
        ));
    }

    #[test]
    fn dj_only_listener_rejects_generic_start_without_losing_old_authentication() {
        let harness = MediaAssetA6CommandHarness::new();
        let state = Arc::clone(&harness.state);
        let probe = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let port = probe.local_addr().unwrap().port();
        drop(probe);
        let token = "0123456789abcdef0123456789abcdef";
        state
            .dj_link_machine
            .lock()
            .unwrap()
            .install_test_armed_listener_authority("127.0.0.1", port, token);
        let dj_only = RemoteControlConfig {
            bind_ip: "127.0.0.1".to_string(),
            port,
            allow_lan: true,
            web_remote_enabled: false,
            dj_link_enabled: true,
            dj_link_bind_ip: Some("127.0.0.1".to_string()),
            ..RemoteControlConfig::default()
        };
        let generic = RemoteControlConfig {
            bind_ip: "127.0.0.1".to_string(),
            port,
            pairing_pin: "123456".to_string(),
            ..RemoteControlConfig::default()
        };
        let error = start_remote_control_for_state(&state, generic.clone())
            .expect_err("armed authority must reject a raw Web-only start");
        assert!(error.contains("armed"), "unexpected error: {error}");
        assert!(state.remote_control.lock().unwrap().is_none());
        let armed_status = state.dj_link_machine.lock().unwrap().status();
        assert!(armed_status.auto_start_armed);
        assert!(armed_status.credential_ready);
        start_remote_control_for_state(&state, dj_only.clone()).expect("start DJ-only listener");

        let error = start_remote_control_for_state(&state, generic.clone())
            .expect_err("must not replace DJ-only");
        assert!(error.contains("armed"), "unexpected error: {error}");
        let status = state
            .remote_control
            .lock()
            .unwrap()
            .as_ref()
            .map(RemoteWsServer::status)
            .expect("DJ-only listener retained");
        assert!(status.running);
        assert!(!status.web_remote_enabled);
        assert!(status.dj_link_enabled);

        let mut retained_client = DjLinkLoopbackClient::connect(port);
        retained_client.send_json(&dj_link_socket_hello(
            token,
            "mode-guard-retained",
            "mode-guard-retained-hello",
        ));
        assert_eq!(
            retained_client.read_ack().outcome,
            protocol::DjLinkAckOutcome::Accepted,
            "rejected generic Start must retain the old DJ credential"
        );
        drop(retained_client);
        stop_remote_control_for_state(&state).expect("stop retained listener");

        let error = start_remote_control_for_state(&state, generic.clone())
            .expect_err("post-stop raw Web-only start must remain blocked while armed");
        assert!(error.contains("armed"), "unexpected error: {error}");
        assert!(state.remote_control.lock().unwrap().is_none());
        let unbound = std::net::TcpListener::bind(("127.0.0.1", port))
            .expect("rejected Web-only start must leave the port unbound");
        drop(unbound);
        let armed_status = state.dj_link_machine.lock().unwrap().status();
        assert!(armed_status.auto_start_armed);
        assert!(armed_status.credential_ready);

        let mut hybrid = dj_only.clone();
        hybrid.web_remote_enabled = true;
        hybrid.pairing_pin = "123456".to_string();
        start_remote_control_for_state(&state, hybrid).expect("exact hybrid listener starts");
        let hybrid_status = state
            .remote_control
            .lock()
            .unwrap()
            .as_ref()
            .map(RemoteWsServer::status)
            .expect("hybrid listener active");
        assert!(hybrid_status.web_remote_enabled);
        assert!(hybrid_status.dj_link_enabled);
        stop_remote_control_for_state(&state).expect("stop hybrid listener");

        state
            .dj_link_machine
            .lock()
            .unwrap()
            .install_test_disarmed_listener_authority();
        start_remote_control_for_state(&state, generic)
            .expect("generic start is allowed after disarm");
        let generic_status = state
            .remote_control
            .lock()
            .unwrap()
            .as_ref()
            .map(RemoteWsServer::status)
            .expect("generic listener active");
        assert!(generic_status.web_remote_enabled);
        assert!(!generic_status.dj_link_enabled);
        stop_remote_control_for_state(&state).expect("stop generic listener");
    }

    #[test]
    fn dj_link_lifecycle_serializes_start_against_disarm_and_rotate() {
        let harness = MediaAssetA6CommandHarness::new();
        let state = Arc::clone(&harness.state);
        let reserve_port = || {
            let probe = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
            let port = probe.local_addr().unwrap().port();
            drop(probe);
            port
        };
        let config_for = |port| RemoteControlConfig {
            bind_ip: "127.0.0.1".to_string(),
            port,
            allow_lan: true,
            web_remote_enabled: false,
            dj_link_enabled: true,
            dj_link_bind_ip: Some("127.0.0.1".to_string()),
            ..RemoteControlConfig::default()
        };

        // Start owns lifecycle first; a queued disarm must run only after the
        // listener has either been created or failed. The test mutation below
        // models the already-unit-tested durable disarm result, while this
        // AppState proof exercises the production listener lock/order itself.
        let first_port = reserve_port();
        state
            .dj_link_machine
            .lock()
            .unwrap()
            .install_test_armed_listener_authority(
                "127.0.0.1",
                first_port,
                "0123456789abcdef0123456789abcdef",
            );
        let (start_entered_tx, start_entered_rx) = mpsc::channel();
        let (release_start_tx, release_start_rx) = mpsc::channel();
        let release_start_rx = Arc::new(Mutex::new(release_start_rx));
        let hook_state = Arc::clone(&state);
        let hook_release_start_rx = Arc::clone(&release_start_rx);
        let first_hook = install_remote_control_lifecycle_test_hook(Arc::new(move |entered| {
            if std::ptr::eq(entered, hook_state.as_ref()) {
                start_entered_tx
                    .send(())
                    .expect("report start lifecycle entry");
                hook_release_start_rx
                    .lock()
                    .expect("start lifecycle release mutex")
                    .recv()
                    .expect("release start lifecycle hook");
            }
        }));
        let start_state = Arc::clone(&state);
        let start = std::thread::spawn(move || {
            start_remote_control_for_state(&start_state, config_for(first_port))
        });
        start_entered_rx
            .recv_timeout(Duration::from_secs(2))
            .expect("start holds lifecycle before listener mutation");
        let (disarm_ready_tx, disarm_ready_rx) = mpsc::channel();
        let (disarm_done_tx, disarm_done_rx) = mpsc::channel();
        let disarm_state = Arc::clone(&state);
        let disarm = std::thread::spawn(move || {
            disarm_ready_tx.send(()).expect("queue disarm");
            disarm_dj_link_machine_for_state_with(&disarm_state, |machine| {
                machine.install_test_disarmed_listener_authority();
                disarm_done_tx.send(()).expect("report disarm completion");
                Ok(())
            })
        });
        disarm_ready_rx.recv().expect("disarm queued behind start");
        assert!(matches!(
            disarm_done_rx.try_recv(),
            Err(mpsc::TryRecvError::Empty)
        ));
        release_start_tx.send(()).expect("release first start");
        start
            .join()
            .expect("start worker did not panic")
            .expect("start succeeds before queued disarm");
        disarm
            .join()
            .expect("disarm worker did not panic")
            .expect("queued disarm succeeds after start");
        drop(first_hook);
        assert!(state.remote_control.lock().unwrap().is_none());
        let disarmed = state.dj_link_machine.lock().unwrap().status();
        assert!(!disarmed.auto_start_armed);
        assert!(!disarmed.credential_ready);

        // Repeat the deterministic start boundary with the real rotate body.
        // Rotation cannot run before start has published the sole listener;
        // it then rejects without altering the accepted armed credential.
        let second_port = reserve_port();
        state
            .dj_link_machine
            .lock()
            .unwrap()
            .install_test_armed_listener_authority(
                "127.0.0.1",
                second_port,
                "fedcba9876543210fedcba9876543210",
            );
        let (rotate_start_entered_tx, rotate_start_entered_rx) = mpsc::channel();
        let (rotate_release_start_tx, rotate_release_start_rx) = mpsc::channel();
        let rotate_release_start_rx = Arc::new(Mutex::new(rotate_release_start_rx));
        let hook_state = Arc::clone(&state);
        let hook_rotate_release_start_rx = Arc::clone(&rotate_release_start_rx);
        let second_hook = install_remote_control_lifecycle_test_hook(Arc::new(move |entered| {
            if std::ptr::eq(entered, hook_state.as_ref()) {
                rotate_start_entered_tx
                    .send(())
                    .expect("report rotate/start lifecycle entry");
                hook_rotate_release_start_rx
                    .lock()
                    .expect("rotate lifecycle release mutex")
                    .recv()
                    .expect("release rotate/start lifecycle hook");
            }
        }));
        let start_state = Arc::clone(&state);
        let start = std::thread::spawn(move || {
            start_remote_control_for_state(&start_state, config_for(second_port))
        });
        rotate_start_entered_rx
            .recv_timeout(Duration::from_secs(2))
            .expect("second start holds lifecycle before listener mutation");
        let (rotate_ready_tx, rotate_ready_rx) = mpsc::channel();
        let (rotate_done_tx, rotate_done_rx) = mpsc::channel();
        let rotate_state = Arc::clone(&state);
        let rotate = std::thread::spawn(move || {
            rotate_ready_tx.send(()).expect("queue rotate");
            let result = rotate_dj_link_token_for_state(&rotate_state);
            rotate_done_tx.send(()).expect("report rotate completion");
            result
        });
        rotate_ready_rx.recv().expect("rotate queued behind start");
        assert!(matches!(
            rotate_done_rx.try_recv(),
            Err(mpsc::TryRecvError::Empty)
        ));
        rotate_release_start_tx
            .send(())
            .expect("release second start");
        start
            .join()
            .expect("second start worker did not panic")
            .expect("second start succeeds before queued rotate");
        let rotate_error = rotate
            .join()
            .expect("rotate worker did not panic")
            .expect_err("rotate must reject while the just-started listener is active");
        assert!(rotate_error.contains("Stop the shared Remote listener"));
        drop(second_hook);
        let listener = state
            .remote_control
            .lock()
            .unwrap()
            .as_ref()
            .map(RemoteWsServer::status)
            .expect("single DJ listener remains active after rejected rotate");
        assert!(listener.running && listener.dj_link_enabled && !listener.web_remote_enabled);
        let armed = state.dj_link_machine.lock().unwrap().status();
        assert!(armed.auto_start_armed);
        assert!(armed.credential_ready);
        stop_remote_control_for_state(&state).expect("cleanup retained DJ listener");
    }

    #[test]
    fn dj_link_production_remote_stop_is_bounded_and_replacement_rejects_replay() {
        let harness = MediaAssetA6CommandHarness::new();
        let state = Arc::clone(&harness.state);
        let probe = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let port = probe.local_addr().unwrap().port();
        drop(probe);
        let token = "0123456789abcdef0123456789abcdef";
        state
            .dj_link_machine
            .lock()
            .unwrap()
            .install_test_armed_listener_authority("127.0.0.1", port, token);
        let mut production_timeline = state.engine.snapshot().timeline;
        production_timeline.phases = vec![TimelinePhaseSummary {
            id: protocol::TimelinePhaseId(1),
            label: "DJ Link production stop phase".to_string(),
            role: protocol::TimelinePhaseRole::Intro,
            start_ms: 0,
            end_ms: 16_000,
        }];
        production_timeline.loop_region = Some(TimelineLoopRegionSummary {
            a_ms: 0,
            b_ms: 16_000,
            enabled: false,
            musical_length_beats: None,
        });
        state
            .engine
            .apply_timeline_bank_published(
                vec![production_timeline.clone()],
                production_timeline.id,
                false,
            )
            .unwrap();
        let production_timeline_id = state.engine.snapshot().timeline.id;
        {
            let mut coordinator = state.project_coordinator.lock().unwrap();
            let mut mapping = dj_link_test_mapping(
                "production-stop-content",
                protocol::DjTrackSelector {
                    content_id: Some("production-stop-content".to_string()),
                    title: None,
                    artist: None,
                    title_contains: None,
                    fallback_deck: None,
                },
            );
            mapping.timeline_id = production_timeline_id;
            coordinator.mappings.dj_track_triggers = vec![mapping];
            state
                .dj_link_runtime
                .lock()
                .unwrap()
                .sync_project(&coordinator);
        }
        let production_active_outcome = dispatch_dj_link_event(
            dj_link_test_envelope(
                protocol::DjLinkMessageType::TrackActive,
                1,
                "production-stop-active",
                json!({
                    "deck": 1,
                    "deckId": "rekordbox-deck-1",
                    "contentId": "production-stop-content",
                    "trackBpm": 120.0,
                    "positionAtSendSec": 0.0,
                    "effectiveBpm": 120.0,
                    "positionRevision": 1,
                    "sampleAgeMs": 0,
                    "isPlaying": true,
                    "startedAt": "2026-08-26T00:00:00Z",
                    "playSessionId": "production-stop-play",
                    "loop": null
                }),
            ),
            &state.engine,
            state.project_coordinator.as_ref(),
            state.dj_link_runtime.as_ref(),
            state.project_external_command_admission.as_ref(),
            state.project_transaction_active.as_ref(),
        );
        assert!(
            matches!(
                production_active_outcome,
                DjLinkDispatchOutcome::TimelineState { .. }
            ),
            "production stop fixture ACTIVE must establish a valid v3 owner, got {production_active_outcome:?}"
        );
        let production_timeline_id = production_timeline_id.0.to_string();
        *state.current_project_path.lock().unwrap() = Some(PathBuf::from("production-stop.sdc"));
        let config = RemoteControlConfig {
            bind_ip: "127.0.0.1".to_string(),
            port,
            pairing_pin: "123456".to_string(),
            allow_lan: true,
            max_connections: 2,
            max_messages_per_second: 1_000,
            dj_link_enabled: true,
            dj_link_bind_ip: Some("127.0.0.1".to_string()),
            ..RemoteControlConfig::default()
        };
        start_remote_control_for_state(&state, config.clone()).unwrap();

        let mut old_client = DjLinkLoopbackClient::connect(port);
        old_client.send_json(&dj_link_socket_hello(
            token,
            "production-stop-old",
            "production-stop-old-hello",
        ));
        assert_eq!(
            old_client.read_ack().outcome,
            protocol::DjLinkAckOutcome::Accepted
        );
        complete_dj_link_socket_snapshot_gate(&mut old_client, "production-stop-old");

        // Generic workers are retained by the same server join. Prove the
        // status provider fails closed instead of waiting behind an app-owned
        // transport mutex, and keep that actual socket open through stop.
        let transport_status_guard = state.external_video_transport.lock().unwrap();
        let mut remote_client = DjLinkLoopbackClient::connect_path(port, "/ws?token=123456");
        let status_started = Instant::now();
        remote_client.send_json(&json!({"type":"getExternalVideoTransportStatus"}));
        let status_response = remote_client.read_json();
        assert!(
            status_started.elapsed() < Duration::from_secs(1),
            "busy external transport status provider did not fail closed"
        );
        assert_eq!(status_response["type"], "externalVideoTransportStatus");
        assert!(status_response["external_video_transport_status"]["error"]
            .as_str()
            .is_some_and(|error| error.contains("busy") && error.contains("retry")));

        // Enqueue the real production project-load command before the fence,
        // then wait for its exact worker admission and pending-publication
        // barrier. The nondefault engine test-support seam pauses the worker
        // only after LoadProjectSnapshotPublished has validated B and queued
        // its real ACK; it does not replace the shared publication lock.
        let fence_engine = state.engine.clone();
        let audio = fence_engine.video_audio_runtime_snapshot().timeline_audio;
        let load_snapshot = fence_engine.snapshot();
        let submission = fence_engine
            .submit_project_snapshot_load_for_test(load_snapshot)
            .expect("enqueue production project snapshot load");
        assert!(
            submission.wait_until_admitted(Duration::from_secs(1)),
            "production project snapshot load did not enter Admitted"
        );
        assert!(
            submission.wait_until_pending_publication(Duration::from_secs(1)),
            "production project snapshot load did not reach its pending publication barrier"
        );

        let (fence_entered_tx, fence_entered_rx) = mpsc::sync_channel(1);
        let (release_fence_tx, release_fence_rx) = mpsc::sync_channel(1);
        let fence_thread = std::thread::spawn(move || {
            fence_engine.with_timeline_audio_projection_fence(
                audio.source_projection_authority,
                audio.publication_generation,
                || {
                    fence_entered_tx.send(()).unwrap();
                    release_fence_rx.recv().unwrap();
                },
            )
        });
        fence_entered_rx
            .recv_timeout(Duration::from_secs(1))
            .expect("snapshot/audio fence did not enter");
        submission.release_publication_barrier();

        old_client.send_json(&dj_link_socket_release(
            "production-stop-old",
            &production_timeline_id,
        ));
        let inflight_deadline = Instant::now() + Duration::from_secs(1);
        loop {
            let inflight = state
                .remote_control
                .lock()
                .unwrap()
                .as_ref()
                .map(RemoteWsServer::dj_link_inflight_dispatch_count)
                .unwrap_or_default();
            if inflight == 1 {
                break;
            }
            assert!(
                Instant::now() < inflight_deadline,
                "actual DJ Link RELEASE never entered the production handler"
            );
            std::thread::sleep(Duration::from_millis(2));
        }

        let stop_started = Instant::now();
        let stop_result = stop_remote_control_for_state(&state);
        let stop_elapsed = stop_started.elapsed();

        // Always release the real snapshot fence and wait for the definitive
        // project ACK before making assertions, so a failed lifecycle
        // expectation cannot strand either the publication or retained worker.
        release_fence_tx.send(()).unwrap();
        let fence_result = fence_thread.join().expect("audio fence thread panicked");
        let submission_result = submission.wait_result();
        stop_result.unwrap();
        fence_result.unwrap();
        submission_result.unwrap();
        assert!(
            stop_elapsed < DJ_LINK_SHUTDOWN_DEADLINE,
            "production remote stop took {stop_elapsed:?}"
        );
        assert!(
            stop_elapsed >= Duration::from_secs(2),
            "stop did not actually join the in-flight three-second Engine receipt: {stop_elapsed:?}"
        );
        assert!(state.remote_control.lock().unwrap().is_none());
        drop(transport_status_guard);
        drop(remote_client);

        state
            .engine
            .send(EngineCommand::SetTimelinePlaying(false))
            .unwrap();
        std::thread::sleep(Duration::from_millis(25));
        let after_cancel = state.engine.snapshot();
        let after_cancel_audio = state.engine.video_audio_runtime_snapshot().timeline_audio;
        std::thread::sleep(Duration::from_millis(100));
        let after_late_window = state.engine.snapshot();
        let after_late_audio = state.engine.video_audio_runtime_snapshot().timeline_audio;
        assert_eq!(after_late_window.timeline, after_cancel.timeline);
        assert_eq!(after_late_window.timeline_bank, after_cancel.timeline_bank);
        assert_eq!(after_late_audio.playing, after_cancel_audio.playing);
        assert_eq!(after_late_audio.position_ms, after_cancel_audio.position_ms);
        assert_eq!(after_late_audio.muted, after_cancel_audio.muted);
        assert_eq!(
            after_late_audio.transport_revision,
            after_cancel_audio.transport_revision
        );
        assert_eq!(
            after_late_audio.source_projection_authority,
            after_cancel_audio.source_projection_authority
        );
        assert_eq!(
            after_late_audio.publication_generation,
            after_cancel_audio.publication_generation
        );
        assert!(after_late_audio.clips.is_empty());
        assert!(after_late_audio.child_clips.is_empty());

        // The explicit post-stop restart cannot bind until the old listener
        // and all retained socket workers have joined. It shares the same
        // process fence, so replaying the retired physical identity never
        // invokes the Engine handler or publishes a late B.
        start_remote_control_for_state(&state, config).unwrap();
        let mut replacement = DjLinkLoopbackClient::connect(port);
        replacement.send_json(&dj_link_socket_hello(
            token,
            "production-stop-replacement",
            "production-stop-replacement-hello",
        ));
        assert_eq!(
            replacement.read_ack().outcome,
            protocol::DjLinkAckOutcome::Accepted
        );
        complete_dj_link_socket_snapshot_gate(&mut replacement, "production-stop-replacement");
        replacement.send_json(&dj_link_socket_release(
            "production-stop-replacement",
            &production_timeline_id,
        ));
        let replay = replacement.read_ack();
        assert_eq!(replay.outcome, protocol::DjLinkAckOutcome::Rejected);
        assert_eq!(replay.code.as_deref(), Some("event_id_not_retained"));
        stop_remote_control_for_state(&state).unwrap();
        assert_eq!(state.engine.snapshot().timeline, after_late_window.timeline);
    }

    #[test]
    fn dj_link_selector_content_id_is_authoritative_when_present() {
        let mappings = vec![
            dj_link_test_mapping(
                "content",
                protocol::DjTrackSelector {
                    content_id: Some("content-1".to_string()),
                    title: None,
                    artist: None,
                    title_contains: None,
                    fallback_deck: None,
                },
            ),
            dj_link_test_mapping(
                "title-artist",
                protocol::DjTrackSelector {
                    content_id: None,
                    title: Some("Caf\u{e9}".to_string()),
                    artist: Some("Artist".to_string()),
                    title_contains: None,
                    fallback_deck: None,
                },
            ),
        ];
        let content_payload = protocol::DjLinkTrackPayload {
            deck: 1,
            deck_id: "rekordbox-deck-1".to_string(),
            content_id: Some("content-1".to_string()),
            title: None,
            artist: None,
            track_bpm: None,
            position_at_send_sec: 0.0,
            effective_bpm: 120.0,
            position_revision: 1,
            sample_age_ms: 0,
            is_playing: true,
            started_at: "2026-08-25T00:00:00Z".to_string(),
            play_session_id: "play-1".to_string(),
            loop_state: None,
        };
        assert_eq!(
            match dj_track_selector::resolve_track_mapping(&mappings, &content_payload) {
                dj_track_selector::DjTrackMappingResolution::Unique(mapping) => mapping.id,
                resolution => panic!("expected exact content mapping, got {resolution:?}"),
            },
            "content"
        );
        let title_payload = protocol::DjLinkTrackPayload {
            content_id: None,
            title: Some("Cafe\u{301}".to_string()),
            artist: Some("Artist".to_string()),
            ..content_payload.clone()
        };
        assert_eq!(
            match dj_track_selector::resolve_track_mapping(&mappings, &title_payload) {
                dj_track_selector::DjTrackMappingResolution::Unique(mapping) => mapping.id,
                resolution => panic!("expected exact title mapping, got {resolution:?}"),
            },
            "title-artist"
        );
        let unmatched_content = protocol::DjLinkTrackPayload {
            content_id: Some("unknown".to_string()),
            title: None,
            artist: None,
            ..content_payload.clone()
        };
        assert_eq!(
            dj_track_selector::resolve_track_mapping(&mappings, &unmatched_content),
            dj_track_selector::DjTrackMappingResolution::NoMapping
        );
        assert!(validate_dj_track_triggers(vec![dj_link_test_mapping(
            "title-only",
            protocol::DjTrackSelector {
                content_id: None,
                title: Some("Track".to_string()),
                artist: None,
                title_contains: None,
                fallback_deck: None,
            },
        )])
        .is_err());
    }

